
'use strict';
/**
 * MiniPy v4.1x builder -- incremental feature patches applied to MiniPy_v4.sb3.
 * Source of truth for the v4.1x line; the .sb3 is a product of this script.
 *   node _work/v41/build41.js            -> MiniPy_v4.16.sb3 (newest)
 *   V41_OUT=... V41_SRC=... V41_STAMP=... node ...     -> override
 *   V41_SKIP="P14 def/return,..." node ...             -> rebuild an earlier version
 *     (patch names are the first argument of each patch() call; P1..P14 == v4.10,
 *      everything == v4.11)
 */
const fs = require('fs');
const path = require('path');
const { zipRead, zipWrite, makeBuilder } = require('../sb3lib.js');

const ROOT = 'D:/编程/scratch/ai/minipython';
const SRC = process.env.V41_SRC || (ROOT + '/MiniPy_v4.sb3');
const OUT = process.env.V41_OUT || (ROOT + '/MiniPy_v4.128.sb3');
const OUT_JSON = process.env.V41_JSON || (ROOT + '/_work/v41/project.json');
const STAMP = process.env.V41_STAMP || 'MiniPy v4.128 - built 2026-09-18';
const SKIP = new Set((process.env.V41_SKIP || '').split(',').map((s) => s.trim()).filter(Boolean));

const entries = zipRead(SRC);
const project = JSON.parse(entries.find((e) => e.name === 'project.json').data.toString('utf8'));
const B = makeBuilder(project);
B.setCtx('Interpreter');
const IT = 'Interpreter';

// ---------------------------------------------------------------- helpers
const T = (n) => project.targets.find((t) => t.name === n);
const BL = () => T(IT).blocks;
const I = (op, opts) => B.B(IT, op, opts);
const num = (v) => B.num(v);
const txt = (v) => B.txt(v);
const VAR = (n) => B.VAR(n);
const item = (list, idx) => I('data_itemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']) } });
const llen = (list) => I('data_lengthoflist', { fields: B.LISTF(list) });
const addTo = (list, v) => I('data_addtolist', { fields: B.LISTF(list), inputs: { ITEM: B.REP(v, [4, '0']) } });
const clearL = (list) => I('data_deletealloflist', { fields: B.LISTF(list) });
const lenOf = (x) => I('operator_length', { inputs: { STRING: B.REP(x, [10, '']) } });
const letterOf = (i, s) => I('operator_letter_of', { inputs: { LETTER: B.REP(i, [4, '0']), STRING: B.REP(s, [10, '']) } });
const JOIN = (a, b) => I('operator_join', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
const ADD = (a, b) => I('operator_add', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
const SUB = (a, b) => I('operator_subtract', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
const MUL = (a, b) => I('operator_multiply', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
const MOD = (a, b) => I('operator_mod', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
const DIV = (a, b) => I('operator_divide', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
const FLOOR = (x) => I('operator_mathop', { fields: { OPERATOR: ['floor', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
const EQ = (a, b) => I('operator_equals', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
const LT = (a, b) => I('operator_lt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
const GT = (a, b) => I('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
const AND = (a, b) => I('operator_and', { inputs: { OPERAND1: B.BOOL(a), OPERAND2: B.BOOL(b) } });
const OR = (a, b) => I('operator_or', { inputs: { OPERAND1: B.BOOL(a), OPERAND2: B.BOOL(b) } });
const NOT = (a) => I('operator_not', { inputs: { OPERAND: B.BOOL(a) } });
const setV = (n, v) => I('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
const chgV = (n, v) => I('data_changevariableby', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
const IF = (c, ids) => { const id = I('control_if', { inputs: { CONDITION: B.BOOL(c) } }); B.sub(IT, id, 'SUBSTACK', B.chain(IT, ids)); return id; };
const IFELSE = (c, a, b) => { const id = I('control_if_else', { inputs: { CONDITION: B.BOOL(c) } }); B.sub(IT, id, 'SUBSTACK', B.chain(IT, a)); B.sub(IT, id, 'SUBSTACK2', B.chain(IT, b)); return id; };
const REPEAT = (n, ids) => { const id = I('control_repeat', { inputs: { TIMES: B.REP(n, [4, '0']) } }); B.sub(IT, id, 'SUBSTACK', B.chain(IT, ids)); return id; };
const REPEATU = (c, ids) => { const id = I('control_repeat_until', { inputs: { CONDITION: B.BOOL(c) } }); B.sub(IT, id, 'SUBSTACK', B.chain(IT, ids)); return id; };
const newVar = (n, v) => B.addVar(IT, n, v === undefined ? 0 : v);
const argOf = (n) => B.argReporter(IT, n);

function chain(ids) { return B.chain(IT, ids); }
function blockOf(id) { return BL()[id]; }
function allIds() { return Object.keys(BL()); }

function defIdOf(proccode) {
  for (const id of allIds()) {
    const b = BL()[id];
    if (b.opcode === 'procedures_definition' && b.inputs && b.inputs.custom_block) {
      const proto = BL()[b.inputs.custom_block[1]];
      if (proto && proto.mutation && proto.mutation.proccode === proccode) return id;
    }
  }
  throw new Error('definition not found: ' + proccode);
}
function reach(roots) {
  const seen = new Set();
  const stack = (Array.isArray(roots) ? roots : [roots]).slice();
  while (stack.length) {
    const id = stack.pop();
    if (!id || seen.has(id)) continue;
    const b = BL()[id];
    if (!b) continue;
    seen.add(id);
    for (const v of Object.values(b.inputs || {})) { if (v && typeof v[1] === 'string') stack.push(v[1]); }
    if (b.next) stack.push(b.next);
  }
  return seen;
}
function inDef(proccode) { return reach(defIdOf(proccode)); }
function find(set, pred) { const out = []; for (const id of set) if (pred(BL()[id], id)) out.push(id); return out; }
function refOf(id) {
  for (const pid of allIds()) {
    const p = BL()[pid];
    for (const [slot, v] of Object.entries(p.inputs || {})) {
      if (v && v[1] === id) return { pid, slot, v };
    }
  }
  return null;
}
function cloneExpr(id) {
  if (typeof id !== 'string') return id;
  const src = BL()[id];
  if (!src) return id;
  const copy = JSON.parse(JSON.stringify(src));
  copy.next = null; copy.parent = null; copy.inputs = {};
  const newId = B.nid('cl');
  for (const [k, v] of Object.entries(src.inputs || {})) {
    const nv = JSON.parse(JSON.stringify(v));
    if (typeof nv[1] === 'string') nv[1] = cloneExpr(nv[1]);
    copy.inputs[k] = nv;
  }
  BL()[newId] = copy;
  return newId;
}
// replace the expression block oldId (which sits in some input slot) with a fresh builder result
function replaceExpr(oldId, build) {
  const ref = refOf(oldId);
  if (!ref) throw new Error('cannot locate parent of ' + oldId);
  const fresh = build();
  const desc = ref.v.length > 2 ? [ref.v[0], fresh, ref.v[2]] : [ref.v[0], fresh];
  BL()[ref.pid].inputs[ref.slot] = desc;
  if (typeof fresh === 'string') BL()[fresh].parent = ref.pid;
  return fresh;
}
function spliceAfter(afterId, firstId) {
  const a = BL()[afterId];
  const nx = a.next;
  a.next = firstId;
  BL()[firstId].parent = afterId;
  let t = firstId;
  while (BL()[t].next) t = BL()[t].next;
  BL()[t].next = nx;
  if (nx) BL()[nx].parent = t;
  return firstId;
}
function detachTail(predId) {
  const p = BL()[predId];
  const nx = p.next;
  p.next = null;
  if (nx) BL()[nx].parent = null;
  return nx;
}
function callProc(proccode, args, fallbackWarp) {
  const defId = defIdOf(proccode);
  const t = T(IT);
  const proto = t.blocks[t.blocks[defId].inputs.custom_block[1]];
  const argIds = JSON.parse(proto.mutation.argumentids);
  const inputs = {};
  for (let i = 0; i < argIds.length; i++) inputs[argIds[i]] = B.REP(args[i], [4, '0']);
  return I('procedures_call', {
    inputs,
    mutation: { tagName: 'mutation', children: [], proccode, argumentids: proto.mutation.argumentids, warp: fallbackWarp || proto.mutation.warp || 'true' }
  });
}
const FAIL = (msg) => callProc('fail %s', [typeof msg === 'string' ? txt(msg) : msg]);
const FAILB = (expr) => callProc('fail %s', [expr]);   // message built by a block
function newProc(proccode, argNames) {
  const d = B.makeProcedure(IT, proccode, argNames, true);
  return d;
}
function attachBody(defId, ids) {
  const first = chain(ids);
  BL()[defId].next = first;
  if (first) BL()[first].parent = defId;
  return first;
}
function pruneUnreachable() {
  const keep = new Set();
  const stack = allIds().filter((id) => BL()[id].topLevel);
  while (stack.length) {
    const id = stack.pop();
    if (!id || keep.has(id)) continue;
    const b = BL()[id];
    if (!b) continue;
    keep.add(id);
    for (const v of Object.values(b.inputs || {})) { if (v && typeof v[1] === 'string') stack.push(v[1]); }
    if (b.next) stack.push(b.next);
  }
  let dropped = 0;
  for (const id of allIds()) if (!keep.has(id)) { delete BL()[id]; dropped++; }
  return dropped;
}
function relinkParents() {
  const blocks = BL();
  for (const id of Object.keys(blocks)) blocks[id].parent = null;
  for (const id of Object.keys(blocks)) {
    const b = blocks[id];
    if (b.next && blocks[b.next]) blocks[b.next].parent = id;
    for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string' && blocks[v[1]]) blocks[v[1]].parent = id;
  }
}

function ancestor(id, pred) {
  let cur = id, guard = 0;
  while (cur && guard++ < 200) {
    const p = BL()[cur].parent;
    if (!p) return null;
    cur = p;
    if (pred(BL()[cur])) return cur;
  }
  return null;
}
function predecessorOf(id) { for (const pid of allIds()) if (BL()[pid].next === id) return pid; return null; }
function setStack(parentId, slot, ids) {
  const first = ids && ids.length ? chain(ids.slice()) : null;
  BL()[parentId].inputs[slot] = [2, first];
  if (first) BL()[first].parent = parentId;
  return first;
}
function prependStack(parentId, slot, blockId) {
  const cur = BL()[parentId].inputs[slot] ? BL()[parentId].inputs[slot][1] : null;
  let tail = blockId;
  while (BL()[tail].next) tail = BL()[tail].next;
  if (typeof cur === 'string') { BL()[tail].next = cur; BL()[cur].parent = tail; }
  BL()[parentId].inputs[slot] = [2, blockId];
  BL()[blockId].parent = parentId;
  return blockId;
}
function replaceStmt(oldId, newId) {
  const pred = predecessorOf(oldId);
  const nx = BL()[oldId].next;
  if (pred) { BL()[pred].next = newId; BL()[newId].parent = pred; }
  else {
    const ref = refOf(oldId);
    if (!ref) throw new Error('cannot place statement ' + oldId);
    BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], newId, ref.v[2]] : [ref.v[0], newId];
    BL()[newId].parent = ref.pid;
  }
  BL()[newId].next = nx; if (nx) BL()[nx].parent = newId;
  return newId;
}
function insertBeforeStmt(targetId, ids) {
  const first = chain(ids.slice());
  const pred = predecessorOf(targetId);
  if (pred) spliceAfter(pred, first);
  else {
    const ref = refOf(targetId);
    if (!ref) throw new Error('cannot insert before ' + targetId);
    BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], first, ref.v[2]] : [ref.v[0], first];
    BL()[first].parent = ref.pid;
    let tail = first;
    while (BL()[tail].next) tail = BL()[tail].next;
    BL()[tail].next = targetId;
    BL()[targetId].parent = tail;
  }
  return first;
}

// ---------------------------------------------------------------- patches
const PATCHES = [];
function patch(name, fn) { PATCHES.push({ name, fn }); }
function patchEnabled(name) { return !SKIP.has(name) && ![...SKIP].some((s) => name.startsWith(s.split(' ')[0]) && s.split(' ')[0] === name.split(' ')[0]); }

// ---- P1: the escape character variable held two chars, so "\"" never escaped
patch('P1 slash', () => {
  const st = T('Stage');
  let hits = 0;
  for (const v of Object.values(st.variables || {})) if (v[0] === 'slash') { v[1] = '\\'; hits++; }
  for (const v of Object.values(T(IT).variables || {})) if (v[0] === 'slash') { v[1] = '\\'; hits++; }
  if (!hits) throw new Error('slash variable not found');
  console.log('[P1] slash -> single backslash (' + hits + ' decls)');
});

// ---- P2: int()/float() accept surrounding whitespace (Python semantics)
patch('P2 int trim', () => {
  newVar('ta', 0); newVar('tb', 0);
  const d = newProc('trimsp %s', ['v']);
  attachBody(d.defId, [
    setV('ta', num(1)),
    REPEATU(OR(GT(VAR('ta'), lenOf(argOf('v'))), NOT(EQ(letterOf(VAR('ta'), argOf('v')), txt(' ')))), [chgV('ta', num(1))]),
    setV('tb', lenOf(argOf('v'))),
    REPEATU(OR(LT(VAR('tb'), VAR('ta')), NOT(EQ(letterOf(VAR('tb'), argOf('v')), txt(' ')))), [chgV('tb', num(-1))]),
    IFELSE(LT(VAR('tb'), VAR('ta')),
      [setV('ev', txt('')), setV('evtype', txt('S'))],
      [callProc('substr %s %s %s', [argOf('v'), VAR('ta'), VAR('tb')])])
  ]);
  const set = inDef('callfn %s %s %s');
  // the OUTER "fn == int or fn == float" test is the one whose comparison feeds an OR
  const eqInt = find(set, (b) => b.opcode === 'operator_equals' && b.inputs.OPERAND2 && b.inputs.OPERAND2[1] && b.inputs.OPERAND2[1][1] === 'int'
    && b.parent && BL()[b.parent] && BL()[b.parent].opcode === 'operator_or');
  if (!eqInt.length) throw new Error('callfn int/float test not found');
  const target = ancestor(eqInt[0], (b) => b.opcode === 'control_if');
  if (!target) throw new Error('callfn int control_if not found');
  const call = callProc('trimsp %s', [VAR('ev')]);
  prependStack(target, 'SUBSTACK', call);
  console.log('[P2] int()/float() trim');
});

// ---- P3: round() uses banker's rounding (half to even)
patch('P3 round half even', () => {
  newVar('lf', 0); newVar('fr', 0); newVar('mrt', 0);
  const d = newProc('roundpy %s', ['v']);
  attachBody(d.defId, [
    setV('lf', FLOOR(argOf('v'))),
    setV('fr', SUB(argOf('v'), FLOOR(argOf('v')))),
    IFELSE(EQ(VAR('fr'), num('0.5')),
      [IFELSE(EQ(MOD(VAR('lf'), num(2)), num(1)), [setV('ev', ADD(VAR('lf'), num(1)))], [setV('ev', VAR('lf'))])],
      [setV('ev', I('operator_round', { inputs: { NUM: B.REP(argOf('v'), [4, '0']) } }))]),
    setV('evtype', txt('N'))
  ]);
  // callfn: ev = round(ev)
  const cf = inDef('callfn %s %s %s');
  const setRounds = find(cf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ev' && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]].opcode === 'operator_round');
  if (setRounds.length !== 1) throw new Error('callfn round stmt not found (' + setRounds.length + ')');
  replaceStmt(setRounds[0], callProc('roundpy %s', [VAR('ev')]));
  // builtin2b: round(x, n)
  const b2 = inDef('builtin2b %s %s %s %s %s');
  const ife = find(b2, (b) => b.opcode === 'control_if_else' && reach(b.inputs.SUBSTACK[1]).size && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'operator_round'));
  if (ife.length !== 1) throw new Error('builtin2b round if not found (' + ife.length + ')');
  const a1 = () => argOf('a1v');
  const qp = () => VAR('qpow');
  setStack(ife[0], 'SUBSTACK', [setV('mrt', DIV(a1(), qp())), callProc('roundpy %s', [VAR('mrt')]), setV('ev', MUL(VAR('ev'), qp()))]);
  const ife2 = find(reach(ife[0]), (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string' && [...reach(b.inputs.SUBSTACK2[1])].some((id) => BL()[id].opcode === 'operator_round'));
  if (ife2.length !== 1) throw new Error('builtin2b else round not found');
  setStack(ife2[0], 'SUBSTACK2', [setV('mrt', MUL(a1(), qp())), callProc('roundpy %s', [VAR('mrt')]), setV('ev', DIV(VAR('ev'), qp()))]);
  console.log('[P3] round = half-to-even');
});

// ---- P11: **= and //= augmented assignment
patch('P11 pow/floor assign', () => {
  const ex = inDef('execute');
  const eqPlus = find(ex, (b) => b.opcode === 'operator_equals' && b.inputs.OPERAND2 && b.inputs.OPERAND2[1] && b.inputs.OPERAND2[1][1] === '+=');
  if (!eqPlus.length) throw new Error('+= branch not found');
  const augIf = ancestor(eqPlus[0], (b) => b.opcode === 'control_if');
  if (!augIf) throw new Error('aug assign if not found');
  const tok2 = () => item('Tok', num(2));
  const cond = AND(EQ(item('Kind', num(1)), txt('I')), AND(OR(EQ(tok2(), txt('//')), EQ(tok2(), txt('**'))), EQ(item('Tok', num(3)), txt('='))));
  const body = [
    setV('name', item('Tok', num(1))),
    callProc('lookup %s', [VAR('name')]),
    IFELSE(EQ(VAR('found'), num(0)),
      [FAIL(JOIN(txt('NameError: '), VAR('name')))],
      [callProc('rightside %s %s %s %s %s', [item('Values', VAR('found')), item('Types', VAR('found')), item('Tok', num(2)), txt('4'), VAR('count')]),
       IF(EQ(VAR('error'), txt('')), [callProc('assign %s %s %s', [VAR('name'), VAR('ev'), VAR('evtype')])])]),
    setV('pending', num(1))
  ];
  insertBeforeStmt(augIf, [IF(cond, body)]);
  console.log('[P11] **= //= installed');
});

// ---- P12: is / is not
patch('P12 is operator', () => {
  // rank: is / isnot sit with the comparison operators
  const rk = defIdOf('rank %s');
  const tail = (() => { let id = BL()[rk].next; while (BL()[id].next) id = BL()[id].next; return id; })();
  spliceAfter(tail, chain([
    IF(EQ(argOf('op'), txt('is')), [setV('erank', num(3))]),
    IF(EQ(argOf('op'), txt('isnot')), [setV('erank', num(3))])
  ]));
  // eval: turn "is not" into one operator token
  const ev = inDef('eval %s %s');
  const ifNotIn = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string' && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'data_setvariableto' && BL()[id].fields.VARIABLE[0] === 'eop' && BL()[id].inputs.VALUE[1] && BL()[id].inputs.VALUE[1][1] === 'notin'));
  if (ifNotIn.length !== 1) throw new Error('eval notin dispatch not found (' + ifNotIn.length + ')');
  spliceAfter(ifNotIn[0], chain([
    IF(AND(EQ(VAR('eop'), txt('is')), EQ(item('Tok', ADD(VAR('ek'), num(1))), txt('not'))), [setV('eop', txt('isnot'))]),
    IF(AND(EQ(VAR('eop'), txt('not')), EQ(item('Tok', SUB(VAR('ek'), num(1))), txt('is'))), [setV('eop', txt('skip'))])
  ]));
  // pair: isnot consumes two tokens
  const pr = inDef('pair %s %s %s %s');
  const pairIf = find(pr, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string' && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'rightside %s %s %s %s %s' && JSON.stringify(BL()[id].inputs).includes('notin')));
  if (pairIf.length !== 1) throw new Error('pair notin branch not found (' + pairIf.length + ')');
  const oldElse = BL()[pairIf[0]].inputs.SUBSTACK2 ? BL()[pairIf[0]].inputs.SUBSTACK2[1] : null;
  const newElse = IFELSE(EQ(argOf('op'), txt('isnot')),
    [callProc('rightside %s %s %s %s %s', [VAR('ev'), VAR('evtype'), txt('isnot'), ADD(argOf('cut'), num(2)), argOf('hi')])],
    oldElse ? [oldElse] : []);
  setStack(pairIf[0], 'SUBSTACK2', [newElse]);
  // rightside: identity comparison
  const rs = inDef('rightside %s %s %s %s %s');
  const errIf = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals' && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === '');
  if (errIf.length !== 1) throw new Error('rightside body if not found (' + errIf.length + ')');
  newVar('isv', 0);
  const idChain = [
    IF(OR(EQ(argOf('op'), txt('is')), EQ(argOf('op'), txt('isnot'))), [
      setV('isv', num(0)),
      IF(AND(EQ(argOf('leftval'), VAR('ev')), EQ(argOf('lefttype'), VAR('evtype'))), [setV('isv', num(1))]),
      setV('ev', VAR('isv')),
      IF(EQ(argOf('op'), txt('isnot')), [setV('ev', SUB(num(1), VAR('ev')))]),
      setV('evtype', txt('B'))
    ])
  ];
  prependStack(errIf[0], 'SUBSTACK', chain(idChain));
  console.log('[P12] is / is not installed');
});

// ---- P4: conditional expression  a if c else b
patch('P4 ternary', () => {
  newVar('tif', 0); newVar('tel', 0); newVar('td', 0); newVar('tk', 0); newVar('tifs', 0); newVar('tels', 0);
  const evalDef = defIdOf('eval %s %s');
  const guard = BL()[BL()[evalDef].next].next;
  if (!guard || BL()[guard].opcode !== 'control_if') throw new Error('eval guard not found');
  const rest = detachTail(guard);
  const tokAt = (x) => item('Tok', x);
  const scan = [
    IF(NOT(EQ(item('Kind', VAR('tk')), txt('S'))), [
      setV('eop', tokAt(VAR('tk'))),
      IF(OR(EQ(VAR('eop'), txt('(')), EQ(VAR('eop'), txt('['))), [chgV('td', num(1))]),
      IF(OR(EQ(VAR('eop'), txt(')')), EQ(VAR('eop'), txt(']'))), [chgV('td', num(-1))]),
      IF(AND(EQ(VAR('td'), num(0)), AND(EQ(VAR('eop'), txt('if')), EQ(VAR('tif'), num(0)))), [setV('tif', VAR('tk'))]),
      IF(AND(EQ(VAR('td'), num(0)), AND(EQ(VAR('eop'), txt('else')), AND(GT(VAR('tif'), num(0)), EQ(VAR('tel'), num(0))))), [setV('tel', VAR('tk'))])
    ]),
    chgV('tk', num(1))
  ];
  // the nested eval() calls reset tif/tel, so save the branch bounds first
  const tri = [
    setV('tifs', VAR('tif')),
    setV('tels', VAR('tel')),
    callProc('eval %s %s', [ADD(VAR('tifs'), num(1)), SUB(VAR('tels'), num(1))]),
    callProc('truth %s %s', [VAR('ev'), VAR('evtype')]),
    IFELSE(EQ(VAR('truthv'), num(1)),
      [callProc('eval %s %s', [argOf('lo'), SUB(VAR('tifs'), num(1))])],
      [callProc('eval %s %s', [ADD(VAR('tels'), num(1)), argOf('hi')])]),
    chgV('fnlimit', num(-1))
  ];
  const stmts = [setV('tif', num(0)), setV('tel', num(0)), setV('td', num(0)), setV('tk', argOf('lo')),
    REPEAT(ADD(SUB(argOf('hi'), argOf('lo')), num(1)), scan),
    IFELSE(AND(GT(VAR('tif'), num(0)), GT(VAR('tel'), num(0))), tri, rest ? [rest] : [])];
  const first = chain(stmts);
  BL()[guard].next = first; BL()[first].parent = guard;
  console.log('[P4] ternary installed');
});

// ---- P6: max()/min() with any number of arguments
patch('P6 max/min n-ary', () => {
  newVar('mbest', 0); newVar('mtype', 0); newVar('mpi', 0); newVar('mx', 0);
  B.addList(IT, 'MComma', []);   // private: must not clobber printargs' Comma
  const d = newProc('minmax %s %s %s', ['fn', 'lo', 'hi']);
  const inner = [
    callProc('eval %s %s', [ADD(item('MComma', VAR('mpi')), num(1)), SUB(item('MComma', ADD(VAR('mpi'), num(1))), num(1))]),
    IF(AND(EQ(VAR('mtype'), txt('N')), EQ(VAR('evtype'), txt('N'))), [
      IFELSE(EQ(argOf('fn'), txt('max')),
        [IF(GT(VAR('ev'), VAR('mbest')), [setV('mbest', VAR('ev'))])],
        [IF(LT(VAR('ev'), VAR('mbest')), [setV('mbest', VAR('ev'))])])
    ], [
      IF(AND(EQ(VAR('mtype'), txt('S')), EQ(VAR('evtype'), txt('S'))), [
        callProc('compareText %s %s', [VAR('ev'), VAR('mbest')]),
        IFELSE(EQ(argOf('fn'), txt('max')),
          [IF(GT(VAR('cmp'), num(0)), [setV('mbest', VAR('ev'))])],
          [IF(LT(VAR('cmp'), num(0)), [setV('mbest', VAR('ev'))])])
      ], [FAIL(txt('TypeError: max/min requires matching types'))])
    ]),
    chgV('mpi', num(1))
  ];
  attachBody(d.defId, [
    clearL('MComma'),
    setV('ed', num(0)), setV('ek', argOf('lo')),
    REPEATU(GT(VAR('ek'), argOf('hi')), [
      setV('eop', item('Tok', VAR('ek'))),
      IF(OR(EQ(VAR('eop'), txt('(')), EQ(VAR('eop'), txt('['))), [chgV('ed', num(1))]),
      IF(OR(EQ(VAR('eop'), txt(')')), EQ(VAR('eop'), txt(']'))), [chgV('ed', num(-1))]),
      IF(AND(EQ(VAR('ed'), num(0)), EQ(VAR('eop'), txt(','))), [addTo('MComma', VAR('ek'))]),
      chgV('ek', num(1))
    ]),
    addTo('MComma', ADD(argOf('hi'), num(1))),
    callProc('eval %s %s', [argOf('lo'), SUB(item('MComma', num(1)), num(1))]),
    IF(NOT(EQ(VAR('error'), txt(''))), [I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } })]),
    setV('mbest', VAR('ev')), setV('mtype', VAR('evtype')),
    setV('mpi', num(1)),
    REPEATU(NOT(LT(VAR('mpi'), SUB(llen('MComma'), num(1)))), inner),
    setV('ev', VAR('mbest')), setV('evtype', VAR('mtype'))
  ]);
  const ev = inDef('eval %s %s');
  const multiIf = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string' && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'builtin2 %s %s %s %s'));
  if (!multiIf.length) throw new Error('eval multi-arg dispatch not found');
  // reach() descends into nested substacks, so keep the innermost match
  multiIf.sort((a, b) => reach(BL()[a].inputs.SUBSTACK[1]).size - reach(BL()[b].inputs.SUBSTACK[1]).size);
  multiIf.length = 1;
  const oldElse = BL()[multiIf[0]].inputs.SUBSTACK2 ? BL()[multiIf[0]].inputs.SUBSTACK2[1] : null;
  const fnTok = () => item('Tok', argOf('lo'));
  const mm = IFELSE(OR(EQ(fnTok(), txt('max')), EQ(fnTok(), txt('min'))),
    [callProc('minmax %s %s %s', [fnTok(), ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))])],
    oldElse ? [oldElse] : []);
  setStack(multiIf[0], 'SUBSTACK2', [mm]);
  console.log('[P6] n-ary max/min installed');
});

// ---- P5: in / not in over lists
patch('P5 in-list', () => {
  newVar('inel', ''); newVar('ini', 0); newVar('inf', 0); newVar('lii', 0);
  const rs = inDef('rightside %s %s %s %s %s');
  const failIn = find(rs, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s' && JSON.stringify(b.inputs).includes('in requires strings'));
  if (failIn.length !== 1) throw new Error('in-requires-strings fail not found (' + failIn.length + ')');
  const ife = ancestor(failIn[0], (b) => b.opcode === 'control_if_else');
  if (!ife) throw new Error('in branch if_else not found');
  const search = [
    setV('inel', VAR('ev')),
    callProc('listlen %s', [VAR('inel')]),
    setV('ini', VAR('ev')),
    setV('inf', num(0)),
    setV('lii', num(1)),
    REPEATU(OR(GT(VAR('lii'), VAR('ini')), EQ(VAR('inf'), num(1))), [
      callProc('listitem %s %s', [VAR('inel'), VAR('lii')]),
      IF(EQ(VAR('evtype'), argOf('lefttype')), [
        IFELSE(EQ(argOf('lefttype'), txt('S')),
          [callProc('compareText %s %s', [argOf('leftval'), VAR('ev')]), IF(EQ(VAR('cmp'), num(0)), [setV('inf', num(1))])],
          [IF(EQ(argOf('leftval'), VAR('ev')), [setV('inf', num(1))])])
      ]),
      chgV('lii', num(1))
    ]),
    setV('ev', VAR('inf')),
    setV('evtype', txt('B')),
    IF(EQ(argOf('op'), txt('notin')), [setV('ev', SUB(num(1), VAR('ev')))])
  ];
  setStack(ife, 'SUBSTACK2', [IFELSE(EQ(VAR('evtype'), txt('L')), search, failIn)]);
  console.log('[P5] in/not in for lists');
});

// ---- P10: real bool / None values, str() and repr() semantics
patch('P10 bool/None', () => {
  newVar('lt2', '');
  const atomSet = inDef('atom %s');
  const bset = find(atomSet, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'evtype' && b.inputs.VALUE && b.inputs.VALUE[1] && b.inputs.VALUE[1][1] === 'N');
  if (bset.length !== 2) throw new Error('atom True/False evtype sets = ' + bset.length);
  for (const id of bset) BL()[id].inputs.VALUE = [1, [10, 'B']];
  // None literal
  const lookup = find(atomSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'lookup %s');
  if (lookup.length !== 1) throw new Error('atom lookup not found');
  const noneIf = ancestor(lookup[0], (b) => b.opcode === 'control_if_else');
  if (!noneIf) throw new Error('atom false-branch else not found');
  const oldLookup = BL()[noneIf].inputs.SUBSTACK2[1];
  setStack(noneIf, 'SUBSTACK2', [IFELSE(EQ(VAR('ev'), txt('None')),
    [setV('ev', txt('')), setV('evtype', txt('Z'))],
    [oldLookup])]);
  // truth(): None is falsy
  const tr = defIdOf('truth %s %s');
  const tvInit = BL()[tr].next;
  if (BL()[tvInit].opcode !== 'data_setvariableto' || BL()[tvInit].fields.VARIABLE[0] !== 'truthv') throw new Error('truth init not found');
  spliceAfter(tvInit, chain([IF(EQ(argOf('vt'), txt('Z')), [setV('truthv', num(0))])]));
  // strval / reprval
  newVar('lfn', 0); newVar('lfi', 0); newVar('lfacc', '');
  const sv = newProc('strval %s %s', ['vv', 'vt']);
  attachBody(sv.defId, [
    IFELSE(EQ(argOf('vt'), txt('B')), [
      IFELSE(EQ(argOf('vv'), num(1)), [setV('ev', txt('True'))], [setV('ev', txt('False'))]),
      setV('evtype', txt('S'))
    ], [
      IFELSE(EQ(argOf('vt'), txt('Z')), [setV('ev', txt('None')), setV('evtype', txt('S'))], [
        IFELSE(EQ(argOf('vt'), txt('L')), [callProc('listfmt %s', [argOf('vv')])], [
          setV('ev', argOf('vv')), setV('evtype', txt('S'))
        ])
      ])
    ])
  ]);
  const rv = newProc('reprval %s %s', ['vv', 'vt']);
  attachBody(rv.defId, [
    IFELSE(EQ(argOf('vt'), txt('S')), [
      setV('ev', JOIN(JOIN(txt("'"), argOf('vv')), txt("'"))),
      setV('evtype', txt('S'))
    ], [
      callProc('strval %s %s', [argOf('vv'), argOf('vt')])
    ])
  ]);
  // listfmt: element-wise repr (so string elements get quotes)
  const lf = defIdOf('listfmt %s');
  // NB: listitem() reuses lacc internally, so listfmt needs its own accumulator
  const newBody = chain([
    setV('lfacc', txt('[')),
    callProc('listlen %s', [argOf('s')]),
    setV('lfn', VAR('ev')),
    setV('lfi', num(1)),
    REPEATU(GT(VAR('lfi'), VAR('lfn')), [
      callProc('listitem %s %s', [argOf('s'), VAR('lfi')]),
      callProc('reprval %s %s', [VAR('ev'), VAR('evtype')]),
      IF(GT(VAR('lfi'), num(1)), [setV('lfacc', JOIN(VAR('lfacc'), txt(', ')))]),
      setV('lfacc', JOIN(VAR('lfacc'), VAR('ev'))),
      chgV('lfi', num(1))
    ]),
    setV('ev', JOIN(VAR('lfacc'), txt(']'))),
    setV('evtype', txt('S'))
  ]);
  BL()[lf].next = newBody; BL()[newBody].parent = lf;
  // printargs: show values Python-style
  const pa = inDef('printargs');
  const listIf = find(pa, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === 'L');
  if (listIf.length !== 1) throw new Error('printargs listfmt if = ' + listIf.length);
  replaceStmt(listIf[0], callProc('strval %s %s', [VAR('ev'), VAR('evtype')]));
  // callfn str()
  const cf = inDef('callfn %s %s %s');
  const strIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === 'str');
  if (strIf.length !== 1) throw new Error('callfn str branch = ' + strIf.length);
  setStack(strIf[0], 'SUBSTACK', [callProc('strval %s %s', [VAR('ev'), VAR('evtype')]), setV('pending', num(1))]);
  // callfn repr()
  const noFn = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'pending');
  if (noFn.length !== 1) throw new Error('callfn pending guard = ' + noFn.length);
  insertBeforeStmt(noFn[0], [IF(EQ(argOf('fn'), txt('repr')), [callProc('reprval %s %s', [VAR('ev'), VAR('evtype')]), setV('pending', num(1))])]);
  // callfn type(): bool / NoneType
  const typeElse = find(cf, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === 'S'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string' && JSON.stringify(reach(b.inputs.SUBSTACK[1]) && [...reach(b.inputs.SUBSTACK[1])].map((i) => BL()[i].inputs && BL()[i].inputs.VALUE)).includes('str'));
  if (typeElse.length !== 1) throw new Error('callfn type else = ' + typeElse.length);
  const oldType = BL()[typeElse[0]].inputs.SUBSTACK2[1];
  const tIf = ancestor(typeElse[0], (b) => b.opcode === 'control_if');
  setStack(tIf, 'SUBSTACK', [
    IFELSE(EQ(VAR('evtype'), txt('B')), [setV('ev', txt('bool'))],
      [IFELSE(EQ(VAR('evtype'), txt('Z')), [setV('ev', txt('NoneType'))], [oldType])]),
    setV('evtype', txt('S')),
    setV('pending', num(1))
  ]);
  // results of comparisons / in / not / bool() are bools
  const rs = inDef('rightside %s %s %s %s %s');
  const zeros = find(rs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ev' && b.inputs.VALUE && b.inputs.VALUE[1] && b.inputs.VALUE[1][1] === '0');
  let marked = 0;
  for (const zid of zeros) {
    const nxt = BL()[zid].next;
    if (!nxt || BL()[nxt].opcode !== 'control_if') continue;
    const evt = BL()[nxt].next;
    if (evt && BL()[evt].opcode === 'data_setvariableto' && BL()[evt].fields.VARIABLE[0] === 'evtype') { BL()[evt].inputs.VALUE = [1, [10, 'B']]; marked++; }
  }
  const foundSet = find(rs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ev' && b.inputs.VALUE && BL()[b.inputs.VALUE[1]] === undefined && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === 'found');
  for (const fid of foundSet) { const evt = BL()[fid].next; if (evt && BL()[evt].opcode === 'data_setvariableto' && BL()[evt].fields.VARIABLE[0] === 'evtype') { BL()[evt].inputs.VALUE = [1, [10, 'B']]; marked++; } }
  const un = inDef('unary %s %s %s');
  for (const id of find(un, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'evtype' && b.inputs.VALUE && b.inputs.VALUE[1] && b.inputs.VALUE[1][1] === 'N')) { BL()[id].inputs.VALUE = [1, [10, 'B']]; marked++; }
  const boolSet = find(cf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ev' && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === 'truthv');
  for (const bid of boolSet) { const evt = BL()[bid].next; if (evt && BL()[evt].opcode === 'data_setvariableto' && BL()[evt].fields.VARIABLE[0] === 'evtype') { BL()[evt].inputs.VALUE = [1, [10, 'B']]; marked++; } }
  // numeric operators treat bool as a number on the left-hand side
  const reps = find(new Set([...rs]), (b) => b.opcode === 'argument_reporter_string_number' && b.fields.VALUE && b.fields.VALUE[0] === 'lefttype');
  if (!reps.length) throw new Error('lefttype reporters not found');
  const vid = B.varIdOf('lt2');
  let rewrites = 0;
  for (const pid of allIds()) {
    const p = BL()[pid];
    for (const [slot, v] of Object.entries(p.inputs || {})) {
      if (v && typeof v[1] === 'string' && reps.includes(v[1])) { p.inputs[slot] = v.length > 2 ? [v[0], [12, 'lt2', vid], v[2]] : [v[0], [12, 'lt2', vid]]; rewrites++; }
    }
  }
  const rsDef = defIdOf('rightside %s %s %s %s %s');
  const rsBody = BL()[BL()[rsDef].next].next;   // if error == ""
  if (BL()[rsBody].opcode !== 'control_if') throw new Error('rightside body not found');
  const norm = chain([
    setV('lt2', argOf('lefttype')),
    IF(EQ(VAR('lt2'), txt('B')), [setV('lt2', txt('N'))]),
    IF(EQ(VAR('evtype'), txt('B')), [setV('evtype', txt('N'))])
  ]);
  prependStack(rsBody, 'SUBSTACK', norm);
  console.log('[P10] bools/None: evtype->B sets=' + marked + ', lefttype rewrites=' + rewrites);
});

// ---- P7: print(..., sep=, end=)
patch('P7 print sep/end', () => {
  newVar('psep', ' '); newVar('pendnl', 1); newVar('pendtxt', ''); newVar('pmbuf', ''); newVar('psepi', 0); newVar('pendi', 0); newVar('pstart', 0); newVar('pk', 0); newVar('pd', 0);
  const runDef = (() => {
    for (const id of allIds()) { const b = BL()[id]; if (b.opcode === 'event_whenbroadcastreceived' && b.fields.BROADCAST_OPTION && b.fields.BROADCAST_OPTION[0] === 'RUN') return id; }
    throw new Error('RUN hat not found');
  })();
  spliceAfter(runDef, chain([setV('pmbuf', txt(''))]));
  const pa = inDef('printargs');
  const bodyIf = find(pa, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals' && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'error');
  if (bodyIf.length !== 1) throw new Error('printargs log guard = ' + bodyIf.length);
  const logCall = BL()[bodyIf[0]].inputs.SUBSTACK[1];
  // statements that replace the old "clear(Comma) ... append(Comma,count)" preamble
  const clearComma = find(pa, (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'Comma');
  if (clearComma.length !== 1) throw new Error('printargs Comma clear = ' + clearComma.length);
  const firstStmt = BL()[defIdOf('printargs')].next;
  if (firstStmt !== clearComma[0]) throw new Error('printargs head changed');
  const tokAt = (x) => item('Tok', x);
  const scanKw = [
    setV('psepi', VAR('count')), setV('pendi', VAR('count')),
    setV('pk', num(3)), setV('pd', num(0)),
    REPEATU(GT(VAR('pk'), SUB(VAR('count'), num(1))), [
      IF(NOT(EQ(item('Kind', VAR('pk')), txt('S'))), [
        setV('eop', tokAt(VAR('pk'))),
        IF(OR(EQ(VAR('eop'), txt('(')), EQ(VAR('eop'), txt('['))), [chgV('pd', num(1))]),
        IF(OR(EQ(VAR('eop'), txt(')')), EQ(VAR('eop'), txt(']'))), [chgV('pd', num(-1))]),
        IF(AND(EQ(VAR('pd'), num(0)), AND(EQ(tokAt(ADD(VAR('pk'), num(1))), txt('=')), OR(EQ(VAR('eop'), txt('sep')), EQ(VAR('eop'), txt('end'))))), [
          IFELSE(EQ(VAR('eop'), txt('sep')), [setV('psepi', VAR('pk'))], [setV('pendi', VAR('pk'))])
        ])
      ]),
      chgV('pk', num(1))
    ]),
    setV('pstart', VAR('count')),
    IF(LT(VAR('psepi'), VAR('pstart')), [setV('pstart', VAR('psepi'))]),
    IF(LT(VAR('pendi'), VAR('pstart')), [setV('pstart', VAR('pendi'))]),
    setV('psep', txt(' ')), setV('pendnl', num(1)), setV('pendtxt', txt(''))
  ];
  const commaScan = [
    clearL('Comma'),
    setV('ed', num(0)), setV('ek', num(3)),
    REPEATU(GT(VAR('ek'), SUB(VAR('pstart'), num(1))), [
      IF(NOT(EQ(item('Kind', VAR('ek')), txt('S'))), [
        IF(OR(EQ(tokAt(VAR('ek')), txt('(')), EQ(tokAt(VAR('ek')), txt('['))), [chgV('ed', num(1))]),
        IF(OR(EQ(tokAt(VAR('ek')), txt(')')), EQ(tokAt(VAR('ek')), txt(']'))), [chgV('ed', num(-1))]),
        IF(AND(EQ(VAR('ed'), num(0)), EQ(tokAt(VAR('ek')), txt(','))), [addTo('Comma', VAR('ek'))])
      ]),
      chgV('ek', num(1))
    ]),
    IFELSE(EQ(tokAt(SUB(VAR('pstart'), num(1))), txt(',')),
      [addTo('Comma', SUB(VAR('pstart'), num(1)))],
      [addTo('Comma', VAR('pstart'))])
  ];
  const sepEval = [
    IF(AND(LT(VAR('psepi'), VAR('count')), EQ(VAR('psepi'), SUB(VAR('pstart'), num(0)))), [
      IFELSE(LT(VAR('pendi'), VAR('count')),
        [callProc('eval %s %s', [ADD(VAR('psepi'), num(2)), SUB(VAR('pendi'), num(1))])],
        [callProc('eval %s %s', [ADD(VAR('psepi'), num(2)), SUB(VAR('count'), num(1))])]),
      IF(EQ(VAR('error'), txt('')), [callProc('strval %s %s', [VAR('ev'), VAR('evtype')]), setV('psep', VAR('ev'))])
    ])
  ];
  const endEval = [
    IF(LT(VAR('pendi'), VAR('count')), [
      IFELSE(LT(VAR('psepi'), VAR('count')),
        [callProc('eval %s %s', [ADD(VAR('pendi'), num(2)), SUB(VAR('count'), num(1))])],
        [callProc('eval %s %s', [ADD(VAR('pendi'), num(2)), SUB(VAR('count'), num(1))])]),
      IF(EQ(VAR('error'), txt('')), [
        callProc('strval %s %s', [VAR('ev'), VAR('evtype')]),
        setV('pendtxt', VAR('ev')),
        IF(EQ(VAR('ev'), txt('')), [setV('pendnl', num(0))])
      ])
    ])
  ];
  const emit = [
    IFELSE(EQ(VAR('pendnl'), num(1)),
      [callProc('log %s', [JOIN(JOIN(VAR('pmbuf'), VAR('printbuf')), VAR('pendtxt'))]),
       setV('pmbuf', txt('')), setV('pendnl', num(1)), setV('pendtxt', txt(''))],
      [setV('pmbuf', JOIN(VAR('pmbuf'), VAR('printbuf')))])
  ];
  const head = chain([...scanKw, ...commaScan, setV('printbuf', txt(''))]);
  insertBeforeStmt(firstStmt, [head]);
  // drop the original "clear(Comma) ... append(Comma, count)" preamble: the new
  // scan above already built Comma, stopping before any sep=/end= keyword
  const oldSentinel = find(pa, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'Comma'
    && b.inputs.ITEM && Array.isArray(b.inputs.ITEM[1]) && b.inputs.ITEM[1][1] === 'count');
  if (oldSentinel.length !== 1) throw new Error('printargs old sentinel = ' + oldSentinel.length);
  {
    const pred = predecessorOf(firstStmt);
    const after = BL()[oldSentinel[0]].next;
    if (!pred) throw new Error('printargs head not spliced');
    BL()[pred].next = after;
    if (after) BL()[after].parent = pred;
    BL()[firstStmt].parent = null;
    BL()[oldSentinel[0]].next = null;
  }
  // rebuild the argument loop: empty segments (trailing comma before sep=) produce
  // no text, and the join uses psep instead of a hard-coded space
  const loop = find(pa, (b) => b.opcode === 'control_repeat' && b.inputs.TIMES && typeof b.inputs.TIMES[1] === 'string'
    && BL()[b.inputs.TIMES[1]].opcode === 'data_lengthoflist' && BL()[b.inputs.TIMES[1]].fields.LIST[0] === 'Comma');
  if (loop.length !== 1) throw new Error('printargs loop = ' + loop.length);
  setStack(loop[0], 'SUBSTACK', [
    setV('phi', SUB(item('Comma', VAR('pi')), num(1))),
    IF(NOT(GT(VAR('plo'), VAR('phi'))), [
      callProc('eval %s %s', [VAR('plo'), VAR('phi')]),
      IF(GT(VAR('pi'), num(1)), [setV('printbuf', JOIN(VAR('printbuf'), VAR('psep')))]),
      callProc('strval %s %s', [VAR('ev'), VAR('evtype')]),
      setV('printbuf', JOIN(VAR('printbuf'), VAR('ev')))
    ]),
    setV('plo', ADD(item('Comma', VAR('pi')), num(1))),
    chgV('pi', num(1))
  ]);
  // final log -> emit (honours end=), preceded by the sep=/end= evaluation
  const emitFirst = chain(emit);
  replaceStmt(logCall, emitFirst);
  // sep=/end= are evaluated before the arguments (they apply to the whole call)
  insertBeforeStmt(loop[0], [...sepEval, ...endEval]);
  console.log('[P7] print sep/end installed');
});

// ---- P8/P9: list slicing -- a[1:3], a[i:j] = [...], del a[i:j]
patch('P8/P9 list slices', () => {
  newVar('lsacc', ''); newVar('lsi', 0);
  newVar('slc', 0); newVar('sd', 0); newVar('sk', 0);
  newVar('sls', 0); newVar('sle', 0); newVar('sln', 0); newVar('slr', ''); newVar('slrec', '');
  newVar('swa', ''); newVar('swn', 0); newVar('sws', 0); newVar('swe', 0); newVar('swi', 0); newVar('swacc', '');
  const tokAt = (x) => item('Tok', x);

  // shared writer: name, recv(encoded list), xs, xe (0-based, half-open), repl(encoded list or "")
  const sw = newProc('slicewrite %s %s %s %s %s', ['name', 'recv', 'xs', 'xe', 'repl']);
  attachBody(sw.defId, [
    setV('swa', argOf('recv')),
    callProc('listlen %s', [VAR('swa')]),
    setV('swn', VAR('ev')),
    IFELSE(LT(argOf('xs'), num(0)), [setV('sws', ADD(argOf('xs'), VAR('swn')))], [setV('sws', argOf('xs'))]),
    IF(LT(VAR('sws'), num(0)), [setV('sws', num(0))]),
    IF(GT(VAR('sws'), VAR('swn')), [setV('sws', VAR('swn'))]),
    IFELSE(LT(argOf('xe'), num(0)), [setV('swe', ADD(argOf('xe'), VAR('swn')))], [setV('swe', argOf('xe'))]),
    IF(LT(VAR('swe'), num(0)), [setV('swe', num(0))]),
    IF(GT(VAR('swe'), VAR('swn')), [setV('swe', VAR('swn'))]),
    IF(LT(VAR('swe'), VAR('sws')), [setV('swe', VAR('sws'))]),
    setV('swacc', txt('')), setV('swi', num(1)),
    REPEATU(GT(VAR('swi'), VAR('sws')), [
      callProc('listitem %s %s', [VAR('swa'), VAR('swi')]),
      setV('swacc', JOIN(JOIN(JOIN(VAR('swacc'), VAR('lsep')), VAR('evtype')), VAR('ev'))),
      chgV('swi', num(1))
    ]),
    setV('swacc', JOIN(VAR('swacc'), argOf('repl'))),
    setV('swi', ADD(VAR('swe'), num(1))),
    REPEATU(GT(VAR('swi'), VAR('swn')), [
      callProc('listitem %s %s', [VAR('swa'), VAR('swi')]),
      setV('swacc', JOIN(JOIN(JOIN(VAR('swacc'), VAR('lsep')), VAR('evtype')), VAR('ev'))),
      chgV('swi', num(1))
    ]),
    callProc('assign %s %s %s', [argOf('name'), VAR('swacc'), txt('L')]),
    setV('ev', txt('')), setV('evtype', txt('S'))
  ]);

  // find the top-level ':' inside an index region (returns the token index in slc)
  const colonScan = (startExpr, endExpr) => [
    setV('slc', num(0)), setV('sd', num(0)), setV('sk', startExpr),
    REPEATU(GT(VAR('sk'), endExpr), [
      IF(OR(EQ(tokAt(VAR('sk')), txt('(')), EQ(tokAt(VAR('sk')), txt('['))), [chgV('sd', num(1))]),
      IF(OR(EQ(tokAt(VAR('sk')), txt(')')), EQ(tokAt(VAR('sk')), txt(']'))), [chgV('sd', num(-1))]),
      IF(AND(EQ(VAR('sd'), num(0)), AND(EQ(tokAt(VAR('sk')), txt(':')), EQ(VAR('slc'), num(0)))), [setV('slc', VAR('sk'))]),
      chgV('sk', num(1))
    ])
  ];
  const bounds = (startTok, endTok) => [
    setV('sls', num(0)),
    setV('sle', VAR('sln')),
    IF(GT(VAR('slc'), startTok), [callProc('eval %s %s', [startTok, SUB(VAR('slc'), num(1))]), setV('sls', VAR('ev'))]),
    IF(LT(VAR('slc'), endTok), [callProc('eval %s %s', [ADD(VAR('slc'), num(1)), endTok]), setV('sle', VAR('ev'))])
  ];

  // ---- read: a[1:3]
  const ig = inDef('indexget %s %s');
  const xlenSet = find(ig, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'xlen' && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]].opcode === 'operator_length');
  if (xlenSet.length !== 1) throw new Error('indexget xlen = ' + xlenSet.length);
  spliceAfter(xlenSet[0], chain([
    IF(EQ(VAR('xb'), txt('L')), [callProc('listlen %s', [VAR('xa')]), setV('xlen', VAR('ev'))])
  ]));
  const subFinal = find(ig, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'substr %s %s %s'
    && Object.values(b.inputs).some((v) => Array.isArray(v[1]) && v[1][1] === 'xhi'));
  if (subFinal.length !== 1) throw new Error('indexget slice tail = ' + subFinal.length);
  replaceStmt(subFinal[0], IFELSE(EQ(VAR('xb'), txt('L')), [
    setV('lsacc', txt('')),
    setV('lsi', ADD(VAR('xlo'), num(1))),
    REPEATU(GT(VAR('lsi'), VAR('xhi')), [
      callProc('listitem %s %s', [VAR('xa'), VAR('lsi')]),
      setV('lsacc', JOIN(JOIN(JOIN(VAR('lsacc'), VAR('lsep')), VAR('evtype')), VAR('ev'))),
      chgV('lsi', num(1))
    ]),
    setV('ev', VAR('lsacc')),
    setV('evtype', txt('L'))
  ], [callProc('substr %s %s %s', [VAR('xa'), ADD(VAR('xlo'), num(1)), VAR('xhi')])]));

  // ---- assign: a[i:j] = [...]
  const iset = inDef('indexset %s %s');
  const setEqFail = find(iset, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s' && JSON.stringify(b.inputs).includes('expected = after'));
  if (setEqFail.length !== 1) throw new Error('indexset = check not found');
  const setIf = ancestor(setEqFail[0], (b) => b.opcode === 'control_if');
  if (!setIf) throw new Error('indexset = check if not found');
  spliceAfter(setIf, chain([
    ...colonScan(ADD(argOf('lo'), num(2)), SUB(VAR('lsp'), num(1))),
    IF(GT(VAR('slc'), num(0)), [
      callProc('eval %s %s', [argOf('lo'), argOf('lo')]),
      IF(NOT(EQ(VAR('evtype'), txt('L'))), [FAIL(txt('TypeError: slice assignment needs a list'))]),
      setV('slrec', VAR('ev')),
      callProc('listlen %s', [VAR('slrec')]),
      setV('sln', VAR('ev')),
      setV('sls', num(0)),
      setV('sle', VAR('sln')),
      IF(GT(VAR('slc'), ADD(argOf('lo'), num(2))), [
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('slc'), num(1))]),
        setV('sls', VAR('ev'))
      ]),
      IF(LT(VAR('slc'), SUB(VAR('lsp'), num(1))), [
        callProc('eval %s %s', [ADD(VAR('slc'), num(1)), SUB(VAR('lsp'), num(1))]),
        setV('sle', VAR('ev'))
      ]),
      callProc('eval %s %s', [ADD(VAR('lsp'), num(2)), argOf('hi')]),
      IF(NOT(EQ(VAR('evtype'), txt('L'))), [FAIL(txt('TypeError: slice assignment needs a list'))]),
      setV('slr', VAR('ev')),
      callProc('slicewrite %s %s %s %s %s', [tokAt(argOf('lo')), VAR('slrec'), VAR('sls'), VAR('sle'), VAR('slr')]),
      I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } })
    ])
  ]));

  // ---- del a[i:j]
  const idel = inDef('indexdel %s %s');
  const delBracket = find(idel, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s' && JSON.stringify(b.inputs).includes('expected ] after del'));
  if (delBracket.length !== 1) throw new Error('indexdel bracket check not found');
  const delIf = ancestor(delBracket[0], (b) => b.opcode === 'control_if');
  if (!delIf) throw new Error('indexdel bracket if not found');
  spliceAfter(delIf, chain([
    ...colonScan(ADD(argOf('lo'), num(3)), SUB(VAR('lsp'), num(1))),
    IF(GT(VAR('slc'), num(0)), [
      callProc('eval %s %s', [ADD(argOf('lo'), num(1)), ADD(argOf('lo'), num(1))]),
      IF(NOT(EQ(VAR('evtype'), txt('L'))), [FAIL(txt('TypeError: del needs a list'))]),
      setV('slrec', VAR('ev')),
      callProc('listlen %s', [VAR('slrec')]),
      setV('sln', VAR('ev')),
      setV('sls', num(0)),
      setV('sle', VAR('sln')),
      IF(GT(VAR('slc'), ADD(argOf('lo'), num(3))), [
        callProc('eval %s %s', [ADD(argOf('lo'), num(3)), SUB(VAR('slc'), num(1))]),
        setV('sls', VAR('ev'))
      ]),
      IF(LT(VAR('slc'), SUB(VAR('lsp'), num(1))), [
        callProc('eval %s %s', [ADD(VAR('slc'), num(1)), SUB(VAR('lsp'), num(1))]),
        setV('sle', VAR('ev'))
      ]),
      callProc('slicewrite %s %s %s %s %s', [tokAt(ADD(argOf('lo'), num(1))), VAR('slrec'), VAR('sls'), VAR('sle'), txt('')]),
      I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } })
    ])
  ]));
  // del slice needs the bounds too: recompute inside the branch
  console.log('[P8/P9] list slicing installed');
});

// ---- P13: list methods sort/reverse/index/count/insert/remove + sorted()
patch('P13 list methods', () => {
  newVar('lsn', 0); newVar('lsix', 0); newVar('lsj', 0); newVar('lsk', 0);
  newVar('lsacc2', ''); newVar('lsav', ''); newVar('lsbv', ''); newVar('lsat', ''); newVar('lsbt', '');
  newVar('lswap', 0); newVar('lneed', ''); newVar('lnt', ''); newVar('lres', 0); newVar('mcut', 0); newVar('mbest', 0);
  B.addList(IT, 'LSV', []); B.addList(IT, 'LST', []);
  const tokAt = (x) => item('Tok', x);
  const enc = (acc, tv, vv) => JOIN(JOIN(JOIN(acc, VAR('lsep')), tv), vv);
  const sameElem = (va, ta, vb, tb) => IFELSE(EQ(ta, txt('S')),
    [callProc('compareText %s %s', [va, vb]), IF(EQ(VAR('cmp'), num(0)), [setV('lswap', num(1))])],
    [IF(AND(EQ(va, vb), EQ(ta, tb)), [setV('lswap', num(1))])]);

  // ---- lsort: enc(list) -> ev (sorted list)
  const srt = newProc('lsort %s', ['s']);
  attachBody(srt.defId, [
    clearL('LSV'), clearL('LST'),
    callProc('listlen %s', [argOf('s')]), setV('lsn', VAR('ev')),
    setV('lsix', num(1)),
    REPEATU(GT(VAR('lsix'), VAR('lsn')), [
      callProc('listitem %s %s', [argOf('s'), VAR('lsix')]),
      addTo('LSV', VAR('ev')), addTo('LST', VAR('evtype')),
      chgV('lsix', num(1))
    ]),
    setV('lsk', num(1)),
    REPEATU(GT(VAR('lsk'), SUB(VAR('lsn'), num(1))), [
      setV('lsj', num(1)),
      REPEATU(GT(VAR('lsj'), SUB(VAR('lsn'), num(1))), [
        setV('lsav', item('LSV', VAR('lsj'))), setV('lsat', item('LST', VAR('lsj'))),
        setV('lsbv', item('LSV', ADD(VAR('lsj'), num(1)))), setV('lsbt', item('LST', ADD(VAR('lsj'), num(1)))),
        setV('lswap', num(0)),
        IFELSE(AND(EQ(VAR('lsat'), txt('N')), EQ(VAR('lsbt'), txt('N'))),
          [IF(GT(VAR('lsav'), VAR('lsbv')), [setV('lswap', num(1))])],
          [IFELSE(AND(EQ(VAR('lsat'), txt('S')), EQ(VAR('lsbt'), txt('S'))),
            [callProc('compareText %s %s', [VAR('lsav'), VAR('lsbv')]), IF(GT(VAR('cmp'), num(0)), [setV('lswap', num(1))])],
            [FAIL(txt('TypeError: sort requires all numbers or all strings'))])]),
        IF(EQ(VAR('lswap'), num(1)), [
          I('data_replaceitemoflist', { fields: B.LISTF('LSV'), inputs: { INDEX: B.REP(VAR('lsj'), [4, '0']), ITEM: B.REP(VAR('lsbv'), [4, '0']) } }),
          I('data_replaceitemoflist', { fields: B.LISTF('LSV'), inputs: { INDEX: B.REP(ADD(VAR('lsj'), num(1)), [4, '0']), ITEM: B.REP(VAR('lsav'), [4, '0']) } }),
          I('data_replaceitemoflist', { fields: B.LISTF('LST'), inputs: { INDEX: B.REP(VAR('lsj'), [4, '0']), ITEM: B.REP(VAR('lsbt'), [4, '0']) } }),
          I('data_replaceitemoflist', { fields: B.LISTF('LST'), inputs: { INDEX: B.REP(ADD(VAR('lsj'), num(1)), [4, '0']), ITEM: B.REP(VAR('lsat'), [4, '0']) } })
        ]),
        chgV('lsj', num(1))
      ]),
      chgV('lsk', num(1))
    ]),
    setV('lsacc2', txt('')), setV('lsix', num(1)),
    REPEATU(GT(VAR('lsix'), VAR('lsn')), [
      setV('lsacc2', enc(VAR('lsacc2'), item('LST', VAR('lsix')), item('LSV', VAR('lsix')))),
      chgV('lsix', num(1))
    ]),
    setV('ev', VAR('lsacc2')), setV('evtype', txt('L'))
  ]);

  // ---- methodcall: extra methods
  const mc = inDef('methodcall %s %s');
  const lit = find(mc, (b) => Object.values(b.inputs || {}).some((v) => Array.isArray(v[1]) && v[1][1] === 'AttributeError: list has no method '));
  if (lit.length !== 1) throw new Error('methodcall fallback literal = ' + lit.length);
  let callId = lit[0];
  while (callId && !(BL()[callId].opcode === 'procedures_call' && BL()[callId].mutation && BL()[callId].mutation.proccode === 'fail %s')) callId = BL()[callId].parent;
  if (!callId) throw new Error('methodcall fallback call not found');
  const noMethIf = ancestor(callId, (b) => b.opcode === 'control_if');
  if (!noMethIf) throw new Error('methodcall fallback if not found');
  {
    const names = ['append', 'extend', 'pop', 'clear', 'sort', 'reverse', 'index', 'count', 'insert', 'remove'];
    let cond = null;
    for (const n of names) { const e = EQ(VAR('lmeth'), txt(n)); cond = cond ? OR(cond, e) : e; }
    BL()[noMethIf].inputs.CONDITION = B.BOOL(NOT(cond));
  }
  const recvName = () => tokAt(argOf('lo'));
  const newBlocks = [
    // a.sort()
    IF(EQ(VAR('lmeth'), txt('sort')), [
      callProc('lsort %s', [VAR('xa')]),
      callProc('assign %s %s %s', [recvName(), VAR('ev'), txt('L')]),
      setV('ev', txt('')), setV('evtype', txt('S'))
    ]),
    // a.reverse()
    IF(EQ(VAR('lmeth'), txt('reverse')), [
      callProc('listlen %s', [VAR('xa')]), setV('lsn', VAR('ev')),
      setV('lsacc2', txt('')), setV('lsix', VAR('lsn')),
      REPEATU(NOT(GT(VAR('lsix'), num(0))), [
        callProc('listitem %s %s', [VAR('xa'), VAR('lsix')]),
        setV('lsacc2', enc(VAR('lsacc2'), VAR('evtype'), VAR('ev'))),
        chgV('lsix', num(-1))
      ]),
      callProc('assign %s %s %s', [recvName(), VAR('lsacc2'), txt('L')]),
      setV('ev', txt('')), setV('evtype', txt('S'))
    ]),
    // a.index(x) / a.count(x)
    IF(OR(EQ(VAR('lmeth'), txt('index')), EQ(VAR('lmeth'), txt('count'))), [
      callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
      setV('lneed', VAR('ev')), setV('lnt', VAR('evtype')),
      callProc('listlen %s', [VAR('xa')]), setV('lsn', VAR('ev')),
      setV('lsix', num(1)), setV('lres', num(0)), setV('mbest', num(0)),
      REPEATU(GT(VAR('lsix'), VAR('lsn')), [
        callProc('listitem %s %s', [VAR('xa'), VAR('lsix')]),
        setV('lsbv', VAR('ev')), setV('lsbt', VAR('evtype')),
        setV('lswap', num(0)),
        sameElem(VAR('lsbv'), VAR('lsbt'), VAR('lneed'), VAR('lnt')),
        IF(EQ(VAR('lswap'), num(1)), [
          chgV('mbest', num(1)),
          IF(EQ(VAR('lres'), num(0)), [setV('lres', VAR('lsix'))])
        ]),
        chgV('lsix', num(1))
      ]),
      IFELSE(EQ(VAR('lmeth'), txt('index')),
        [IFELSE(EQ(VAR('mbest'), num(0)),
          [FAILB(JOIN(txt('ValueError: '), JOIN(VAR('lneed'), txt(' is not in list'))))],
          [setV('ev', SUB(VAR('lres'), num(1))), setV('evtype', txt('N'))])],
        [setV('ev', VAR('mbest')), setV('evtype', txt('N'))])
    ]),
    // a.insert(i, x)
    IF(EQ(VAR('lmeth'), txt('insert')), [
      setV('mcut', num(0)), setV('sd', num(0)), setV('sk', ADD(argOf('lo'), num(4))),
      REPEATU(GT(VAR('sk'), SUB(argOf('hi'), num(1))), [
        IF(OR(EQ(tokAt(VAR('sk')), txt('(')), EQ(tokAt(VAR('sk')), txt('['))), [chgV('sd', num(1))]),
        IF(OR(EQ(tokAt(VAR('sk')), txt(')')), EQ(tokAt(VAR('sk')), txt(']'))), [chgV('sd', num(-1))]),
        IF(AND(EQ(VAR('sd'), num(0)), AND(EQ(tokAt(VAR('sk')), txt(',')), EQ(VAR('mcut'), num(0)))), [setV('mcut', VAR('sk'))]),
        chgV('sk', num(1))
      ]),
      IF(EQ(VAR('mcut'), num(0)), [FAIL(txt('TypeError: insert needs 2 arguments'))]),
      callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(VAR('mcut'), num(1))]),
      setV('lsi', VAR('ev')),
      IF(LT(VAR('lsi'), num(0)), [
        callProc('listlen %s', [VAR('xa')]), setV('lsi', ADD(VAR('lsi'), VAR('ev')))
      ]),
      IF(LT(VAR('lsi'), num(0)), [setV('lsi', num(0))]),
      callProc('eval %s %s', [ADD(VAR('mcut'), num(1)), SUB(argOf('hi'), num(1))]),
      setV('lres', VAR('lsi')), setV('lneed', VAR('ev')), setV('lnt', VAR('evtype')),
      callProc('slicewrite %s %s %s %s %s', [recvName(), VAR('xa'), VAR('lres'), VAR('lres'), JOIN(JOIN(VAR('lsep'), VAR('lnt')), VAR('lneed'))]),
      setV('ev', txt('')), setV('evtype', txt('S'))
    ]),
    // a.remove(x)
    IF(EQ(VAR('lmeth'), txt('remove')), [
      callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
      setV('lneed', VAR('ev')), setV('lnt', VAR('evtype')),
      callProc('listlen %s', [VAR('xa')]), setV('lsn', VAR('ev')),
      setV('lsix', num(1)), setV('lres', num(0)),
      REPEATU(OR(GT(VAR('lsix'), VAR('lsn')), GT(VAR('lres'), num(0))), [
        callProc('listitem %s %s', [VAR('xa'), VAR('lsix')]),
        setV('lsbv', VAR('ev')), setV('lsbt', VAR('evtype')),
        setV('lswap', num(0)),
        sameElem(VAR('lsbv'), VAR('lsbt'), VAR('lneed'), VAR('lnt')),
        IF(EQ(VAR('lswap'), num(1)), [setV('lres', VAR('lsix'))]),
        chgV('lsix', num(1))
      ]),
      IFELSE(EQ(VAR('lres'), num(0)),
        [FAILB(JOIN(txt('ValueError: '), JOIN(VAR('lneed'), txt(' is not in list'))))],
        [callProc('slicewrite %s %s %s %s %s', [recvName(), VAR('xa'), SUB(VAR('lres'), num(1)), VAR('lres'), txt('')])]),
      setV('ev', txt('')), setV('evtype', txt('S'))
    ])
  ];
  insertBeforeStmt(noMethIf, newBlocks);

  // ---- sorted(x) builtin
  const cf = inDef('callfn %s %s %s');
  const pendingIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'pending');
  if (pendingIf.length !== 1) throw new Error('callfn pending guard (sorted) = ' + pendingIf.length);
  insertBeforeStmt(pendingIf[0], [
    IF(EQ(argOf('fn'), txt('sorted')), [
      IF(NOT(EQ(VAR('evtype'), txt('L'))), [FAIL(txt('TypeError: sorted() requires a list'))]),
      callProc('lsort %s', [VAR('ev')]),
      setV('pending', num(1))
    ])
  ]);
  console.log('[P13] list methods + sorted installed');
});

// ---- P14: user-defined functions -- def / return / recursion / local scope
patch('P14 def/return', () => {
  for (const v of ['fi', 'fj', 'fk', 'fd', 'fphi', 'fplo', 'fpn', 'fpo', 'fdd', 'ftype', 'fval', 'fu',
                   'fstart', 'fend', 'retflag', 'cdepth', 'csteps',
                   'epB', 'epI', 'epJ', 'epN']) newVar(v, 0);
  for (const l of ['FnName', 'FnPN', 'FnPO', 'FnPar', 'FnDef', 'FnStart', 'FnEnd',
                   'FrRet', 'FrLoop', 'FrBase', 'FrVBase', 'FrLBase', 'FN', 'FV', 'FT',
                   'UArgV', 'UArgT', 'UComma', 'DefSeg', 'DefPar', 'DefDef', 'VSave', 'LSave']) B.addList(IT, l, []);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const IN = (x, list) => I('data_listcontainsitem', { fields: B.LISTF(list), inputs: { ITEM: B.REP(x, [10, '']) } });
  const delItem = (list, idx) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']) } });
  const lastOf = (list) => item(list, llen(list));

  const fp = newProc('fpush', []);
  const fo = newProc('fpop', []);

  // (a) indentation: a block may follow "def" just like if/while/for
  {
    const prep = inDef('prepare');
    const elifEqs = find(prep, (b) => b.opcode === 'operator_equals' && b.inputs.OPERAND2 && b.inputs.OPERAND2[1] && b.inputs.OPERAND2[1][1] === 'elif');
    if (!elifEqs.length) throw new Error('prepare elif tests not found');
    for (const eq of elifEqs) {
      const orId = BL()[eq].parent;
      if (!orId || BL()[orId].opcode !== 'operator_or') throw new Error('prepare elif or not found');
      const ref = refOf(orId);
      if (!ref) throw new Error('prepare elif or has no parent');
      const outer = OR(orId, EQ(VAR('prevhead'), txt('def')));
      BL()[ref.pid].inputs[ref.slot] = [2, outer];
      BL()[outer].parent = ref.pid;
      BL()[orId].parent = outer;
    }
  }

  // (b) register the function
  const rd = newProc('regdef %s', ['name']);
  attachBody(rd.defId, [
    clearL('DefSeg'), clearL('DefPar'), clearL('DefDef'),
    setV('fd', num(0)), setV('fk', num(4)),
    REPEATU(GT(VAR('fk'), SUB(VAR('count'), num(1))), [
      IF(OR(EQ(tokAt(VAR('fk')), txt('(')), EQ(tokAt(VAR('fk')), txt('['))), [chgV('fd', num(1))]),
      IF(OR(EQ(tokAt(VAR('fk')), txt(')')), EQ(tokAt(VAR('fk')), txt(']'))), [chgV('fd', num(-1))]),
      IF(AND(EQ(VAR('fd'), num(0)), EQ(tokAt(VAR('fk')), txt(','))), [addTo('DefSeg', VAR('fk'))]),
      chgV('fk', num(1))
    ]),
    addTo('DefSeg', SUB(VAR('count'), num(1))),
    setV('fj', num(1)), setV('fplo', num(4)),
    REPEATU(GT(VAR('fj'), llen('DefSeg')), [
      setV('fphi', SUB(item('DefSeg', VAR('fj')), num(1))),
      IF(NOT(GT(VAR('fplo'), VAR('fphi'))), [
        addTo('DefPar', tokAt(VAR('fplo'))),
        IFELSE(EQ(tokAt(ADD(VAR('fplo'), num(1))), txt('=')), [
          callProc('eval %s %s', [ADD(VAR('fplo'), num(2)), VAR('fphi')]),
          addTo('DefDef', JOIN(JOIN(VAR('lsep'), VAR('evtype')), VAR('ev')))
        ], [addTo('DefDef', txt(''))])
      ]),
      setV('fplo', ADD(item('DefSeg', VAR('fj')), num(1))),
      chgV('fj', num(1))
    ]),
    addTo('FnName', argOf('name')),
    addTo('FnPN', llen('DefPar')),
    addTo('FnPO', ADD(llen('FnPar'), num(1))),
    setV('fj', num(1)),
    REPEATU(GT(VAR('fj'), llen('DefPar')), [
      addTo('FnPar', item('DefPar', VAR('fj'))),
      addTo('FnDef', item('DefDef', VAR('fj'))),
      chgV('fj', num(1))
    ]),
    addTo('FnStart', ADD(VAR('pc'), num(1))),
    addTo('FnEnd', SUB(item('Ends', VAR('pc')), num(1)))
  ]);

  // (c) run one call
  const cu = newProc('calluser %s %s %s', ['fn', 'lo', 'hi']);
  attachBody(cu.defId, [
    setV('fi', llen('FnName')),
    REPEATU(OR(LT(VAR('fi'), num(1)), EQ(item('FnName', VAR('fi')), argOf('fn'))), [chgV('fi', num(-1))]),
    IF(LT(VAR('fi'), num(1)), [FAILB(JOIN(txt('NameError: function '), argOf('fn'))), STOPTHIS()]),
    chgV('cdepth', num(1)),
    IF(GT(VAR('cdepth'), num('96')), [FAIL(txt('RecursionError: maximum recursion depth exceeded')), STOPTHIS()]),
    // frame switch: snapshot the caller's globals, keep the variable table as the
    // callee's starting scope (assignments are discarded on return, like Python locals)
    addTo('FrRet', VAR('pc')),
    addTo('FrBase', ADD(llen('FN'), num(1))),
    callProc('fpush'),
    setV('fj', num(1)),
    REPEATU(GT(VAR('fj'), llen('Names')), [
      addTo('FN', item('Names', VAR('fj'))), addTo('FV', item('Values', VAR('fj'))), addTo('FT', item('Types', VAR('fj'))),
      chgV('fj', num(1))
    ]),
    // arguments: evaluated in the caller's scope, after the caller's state is saved
    clearL('UArgV'), clearL('UArgT'), clearL('UComma'),
    IF(NOT(GT(argOf('lo'), argOf('hi'))), [
      setV('fd', num(0)), setV('fk', argOf('lo')),
      REPEATU(GT(VAR('fk'), argOf('hi')), [
        IF(OR(EQ(tokAt(VAR('fk')), txt('(')), EQ(tokAt(VAR('fk')), txt('['))), [chgV('fd', num(1))]),
        IF(OR(EQ(tokAt(VAR('fk')), txt(')')), EQ(tokAt(VAR('fk')), txt(']'))), [chgV('fd', num(-1))]),
        IF(AND(EQ(VAR('fd'), num(0)), EQ(tokAt(VAR('fk')), txt(','))), [addTo('UComma', VAR('fk'))]),
        chgV('fk', num(1))
      ]),
      addTo('UComma', ADD(argOf('hi'), num(1))),
      setV('fj', num(1)), setV('fplo', argOf('lo')),
      REPEATU(GT(VAR('fj'), llen('UComma')), [
        setV('fphi', SUB(item('UComma', VAR('fj')), num(1))),
        IF(NOT(GT(VAR('fplo'), VAR('fphi'))), [
          callProc('eval %s %s', [VAR('fplo'), VAR('fphi')]),
          addTo('UArgV', VAR('ev')), addTo('UArgT', VAR('evtype'))
        ]),
        setV('fplo', ADD(item('UComma', VAR('fj')), num(1))),
        chgV('fj', num(1))
      ])
    ]),
    // parameters
    setV('fpn', item('FnPN', VAR('fi'))), setV('fpo', item('FnPO', VAR('fi'))),
    IF(GT(llen('UArgV'), VAR('fpn')), [FAIL(txt('TypeError: too many arguments')), STOPTHIS()]),
    setV('fj', num(1)),
    REPEATU(GT(VAR('fj'), VAR('fpn')), [
      setV('fu', ADD(VAR('fpo'), SUB(VAR('fj'), num(1)))),
      IFELSE(NOT(GT(VAR('fj'), llen('UArgV'))), [
        callProc('assign %s %s %s', [item('FnPar', VAR('fu')), item('UArgV', VAR('fj')), item('UArgT', VAR('fj'))])
      ], [
        setV('fdd', item('FnDef', VAR('fu'))),
        IFELSE(EQ(VAR('fdd'), txt('')), [
          FAILB(JOIN(txt('TypeError: missing argument '), item('FnPar', VAR('fu')))), STOPTHIS()
        ], [
          callProc('substr %s %s %s', [VAR('fdd'), num(3), lenOf(VAR('fdd'))]),
          setV('fval', VAR('ev')),
          setV('ftype', letterOf(num(2), VAR('fdd'))),
          callProc('assign %s %s %s', [item('FnPar', VAR('fu')), VAR('fval'), VAR('ftype')])
        ])
      ]),
      chgV('fj', num(1))
    ]),
    // body
    setV('pc', item('FnStart', VAR('fi'))),
    setV('fend', item('FnEnd', VAR('fi'))),
    setV('retflag', num(0)),
    setV('csteps', num(0)),
    REPEATU(OR(OR(GT(VAR('pc'), VAR('fend')), NOT(EQ(VAR('error'), txt('')))), EQ(VAR('retflag'), num(1))), [
      chgV('csteps', num(1)),
      IFELSE(GT(VAR('csteps'), num(20000)), [FAIL(txt('LimitError: step limit inside function'))], [
        callProc('boundary'),
        IFELSE(AND(NOT(GT(VAR('pc'), llen('Code'))), EQ(VAR('error'), txt(''))), [
          callProc('tokenize %s', [item('Code', VAR('pc'))]),
          IFELSE(GT(llen('Tok'), num(0)), [callProc('execute')], [chgV('pc', num(1))])
        ], [setV('pc', ADD(VAR('fend'), num(1)))])
      ])
    ]),
    IF(EQ(VAR('retflag'), num(0)), [setV('ev', txt('')), setV('evtype', txt('Z'))]),
    // unwind loops the callee left open
    REPEATU(NOT(GT(llen('LoopHead'), lastOf('FrLoop'))), [callProc('popLoop')]),
    // restore the caller's variable table
    setV('epB', lastOf('FrBase')),
    clearL('Names'), clearL('Values'), clearL('Types'),
    setV('epI', VAR('epB')),
    REPEATU(GT(VAR('epI'), llen('FN')), [
      addTo('Names', item('FN', VAR('epI'))), addTo('Values', item('FV', VAR('epI'))), addTo('Types', item('FT', VAR('epI'))),
      chgV('epI', num(1))
    ]),
    REPEAT(ADD(SUB(llen('FN'), VAR('epB')), num(1)), [delItem('FN', llen('FN')), delItem('FV', llen('FV')), delItem('FT', llen('FT'))]),
    // restore every shared global (pc/dest included) and this line's tokens
    callProc('fpop'),
    callProc('tokenize %s', [item('Code', VAR('pc'))]),
    delItem('FrRet', llen('FrRet')), delItem('FrLoop', llen('FrLoop')), delItem('FrBase', llen('FrBase')),
    delItem('FrVBase', llen('FrVBase')), delItem('FrLBase', llen('FrLBase')),
    chgV('cdepth', num(-1)),
    setV('retflag', num(0))
  ]);
  // ------------------------------------------------------------------
  // Which globals must be saved around a call?  Any variable/list touched by a
  // procedure that can (transitively) run user code may be live across a nested
  // call -- e.g. printargs' Comma while a function prints.  Everything else is
  // provably private to a leaf procedure and is left alone.
  const procInfo = new Map();
  for (const id of allIds()) {
    const b = BL()[id];
    if (b.opcode !== 'procedures_definition' || !b.inputs || !b.inputs.custom_block) continue;
    const proto = BL()[b.inputs.custom_block[1]];
    if (proto) procInfo.set(proto.mutation.proccode, { callees: new Set(), vars: new Set(), lists: new Set() });
  }
  for (const pc of [...procInfo.keys()]) {
    const info = procInfo.get(pc);
    for (const id of reach(defIdOf(pc))) {
      const b = BL()[id];
      if (b.opcode === 'procedures_call' && b.mutation) info.callees.add(b.mutation.proccode);
      if (b.fields && b.fields.VARIABLE) info.vars.add(b.fields.VARIABLE[0]);
      if (b.fields && b.fields.LIST) info.lists.add(b.fields.LIST[0]);
      for (const v of Object.values(b.inputs || {})) if (Array.isArray(v[1]) && v[1][0] === 12) info.vars.add(v[1][1]);
    }
  }
  const impure = new Set(['execute', 'eval %s %s', 'callfn %s %s %s', 'calluser %s %s %s']);
  for (let changed = true; changed;) {
    changed = false;
    for (const [pc, info] of procInfo) {
      if (impure.has(pc)) continue;
      for (const c of info.callees) if (impure.has(c)) { impure.add(pc); changed = true; break; }
    }
  }
  // NB: the interpreter keeps several temps on the Stage (pc, branchjump, ...); they are
  // shared with the shell, so error/running/status/... are deliberately left alone.
  const EXCL_VARS = new Set(['ev', 'evtype', 'retflag', 'cdepth', 'error', 'running', 'status', 'dirty', 'busy', 'dq', 'slash', 'lsep']);
  const saveVars = Object.values(T(IT).variables).map((x) => x[0])
    .filter((v) => !EXCL_VARS.has(v) && !v.startsWith('ep'))
    .filter((v) => [...procInfo].some(([pc, info]) => impure.has(pc) && info.vars.has(v)))
    .concat(Object.values(T('Stage').variables).map((x) => x[0]).filter((v) => !EXCL_VARS.has(v)));
  const SKIP_LISTS = new Set(['Tok', 'Kind', 'LoopText', 'FnName', 'FnPN', 'FnPO', 'FnPar', 'FnDef', 'FnStart', 'FnEnd',
    'FrRet', 'FrLoop', 'FrBase', 'FrVBase', 'FrLBase', 'FN', 'FV', 'FT', 'VSave', 'LSave', 'Trace']);
  const saveLists = Object.values(T(IT).lists).map((x) => x[0])
    .filter((l) => !SKIP_LISTS.has(l))
    .filter((l) => [...procInfo].some(([pc, info]) => impure.has(pc) && info.lists.has(l)));

  // fpush: snapshot every shared global into the frame stacks
  attachBody(fp.defId, [
    addTo('FrVBase', ADD(llen('VSave'), num(1))),
    addTo('FrLBase', ADD(llen('LSave'), num(1))),
    addTo('FrLoop', llen('LoopHead')),
    ...saveVars.map((v) => addTo('VSave', VAR(v))),
    ...saveLists.flatMap((L) => [
      addTo('LSave', llen(L)),
      setV('epI', num(1)),
      REPEATU(GT(VAR('epI'), llen(L)), [addTo('LSave', item(L, VAR('epI'))), chgV('epI', num(1))])
    ])
  ]);
  // fpop: put them back (and drop this frame's copies)
  attachBody(fo.defId, [
    setV('epB', lastOf('FrVBase')),
    ...saveVars.map((v, k) => setV(v, item('VSave', ADD(VAR('epB'), num(k))))),
    REPEAT(ADD(SUB(llen('VSave'), VAR('epB')), num(1)), [delItem('VSave', llen('VSave'))]),
    setV('epB', lastOf('FrLBase')),
    setV('epI', VAR('epB')),
    ...saveLists.flatMap((L) => [
      setV('epN', item('LSave', VAR('epI'))),
      chgV('epI', num(1)),
      clearL(L),
      setV('epJ', num(1)),
      REPEATU(GT(VAR('epJ'), VAR('epN')), [addTo(L, item('LSave', VAR('epI'))), chgV('epI', num(1)), chgV('epJ', num(1))])
    ]),
    REPEAT(ADD(SUB(llen('LSave'), VAR('epB')), num(1)), [delItem('LSave', llen('LSave'))])
  ]);

  console.log('[P14] frames save ' + saveVars.length + ' vars + ' + saveLists.length + ' lists: ' + saveLists.join(','));

  // (d) execute: def / return statements
  const ex = inDef('execute');
  const pendingIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'pending');
  if (pendingIf.length !== 1) throw new Error('execute pending guard = ' + pendingIf.length);
  insertBeforeStmt(pendingIf[0], [
    IF(EQ(VAR('head'), txt('def')), [
      IF(NOT(AND(EQ(item('Kind', num(2)), txt('I')), AND(EQ(tokAt(num(3)), txt('(')), EQ(tokAt(VAR('count')), txt(':'))))),
        [FAIL(txt('SyntaxError: def name(params):'))]),
      callProc('regdef %s', [tokAt(num(2))]),
      setV('dest', item('Ends', VAR('pc'))),
      setV('pending', num(1))
    ]),
    IF(EQ(VAR('head'), txt('return')), [
      IFELSE(EQ(VAR('cdepth'), num(0)),
        [FAIL(txt('SyntaxError: return outside function'))],
        [IFELSE(GT(VAR('count'), num(1)),
           [callProc('eval %s %s', [num(2), VAR('count')])],
           [setV('ev', txt('')), setV('evtype', txt('Z'))]),
         setV('retflag', num(1))]),
      setV('pending', num(1))
    ])
  ]);

  // (e) callfn: user functions first
  {
    const cf = defIdOf('callfn %s %s %s');
    insertBeforeStmt(BL()[cf].next, [
      IF(IN(argOf('fn'), 'FnName'), [
        callProc('calluser %s %s %s', [argOf('fn'), argOf('lo'), argOf('hi')]),
        STOPTHIS()
      ])
    ]);
  }

  // (f) eval: multi-argument calls to user functions
  {
    const ev = inDef('eval %s %s');
    const multi = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'builtin2 %s %s %s %s'));
    if (!multi.length) throw new Error('eval multi dispatch not found');
    multi.sort((a, b) => reach(BL()[a].inputs.SUBSTACK[1]).size - reach(BL()[b].inputs.SUBSTACK[1]).size);
    const mId = multi[0];
    const oldSub2 = BL()[mId].inputs.SUBSTACK2 ? BL()[mId].inputs.SUBSTACK2[1] : null;
    const fnTok = () => item('Tok', argOf('lo'));
    const userIf = IFELSE(IN(fnTok(), 'FnName'),
      [callProc('callfn %s %s %s', [fnTok(), ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))])],
      oldSub2 ? [oldSub2] : []);
    setStack(mId, 'SUBSTACK2', [userIf]);
  }

  // (g) reset the function table on every run
  {
    const runDef = (() => { for (const id of allIds()) { const b = BL()[id]; if (b.opcode === 'event_whenbroadcastreceived' && b.fields.BROADCAST_OPTION && b.fields.BROADCAST_OPTION[0] === 'RUN') return id; } throw new Error('RUN hat not found'); })();
    spliceAfter(runDef, chain([
      clearL('FnName'), clearL('FnPN'), clearL('FnPO'), clearL('FnPar'), clearL('FnDef'), clearL('FnStart'), clearL('FnEnd'),
      clearL('FrRet'), clearL('FrLoop'), clearL('FrBase'), clearL('FrVBase'), clearL('FrLBase'), clearL('FN'), clearL('FV'), clearL('FT'),
      clearL('VSave'), clearL('LSave'),
      setV('cdepth', num(0)), setV('retflag', num(0))
    ]));
  }
});

// ---- P15: for/while ... else  (+ break skips the else clause)
patch('P15 loop-else', () => {
  const prep = inDef('prepare');
  const tokAt = (x) => item('Tok', x);
  const headIs = (v) => EQ(tokAt(num(1)), txt(v));
  const isTok1Test = (id, val) => {
    const b = BL()[id];
    if (b.opcode !== 'operator_equals') return false;
    if (!b.inputs.OPERAND2 || !b.inputs.OPERAND2[1] || b.inputs.OPERAND2[1][1] !== val) return false;
    const l = b.inputs.OPERAND1 && b.inputs.OPERAND1[1];
    if (typeof l !== 'string') return false;
    const lb = BL()[l];
    return lb && lb.opcode === 'data_itemoflist' && lb.fields.LIST[0] === 'Tok'
      && lb.inputs.INDEX && lb.inputs.INDEX[1] && lb.inputs.INDEX[1][1] === '1';
  };
  // trigger: "else:" / "elif:" lines get validated (drop P14's stray prevhead clause)
  const trigger = find(prep, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && [...reach(b.inputs.CONDITION[1])].some((id) => isTok1Test(id, 'elif'))
    && [...reach(b.inputs.CONDITION[1])].some((id) => isTok1Test(id, 'else'))
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto' && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'ej');
  if (trigger.length !== 1) throw new Error('prepare else/elif trigger = ' + trigger.length);
  BL()[trigger[0]].inputs.CONDITION = B.BOOL(OR(headIs('else'), headIs('elif')));
  // validation: the preceding same-indent line may also be for/while (loop else)
  const fails = find(prep, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && Object.values(b.inputs).some((v) => Array.isArray(v[1]) && v[1][1] === 'SyntaxError: elif/else without if'));
  if (fails.length !== 2) throw new Error('prepare loop-else fails = ' + fails.length);
  for (const fid of fails) {
    const ifId = ancestor(fid, (b) => b.opcode === 'control_if');
    if (!ifId) continue;
    const cond = BL()[ifId].inputs.CONDITION[1];
    if (!cond || BL()[cond].opcode !== 'operator_not') continue;
    BL()[ifId].inputs.CONDITION = B.BOOL(NOT(OR(OR(headIs('if'), headIs('elif')), OR(headIs('while'), headIs('for')))));
  }
  // loop-else marker: prepare flags "else:" lines whose owner is for/while
  B.addList(IT, 'LoopElse', []);
  const indentsAppend = find(prep, (b) => b.opcode === 'data_addtolist' && b.fields.LIST[0] === 'Indents');
  if (indentsAppend.length !== 1) throw new Error('Indents append = ' + indentsAppend.length);
  spliceAfter(indentsAppend[0], chain([addTo('LoopElse', num(0))]));
  const valIf = find(prep, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_not'
    && [...reach(b.inputs.CONDITION[1])].some((id) => isTok1Test(id, 'if')));
  if (valIf.length !== 1) throw new Error('prepare loop-else validation = ' + valIf.length);
  {
    // Tok still holds the PRECEDING same-indent line here, so this is where we can
    // tell a loop-else ("else:" owned by for/while) from an if-else.
    const marker = chain([
      IF(OR(headIs('for'), headIs('while')), [
        callProc('tokenize %s', [item('Code', VAR('ei'))]),
        IF(headIs('else'), [
          I('data_replaceitemoflist', { fields: B.LISTF('LoopElse'), inputs: { INDEX: B.REP(VAR('ei'), [4, '0']), ITEM: B.REP(num(1), [4, '0']) } })
        ])
      ])
    ]);
    spliceAfter(valIf[0], marker);
  }
  // execute: fall into the loop-else body
  {
    const ex = inDef('execute');
    const elseIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === 'else');
    if (elseIf.length !== 1) throw new Error('execute else branch = ' + elseIf.length);
    // the "if branchjump == 1 ... else dest = Ends[pc]" inner if/else: take the else path
    const destEnds = find(reach(elseIf[0]), (b, id) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'dest'
      && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]].opcode === 'data_itemoflist'
      && BL()[b.inputs.VALUE[1]].fields.LIST[0] === 'Ends'
      && b.parent && BL()[b.parent].opcode === 'control_if_else'
      && BL()[b.parent].inputs.SUBSTACK2 && BL()[b.parent].inputs.SUBSTACK2[1] === id);
    if (destEnds.length !== 1) throw new Error('execute else dest = ' + destEnds.length);
    replaceStmt(destEnds[0], IFELSE(EQ(item('LoopElse', VAR('pc')), num(1)), [setV('dest', ADD(VAR('pc'), num(1)))], [setV('dest', item('Ends', VAR('pc')))]));
  }
  // break must jump past the else clause of the enclosing loop
  {
    const ex = inDef('execute');
    const destLoopEnd = find(ex, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'dest'
      && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
      && BL()[b.inputs.VALUE[1]].opcode === 'data_itemoflist' && BL()[b.inputs.VALUE[1]].fields.LIST[0] === 'LoopEnd');
    if (destLoopEnd.length !== 1) throw new Error('break dest = ' + destLoopEnd.length);
    spliceAfter(destLoopEnd[0], chain([
      IF(EQ(VAR('head'), txt('break')), [
        IF(GT(item('Elses', item('LoopHead', VAR('lc'))), num(0)), [
          setV('dest', item('Ends', item('Elses', item('LoopHead', VAR('lc')))))
        ])
      ])
    ]));
  }
  console.log('[P15] for/while-else installed');
});

// ---- P16: builtin exception classes as values (print(ValueError) etc.)
patch('P16 builtin classes', () => {
  const CLASSES = ['Exception', 'ValueError', 'TypeError', 'IndexError', 'KeyError', 'NameError', 'ZeroDivisionError',
    'AttributeError', 'RuntimeError', 'AssertionError', 'StopIteration', 'ArithmeticError', 'OverflowError'];
  const atomSet = inDef('atom %s');
  const lookup = find(atomSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'lookup %s');
  if (lookup.length !== 1) throw new Error('atom lookup = ' + lookup.length);
  const noneIf = refOf(lookup[0]).pid;         // the "None" test P10 built
  let cond = null;
  for (const c of CLASSES) { const e = EQ(VAR('ev'), txt(c)); cond = cond ? OR(cond, e) : e; }
  replaceStmt(noneIf, IFELSE(cond, [setV('evtype', txt('C'))], [noneIf]));
  // strval: "<class 'ValueError'>"
  const sv = defIdOf('strval %s %s');
  const body = BL()[sv].next;
  if (BL()[body].opcode !== 'control_if_else') throw new Error('strval body = ' + BL()[body].opcode);
  const outer = IFELSE(EQ(argOf('vt'), txt('C')), [
    setV('ev', JOIN(JOIN(txt("<class '"), argOf('vv')), txt("'>"))),
    setV('evtype', txt('S'))
  ], [body]);
  BL()[sv].next = outer; BL()[outer].parent = sv;
  console.log('[P16] builtin exception classes installed');
});

// ---- P17: lambda (expression-bodied functions, assigned like any value)
patch('P17 lambda', () => {
  newVar('lamn', 0); newVar('fc', 0); newVar('fd2', 0); newVar('fk2', 0);
  newVar('rlfj', 0); newVar('rlflo', 0); newVar('rlfphi', 0);   // private: calluser's arg loop uses fj/fplo/fphi
  for (const l of ['FnKind', 'FnLine', 'FnTlo', 'FnThi']) B.addList(IT, l, []);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const IN = (x, list) => I('data_listcontainsitem', { fields: B.LISTF(list), inputs: { ITEM: B.REP(x, [10, '']) } });

  // every plain def also needs an entry in the parallel lists
  {
    const rd = defIdOf('regdef %s');
    const appends = find(reach(rd), (b) => b.opcode === 'data_addtolist' && b.fields.LIST[0] === 'FnEnd');
    if (appends.length !== 1) throw new Error('regdef FnEnd append = ' + appends.length);
    spliceAfter(appends[0], chain([
      addTo('FnKind', txt('D')), addTo('FnLine', num(0)), addTo('FnTlo', num(0)), addTo('FnThi', num(0))
    ]));
  }

  // reglam lo hi : parse "lambda <params> : <body>" starting at token lo
  const rl = newProc('reglam %s %s', ['lo', 'hi']);
  attachBody(rl.defId, [
    setV('fc', num(0)), setV('fd2', num(0)), setV('fk2', ADD(argOf('lo'), num(1))),
    REPEATU(GT(VAR('fk2'), argOf('hi')), [
      IF(OR(EQ(tokAt(VAR('fk2')), txt('(')), EQ(tokAt(VAR('fk2')), txt('['))), [chgV('fd2', num(1))]),
      IF(OR(EQ(tokAt(VAR('fk2')), txt(')')), EQ(tokAt(VAR('fk2')), txt(']'))), [chgV('fd2', num(-1))]),
      IF(AND(EQ(VAR('fd2'), num(0)), AND(EQ(tokAt(VAR('fk2')), txt(':')), EQ(VAR('fc'), num(0)))), [setV('fc', VAR('fk2'))]),
      chgV('fk2', num(1))
    ]),
    IF(EQ(VAR('fc'), num(0)), [FAIL(txt('SyntaxError: lambda needs a colon')), STOPTHIS()]),
    clearL('DefSeg'), clearL('DefPar'),
    setV('fd2', num(0)), setV('fk2', ADD(argOf('lo'), num(1))),
    REPEATU(GT(VAR('fk2'), SUB(VAR('fc'), num(1))), [
      IF(OR(EQ(tokAt(VAR('fk2')), txt('(')), EQ(tokAt(VAR('fk2')), txt('['))), [chgV('fd2', num(1))]),
      IF(OR(EQ(tokAt(VAR('fk2')), txt(')')), EQ(tokAt(VAR('fk2')), txt(']'))), [chgV('fd2', num(-1))]),
      IF(AND(EQ(VAR('fd2'), num(0)), EQ(tokAt(VAR('fk2')), txt(','))), [addTo('DefSeg', VAR('fk2'))]),
      chgV('fk2', num(1))
    ]),
    addTo('DefSeg', VAR('fc')),   // sentinel: the colon, so the last param ends at fc-1
    setV('rlfj', num(1)), setV('rlflo', ADD(argOf('lo'), num(1))),
    REPEATU(GT(VAR('rlfj'), llen('DefSeg')), [
      setV('rlfphi', SUB(item('DefSeg', VAR('rlfj')), num(1))),
      IF(NOT(GT(VAR('rlflo'), VAR('rlfphi'))), [addTo('DefPar', tokAt(VAR('rlflo')))]),
      setV('rlflo', ADD(item('DefSeg', VAR('rlfj')), num(1))),
      chgV('rlfj', num(1))
    ]),
    chgV('lamn', num(1)),
    addTo('FnName', JOIN(txt('#lambda'), VAR('lamn'))),
    addTo('FnPN', llen('DefPar')),
    addTo('FnPO', ADD(llen('FnPar'), num(1))),
    setV('rlfj', num(1)),
    REPEATU(GT(VAR('rlfj'), llen('DefPar')), [
      addTo('FnPar', item('DefPar', VAR('rlfj'))),
      addTo('FnDef', txt('')),
      chgV('rlfj', num(1))
    ]),
    addTo('FnStart', num(0)), addTo('FnEnd', num(0)),
    addTo('FnKind', txt('L')), addTo('FnLine', VAR('pc')),
    addTo('FnTlo', ADD(VAR('fc'), num(1))), addTo('FnThi', argOf('hi')),
    setV('ev', llen('FnName')), setV('evtype', txt('F'))
  ]);

  // eval: "lambda ..." at the head of an expression builds a function value
  {
    const evDef = defIdOf('eval %s %s');
    const guard = BL()[BL()[evDef].next].next;
    if (!guard || BL()[guard].opcode !== 'control_if') throw new Error('eval guard not found');
    const rest = detachTail(guard);
    const lamIf = IFELSE(EQ(tokAt(argOf('lo')), txt('lambda')), [
      callProc('reglam %s %s', [argOf('lo'), argOf('hi')]),
      chgV('fnlimit', num(-1))
    ], rest ? [rest] : []);
    const first = chain([lamIf]);
    BL()[guard].next = first; BL()[first].parent = guard;
  }

  // callfn: a name bound to a function value is callable too
  {
    const cf = defIdOf('callfn %s %s %s');
    insertBeforeStmt(BL()[cf].next, [
      callProc('lookup %s', [argOf('fn')]),
      IF(AND(NOT(EQ(VAR('found'), num(0))), EQ(item('Types', VAR('found')), txt('F'))), [
        callProc('calluser %s %s %s', [argOf('fn'), argOf('lo'), argOf('hi')]),
        STOPTHIS()
      ])
    ]);
  }

  // eval's dispatch must also treat "name holds a function value" as callable
  {
    newVar('callable', 0);
    const evSet = inDef('eval %s %s');
    const dispatch = find(evSet, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'callfn %s %s %s')
      && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === '0');
    if (!dispatch.length) throw new Error('eval dispatch narg==0 branch not found');
    dispatch.sort((a, b) => reach(BL()[a].inputs.SUBSTACK[1]).size - reach(BL()[b].inputs.SUBSTACK[1]).size);
    const dId = dispatch[0];
    const fnTok = () => item('Tok', argOf('lo'));
    insertBeforeStmt(dId, [
      setV('callable', num(0)),
      IF(IN(fnTok(), 'FnName'), [setV('callable', num(1))]),
      callProc('lookup %s', [fnTok()]),
      IF(AND(NOT(EQ(VAR('found'), num(0))), EQ(item('Types', VAR('found')), txt('F'))), [setV('callable', num(1))])
    ]);
    const userIf = find(evSet, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'data_listcontainsitem' && BL()[b.inputs.CONDITION[1]].fields.LIST[0] === 'FnName');
    if (userIf.length !== 1) throw new Error('eval user-function dispatch = ' + userIf.length);
    BL()[userIf[0]].inputs.CONDITION = B.BOOL(EQ(VAR('callable'), num(1)));
  }

  // calluser: resolve F values, and run lambda bodies as a single expression
  {
    const cu = defIdOf('calluser %s %s %s');
    const nameFail = find(reach(cu), (b) => {
      if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
      return Object.values(b.inputs).some((v) => {
        if (typeof v[1] !== 'string') return false;
        const j = BL()[v[1]];
        return j && j.opcode === 'operator_join' && j.inputs.STRING1 && j.inputs.STRING1[1] && j.inputs.STRING1[1][1] === 'NameError: function ';
      });
    });
    if (!nameFail.length) throw new Error('calluser name lookup fail not found');
    const nameFailIf = ancestor(nameFail[0], (b) => b.opcode === 'control_if');
    insertBeforeStmt(nameFailIf, [
      IF(LT(VAR('fi'), num(1)), [
        callProc('lookup %s', [argOf('fn')]),
        IF(AND(NOT(EQ(VAR('found'), num(0))), EQ(item('Types', VAR('found')), txt('F'))), [
          setV('fi', item('Values', VAR('found')))
        ])
      ])
    ]);
    // body: lambda -> evaluate the stored token range of its defining line
    const bodySet = find(reach(cu), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'pc'
      && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]].opcode === 'data_itemoflist'
      && BL()[b.inputs.VALUE[1]].fields.LIST[0] === 'FnStart');
    if (bodySet.length !== 1) throw new Error('calluser body start = ' + bodySet.length);
    // everything from "pc = FnStart" up to (but not including) the epilogue is the
    // "def" path; a lambda is just one expression on its defining line.
    const epi = find(reach(cu), (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'retflag'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === '0');
    if (epi.length !== 1) throw new Error('calluser epilogue = ' + epi.length);
    const epiId = epi[0];
    const lastOfDefPath = predecessorOf(epiId);
    if (!lastOfDefPath) throw new Error('calluser def path tail not found');
    BL()[lastOfDefPath].next = null;
    const loopBody = IFELSE(EQ(item('FnKind', VAR('fi')), txt('L')), [
      // pc must point at the defining line: a nested call re-tokenizes Code[pc]
      setV('pc', item('FnLine', VAR('fi'))),
      callProc('tokenize %s', [item('Code', VAR('pc'))]),
      callProc('eval %s %s', [item('FnTlo', VAR('fi')), item('FnThi', VAR('fi'))]),
      setV('retflag', num(1))
    ], [bodySet[0]]);
    insertBeforeStmt(bodySet[0], [loopBody]);
    BL()[loopBody].next = epiId;
    BL()[epiId].parent = loopBody;
  }

  // reset the new tables each run
  {
    const runDef = (() => { for (const id of allIds()) { const b = BL()[id]; if (b.opcode === 'event_whenbroadcastreceived' && b.fields.BROADCAST_OPTION && b.fields.BROADCAST_OPTION[0] === 'RUN') return id; } throw new Error('RUN hat not found'); })();
    spliceAfter(runDef, chain([clearL('FnKind'), clearL('FnLine'), clearL('FnTlo'), clearL('FnThi'), setV('lamn', num(0))]));
  }
  console.log('[P17] lambda installed');
});

// ---- P18: string methods (upper/lower/strip/find/count/replace/startswith/endswith/split/join)
patch('P18 string methods', () => {
  for (const v of ['smacc', 'smi', 'smp', 'smn', 'smc', 'smrep', 'smout', 'smlo', 'smhi', 'smlen', 'smlist', 'smcut', 'smrec', 'smmeth', 'sma1', 'smt1', 'sma2', 'smt2'])
    newVar(v, 0);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const LOWER = 'abcdefghijklmnopqrstuvwxyz';
  const UPPER = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const args = () => [ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))];

  // --- index of a character inside cs (ASCII 32..126), 1-based
  const charIndex = (chExpr) => [
    setV('smp', num(1)), setV('found', num(0)),
    REPEATU(OR(GT(VAR('smp'), num(95)), EQ(VAR('found'), num(1))), [
      callProc('compareText %s %s', [letterOf(VAR('smp'), VAR('cs')), chExpr]),
      IFELSE(EQ(VAR('cmp'), num(0)), [setV('found', num(1))], [chgV('smp', num(1))])
    ])
  ];

  // --- scase s mode : 'U' upper / 'L' lower
  // --- scase s mode : 'upper' / 'lower'
  // NB: Scratch's "contains" is case-INsensitive, so membership is decided by the
  // index of the character inside cs (ASCII 32..126) instead.
  const scase = newProc('scase %s %s', ['s', 'mode']);
  attachBody(scase.defId, [
    setV('smacc', txt('')), setV('smi', num(1)),
    REPEATU(GT(VAR('smi'), lenOf(argOf('s'))), [
      setV('smc', letterOf(VAR('smi'), argOf('s'))),
      setV('smrep', VAR('smc')),
      ...charIndex(VAR('smc')),
      IF(EQ(VAR('found'), num(1)), [
        IFELSE(EQ(argOf('mode'), txt('upper')), [
          IF(AND(NOT(LT(VAR('smp'), num(66))), NOT(GT(VAR('smp'), num(91)))), [
            setV('smrep', letterOf(SUB(VAR('smp'), num(32)), VAR('cs')))
          ])
        ], [
          IF(AND(NOT(LT(VAR('smp'), num(34))), NOT(GT(VAR('smp'), num(59)))), [
            setV('smrep', letterOf(ADD(VAR('smp'), num(32)), VAR('cs')))
          ])
        ])
      ]),
      setV('smacc', JOIN(VAR('smacc'), VAR('smrep'))),
      chgV('smi', num(1))
    ]),
    setV('ev', VAR('smacc')), setV('evtype', txt('S'))
  ]);

  // --- sfind s sub -> 0-based index or -1
  const sfind = newProc('sfind %s %s', ['s', 'sub']);
  attachBody(sfind.defId, [
    setV('smlen', lenOf(argOf('sub'))), setV('smn', lenOf(argOf('s'))),
    IFELSE(EQ(VAR('smlen'), num(0)), [
      setV('ev', num(0)), setV('evtype', txt('N'))
    ], [
      setV('smi', num(1)), setV('found', num(-1)),
      REPEATU(OR(GT(VAR('smi'), ADD(SUB(VAR('smn'), VAR('smlen')), num(1))), GT(VAR('found'), num(-1))), [
        callProc('substr %s %s %s', [argOf('s'), VAR('smi'), SUB(ADD(VAR('smi'), VAR('smlen')), num(1))]),
        callProc('compareText %s %s', [VAR('ev'), argOf('sub')]),
        IFELSE(EQ(VAR('cmp'), num(0)), [setV('found', SUB(VAR('smi'), num(1)))], [chgV('smi', num(1))])
      ]),
      setV('ev', VAR('found')), setV('evtype', txt('N'))
    ])
  ]);

  // --- scount s sub -> number of non-overlapping occurrences
  const scount = newProc('scount %s %s', ['s', 'sub']);
  attachBody(scount.defId, [
    setV('smlen', lenOf(argOf('sub'))), setV('smn', lenOf(argOf('s'))), setV('smp', num(0)), setV('smi', num(1)),
    IF(GT(VAR('smlen'), num(0)), [
      REPEATU(GT(VAR('smi'), ADD(SUB(VAR('smn'), VAR('smlen')), num(1))), [
        callProc('substr %s %s %s', [argOf('s'), VAR('smi'), SUB(ADD(VAR('smi'), VAR('smlen')), num(1))]),
        callProc('compareText %s %s', [VAR('ev'), argOf('sub')]),
        IFELSE(EQ(VAR('cmp'), num(0)), [chgV('smp', num(1)), chgV('smi', SUB(VAR('smlen'), num(1)))], []),
        chgV('smi', num(1))
      ])
    ]),
    setV('ev', VAR('smp')), setV('evtype', txt('N'))
  ]);

  // --- srep s from to
  const srep = newProc('srep %s %s %s', ['s', 'from', 'to']);
  attachBody(srep.defId, [
    setV('smlen', lenOf(argOf('from'))), setV('smn', lenOf(argOf('s'))),
    setV('smacc', txt('')), setV('smi', num(1)),
    IFELSE(EQ(VAR('smlen'), num(0)), [
      setV('smacc', argOf('s'))
    ], [
      REPEATU(GT(VAR('smi'), VAR('smn')), [
        setV('found', num(0)),
        IF(NOT(GT(ADD(VAR('smi'), VAR('smlen')), ADD(VAR('smn'), num(1)))), [
          callProc('substr %s %s %s', [argOf('s'), VAR('smi'), SUB(ADD(VAR('smi'), VAR('smlen')), num(1))]),
          callProc('compareText %s %s', [VAR('ev'), argOf('from')]),
          IF(EQ(VAR('cmp'), num(0)), [setV('found', num(1))])
        ]),
        IFELSE(EQ(VAR('found'), num(1)), [
          setV('smacc', JOIN(VAR('smacc'), argOf('to'))),
          chgV('smi', SUB(VAR('smlen'), num(1)))
        ], [
          setV('smacc', JOIN(VAR('smacc'), letterOf(VAR('smi'), argOf('s'))))
        ]),
        chgV('smi', num(1))
      ])
    ]),
    setV('ev', VAR('smacc')), setV('evtype', txt('S'))
  ]);

  // --- sprefix s sub mode : 'B' begin / 'E' end -> bool
  const sprefix = newProc('sprefix %s %s %s', ['s', 'sub', 'mode']);
  attachBody(sprefix.defId, [
    setV('smlen', lenOf(argOf('sub'))), setV('smn', lenOf(argOf('s'))), setV('found', num(0)),
    IF(NOT(GT(VAR('smlen'), VAR('smn'))), [
      IFELSE(EQ(argOf('mode'), txt('startswith')), [
        callProc('substr %s %s %s', [argOf('s'), num(1), VAR('smlen')])
      ], [
        callProc('substr %s %s %s', [argOf('s'), ADD(SUB(VAR('smn'), VAR('smlen')), num(1)), VAR('smn')])
      ]),
      callProc('compareText %s %s', [VAR('ev'), argOf('sub')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('found', num(1))])
    ]),
    setV('ev', VAR('found')), setV('evtype', txt('B'))
  ]);

  // --- ssplit s sep -> list of parts (sep = "" splits into characters)
  const ssplit = newProc('ssplit %s %s', ['s', 'sep']);
  attachBody(ssplit.defId, [
    setV('smacc', txt('')), setV('smlen', lenOf(argOf('sep'))), setV('smn', lenOf(argOf('s'))),
    IFELSE(EQ(VAR('smlen'), num(0)), [
      setV('smi', num(1)),
      REPEATU(GT(VAR('smi'), VAR('smn')), [
        setV('smacc', JOIN(VAR('smacc'), JOIN(JOIN(VAR('lsep'), txt('S')), letterOf(VAR('smi'), argOf('s'))))),
        chgV('smi', num(1))
      ])
    ], [
      setV('smi', num(1)), setV('smlo', num(1)),
      REPEATU(GT(ADD(VAR('smi'), VAR('smlen')), ADD(VAR('smn'), num(1))), [
        callProc('substr %s %s %s', [argOf('s'), VAR('smi'), SUB(ADD(VAR('smi'), VAR('smlen')), num(1))]),
        callProc('compareText %s %s', [VAR('ev'), argOf('sep')]),
        IF(EQ(VAR('cmp'), num(0)), [
          callProc('substr %s %s %s', [argOf('s'), VAR('smlo'), SUB(VAR('smi'), num(1))]),
          setV('smacc', JOIN(VAR('smacc'), JOIN(JOIN(VAR('lsep'), txt('S')), VAR('ev')))),
          chgV('smi', SUB(VAR('smlen'), num(1))),
          setV('smlo', ADD(VAR('smi'), num(1)))
        ]),
        chgV('smi', num(1))
      ]),
      IF(NOT(GT(VAR('smlo'), VAR('smn'))), [
        callProc('substr %s %s %s', [argOf('s'), VAR('smlo'), VAR('smn')]),
        setV('smacc', JOIN(VAR('smacc'), JOIN(JOIN(VAR('lsep'), txt('S')), VAR('ev'))))
      ])
    ]),
    setV('ev', VAR('smacc')), setV('evtype', txt('L'))
  ]);

  // --- sjoin sep list -> string
  const sjoin = newProc('sjoin %s %s', ['sep', 'lst']);
  attachBody(sjoin.defId, [
    callProc('listlen %s', [argOf('lst')]), setV('smn', VAR('ev')),
    setV('smacc', txt('')), setV('smi', num(1)),
    REPEATU(GT(VAR('smi'), VAR('smn')), [
      IF(GT(VAR('smi'), num(1)), [setV('smacc', JOIN(VAR('smacc'), argOf('sep')))]),
      callProc('listitem %s %s', [argOf('lst'), VAR('smi')]),
      setV('smacc', JOIN(VAR('smacc'), VAR('ev'))),
      chgV('smi', num(1))
    ]),
    setV('ev', VAR('smacc')), setV('evtype', txt('S'))
  ]);

  // --- methodcall: string receivers
  // All argument expressions are evaluated BEFORE the dispatch, and the receiver is
  // taken from a private stack, because a nested method call in an argument would
  // otherwise clobber xa/lmeth (they are plain globals).
  const mc = inDef('methodcall %s %s');
  const onlyList = find(mc, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && Object.values(b.inputs).some((v) => Array.isArray(v[1]) && v[1][1] === 'AttributeError: only lists have methods'));
  if (onlyList.length !== 1) throw new Error('methodcall list-only guard = ' + onlyList.length);
  const guardIf = ancestor(onlyList[0], (b) => b.opcode === 'control_if');
  BL()[guardIf].inputs.CONDITION = B.BOOL(NOT(OR(EQ(VAR('xb'), txt('L')), EQ(VAR('xb'), txt('S')))));
  B.addList(IT, 'MRStack', []); B.addList(IT, 'MMStack', []);
  const knownNames = ['upper', 'lower', 'strip', 'find', 'count', 'replace', 'startswith', 'endswith', 'split', 'join'];
  let knownCond = null;
  for (const n of knownNames) { const e = EQ(VAR('smmeth'), txt(n)); knownCond = knownCond ? OR(knownCond, e) : e; }
  const argLo = () => ADD(argOf('lo'), num(4));
  const argHi = () => SUB(argOf('hi'), num(1));
  const dispatch = [
    IF(OR(EQ(VAR('smmeth'), txt('upper')), EQ(VAR('smmeth'), txt('lower'))), [
      callProc('scase %s %s', [VAR('smrec'), VAR('smmeth')])
    ]),
    IF(EQ(VAR('smmeth'), txt('strip')), [callProc('trimsp %s', [VAR('smrec')])]),
    IF(EQ(VAR('smmeth'), txt('find')), [callProc('sfind %s %s', [VAR('smrec'), VAR('sma1')])]),
    IF(EQ(VAR('smmeth'), txt('count')), [callProc('scount %s %s', [VAR('smrec'), VAR('sma1')])]),
    IF(OR(EQ(VAR('smmeth'), txt('startswith')), EQ(VAR('smmeth'), txt('endswith'))), [
      callProc('sprefix %s %s %s', [VAR('smrec'), VAR('sma1'), VAR('smmeth')])
    ]),
    IF(EQ(VAR('smmeth'), txt('replace')), [callProc('srep %s %s %s', [VAR('smrec'), VAR('sma1'), VAR('sma2')])]),
    IF(EQ(VAR('smmeth'), txt('split')), [callProc('ssplit %s %s', [VAR('smrec'), VAR('sma1')])]),
    IF(EQ(VAR('smmeth'), txt('join')), [
      IF(NOT(EQ(VAR('smt1'), txt('L'))), [FAIL(txt('TypeError: join needs a list'))]),
      callProc('sjoin %s %s', [VAR('smrec'), VAR('sma1')])
    ]),
    IF(NOT(knownCond), [FAILB(JOIN(txt('AttributeError: str has no method '), VAR('smmeth')))])
  ];
  const strBranch = [
    addTo('MRStack', VAR('xa')), addTo('MMStack', VAR('lmeth')),
    setV('sma1', txt('')), setV('smt1', txt('S')), setV('sma2', txt('')), setV('smt2', txt('S')), setV('mcut', num(0)),
    IF(NOT(GT(argLo(), argHi())), [
      setV('sd', num(0)), setV('sk', argLo()),
      REPEATU(GT(VAR('sk'), argHi()), [
        IF(NOT(EQ(item('Kind', VAR('sk')), txt('S'))), [
          IF(OR(EQ(tokAt(VAR('sk')), txt('(')), EQ(tokAt(VAR('sk')), txt('['))), [chgV('sd', num(1))]),
          IF(OR(EQ(tokAt(VAR('sk')), txt(')')), EQ(tokAt(VAR('sk')), txt(']'))), [chgV('sd', num(-1))]),
          IF(AND(EQ(VAR('sd'), num(0)), AND(EQ(tokAt(VAR('sk')), txt(',')), EQ(VAR('mcut'), num(0)))), [setV('mcut', VAR('sk'))])
        ]),
        chgV('sk', num(1))
      ]),
      IFELSE(GT(VAR('mcut'), num(0)), [
        callProc('eval %s %s', [argLo(), SUB(VAR('mcut'), num(1))]),
        setV('sma1', VAR('ev')), setV('smt1', VAR('evtype')),
        callProc('eval %s %s', [ADD(VAR('mcut'), num(1)), argHi()]),
        setV('sma2', VAR('ev')), setV('smt2', VAR('evtype'))
      ], [
        callProc('eval %s %s', [argLo(), argHi()]),
        setV('sma1', VAR('ev')), setV('smt1', VAR('evtype'))
      ])
    ]),
    setV('smrec', item('MRStack', llen('MRStack'))),
    I('data_deleteoflist', { fields: B.LISTF('MRStack'), inputs: { INDEX: B.REP(llen('MRStack'), [4, '0']) } }),
    setV('smmeth', item('MMStack', llen('MMStack'))),
    I('data_deleteoflist', { fields: B.LISTF('MMStack'), inputs: { INDEX: B.REP(llen('MMStack'), [4, '0']) } }),
    ...dispatch
  ];
  const lmethSet = find(mc, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'lmeth');
  if (lmethSet.length !== 1) throw new Error('methodcall lmeth set = ' + lmethSet.length);
  spliceAfter(lmethSet[0], chain([
    IF(EQ(VAR('xb'), txt('S')), [ ...strBranch, STOPTHIS() ])
  ]));
  console.log('[P18] string methods installed');
});

// ---- P19: a string token whose text is "-"/"+"/"not" must not be read as an operator
//      (e.g. '-'.join(a)); guard the unary dispatch with the token kind
patch('P19 kind guards', () => {
  const evSet = inDef('eval %s %s');
  const kindIsS = () => EQ(item('Kind', argOf('lo')), txt('S'));
  const isTokLoTest = (x, vals) => {
    if (x.opcode !== 'operator_equals') return false;
    if (!vals.includes(x.inputs.OPERAND2 && x.inputs.OPERAND2[1] && x.inputs.OPERAND2[1][1])) return false;
    const l = x.inputs.OPERAND1 && x.inputs.OPERAND1[1];
    if (typeof l !== 'string') return false;
    const t = BL()[l];
    if (!t || t.opcode !== 'data_itemoflist' || t.fields.LIST[0] !== 'Tok') return false;
    const idx = t.inputs.INDEX && t.inputs.INDEX[1];
    if (typeof idx !== 'string') return false;
    const r = BL()[idx];
    return r && r.opcode === 'argument_reporter_string_number' && r.fields.VALUE[0] === 'lo';
  };
  let wrapped = 0; let seen = 0; let cand = 0;
  for (const id of [...evSet]) {
    const b = BL()[id];
    if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') continue;
    seen++;
    if (!b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') continue;
    const hits = [...reach(b.inputs.CONDITION[1])].filter((x) => isTokLoTest(BL()[x], ['-', '+', 'not']));
    if (!hits.length) continue;
    cand++;
    const oldCond = b.inputs.CONDITION[1];
    const w = AND(NOT(kindIsS()), oldCond);
    b.inputs.CONDITION = B.BOOL(w);
    BL()[oldCond].parent = w;
    wrapped++;
  }
  console.log('[P19] control_ifs=' + seen + ' candidates=' + cand);
  if (wrapped !== 2) throw new Error('kind guards wrapped ' + wrapped + ' (expected 2)');
  console.log('[P19] token-kind guards: ' + wrapped);
});

// ---- P20: chained method calls -- s.strip().lower().replace(' ', '_')
//      methodcall() recurses: evaluate the first segment, then re-dispatch with the
//      result pre-loaded as the receiver (mcpre flag).
patch('P20 method chains', () => {
  newVar('mccut', 0); newVar('mccut2', 0); newVar('mck', 0); newVar('mcdepth', 0); newVar('mcval', ''); newVar('mctype', ''); newVar('mcpre', 0);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const mcDef = defIdOf('methodcall %s %s');
  insertBeforeStmt(BL()[mcDef].next, [
    setV('mccut', num(0)), setV('mcdepth', num(0)), setV('mck', argOf('lo')),
    // a segment range may start at the ')' of the previous call: skip that token
    IF(EQ(tokAt(argOf('lo')), txt(')')), [chgV('mck', num(1))]),
    REPEATU(GT(VAR('mck'), argOf('hi')), [
      IF(EQ(tokAt(VAR('mck')), txt('(')), [chgV('mcdepth', num(1))]),
      IF(EQ(tokAt(VAR('mck')), txt(')')), [
        chgV('mcdepth', num(-1)),
        // only a ')' that is NOT the end of the range starts a new chain segment
        IF(AND(EQ(VAR('mcdepth'), num(0)), AND(LT(VAR('mck'), argOf('hi')), AND(EQ(VAR('mccut'), num(0)), EQ(tokAt(ADD(VAR('mck'), num(1))), txt('.'))))),
          [setV('mccut', VAR('mck'))])
      ]),
      chgV('mck', num(1))
    ]),
    IF(GT(VAR('mccut'), num(0)), [
      // the recursive call reuses mccut, so keep our own copy
      setV('mccut2', VAR('mccut')),
      callProc('methodcall %s %s', [argOf('lo'), VAR('mccut2')]),
      setV('mcval', VAR('ev')), setV('mctype', VAR('evtype')), setV('mcpre', num(1)),
      callProc('methodcall %s %s', [VAR('mccut2'), argOf('hi')]),
      setV('mcpre', num(0)),
      STOPTHIS()
    ])
  ]);
  // receiver: either the token at lo, or the value the previous segment produced
  const recvEval = find(reach(mcDef), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s'
    && Object.values(b.inputs).every((v) => typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'argument_reporter_string_number' && BL()[v[1]].fields.VALUE[0] === 'lo'));
  if (recvEval.length !== 1) throw new Error('methodcall receiver eval = ' + recvEval.length);
  replaceStmt(recvEval[0], IFELSE(EQ(VAR('mcpre'), num(1)),
    [setV('xa', VAR('mcval')), setV('xb', VAR('mctype'))],
    [callProc('eval %s %s', [argOf('lo'), argOf('lo')])]));
  console.log('[P20] method chains installed');
});

// ---- P21: f-strings -- f"text {expr} text"
patch('P21 f-strings', () => {
  newVar('fq', ''); newVar('fbody', ''); newVar('fsrc', ''); newVar('fo', ''); newVar('fi', 0); newVar('fj', 0); newVar('fc2', ''); newVar('fexpr', '');
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const repItem = (list, idx, val) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(val, [4, '0']) } });

  // (a) tokenizer: an identifier "f" directly followed by a quote becomes an f-string token
  {
    const tk = defIdOf('tokenize %s');
    const kindAppend = find(reach(tk), (b) => b.opcode === 'data_addtolist' && b.fields.LIST[0] === 'Kind'
      && b.inputs.ITEM && Array.isArray(b.inputs.ITEM[1]) && b.inputs.ITEM[1][1] === 'I');
    if (kindAppend.length !== 1) throw new Error('tokenize identifier append = ' + kindAppend.length);
    const ch = () => letterOf(VAR('ep'), argOf('source'));
    spliceAfter(kindAppend[0], chain([
      IF(AND(EQ(VAR('et'), txt('f')),
             OR(EQ(ch(), VAR('dq')), EQ(ch(), txt("'")))), [
        setV('fq', ch()),
        setV('fbody', txt('')), chgV('ep', num(1)),
        REPEATU(OR(GT(VAR('ep'), lenOf(argOf('source'))), EQ(ch(), VAR('fq'))), [
          IF(EQ(ch(), VAR('slash')), [chgV('ep', num(1))]),
          setV('fbody', JOIN(VAR('fbody'), ch())),
          chgV('ep', num(1))
        ]),
        IF(GT(VAR('ep'), lenOf(argOf('source'))), [FAIL(txt('SyntaxError: unclosed string'))]),
        chgV('ep', num(1)),
        repItem('Tok', llen('Tok'), VAR('fbody')),
        repItem('Kind', llen('Kind'), txt('F'))
      ])
    ]));
  }

  // (b) fstr idx : expand the token at idx into a plain string
  const fsProc = newProc('fstr %s', ['idx']);
  attachBody(fsProc.defId, [
    setV('fsrc', tokAt(argOf('idx'))),
    setV('fo', txt('')), setV('fi', num(1)),
    REPEATU(GT(VAR('fi'), lenOf(VAR('fsrc'))), [
      setV('fc2', letterOf(VAR('fi'), VAR('fsrc'))),
      IFELSE(EQ(VAR('fc2'), txt('{')), [
        IFELSE(EQ(letterOf(ADD(VAR('fi'), num(1)), VAR('fsrc')), txt('{')), [
          setV('fo', JOIN(VAR('fo'), txt('{'))),
          chgV('fi', num(1))
        ], [
          setV('fj', ADD(VAR('fi'), num(1))),
          REPEATU(OR(GT(VAR('fj'), lenOf(VAR('fsrc'))), EQ(letterOf(VAR('fj'), VAR('fsrc')), txt('}'))), [chgV('fj', num(1))]),
          IF(GT(VAR('fj'), lenOf(VAR('fsrc'))), [FAIL(txt('SyntaxError: f-string expects }')), STOPTHIS()]),
          callProc('substr %s %s %s', [VAR('fsrc'), ADD(VAR('fi'), num(1)), SUB(VAR('fj'), num(1))]),
          setV('fexpr', VAR('ev')),
          callProc('tokenize %s', [VAR('fexpr')]),
          callProc('eval %s %s', [num(1), llen('Tok')]),
          callProc('strval %s %s', [VAR('ev'), VAR('evtype')]),
          setV('fo', JOIN(VAR('fo'), VAR('ev'))),
          setV('fi', VAR('fj'))
        ])
      ], [
        setV('fo', JOIN(VAR('fo'), VAR('fc2')))
      ]),
      chgV('fi', num(1))
    ]),
    setV('ev', VAR('fo')), setV('evtype', txt('S'))
  ]);

  // (c) atom: an f-string token is expanded, then the line is re-tokenized
  {
    const atomSet = inDef('atom %s');
    const notNS = find(atomSet, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_and'
      && [...reach(b.inputs.CONDITION[1])].some((id) => BL()[id].opcode === 'operator_equals'
        && BL()[id].inputs.OPERAND2 && BL()[id].inputs.OPERAND2[1] && BL()[id].inputs.OPERAND2[1][1] === 'S'));
    if (notNS.length !== 1) throw new Error('atom type guard = ' + notNS.length);
    const oldCond = BL()[notNS[0]].inputs.CONDITION[1];
    const w = AND(NOT(EQ(VAR('evtype'), txt('F'))), oldCond);
    BL()[notNS[0]].inputs.CONDITION = B.BOOL(w);
    BL()[oldCond].parent = w;
    insertBeforeStmt(notNS[0], [
      IF(EQ(VAR('evtype'), txt('F')), [
        callProc('fstr %s', [argOf('idx')]),
        callProc('tokenize %s', [item('Code', VAR('pc'))])
      ])
    ]);
  }
  console.log('[P21] f-strings installed');
});

// ---- P23: import math + the math module (math.floor(3.7), math.sqrt(x), ...)
patch('P23 math module', () => {
  for (const v of ['mav', 'mav2', 'mat2', 'hasmath']) newVar(v, 0);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const MATHOP = (op, x) => I('operator_mathop', { fields: { OPERATOR: [op, null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const FNS = ['floor', 'ceil', 'sqrt', 'fabs', 'exp', 'log', 'log10', 'sin', 'cos', 'tan', 'trunc', 'pow', 'fmod'];

  // (a) "import math" is accepted; other modules fail loudly
  {
    const ex = inDef('execute');
    const pendingIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'pending');
    if (pendingIf.length !== 1) throw new Error('execute pending guard = ' + pendingIf.length);
    insertBeforeStmt(pendingIf[0], [
      IF(EQ(VAR('head'), txt('import')), [
        IF(NOT(EQ(tokAt(num(2)), txt('math'))), [FAILB(JOIN(txt('ImportError: no module named '), tokAt(num(2))))]),
        setV('hasmath', num(1)),
        setV('pending', num(1))
      ])
    ]);
  }

  // (b) math.<fn>(...) inside methodcall (eval's shape check already routes it there)
  {
    const mc = defIdOf('methodcall %s %s');
    const fnTok = () => tokAt(ADD(argOf('lo'), num(2)));
    const argLo = () => ADD(argOf('lo'), num(4));
    const argHi = () => SUB(argOf('hi'), num(1));
    const one = () => [
      callProc('eval %s %s', [argLo(), argHi()]),
      setV('mav', VAR('ev')), setV('mat2', VAR('evtype'))
    ];
    const two = () => [
      setV('mcut', num(0)), setV('sd', num(0)), setV('sk', argLo()),
      REPEATU(GT(VAR('sk'), argHi()), [
        IF(OR(EQ(tokAt(VAR('sk')), txt('(')), EQ(tokAt(VAR('sk')), txt('['))), [chgV('sd', num(1))]),
        IF(OR(EQ(tokAt(VAR('sk')), txt(')')), EQ(tokAt(VAR('sk')), txt(']'))), [chgV('sd', num(-1))]),
        IF(AND(EQ(VAR('sd'), num(0)), AND(EQ(tokAt(VAR('sk')), txt(',')), EQ(VAR('mcut'), num(0)))), [setV('mcut', VAR('sk'))]),
        chgV('sk', num(1))
      ]),
      callProc('eval %s %s', [argLo(), SUB(VAR('mcut'), num(1))]),
      setV('mav', VAR('ev')), setV('mat2', VAR('evtype')),
      callProc('eval %s %s', [ADD(VAR('mcut'), num(1)), argHi()]),
      setV('mav2', VAR('ev'))
    ];
    const simple = (op) => [...one(), setV('ev', MATHOP(op, VAR('mav'))), setV('evtype', txt('N'))];
    let knownMath = null;
    for (const f of FNS) { const e = EQ(fnTok(), txt(f)); knownMath = knownMath ? OR(knownMath, e) : e; }
    const mathBranch = [
      IF(EQ(fnTok(), txt('floor')), simple('floor')),
      IF(EQ(fnTok(), txt('ceil')), simple('ceiling')),
      IF(EQ(fnTok(), txt('fabs')), simple('abs')),
      IF(EQ(fnTok(), txt('exp')), simple('e ^')),
      IF(OR(EQ(fnTok(), txt('log')), EQ(fnTok(), txt('log10'))), simple('ln')),
      IF(EQ(fnTok(), txt('sin')), simple('sin')),
      IF(EQ(fnTok(), txt('cos')), simple('cos')),
      IF(EQ(fnTok(), txt('tan')), simple('tan')),
      IF(EQ(fnTok(), txt('sqrt')), [
        ...one(),
        IF(LT(VAR('mav'), num(0)), [FAIL(txt('ValueError: math domain error'))]),
        setV('ev', MATHOP('sqrt', VAR('mav'))), setV('evtype', txt('N'))
      ]),
      IF(EQ(fnTok(), txt('trunc')), [
        ...one(),
        IFELSE(LT(VAR('mav'), num(0)), [setV('ev', MATHOP('ceiling', VAR('mav')))], [setV('ev', MATHOP('floor', VAR('mav')))]),
        setV('evtype', txt('N'))
      ]),
      IF(EQ(fnTok(), txt('pow')), [
        ...two(),
        setV('ev', MATHOP('e ^', MUL(VAR('mav2'), MATHOP('ln', VAR('mav'))))),
        setV('evtype', txt('N'))
      ]),
      IF(EQ(fnTok(), txt('fmod')), [
        ...two(),
        setV('ev', MOD(VAR('mav'), VAR('mav2'))), setV('evtype', txt('N'))
      ]),
      IF(NOT(knownMath), [FAILB(JOIN(txt('AttributeError: math has no '), fnTok()))])
    ];
    insertBeforeStmt(BL()[mc].next, [
      IF(EQ(tokAt(argOf('lo')), txt('math')), [
        IF(EQ(VAR('hasmath'), num(0)), [FAIL(txt('NameError: name math is not defined')), STOPTHIS()]),
        ...mathBranch, STOPTHIS()
      ])
    ]);
  }

  // (c) reset the flag each run
  {
    const runDef = (() => { for (const id of allIds()) { const b = BL()[id]; if (b.opcode === 'event_whenbroadcastreceived' && b.fields.BROADCAST_OPTION && b.fields.BROADCAST_OPTION[0] === 'RUN') return id; } throw new Error('RUN hat not found'); })();
    spliceAfter(runDef, chain([setV('hasmath', num(0))]));
  }
  console.log('[P23] math module installed');
});

// ---- P24: %-formatting -- "%d-%s" % (1, "a")
patch('P24 percent format', () => {
  for (const v of ['pvout', 'pvi', 'pvv', 'pvt', 'pvspec', 'pvc', 'pvlo', 'pvhi', 'pvj', 'pvk']) newVar(v, 0);
  for (const l of ['PVal', 'PTyp', 'PComm']) B.addList(IT, l, []);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });

  const pf = newProc('pctfmt %s %s %s', ['fmt', 'lo', 'hi']);
  attachBody(pf.defId, [
    clearL('PVal'), clearL('PTyp'), clearL('PComm'),
    IFELSE(AND(EQ(tokAt(argOf('lo')), txt('(')), EQ(tokAt(argOf('hi')), txt(')'))), [
      // split the parenthesised value list on top-level commas
      setV('fd', num(0)), setV('fk', ADD(argOf('lo'), num(1))),
      REPEATU(GT(VAR('fk'), SUB(argOf('hi'), num(1))), [
        IF(OR(EQ(tokAt(VAR('fk')), txt('(')), EQ(tokAt(VAR('fk')), txt('['))), [chgV('fd', num(1))]),
        IF(OR(EQ(tokAt(VAR('fk')), txt(')')), EQ(tokAt(VAR('fk')), txt(']'))), [chgV('fd', num(-1))]),
        IF(AND(EQ(VAR('fd'), num(0)), EQ(tokAt(VAR('fk')), txt(','))), [addTo('PComm', VAR('fk'))]),
        chgV('fk', num(1))
      ]),
      addTo('PComm', argOf('hi')),   // sentinel: one past the last value
      setV('pvj', num(1)), setV('pvlo', ADD(argOf('lo'), num(1))),
      REPEATU(GT(VAR('pvj'), llen('PComm')), [
        setV('pvhi', SUB(item('PComm', VAR('pvj')), num(1))),
        IF(NOT(GT(VAR('pvlo'), VAR('pvhi'))), [
          callProc('eval %s %s', [VAR('pvlo'), VAR('pvhi')]),
          addTo('PVal', VAR('ev')), addTo('PTyp', VAR('evtype'))
        ]),
        setV('pvlo', ADD(item('PComm', VAR('pvj')), num(1))),
        chgV('pvj', num(1))
      ])
    ], [
      callProc('eval %s %s', [argOf('lo'), argOf('hi')]),
      addTo('PVal', VAR('ev')), addTo('PTyp', VAR('evtype'))
    ]),
    // walk the format string
    setV('pvout', txt('')), setV('pvi', num(1)), setV('pvk', num(1)),
    REPEATU(GT(VAR('pvi'), lenOf(argOf('fmt'))), [
      setV('pvc', letterOf(VAR('pvi'), argOf('fmt'))),
      IFELSE(EQ(VAR('pvc'), txt('%')), [
        setV('pvspec', letterOf(ADD(VAR('pvi'), num(1)), argOf('fmt'))),
        IFELSE(EQ(VAR('pvspec'), txt('%')), [
          setV('pvout', JOIN(VAR('pvout'), txt('%')))
        ], [
          IF(GT(VAR('pvk'), llen('PVal')), [FAIL(txt('TypeError: not enough arguments for format string'))]),
          setV('pvv', item('PVal', VAR('pvk'))), setV('pvt', item('PTyp', VAR('pvk'))), chgV('pvk', num(1)),
          IFELSE(EQ(VAR('pvspec'), txt('d')), [
            IF(NOT(EQ(VAR('pvt'), txt('N'))), [FAIL(txt('TypeError: %d format requires a number'))]),
            callProc('strval %s %s', [FLOOR(VAR('pvv')), txt('N')]),
            setV('pvout', JOIN(VAR('pvout'), VAR('ev')))
          ], [
            callProc('strval %s %s', [VAR('pvv'), VAR('pvt')]),
            setV('pvout', JOIN(VAR('pvout'), VAR('ev')))
          ])
        ]),
        chgV('pvi', num(1))
      ], [
        setV('pvout', JOIN(VAR('pvout'), VAR('pvc')))
      ]),
      chgV('pvi', num(1))
    ]),
    setV('ev', VAR('pvout')), setV('evtype', txt('S'))
  ]);

  // rightside: "string" % ... never reaches the numeric % path
  {
    const rs = defIdOf('rightside %s %s %s %s %s');
    const firstEval = find(reach(rs), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s'
      && Object.values(b.inputs).every((v) => typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'argument_reporter_string_number'));
    if (!firstEval.length) throw new Error('rightside first eval not found');
    firstEval.sort((a, b) => (BL()[a].parent === BL()[b].parent ? 0 : 1));
    // the FIRST statement of rightside is that eval
    const bodyIf = find(reach(rs), (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'error');
    if (!bodyIf.length) throw new Error('rightside body if not found');
    insertBeforeStmt(BL()[rs].next, [
      IF(AND(EQ(argOf('op'), txt('%')), EQ(argOf('lefttype'), txt('S'))), [
        callProc('pctfmt %s %s %s', [argOf('leftval'), argOf('lo'), argOf('hi')]),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ]);
  }
  console.log('[P24] percent formatting installed');
});

// ---- P25: bitwise operators -- & | ^ << >> (non-negative integers)
patch('P25 bitwise ops', () => {
  for (const v of ['bt_r', 'bt_p', 'bt_a', 'bt_b', 'bt_ab', 'bt_bb', 'bt_bit', 'bti', 'evtsave']) newVar(v, 0);
  const tokAt = (x) => item('Tok', x);
  const bitOpNames = ['&', '|', '^', '<<', '>>'];

  // (a) tokenizer: recognise << and >>
  {
    const tk = defIdOf('tokenize %s');
    // the two-char merge rule compares ec/en against "=", "!", "/", "*" ...
    const lit = (id) => (BL()[id].opcode === 'operator_equals' && BL()[id].inputs.OPERAND2 && BL()[id].inputs.OPERAND2[1])
      ? BL()[id].inputs.OPERAND2[1][1] : null;
    const mergeIf = find(reach(tk), (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].filter((id) => lit(id) === '*').length >= 2
      && [...reach(b.inputs.CONDITION[1])].some((id) => lit(id) === '!'));
    if (mergeIf.length !== 1) throw new Error('tokenize merge rule = ' + mergeIf.length);
    const oc = BL()[mergeIf[0]].inputs.CONDITION[1];
    const w = OR(oc, OR(AND(EQ(VAR('ec'), txt('<')), EQ(VAR('en'), txt('<'))),
                       AND(EQ(VAR('ec'), txt('>')), EQ(VAR('en'), txt('>')))));
    BL()[mergeIf[0]].inputs.CONDITION = B.BOOL(w);
    BL()[oc].parent = w;
  }

  // (b) rank: rebuild with the Python precedence ladder
  {
    const rk = defIdOf('rank %s');
    const RANKS = [
      [['or'], 1], [['and'], 2],
      [['==', '!=', '<', '>', '<=', '>=', 'in', 'notin', 'is', 'isnot'], 3],
      [['|'], 4], [['^'], 5], [['&'], 6], [['<<', '>>'], 7],
      [['+', '-'], 8], [['*', '/', '//', '%'], 9], [['**'], 10],
    ];
    const body = [setV('erank', num(0))];
    for (const [ops, r] of RANKS) {
      let cond = null;
      for (const o of ops) { const e = EQ(argOf('op'), txt(o)); cond = cond ? OR(cond, e) : e; }
      body.push(IF(cond, [setV('erank', num(r))]));
    }
    const old = BL()[rk].next;
    if (old) BL()[old].parent = null;
    attachBody(rk, body);
  }

  // (c) bitop op a b -> ev
  const bo = newProc('bitop %s %s %s', ['op', 'a', 'b']);
  attachBody(bo.defId, [
    setV('bt_a', argOf('a')), setV('bt_b', argOf('b')), setV('bt_r', num(0)), setV('bt_p', num(1)), setV('bti', num(0)),
    REPEATU(OR(AND(NOT(GT(VAR('bt_a'), num(0))), NOT(GT(VAR('bt_b'), num(0)))), GT(VAR('bti'), num(62))), [
      chgV('bti', num(1)),
      setV('bt_ab', MOD(VAR('bt_a'), num(2))),
      setV('bt_bb', MOD(VAR('bt_b'), num(2))),
      setV('bt_bit', num(0)),
      IF(EQ(argOf('op'), txt('&')), [setV('bt_bit', MUL(VAR('bt_ab'), VAR('bt_bb')))]),
      IF(EQ(argOf('op'), txt('|')), [setV('bt_bit', SUB(ADD(VAR('bt_ab'), VAR('bt_bb')), MUL(VAR('bt_ab'), VAR('bt_bb'))))]),
      IF(EQ(argOf('op'), txt('^')), [setV('bt_bit', MOD(ADD(VAR('bt_ab'), VAR('bt_bb')), num(2)))]),
      setV('bt_r', ADD(VAR('bt_r'), MUL(VAR('bt_bit'), VAR('bt_p')))),
      setV('bt_a', I('operator_mathop', { fields: { OPERATOR: ['floor', null] }, inputs: { NUM: B.REP(DIV(VAR('bt_a'), num(2)), [4, '0']) } })),
      setV('bt_b', I('operator_mathop', { fields: { OPERATOR: ['floor', null] }, inputs: { NUM: B.REP(DIV(VAR('bt_b'), num(2)), [4, '0']) } })),
      setV('bt_p', MUL(VAR('bt_p'), num(2)))
    ]),
    setV('ev', VAR('bt_r')), setV('evtype', txt('N'))
  ]);
  // (d) rightside: bitwise branches
  {
    const rs = defIdOf('rightside %s %s %s %s %s');
    const powIf = find(reach(rs), (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1] && BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1] === '**');
    if (powIf.length !== 1) throw new Error('rightside ** branch = ' + powIf.length);
    const intCheck = () => [
      IF(OR(NOT(EQ(argOf('lefttype'), txt('N'))), NOT(EQ(VAR('evtype'), txt('N')))), [FAIL(txt('TypeError: bitwise requires integers'))]),
      IF(OR(LT(argOf('leftval'), num(0)), LT(VAR('ev'), num(0))), [FAIL(txt('ValueError: bitwise needs non-negative integers'))]),
      IF(OR(NOT(EQ(MOD(argOf('leftval'), num(1)), num(0))), NOT(EQ(MOD(VAR('ev'), num(1)), num(0)))), [FAIL(txt('TypeError: bitwise requires integers'))])
    ];
    const floorDiv2 = (x) => I('operator_mathop', { fields: { OPERATOR: ['floor', null] }, inputs: { NUM: B.REP(DIV(x, num(2)), [4, '0']) } });
    const bitFis = [
      IF(OR(OR(EQ(argOf('op'), txt('&')), EQ(argOf('op'), txt('|'))), EQ(argOf('op'), txt('^'))), [
        ...intCheck(),
        callProc('bitop %s %s %s', [argOf('op'), argOf('leftval'), VAR('ev')]),
        setV('evtype', txt('N'))
      ]),
      IF(OR(EQ(argOf('op'), txt('<<')), EQ(argOf('op'), txt('>>'))), [
        ...intCheck(),
        setV('bt_r', argOf('leftval')), setV('bt_b', VAR('ev')), setV('bti', num(0)),
        REPEATU(OR(NOT(LT(VAR('bti'), VAR('bt_b'))), GT(VAR('bt_b'), num(62))), [
          IFELSE(EQ(argOf('op'), txt('<<')),
            [setV('bt_r', MUL(VAR('bt_r'), num(2)))],
            [setV('bt_r', floorDiv2(VAR('bt_r')))]),
          chgV('bti', num(1))
        ]),
        setV('ev', VAR('bt_r')), setV('evtype', txt('N'))
      ])
    ];
    spliceAfter(powIf[0], chain(bitFis));
    const ok = [...reach(rs)].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'bitop %s %s %s');
    if (!ok) throw new Error('bitop call not reachable in rightside');
  }

  // (e) "and"/"or" must not turn a bool result into a number (P10 normalises B->N)
  {
    const rs = defIdOf('rightside %s %s %s %s %s');
    const lt2Set = find(reach(rs), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'lt2'
      && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]].opcode === 'argument_reporter_string_number');
    if (lt2Set.length !== 1) throw new Error('rightside lt2 normalisation = ' + lt2Set.length);
    insertBeforeStmt(lt2Set[0], [setV('evtsave', VAR('evtype'))]);
    let last = BL()[rs].next; let g = 0;
    while (BL()[last].next && g++ < 500) last = BL()[last].next;
    spliceAfter(last, chain([
      IF(OR(EQ(argOf('op'), txt('and')), EQ(argOf('op'), txt('or'))), [setV('evtype', VAR('evtsave'))])
    ]));
  }
  console.log('[P25] bitwise installed');
});

// ---- P26: list comprehensions -- [expr for v in iterable if cond]
patch('P26 comprehensions', () => {
  for (const v of ['cfor', 'cif', 'cdep', 'ck', 'cilo', 'cihi', 'cacc', 'cv', 'cstop', 'cstep',
                   'clist', 'cltyp', 'cqidx', 'cn', 'cev', 'cet', 'cok', 'cb1', 'cb2']) newVar(v, 0);
  B.addList(IT, 'CComm', []);
  const tokAt = (x) => item('Tok', x);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const enc = (acc, tv, vv) => JOIN(JOIN(JOIN(acc, VAR('lsep')), tv), vv);
  const commScan = (fromExpr, toExpr) => [
    clearL('CComm'), setV('cdep', num(0)), setV('ck', fromExpr),
    REPEATU(GT(VAR('ck'), toExpr), [
      IF(OR(EQ(tokAt(VAR('ck')), txt('(')), EQ(tokAt(VAR('ck')), txt('['))), [chgV('cdep', num(1))]),
      IF(OR(EQ(tokAt(VAR('ck')), txt(')')), EQ(tokAt(VAR('ck')), txt(']'))), [chgV('cdep', num(-1))]),
      IF(AND(EQ(VAR('cdep'), num(0)), EQ(tokAt(VAR('ck')), txt(','))), [addTo('CComm', VAR('ck'))]),
      chgV('ck', num(1))
    ])
  ];
  // guarded body: bind already done, evaluate the filter (if any) then the body, append
  const guarded = () => [
    setV('cok', num(1)),
    IF(GT(VAR('cif'), num(0)), [
      callProc('eval %s %s', [ADD(VAR('cif'), num(1)), argOf('hi')]),
      callProc('truth %s %s', [VAR('ev'), VAR('evtype')]),
      IF(EQ(VAR('truthv'), num(0)), [setV('cok', num(0))])
    ]),
    IF(EQ(VAR('cok'), num(1)), [
      callProc('eval %s %s', [argOf('lo'), SUB(VAR('cfor'), num(1))]),
      setV('cacc', enc(VAR('cacc'), VAR('evtype'), VAR('ev')))
    ])
  ];

  const cl = newProc('complist %s %s', ['lo', 'hi']);
  attachBody(cl.defId, [
    // split "[body for v in iterable (if cond)]"
    setV('cfor', num(0)), setV('cif', num(0)), setV('cdep', num(0)), setV('ck', argOf('lo')),
    REPEATU(GT(VAR('ck'), argOf('hi')), [
      IF(OR(EQ(tokAt(VAR('ck')), txt('(')), EQ(tokAt(VAR('ck')), txt('['))), [chgV('cdep', num(1))]),
      IF(OR(EQ(tokAt(VAR('ck')), txt(')')), EQ(tokAt(VAR('ck')), txt(']'))), [chgV('cdep', num(-1))]),
      IF(AND(EQ(VAR('cdep'), num(0)), AND(EQ(tokAt(VAR('ck')), txt('for')), EQ(VAR('cfor'), num(0)))), [setV('cfor', VAR('ck'))]),
      IF(AND(EQ(VAR('cdep'), num(0)), AND(EQ(tokAt(VAR('ck')), txt('if')), AND(GT(VAR('cfor'), num(0)), EQ(VAR('cif'), num(0))))), [setV('cif', VAR('ck'))]),
      chgV('ck', num(1))
    ]),
    IF(EQ(VAR('cfor'), num(0)), [FAIL(txt('SyntaxError: comprehension needs for')), STOPTHIS()]),
    IF(NOT(AND(EQ(item('Kind', ADD(VAR('cfor'), num(1))), txt('I')), EQ(tokAt(ADD(VAR('cfor'), num(2))), txt('in')))),
      [FAIL(txt('SyntaxError: for <name> in ...')), STOPTHIS()]),
    setV('cilo', ADD(VAR('cfor'), num(3))),
    IFELSE(GT(VAR('cif'), num(0)), [setV('cihi', SUB(VAR('cif'), num(1)))], [setV('cihi', argOf('hi'))]),
    setV('cacc', txt('')),
    IFELSE(AND(EQ(tokAt(VAR('cilo')), txt('range')), AND(EQ(tokAt(ADD(VAR('cilo'), num(1))), txt('(')), EQ(tokAt(VAR('cihi')), txt(')')))), [
      // range(start, stop[, step])
      ...commScan(ADD(VAR('cilo'), num(2)), SUB(VAR('cihi'), num(1))),
      setV('cn', llen('CComm')),
      IFELSE(EQ(VAR('cn'), num(0)), [
        callProc('eval %s %s', [ADD(VAR('cilo'), num(2)), SUB(VAR('cihi'), num(1))]),
        setV('cv', num(0)), setV('cstop', VAR('ev')), setV('cstep', num(1))
      ], [
        callProc('eval %s %s', [ADD(VAR('cilo'), num(2)), SUB(item('CComm', num(1)), num(1))]),
        setV('cv', VAR('ev')),
        IFELSE(EQ(VAR('cn'), num(1)), [
          callProc('eval %s %s', [ADD(item('CComm', num(1)), num(1)), SUB(VAR('cihi'), num(1))]),
          setV('cstop', VAR('ev')), setV('cstep', num(1))
        ], [
          callProc('eval %s %s', [ADD(item('CComm', num(1)), num(1)), SUB(item('CComm', num(2)), num(1))]),
          setV('cstop', VAR('ev')),
          callProc('eval %s %s', [ADD(item('CComm', num(2)), num(1)), SUB(VAR('cihi'), num(1))]),
          setV('cstep', VAR('ev'))
        ])
      ]),
      IF(EQ(VAR('cstep'), num(0)), [FAIL(txt('ValueError: range step is zero')), STOPTHIS()]),
      REPEATU(OR(AND(GT(VAR('cstep'), num(0)), NOT(LT(VAR('cv'), VAR('cstop')))),
                 AND(LT(VAR('cstep'), num(0)), NOT(GT(VAR('cv'), VAR('cstop'))))), [
        callProc('assign %s %s %s', [tokAt(ADD(VAR('cfor'), num(1))), VAR('cv'), txt('N')]),
        ...guarded(),
        chgV('cv', VAR('cstep'))
      ])
    ], [
      // any other iterable: evaluate it once, then walk its elements (or characters)
      callProc('eval %s %s', [VAR('cilo'), VAR('cihi')]),
      setV('clist', VAR('ev')), setV('cltyp', VAR('evtype')),
      IF(NOT(OR(EQ(VAR('cltyp'), txt('L')), EQ(VAR('cltyp'), txt('S')))), [FAIL(txt('TypeError: comprehension needs a list or string')), STOPTHIS()]),
      IFELSE(EQ(VAR('cltyp'), txt('L')), [
        callProc('listlen %s', [VAR('clist')]),
        setV('cn', VAR('ev')), setV('cqidx', num(1)),
        REPEATU(GT(VAR('cqidx'), VAR('cn')), [
          callProc('listitem %s %s', [VAR('clist'), VAR('cqidx')]),
          setV('cev', VAR('ev')), setV('cet', VAR('evtype')),
          callProc('assign %s %s %s', [tokAt(ADD(VAR('cfor'), num(1))), VAR('cev'), VAR('cet')]),
          ...guarded(),
          chgV('cqidx', num(1))
        ])
      ], [
        setV('cn', lenOf(VAR('clist'))), setV('cqidx', num(1)),
        REPEATU(GT(VAR('cqidx'), VAR('cn')), [
          callProc('assign %s %s %s', [tokAt(ADD(VAR('cfor'), num(1))), letterOf(VAR('cqidx'), VAR('clist')), txt('S')]),
          ...guarded(),
          chgV('cqidx', num(1))
        ])
      ])
    ]),
    setV('ev', VAR('cacc')), setV('evtype', txt('L'))
  ]);

  // listlit: a top-level "for" inside the brackets means a comprehension
  {
    const ll = defIdOf('listlit %s %s');
    insertBeforeStmt(BL()[ll].next, [
      setV('cfor', num(0)), setV('cdep', num(0)), setV('ck', argOf('lo')),
      REPEATU(GT(VAR('ck'), argOf('hi')), [
        IF(OR(EQ(tokAt(VAR('ck')), txt('(')), EQ(tokAt(VAR('ck')), txt('['))), [chgV('cdep', num(1))]),
        IF(OR(EQ(tokAt(VAR('ck')), txt(')')), EQ(tokAt(VAR('ck')), txt(']'))), [chgV('cdep', num(-1))]),
        IF(AND(EQ(VAR('cdep'), num(0)), AND(EQ(tokAt(VAR('ck')), txt('for')), EQ(VAR('cfor'), num(0)))), [setV('cfor', VAR('ck'))]),
        chgV('ck', num(1))
      ]),
      IF(GT(VAR('cfor'), num(0)), [
        callProc('complist %s %s', [argOf('lo'), argOf('hi')]),
        STOPTHIS()
      ])
    ]);
  }
  console.log('[P26] comprehensions installed');
});

// ---- P27: float repr -- "/" and float operands keep a decimal point (CPython style)
patch('P27 float repr', () => {
  newVar('fv', '');
  const hasDot = (x) => I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('.'), [10, '']) } });
  // mkfloat v : make sure the text has a decimal point
  const mk = newProc('mkfloat %s', ['v']);
  attachBody(mk.defId, [
    IFELSE(hasDot(argOf('v')), [setV('ev', argOf('v'))], [setV('ev', JOIN(argOf('v'), txt('.0')))]),
    setV('evtype', txt('N'))
  ]);

  const rs = defIdOf('rightside %s %s %s %s %s');
  const all = [...reach(rs)];
  const isSetEv = (id) => BL()[id].opcode === 'data_setvariableto' && BL()[id].fields.VARIABLE[0] === 'ev';
  // (a) "/" always produces a float
  const divSet = all.filter((id) => isSetEv(id) && BL()[id].inputs.VALUE && BL()[id].inputs.VALUE[1] === undefined);
  const divAssign = all.filter((id) => isSetEv(id) && typeof BL()[id].inputs.VALUE[1] === 'string'
    && BL()[BL()[id].inputs.VALUE[1]].opcode === 'operator_divide');
  let nDiv = 0;
  for (const id of divAssign) {
    // the division branch assigns ev = leftval / ev ; make it a float afterwards
    spliceAfter(id, chain([callProc('mkfloat %s', [VAR('ev')])]));
    nDiv++;
  }
  // (b) other arithmetic keeps float-ness when either side is a float
  const arithIf = all.filter((id) => BL()[id].opcode === 'control_if' && BL()[id].inputs.CONDITION && typeof BL()[id].inputs.CONDITION[1] === 'string'
    && [...reach(BL()[id].inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && BL()[x].inputs.OPERAND2 && BL()[x].inputs.OPERAND2[1] && BL()[x].inputs.OPERAND2[1][1] === '-')
    && [...reach(BL()[id].inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && BL()[x].inputs.OPERAND2 && BL()[x].inputs.OPERAND2[1] && BL()[x].inputs.OPERAND2[1][1] === '%'));
  let nArith = 0;
  for (const id of arithIf) {
    const ops = ['-', '*', '/', '//', '%'];
    let cond = null;
    for (const o of ops) { const e = EQ(argOf('op'), txt(o)); cond = cond ? OR(cond, e) : e; }
    spliceAfter(id, chain([
      IF(AND(cond, OR(hasDot(argOf('leftval')), hasDot(VAR('ev')))), [callProc('mkfloat %s', [VAR('ev')])])
    ]));
    nArith++;
  }
  // (c) "+" of two floats (and ** ) stay floats
  const plusIf = all.filter((id) => BL()[id].opcode === 'control_if' && BL()[id].inputs.CONDITION && typeof BL()[id].inputs.CONDITION[1] === 'string'
    && BL()[BL()[id].inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[BL()[id].inputs.CONDITION[1]].inputs.OPERAND2 && BL()[BL()[id].inputs.CONDITION[1]].inputs.OPERAND2[1]
    && BL()[BL()[id].inputs.CONDITION[1]].inputs.OPERAND2[1][1] === '+');
  let nPlus = 0;
  for (const id of plusIf) {
    spliceAfter(id, chain([
      IF(OR(hasDot(argOf('leftval')), hasDot(VAR('ev'))), [callProc('mkfloat %s', [VAR('ev')])])
    ]));
    nPlus++;
  }
  const powIf = all.filter((id) => BL()[id].opcode === 'control_if' && BL()[id].inputs.CONDITION && typeof BL()[id].inputs.CONDITION[1] === 'string'
    && BL()[BL()[id].inputs.CONDITION[1]].opcode === 'operator_equals'
    && BL()[BL()[id].inputs.CONDITION[1]].inputs.OPERAND2 && BL()[BL()[id].inputs.CONDITION[1]].inputs.OPERAND2[1]
    && BL()[BL()[id].inputs.CONDITION[1]].inputs.OPERAND2[1][1] === '**');
  for (const id of powIf) {
    const nx = BL()[id].next;
    BL()[id].next = null;
    spliceAfter(id, chain([
      IF(OR(hasDot(argOf('leftval')), hasDot(VAR('ev'))), [callProc('mkfloat %s', [VAR('ev')])])
    ]));
    if (nx) { let t = id; let g = 0; while (BL()[t].next && g++ < 200) t = BL()[t].next; BL()[t].next = nx; BL()[nx].parent = t; }
  }
  console.log('[P27] float repr: div=' + divAssign.length + ' arith=' + nArith + ' plus=' + nPlus + ' pow=' + powIf.length);
});

// ---- P28: tuples -- (1, 2), t[0], len(t), for x in t, divmod(); nested-list formatting fix
patch('P28 tuples', () => {
  for (const v of ['tqhcm', 'tqcpz', 'tqed', 'tqek', 'tqeop', 'tqlo', 'tqhi', 'tqenc', 'tqacc', 'tqn', 'tqi', 'tqelem', 'lfelem', 'tqdiv']) newVar(v, 0);
  B.addList(IT, 'VStack', []);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const isT = (x) => EQ(x, txt('T'));
  const isLorT = (x) => OR(EQ(x, txt('L')), isT(x));
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const pushv = (v) => addTo('VStack', v);
  const popv = (name) => [setV(name, item('VStack', llen('VStack'))), delLast('VStack')];
  // save/restore loop state around a recursive call: pushes are LIFO, so restore in reverse order
  const pushVars = (names) => names.map((n) => pushv(VAR(n)));
  const popVars = (names) => [...names].reverse().flatMap((n) => popv(n));
  const errStop = () => [IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()])];
  // input descriptors: [1, [10, 'lit']] literal | [3, blockid, shadow] block | [3, [12, name, id], shadow] variable
  const litOf = (desc) => (desc && Array.isArray(desc[1]) && [4, 5, 6, 7, 8, 9, 10].includes(desc[1][0]) && desc[1][1] !== undefined && desc[1][1] !== null) ? String(desc[1][1]) : null;
  const blkOf = (desc) => (desc && typeof desc[1] === 'string') ? desc[1] : null;
  const varOf = (desc) => (desc && Array.isArray(desc[1]) && desc[1][0] === 12) ? desc[1][1] : null;
  const repOf = (desc) => blkOf(desc) || (varOf(desc) ? VAR(varOf(desc)) : null);
  const condBlock = (b) => (b.inputs && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string') ? BL()[b.inputs.CONDITION[1]] : null;
  const condId = (b) => (b.inputs && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string') ? b.inputs.CONDITION[1] : null;
  const subHas = (b, proccode) => b.inputs && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === proccode);
  const isCtrl = (b) => b.opcode === 'control_if' || b.opcode === 'control_if_else';

  // (a) hascomma from to -> hcm/cpz : is there a top-level comma, and where?
  const hc = newProc('hascomma %s %s', ['from', 'to']);
  attachBody(hc.defId, [
    setV('tqhcm', num(0)), setV('tqcpz', num(0)),
    IF(GT(argOf('from'), argOf('to')), [setV('tqhcm', num(1))]),
    setV('tqed', num(0)), setV('tqek', argOf('from')),
    REPEATU(OR(GT(VAR('tqek'), argOf('to')), EQ(VAR('tqhcm'), num(1))), [
      setV('tqeop', item('Tok', VAR('tqek'))),
      IF(OR(EQ(VAR('tqeop'), txt('(')), EQ(VAR('tqeop'), txt('['))), [chgV('tqed', num(1))]),
      IF(OR(EQ(VAR('tqeop'), txt(')')), EQ(VAR('tqeop'), txt(']'))), [chgV('tqed', num(-1))]),
      IF(AND(EQ(VAR('tqed'), num(0)), EQ(VAR('tqeop'), txt(','))), [setV('tqhcm', num(1)), setV('tqcpz', VAR('tqek'))]),
      chgV('tqek', num(1))
    ])
  ]);
  console.log('[P28a] hascomma ok');

  // (b) tuplelit lo hi -> ev (type T); same element encoding as lists
  const tl = newProc('tuplelit %s %s', ['lo', 'hi']);
  attachBody(tl.defId, [
    setV('ev', txt('')), setV('evtype', txt('T')),
    IF(NOT(GT(argOf('lo'), argOf('hi'))), [
      setV('tqacc', txt('')), setV('tqlo', argOf('lo')),
      setV('tqed', num(0)), setV('tqek', argOf('lo')),
      REPEATU(GT(VAR('tqek'), argOf('hi')), [
        setV('tqeop', item('Tok', VAR('tqek'))),
        IF(OR(EQ(VAR('tqeop'), txt('(')), EQ(VAR('tqeop'), txt('['))), [chgV('tqed', num(1))]),
        IF(OR(EQ(VAR('tqeop'), txt(')')), EQ(VAR('tqeop'), txt(']'))), [chgV('tqed', num(-1))]),
        IF(AND(EQ(VAR('tqed'), num(0)), EQ(VAR('tqeop'), txt(','))), [
          setV('tqhi', SUB(VAR('tqek'), num(1))),
          ...pushVars(['tqacc', 'tqlo', 'tqek', 'tqed']),
          IF(NOT(GT(VAR('tqlo'), VAR('tqhi'))), [
            callProc('eval %s %s', [VAR('tqlo'), VAR('tqhi')]),
            IF(NOT(EQ(VAR('error'), txt(''))), [...popVars(['tqacc', 'tqlo', 'tqek', 'tqed'])]),
            IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()])
          ]),
          setV('tqenc', JOIN(JOIN(VAR('lsep'), VAR('evtype')), VAR('ev'))),
          ...popVars(['tqacc', 'tqlo', 'tqek', 'tqed']),
          setV('tqacc', JOIN(VAR('tqacc'), VAR('tqenc'))),
          setV('tqlo', ADD(VAR('tqek'), num(1)))
        ]),
        chgV('tqek', num(1))
      ]),
      IF(NOT(GT(VAR('tqlo'), argOf('hi'))), [
        ...pushVars(['tqacc', 'tqlo', 'tqek', 'tqed']),
        callProc('eval %s %s', [VAR('tqlo'), argOf('hi')]),
        IF(NOT(EQ(VAR('error'), txt(''))), [...popVars(['tqacc', 'tqlo', 'tqek', 'tqed'])]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        setV('tqenc', JOIN(JOIN(VAR('lsep'), VAR('evtype')), VAR('ev'))),
        ...popVars(['tqacc', 'tqlo', 'tqek', 'tqed']),
        setV('tqacc', JOIN(VAR('tqacc'), VAR('tqenc')))
      ]),
      setV('ev', VAR('tqacc')), setV('evtype', txt('T'))
    ])
  ]);
  console.log('[P28b] tuplelit ok');

  // (c) tupfmt s -> "(a, b)"
  const tf = newProc('tupfmt %s', ['s']);
  attachBody(tf.defId, [
    setV('tqacc', txt('(')),
    callProc('listlen %s', [argOf('s')]),
    setV('tqn', VAR('ev')), setV('tqi', num(1)),
    REPEATU(GT(VAR('tqi'), VAR('tqn')), [
      callProc('listitem %s %s', [argOf('s'), VAR('tqi')]),
      ...pushVars(['tqacc', 'tqi', 'tqn']),
      callProc('reprval %s %s', [VAR('ev'), VAR('evtype')]),
      ...pushVars(['ev']),
      ...popVars(['ev']),
      ...popVars(['tqacc', 'tqi', 'tqn']),
      setV('tqelem', VAR('ev')),
      IF(GT(VAR('tqi'), num(1)), [setV('tqacc', JOIN(VAR('tqacc'), txt(', ')))]),
      setV('tqacc', JOIN(VAR('tqacc'), VAR('tqelem'))),
      chgV('tqi', num(1))
    ]),
    IF(EQ(VAR('tqn'), num(1)), [setV('tqacc', JOIN(VAR('tqacc'), txt(',')))]),
    setV('ev', JOIN(VAR('tqacc'), txt(')'))),
    setV('evtype', txt('S'))
  ]);
  console.log('[P28c] tupfmt ok');

  // (d) eval: "( ... )" holding a top-level comma is a tuple
  {
    const evSet = inDef('eval %s %s');
    const parenIf = find(evSet, (b) => isCtrl(b) && (() => {
      const cb = condBlock(b);
      if (!cb || cb.opcode !== 'operator_and') return false;
      return [...reach(b.inputs.CONDITION[1])].some((id) => BL()[id].opcode === 'operator_equals' && litOf(BL()[id].inputs.OPERAND2) === '(')
        && subHas(b, 'eval %s %s');
    })());
    if (parenIf.length !== 1) throw new Error('eval paren branch = ' + parenIf.length);
    const subId = BL()[parenIf[0]].inputs.SUBSTACK[1];
    const inner = find(reach(subId), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
    if (inner.length !== 1) throw new Error('eval paren inner = ' + inner.length);
    insertBeforeStmt(inner[0], [callProc('hascomma %s %s', [ADD(argOf('lo'), num(1)), SUB(argOf('hi'), num(1))])]);
    replaceStmt(inner[0], IFELSE(EQ(VAR('tqhcm'), num(1)),
      [callProc('tuplelit %s %s', [ADD(argOf('lo'), num(1)), SUB(argOf('hi'), num(1))])],
      [callProc('eval %s %s', [ADD(argOf('lo'), num(1)), SUB(argOf('hi'), num(1))])]));
  }
  console.log('[P28d] eval hook ok');

  // (e) indexget: accept tuples in the type guard and in the element branch
  {
    const ig = inDef('indexget %s %s');
    const guard = find(ig, (b) => isCtrl(b) && (() => {
      const cb = condBlock(b);
      return !!cb && cb.opcode === 'operator_not'
        && [...reach(b.inputs.CONDITION[1])].some((id) => BL()[id].opcode === 'operator_equals' && litOf(BL()[id].inputs.OPERAND2) === 'L');
    })());
    if (guard.length !== 1) throw new Error('indexget type guard = ' + guard.length);
    BL()[guard[0]].inputs.CONDITION = B.BOOL(NOT(OR(EQ(VAR('xb'), txt('S')), isLorT(VAR('xb')))));
    const idxL = find(ig, (b) => isCtrl(b) && (() => {
      const cb = condBlock(b);
      return !!cb && cb.opcode === 'operator_equals' && litOf(cb.inputs.OPERAND2) === 'L' && subHas(b, 'listlen %s');
    })());
    if (idxL.length < 1) throw new Error('indexget list branch = ' + idxL.length);
    for (const id of idxL) BL()[id].inputs.CONDITION = B.BOOL(isLorT(VAR('xb')));
    console.log('[P28e1] widened ' + idxL.length + ' indexget branches');
  }
  console.log('[P28e] indexget ok');

  // (f) len(x) / sum(x) / for x in x accept tuples
  for (const proc of ['callfn %s %s %s', 'forloop']) {
    const def = inDef(proc);
    for (const id of find(def, isCtrl)) {
      const cb = condBlock(BL()[id]);
      if (!cb) continue;
      if (cb.opcode === 'operator_equals' && litOf(cb.inputs.OPERAND2) === 'L') {
        const lhs = repOf(cb.inputs.OPERAND1);
        const eqId = condId(BL()[id]);
        if (!lhs) continue;
        BL()[id].inputs.CONDITION = B.BOOL(OR(eqId, EQ(lhs, txt('T'))));
      } else if (cb.opcode === 'operator_not') {
        const eqId = blkOf(cb.inputs.OPERAND);
        if (!eqId) continue;
        const eb = BL()[eqId];
        if (!eb || eb.opcode !== 'operator_equals' || litOf(eb.inputs.OPERAND2) !== 'L') continue;
        const lhs = repOf(eb.inputs.OPERAND1);
        if (!lhs) continue;
        cb.inputs.OPERAND = B.BOOL(OR(eqId, EQ(lhs, txt('T'))));
      }
    }
  }
  console.log('[P28f] callfn/forloop ok');

  // (g) strval/reprval: tuples render as (a, b)
  for (const proc of ['strval %s %s', 'reprval %s %s']) {
    const def = inDef(proc);
    const br = find(def, (b) => b.opcode === 'control_if_else' && (() => {
      const cb = condBlock(b);
      return !!cb && cb.opcode === 'operator_equals' && litOf(cb.inputs.OPERAND2) === 'L' && subHas(b, 'listfmt %s');
    })());
    if (br.length !== 1) { console.log('[P28g1] ' + proc + ' branches=' + br.length + ' (skipped)'); continue; }
    const eqId = condId(BL()[br[0]]);
    const listCall = find(reach(BL()[br[0]].inputs.SUBSTACK[1]), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'listfmt %s');
    if (listCall.length !== 1) throw new Error(proc + ' listfmt call = ' + listCall.length);
    BL()[br[0]].inputs.CONDITION = B.BOOL(OR(eqId, EQ(argOf('vt'), txt('T'))));
    replaceStmt(listCall[0], IFELSE(EQ(argOf('vt'), txt('T')), [callProc('tupfmt %s', [argOf('vv')])], [callProc('listfmt %s', [argOf('vv')])]));
  }
  console.log('[P28g] strval reprval ok');

  // (h) listfmt: keep the accumulator across the recursive reprval call (nested lists)
  {
    const lf = inDef('listfmt %s');
    const rp = find(lf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'reprval %s %s');
    if (rp.length !== 1) throw new Error('listfmt reprval = ' + rp.length);
    insertBeforeStmt(rp[0], pushVars(['lfacc', 'lfi', 'lfn']));
    spliceAfter(rp[0], chain([...pushVars(['ev']), ...popVars(['ev']), ...popVars(['lfacc', 'lfi', 'lfn'])]));
  }
  console.log('[P28h] listfmt ok');

  // (i) divmod(a, b) -> (a // b, a % b)
  // (i) divmod(a, b) -> (a // b, a % b); runs in eval because 2-argument calls never reach callfn
  {
    const evSet = inDef('eval %s %s');
    const nargIf = find(evSet, (b) => b.opcode === 'control_if_else' && (() => {
      const cb = condBlock(b);
      return !!cb && cb.opcode === 'operator_equals' && varOf(cb.inputs.OPERAND1) === 'narg' && litOf(cb.inputs.OPERAND2) === '0';
    })());
    if (nargIf.length !== 1) throw new Error('eval narg branch = ' + nargIf.length);
    prependStack(nargIf[0], 'SUBSTACK2', chain([
      IF(AND(EQ(item('Tok', argOf('lo')), txt('divmod')), EQ(VAR('narg'), num(1))), [
        callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
        IF(EQ(VAR('tqhcm'), num(0)), [FAIL(txt('TypeError: divmod expected 2 arguments, got 1'))]),
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('tqcpz'), num(1))]),
        ...errStop(),
        IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL(txt('TypeError: divmod() argument must be a number'))]),
        setV('tqdiv', VAR('ev')),
        callProc('eval %s %s', [ADD(VAR('tqcpz'), num(1)), SUB(argOf('hi'), num(1))]),
        ...errStop(),
        IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL(txt('TypeError: divmod() argument must be a number'))]),
        IF(EQ(VAR('ev'), num(0)), [FAIL(txt('ZeroDivisionError: integer division or modulo by zero'))]),
        setV('tqacc', JOIN(JOIN(VAR('lsep'), txt('N')), FLOOR(DIV(VAR('tqdiv'), VAR('ev'))))),
        setV('tqacc', JOIN(VAR('tqacc'), JOIN(JOIN(VAR('lsep'), txt('N')), MOD(VAR('tqdiv'), VAR('ev'))))),
        setV('ev', VAR('tqacc')), setV('evtype', txt('T')),
        STOPTHIS()
      ])
    ]));
  }
  console.log('[P28i] divmod ok');

  // (j) the unknown-function branch reported a stale block id as its message
  {
    const evSet = inDef('eval %s %s');
    const bad = find(evSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
      && Object.values(b.inputs || {}).some((v) => Array.isArray(v[1]) && v[1][0] === 10 && /^b(operat|proced|contro|datait|argume)_/.test(String(v[1][1]))));
    if (bad.length !== 1) throw new Error('stale fail message blocks = ' + bad.length);
    const slot = Object.keys(BL()[bad[0]].inputs).find((k) => Array.isArray(BL()[bad[0]].inputs[k][1]) && BL()[bad[0]].inputs[k][1][0] === 10);
    BL()[bad[0]].inputs[slot] = B.REP(JOIN(txt('NameError: name '), JOIN(item('Tok', argOf('lo')), txt(' is not defined'))), [10, '']);
    console.log('[P28j] fixed unknown-function message');
  }
  console.log('[P28] tuples + divmod installed');
});

// ---- P29: math.* results keep CPython's float type (math.sqrt(16) -> 4.0, floor stays int)
patch('P29 math floats', () => {
  const FLOATS = ['fabs', 'exp', 'log', 'log10', 'sin', 'cos', 'tan', 'sqrt', 'pow', 'fmod'];
  const mc = inDef('methodcall %s %s');
  const litOf2 = (desc) => (desc && Array.isArray(desc[1]) && [4, 10].includes(desc[1][0]) && desc[1][1] !== undefined) ? String(desc[1][1]) : null;
  const subOf = (b) => (b.inputs && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string') ? b.inputs.SUBSTACK[1] : null;
  let hits = 0;
  for (const id of find(mc, (b) => b.opcode === 'control_if' || b.opcode === 'control_if_else')) {
    const b = BL()[id];
    const condId = b.inputs.CONDITION && b.inputs.CONDITION[1];
    if (typeof condId !== 'string') continue;
    const names = [...reach(condId)].filter((x) => BL()[x].opcode === 'operator_equals')
      .map((x) => [litOf2(BL()[x].inputs.OPERAND1), litOf2(BL()[x].inputs.OPERAND2)])
      .map(([p, q]) => (FLOATS.includes(p) ? p : (FLOATS.includes(q) ? q : null)))
      .filter(Boolean);
    const want = [...new Set(names)].filter((n) => FLOATS.includes(n));
    if (!want.length) continue;
    const sub = subOf(b);
    if (!sub) continue;
    // place mkfloat right after the last value-typing statement of this branch
    let last = null, cur = sub, guard = 0;
    while (cur && guard++ < 200) {
      const s = BL()[cur];
      if (s.opcode === 'data_setvariableto' && s.fields && s.fields.VARIABLE && ['ev', 'evtype'].includes(s.fields.VARIABLE[0])) last = cur;
      cur = s.next;
    }
    if (!last) continue;
    spliceAfter(last, chain([callProc('mkfloat %s', [VAR('ev')])]));
    hits++;
    console.log('[P29] ' + want.join('/') + ' -> float');
  }
  console.log('[P29] math float branches patched = ' + hits);

  // (b) match CPython's wording for the two math error messages
  let msgs = 0;
  for (const id of find(mc, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s')) {
    const slot = Object.keys(BL()[id].inputs)[0];
    const desc = BL()[id].inputs[slot];
    const blk = typeof desc[1] === 'string' ? desc[1] : null;
    const texts = (() => {
      const out = [];
      const walkDesc = (d) => {
        if (!d) return;
        if (Array.isArray(d[1]) && d[1][0] === 10) out.push(String(d[1][1]));
        else if (typeof d[1] === 'string' && BL()[d[1]]) walkBlock(d[1]);
      };
      const walkBlock = (bid) => { const b = BL()[bid]; if (!b) return; for (const v of Object.values(b.inputs || {})) walkDesc(v); };
      if (blk) walkBlock(blk);
      return out.join('');
    })();
    const lit = litOf2(desc) || '';
    if (lit === 'NameError: name math is not defined') {
      BL()[id].inputs[slot] = B.REP(txt("NameError: name 'math' is not defined. Did you forget to import 'math'?"), [10, '']);
      msgs++;
    } else if (texts.includes('AttributeError: math has no ')) {
      BL()[id].inputs[slot] = B.REP(JOIN(txt("AttributeError: module 'math' has no attribute '"), JOIN(item('Tok', ADD(argOf('lo'), num(2))), txt("'"))), [10, '']);
      msgs++;
    }
  }
  console.log('[P29] math messages rewritten = ' + msgs);
});

// ---- P30: one-line suites -- "if x: print(1)" is expanded into a two-line block before prepare
patch('P30 one-line suites', () => {
  for (const v of ['xli', 'xlj', 'xlk', 'xlind', 'xlcut', 'xlch', 'xlstr', 'xldep', 'xles', 'xlrest', 'xlhead', 'xlbod', 'xlw']) newVar(v, 0);
  B.addList(IT, 'NewLines', []);
  B.addList(IT, 'Kw', ['if', 'elif', 'else', 'while', 'for', 'def', 'try', 'except', 'finally', 'with', 'class']);

  const chAt = (i) => letterOf(i, VAR('xles'));
  const isKw = () => I('data_listcontainsitem', { fields: B.LISTF('Kw'), inputs: { ITEM: B.REP(VAR('xlw'), [10, '']) } });

  const ex = newProc('expandlines', []);
  attachBody(ex.defId, [
    clearL('NewLines'),
    setV('xli', num(1)),
    REPEATU(GT(VAR('xli'), llen('Code')), [
      setV('xles', item('Code', VAR('xli'))),
      // index of the first non-space character
      setV('xlj', num(1)),
      REPEATU(OR(GT(VAR('xlj'), lenOf(VAR('xles'))), NOT(EQ(chAt(VAR('xlj')), txt(' ')))), [chgV('xlj', num(1))]),
      setV('xlind', SUB(VAR('xlj'), num(1))),
      // first word of the statement
      setV('xlw', txt('')), setV('xlk', VAR('xlj')),
      REPEATU(OR(GT(VAR('xlk'), lenOf(VAR('xles'))), OR(EQ(chAt(VAR('xlk')), txt(' ')), OR(EQ(chAt(VAR('xlk')), txt(':')), EQ(chAt(VAR('xlk')), txt('('))))), [
        setV('xlw', JOIN(VAR('xlw'), chAt(VAR('xlk')))),
        chgV('xlk', num(1))
      ]),
      // last colon at bracket depth 0 (strings and comments are skipped)
      setV('xlcut', num(0)), setV('xldep', num(0)), setV('xlstr', num(0)), setV('xlk', VAR('xlj')),
      REPEATU(GT(VAR('xlk'), lenOf(VAR('xles'))), [
        setV('xlch', chAt(VAR('xlk'))),
        IFELSE(EQ(VAR('xlstr'), num(1)), [
          IFELSE(EQ(VAR('xlch'), VAR('slash')), [chgV('xlk', num(1))], [
            IF(EQ(VAR('xlch'), VAR('dq')), [setV('xlstr', num(0))])
          ])
        ], [
          IFELSE(EQ(VAR('xlch'), VAR('dq')), [setV('xlstr', num(1))], [
            IFELSE(EQ(VAR('xlch'), txt('#')), [setV('xlk', ADD(lenOf(VAR('xles')), num(1)))], [
              IF(OR(EQ(VAR('xlch'), txt('(')), OR(EQ(VAR('xlch'), txt('[')), EQ(VAR('xlch'), txt('{')))), [chgV('xldep', num(1))]),
              IF(OR(EQ(VAR('xlch'), txt(')')), OR(EQ(VAR('xlch'), txt(']')), EQ(VAR('xlch'), txt('}')))), [chgV('xldep', num(-1))]),
              IF(AND(EQ(VAR('xldep'), num(0)), EQ(VAR('xlch'), txt(':'))), [setV('xlcut', VAR('xlk'))])
            ])
          ])
        ]),
        chgV('xlk', num(1))
      ]),
      // statement text after the colon (a comment does not count)
      setV('xlrest', txt('')),
      IF(AND(GT(VAR('xlcut'), num(0)), isKw()), [
        setV('xlk', ADD(VAR('xlcut'), num(1))),
        REPEATU(OR(GT(VAR('xlk'), lenOf(VAR('xles'))), NOT(EQ(chAt(VAR('xlk')), txt(' ')))), [chgV('xlk', num(1))]),
        IF(AND(NOT(GT(VAR('xlk'), lenOf(VAR('xles')))), NOT(EQ(chAt(VAR('xlk')), txt('#')))), [
          REPEATU(GT(VAR('xlk'), lenOf(VAR('xles'))), [
            setV('xlrest', JOIN(VAR('xlrest'), chAt(VAR('xlk')))),
            chgV('xlk', num(1))
          ])
        ])
      ]),
      IFELSE(NOT(EQ(VAR('xlrest'), txt(''))), [
        setV('xlhead', txt('')), setV('xlk', num(1)),
        REPEATU(GT(VAR('xlk'), VAR('xlcut')), [
          setV('xlhead', JOIN(VAR('xlhead'), chAt(VAR('xlk')))),
          chgV('xlk', num(1))
        ]),
        addTo('NewLines', VAR('xlhead')),
        setV('xlbod', txt('')), setV('xlj', num(1)),
        REPEATU(GT(VAR('xlj'), ADD(VAR('xlind'), num(4))), [
          setV('xlbod', JOIN(VAR('xlbod'), txt(' '))),
          chgV('xlj', num(1))
        ]),
        addTo('NewLines', JOIN(VAR('xlbod'), VAR('xlrest')))
      ], [
        addTo('NewLines', VAR('xles'))
      ]),
      chgV('xli', num(1))
    ]),
    clearL('Code'),
    setV('xli', num(1)),
    REPEATU(GT(VAR('xli'), llen('NewLines')), [
      addTo('Code', item('NewLines', VAR('xli'))),
      chgV('xli', num(1))
    ])
  ]);

  const prep = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'prepare');
  if (prep.length !== 1) throw new Error('prepare call sites = ' + prep.length);
  insertBeforeStmt(prep[0], [callProc('expandlines'), callProc('expandlines'), callProc('expandlines')]);
  console.log('[P30] one-line suite expansion installed');
});

// ---- P31: any() / all() builtins
patch('P31 any/all', () => {
  for (const v of ['aai', 'aan', 'aaacc']) newVar(v, 0);
  const isLorT = (x) => OR(EQ(x, txt('L')), EQ(x, txt('T')));
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const condBlock = (b) => (b.inputs && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string') ? BL()[b.inputs.CONDITION[1]] : null;
  const isCtrl = (b) => b.opcode === 'control_if' || b.opcode === 'control_if_else';
  const varOf = (desc) => (desc && Array.isArray(desc[1]) && desc[1][0] === 12) ? desc[1][1] : null;
  const litOf = (desc) => (desc && Array.isArray(desc[1]) && [4, 10].includes(desc[1][0])) ? String(desc[1][1]) : null;

  // anyall fn vv vt -> ev/evtype (B)
  const p = newProc('anyall %s %s %s', ['fn', 'vv', 'vt']);
  const emit = () => [setV('ev', VAR('aaacc')), setV('evtype', txt('B'))];
  attachBody(p.defId, [
    // 注意：这里按全局 evtype 分派（argument reporter 参与 operator_or 组合时行为不可靠，见 README）
    IFELSE(isLorT(VAR('evtype')), [
      callProc('listlen %s', [argOf('vv')]),
      setV('aan', VAR('ev')), setV('aai', num(1)),
      IFELSE(EQ(argOf('fn'), txt('any')), [setV('aaacc', num(0))], [setV('aaacc', num(1))]),
      REPEATU(GT(VAR('aai'), VAR('aan')), [
        callProc('listitem %s %s', [argOf('vv'), VAR('aai')]),
        callProc('truth %s %s', [VAR('ev'), VAR('evtype')]),
        IFELSE(EQ(argOf('fn'), txt('any')), [
          IF(EQ(VAR('truthv'), num(1)), [setV('aaacc', num(1)), setV('aai', VAR('aan'))])
        ], [
          IF(EQ(VAR('truthv'), num(0)), [setV('aaacc', num(0)), setV('aai', VAR('aan'))])
        ]),
        chgV('aai', num(1))
      ]),
      ...emit()
    ], [
      IFELSE(EQ(VAR('evtype'), txt('S')), [
        IFELSE(EQ(argOf('fn'), txt('any')), [
          IFELSE(GT(lenOf(argOf('vv')), num(0)), [setV('aaacc', num(1))], [setV('aaacc', num(0))])
        ], [setV('aaacc', num(1))]),
        ...emit()
      ], [
        FAILB(JOIN(txt("TypeError: '"), JOIN(argOf('vt'), txt("' object is not iterable"))))
      ])
    ])
  ]);
  console.log('[P31] anyall proc rebuilt');

  // hook into callfn, right before the "not callable" guard
  const cf = inDef('callfn %s %s %s');
  const guard = find(cf, (b) => isCtrl(b) && (() => {
    const cb = condBlock(b);
    return !!cb && cb.opcode === 'operator_equals' && varOf(cb.inputs.OPERAND1) === 'pending' && litOf(cb.inputs.OPERAND2) === '0';
  })());
  if (guard.length !== 1) throw new Error('callfn pending guard = ' + guard.length);
  insertBeforeStmt(guard[0], [
    // callfn 已经把整个实参区间求值到 ev/evtype，直接用即可（它自己的 lo/hi 就是实参范围）
    IF(OR(EQ(argOf('fn'), txt('any')), EQ(argOf('fn'), txt('all'))), [
      callProc('anyall %s %s %s', [argOf('fn'), VAR('ev'), VAR('evtype')]),
      setV('pending', num(1)),
      STOPTHIS()
    ])
  ]);
  console.log('[P31] any/all installed');
});

// ---- P32: implicit line joining -- "(1 +\n 2)", "[1,\n 2]" and trailing backslash are merged before prepare
patch('P32 line continuation', () => {
  for (const v of ['xgi', 'xgj', 'xgc', 'xgd', 'xgs', 'xgb', 'xgk', 'xgch', 'xgw']) newVar(v, 0);
  B.addList(IT, 'New2', []);

  const chAt = (i) => letterOf(i, VAR('xgc'));
  const c0 = () => VAR('xgch');
  const eqc = (s) => EQ(c0(), txt(s));
  const Q = String.fromCharCode(39);   // single quote
  // scan the accumulated line: xgd = bracket depth, xgb = 1 when it ends with a code backslash
  const scan = () => [
    setV('xgd', num(0)), setV('xgs', txt('')), setV('xgb', num(0)), setV('xgk', num(1)),
    REPEATU(GT(VAR('xgk'), lenOf(VAR('xgc'))), [
      setV('xgch', chAt(VAR('xgk'))),
      IFELSE(NOT(EQ(VAR('xgs'), txt(''))), [
        IFELSE(EQ(c0(), VAR('slash')), [chgV('xgk', num(1))], [
          IF(EQ(c0(), VAR('xgs')), [setV('xgs', txt(''))])
        ])
      ], [
        IFELSE(OR(EQ(c0(), VAR('dq')), EQ(c0(), txt(Q))), [setV('xgs', c0())], [
          IFELSE(EQ(c0(), txt('#')), [setV('xgk', ADD(lenOf(VAR('xgc')), num(1)))], [
            IF(OR(eqc('('), OR(eqc('['), eqc('{'))), [chgV('xgd', num(1))]),
            IF(OR(eqc(')'), OR(eqc(']'), eqc('}'))), [chgV('xgd', num(-1))])
          ])
        ])
      ]),
      chgV('xgk', num(1))
    ]),
    IF(AND(GT(lenOf(VAR('xgc')), num(0)), EQ(letterOf(lenOf(VAR('xgc')), VAR('xgc')), VAR('slash'))), [setV('xgb', num(1))]),
    IF(NOT(EQ(VAR('xgs'), txt(''))), [setV('xgb', num(0))])
  ];

  const p = newProc('joinlines', []);
  attachBody(p.defId, [
    clearL('New2'),
    setV('xgi', num(1)),
    REPEATU(GT(VAR('xgi'), llen('Code')), [
      setV('xgc', item('Code', VAR('xgi'))),
      setV('xgj', num(0)),
      REPEATU(EQ(VAR('xgj'), num(1)), [
        ...scan(),
        IFELSE(OR(GT(VAR('xgd'), num(0)), EQ(VAR('xgb'), num(1))), [
          IF(EQ(VAR('xgb'), num(1)), [
            setV('xgw', txt('')), setV('xgk', num(1)),
            REPEATU(GT(VAR('xgk'), SUB(lenOf(VAR('xgc')), num(1))), [
              setV('xgw', JOIN(VAR('xgw'), chAt(VAR('xgk')))),
              chgV('xgk', num(1))
            ]),
            setV('xgc', VAR('xgw'))
          ]),
          chgV('xgi', num(1)),
          IFELSE(GT(VAR('xgi'), llen('Code')), [setV('xgj', num(1))], [
            callProc('trimsp %s', [item('Code', VAR('xgi'))]),
            setV('xgc', JOIN(VAR('xgc'), JOIN(txt(' '), VAR('ev'))))
          ])
        ], [
          setV('xgj', num(1))
        ])
      ]),
      addTo('New2', VAR('xgc')),
      chgV('xgi', num(1))
    ]),
    clearL('Code'),
    setV('xgi', num(1)),
    REPEATU(GT(VAR('xgi'), llen('New2')), [
      addTo('Code', item('New2', VAR('xgi'))),
      chgV('xgi', num(1))
    ])
  ]);

  const exp = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'expandlines');
  if (exp.length !== 3) throw new Error('expandlines call sites = ' + exp.length);
  insertBeforeStmt(exp[0], [callProc('joinlines')]);   // join first, then expand one-liners
  console.log('[P32] line continuation installed');
});

// ---- P33: dict literals with scalar keys -- {'a': 1}, d['a']
patch('P33 dict literals', () => {
  for (const v of ['dgi', 'dgk', 'dged', 'dgeop', 'dgdep', 'dgcp', 'dglo', 'dga', 'dgb', 'dgkey', 'dgkt', 'dgn', 'dgj']) newVar(v, 0);
  B.addList(IT, 'DOut', []);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const isCtrl = (b) => b.opcode === 'control_if' || b.opcode === 'control_if_else';
  const condBlock = (b) => (b.inputs && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string') ? BL()[b.inputs.CONDITION[1]] : null;
  const litOf = (desc) => (desc && Array.isArray(desc[1]) && [4, 10].includes(desc[1][0])) ? String(desc[1][1]) : null;
  const blkOf = (desc) => (desc && typeof desc[1] === 'string') ? desc[1] : null;
  const varOf = (desc) => (desc && Array.isArray(desc[1]) && desc[1][0] === 12) ? desc[1][1] : null;
  const tokAt = (x) => item('Tok', x);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const pushv = (v) => addTo('VStack', v);
  const popv = (name) => [setV(name, item('VStack', llen('VStack'))), delLast('VStack')];
  const pushVars = (names) => names.map((n) => pushv(VAR(n)));
  const popVars = (names) => [...names].reverse().flatMap((n) => popv(n));
  const chAt = (s, i) => letterOf(i, s);

  // dictpair a b : one "key : value" pair, appended to DOut
  const dp = newProc('dictpair %s %s', ['a', 'b']);
  attachBody(dp.defId, [
    setV('dgdep', num(0)), setV('dgcp', num(0)), setV('dgi', argOf('a')),
    REPEATU(GT(VAR('dgi'), argOf('b')), [
      setV('dgeop', tokAt(VAR('dgi'))),
      IF(OR(EQ(VAR('dgeop'), txt('(')), OR(EQ(VAR('dgeop'), txt('[')), EQ(VAR('dgeop'), txt('{')))), [chgV('dgdep', num(1))]),
      IF(OR(EQ(VAR('dgeop'), txt(')')), OR(EQ(VAR('dgeop'), txt(']')), EQ(VAR('dgeop'), txt('}')))), [chgV('dgdep', num(-1))]),
      IF(AND(EQ(VAR('dgdep'), num(0)), EQ(VAR('dgeop'), txt(':'))), [setV('dgcp', VAR('dgi'))]),
      chgV('dgi', num(1))
    ]),
    IF(EQ(VAR('dgcp'), num(0)), [FAIL(txt('SyntaxError: expected colon in dictionary'))]),
    // key
    ...pushVars(['dgcp']),
    callProc('eval %s %s', [argOf('a'), SUB(VAR('dgcp'), num(1))]),
    IF(NOT(EQ(VAR('error'), txt(''))), [...popVars(['dgcp'])]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    setV('dgkey', VAR('ev')), setV('dgkt', VAR('evtype')),
    ...popVars(['dgcp']),
    addTo('DOut', JOIN(JOIN(VAR('lsep'), VAR('dgkt')), VAR('dgkey'))),
    // value
    ...pushVars(['dgcp']),
    callProc('eval %s %s', [ADD(VAR('dgcp'), num(1)), argOf('b')]),
    IF(NOT(EQ(VAR('error'), txt(''))), [...popVars(['dgcp'])]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    setV('dga', VAR('ev')), setV('dgb', VAR('evtype')),
    ...popVars(['dgcp']),
    addTo('DOut', JOIN(JOIN(VAR('lsep'), VAR('dgb')), VAR('dga')))
  ]);

  // dictlit lo hi : { k: v, k2: v2 }
  const dl = newProc('dictlit %s %s', ['lo', 'hi']);
  attachBody(dl.defId, [
    setV('ev', txt('')), setV('evtype', txt('D')),
    IF(NOT(GT(argOf('lo'), argOf('hi'))), [
      clearL('DOut'),
      setV('dged', num(0)), setV('dglo', argOf('lo')), setV('dgi', argOf('lo')),
      REPEATU(GT(VAR('dgi'), argOf('hi')), [
        setV('dgeop', tokAt(VAR('dgi'))),
        IF(OR(EQ(VAR('dgeop'), txt('(')), OR(EQ(VAR('dgeop'), txt('[')), EQ(VAR('dgeop'), txt('{')))), [chgV('dged', num(1))]),
        IF(OR(EQ(VAR('dgeop'), txt(')')), OR(EQ(VAR('dgeop'), txt(']')), EQ(VAR('dgeop'), txt('}')))), [chgV('dged', num(-1))]),
        IF(AND(EQ(VAR('dged'), num(0)), EQ(VAR('dgeop'), txt(','))), [
          callProc('dictpair %s %s', [VAR('dglo'), SUB(VAR('dgi'), num(1))]),
          IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
          setV('dglo', ADD(VAR('dgi'), num(1)))
        ]),
        chgV('dgi', num(1))
      ]),
      IF(NOT(GT(VAR('dglo'), argOf('hi'))), [
        callProc('dictpair %s %s', [VAR('dglo'), argOf('hi')]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()])
      ]),
      setV('dgn', txt('')), setV('dgi', num(1)),
      REPEATU(GT(VAR('dgi'), llen('DOut')), [
        setV('dgn', JOIN(VAR('dgn'), item('DOut', VAR('dgi')))),
        chgV('dgi', num(1))
      ]),
      setV('ev', VAR('dgn')), setV('evtype', txt('D'))
    ])
  ]);

  // (a) eval: { ... } is a dict literal
  {
    const evSet = inDef('eval %s %s');
    const listIf = find(evSet, (b) => isCtrl(b) && (() => {
      const cb = condBlock(b);
      if (!cb || cb.opcode !== 'operator_and') return false;
      if (![...reach(b.inputs.CONDITION[1])].some((id) => BL()[id].opcode === 'operator_equals' && litOf(BL()[id].inputs.OPERAND2) === '[')) return false;
      return b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
        && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'listlit %s %s');
    })());
    if (listIf.length !== 1) throw new Error('eval list branch = ' + listIf.length);
    insertBeforeStmt(listIf[0], [
      IF(AND(EQ(tokAt(argOf('lo')), txt('{')), EQ(tokAt(argOf('hi')), txt('}'))), [
        callProc('dictlit %s %s', [ADD(argOf('lo'), num(1)), SUB(argOf('hi'), num(1))]),
        // without this the dispatch falls through to the final else -> 'SyntaxError: expression'
        STOPTHIS()
      ])
    ]);
  }

  // (b) indexget: accept D and look a key up
  {
    const ig = inDef('indexget %s %s');
    const guard = find(ig, (b) => isCtrl(b) && (() => {
      const cb = condBlock(b);
      if (!cb || cb.opcode !== 'operator_not') return false;
      if (![...reach(b.inputs.CONDITION[1])].some((id) => BL()[id].opcode === 'operator_equals' && litOf(BL()[id].inputs.OPERAND2) === 'S')) return false;
      return b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
        && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation && BL()[id].mutation.proccode === 'fail %s');
    })());
    if (guard.length !== 1) throw new Error('indexget guard = ' + guard.length);
    const isType = (x, t) => EQ(x, txt(t));
    BL()[guard[0]].inputs.CONDITION = B.BOOL(NOT(OR(OR(isType(VAR('xb'), 'S'), OR(isType(VAR('xb'), 'L'), isType(VAR('xb'), 'T'))), isType(VAR('xb'), 'D'))));
    const colIf = find(ig, (b) => isCtrl(b) && (() => {
      const cb = condBlock(b);
      return !!cb && cb.opcode === 'operator_equals' && varOf(cb.inputs.OPERAND1) === 'xcol' && litOf(cb.inputs.OPERAND2) === '0';
    })());
    if (colIf.length < 1) throw new Error('indexget xcol branch = ' + colIf.length);
    for (const cid of colIf) prependStack(cid, 'SUBSTACK', chain([
      IF(EQ(VAR('xb'), txt('D')), [
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        setV('dgkey', VAR('ev')), setV('dgkt', VAR('evtype')),
        callProc('listlen %s', [VAR('xa')]),
        setV('dgn', VAR('ev')),
        setV('dgi', num(1)), setV('dgj', num(0)), setV('dgeop', txt('')),
        REPEATU(GT(VAR('dgi'), VAR('dgn')), [
          callProc('listitem %s %s', [VAR('xa'), VAR('dgi')]),
          IFELSE(EQ(VAR('evtype'), VAR('dgkt')), [
            callProc('compareText %s %s', [VAR('ev'), VAR('dgkey')]),
            IF(EQ(VAR('cmp'), num(0)), [
              setV('dgj', VAR('dgi')),
              setV('dgi', VAR('dgn')),
              setV('dgeop', txt('1'))
            ])
          ], []),
          chgV('dgi', num(1))
        ]),
        IF(EQ(VAR('dgeop'), txt('')), [
          FAILB(JOIN(txt('KeyError: '), VAR('dgkey')))
        ]),
        callProc('listitem %s %s', [VAR('xa'), ADD(VAR('dgj'), num(1))]),
        STOPTHIS()
      ])
    ]));
  }
  console.log('[P33] dict literals installed');
});

// ---- P34: escape lsep inside element text so nested containers survive the flat encoding
patch('P34 nested escaping', () => {
  for (const v of ['lei', 'leout']) newVar(v, 0);
  B.addVar(IT, 'lesc1', String.fromCharCode(30));
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const chAt = (i, s) => letterOf(i, s);
  // 描述符里变量报告器嵌在 [3, [12,'name',id], [10,'']] 的 desc[1] 上
  const isVarRep = (desc, name) => !!desc && Array.isArray(desc[1]) && desc[1][0] === 12 && desc[1][1] === name;

  // lesc v : ev = v with every lsep replaced by ESC + "1"
  const en = newProc('lesc %s', ['v']);
  attachBody(en.defId, [
    setV('leout', txt('')), setV('lei', num(1)),
    REPEATU(GT(VAR('lei'), lenOf(argOf('v'))), [
      IFELSE(EQ(chAt(VAR('lei'), argOf('v')), VAR('lsep')), [
        setV('leout', JOIN(VAR('leout'), JOIN(VAR('lesc1'), txt('1'))))
      ], [
        setV('leout', JOIN(VAR('leout'), chAt(VAR('lei'), argOf('v'))))
      ]),
      chgV('lei', num(1))
    ]),
    setV('ev', VAR('leout'))
  ]);

  // lunesc v : ev = v with ESC + "1" turned back into lsep
  const de = newProc('lunesc %s', ['v']);
  attachBody(de.defId, [
    setV('leout', txt('')), setV('lei', num(1)),
    REPEATU(GT(VAR('lei'), lenOf(argOf('v'))), [
      IFELSE(EQ(chAt(VAR('lei'), argOf('v')), VAR('lesc1')), [
        IFELSE(EQ(chAt(ADD(VAR('lei'), num(1)), argOf('v')), txt('1')), [
          setV('leout', JOIN(VAR('leout'), VAR('lsep'))),
          chgV('lei', num(1))
        ], [
          setV('leout', JOIN(VAR('leout'), chAt(VAR('lei'), argOf('v'))))
        ])
      ], [
        setV('leout', JOIN(VAR('leout'), chAt(VAR('lei'), argOf('v'))))
      ]),
      chgV('lei', num(1))
    ]),
    setV('ev', VAR('leout'))
  ]);

  // (a) every statement that builds an element from a fresh value gets lesc(ev) in front of it
  let n = 0;
  for (const id of allIds()) {
    const b = BL()[id];
    if (b.opcode !== 'data_addtolist' && b.opcode !== 'data_setvariableto') continue;
    const val = b.inputs && b.inputs.ITEM ? b.inputs.ITEM : (b.inputs && b.inputs.VALUE);
    const root = val && typeof val[1] === 'string' ? val[1] : null;
    if (!root) continue;
    let hasLsep = false, hasEv = false;
    for (const x of reach(root)) {
      for (const v of Object.values(BL()[x].inputs || {})) {
        if (isVarRep(v, 'lsep')) hasLsep = true;
        if (isVarRep(v, 'ev') || isVarRep(v, 'evtype')) hasEv = true;
      }
    }
    if (!hasLsep || !hasEv) continue;
    insertBeforeStmt(id, [callProc('lesc %s', [VAR('ev')])]);
    n++;
  }
  console.log('[P34] escaped element sites = ' + n);

  // (b) listitem restores the original text of the element it returns
  const li = inDef('listitem %s %s');
  const subs = find(li, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'substr %s %s %s');
  if (subs.length !== 1) throw new Error('listitem substr = ' + subs.length);
  spliceAfter(subs[0], chain([callProc('lunesc %s', [VAR('ev')])]));
  console.log('[P34] listitem unescape installed');

  // (c) lift the old "nested lists are not supported" guard: escaping makes it safe now
  const noop = () => setV('lesc1', VAR('lesc1'));
  let lifted = 0;
  for (const id of find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s')) {
    const desc = Object.values(BL()[id].inputs || {})[0];
    const lit = (desc && Array.isArray(desc[1]) && desc[1][0] === 10) ? String(desc[1][1]) : '';
    if (!lit.includes('nested list')) continue;
    replaceStmt(id, noop());
    lifted++;
  }
  console.log('[P34] nested-list guards lifted = ' + lifted);
});

// ---- P38: the remaining stale block-id error messages (//= and **= on an undefined name)
patch('P38 stale messages', () => {
  const litOf = (desc) => (desc && Array.isArray(desc[1]) && [4, 10].includes(desc[1][0])) ? String(desc[1][1]) : null;
  let fixed = 0;
  for (const id of find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s')) {
    const slot = Object.keys(BL()[id].inputs || {})[0];
    if (!slot) continue;
    const l = litOf(BL()[id].inputs[slot]);
    if (!l || !/^b(operat|proced|contro|datait|argume)_/.test(l)) continue;
    BL()[id].inputs[slot] = B.REP(JOIN(txt('NameError: '), VAR('name')), [10, '']);
    fixed++;
  }
  console.log('[P38] stale block-id messages fixed = ' + fixed);
});

// ---- P46: make listlit reentrant -- nested container literals (A13)
//
// Root cause (proved with the P44 probe, see A13_context.md): a nested list literal
// calls listlit again, and the inner call clears the *shared* scratch lists
// LComm/LOut and overwrites lpi/lplo -- so the outer call loses its element
// boundaries and its already-evaluated elements.  It then reads an empty LComm,
// computes lplo=1 and evaluates the tail as eval(1, hi) -> 'SyntaxError: parentheses'.
//
// Fix: save exactly the state the outer call still needs (lpi, lplo + LComm + LOut)
// across each recursive eval, on VStack, in the same LIFO discipline tuplelit uses,
// and restore it unconditionally right after eval returns (ev/evtype/error are not
// touched by the save/restore, so the element value survives).
//
// NB the three earlier attempts (P42/P43/P45) all pushed the list length BEFORE the
// elements and then read it back with `item last of VStack`, which returns the last
// ELEMENT, not the length; the mismatched `del` count wrecked VStack.  Here the
// elements are pushed in reverse and the count last, so the count really is on top.
// NB a `control_repeat_until` body runs while its condition is FALSE, so the
// count-down push loop must test NOT(i > 0), not i > 0.
patch('P46 listlit reentrant', () => {
  for (const v of ['l6n', 'l6i']) newVar(v, 0);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const pushV = (n) => addTo('VStack', VAR(n));
  const popV = (n) => [setV(n, item('VStack', llen('VStack'))), delLast('VStack')];
  // push the list contents in REVERSE order, then the count on top
  const saveL = (X) => [
    setV('l6n', llen(X)),
    setV('l6i', VAR('l6n')),
    REPEATU(NOT(GT(VAR('l6i'), num(0))), [addTo('VStack', item(X, VAR('l6i'))), chgV('l6i', num(-1))]),
    addTo('VStack', VAR('l6n'))
  ];
  // pop the count, then pop the elements back in forward order
  const restoreL = (X) => [
    setV('l6n', item('VStack', llen('VStack'))),
    delLast('VStack'),
    clearL(X),
    setV('l6i', num(1)),
    REPEATU(GT(VAR('l6i'), VAR('l6n')), [addTo(X, item('VStack', llen('VStack'))), delLast('VStack'), chgV('l6i', num(1))])
  ];
  const saveState = () => [pushV('lpi'), pushV('lplo'), ...saveL('LComm'), ...saveL('LOut')];
  const restoreState = () => [...restoreL('LOut'), ...restoreL('LComm'), ...popV('lplo'), ...popV('lpi')];
  // the error guard spells the error variable either as a data_variable block or as
  // an inline descriptor [3,[12,'error',id],[10,'']] -- accept both shapes
  const mentionsError = (desc) => {
    const seen = new Set(); const stack = [desc];
    while (stack.length) {
      const cur = stack.pop();
      if (cur === null || cur === undefined) continue;
      if (Array.isArray(cur)) {
        if (cur[0] === 12 && cur[1] === 'error') return true;
        for (const e of cur) stack.push(e);
        continue;
      }
      if (typeof cur !== 'string' || seen.has(cur)) continue;
      seen.add(cur);
      const b = BL()[cur]; if (!b) continue;
      if (b.opcode === 'data_variable' && b.fields.VARIABLE[0] === 'error') return true;
      for (const v of Object.values(b.inputs || {})) stack.push(v);
    }
    return false;
  };
  const ll = inDef('listlit %s %s');
  const evals = find(ll, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
  if (evals.length !== 2) throw new Error('[P46] expected 2 eval anchors in listlit, got ' + evals.length);
  let n = 0;
  for (const callId of evals) {
    // sanity: each anchor must be followed by the error guard, the lesc call and the LOut append
    let cur = BL()[callId].next, guard = 0, ok = false;
    while (cur && guard++ < 4) {
      const b = BL()[cur];
      if (b.opcode === 'control_if' && b.inputs.CONDITION && mentionsError(b.inputs.CONDITION[1])) ok = true;
      cur = b.next;
    }
    if (!ok) throw new Error('[P46] eval anchor ' + callId + ' has no error guard');
    insertBeforeStmt(callId, saveState());
    spliceAfter(callId, chain(restoreState()));
    n++;
  }
  console.log('[P46] listlit recursive evals protected = ' + n);
});

// ---- P47: make P34's element escaping composable (arbitrary nesting depth)
//
// P34 encodes element text as  lsep -> ESC + '1'  and listitem undoes it once per
// level.  That is NOT composable: when a list is stored inside a list, the inner
// list's own separators are already ESC+'1', and escaping the outer level leaves
// them untouched, so the single unescape at the outer level turns ALL of them back
// into lsep at once -- the middle list then looks like it has the deeper elements
// flattened into it.  Observed: a = [1, [2, [3, 4]]] prints as [1, [2, [], 3, 4]]
// and len(a[1]) is 4 instead of 2 (same with a pre-built inner list, so this is a
// second, independent root cause from the listlit one).
//
// Fix: also escape the escape character itself (ESC -> ESC + '0') when escaping,
// and decode ESC + '0' back to ESC when unescaping.  Escaping twice then yields
// ESC+'0'+'1' for a doubly nested separator, which unescapes correctly one level
// at a time.
patch('P47 composable escaping', () => {
  const chAt = (i, s) => letterOf(i, s);
  const escVar = () => VAR('lesc1');

  // class 1: lesc -- the else branch becomes  if char == ESC then out += ESC + '0' else out += char
  const en = inDef('lesc %s');
  const enIfs = find(en, (b) => b.opcode === 'control_if_else');
  if (enIfs.length !== 1) throw new Error('[P47] lesc if-else = ' + enIfs.length);
  const enElse = BL()[enIfs[0]].inputs.SUBSTACK2 ? BL()[enIfs[0]].inputs.SUBSTACK2[1] : null;
  if (typeof enElse !== 'string') throw new Error('[P47] lesc else branch missing');
  const enInner = IFELSE(EQ(chAt(VAR('lei'), argOf('v')), escVar()), [
    setV('leout', JOIN(VAR('leout'), JOIN(escVar(), txt('0'))))
  ], []);
  setStack(enInner, 'SUBSTACK2', [enElse]);
  setStack(enIfs[0], 'SUBSTACK2', [enInner]);

  // class 2: lunesc -- the ESC branch's else becomes  if next == '0' then out += ESC; i += 1 else out += char
  const de = inDef('lunesc %s');
  const deIfs = find(de, (b) => b.opcode === 'control_if_else');
  if (deIfs.length !== 2) throw new Error('[P47] lunesc if-else = ' + deIfs.length);
  let outer = null, inner = null;
  for (const id of deIfs) {
    const sub = BL()[id].inputs.SUBSTACK ? BL()[id].inputs.SUBSTACK[1] : null;
    if (typeof sub === 'string' && [...reach(sub)].some((x) => BL()[x].opcode === 'control_if_else')) outer = id;
    else inner = id;
  }
  if (!outer || !inner) throw new Error('[P47] lunesc nesting not recognised');
  const deElse = BL()[inner].inputs.SUBSTACK2 ? BL()[inner].inputs.SUBSTACK2[1] : null;
  if (typeof deElse !== 'string') throw new Error('[P47] lunesc inner else missing');
  const deInner2 = IFELSE(EQ(chAt(ADD(VAR('lei'), num(1)), argOf('v')), txt('0')), [
    setV('leout', JOIN(VAR('leout'), escVar())),
    chgV('lei', num(1))
  ], []);
  setStack(deInner2, 'SUBSTACK2', [deElse]);
  setStack(inner, 'SUBSTACK2', [deInner2]);
  console.log('[P47] escaping made composable (ESC -> ESC+0 / ESC+0 -> ESC)');
});

// ---- P48: make the dict procs reentrant (needed once P33 dict literals are on)
//
// dictlit/dictpair share the scratch list DOut and the scratch vars dgi/dglo/dged
// exactly the way listlit shared LComm/LOut (P46).  A dict literal nested inside a
// key/value expression re-enters dictlit, which clears DOut and overwrites those
// vars, so the outer pair loses its key and its loop state.  Same cure as P46:
// save the still-needed state on VStack and restore it right after the inner call.
// (Flat dicts work without this; the flat cases are the A12 row.)
patch('P48 dict reentrancy', () => {
  for (const v of ['l8n', 'l8i']) newVar(v, 0);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const pushV = (n) => addTo('VStack', VAR(n));
  const popV = (n) => [setV(n, item('VStack', llen('VStack'))), delLast('VStack')];
  const saveL = (X) => [
    setV('l8n', llen(X)),
    setV('l8i', VAR('l8n')),
    REPEATU(NOT(GT(VAR('l8i'), num(0))), [addTo('VStack', item(X, VAR('l8i'))), chgV('l8i', num(-1))]),
    addTo('VStack', VAR('l8n'))
  ];
  const restoreL = (X) => [
    setV('l8n', item('VStack', llen('VStack'))),
    delLast('VStack'),
    clearL(X),
    setV('l8i', num(1)),
    REPEATU(GT(VAR('l8i'), VAR('l8n')), [addTo(X, item('VStack', llen('VStack'))), delLast('VStack'), chgV('l8i', num(1))])
  ];
  // dictpair: a nested dict on the value side clears DOut under us
  const dp = inDef('dictpair %s %s');
  const dpEvals = find(dp, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
  if (dpEvals.length !== 2) throw new Error('[P48] dictpair evals = ' + dpEvals.length);
  for (const id of dpEvals) {
    insertBeforeStmt(id, saveL('DOut'));
    spliceAfter(id, chain(restoreL('DOut')));
  }
  // dictlit: keep the scan/loop state across each dictpair call.  NOTE: DOut must NOT be
  // saved/restored here -- dictpair's whole job is to append to it; the DOut protection
  // above lives around the two inner evals (where a nested dict really does clear it).
  const dl = inDef('dictlit %s %s');
  const dpCalls = find(dl, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'dictpair %s %s');
  if (dpCalls.length !== 2) throw new Error('[P48] dictlit dictpair calls = ' + dpCalls.length);
  for (const id of dpCalls) {
    insertBeforeStmt(id, [pushV('dgi'), pushV('dglo'), pushV('dged')]);
    spliceAfter(id, chain([...popV('dged'), ...popV('dglo'), ...popV('dgi')]));
  }
  console.log('[P48] dict state protected at ' + (dpEvals.length + dpCalls.length) + ' sites');
});

// ---- P49: chained subscripts  a[0][1]  (indexget assumed a one-token base)
//
// indexget lo hi used to evaluate its base with `eval(lo, lo)`, which is right only
// when the base is a single token.  For a[0][1] the base expression is `a[0]`, so the
// old code indexed the *whole* list with the bogus range `0][1`.  Fix: walk backwards
// from the final ']' to find the '[' that opens the outermost subscript (xbr), then
// base = eval(lo, xbr-1) and the index/slice range starts at xbr+1.  For a simple
// a[i] this is identical to the old behaviour (xbr = lo+1).
patch('P49 chained subscript', () => {
  for (const v of ['xbr', 'xdep', 'xj']) newVar(v, 0);
  const ig = inDef('indexget %s %s');
  const isArgRep = (desc, name) => {
    if (!desc || desc[0] !== 3 || typeof desc[1] !== 'string') return false;
    const b = BL()[desc[1]];
    return !!b && b.opcode === 'argument_reporter_string_number' && b.fields.VALUE[0] === name;
  };
  const isLit = (desc, n) => Array.isArray(desc[1]) && desc[1][0] === 4 && String(desc[1][1]) === String(n);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  // 1) insert the backward bracket scan right after the base type guard
  // the scan must run BEFORE the base eval: that eval is what uses xbr
  const baseEval = find(ig, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'eval %s %s') return false;
    const ids = JSON.parse(b.mutation.argumentids);
    return isArgRep(b.inputs[ids[0]], 'lo') && isArgRep(b.inputs[ids[1]], 'lo');
  });
  if (baseEval.length !== 1) throw new Error('[P49] indexget base eval = ' + baseEval.length);
  // indexget's body starts with that eval, so splice the scan in at the head manually
  const igDef = defIdOf('indexget %s %s');
  const head = BL()[igDef].next;
  if (head !== baseEval[0]) throw new Error('[P49] base eval is not the first statement of indexget');
  const scanHead = chain([
    setV('xdep', num(1)),
    setV('xj', SUB(argOf('hi'), num(1))),
    REPEATU(OR(LT(VAR('xj'), ADD(argOf('lo'), num(1))), EQ(VAR('xdep'), num(0))), [
      setV('eop', item('Tok', VAR('xj'))),
      IF(OR(EQ(VAR('eop'), txt(']')), EQ(VAR('eop'), txt(')'))), [chgV('xdep', num(1))]),
      IF(OR(EQ(VAR('eop'), txt('[')), EQ(VAR('eop'), txt('('))), [chgV('xdep', num(-1))]),
      chgV('xj', num(-1))
    ]),
    setV('xbr', ADD(VAR('xj'), num(1))),
    // the base eval below is itself an indexget when the subscript is chained,
    // and that inner call overwrites xbr -- keep ours on VStack
    addTo('VStack', VAR('xbr'))
  ]);
  {
    BL()[igDef].next = scanHead;
    BL()[scanHead].parent = igDef;
    let t = scanHead;
    while (BL()[t].next) t = BL()[t].next;
    BL()[t].next = head;
    BL()[head].parent = t;
  }
  // 2) the base expression is everything left of that bracket
  {
    const b = BL()[baseEval[0]];
    const ids = JSON.parse(b.mutation.argumentids);
    replaceExpr(b.inputs[ids[1]][1], () => SUB(VAR('xbr'), num(1)));
  }
  // 2b) restore our xbr once the base has been evaluated
  insertBeforeStmt(BL()[baseEval[0]].next, [setV('xbr', item('VStack', llen('VStack'))), delLast('VStack')]);
  // 3) the index expression / slice scan starts after that bracket
  const adds = find(ig, (b) => b.opcode === 'operator_add' && isArgRep(b.inputs.NUM1, 'lo') && isLit(b.inputs.NUM2, 2));
  // base indexget has 5 such sites (xi = lo+2, the list-index eval, the string-index eval,
  // xcol > lo+2, the slice-lo eval); P33 adds one or two more inside its dict-key branch.
  // All of them sit in indexget's body, after xbr is computed, so xbr+1 is right for each.
  if (adds.length < 5 || adds.length > 8) throw new Error('[P49] unexpected lo+2 sites = ' + adds.length);
  for (const id of adds) replaceExpr(id, () => ADD(VAR('xbr'), num(1)));
  console.log('[P49] chained subscripts installed (base eval + ' + adds.length + ' index ranges)');
});

// ---- P51: try / except (+ raise)  [gap row A5]
//
// Architecture facts this patch relies on:
//  * prepare() computes per line:  Ends[line] = first line after the block,
//    Elses[line] = a same-indent else/elif/except/finally line that follows it.
//  * execute() is a flat chain of `if head == ...` branches; it leaves the next
//    line in `dest` and only commits it when `error == ''` (so a failed statement
//    does not advance pc).
//  * two drivers call execute(): the main RUN loop and calluser (function bodies).
//
// Design: `try:` pushes a catch frame (handler line, handler end, exception name,
// LoopHead depth); `except:` on the normal path pops the frame and jumps past the
// handler; a new trycatch proc is called right after each execute() and, when an
// error is set, matches it against the frame, clears it and jumps into the handler.
patch('P51 try except raise', () => {
  for (const v of ['tpc', 'tnm', 'tcl', 'tpl', 'tms', 'tsv', 'tlast']) newVar(v, 0);
  for (const l of ['TryHand', 'TryEnd', 'TryName', 'TryLoop', 'TryC']) B.addList(IT, l, []);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const last = (list) => item(list, llen(list));
  const lenTok = () => I('data_lengthoflist', { fields: B.LISTF('Tok') });
  const tokAt = (i) => item('Tok', i);
  const pop4 = () => [delLast('TryHand'), delLast('TryEnd'), delLast('TryName'), delLast('TryLoop'), delLast('TryC')];

  // ---------- helpers for finding comparison chains
  const varNameOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
    const b = (typeof d[1] === 'string') ? BL()[d[1]] : null;
    return b && b.opcode === 'data_variable' ? b.fields.VARIABLE[0] : null;
  };
  // literals appear in both encodings: [1,[10,'def']] and the raw [10,'def']
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const isTokOne = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    if (!b || b.opcode !== 'data_itemoflist') return false;
    if (!b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
    const ix = b.inputs.INDEX;
    if (!ix) return false;
    if (Array.isArray(ix) && ix[0] === 4) return String(ix[1]) === '1';
    return Array.isArray(ix[1]) && ix[1][0] === 4 && String(ix[1][1]) === '1';
  };
  const eqTo = (d, word) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    if (!b || b.opcode !== 'operator_equals') return false;
    return (varNameOf(b.inputs.OPERAND1) === word && litOf(b.inputs.OPERAND2) === word)
        || (varNameOf(b.inputs.OPERAND2) === word && litOf(b.inputs.OPERAND1) === word);
  };
  const hasVarEq = (orId, word, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    return (varNameOf(b.inputs.OPERAND1) === word && litOf(b.inputs.OPERAND2) === lit)
        || (varNameOf(b.inputs.OPERAND2) === word && litOf(b.inputs.OPERAND1) === lit);
  });
  // the Elses chain is the one comparing a Tok item against 'else'
  const isItemBlock = (d) => {
    const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return !!bb && bb.opcode === 'data_itemoflist';
  };
  const hasTokEq = (orId, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return ((isItemBlock(a) && litOf(c) === lit) || (isItemBlock(c) && litOf(a) === lit));
  });

  // ---------- 1) prepare(): try / except count as block heads, except as an else-like clause
  const prep = inDef('prepare');
  // find() hands us (block, id) -- the helpers need the ID, not the block object
  // only the *inner* head chain -- the enclosing condition wraps it in not(...) and
  // patching that one would make try/except count as 'unexpected indent'
  const notFree = (id) => ![...reach(id)].some((x) => BL()[x].opcode === 'operator_not');
  const headChains = find(prep, (b, id) => b.opcode === 'operator_or' && hasVarEq(id, 'prevhead', 'def') && notFree(id));
  // the chains nest, so keep only the outermost block of each site
  const elsesChains = headChains.filter((id) => hasTokEq(id, 'else'));
  const headAll = headChains.filter((id) => !hasTokEq(id, 'else'));
  const plainChains = headAll.filter((id) => !headAll.some((o) => o !== id && reach(o).has(id)));
  if (!plainChains.length || elsesChains.length !== 1) throw new Error('[P51] prepare chains: head=' + plainChains.length + ' else=' + elsesChains.length);
  if (elsesChains.length !== 1) throw new Error('[P51] prepare else chains = ' + elsesChains.length + ' (expected 1)');
  for (const id of plainChains) {
    replaceExpr(id, () => OR(OR(id, EQ(VAR('prevhead'), txt('try'))), EQ(VAR('prevhead'), txt('except'))));
  }
  for (const id of elsesChains) {
    replaceExpr(id, () => OR(OR(id, EQ(tokAt(num(1)), txt('except'))), EQ(tokAt(num(1)), txt('finally'))));
  }
  console.log('[P51] prepare: ' + plainChains.length + ' head chains + ' + elsesChains.length + ' else chain patched');

  // ---------- 2) execute(): new statement branches, inserted before the `for` branch
  const ex = inDef('execute');
  const forIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && hasVarEq(b.inputs.CONDITION[1], 'head', 'for'));
  if (forIf.length !== 1) throw new Error('[P51] execute for-branch = ' + forIf.length);
  const tryBranch = IF(EQ(VAR('head'), txt('try')), [
    setV('tpc', item('Elses', VAR('pc'))),
    IF(EQ(VAR('tpc'), num(0)), [FAIL('SyntaxError: try without except')]),
    IF(NOT(EQ(VAR('tpc'), num(0))), [
      callProc('tokenize %s', [item('Code', VAR('tpc'))]),
      setV('tnm', txt('')),
      IF(GT(lenTok(), num(2)), [setV('tnm', tokAt(num(2)))]),
      addTo('TryHand', ADD(VAR('tpc'), num(1))),
      addTo('TryEnd', item('Ends', VAR('tpc'))),
      addTo('TryName', VAR('tnm')),
      addTo('TryLoop', llen('LoopHead')),
      addTo('TryC', VAR('cdepth')),
      // tokenize() rewrote Tok/ count for the except line -- put our own line back
      callProc('tokenize %s', [item('Code', VAR('pc'))]),
      setV('count', lenTok())
    ]),
    setV('pending', num(1))
  ]);
  const exceptBranch = IF(EQ(VAR('head'), txt('except')), [
    IFELSE(AND(GT(llen('TryEnd'), num(0)), EQ(ADD(VAR('pc'), num(1)), last('TryHand'))), [
      // normal completion of our try body: skip past the whole handler
      setV('dest', last('TryEnd')),
      ...pop4()
    ], [
      // a following handler clause (or a stray except): never a statement to run
      setV('dest', item('Ends', VAR('pc')))
    ]),
    setV('pending', num(1))
  ]);
  const raiseBranch = IF(EQ(VAR('head'), txt('raise')), [
    setV('tms', txt('')),
    setV('tnm', txt('')),
    IF(GT(VAR('count'), num(1)), [
      setV('tnm', tokAt(num(2))),
      IF(EQ(tokAt(num(3)), txt('(')), [
        callProc('eval %s %s', [num(4), SUB(VAR('count'), num(1))]),
        IF(EQ(VAR('error'), txt('')), [callProc('strval %s %s', [VAR('ev'), VAR('evtype')]), setV('tms', VAR('ev'))])
      ])
    ]),
    IFELSE(EQ(VAR('tnm'), txt('')), [
      IFELSE(EQ(VAR('tlast'), txt('')), [FAIL('RuntimeError: No active exception to re-raise')], [FAILB(VAR('tlast'))])
    ], [
      FAILB(JOIN(JOIN(VAR('tnm'), txt(': ')), VAR('tms')))
    ]),
    setV('pending', num(1))
  ]);
  insertBeforeStmt(forIf[0], [tryBranch, exceptBranch, raiseBranch]);
  console.log('[P51] execute: try/except/raise branches installed');

  // ---------- 3) trycatch(): called by both drivers right after execute()
  const tc = newProc('trycatch', []);
  attachBody(tc.defId, [
    IF(NOT(EQ(VAR('error'), txt(''))), [
      // walk outward: a frame whose name does not match can never run a handler,
      // so discard it and let an outer try catch the error instead
      REPEATU(OR(EQ(VAR('error'), txt('')), OR(EQ(llen('TryHand'), num(0)), NOT(EQ(VAR('cdepth'), last('TryC'))))), [
        setV('tnm', last('TryName')),
        setV('tpl', last('TryLoop')),
        REPEATU(NOT(GT(llen('LoopHead'), VAR('tpl'))), [callProc('popLoop')]),
        setV('tcl', num(0)),
        IFELSE(EQ(VAR('tnm'), txt('')), [setV('tcl', num(1))], [
          IFELSE(EQ(VAR('tnm'), txt('Exception')), [setV('tcl', num(1))], [
            // messages look like 'IndexError: ...' but ZeroDivisionError is bare,
            // so the test is a plain startswith(name)
            callProc('sprefix %s %s %s', [VAR('error'), VAR('tnm'), txt('startswith')]),
            IF(EQ(VAR('ev'), num(1)), [setV('tcl', num(1))])
          ])
        ]),
        IF(EQ(VAR('tcl'), num(1)), [
          setV('tlast', VAR('error')),
          setV('error', txt('')),
          setV('pc', last('TryHand'))
        ]),
        ...pop4()
      ])
    ])
  ]);
  let hooked = 0;
  for (const id of allIds()) {
    const b = BL()[id];
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'execute') continue;
    spliceAfter(id, chain([callProc('trycatch')]));
    hooked++;
  }
  if (hooked !== 2) throw new Error('[P51] execute call sites = ' + hooked + ' (expected 2)');
  console.log('[P51] trycatch hooked after ' + hooked + ' execute() calls');

  // ---------- 4) reset the frame lists at the start of every run
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P51] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [clearL('TryHand'), clearL('TryEnd'), clearL('TryName'), clearL('TryLoop'), clearL('TryC')]);
  console.log('[P51] try/except ready');
});

// ---- P52: generators -- `def f(): yield ...` + list()  [gap row A8]
//
// The interpreter drives a function body line by line through calluser's loop, so a
// suspended generator frame would need (pc + locals + loop stack) kept alive across
// calls.  This patch takes the pragmatic route the surrounding code already uses for
// other limits: a generator function is detected at def time (its body contains the
// `yield` token), and calling it runs the body eagerly, collecting every yielded
// value into GYield; the call returns that collection tagged 'G'.
//
// That is exact for the common teaching shapes -- list(gen()), sum(gen()), len(gen()),
// generators over range(), yields of strings and of nested lists -- but it is NOT a
// real coroutine: values are produced eagerly, so infinite/lazy generators and
// side-effect interleaving are out of scope (documented in the release notes).
//
// Also adds the missing `list()` builtin (nothing in v4.26 provided it).
patch('P52 generators', () => {
  for (const v of ['gy', 'gk', 'gci', 'gan', 'gat']) newVar(v, 0);
  for (const l of ['GYield', 'LConv']) B.addList(IT, l, []);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const setLast = (list, v) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(llen(list), [4, '0']), ITEM: B.REP(v, [4, '0']) } });
  const lenTok = () => I('data_lengthoflist', { fields: B.LISTF('Tok') });
  const varNameOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
    const b = (typeof d[1] === 'string') ? BL()[d[1]] : null;
    return b && b.opcode === 'data_variable' ? b.fields.VARIABLE[0] : null;
  };
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const eqConst = (orId, name, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (varNameOf(a) === name && litOf(c) === lit) || (varNameOf(c) === name && litOf(a) === lit);
  });
  // `item N of FnKind` and argument reporters need their own shapes
  const itemListOf = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return b && b.opcode === 'data_itemoflist' && b.fields.LIST ? b.fields.LIST[0] : null;
  };
  const argNameOf = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null;
  };
  const eqItem = (orId, listName, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (itemListOf(a) === listName && litOf(c) === lit) || (itemListOf(c) === listName && litOf(a) === lit);
  });
  const isTok2Bracket = (orId) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    const itemOfTok2 = (d) => {
      const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      if (!bb || bb.opcode !== 'data_itemoflist' || !bb.fields.LIST || bb.fields.LIST[0] !== 'Tok') return false;
      const ix = bb.inputs.INDEX;
      return (Array.isArray(ix) && ix[0] === 4 && String(ix[1]) === '2') || (Array.isArray(ix[1]) && ix[1][0] === 4 && String(ix[1][1]) === '2');
    };
    return (itemOfTok2(a) && litOf(c) === '[') || (itemOfTok2(c) && litOf(a) === '[');
  });
  const eqArg = (orId, name, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (argNameOf(a) === name && litOf(c) === lit) || (argNameOf(c) === name && litOf(a) === lit);
  });

  // ---------- 1) regdef: mark generator functions (body contains `yield`)
  const rd = inDef('regdef %s');
  const kindAppend = find(rd, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'FnKind');
  if (kindAppend.length !== 1) throw new Error('[P52] FnKind append = ' + kindAppend.length);
  insertBeforeStmt(kindAppend[0], [
    setV('gy', num(0)),
    setV('gk', ADD(VAR('pc'), num(1))),
    REPEATU(OR(GT(VAR('gk'), SUB(item('Ends', VAR('pc')), num(1))), EQ(VAR('gy'), num(1))), [
      callProc('tokenize %s', [item('Code', VAR('gk'))]),
      setV('gci', num(1)),
      REPEATU(GT(VAR('gci'), lenTok()), [
        IF(EQ(item('Tok', VAR('gci')), txt('yield')), [setV('gy', num(1))]),
        chgV('gci', num(1))
      ]),
      chgV('gk', num(1))
    ]),
    callProc('tokenize %s', [item('Code', VAR('pc'))])
  ]);
  spliceAfter(kindAppend[0], chain([
    IF(EQ(VAR('gy'), num(1)), [setLast('FnKind', txt('G'))])
  ]));
  console.log('[P52] regdef marks generator functions');

  // ---------- 2) execute: the yield statement collects into GYield
  const ex = inDef('execute');
  const forIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqConst(b.inputs.CONDITION[1], 'head', 'for'));
  if (forIf.length !== 1) throw new Error('[P52] execute for-branch = ' + forIf.length);
  insertBeforeStmt(forIf[0], [
    IF(EQ(VAR('head'), txt('yield')), [
      IFELSE(EQ(VAR('cdepth'), num(0)), [FAIL('SyntaxError: yield outside function')], [
        IFELSE(GT(VAR('count'), num(1)), [
          callProc('eval %s %s', [num(2), VAR('count')])
        ], [
          setV('ev', txt('')), setV('evtype', txt('Z'))
        ]),
        IF(EQ(VAR('error'), txt('')), [
          callProc('lesc %s', [VAR('ev')]),
          addTo('GYield', JOIN(JOIN(VAR('lsep'), VAR('evtype')), VAR('ev')))
        ])
      ]),
      setV('pending', num(1))
    ])
  ]);
  // `yield [1, 2]` used to be hijacked by the indexset branch (Kind[1]=='I' and Tok[2]=='[')
  const idxIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && eqItem(b.inputs.CONDITION[1], 'Kind', 'I') && isTok2Bracket(b.inputs.CONDITION[1]));
  if (idxIf.length !== 1) throw new Error('[P52] indexset branch = ' + idxIf.length);
  replaceExpr(BL()[idxIf[0]].inputs.CONDITION[1], () => AND(BL()[idxIf[0]].inputs.CONDITION[1], EQ(VAR('pending'), num(0))));
  console.log('[P52] execute: yield branch installed');

  // ---------- 3) calluser: clear the collector, then hand back the collected values
  const cu = inDef('calluser %s %s %s');
  const kindLIf = find(cu, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqItem(b.inputs.CONDITION[1], 'FnKind', 'L'));
  if (kindLIf.length !== 1) throw new Error('[P52] calluser FnKind L branch = ' + kindLIf.length);
  const sub2 = BL()[kindLIf[0]].inputs.SUBSTACK2 ? BL()[kindLIf[0]].inputs.SUBSTACK2[1] : null;
  if (typeof sub2 !== 'string') throw new Error('[P52] calluser body branch missing');
  insertBeforeStmt(sub2, [clearL('GYield')]);
  const zeroRetIf = find(cu, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqConst(b.inputs.CONDITION[1], 'retflag', '0'));
  if (zeroRetIf.length !== 1) throw new Error('[P52] calluser retflag branch = ' + zeroRetIf.length);
  spliceAfter(zeroRetIf[0], chain([
    IF(EQ(item('FnKind', VAR('fi')), txt('G')), [
      setV('gan', txt('')),
      setV('gci', num(1)),
      REPEATU(GT(VAR('gci'), llen('GYield')), [setV('gan', JOIN(VAR('gan'), item('GYield', VAR('gci')))), chgV('gci', num(1))]),
      setV('ev', VAR('gan')),
      setV('evtype', txt('G'))
    ])
  ]));
  console.log('[P52] calluser: generator result assembly installed');

  // ---------- 4) callfn: the list() builtin, and let len()/sum() see generators
  const cf = inDef('callfn %s %s %s');
  const strIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqArg(b.inputs.CONDITION[1], 'fn', 'str'));
  if (strIf.length !== 1) throw new Error('[P52] callfn str branch = ' + strIf.length);
  insertBeforeStmt(strIf[0], [
    IF(EQ(argOf('fn'), txt('list')), [
      IFELSE(OR(OR(EQ(VAR('evtype'), txt('L')), EQ(VAR('evtype'), txt('T'))), EQ(VAR('evtype'), txt('G'))), [
        setV('evtype', txt('L'))
      ], [
        IFELSE(EQ(VAR('evtype'), txt('S')), [
          // lesc() writes into ev, so the source string must live elsewhere
          setV('gan', VAR('ev')),
          clearL('LConv'),
          setV('gci', num(1)),
          REPEATU(GT(VAR('gci'), lenOf(VAR('gan'))), [
            callProc('lesc %s', [letterOf(VAR('gci'), VAR('gan'))]),
            addTo('LConv', JOIN(JOIN(VAR('lsep'), txt('S')), VAR('ev'))),
            chgV('gci', num(1))
          ]),
          setV('gat', txt('')),
          setV('gci', num(1)),
          REPEATU(GT(VAR('gci'), llen('LConv')), [setV('gat', JOIN(VAR('gat'), item('LConv', VAR('gci')))), chgV('gci', num(1))]),
          setV('ev', VAR('gat')),
          setV('evtype', txt('L'))
        ], [
          FAIL('TypeError: list() requires an iterable')
        ])
      ]),
      setV('pending', num(1))
    ])
  ]);
  // widen the (evtype == 'L' or evtype == 'T') tests of len() and sum() to accept G
  const etChains = find(cf, (b, id) => b.opcode === 'operator_or' && eqConst(id, 'evtype', 'L') && eqConst(id, 'evtype', 'T'));
  if (etChains.length < 2) throw new Error('[P52] evtype chains = ' + etChains.length);
  for (const id of etChains) replaceExpr(id, () => OR(id, EQ(VAR('evtype'), txt('G'))));
  console.log('[P52] list() builtin + ' + etChains.length + ' evtype tests widened');

  // ---------- 5) reset the new lists at run start
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P52] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [clearL('GYield'), clearL('LConv')]);
  console.log('[P52] generators ready');
});

// ---- P54: list aliasing  x = y = [0]; x[0] = 1; print(y) -> [1]   [gap row B5]
//
// Values are strings, so `x = y = [0]` stores two copies of the same list text and a
// later x[0]=1 only rewrites x.  Full object identity would mean a heap table keyed by
// id -- far too invasive here.  Instead mimic the observable behaviour:
//   * record `T aliases S` when a plain variable-to-variable assignment carries a list
//     (y = x) and when a chained assignment hands the same list to several names;
//   * every in-place mutation ends with assign(name, newtext, 'L'), so propagating to
//     the alias targets inside assign() covers indexset/indexdel/methodcall/slicewrite;
//   * a rebinding assignment (execute's `name = expr`, assignlist) drops the name's
//     alias entries first, so `x = [5]` leaves y pointing at the old list, as in Python.
// Out of scope (documented): aliases through function arguments, through container
// elements (b = a[0]), and augmented assignment.
patch('P54 list aliasing', () => {
  for (const v of ['ali', 'aln', 'alz', 'alT', 'alT2', 'alS', 'ald']) newVar(v, 0);
  for (const l of ['AliasN', 'AliasT']) B.addList(IT, l, []);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const delAt = (list, idx) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']) } });
  const at = (list, idx) => item(list, idx);
  const tokAt = (i) => item('Tok', i);

  // ---------- procs
  const ad = newProc('aldrop %s', ['vn']);
  attachBody(ad.defId, [
    setV('ali', num(1)),
    REPEATU(GT(VAR('ali'), llen('AliasN')), [
      IFELSE(OR(EQ(at('AliasN', VAR('ali')), argOf('vn')), EQ(at('AliasT', VAR('ali')), argOf('vn'))), [
        delAt('AliasN', VAR('ali')),
        delAt('AliasT', VAR('ali'))
      ], [
        chgV('ali', num(1))
      ])
    ])
  ]);
  const ar = newProc('alrec %s %s', ['target', 'src']);
  attachBody(ar.defId, [
    callProc('aldrop %s', [argOf('target')]),
    setV('ali', num(1)),
    REPEATU(GT(VAR('ali'), llen('AliasN')), [
      IFELSE(AND(EQ(at('AliasN', VAR('ali')), argOf('target')), EQ(at('AliasT', VAR('ali')), argOf('src'))), [
        delAt('AliasN', VAR('ali')),
        delAt('AliasT', VAR('ali'))
      ], [
        chgV('ali', num(1))
      ])
    ]),
    addTo('AliasN', argOf('src')),
    addTo('AliasT', argOf('target'))
  ]);

  // ---------- assign(): propagate a list value to every name that aliases this one
  const asg = inDef('assign %s %s %s');
  const ifElse = find(asg, (b) => b.opcode === 'control_if_else');
  if (ifElse.length !== 1) throw new Error('[P54] assign if-else = ' + ifElse.length);
  spliceAfter(ifElse[0], chain([
    IF(AND(EQ(argOf('vt'), txt('L')), LT(VAR('ald'), num(3))), [
      // ping-pong between a and b is stopped by the depth guard; two levels cover
      // chains like c -> b -> a
      chgV('ald', num(1)),
      callProc('lookup %s', [argOf('vn')]),
      IF(NOT(EQ(VAR('found'), num(0))), [
        setV('alS', item('Values', VAR('found'))),
        setV('alT2', item('Types', VAR('found'))),
        setV('ali', num(1)),
        setV('aln', llen('AliasN')),
        REPEATU(GT(VAR('ali'), VAR('aln')), [
          // both directions: y = x then mutating either name must update the other
          IF(OR(EQ(at('AliasN', VAR('ali')), argOf('vn')), EQ(at('AliasT', VAR('ali')), argOf('vn'))), [
            setV('alT', at('AliasT', VAR('ali'))),
            IF(EQ(VAR('alT'), argOf('vn')), [setV('alT', at('AliasN', VAR('ali')))]),
            // the nested assign reuses our scratch vars -- keep the loop state
            addTo('VStack', VAR('ali')),
            addTo('VStack', VAR('aln')),
            callProc('assign %s %s %s', [VAR('alT'), VAR('alS'), VAR('alT2')]),
            setV('aln', item('VStack', llen('VStack'))),
            delLast('VStack'),
            setV('ali', item('VStack', llen('VStack'))),
            delLast('VStack')
          ]),
          chgV('ali', num(1))
        ])
      ]),
      chgV('ald', num(-1))
    ])
  ]));
  console.log('[P54] assign propagates list aliases');

  // ---------- execute(): `y = x` records an alias, and a rebind drops stale ones
  const ex = inDef('execute');
  const eqTok = (orId, idx, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const itemOf = (d, want) => {
      const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      if (!bb || bb.opcode !== 'data_itemoflist' || !bb.fields.LIST || bb.fields.LIST[0] !== 'Tok') return false;
      const ix = bb.inputs.INDEX;
      return (Array.isArray(ix) && ix[0] === 4 && String(ix[1]) === String(want)) || (Array.isArray(ix[1]) && ix[1][0] === 4 && String(ix[1][1]) === String(want));
    };
    const litOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
      if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
      return null;
    };
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (itemOf(a, idx) && litOf(c) === lit) || (itemOf(c, idx) && litOf(a) === lit);
  });
  const eqCands = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqTok(b.inputs.CONDITION[1], 2, '='));
  // two branches compare Tok[2] with '='; the plain assignment is the one that calls assign itself
  const inSub = (id) => (BL()[id].inputs.SUBSTACK && typeof BL()[id].inputs.SUBSTACK[1] === 'string') ? reach(BL()[id].inputs.SUBSTACK[1]) : new Set();
  const asgBranch = eqCands.filter((id) => [...inSub(id)].some((x) => {
    const b = BL()[x];
    return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'assign %s %s %s';
  }));
  if (asgBranch.length !== 1) throw new Error('[P54] execute assignment branch = ' + asgBranch.length + ' (cands ' + eqCands.length + ')');
  const callIn = (hostId, proccode) => find(inSub(hostId), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === proccode);
  const asgCalls = callIn(asgBranch[0], 'assign %s %s %s');
  if (asgCalls.length !== 1) throw new Error('[P54] assignment assign call = ' + asgCalls.length);
  insertBeforeStmt(asgCalls[0], [callProc('aldrop %s', [VAR('name')])]);
  spliceAfter(asgCalls[0], chain([
    IF(AND(EQ(VAR('evtype'), txt('L')), AND(EQ(VAR('count'), num(3)), EQ(tokAt(num(3)), tokAt(num(3))))), [
      callProc('alrec %s %s', [VAR('name'), tokAt(num(3))])
    ])
  ]));
  console.log('[P54] execute records y = x aliases');

  // ---------- assignlist(): chained x = y = <list> aliases all names to the first
  const al = inDef('assignlist %s');
  const alAssign = find(al, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'assign %s %s %s');
  if (alAssign.length !== 1) throw new Error('[P54] assignlist assign call = ' + alAssign.length);
  insertBeforeStmt(alAssign[0], [callProc('aldrop %s', [at('AName', VAR('mi'))])]);
  const alLoop = find(al, (b) => b.opcode === 'control_repeat_until' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => x === alAssign[0]));
  if (alLoop.length !== 1) throw new Error('[P54] assignlist loop = ' + alLoop.length);
  const loopId = alLoop[0];
  spliceAfter(loopId, chain([
    IF(AND(EQ(at('AType', num(1)), txt('L')), GT(llen('AName'), num(1))), [
      // alrec/aldrop reset `ali`, so this loop counts in `alz`
      setV('alz', num(2)),
      REPEATU(GT(VAR('alz'), llen('AName')), [
        callProc('alrec %s %s', [at('AName', VAR('alz')), at('AName', num(1))]),
        chgV('alz', num(1))
      ])
    ])
  ]));
  console.log('[P54] assignlist records chained aliases');

  // ---------- reset
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P54] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [clearL('AliasN'), clearL('AliasT')]);
  console.log('[P54] aliasing ready');
});

// ---- P55: classes -- class A: / __init__ / methods / self.attr   [gap row A4]
//
// Minimal object model that fits the string-encoded value scheme:
//   * `class A:` registers every `def` in its body as a *function* named A.m
//     (lookup/calluser/regdef then do the work); curcls marks it as a method so the
//     leading `self` parameter is dropped from its recorded signature;
//   * an instance is a small integer id -- its class is InstCls[id], its attributes
//     are rows of IAttrId/IAttrName/IAttrVal/IAttrType;
//   * `A(5)` constructs: callfn sees a class name, allocates the id, binds `self`,
//     runs A.__init__ when present, and returns the id with type 'O';
//   * `obj.m(args)` -> methodcall (guard widened to 'O') -> callmeth -> calluser;
//   * `self.v` reads through a new eval branch, `self.v = x` through a new execute
//     branch.
// Not supported (documented): inheritance, class attributes, __repr__, bound-method
// values, attribute access on list elements (a[0].v), operators on instances.
patch('P55 classes', () => {
  for (const v of ['iid', 'cfull', 'ccls', 'ck', 'cax', 'cax2', 'cX', 'clf', 'self', 'mdot', 'mdep', 'mk']) newVar(v, 0);
  // NB: 0 == '' is FALSE in scratch-vm, so string-valued flags must start as ''
  newVar('curcls', '');
  for (const l of ['ClsName', 'InstCls', 'IAttrId', 'IAttrName', 'IAttrVal', 'IAttrType']) B.addList(IT, l, []);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const delAt = (list, idx) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']) } });
  const at = (list, idx) => item(list, idx);
  const setAt = (list, idx, v) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(v, [4, '0']) } });
  const tokAt = (i) => item('Tok', i);
  const lcont = (listName) => I('data_listcontents', { fields: B.LISTF(listName) });
  const contains = (listName, v) => I('operator_contains', { inputs: { STRING1: B.REP(lcont(listName), [10, '']), STRING2: B.REP(v, [10, '']) } });
  const varNameOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
    const b = (typeof d[1] === 'string') ? BL()[d[1]] : null;
    return b && b.opcode === 'data_variable' ? b.fields.VARIABLE[0] : null;
  };
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const eqConst = (orId, name, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (varNameOf(a) === name && litOf(c) === lit) || (varNameOf(c) === name && litOf(a) === lit);
  });
  const hasVarEq = eqConst;
  const callsProc = (rootId, proccode) => [...reach(rootId)].some((x) => {
    const b = BL()[x];
    return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === proccode;
  });
  const subOf = (id) => (BL()[id].inputs.SUBSTACK && typeof BL()[id].inputs.SUBSTACK[1] === 'string') ? BL()[id].inputs.SUBSTACK[1] : null;

  // ---------- 1) prepare(): class is a block head
  const prep = inDef('prepare');
  const notFree = (id) => ![...reach(id)].some((x) => BL()[x].opcode === 'operator_not');
  const headAll = find(prep, (b, id) => b.opcode === 'operator_or' && hasVarEq(id, 'prevhead', 'def') && notFree(id));
  const headChains = headAll.filter((id) => !headAll.some((o) => o !== id && reach(o).has(id)));
  if (!headChains.length) throw new Error('[P55] prepare head chains = 0');
  for (const id of headChains) replaceExpr(id, () => OR(id, EQ(VAR('prevhead'), txt('class'))));
  console.log('[P55] prepare: class is a block head (' + headChains.length + ' chains)');

  // ---------- 2) regdef(): a method loses its leading `self` parameter
  const rd = inDef('regdef %s');
  const pnAppend = find(rd, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'FnPN');
  if (pnAppend.length !== 1) throw new Error('[P55] FnPN append = ' + pnAppend.length);
  insertBeforeStmt(pnAppend[0], [
    IF(NOT(EQ(VAR('curcls'), txt(''))), [delAt('DefPar', num(1)), delAt('DefDef', num(1))])
  ]);
  console.log('[P55] regdef: methods drop self from the signature');

  // ---------- 3) execute(): class statement + `self.v = expr`
  const ex = inDef('execute');
  const forIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqConst(b.inputs.CONDITION[1], 'head', 'for'));
  if (forIf.length !== 1) throw new Error('[P55] execute for-branch = ' + forIf.length);
  const classBranch = IF(EQ(VAR('head'), txt('class')), [
    IF(NOT(EQ(tokAt(num(3)), txt(':'))), [FAIL('SyntaxError: class Name:')]),
    setV('ccls', tokAt(num(2))),
    addTo('ClsName', VAR('ccls')),
    setV('ck', ADD(VAR('pc'), num(1))),
    REPEATU(OR(GT(VAR('ck'), SUB(item('Ends', VAR('pc')), num(1))), NOT(EQ(VAR('error'), txt('')))), [
      callProc('tokenize %s', [item('Code', VAR('ck'))]),
      setV('count', I('data_lengthoflist', { fields: B.LISTF('Tok') })),
      IF(EQ(tokAt(num(1)), txt('def')), [
        setV('cax', VAR('pc')),
        setV('pc', VAR('ck')),
        setV('curcls', VAR('ccls')),
        callProc('regdef %s', [JOIN(JOIN(VAR('ccls'), txt('.')), tokAt(num(2)))]),
        setV('curcls', txt('')),
        setV('pc', VAR('cax'))
      ]),
      chgV('ck', num(1))
    ]),
    callProc('tokenize %s', [item('Code', VAR('pc'))]),
    setV('dest', item('Ends', VAR('pc'))),
    setV('pending', num(1))
  ]);
  const attrSetBranch = IF(AND(EQ(tokAt(num(2)), txt('.')), AND(EQ(tokAt(num(4)), txt('=')), EQ(item('Kind', num(1)), txt('I')))), [
    callProc('lookup %s', [tokAt(num(1))]),
    IFELSE(AND(NOT(EQ(VAR('found'), num(0))), EQ(item('Types', VAR('found')), txt('O'))), [
      setV('iid', item('Values', VAR('found'))),
      callProc('eval %s %s', [num(5), VAR('count')]),
      setV('cax', VAR('ev')),
      setV('cax2', VAR('evtype')),
      setV('cX', num(0)),
      setV('ck', num(1)),
      REPEATU(GT(VAR('ck'), llen('IAttrId')), [
        IF(AND(EQ(at('IAttrId', VAR('ck')), VAR('iid')), EQ(at('IAttrName', VAR('ck')), tokAt(num(3)))), [
          setV('cX', VAR('ck')),
          setV('ck', llen('IAttrId'))
        ]),
        chgV('ck', num(1))
      ]),
      IFELSE(EQ(VAR('cX'), num(0)), [
        addTo('IAttrId', VAR('iid')),
        addTo('IAttrName', tokAt(num(3))),
        addTo('IAttrVal', VAR('cax')),
        addTo('IAttrType', VAR('cax2'))
      ], [
        setAt('IAttrVal', VAR('cX'), VAR('cax')),
        setAt('IAttrType', VAR('cX'), VAR('cax2'))
      ])
    ], [
      FAIL('AttributeError: only instances have attributes')
    ]),
    setV('pending', num(1))
  ]);
  // `return [1, 2]` (and friends) must not be taken for an index assignment
  const isTok2Bracket = (orId) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    const link = (d) => {
      const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      if (!bb || bb.opcode !== 'data_itemoflist' || !bb.fields.LIST || bb.fields.LIST[0] !== 'Tok') return false;
      const ix = bb.inputs.INDEX;
      return (Array.isArray(ix) && ix[0] === 4 && String(ix[1]) === '2') || (Array.isArray(ix[1]) && ix[1][0] === 4 && String(ix[1][1]) === '2');
    };
    return (link(a) && litOf(c) === '[') || (link(c) && litOf(a) === '[');
  });
  const hasItemEq = (orId, listName, want, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    const link = (d) => {
      const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      if (!bb || bb.opcode !== 'data_itemoflist' || !bb.fields.LIST || bb.fields.LIST[0] !== listName) return false;
      const ix = bb.inputs.INDEX;
      return (Array.isArray(ix) && ix[0] === 4 && String(ix[1]) === String(want)) || (Array.isArray(ix[1]) && ix[1][0] === 4 && String(ix[1][1]) === String(want));
    };
    return (link(a) && litOf(c) === lit) || (link(c) && litOf(a) === lit);
  });
  const idxIf = find(ex, (b, id) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && hasItemEq(b.inputs.CONDITION[1], 'Kind', 1, 'I') && isTok2Bracket(b.inputs.CONDITION[1]));
  if (idxIf.length !== 1) throw new Error('[P55] indexset branch = ' + idxIf.length);
  {
    const condId = BL()[idxIf[0]].inputs.CONDITION[1];
    const kw = () => OR(OR(EQ(tokAt(num(1)), txt('return')), OR(EQ(tokAt(num(1)), txt('yield')), EQ(tokAt(num(1)), txt('raise')))), EQ(tokAt(num(1)), txt('print')));
    replaceExpr(condId, () => AND(condId, NOT(kw())));
  }
  console.log('[P55] indexset branch guarded against keyword heads');
  insertBeforeStmt(forIf[0], [classBranch, attrSetBranch]);
  console.log('[P55] execute: class + attribute-set branches installed');

  // ---------- 4) eval(): `self.v` (exactly three tokens with a dot) reads an attribute
  const ev = inDef('eval %s %s');
  const mcallIf = find(ev, (b, id) => b.opcode === 'control_if' && callsProc(subOf(id) || id, 'methodcall %s %s'));
  if (mcallIf.length !== 1) throw new Error('[P55] eval methodcall branch = ' + mcallIf.length);
  const callIf = find(ev, (b, id) => b.opcode === 'control_if' && callsProc(subOf(id) || id, 'callfn %s %s %s'));
  if (callIf.length !== 1) throw new Error('[P55] eval call branch = ' + callIf.length);
  // obj.method(...) with a receiver that is itself an expression: find the first
  // top-level dot, hand it to methodcall2 (which evaluates the receiver properly)
  const mc2 = newProc('methodcall2 %s %s %s', ['lo', 'hi', 'mdot']);
  attachBody(mc2.defId, [
    callProc('eval %s %s', [argOf('lo'), SUB(argOf('mdot'), num(1))]),
    IF(EQ(VAR('error'), txt('')), [
      setV('mcval', VAR('ev')),
      setV('mctype', VAR('evtype')),
      setV('mcpre', num(1)),
      callProc('methodcall %s %s', [SUB(argOf('mdot'), num(1)), argOf('hi')]),
      setV('mcpre', num(0))
    ])
  ]);
  insertBeforeStmt(callIf[0], [
    setV('mdot', num(0)),
    IF(NOT(LT(argOf('hi'), ADD(argOf('lo'), num(2)))), [
      setV('mdep', num(0)),
      setV('mk', argOf('lo')),
      REPEATU(GT(VAR('mk'), argOf('hi')), [
        IF(OR(EQ(tokAt(VAR('mk')), txt('(')), EQ(tokAt(VAR('mk')), txt('['))), [chgV('mdep', num(1))]),
        IF(OR(EQ(tokAt(VAR('mk')), txt(')')), EQ(tokAt(VAR('mk')), txt(']'))), [chgV('mdep', num(-1))]),
        IF(AND(EQ(VAR('mdep'), num(0)), EQ(tokAt(VAR('mk')), txt('.'))), [IF(EQ(VAR('mdot'), num(0)), [setV('mdot', VAR('mk'))])]),
        chgV('mk', num(1))
      ])
    ]),
    // only a MULTI-token receiver needs methodcall2; `math.floor(x)` keeps going through
    // the classic methodcall branch (its math special case reads Tok[lo+2])
    IF(AND(GT(VAR('mdot'), ADD(argOf('lo'), num(1))), EQ(tokAt(argOf('hi')), txt(')'))), [
      callProc('methodcall2 %s %s %s', [argOf('lo'), argOf('hi'), VAR('mdot')]),
      STOPTHIS()
    ])
  ]);
  console.log('[P55] eval: methodcall2 route installed');
  insertBeforeStmt(mcallIf[0], [
    IF(AND(EQ(tokAt(ADD(argOf('lo'), num(1))), txt('.')), EQ(argOf('hi'), ADD(argOf('lo'), num(2)))), [
      callProc('eval %s %s', [argOf('lo'), argOf('lo')]),
      IFELSE(EQ(VAR('evtype'), txt('O')), [
        setV('iid', VAR('ev')),
        setV('cX', num(0)),
        setV('ck', num(1)),
        REPEATU(GT(VAR('ck'), llen('IAttrId')), [
          IF(AND(EQ(at('IAttrId', VAR('ck')), VAR('iid')), EQ(at('IAttrName', VAR('ck')), tokAt(ADD(argOf('lo'), num(2))))), [
            setV('cX', VAR('ck')),
            setV('ck', llen('IAttrId'))
          ]),
          chgV('ck', num(1))
        ]),
        IFELSE(EQ(VAR('cX'), num(0)), [
          FAILB(JOIN(txt('AttributeError: '), tokAt(ADD(argOf('lo'), num(2)))))
        ], [
          setV('ev', at('IAttrVal', VAR('cX'))),
          setV('evtype', at('IAttrType', VAR('cX')))
        ])
      ], [
        FAIL('SyntaxError: attribute access')
      ]),
      STOPTHIS()
    ])
  ]);
  console.log('[P55] eval: attribute read installed');

  // ---------- 5) callmeth proc + methodcall dispatch for instances
  const cm = newProc('callmeth %s %s %s %s', ['inst', 'meth', 'lo', 'hi']);
  attachBody(cm.defId, [
    setV('ccls', item('InstCls', argOf('inst'))),
    setV('cfull', JOIN(JOIN(VAR('ccls'), txt('.')), argOf('meth'))),
    IFELSE(contains('FnName', VAR('cfull')), [
      addTo('VStack', VAR('self')),
      setV('self', argOf('inst')),
      callProc('assign %s %s %s', [txt('self'), argOf('inst'), txt('O')]),
      callProc('calluser %s %s %s', [VAR('cfull'), argOf('lo'), argOf('hi')]),
      setV('clf', item('VStack', llen('VStack'))),
      delLast('VStack'),
      IFELSE(EQ(VAR('clf'), txt('')), [
        callProc('assign %s %s %s', [txt('self'), txt(''), txt('Z')])
      ], [
        callProc('assign %s %s %s', [txt('self'), VAR('clf'), txt('O')])
      ]),
      setV('self', VAR('clf'))
    ], [
      FAILB(JOIN(JOIN(VAR('ccls'), txt(' has no attribute ')), argOf('meth')))
    ])
  ]);
  const mc = inDef('methodcall %s %s');
  const lmStmt = find(mc, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'lmeth');
  if (lmStmt.length !== 1) throw new Error('[P55] methodcall lmeth = ' + lmStmt.length);
  spliceAfter(lmStmt[0], chain([
    IF(EQ(VAR('xb'), txt('O')), [
      callProc('callmeth %s %s %s %s', [VAR('xa'), VAR('lmeth'), ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
      STOPTHIS()
    ])
  ]));
  const guard = find(mc, (b, id) => b.opcode === 'operator_or' && eqConst(id, 'xb', 'L') && eqConst(id, 'xb', 'S'));
  if (guard.length !== 1) throw new Error('[P55] methodcall type guard = ' + guard.length);
  replaceExpr(guard[0], () => OR(guard[0], EQ(VAR('xb'), txt('O'))));
  console.log('[P55] methodcall: instance dispatch installed');

  // ---------- 6) callfn(): a class name constructs an instance
  const cf = inDef('callfn %s %s %s');
  const argEval = find(cf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
  if (argEval.length !== 1) throw new Error('[P55] callfn arg eval = ' + argEval.length);
  insertBeforeStmt(argEval[0], [
    IF(contains('ClsName', argOf('fn')), [
      setV('iid', ADD(llen('InstCls'), num(1))),
      addTo('InstCls', argOf('fn')),
      setV('cfull', JOIN(JOIN(argOf('fn'), txt('.')), txt('__init__'))),
      IF(contains('FnName', VAR('cfull')), [
        addTo('VStack', VAR('self')),
        setV('self', VAR('iid')),
        callProc('assign %s %s %s', [txt('self'), VAR('iid'), txt('O')]),
        callProc('calluser %s %s %s', [VAR('cfull'), argOf('lo'), argOf('hi')]),
        setV('clf', item('VStack', llen('VStack'))),
        delLast('VStack'),
        IFELSE(EQ(VAR('clf'), txt('')), [
          callProc('assign %s %s %s', [txt('self'), txt(''), txt('Z')])
        ], [
          callProc('assign %s %s %s', [txt('self'), VAR('clf'), txt('O')])
        ]),
        setV('self', VAR('clf'))
      ]),
      IF(EQ(VAR('error'), txt('')), [setV('ev', VAR('iid')), setV('evtype', txt('O'))]),
      STOPTHIS()
    ])
  ]);

  // ---------- 7) reset the new tables at run start
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P55] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [clearL('ClsName'), clearL('InstCls'), clearL('IAttrId'), clearL('IAttrName'), clearL('IAttrVal'), clearL('IAttrType')]);
  console.log('[P55] classes ready');
});

// ---- P56: DEMO samples + HELP screen (Controller target) ----
//
// The DEMO button used to show 9 samples written before most of the language
// existed (no def/class/try/dict/comprehension).  This patch rebuilds `example`
// from _work/v41/demos.json (+ demos_input.json) and `help` from help.json.
//
// Help also gains real wrapping: the Output panel is 30 columns wide and the
// renderer (text %s ... limit 30) CLIPS, so any longer line was silently cut.
// Program output already wrapped (the Interpreter's `log` chunks at 30); the help
// screen now goes through a new Controller proc hwrap %s with the same rule.
// All help lines are kept <= 30 chars as well, so wrapping stays a safety net.
patch('P56 demo + help', () => {
  const fs = require('fs');
  const DIR = 'D:/编程/scratch/ai/minipython/_work/v41/';
  const asLines = (d) => ({ name: d.name, lines: String(d.code).replace(/\r/g, '').split('\n') });
  const demos = JSON.parse(fs.readFileSync(DIR + 'demos.json', 'utf8')).map(asLines)
    .concat(JSON.parse(fs.readFileSync(DIR + 'demos_input.json', 'utf8')).map(asLines));
  const help = JSON.parse(fs.readFileSync(DIR + 'help.json', 'utf8'));
  const long = help.filter((l) => l.length > 30);
  if (long.length) throw new Error('[P56] help lines over 30 chars: ' + JSON.stringify(long));
  const CTRL = 'Controller';
  B.setCtx(CTRL);
  const CB = () => T(CTRL).blocks;
  // ---- ctx-aware builders (head.txt's helpers are Interpreter-bound)
  const ci = (op, opts) => B.B(CTRL, op, opts);
  const cchain = (ids) => B.chain(CTRL, ids);
  const csub = (parentId, slot, ids) => {
    const first = ids.length ? cchain(ids) : null;
    CB()[parentId].inputs[slot] = [2, first];
    if (first) CB()[first].parent = parentId;
    return first;
  };
  const csetV = (n, v) => ci('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
  const cchg = (n, v) => ci('data_changevariableby', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
  const caddTo = (l, v) => ci('data_addtolist', { fields: B.LISTF(l), inputs: { ITEM: B.REP(v, [10, '']) } });
  const cclear = (l) => ci('data_deletealloflist', { fields: B.LISTF(l) });
  const clen = (x) => ci('operator_length', { inputs: { STRING: B.REP(x, [10, '']) } });
  const cletter = (i, s) => ci('operator_letter_of', { inputs: { LETTER: B.REP(i, [4, '0']), STRING: B.REP(s, [10, '']) } });
  const cjoin = (a, b) => ci('operator_join', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const ceq = (a, b) => ci('operator_equals', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cgt = (a, b) => ci('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cor = (a, b) => ci('operator_or', { inputs: { OPERAND1: B.BOOL(a), OPERAND2: B.BOOL(b) } });
  const cnot = (a) => ci('operator_not', { inputs: { OPERAND: B.BOOL(a) } });
  const csub2 = (a, b) => ci('operator_subtract', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const cif = (c, ids) => { const id = ci('control_if', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', ids); return id; };
  const crepeatU = (c, ids) => { const id = ci('control_repeat_until', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', ids); return id; };
  const cvar = (n) => B.VAR(n);
  const defOf = (proccode) => {
    for (const [id, b] of Object.entries(CB())) {
      if (b.opcode === 'procedures_definition' && b.inputs && b.inputs.custom_block) {
        const pr = CB()[b.inputs.custom_block[1]];
        if (pr && pr.mutation && pr.mutation.proccode === proccode) return id;
      }
    }
    throw new Error('[P56] controller def not found: ' + proccode);
  };
  const ccall = (proccode, args) => {
    const defId = defOf(proccode);
    const proto = CB()[CB()[defId].inputs.custom_block[1]];
    const ids = JSON.parse(proto.mutation.argumentids);
    const inputs = {};
    for (let i = 0; i < ids.length; i++) inputs[ids[i]] = B.REP((args || [])[i], [10, '']);
    return ci('procedures_call', { inputs, mutation: { tagName: 'mutation', children: [], proccode, argumentids: proto.mutation.argumentids, warp: proto.mutation.warp || 'true' } });
  };
  const attach = (defId, ids) => { const first = ids.length ? cchain(ids) : null; CB()[defId].next = first; if (first) CB()[first].parent = defId; return first; };

  // ---- hwrap %s : one help line, wrapped at 30 columns
  B.addVar(CTRL, 'hwb', '');
  B.addVar(CTRL, 'hwi', 0);
  // a block may have exactly one parent, so every use builds its own reporter
  const argText = () => B.argReporter(CTRL, 'text');
  const hw = B.makeProcedure(CTRL, 'hwrap %s', ['text'], true);
  attach(hw.defId, [
    csetV('hwb', B.txt('')),
    csetV('hwi', B.num(1)),
    crepeatU(cgt(cvar('hwi'), clen(argText())), [
      csetV('hwb', cjoin(cvar('hwb'), cletter(cvar('hwi'), argText()))),
      cif(ceq(clen(cvar('hwb')), B.num(30)), [caddTo('Output', cvar('hwb')), csetV('hwb', B.txt(''))]),
      cchg('hwi', B.num(1))
    ]),
    cif(cor(cnot(ceq(cvar('hwb'), B.txt(''))), ceq(clen(argText()), B.num(0))), [caddTo('Output', cvar('hwb'))])
  ]);

  // ---- help: clear, then one wrapped line per entry
  const helpDef = defOf('help');
  attach(helpDef, [cclear('Output')]
    .concat(help.map((l) => ccall('hwrap %s', [B.txt(l)])))
    .concat([csetV('outpage', B.num(1)), csetV('dirty', B.num(1))]));
  console.log('[P56] help rebuilt: ' + help.length + ' lines (max ' + Math.max(...help.map((l) => l.length)) + ' chars)');

  // ---- example: keep the original backup() call, replace every sample
  const exDef = defOf('example');
  const keep = CB()[exDef].next;
  if (!keep) throw new Error('[P56] example body missing');
  CB()[keep].next = null;
  const branches = demos.map((d, i) => cif(ceq(cvar('demo'), B.txt(String(i + 1))), d.lines.map((l) => caddTo('Code', B.txt(l)))));
  attach(exDef, [
    keep,
    cclear('Code')
  ].concat(branches).concat([
    cchg('demo', B.num(1)),
    cif(cgt(cvar('demo'), B.num(demos.length)), [csetV('demo', B.num(1))]),
    csetV('selected', B.num(1)),
    csetV('page', B.num(1)),
    csetV('hscroll', B.num(0)),
    csetV('status', cjoin(B.txt('Demo '), csub2(cvar('demo'), B.num(1)))),
    csetV('dirty', B.num(1))
  ]));
  console.log('[P56] demo rebuilt: ' + demos.length + ' samples');
  // head.txt's prune/relink only walk the Interpreter, so do the Controller here:
  // drop the replaced bodies (they are unreachable) and only then fix the parents
  {
    const blocks = CB();
    const keep = new Set();
    const stack = Object.keys(blocks).filter((id) => blocks[id].topLevel);
    while (stack.length) {
      const id = stack.pop();
      if (!id || keep.has(id)) continue;
      const b = blocks[id]; if (!b) continue;
      keep.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
    let dropped = 0;
    for (const id of Object.keys(blocks)) if (!keep.has(id)) { delete blocks[id]; dropped++; }
    for (const id of Object.keys(blocks)) blocks[id].parent = null;
    for (const id of Object.keys(blocks)) {
      const b = blocks[id];
      if (b.next && blocks[b.next]) blocks[b.next].parent = id;
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string' && blocks[v[1]]) blocks[v[1]].parent = id;
    }
    console.log('[P56] controller pruned ' + dropped + ' stale blocks');
  }
  B.setCtx('Interpreter');
});

// ---- P57: class calls with >1 argument, and unary `~` ----
//
// Two gaps the new DEMO samples walked straight into:
//   1. `Point(3, 4)` -> eval's call branch only marks a name *callable* when it is
//      in FnName (plain functions) or holds type F (lambdas).  A CLASS name is
//      neither, and with one comma or more the branch takes the multi-argument path,
//      so it fell through to `NameError: name Point is not defined`.  Single-argument
//      calls took the narg==0 path and worked, which is why the gap hid.
//   2. `~x` was not in the unary operator set at all (`print(~12)` ->
//      `SyntaxError: expression`).  CPython: ~n == -n - 1 (ints only).
patch('P57 class calls + tilde', () => {
  const ev = inDef('eval %s %s');
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const isTokItem = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return !!b && b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Tok';
  };
  const eqTokLit = (orId, lit) => [...reach(orId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (isTokItem(a) && litOf(c) === lit) || (isTokItem(c) && litOf(a) === lit);
  });
  // list reporters show up as data_listcontents, data_listcontainsitem, data_itemoflist, ...
  const listContents = (x) => {
    const b = BL()[x];
    return !!b && b.fields && b.fields.LIST ? b.fields.LIST[0] : null;
  };
  const mentionsList = (desc, name) => {
    const seen = new Set(); const stack = [desc];
    while (stack.length) {
      const cur = stack.pop();
      if (cur === null || cur === undefined) continue;
      if (typeof cur === 'string') {
        if (seen.has(cur)) continue; seen.add(cur);
        if (listContents(cur) === name) return true;
        const b = BL()[cur]; if (!b) continue;
        for (const v of Object.values(b.inputs || {})) stack.push(v);
        continue;
      }
      if (Array.isArray(cur)) for (const e of cur) stack.push(e);
    }
    return false;
  };
  // ---- 1) a class name is callable
  const fnChk = find(ev, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && mentionsList(b.inputs.CONDITION[1], 'FnName'));
  if (fnChk.length !== 1) throw new Error('[P57] eval FnName check = ' + fnChk.length);
  const hit = () => { const v = 'cax'; return VAR(v); };
  const membership = [
    setV('cax', num(0)),
    setV('ck', num(1)),
    REPEATU(GT(VAR('ck'), llen('ClsName')), [
      IF(EQ(item('ClsName', VAR('ck')), item('Tok', argOf('lo'))), [setV('cax', num(1))]),
      chgV('ck', num(1))
    ]),
    IF(EQ(VAR('cax'), num(1)), [setV('callable', num(1))])
  ];
  insertBeforeStmt(fnChk[0], membership);
  console.log('[P57] class names count as callable');
  // ---- 2) unary ~
  const ors = find(ev, (b, id) => b.opcode === 'operator_or' && eqTokLit(id, '-') && eqTokLit(id, '+'));
  if (!ors.length) throw new Error('[P57] eval unary operator chain not found');
  for (const id of ors) replaceExpr(id, () => OR(id, EQ(item('Tok', argOf('lo')), txt('~'))));
  const un = inDef('unary %s %s %s');
  const minusIf = find(un, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && mentionsList(b.inputs.CONDITION[1], 'x') === false && eqConstArg(b.inputs.CONDITION[1], 'op', '-'));
  function eqConstArg(condId, name, lit) {
    return [...reach(condId)].some((id) => {
      const b = BL()[id];
      if (!b || b.opcode !== 'operator_equals') return false;
      const argName = (d) => { const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null; return bb && bb.opcode === 'argument_reporter_string_number' ? bb.fields.VALUE[0] : null; };
      const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
      return (argName(a) === name && litOf(c) === lit) || (argName(c) === name && litOf(a) === lit);
    });
  }
  if (minusIf.length !== 1) throw new Error('[P57] unary minus branch = ' + minusIf.length);
  spliceAfter(minusIf[0], chain([
    IF(EQ(argOf('op'), txt('~')), [setV('ev', SUB(SUB(num(0), VAR('ev')), num(1)))])
  ]));
  console.log('[P57] unary ~ installed (' + ors.length + ' operator chains)');
});

// ---- P58: the variables panel shows real Python values, not the internal encoding ----
//
// The panel row is built from the Stage's Names/Values lists, and Values holds the
// interpreter's internal value encoding: a list is stored as "\x1fN1\x1fStwo" etc.
// The TextRenderer draws one glyph per character, and \x1f has no costume, so the row
// came out as mojibake (demo4's list comprehension made it obvious: "b = ?N0?N1?N4...").
//
// Fix: the interpreter now keeps a parallel Stage list Show next to Names, holding the
// *display* text of each variable (strval, so it matches print()).  Show is written by
// assign, deleted by `del`, saved/restored around function frames exactly like
// Values, and the panel renders "name = Show[i]" (trimmed to the 30-column panel with
// an ellipsis instead of a silent cut).
patch('P58 panel values', () => {
  B.addList('Stage', 'Show', []);
  B.addList(IT, 'FSV', []);
  newVar('dve', '');
  newVar('dvt', '');
  const showId = B.LISTF('Show').LIST;
  const itemShow = (idx) => I('data_itemoflist', { fields: B.LISTF('Show'), inputs: { INDEX: B.REP(idx, [10, '']) } });
  const delShow = (idx) => I('data_deleteoflist', { fields: B.LISTF('Show'), inputs: { INDEX: B.REP(idx, [10, '']) } });
  const setShow = (idx, v) => I('data_replaceitemoflist', { fields: B.LISTF('Show'), inputs: { INDEX: B.REP(idx, [10, '']), ITEM: B.REP(v, [10, '']) } });
  const saveEv = () => [setV('dve', VAR('ev')), setV('dvt', VAR('evtype'))];
  const restoreEv = () => [setV('ev', VAR('dve')), setV('evtype', VAR('dvt'))];
  const strvalCall = () => callProc('strval %s %s', [argOf('vv'), argOf('vt')]);

  // 1) assign: keep Show in step with Names/Values/Types (append and update paths)
  const asg = inDef('assign %s %s %s');
  const appTypes = find(asg, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'Types');
  const setTypes = find(asg, (b) => b.opcode === 'data_replaceitemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Types');
  if (appTypes.length !== 1 || setTypes.length !== 1) throw new Error('[P58] assign paths = ' + appTypes.length + ',' + setTypes.length);
  spliceAfter(appTypes[0], chain(saveEv().concat([strvalCall()], [addTo('Show', VAR('ev'))], restoreEv())));
  spliceAfter(setTypes[0], chain(saveEv().concat([strvalCall()], [setShow(VAR('found'), VAR('ev'))], restoreEv())));
  console.log('[P58] assign keeps Show');

  // 2) `del name` drops the row from every parallel list
  const ex = inDef('execute');
  const delTypes = find(ex, (b) => b.opcode === 'data_deleteoflist' && b.fields.LIST && b.fields.LIST[0] === 'Types');
  if (delTypes.length !== 1) throw new Error('[P58] del Types = ' + delTypes.length);
  spliceAfter(delTypes[0], chain([delShow(VAR('found'))]));
  console.log('[P58] del drops Show');

  // 3) RUN start: the panel lists are cleared together
  const runHat = Object.entries(BL()).find(([id, b]) => b.opcode === 'event_whenbroadcastreceived' && b.fields.BROADCAST_OPTION && b.fields.BROADCAST_OPTION[0] === 'RUN');
  if (!runHat) throw new Error('[P58] RUN hat not found');
  const clears = find(reach(runHat[0]), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'Types');
  if (clears.length !== 1) throw new Error('[P58] RUN clear Types = ' + clears.length);
  spliceAfter(clears[0], chain([clearL('Show')]));

  // 4) function frames: Show rides along with Values (FN/FV/FT <-> FSV)
  const cu = inDef('calluser %s %s %s');
  const entFT = find(cu, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'FT');
  if (entFT.length !== 1) throw new Error('[P58] frame enter = ' + entFT.length);
  spliceAfter(entFT[0], chain([IFELSE(GT(VAR('fj'), llen('Show')),
    [addTo('FSV', txt(''))],
    [addTo('FSV', itemShow(VAR('fj')))])]));
  const exitTypes = find(cu, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'Types');
  if (exitTypes.length !== 1) throw new Error('[P58] frame exit = ' + exitTypes.length);
  spliceAfter(exitTypes[0], chain([IFELSE(GT(VAR('epI'), llen('FSV')),
    [addTo('Show', txt(''))],
    [addTo('Show', I('data_itemoflist', { fields: B.LISTF('FSV'), inputs: { INDEX: B.REP(VAR('epI'), [10, '']) } }))])]));
  const clearTypes = find(cu, (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'Types');
  if (clearTypes.length !== 1) throw new Error('[P58] frame clear = ' + clearTypes.length);
  spliceAfter(clearTypes[0], chain([clearL('Show')]));
  const truncFT = find(cu, (b) => b.opcode === 'data_deleteoflist' && b.fields.LIST && b.fields.LIST[0] === 'FT');
  if (truncFT.length !== 1) throw new Error('[P58] frame trunc = ' + truncFT.length);
  spliceAfter(truncFT[0], chain([I('data_deleteoflist', { fields: B.LISTF('FSV'), inputs: { INDEX: B.REP(llen('FSV'), [4, '0']) } })]));
  console.log('[P58] function frames carry Show');

  // 5) the flag-clicked reset
  {
    const st = T('Stage');
    const sc = Object.keys(st.blocks).filter((id) => {
      const b = st.blocks[id];
      return b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'Types';
    });
    if (sc.length !== 1) throw new Error('[P58] stage clear = ' + sc.length);
    B.setCtx('Stage');
    const clr = B.B('Stage', 'data_deletealloflist', { fields: B.LISTF('Show') });
    const a = st.blocks[sc[0]];
    const nx = a.next;
    a.next = clr; st.blocks[clr].parent = sc[0];
    st.blocks[clr].next = nx;
    if (nx) st.blocks[nx].parent = clr;
    B.setCtx('Interpreter');
  }

  // 6) the panel itself: render the display text and trim long rows with an ellipsis
  const TR = 'TextRenderer';
  B.setCtx(TR);
  B.addVar(TR, 'vtxt', '');
  B.addVar(TR, 'vcut', '');
  B.addVar(TR, 'vk', 0);
  const tb = (op, opts) => B.B(TR, op, opts);
  const TBL = () => T(TR).blocks;
  const tsetV = (n, v) => tb('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
  const tchg = (n, v) => tb('data_changevariableby', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
  const tjoin = (a, b) => tb('operator_join', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const tlen = (x) => tb('operator_length', { inputs: { STRING: B.REP(x, [10, '']) } });
  const tgt = (a, b) => tb('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const tletter = (i, s) => tb('operator_letter_of', { inputs: { LETTER: B.REP(i, [4, '0']), STRING: B.REP(s, [10, '']) } });
  const tif = (c, ids) => { const id = tb('control_if', { inputs: { CONDITION: B.BOOL(c) } }); B.sub(TR, id, 'SUBSTACK', B.chain(TR, ids)); return id; };
  const trepeat = (n, ids) => { const id = tb('control_repeat', { inputs: { TIMES: B.REP(n, [4, '0']) } }); B.sub(TR, id, 'SUBSTACK', B.chain(TR, ids)); return id; };
  const tvar = (n) => B.VAR(n);
  const tspliceAfter = (afterId, firstId) => {
    const a = TBL()[afterId];
    const nx = a.next;
    a.next = firstId; TBL()[firstId].parent = afterId;
    let t = firstId;
    while (TBL()[t].next) t = TBL()[t].next;
    TBL()[t].next = nx;
    if (nx) TBL()[nx].parent = t;
    return firstId;
  };
  // find the draw proc and the panel row
  let drawDef = null;
  for (const [id, b] of Object.entries(TBL())) {
    if (b.opcode !== 'procedures_definition' || !b.inputs.custom_block) continue;
    const pr = TBL()[b.inputs.custom_block[1]];
    if (pr && pr.mutation.proccode === 'draw') drawDef = id;
  }
  if (!drawDef) throw new Error('[P58] draw proc not found');
  const drawSet = new Set();
  {
    const stack = [drawDef];
    while (stack.length) {
      const id = stack.pop();
      if (!id || drawSet.has(id)) continue;
      const b = TBL()[id];
      if (!b) continue;
      drawSet.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
  }
  const iv = [];
  for (const id of drawSet) {
    const b = TBL()[id];
    if (b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Values') iv.push(id);
  }
  if (iv.length !== 1) throw new Error('[P58] panel Values item = ' + iv.length);
  TBL()[iv[0]].fields.LIST = showId;            // reuse the reporter: Values -> Show
  // the enclosing text() call: the first input is the "name = value" join
  let callId = null, callArg = null;
  for (const id of drawSet) {
    const b = TBL()[id];
    if (b.opcode !== 'procedures_call' || !b.mutation || !/^text /.test(b.mutation.proccode)) continue;
    const first = JSON.parse(b.mutation.argumentids)[0];
    const arg = b.inputs[first];
    if (arg && typeof arg[1] === 'string' && drawSet.has(arg[1])) {
      const inner = [...reach2(arg[1])].some((k) => k === iv[0]);
      if (inner) { callId = id; callArg = first; break; }
    }
  }
  function reach2(root) {
    const seen = new Set(); const stack = [root];
    while (stack.length) {
      const id = stack.pop();
      if (!id || seen.has(id)) continue;
      const b = TBL()[id]; if (!b) continue;
      seen.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
    return seen;
  }
  if (!callId) throw new Error('[P58] panel text call not found');
  const joinId = TBL()[callId].inputs[callArg][1];
  TBL()[callId].inputs[callArg] = tvar('vtxt');
  const trim = [
    tsetV('vtxt', joinId),
    tif(tgt(tlen(tvar('vtxt')), B.num(30)), [
      tsetV('vcut', B.txt('')),
      tsetV('vk', B.num(1)),
      trepeat(B.num(27), [
        tsetV('vcut', tjoin(tvar('vcut'), tletter(tvar('vk'), tvar('vtxt')))),
        tchg('vk', B.num(1))
      ]),
      tsetV('vtxt', tjoin(tvar('vcut'), B.txt('...')))
    ])
  ];
  // insert the trim before the call: it may sit inside a SUBSTACK or follow a plain block
  const callB = TBL()[callId];
  let placed = false;
  const par = callB.parent ? TBL()[callB.parent] : null;
  if (par) {
    for (const [slot, v] of Object.entries(par.inputs || {})) {
      if (v && v[1] === callId && slot.indexOf('SUBSTACK') === 0) {
        const first = B.chain(TR, trim);
        par.inputs[slot] = [2, first];
        TBL()[first].parent = callB.parent;
        let t = first;
        while (TBL()[t].next) t = TBL()[t].next;
        TBL()[t].next = callId;
        callB.parent = t;
        placed = true;
      }
    }
  }
  if (!placed) {
    let prevId = null;
    for (const id of drawSet) if (TBL()[id].next === callId) prevId = id;
    if (!prevId) throw new Error('[P58] panel call has no predecessor');
    tspliceAfter(prevId, B.chain(TR, trim));
  }
  console.log('[P58] panel renders Show with a 30-column trim');
  // head.txt's prune/relink only walk the Interpreter, so fix the TextRenderer parents here
  {
    const blocks = TBL();
    for (const id of Object.keys(blocks)) blocks[id].parent = null;
    for (const id of Object.keys(blocks)) {
      const b = blocks[id];
      if (b.next && blocks[b.next]) blocks[b.next].parent = id;
      for (const v of Object.values(b.inputs || {})) {
        if (!v) continue;
        for (const k of [1, 2]) if (typeof v[k] === 'string' && blocks[v[k]]) blocks[v[k]].parent = id;   // 2 = menu-shape shadow
      }
    }
    console.log('[P58] TextRenderer parents relinked');
  }
  B.setCtx('Interpreter');
});

// ---- P59: dicts print (and show) as Python dicts ----
//
// strval had branches for C/B/Z/L/T and a fall-through that returned the value
// untouched, so a dict printed its internal encoding ("\x1fSk\x1fN1").  Dicts are
// stored as a flat key,value,... run of encoded elements, so dictfmt walks them with
// listitem + reprval and builds "{'k': 1}".  The variables panel shows it too,
// because Show is filled from strval.
patch('P59 dicts', () => {
  newVar('d1acc', '');
  newVar('d1n', 0);
  newVar('d1i', 1);
  newVar('d1k', '');
  newVar('d1v', '');
  const dArg = () => argOf('s');          // one reporter per use: a block has one parent
  const proc = newProc('dictfmt %s', ['s']);
  attachBody(proc.defId, [
    setV('d1acc', txt('{')),
    callProc('listlen %s', [dArg()]),
    setV('d1n', VAR('ev')),
    setV('d1i', num(1)),
    REPEATU(GT(VAR('d1i'), VAR('d1n')), [
      callProc('listitem %s %s', [dArg(), VAR('d1i')]),
      callProc('reprval %s %s', [VAR('ev'), VAR('evtype')]),
      setV('d1k', VAR('ev')),
      chgV('d1i', num(1)),
      callProc('listitem %s %s', [dArg(), VAR('d1i')]),
      callProc('reprval %s %s', [VAR('ev'), VAR('evtype')]),
      setV('d1v', VAR('ev')),
      IF(GT(VAR('d1i'), num(2)), [setV('d1acc', JOIN(VAR('d1acc'), txt(', ')))]),
      setV('d1acc', JOIN(VAR('d1acc'), JOIN(VAR('d1k'), JOIN(txt(': '), VAR('d1v'))))),
      chgV('d1i', num(1))
    ]),
    setV('ev', JOIN(VAR('d1acc'), txt('}'))),
    setV('evtype', txt('S'))
  ]);
  console.log('[P59] dictfmt installed');
  // strval: insert "vt == D -> dictfmt vv" in front of the untouched fall-through
  const sv = inDef('strval %s %s');
  const fall = find(sv, (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'argument_reporter_string_number'
    && BL()[b.inputs.VALUE[1]].fields.VALUE[0] === 'vv');
  if (fall.length !== 1) throw new Error('[P59] strval fall-through = ' + fall.length);
  const ref = refOf(fall[0]);
  if (!ref) throw new Error('[P59] strval fall-through has no parent slot');
  const ie = IFELSE(EQ(argOf('vt'), txt('D')), [callProc('dictfmt %s', [argOf('vv')])], [fall[0]]);
  BL()[ref.pid].inputs[ref.slot] = [2, ie];
  BL()[ie].parent = ref.pid;
  console.log('[P59] strval handles D');
  // A nested container used as a dict key/value was stored WITHOUT escaping, so
  // {'a': [1, 2]} held a bare \x1f inside its payload and read back as [] -- every
  // element after it shifted too.  List elements go through lesc; do the same here.
  newVar('dgesc', '');
  const dpDef = defIdOf('dictpair %s %s');
  const mainChain = [];
  {
    let cur = BL()[dpDef].next, g = 0;
    while (cur && g++ < 4000) { mainChain.push(cur); cur = BL()[cur].next; }
  }
  const dout = mainChain.filter((id) => { const b = BL()[id]; return b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'DOut'; });
  if (dout.length !== 2) throw new Error('[P59] DOut appends = ' + dout.length);
  const srcName = ['dgkey', 'dga'];
  dout.forEach((id, i) => {
    const outer = BL()[BL()[id].inputs.ITEM[1]];
    if (!outer || outer.opcode !== 'operator_join' || !outer.inputs.STRING2) throw new Error('[P59] DOut item shape ' + i);
    const s2 = outer.inputs.STRING2;
    if (!Array.isArray(s2[1]) || s2[1][0] !== 12 || s2[1][1] !== srcName[i]) throw new Error('[P59] DOut item var ' + i + ' = ' + JSON.stringify(s2));
    insertBeforeStmt(id, [callProc('lesc %s', [VAR(srcName[i])]), setV('dgesc', VAR('ev'))]);
    BL()[BL()[id].inputs.ITEM[1]].inputs.STRING2 = B.VAR('dgesc');
  });
  console.log('[P59] dict keys/values escaped (nested containers survive)');
  // Instances and functions used to fall through as their internal id ("p = 1"), which
  // is what the panel showed for every object.  Give them CPython-ish text.
  const svDef = inDef('strval %s %s');
  const fall2 = find(svDef, (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'argument_reporter_string_number'
    && BL()[b.inputs.VALUE[1]].fields.VALUE[0] === 'vv');
  if (fall2.length !== 1) throw new Error('[P59] strval fall-through (2nd) = ' + fall2.length);
  const ref2 = refOf(fall2[0]);
  const join2 = (a, b) => JOIN(a, b);
  const objText = JOIN(JOIN(txt('<'), item('InstCls', argOf('vv'))), txt(' object>'));
  const fnText = JOIN(JOIN(txt('<function '), item('FnName', argOf('vv'))), txt('>'));
  const ie2 = IFELSE(EQ(argOf('vt'), txt('O')),
    [setV('ev', objText), setV('evtype', txt('S'))],
    [IFELSE(EQ(argOf('vt'), txt('F')),
      [setV('ev', fnText), setV('evtype', txt('S'))],
      [fall2[0]])]);
  BL()[ref2.pid].inputs[ref2.slot] = [2, ie2];
  BL()[ie2].parent = ref2.pid;
  console.log('[P59] strval handles O and F');
});

// ---- P60: a comprehension's loop variable no longer leaks ----
//
// complist binds the loop name with plain assign, so "x = 99; b = [x for x in range(3)]"
// left x == 2 (CPython keeps 99) and every comprehension row stayed in the variables
// panel for good.  Save the name's old binding before the loop and put it back after;
// when the name did not exist, drop the row again (Names/Values/Types/Show together).
patch('P60 comprehension scope', () => {
  newVar('c1n', '');
  newVar('c1s', 0);
  newVar('c1v', '');
  newVar('c1t', '');
  const cl = inDef('complist %s %s');
  const accInit = find(cl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'cacc'
    && b.inputs.VALUE && b.inputs.VALUE[0] === 1 && b.inputs.VALUE[1] && b.inputs.VALUE[1][0] === 10 && b.inputs.VALUE[1][1] === '');
  if (accInit.length !== 1) throw new Error('[P60] cacc init = ' + accInit.length);
  spliceAfter(accInit[0], chain([
    setV('c1n', item('Tok', ADD(VAR('cfor'), num(1)))),
    callProc('lookup %s', [VAR('c1n')]),
    setV('c1s', VAR('found')),
    IF(GT(VAR('c1s'), num(0)), [
      setV('c1v', I('data_itemoflist', { fields: B.LISTF('Values'), inputs: { INDEX: B.REP(VAR('c1s'), [10, '']) } })),
      setV('c1t', I('data_itemoflist', { fields: B.LISTF('Types'), inputs: { INDEX: B.REP(VAR('c1s'), [10, '']) } }))
    ])
  ]));
  // put the old binding back (or remove the row the comprehension created)
  const evAcc = find(cl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][0] === 12 && b.inputs.VALUE[1][1] === 'cacc');
  if (evAcc.length !== 1) throw new Error('[P60] ev = cacc = ' + evAcc.length);
  const drop = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(VAR('found'), [10, '']) } });
  insertBeforeStmt(evAcc[0], [
    IFELSE(EQ(VAR('c1s'), num(0)), [
      callProc('lookup %s', [VAR('c1n')]),
      IF(GT(VAR('found'), num(0)), [drop('Names'), drop('Values'), drop('Types'), drop('Show')])
    ], [
      callProc('assign %s %s %s', [VAR('c1n'), VAR('c1v'), VAR('c1t')])
    ])
  ]);
  console.log('[P60] comprehension loop variable scoped');
});

// ---- P61: watch the run inside a function (highlight, STEP, slow mode) ----
//
// calluser ran its body loop inside a *warp* procedure that only tokenised and
// executed: it never touched selected/page/dirty, never counted steps and never
// honoured the STEP gate, so while a function ran the code panel stayed frozen on
// the call line and one STEP ran the whole callee.  (A wait_until in a warp
// procedure would also spin forever inside one VM step, which is why the gate could
// not simply be copied.)
//
// Measured cost of dropping warp: fib(16) 4.77s -> 4.89s (same VM step count), so
// the body loop now runs non-warp and mirrors the main RUN loop per line.
patch('P61 step into functions', () => {
  // 1) the body loop must be able to yield (STEP gate / slow mode)
  let proto = 0;
  for (const b of Object.values(BL())) {
    if (b.opcode === 'procedures_prototype' && b.mutation && b.mutation.proccode === 'calluser %s %s %s') { b.mutation.warp = 'false'; proto++; }
  }
  if (proto !== 1) throw new Error('[P61] calluser prototypes = ' + proto);
  const cu = inDef('calluser %s %s %s');
  // 2) the per-line work of the body loop
  const exe = find(cu, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'execute' && b.inputs && !Object.keys(b.inputs).length);
  if (exe.length !== 1) throw new Error('[P61] execute call = ' + exe.length);
  const innerIfId = BL()[exe[0]].parent;
  const innerIf = BL()[innerIfId];
  if (!innerIf || (innerIf.opcode !== 'control_if' && innerIf.opcode !== 'control_if_else') || !innerIf.inputs.SUBSTACK || innerIf.inputs.SUBSTACK[1] !== exe[0]) {
    throw new Error('[P61] execute call is not the head of an if-substack');
  }
  const waitUntil = I('control_wait_until', {
    inputs: { CONDITION: B.BOOL(OR(OR(GT(VAR('ticket'), num(0)), EQ(VAR('mode'), num(0))), EQ(VAR('running'), num(0)))) }
  });
  const chainIds = [
    setV('selected', VAR('pc')),
    IF(OR(LT(VAR('pc'), VAR('page')), GT(VAR('pc'), ADD(VAR('page'), num(15)))), [setV('page', VAR('pc'))]),
    setV('dirty', num(1)),
    IF(EQ(VAR('mode'), num(1)), [
      setV('status', txt('Paused / STEP to advance')),
      waitUntil,
      chgV('ticket', num(-1))
    ]),
    IF(EQ(VAR('running'), num(1)), [
      setV('status', txt('Running')),
      chgV('steps', num(1)),
      IFELSE(GT(VAR('steps'), ADD(num(10000), MUL(VAR('speed'), num(90000)))),
        [FAIL('LimitError: step limit reached')],
        [exe[0]]),
      IF(OR(EQ(VAR('speed'), num(0)), EQ(MOD(VAR('steps'), num(50)), num(0))), [
        setV('dirty', num(1)),
        I('control_wait', { inputs: { DURATION: B.REP(num(0), [4, '0']) } })
      ])
    ])
  ];
  const first = chain(chainIds);
  innerIf.inputs.SUBSTACK = [2, first];
  BL()[first].parent = innerIfId;
  console.log('[P61] function bodies report lines (selected/page/steps)');
  // 3) STOP has to end the body loop the way it ends the main loop
  const loop = find(cu, (b) => b.opcode === 'control_repeat_until'
    && b.inputs.SUBSTACK && b.inputs.SUBSTACK[1] && BL()[b.inputs.SUBSTACK[1]]
    && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_changevariableby'
    && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'csteps');
  if (loop.length !== 1) throw new Error('[P61] body loop = ' + loop.length);
  replaceExpr(BL()[loop[0]].inputs.CONDITION[1], () => OR(BL()[loop[0]].inputs.CONDITION[1], EQ(VAR('running'), num(0))));
  console.log('[P61] body loop also ends on STOP');
});

// ---- P62: `self` no longer leaks into the variables panel ----
//
// Both dispatch paths (callfn's __init__ path and callmeth) bind the user variable
// "self" in the CALLER frame -- that is how the method body resolves it -- and then
// restore whatever was there before.  When nothing was there before, the restore wrote
// the hidden register's initial value back as an *object*, so the panel kept a bogus
// "self = 0" row for the rest of the run (demo8 showed self, p, q).
//
// Now the old binding is saved as value + type, and when the name did not exist before
// the row is dropped again -- the same idea as P60.
patch('P62 self scope', () => {
  newVar('s1s', 0);
  newVar('s1v', '');
  newVar('s1t', '');
  const dropAll = (idx) => [
    I('data_deleteoflist', { fields: B.LISTF('Names'), inputs: { INDEX: B.REP(idx, [10, '']) } }),
    I('data_deleteoflist', { fields: B.LISTF('Values'), inputs: { INDEX: B.REP(idx, [10, '']) } }),
    I('data_deleteoflist', { fields: B.LISTF('Types'), inputs: { INDEX: B.REP(idx, [10, '']) } }),
    I('data_deleteoflist', { fields: B.LISTF('Show'), inputs: { INDEX: B.REP(idx, [10, '']) } })
  ];
  const saveSelf = () => [
    callProc('lookup %s', [txt('self')]),
    setV('s1s', VAR('found')),
    IF(GT(VAR('s1s'), num(0)), [
      setV('s1v', I('data_itemoflist', { fields: B.LISTF('Values'), inputs: { INDEX: B.REP(VAR('s1s'), [10, '']) } })),
      setV('s1t', I('data_itemoflist', { fields: B.LISTF('Types'), inputs: { INDEX: B.REP(VAR('s1s'), [10, '']) } }))
    ])
  ];
  const restoreSelf = () => IFELSE(EQ(VAR('s1s'), num(0)), [
    callProc('lookup %s', [txt('self')]),
    IF(GT(VAR('found'), num(0)), dropAll(VAR('found')))
  ], [
    callProc('assign %s %s %s', [txt('self'), VAR('s1v'), VAR('s1t')])
  ]);
  const isHiddenSelf = (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'self'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][0] === 12 && b.inputs.VALUE[1][1] === 'clf';
  const isSelfPush = (b) => b.opcode === 'data_addtolist'
    && b.fields.LIST && b.fields.LIST[0] === 'VStack'
    && b.inputs.ITEM && Array.isArray(b.inputs.ITEM[1]) && b.inputs.ITEM[1][0] === 12 && b.inputs.ITEM[1][1] === 'self';
  for (const proc of ['callfn %s %s %s', 'callmeth %s %s %s %s']) {
    const set = inDef(proc);
    const reg = find(set, isHiddenSelf);
    const push = find(set, isSelfPush);
    if (reg.length !== 1 || push.length !== 1) throw new Error('[P62] ' + proc + ' reg=' + reg.length + ' push=' + push.length);
    const oldRestore = predecessorOf(reg[0]);
    if (!oldRestore || BL()[oldRestore].opcode !== 'control_if_else') throw new Error('[P62] ' + proc + ' restore shape = ' + (oldRestore && BL()[oldRestore].opcode));
    const before = predecessorOf(oldRestore);
    if (!before) throw new Error('[P62] ' + proc + ' has no predecessor');
    const first = insertBeforeStmt(reg[0], [restoreSelf()]);         // ... oldRestore -> new -> reg
    BL()[before].next = first;                                       // ... before -> new -> reg
    BL()[first].parent = before;
    BL()[oldRestore].next = null;
    BL()[oldRestore].parent = null;
    insertBeforeStmt(push[0], saveSelf());                           // remember the binding we are about to shadow
    console.log('[P62] ' + proc.split(' ')[0] + ': self binding saved/restored');
  }
});

// ---- P65: STEP keeps working after a call returns ----
//
// fpush/fpop snapshot a pile of interpreter registers around a call, and `mode`,
// `ticket` and `steps` are part of it.  So a click that happened *inside* a call was
// simply rolled back when that call returned: stepping silently stopped (mode back to 0
// -> the program ran to the end), which is exactly "I pressed STEP and it ran away".
//
// The debugger state is global, not per frame: keep the current values across fpop.
patch('P65 debug state across calls', () => {
  // NOTE: mv/tv/sv are *taken* (live interpreter registers) -- picking them corrupted
  // the run; these names are checked free.
  newVar('smode', 0);
  newVar('stick', 0);
  newVar('sstep', 0);
  const cu = inDef('calluser %s %s %s');
  const fpopCall = find(cu, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fpop');
  if (fpopCall.length !== 1) throw new Error('[P65] fpop calls = ' + fpopCall.length);
  insertBeforeStmt(fpopCall[0], [
    setV('smode', VAR('mode')),
    setV('stick', VAR('ticket')),
    setV('sstep', VAR('steps'))
  ]);
  spliceAfter(fpopCall[0], chain([
    setV('mode', VAR('smode')),
    setV('ticket', VAR('stick')),
    setV('steps', VAR('sstep'))
  ]));
  console.log('[P65] mode/ticket/steps survive a call return');
});

// ---- P66: a STEP inside a function costs one frame, not 500ms ----
//
// Measured before this patch (harness, real VM): one step inside a function took
// **501ms** while one step at top level took 13ms.  The wait itself is fine -- the
// frame is warp, and a warp thread keeps running until Sequencer.WARP_TIME (500ms)
// expires, so every frame spent waiting burns the whole budget (the UI drops to ~2fps
// and a click takes ~0.5s to show, which reads as "my click did not register").
//
// Warp is INHERITED here: Thread.pushStack copies the parent frame's warpMode and a
// callee's own flag can only *set* it, never clear it (sequencer.stepToProcedure), so
// the function body was warp purely because its ancestors (execute/eval/...) were.
// Flip the call + expression chain to non-warp -- then the pause really yields (one
// frame per step) while a non-warp thread still runs until the frame's work budget
// (75% of currentStepTime) is used up.
//
// Measured after: step inside a function 46-60ms (2-4 frames).
// NOTE: this set was found by hand; P67 completes it with the call-graph closure and
// adds a build-time check (print(area(3, 4)) stayed slow until printargs was included).
patch('P66 non-warp call chain', () => {
  const CHAIN = [
    'execute', 'eval %s %s', 'callfn %s %s %s', 'calluser %s %s %s',
    'methodcall %s %s', 'methodcall2 %s %s %s', 'callmeth %s %s %s %s',
    'pair %s %s %s %s', 'atom %s', 'rightside %s %s %s %s %s',
    'builtin2 %s %s %s %s', 'builtin2b %s %s %s %s %s', 'indexget %s %s',
    'listlit %s %s', 'tuplelit %s %s', 'dictlit %s %s', 'dictpair %s %s',
    'complist %s %s', 'fstr %s', 'pctfmt %s %s %s', 'anyall %s %s %s',
    'unary %s %s %s', 'indexset %s %s', 'indexdel %s %s',
    'assignlist %s', 'conditional %s', 'forloop'
  ];
  const protos = {};
  for (const b of Object.values(BL())) {
    if (b.opcode === 'procedures_prototype' && b.mutation) protos[b.mutation.proccode] = b;
  }
  let n = 0;
  for (const code of CHAIN) {
    const b = protos[code];
    if (!b) throw new Error('[P66] procedure not found: ' + code);
    if (b.mutation.warp !== 'false') n++;
    b.mutation.warp = 'false';
  }
  console.log('[P66] ' + CHAIN.length + ' procedures are non-warp now (' + n + ' changed)');
});

// ---- P67: finish the non-warp chain (the "first demo is still slow" fix) ----
//
// v4.31 flipped the call + expression chain, but demo1 is `print(area(3, 4))` and the
// argument evaluation happens inside `printargs` -- still warp, sitting right above
// `eval`, so everything below it inherited warp again and a step inside area() still
// cost 501ms.
//
// Found by walking the block graph: `_work/v41/callgraph.cjs` computes every procedure
// that can transitively reach `calluser`; only three were still warp:
//   printargs  (print),  minmax (min/max & friends),  regdef (default arguments)
// After flipping them: demo1 step 501ms -> 47ms.
//
// On top of that this patch *checks* the closure at build time: if any procedure that
// can reach calluser is still warp, the build fails -- so a future syntax path cannot
// silently bring back the half-second step.
patch('P67 print chain', () => {
  const MORE = ['printargs', 'minmax %s %s %s', 'regdef %s'];
  const protos = {};
  for (const b of Object.values(BL())) {
    if (b.opcode === 'procedures_prototype' && b.mutation) protos[b.mutation.proccode] = b;
  }
  let n = 0;
  for (const code of MORE) {
    const b = protos[code];
    if (!b) throw new Error('[P67] procedure not found: ' + code);
    if (b.mutation.warp !== 'false') n++;
    b.mutation.warp = 'false';
  }
  console.log('[P67] ' + MORE.length + ' more procedures are non-warp (' + n + ' changed)');
  // build-time closure check: everything that can reach calluser must be non-warp
  const defs = {};
  for (const [id, b] of Object.entries(BL())) {
    if (b.opcode === 'procedures_definition' && b.inputs.custom_block) {
      const pr = BL()[b.inputs.custom_block[1]];
      if (pr && pr.mutation) defs[id] = pr.mutation.proccode;
    }
  }
  const edges = {};
  for (const [defId, code] of Object.entries(defs)) {
    const calls = new Set();
    const seen = new Set();
    const stack = [BL()[defId].next];
    while (stack.length) {
      const id = stack.pop();
      if (!id || seen.has(id)) continue;
      const b = BL()[id];
      if (!b) continue;
      seen.add(id);
      if (b.opcode === 'procedures_call' && b.mutation) calls.add(b.mutation.proccode);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
    edges[code] = calls;
  }
  const reach = new Set(['calluser %s %s %s']);
  let grew = true;
  while (grew) {
    grew = false;
    for (const [code, calls] of Object.entries(edges)) {
      if (reach.has(code)) continue;
      for (const c of calls) if (reach.has(c)) { reach.add(code); grew = true; break; }
    }
  }
  const still = [...reach].filter((code) => protos[code] && protos[code].mutation.warp !== 'false');
  if (still.length) throw new Error('[P67] these can still reach calluser but stay warp: ' + still.join(', '));
  console.log('[P67] checked: all ' + reach.size + ' procedures on the path to calluser are non-warp');
});

// ---- P70: bitwise augmented assignment (E5/E6) ----
//
// `b &= 10` never merges in the tokenizer ('&' is not in its "can be followed by ="
// set), so it arrives as four tokens [name, '&', '=', value].  `b <<= 1` takes the same
// shape because `<`+`<` merges into '<<' but the '=' stays behind.  So one branch in
// execute covers all five operators: reuse `rightside` (it already implements & | ^ << >>)
// and hand it the operator token plus the value starting at index 4.
patch('P70 bitwise augmented assign', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const isTokAt = (d, idx) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    if (!b || b.opcode !== 'data_itemoflist') return false;
    if (!b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
    return litOf(b.inputs.INDEX) === String(idx);
  };
  const eqTokAt = (condId, idx, lit) => [...reach(condId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (isTokAt(a, idx) && litOf(c) === lit) || (isTokAt(c, idx) && litOf(a) === lit);
  });
  const ex = inDef('execute');
  // the "+=" / "-=" / ... branch has a unique condition (item 2 of Tok == "+=")
  const plusEq = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && eqTokAt(b.inputs.CONDITION[1], 2, '+='));
  if (plusEq.length !== 1) throw new Error('[P70] "+=" branch = ' + plusEq.length);
  const opIsBit = I('operator_contains', { inputs: { STRING1: B.REP(txt('&|^<<>>'), [10, '']), STRING2: B.REP(item('Tok', num(2)), [10, '']) } });
  const branch = IF(
    AND(AND(EQ(item('Kind', num(1)), txt('I')), EQ(item('Tok', num(3)), txt('='))), opIsBit),
    [
      setV('name', item('Tok', num(1))),
      callProc('lookup %s', [VAR('name')]),
      IFELSE(EQ(VAR('found'), num(0)),
        [FAILB(JOIN(txt('NameError: '), VAR('name')))],
        [
          callProc('rightside %s %s %s %s %s', [item('Values', VAR('found')), item('Types', VAR('found')), item('Tok', num(2)), num(4), VAR('count')]),
          IF(EQ(VAR('error'), txt('')), [callProc('assign %s %s %s', [VAR('name'), VAR('ev'), VAR('evtype')])])
        ]),
      setV('pending', num(1))
    ]
  );
  insertBeforeStmt(plusEq[0], [branch]);
  console.log('[P70] & | ^ << >> augmented assignment installed');
});

// ---- P71: numeric literals -- 1e3 / 0x10 / 0b101 / 0o17 (E1/E2/E3) ----
//
// Two halves:
//   * tokenize: the number branch stops at the first char outside "0123456789.", so
//     "0x10" became [0, x10] and "1e3" became [1, e3].  Extend the scan: a leading 0
//     followed by x/X/o/O/b/B swallows the matching digit alphabet, otherwise the plain
//     digit run may be followed by an exponent (e/E, optional sign, at least one digit).
//   * atom: the token text is what gets printed, so 0x10 must be rewritten to "16" and
//     1e3 to a float before anything looks at it.  numlit does the rewrite (via basenum
//     for the base prefixes, via a mantissa * 10**exp for the exponent) and leaves plain
//     literals untouched.
patch('P71 numeric literals', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['nls', 'npos', 'nmn', 'nex', 'nbase', 'bdig', 'bstr', 'bacc', 'bi', 'bj', 'bc', 'bd', 'nres', 'nidx', 'nflt', 'est', 'bsg']) {
    if (taken.has(n)) throw new Error('[P71] variable name taken: ' + n);
  }
  if (Object.values(T(IT).lists).some((x) => x[0] === 'NConv')) throw new Error('[P71] list name taken');
  for (const v of ['nls', 'npos', 'nmn', 'nex', 'nbase', 'bstr', 'bacc', 'bi', 'bj', 'bc', 'bd', 'nres', 'nidx', 'nflt', 'est', 'bsg']) newVar(v, 0);
  newVar('bdig', '0123456789abcdefghijklmnopqrstuvwxyz');
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const inSet = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const CEIL = (x) => I('operator_mathop', { fields: { OPERATOR: ['ceiling', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const pow10 = (x) => I('operator_mathop', { fields: { OPERATOR: ['10 ^', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  // NB: every use needs its OWN argument reporter.  A single reporter block shared by
  // many inputs (shadow:true, 19 references) silently evaluated to garbage in scratch-vm.
  const src = () => I('argument_reporter_string_number', { fields: { VALUE: ['source', null] } });
  const chAt = (i) => letterOf(i, src());

  // ---------- (a) tokenizer: one number token may be 0x.. / 0o.. / 0b.. / 1.5e-3
  const tk = inDef('tokenize %s');
  const numIf = find(tk, (b) => {
    if ((b.opcode !== 'control_if' && b.opcode !== 'control_if_else') || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const cb = BL()[b.inputs.CONDITION[1]];
    if (!cb || cb.opcode !== 'operator_contains') return false;
    return litOf(cb.inputs.STRING1) === '0123456789.' || litOf(cb.inputs.STRING2) === '0123456789.';
  });
  if (numIf.length !== 1) throw new Error('[P71] tokenize number branch = ' + numIf.length);
  const numSub = BL()[numIf[0]].inputs.SUBSTACK;
  const numFirst = (numSub && typeof numSub[1] === 'string') ? numSub[1] : null;
  if (!numFirst) throw new Error('[P71] tokenize number branch has no substack');
  const initEt = find(reach(numFirst), (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'et' && litOf(b.inputs.VALUE) === '');
  if (initEt.length !== 1) throw new Error('[P71] tokenize et init = ' + initEt.length);
  detachTail(initEt[0]);   // drops the old digit scan + the two appends
  const eatDigits = (set) => REPEATU(OR(GT(VAR('ep'), lenOf(src())), NOT(inSet(chAt(VAR('ep')), set))), [
    setV('et', JOIN(VAR('et'), chAt(VAR('ep')))),
    chgV('ep', num(1))
  ]);
  spliceAfter(initEt[0], chain([
    IFELSE(
      AND(EQ(VAR('ec'), txt('0')), inSet(chAt(ADD(VAR('ep'), num(1))), 'xXoObB')),
      [
        setV('et', JOIN(VAR('ec'), chAt(ADD(VAR('ep'), num(1))))),
        chgV('ep', num(2)),
        eatDigits('0123456789abcdefABCDEF')
      ],
      [
        eatDigits('0123456789.'),
        IF(AND(NOT(GT(VAR('ep'), lenOf(src()))), inSet(chAt(VAR('ep')), 'eE')), [
          IFELSE(inSet(chAt(ADD(VAR('ep'), num(1))), '+-'),
            [setV('est', ADD(VAR('ep'), num(2)))],
            [setV('est', ADD(VAR('ep'), num(1)))]),
          IF(AND(NOT(GT(VAR('est'), lenOf(src()))), inSet(chAt(VAR('est')), '0123456789')), [
            setV('et', JOIN(VAR('et'), chAt(VAR('ep')))),
            chgV('ep', num(1)),
            IF(inSet(chAt(VAR('ep')), '+-'), [
              setV('et', JOIN(VAR('et'), chAt(VAR('ep')))),
              chgV('ep', num(1))
            ]),
            eatDigits('0123456789')
          ])
        ])
      ]),
    addTo('Tok', VAR('et')),
    addTo('Kind', txt('N'))
  ]));
  console.log('[P71] tokenizer reads 0x/0o/0b and exponents');

  // ---------- (b) basenum: digit-by-digit parse in an arbitrary base
  const bs = newProc('basenum %s %s', ['s', 'b']);
  attachBody(bs.defId, [
    callProc('scase %s %s', [argOf('s'), txt('lower')]),
    setV('bstr', VAR('ev')),
    setV('bacc', num(0)),
    setV('bi', num(1)),
    setV('bsg', num(0)),
    IF(EQ(letterOf(num(1), VAR('bstr')), txt('-')), [setV('bsg', num(1)), setV('bi', num(2))]),
    IF(EQ(letterOf(num(1), VAR('bstr')), txt('+')), [setV('bi', num(2))]),
    REPEATU(GT(VAR('bi'), lenOf(VAR('bstr'))), [
      setV('bc', letterOf(VAR('bi'), VAR('bstr'))),
      setV('bd', num(-1)),
      setV('bj', num(1)),
      REPEATU(OR(GT(VAR('bj'), num(36)), NOT(LT(VAR('bd'), num(0)))), [
        IF(EQ(letterOf(VAR('bj'), VAR('bdig')), VAR('bc')), [setV('bd', SUB(VAR('bj'), num(1)))]),
        chgV('bj', num(1))
      ]),
      IF(OR(LT(VAR('bd'), num(0)), NOT(LT(VAR('bd'), argOf('b')))), [FAIL('ValueError: invalid literal for int()')]),
      setV('bacc', ADD(MUL(VAR('bacc'), argOf('b')), VAR('bd'))),
      chgV('bi', num(1))
    ]),
    IF(EQ(VAR('bsg'), num(1)), [setV('bacc', SUB(num(0), VAR('bacc')))]),
    setV('ev', VAR('bacc')),
    setV('evtype', txt('N'))
  ]);

  // ---------- (c) numlit: rewrite the token text into a plain decimal / float
  const nl = newProc('numlit %s', ['s']);
  attachBody(nl.defId, [
    setV('nres', argOf('s')),
    setV('nbase', num(0)),
    setV('nflt', num(0)),
    IF(AND(GT(lenOf(argOf('s')), num(1)), EQ(letterOf(num(1), argOf('s')), txt('0'))), [
      IF(inSet(letterOf(num(2), argOf('s')), 'xX'), [setV('nbase', num(16))]),
      IF(inSet(letterOf(num(2), argOf('s')), 'oO'), [setV('nbase', num(8))]),
      IF(inSet(letterOf(num(2), argOf('s')), 'bB'), [setV('nbase', num(2))])
    ]),
    IFELSE(GT(VAR('nbase'), num(0)), [
      callProc('substr %s %s %s', [argOf('s'), num(3), lenOf(argOf('s'))]),
      callProc('basenum %s %s', [VAR('ev'), VAR('nbase')]),
      setV('nres', VAR('ev'))
    ], [
      // plain literals (the common case: "1", "42", "3.5") have no exponent -- an
      // exponent needs at least three characters, so short tokens skip the scan.
      // No scase() here: it walks the 95-char charset per character and made every
      // numeric literal in a running program cost ~500 block steps.
      IF(GT(lenOf(argOf('s')), num(2)), [
        setV('npos', num(0)),
        setV('nidx', num(1)),
        REPEATU(GT(VAR('nidx'), lenOf(argOf('s'))), [
          IF(OR(EQ(letterOf(VAR('nidx'), argOf('s')), txt('e')), EQ(letterOf(VAR('nidx'), argOf('s')), txt('E'))), [setV('npos', VAR('nidx'))]),
          chgV('nidx', num(1))
        ]),
        IF(GT(VAR('npos'), num(1)), [
          callProc('substr %s %s %s', [argOf('s'), num(1), SUB(VAR('npos'), num(1))]),
          setV('nmn', VAR('ev')),
          callProc('substr %s %s %s', [argOf('s'), ADD(VAR('npos'), num(1)), lenOf(argOf('s'))]),
          setV('nex', VAR('ev')),
          setV('nres', MUL(VAR('nmn'), pow10(VAR('nex')))),
          setV('nflt', num(1))
        ])
      ])
    ]),
    setV('ev', VAR('nres')),
    setV('evtype', txt('N')),
    IF(EQ(VAR('nflt'), num(1)), [callProc('mkfloat %s', [VAR('ev')])])
  ]);
  console.log('[P71] basenum + numlit registered');

  // ---------- (d) atom goes through numlit before validating the text.
  // A base prefix or an exponent needs at least three characters ("0x1", "1e3"), so
  // one-to-two character literals -- the ones a hot loop is full of -- skip the call.
  if (process.env.V41_NO_ATOMHOOK) { console.log('[P71] atom hook DISABLED (debug)'); return; }
  const at = inDef('atom %s');
  const nc = find(at, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'numbercheck %s');
  if (nc.length !== 1) throw new Error('[P71] atom numbercheck = ' + nc.length);
  insertBeforeStmt(nc[0], [
    IF(GT(lenOf(VAR('ev')), num(2)), [callProc('numlit %s', [VAR('ev')])])
  ]);
  console.log('[P71] atom rewrites prefixed / exponent literals');
});

// ---- P72: string escapes \n and \t (E20/E21) ----
//
// The string reader already consumed the backslash and kept the following character
// verbatim, so 'a\nb' became "anb".  Map the two escapes CPython actually needs here to
// real control characters, and teach `log` to treat a newline as a row break (the console
// is a list of rows, so an embedded \n would otherwise never match CPython's two lines).
patch('P72 string escapes', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('lch')) throw new Error('[P72] variable name taken: lch');
  newVar('lch', '');
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const LF = String.fromCharCode(10);
  const TAB = String.fromCharCode(9);
  // (a) tokenizer: "ec = letter ep of source" inside the backslash branch of the string reader
  const tk = inDef('tokenize %s');
  const isEcRead = (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ec'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'operator_letter_of';
  const escRead = find(tk, (b, id) => {
    if (!isEcRead(b)) return false;
    const par = BL()[id].parent;
    if (par && BL()[par] && BL()[par].opcode === 'control_if') return true;
    const pr = predecessorOf(id);
    return !!(pr && BL()[pr].opcode === 'data_changevariableby' && BL()[pr].fields.VARIABLE && BL()[pr].fields.VARIABLE[0] === 'ep');
  });
  if (escRead.length !== 1) throw new Error('[P72] escaped-char read = ' + escRead.length);
  spliceAfter(escRead[0], chain([
    IF(EQ(VAR('ec'), txt('n')), [setV('ec', txt(LF))]),
    IF(EQ(VAR('ec'), txt('t')), [setV('ec', txt(TAB))])
  ]));
  console.log('[P72] \\n and \\t decode in string literals');
  // (b) log: a newline flushes the current row
  const lg = inDef('log %s');
  const addLt = find(lg, (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'lt'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'operator_join');
  if (addLt.length !== 1) throw new Error('[P72] log accumulate = ' + addLt.length);
  insertBeforeStmt(addLt[0], [setV('lch', letterOf(VAR('lj'), argOf('message')))]);
  const brk = IFELSE(EQ(VAR('lch'), txt(LF)),
    [addTo('Output', VAR('lt')), setV('lt', txt(''))],
    [setV('lt', JOIN(VAR('lt'), VAR('lch')))]);
  replaceStmt(addLt[0], brk);
  console.log('[P72] log breaks rows on a newline');
});

// ---- P73: semicolon separated statements (E4) ----
//
// `a = 1; b = 2` is two statements on one line.  Like P30's one-liner expander this is a
// pure source rewrite, run *after* expandlines so that `for i in range(3): a; b` first
// becomes a block line and only then gets split (both halves stay in the loop body).
// Each piece keeps the original indentation, so prepare's 4-space rule still holds;
// empty pieces (trailing ";") are dropped.
patch('P73 semicolon statements', () => {
  const tv = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['qsrc', 'qind', 'qdep', 'qstr', 'qidx', 'qch', 'qesc', 'qlo', 'qk', 'qst']) {
    if (tv.has(n)) throw new Error('[P73] variable name taken: ' + n);
  }
  for (const l of ['QSpos', 'QNew']) {
    if (Object.values(T(IT).lists).some((x) => x[0] === l)) throw new Error('[P73] list name taken: ' + l);
  }
  for (const v of ['qsrc', 'qind', 'qdep', 'qstr', 'qidx', 'qch', 'qesc', 'qlo', 'qk', 'qst']) newVar(v, 0);
  B.addList(IT, 'QSpos', []);
  B.addList(IT, 'QNew', []);
  const inSet = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const sp = newProc('splitlines', []);
  attachBody(sp.defId, [
    clearL('QNew'),
    setV('qidx', num(1)),
    REPEATU(GT(VAR('qidx'), llen('Code')), [
      setV('qsrc', item('Code', VAR('qidx'))),
      // leading indent of this line, and the index of its first content char
      setV('qind', txt('')),
      setV('qk', num(1)),
      REPEATU(OR(GT(VAR('qk'), lenOf(VAR('qsrc'))), NOT(EQ(letterOf(VAR('qk'), VAR('qsrc')), txt(' ')))), [
        setV('qind', JOIN(VAR('qind'), txt(' '))),
        chgV('qk', num(1))
      ]),
      setV('qst', VAR('qk')),
      clearL('QSpos'),
      setV('qdep', num(0)),
      setV('qstr', txt('')),
      setV('qesc', num(0)),
      setV('qlo', VAR('qst')),
      REPEATU(GT(VAR('qlo'), lenOf(VAR('qsrc'))), [
        setV('qch', letterOf(VAR('qlo'), VAR('qsrc'))),
        IFELSE(EQ(VAR('qesc'), num(1)), [
          setV('qesc', num(0))
        ], [
          IFELSE(NOT(EQ(VAR('qstr'), txt(''))), [
            IFELSE(EQ(VAR('qch'), VAR('slash')), [setV('qesc', num(1))], [
              IF(EQ(VAR('qch'), VAR('qstr')), [setV('qstr', txt(''))])
            ])
          ], [
            IFELSE(OR(EQ(VAR('qch'), txt("'")), EQ(VAR('qch'), VAR('dq'))), [
              setV('qstr', VAR('qch'))
            ], [
              IFELSE(EQ(VAR('qch'), txt('#')), [
                setV('qlo', ADD(lenOf(VAR('qsrc')), num(1)))
              ], [
                IF(inSet(VAR('qch'), '([{'), [chgV('qdep', num(1))]),
                IF(inSet(VAR('qch'), ')]}'), [chgV('qdep', num(-1))]),
                IF(AND(EQ(VAR('qdep'), num(0)), EQ(VAR('qch'), txt(';'))), [addTo('QSpos', VAR('qlo'))])
              ])
            ])
          ])
        ]),
        chgV('qlo', num(1))
      ]),
      IFELSE(EQ(llen('QSpos'), num(0)), [
        addTo('QNew', VAR('qsrc'))
      ], [
        setV('qk', VAR('qst')),
        setV('qlo', num(1)),
        REPEATU(GT(VAR('qlo'), llen('QSpos')), [
          callProc('substr %s %s %s', [VAR('qsrc'), VAR('qk'), SUB(item('QSpos', VAR('qlo')), num(1))]),
          callProc('trimsp %s', [VAR('ev')]),
          IF(GT(lenOf(VAR('ev')), num(0)), [addTo('QNew', JOIN(VAR('qind'), VAR('ev')))]),
          setV('qk', ADD(item('QSpos', VAR('qlo')), num(1))),
          chgV('qlo', num(1))
        ]),
        callProc('substr %s %s %s', [VAR('qsrc'), VAR('qk'), lenOf(VAR('qsrc'))]),
        callProc('trimsp %s', [VAR('ev')]),
        IF(GT(lenOf(VAR('ev')), num(0)), [addTo('QNew', JOIN(VAR('qind'), VAR('ev')))])
      ]),
      chgV('qidx', num(1))
    ]),
    clearL('Code'),
    setV('qidx', num(1)),
    REPEATU(GT(VAR('qidx'), llen('QNew')), [addTo('Code', item('QNew', VAR('qidx'))), chgV('qidx', num(1))])
  ]);
  console.log('[P73] splitlines registered');
  // after the three expandlines calls, immediately before prepare
  const prep = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'prepare');
  if (prep.length !== 1) throw new Error('[P73] prepare call sites = ' + prep.length);
  insertBeforeStmt(prep[0], [callProc('splitlines')]);
  console.log('[P73] splitlines installed before prepare');
});

// ---- P74: list concatenation and repetition (E9/E10) ----
//
// `[1, 2] + [3]` fell into the "use str(number)" error and `[0] * 3` into "numeric
// operands".  Lists are encoded as a flat run of (lsep + type + text) records, so
// concatenating two encodings is exactly list + list, and repeating one n times is
// list * n -- no need to touch listlen/listitem at all.
//
// The two existing operator blocks must be told to leave these cases alone (they both
// look at "is one side not a number", which a list satisfies), and the unconditional
// mkfloat probes would otherwise promote a float-looking list to a number.
patch('P74 list plus and times', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const isArgEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((argName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (argName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isVarEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((varName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (varName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isNotOf = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_not' && isVarEq(b.inputs.OPERAND, name, lit); };
  const isDotContains = (d) => { const b = blk(d); return !!b && b.opcode === 'operator_contains' && litOf(b.inputs.STRING2) === '.'; };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['mrn', 'mrv']) if (taken.has(n)) throw new Error('[P74] variable name taken: ' + n);
  newVar('mrn', 0);
  newVar('mrv', '');
  const rs = inDef('rightside %s %s %s %s %s');

  // (1) the "+" branch: skip it when both sides are lists
  const plusEq = find(rs, (b, id) => isArgEq([2, id], 'op', '+'));
  if (plusEq.length !== 1) throw new Error('[P74] plus condition = ' + plusEq.length);
  const plusIfs = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && b.inputs.CONDITION[1] === plusEq[0]);
  if (plusIfs.length !== 1) throw new Error('[P74] plus if = ' + plusIfs.length);
  const plusIf = plusIfs[0];
  replaceExpr(plusEq[0], () => AND(plusEq[0], NOT(AND(EQ(VAR('lt2'), txt('L')), EQ(VAR('evtype'), txt('L'))))));

  // (2) the string "*" branch: skip it when either side is a list.
  //     NB the same condition is duplicated inside the numeric branch's guard, and that
  //     copy must stay as it is (it already skips lists once evtype is L).
  const starIfs = find(rs, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const a = BL()[b.inputs.CONDITION[1]];
    if (!a || a.opcode !== 'operator_and' || !isArgEq(a.inputs.OPERAND1, 'op', '*')) return false;
    const or = blk(a.inputs.OPERAND2);
    return !!or && or.opcode === 'operator_or' && isVarEq(or.inputs.OPERAND1, 'lt2', 'S') && isNotOf(or.inputs.OPERAND2, 'evtype', 'N');
  });
  if (starIfs.length !== 1) throw new Error('[P74] star branch = ' + starIfs.length);
  const starOr = BL()[BL()[starIfs[0]].inputs.CONDITION[1]].inputs.OPERAND2[1];
  // the new blocks run first and set evtype to L, so "skip when either side is a list"
  // has to look at the *current* evtype, not only at the original operand types
  replaceExpr(starOr, () => AND(starOr, NOT(OR(EQ(VAR('lt2'), txt('L')), EQ(VAR('evtype'), txt('L'))))));

  // (3) the two mkfloat probes must not fire on a list value
  const dotIfs = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]] && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && isDotContains(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1) && isDotContains(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2));
  if (dotIfs.length !== 2) throw new Error('[P74] mkfloat probes = ' + dotIfs.length);
  for (const id of dotIfs) {
    const cond = BL()[id].inputs.CONDITION[1];
    replaceExpr(cond, () => AND(cond, NOT(EQ(VAR('evtype'), txt('L')))));
  }

  // (4) the new handling itself
  const listPlus = IF(AND(EQ(argOf('op'), txt('+')), AND(EQ(VAR('lt2'), txt('L')), EQ(VAR('evtype'), txt('L')))), [
    setV('ev', JOIN(argOf('leftval'), VAR('ev'))),
    setV('evtype', txt('L'))
  ]);
  const repeatEnc = (count, piece) => [
    setV('mrn', count),
    setV('mrv', txt('')),
    REPEAT(VAR('mrn'), [setV('mrv', JOIN(VAR('mrv'), piece))]),
    setV('ev', VAR('mrv')),
    setV('evtype', txt('L'))
  ];
  const listTimes = IF(AND(EQ(argOf('op'), txt('*')), AND(EQ(VAR('lt2'), txt('L')), EQ(VAR('evtype'), txt('N')))),
    repeatEnc(VAR('ev'), argOf('leftval')));
  const listTimesR = IF(AND(EQ(argOf('op'), txt('*')), AND(EQ(VAR('lt2'), txt('N')), EQ(VAR('evtype'), txt('L')))),
    repeatEnc(argOf('leftval'), VAR('ev')));
  insertBeforeStmt(plusIf, [listPlus, listTimes, listTimesR]);
  console.log('[P74] list + and list * installed');
});

// ---- P75: string methods index / title / zfill / isdigit / isalpha (E13/E14/E15) ----
//
// Five more branches in methodcall's S section, plus the membership list of "known
// method names" has to grow or the trailing guard still raises AttributeError.
patch('P75 more string methods', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['ti', 'tout', 'tprev', 'tc', 'zf', 'zi', 'zw', 'sci', 'scok', 'scc']) {
    if (taken.has(n)) throw new Error('[P75] variable name taken: ' + n);
  }
  for (const v of ['ti', 'tout', 'tprev', 'tc', 'zf', 'zi', 'zw', 'sci', 'scok', 'scc']) newVar(v, 0);
  const inSet = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const ALPHA = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const DIGITS = '0123456789';

  // title(): upper-case the first letter of every word
  const st = newProc('stitle %s', ['s']);
  attachBody(st.defId, [
    setV('ti', num(1)),
    setV('tout', txt('')),
    setV('tprev', txt(' ')),
    REPEATU(GT(VAR('ti'), lenOf(argOf('s'))), [
      setV('tc', letterOf(VAR('ti'), argOf('s'))),
      IFELSE(OR(EQ(VAR('tprev'), txt(' ')), NOT(inSet(VAR('tprev'), ALPHA))), [
        callProc('scase %s %s', [VAR('tc'), txt('upper')]),
        setV('tc', VAR('ev'))
      ], [
        callProc('scase %s %s', [VAR('tc'), txt('lower')]),
        setV('tc', VAR('ev'))
      ]),
      setV('tout', JOIN(VAR('tout'), VAR('tc'))),
      setV('tprev', VAR('tc')),
      chgV('ti', num(1))
    ]),
    setV('ev', VAR('tout')),
    setV('evtype', txt('S'))
  ]);

  // zfill(w): left-pad with zeroes
  const zf = newProc('szfill %s %s', ['s', 'w']);
  attachBody(zf.defId, [
    setV('zf', argOf('s')),
    setV('zi', lenOf(VAR('zf'))),
    setV('zw', ADD(argOf('w'), num(0))),
    REPEATU(NOT(LT(VAR('zi'), VAR('zw'))), [
      setV('zf', JOIN(txt('0'), VAR('zf'))),
      chgV('zi', num(1))
    ]),
    setV('ev', VAR('zf')),
    setV('evtype', txt('S'))
  ]);

  // isdigit() / isalpha(): every character belongs to the class, and the string is not empty
  const sc = newProc('sclass %s %s', ['s', 'mode']);
  attachBody(sc.defId, [
    setV('sci', num(1)),
    setV('scok', num(1)),
    IF(EQ(lenOf(argOf('s')), num(0)), [setV('scok', num(0))]),
    REPEATU(GT(VAR('sci'), lenOf(argOf('s'))), [
      setV('scc', letterOf(VAR('sci'), argOf('s'))),
      IFELSE(EQ(argOf('mode'), txt('isdigit')), [
        IF(NOT(inSet(VAR('scc'), DIGITS)), [setV('scok', num(0))])
      ], [
        IF(NOT(inSet(VAR('scc'), ALPHA)), [setV('scok', num(0))])
      ]),
      chgV('sci', num(1))
    ]),
    setV('ev', VAR('scok')),
    setV('evtype', txt('B'))
  ]);
  console.log('[P75] stitle / szfill / sclass registered');

  // hook the five names into methodcall
  const mc = inDef('methodcall %s %s');
  const guard = find(mc, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const nb = BL()[b.inputs.CONDITION[1]];
    if (!nb || nb.opcode !== 'operator_not') return false;
    return [...reach(b.inputs.CONDITION[1])].some((id) => {
      const e = BL()[id];
      if (!e || e.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
      return (vn(e.inputs.OPERAND1) === 'smmeth' && litOf(e.inputs.OPERAND2) === 'join')
        || (vn(e.inputs.OPERAND2) === 'smmeth' && litOf(e.inputs.OPERAND1) === 'join');
    });
  });
  if (guard.length !== 1) throw new Error('[P75] method guard = ' + guard.length);
  const notId = BL()[guard[0]].inputs.CONDITION[1];
  insertBeforeStmt(guard[0], [
    IF(EQ(VAR('smmeth'), txt('index')), [
      callProc('sfind %s %s', [VAR('smrec'), VAR('sma1')]),
      IF(LT(VAR('ev'), num(0)), [FAIL('ValueError: substring not found')])
    ]),
    IF(EQ(VAR('smmeth'), txt('title')), [callProc('stitle %s', [VAR('smrec')])]),
    IF(EQ(VAR('smmeth'), txt('zfill')), [callProc('szfill %s %s', [VAR('smrec'), VAR('sma1')])]),
    IF(OR(EQ(VAR('smmeth'), txt('isdigit')), EQ(VAR('smmeth'), txt('isalpha'))), [
      callProc('sclass %s %s', [VAR('smrec'), VAR('smmeth')])
    ])
  ]);
  const knownNew = OR(EQ(VAR('smmeth'), txt('index')), OR(EQ(VAR('smmeth'), txt('title')),
    OR(EQ(VAR('smmeth'), txt('zfill')), OR(EQ(VAR('smmeth'), txt('isdigit')), EQ(VAR('smmeth'), txt('isalpha'))))));
  replaceExpr(notId, () => AND(notId, NOT(knownNew)));
  console.log('[P75] methodcall accepts the five new names');
});

// ---- P76: list methods return None, and type() prints like CPython (G1/G6) ----
//
// Two silent differences:
//   * list mutators left ev = "" with type "S", so `print(a.append(2))` printed an empty
//     line instead of None.  The interpreter's None is type Z with an empty value, and
//     strval(Z) already prints "None" -- only the type tag has to change.
//   * type() produced bare names ("int"); CPython prints "<class 'int'>".
patch('P76 None returns and type()', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  // (a) every "ev = '' ; evtype = 'S'" pair inside methodcall is a list mutator
  const mc = inDef('methodcall %s %s');
  const setEv = find(mc, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev' && litOf(b.inputs.VALUE) === '');
  let n = 0;
  for (const id of setEv) {
    const nx = BL()[id].next;
    if (!nx) continue;
    const nb = BL()[nx];
    if (nb && nb.opcode === 'data_setvariableto' && nb.fields.VARIABLE && nb.fields.VARIABLE[0] === 'evtype' && litOf(nb.inputs.VALUE) === 'S') {
      nb.inputs.VALUE = txt('Z');
      n++;
    }
  }
  if (n !== 7) throw new Error('[P76] list mutator None returns = ' + n);
  console.log('[P76] ' + n + ' list methods now return None');
  // (b) type(): full class spelling, appended after the existing branch (which still sets
  //     ev to a bare name first, so this must run last inside the type block)
  const cf = inDef('callfn %s %s %s');
  const typeIf = find(cf, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const e = BL()[b.inputs.CONDITION[1]];
    if (!e || e.opcode !== 'operator_equals') return false;
    const an = (d) => { const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null; return bb && bb.opcode === 'argument_reporter_string_number' ? bb.fields.VALUE[0] : null; };
    return (an(e.inputs.OPERAND1) === 'fn' && litOf(e.inputs.OPERAND2) === 'type')
      || (an(e.inputs.OPERAND2) === 'fn' && litOf(e.inputs.OPERAND1) === 'type');
  });
  if (typeIf.length !== 1) throw new Error('[P76] type() branch = ' + typeIf.length);
  // NB reach() walks `next` as well, so start from the branch's own substack -- otherwise
  // the whole rest of callfn (ord/chr/repr/sorted/...) is included and the probe is not unique.
  const tsub = BL()[typeIf[0]].inputs.SUBSTACK;
  const tfirst = (tsub && typeof tsub[1] === 'string') ? tsub[1] : null;
  if (!tfirst) throw new Error('[P76] type() branch has no substack');
  // the branch ends with "evtype = 'S'": build the spelling while evtype still holds the
  // real type, and let that assignment run afterwards.
  const evtSet = find(reach(tfirst), (b) => b.opcode === 'data_setvariableto'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'evtype' && litOf(b.inputs.VALUE) === 'S');
  if (evtSet.length !== 1) throw new Error('[P76] type() evtype set = ' + evtSet.length);
  const cls = (v) => EQ(VAR('evtype'), txt(v));
  const cases = [['B', "<class 'bool'>"], ['Z', "<class 'NoneType'>"], ['L', "<class 'list'>"], ['T', "<class 'tuple'>"],
                 ['D', "<class 'dict'>"], ['S', "<class 'str'>"], ['O', "<class 'object'>"], ['F', "<class 'function'>"]];
  let tail = IFELSE(I('operator_contains', { inputs: { STRING1: B.REP(VAR('ev'), [10, '']), STRING2: B.REP(txt('.'), [10, '']) } }),
    [setV('ev', txt("<class 'float'>"))],
    [setV('ev', txt("<class 'int'>"))]);
  for (let i = cases.length - 1; i >= 0; i--) tail = IFELSE(cls(cases[i][0]), [setV('ev', txt(cases[i][1]))], [tail]);
  insertBeforeStmt(evtSet[0], [tail]);
  console.log('[P76] type() prints <class ...>');
});

// ---- P77: %-format width/precision + f-string format spec (E17/E18/E19/G4) ----
//
// `'%5d|' % 42` printed "42d|" and `'%.2f' % 3.14159` printed "3.141592f": pctfmt only
// looked at the single character after '%' and never parsed flags/width/precision.
// f-string had the mirror-image gap: `f'{x:.2f}'` searched for the closing '}' over the
// whole "x:.2f", so the ':' and the spec leaked into the expression.
//
// One shared procedure does the real work -- pctitem(value, type, spec, conv) -- so the
// f-string path and the % path format identically.  spec carries the flags/width/precision
// ("5", ".2", "-8.3") and conv the conversion character (d/f/s).
patch('P77 percent and f-string formats', () => {
  const tv = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['pwi', 'pwid', 'ppr', 'phas', 'pleft', 'ptx', 'pnn', 'pqq', 'psg', 'pab', 'pmu', 'pn2', 'pin', 'pfr', 'pfs', 'ppad', 'pok',
                   'fz1', 'fz2', 'fz3', 'fz4', 'fz5', 'fz6']) {
    if (tv.has(n)) throw new Error('[P77] variable name taken: ' + n);
  }
  for (const v of ['pwi', 'pwid', 'ppr', 'phas', 'pleft', 'ptx', 'pnn', 'pqq', 'psg', 'pab', 'pmu', 'pn2', 'pin', 'pfr', 'pfs', 'ppad', 'pok',
                   'fz1', 'fz2', 'fz3', 'fz4', 'fz5', 'fz6']) newVar(v, 0);
  const inSet = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const CEIL = (x) => I('operator_mathop', { fields: { OPERATOR: ['ceiling', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });

  // ---------- pctitem: format one value into ev
  const pi = newProc('pctitem %s %s %s %s', ['vv', 'vt', 'spec', 'conv']);
  attachBody(pi.defId, [
    setV('pwi', num(1)),
    setV('pwid', num(0)),
    setV('ppr', num(0)),
    setV('phas', num(0)),
    setV('pleft', num(0)),
    setV('pok', num(0)),
    IF(AND(GT(lenOf(argOf('spec')), num(0)), EQ(letterOf(num(1), argOf('spec')), txt('-'))), [
      setV('pleft', num(1)),
      setV('pwi', num(2))
    ]),
    REPEATU(OR(GT(VAR('pwi'), lenOf(argOf('spec'))), EQ(letterOf(VAR('pwi'), argOf('spec')), txt('.'))), [
      IF(inSet(letterOf(VAR('pwi'), argOf('spec')), '0123456789'), [
        setV('pwid', ADD(MUL(VAR('pwid'), num(10)), letterOf(VAR('pwi'), argOf('spec'))))
      ]),
      chgV('pwi', num(1))
    ]),
    IF(AND(NOT(GT(VAR('pwi'), lenOf(argOf('spec')))), EQ(letterOf(VAR('pwi'), argOf('spec')), txt('.'))), [
      chgV('pwi', num(1)),
      setV('phas', num(1)),
      REPEATU(GT(VAR('pwi'), lenOf(argOf('spec'))), [
        IF(inSet(letterOf(VAR('pwi'), argOf('spec')), '0123456789'), [
          setV('ppr', ADD(MUL(VAR('ppr'), num(10)), letterOf(VAR('pwi'), argOf('spec'))))
        ]),
        chgV('pwi', num(1))
      ])
    ]),
    setV('ptx', txt('')),
    // %d -- integer, truncated toward zero
    IF(EQ(argOf('conv'), txt('d')), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL('%d format: a number is required')]),
      setV('pnn', FLOOR(argOf('vv'))),
      IF(LT(argOf('vv'), num(0)), [setV('pnn', CEIL(argOf('vv')))]),
      setV('ptx', VAR('pnn')),
      setV('pok', num(1))
    ]),
    // %f -- fixed point, 6 decimals unless a precision was given
    IF(OR(EQ(argOf('conv'), txt('f')), EQ(argOf('conv'), txt('F'))), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL('must be real number')]),
      IF(EQ(VAR('phas'), num(0)), [setV('ppr', num(6))]),
      setV('pqq', num(1)),
      REPEAT(VAR('ppr'), [setV('pqq', MUL(VAR('pqq'), num(10)))]),
      setV('psg', txt('')),
      setV('pab', argOf('vv')),
      IF(LT(VAR('pab'), num(0)), [
        setV('psg', txt('-')),
        setV('pab', SUB(num(0), VAR('pab')))
      ]),
      setV('pmu', MUL(VAR('pab'), VAR('pqq'))),
      setV('pn2', FLOOR(ADD(VAR('pmu'), num('0.5')))),
      setV('pin', FLOOR(DIV(VAR('pn2'), VAR('pqq')))),
      setV('pfr', SUB(VAR('pn2'), MUL(VAR('pin'), VAR('pqq')))),
      IFELSE(EQ(VAR('ppr'), num(0)), [
        setV('ptx', JOIN(VAR('psg'), VAR('pin')))
      ], [
        setV('pfs', VAR('pfr')),
        REPEATU(NOT(LT(lenOf(VAR('pfs')), VAR('ppr'))), [setV('pfs', JOIN(txt('0'), VAR('pfs')))]),
        setV('ptx', JOIN(JOIN(JOIN(VAR('psg'), VAR('pin')), txt('.')), VAR('pfs')))
      ]),
      setV('pok', num(1))
    ]),
    // %s / %r
    IF(OR(EQ(argOf('conv'), txt('s')), EQ(argOf('conv'), txt('r'))), [
      callProc('strval %s %s', [argOf('vv'), argOf('vt')]),
      setV('ptx', VAR('ev')),
      setV('pok', num(1))
    ]),
    IF(EQ(VAR('pok'), num(0)), [
      callProc('strval %s %s', [argOf('vv'), argOf('vt')]),
      setV('ptx', VAR('ev'))
    ]),
    // width and - alignment
    IF(LT(lenOf(VAR('ptx')), VAR('pwid')), [
      setV('ppad', txt('')),
      REPEAT(SUB(VAR('pwid'), lenOf(VAR('ptx'))), [setV('ppad', JOIN(VAR('ppad'), txt(' ')))]),
      IFELSE(EQ(VAR('pleft'), num(1)), [
        setV('ptx', JOIN(VAR('ptx'), VAR('ppad')))
      ], [
        setV('ptx', JOIN(VAR('ppad'), VAR('ptx')))
      ])
    ]),
    setV('ev', VAR('ptx')),
    setV('evtype', txt('S'))
  ]);
  console.log('[P77] pctitem registered');

  // ---------- pctfmt: parse "%[-][width][.prec]conv" and hand off to pctitem
  const pf = inDef('pctfmt %s %s %s');
  const vn = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const loop = find(pf, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]] && BL()[b.inputs.CONDITION[1]].opcode === 'operator_gt'
    && vn(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1) === 'pvi');
  if (loop.length !== 1) throw new Error('[P77] pctfmt scan loop = ' + loop.length);
  setStack(loop[0], 'SUBSTACK', [
    setV('pvc', letterOf(VAR('pvi'), argOf('fmt'))),
    IFELSE(EQ(VAR('pvc'), txt('%')), [
      chgV('pvi', num(1)),
      setV('pvspec', txt('')),
      REPEATU(OR(GT(VAR('pvi'), lenOf(argOf('fmt'))), NOT(inSet(letterOf(VAR('pvi'), argOf('fmt')), '-+ 0123456789.'))), [
        setV('pvspec', JOIN(VAR('pvspec'), letterOf(VAR('pvi'), argOf('fmt')))),
        chgV('pvi', num(1))
      ]),
      setV('pvc', letterOf(VAR('pvi'), argOf('fmt'))),
      IFELSE(EQ(VAR('pvc'), txt('%')), [
        setV('pvout', JOIN(VAR('pvout'), txt('%')))
      ], [
        IF(GT(VAR('pvk'), llen('PVal')), [FAIL('TypeError: not enough arguments for format string')]),
        setV('pvv', item('PVal', VAR('pvk'))),
        setV('pvt', item('PTyp', VAR('pvk'))),
        chgV('pvk', num(1)),
        callProc('pctitem %s %s %s %s', [VAR('pvv'), VAR('pvt'), VAR('pvspec'), VAR('pvc')]),
        setV('pvout', JOIN(VAR('pvout'), VAR('ev')))
      ])
    ], [
      setV('pvout', JOIN(VAR('pvout'), VAR('pvc')))
    ]),
    chgV('pvi', num(1))
  ]);
  console.log('[P77] pctfmt parses width and precision');

  // ---------- fstr: split "expr:spec" and format through the same procedure
  const fs = inDef('fstr %s');
  const tokCall = find(fs, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'tokenize %s');
  const svCall = find(fs, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'strval %s %s');
  if (tokCall.length !== 1 || svCall.length !== 1) throw new Error('[P77] fstr hooks = ' + tokCall.length + '/' + svCall.length);
  insertBeforeStmt(tokCall[0], [
    setV('fz2', num(0)),
    setV('fz3', txt('')),
    setV('fz4', txt('s')),
    setV('fz1', num(0)),
    setV('fz5', num(0)),
    setV('fz6', num(1)),
    REPEATU(GT(VAR('fz6'), lenOf(VAR('fexpr'))), [
      IF(inSet(letterOf(VAR('fz6'), VAR('fexpr')), '([{'), [chgV('fz5', num(1))]),
      IF(inSet(letterOf(VAR('fz6'), VAR('fexpr')), ')]}'), [chgV('fz5', num(-1))]),
      IF(AND(EQ(VAR('fz5'), num(0)), EQ(letterOf(VAR('fz6'), VAR('fexpr')), txt(':'))), [
        IF(EQ(VAR('fz1'), num(0)), [setV('fz1', VAR('fz6'))])
      ]),
      chgV('fz6', num(1))
    ]),
    IF(GT(VAR('fz1'), num(0)), [
      setV('fz2', num(1)),
      callProc('substr %s %s %s', [VAR('fexpr'), ADD(VAR('fz1'), num(1)), lenOf(VAR('fexpr'))]),
      setV('fz3', VAR('ev')),
      callProc('substr %s %s %s', [VAR('fexpr'), num(1), SUB(VAR('fz1'), num(1))]),
      setV('fexpr', VAR('ev')),
      setV('fz4', letterOf(lenOf(VAR('fz3')), VAR('fz3'))),
      callProc('substr %s %s %s', [VAR('fz3'), num(1), SUB(lenOf(VAR('fz3')), num(1))]),
      setV('fz3', VAR('ev'))
    ])
  ]);
  const sink = cloneExpr(svCall[0]);
  replaceStmt(svCall[0], IFELSE(GT(VAR('fz2'), num(0)),
    [callProc('pctitem %s %s %s %s', [VAR('ev'), VAR('evtype'), VAR('fz3'), VAR('fz4')])],
    [sink]));
  console.log('[P77] f-string format spec installed');
});

// ---- P78: min/max over a single container, and int(x, base) (E22/E25) ----
//
// `min(a)` / `max(a)` only existed in the multi-argument form (minmax), so the one-argument
// call fell through callfn to "NameError: function min".  `int('101', 2)` was rejected by
// eval's two-argument whitelist (max/min/pow/round only) before it ever reached builtin2b.
patch('P78 minmax container and int base', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const isArgEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((argName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (argName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isTokLo = (x) => { const b = blk(x); return !!b && b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Tok'; };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['mmv', 'mmt', 'mmi']) if (taken.has(n)) throw new Error('[P78] variable name taken: ' + n);
  for (const v of ['mmv', 'mmt', 'mmi']) newVar(v, 0);

  // ---------- (a) callfn: min/max over one iterable argument
  const cf = inDef('callfn %s %s %s');
  const sortedIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && isArgEq(b.inputs.CONDITION, 'fn', 'sorted'));
  if (sortedIf.length !== 1) throw new Error('[P78] sorted branch = ' + sortedIf.length);
  const isIter = OR(EQ(VAR('evtype'), txt('L')), OR(EQ(VAR('evtype'), txt('T')), EQ(VAR('evtype'), txt('G'))));
  const minmaxOne = IF(OR(EQ(argOf('fn'), txt('min')), EQ(argOf('fn'), txt('max'))), [
    IF(NOT(isIter), [FAILB(JOIN(txt("TypeError: '"), JOIN(argOf('fn'), txt("' object is not iterable"))))]),
    setV('ltmp', VAR('ev')),
    callProc('listlen %s', [VAR('ltmp')]),
    setV('ln', VAR('ev')),
    IF(EQ(VAR('ln'), num(0)), [FAILB(JOIN(argOf('fn'), txt('() arg is an empty sequence')))]),
    callProc('listitem %s %s', [VAR('ltmp'), num(1)]),
    setV('mmv', VAR('ev')),
    setV('mmt', VAR('evtype')),
    setV('mmi', num(2)),
    REPEATU(GT(VAR('mmi'), VAR('ln')), [
      callProc('listitem %s %s', [VAR('ltmp'), VAR('mmi')]),
      IFELSE(AND(EQ(VAR('mmt'), txt('N')), EQ(VAR('evtype'), txt('N'))), [
        IFELSE(EQ(argOf('fn'), txt('max')), [
          IF(GT(VAR('ev'), VAR('mmv')), [setV('mmv', VAR('ev'))])
        ], [
          IF(LT(VAR('ev'), VAR('mmv')), [setV('mmv', VAR('ev'))])
        ])
      ], [
        IF(AND(EQ(VAR('mmt'), txt('S')), EQ(VAR('evtype'), txt('S'))), [
          callProc('compareText %s %s', [VAR('ev'), VAR('mmv')]),
          IFELSE(EQ(argOf('fn'), txt('max')), [
            IF(GT(VAR('cmp'), num(0)), [setV('mmv', VAR('ev'))])
          ], [
            IF(LT(VAR('cmp'), num(0)), [setV('mmv', VAR('ev'))])
          ])
        ])
      ]),
      chgV('mmi', num(1))
    ]),
    setV('ev', VAR('mmv')),
    setV('evtype', VAR('mmt')),
    setV('pending', num(1))
  ]);
  insertBeforeStmt(sortedIf[0], [minmaxOne]);
  console.log('[P78] min(iterable) / max(iterable) installed');

  // ---------- (b) eval: allow int(x, base) through the two-argument path
  const ev = inDef('eval %s %s');
  const roundEq = find(ev, (b) => b.opcode === 'operator_equals'
    && ((isTokLo(b.inputs.OPERAND1) && litOf(b.inputs.OPERAND2) === 'round') || (isTokLo(b.inputs.OPERAND2) && litOf(b.inputs.OPERAND1) === 'round')));
  if (roundEq.length !== 1) throw new Error('[P78] eval round test = ' + roundEq.length);
  const roundOr = BL()[roundEq[0]].parent;
  if (!roundOr || BL()[roundOr].opcode !== 'operator_or') throw new Error('[P78] eval round or not found');
  replaceExpr(roundOr, () => OR(roundOr, EQ(item('Tok', argOf('lo')), txt('int'))));
  console.log('[P78] eval routes int(x, base) to builtin2');

  // ---------- (c) builtin2b: parse the string in the requested base
  const bb = inDef('builtin2b %s %s %s %s %s');
  const pendIf = find(bb, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]] && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && varName(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1) === 'pending');
  if (pendIf.length !== 1) throw new Error('[P78] builtin2b pending guard = ' + pendIf.length);
  insertBeforeStmt(pendIf[0], [
    IF(EQ(argOf('fn'), txt('int')), [
      IF(NOT(EQ(argOf('a1t'), txt('S'))), [FAIL("TypeError: int() can't convert non-string with explicit base")]),
      IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL('TypeError: int() base must be an integer')]),
      callProc('basenum %s %s', [argOf('a1v'), VAR('ev')]),
      setV('evtype', txt('N')),
      setV('pending', num(1))
    ])
  ]);
  console.log('[P78] builtin2b handles int(x, base)');
});

// ---- P79: dictionaries are writable -- d[k] = v and del d[k] (E38/E39) ----
//
// The `D` encoding is a flat run of (lsep + type + escaped text) records holding
// key, value, key, value, ...  indexget already reads it; indexset/indexdel only knew
// how to splice a list.  Both procedures now get a `D` branch that goes in *before* the
// list path and stops the script, so the list code stays byte-identical.
//
//   d[k] = v   find the key (flat index 2j-1, so the value sits at 2j) and splice the
//              value record; when the key is absent append key + value at the end.
//   del d[k]   drop the key record and its value record in one substring splice.
patch('P79 dict write and delete', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const argN = (b, i) => { const ids = JSON.parse(b.mutation.argumentids); return b.inputs[ids[i]]; };
  const isAddArg = (d, name, lit) => {
    const b = blk(d);
    return !!b && b.opcode === 'operator_add' && argName(b.inputs.NUM1) === name && litOf(b.inputs.NUM2) === lit;
  };
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  // the guard "if not(xb == 'L'): fail" runs *before* the key eval, so the dict branch has
  // to be spliced in front of that guard, not in front of the eval.
  const notLGuard = (set) => find(set, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const nb = BL()[b.inputs.CONDITION[1]];
    if (!nb || nb.opcode !== 'operator_not') return false;
    const e = blk(nb.inputs.OPERAND);
    return !!e && e.opcode === 'operator_equals' && varName(e.inputs.OPERAND1) === 'xb' && litOf(e.inputs.OPERAND2) === 'L';
  });
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('dgf')) throw new Error('[P79] variable name taken: dgf');
  newVar('dgf', 0);
  // NB jf is a *thunk*: the flat index expression is needed twice, and reusing one block
  // id in two inputs is what broke P71 (one Scratch block has exactly one parent).
  const scanPos = (jf) => [
    setV('lcount', num(0)),
    setV('lstart', num(0)),
    setV('lend', num(0)),
    setV('lx', num(1)),
    REPEATU(GT(VAR('lx'), lenOf(VAR('xa'))), [
      IF(EQ(letterOf(VAR('lx'), VAR('xa')), VAR('lsep')), [
        chgV('lcount', num(1)),
        IF(EQ(VAR('lcount'), jf()), [setV('lstart', VAR('lx'))]),
        IF(EQ(VAR('lcount'), ADD(jf(), num(2))), [setV('lend', VAR('lx'))])
      ]),
      chgV('lx', num(1))
    ]),
    IF(EQ(VAR('lstart'), num(0)), [setV('lstart', num(1))])
  ];
  const itemSplice = () => [
    callProc('substr %s %s %s', [VAR('xa'), num(1), SUB(VAR('lstart'), num(1))]),
    setV('lnew', VAR('ev')),
    setV('lnew', JOIN(VAR('lnew'), JOIN(VAR('lsep'), JOIN(VAR('ltyp'), VAR('lval'))))),
    callProc('substr %s %s %s', [VAR('xa'), VAR('lend'), lenOf(VAR('xa'))]),
    setV('lnew', JOIN(VAR('lnew'), VAR('ev'))),
    callProc('assign %s %s %s', [item('Tok', argOf('lo')), VAR('lnew'), txt('D')]),
    setV('ev', VAR('lval')),
    setV('evtype', VAR('ltyp'))
  ];

  // ---------- (a) d[k] = v
  const ix = inDef('indexset %s %s');
  const keyGuard = notLGuard(ix);
  if (keyGuard.length !== 1) throw new Error('[P79] indexset dict guard = ' + keyGuard.length);
  const writeBranch = IF(EQ(VAR('xb'), txt('D')), [
    callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('lsp'), num(1))]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    setV('dgkey', VAR('ev')),
    setV('dgkt', VAR('evtype')),
    callProc('lesc %s', [VAR('dgkey')]),
    setV('dgesc', VAR('ev')),
    callProc('eval %s %s', [ADD(VAR('lsp'), num(2)), argOf('hi')]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    setV('lval', VAR('ev')),
    setV('ltyp', VAR('evtype')),
    callProc('lesc %s', [VAR('lval')]),
    setV('lval', VAR('ev')),
    callProc('listlen %s', [VAR('xa')]),
    setV('dgn', VAR('ev')),
    setV('dgi', num(1)),
    setV('dgf', num(0)),
    REPEATU(OR(GT(VAR('dgi'), VAR('dgn')), GT(VAR('dgf'), num(0))), [
      callProc('listitem %s %s', [VAR('xa'), VAR('dgi')]),
      IF(EQ(VAR('evtype'), VAR('dgkt')), [
        callProc('compareText %s %s', [VAR('ev'), VAR('dgkey')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('dgf', VAR('dgi'))])
      ]),
      chgV('dgi', num(2))
    ]),
    IFELSE(GT(VAR('dgf'), num(0)), [
      ...scanPos(() => ADD(VAR('dgf'), num(1))),
      IF(EQ(VAR('lend'), num(0)), [setV('lend', ADD(lenOf(VAR('xa')), num(1)))]),
      ...itemSplice()
    ], [
      callProc('assign %s %s %s', [item('Tok', argOf('lo')),
        JOIN(JOIN(VAR('xa'), JOIN(VAR('lsep'), JOIN(VAR('dgkt'), VAR('dgesc')))),
             JOIN(VAR('lsep'), JOIN(VAR('ltyp'), VAR('lval')))), txt('D')]),
      setV('ev', VAR('lval')),
      setV('evtype', VAR('ltyp'))
    ]),
    STOPTHIS()
  ]);
  insertBeforeStmt(keyGuard[0], [writeBranch]);
  console.log('[P79] d[k] = v installed');

  // ---------- (b) del d[k]
  const idl = inDef('indexdel %s %s');
  const delGuard = notLGuard(idl);
  if (delGuard.length !== 1) throw new Error('[P79] indexdel dict guard = ' + delGuard.length);
  const delBranch = IF(EQ(VAR('xb'), txt('D')), [
    callProc('eval %s %s', [ADD(argOf('lo'), num(3)), SUB(VAR('lsp'), num(1))]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    setV('dgkey', VAR('ev')),
    setV('dgkt', VAR('evtype')),
    callProc('listlen %s', [VAR('xa')]),
    setV('dgn', VAR('ev')),
    setV('dgi', num(1)),
    setV('dgf', num(0)),
    REPEATU(OR(GT(VAR('dgi'), VAR('dgn')), GT(VAR('dgf'), num(0))), [
      callProc('listitem %s %s', [VAR('xa'), VAR('dgi')]),
      IF(EQ(VAR('evtype'), VAR('dgkt')), [
        callProc('compareText %s %s', [VAR('ev'), VAR('dgkey')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('dgf', VAR('dgi'))])
      ]),
      chgV('dgi', num(2))
    ]),
    IF(EQ(VAR('dgf'), num(0)), [FAILB(JOIN(txt('KeyError: '), VAR('dgkey')))]),
    IF(EQ(VAR('error'), txt('')), [
      setV('lcount', num(0)),
      setV('lstart', num(0)),
      setV('lend', num(0)),
      setV('lx', num(1)),
      REPEATU(GT(VAR('lx'), lenOf(VAR('xa'))), [
        IF(EQ(letterOf(VAR('lx'), VAR('xa')), VAR('lsep')), [
          chgV('lcount', num(1)),
          IF(EQ(VAR('lcount'), VAR('dgf')), [setV('lstart', VAR('lx'))]),
          IF(EQ(VAR('lcount'), ADD(VAR('dgf'), num(2))), [setV('lend', VAR('lx'))])
        ]),
        chgV('lx', num(1))
      ]),
      IF(EQ(VAR('lstart'), num(0)), [setV('lstart', num(1))]),
      IF(EQ(VAR('lend'), num(0)), [setV('lend', ADD(lenOf(VAR('xa')), num(1)))]),
      callProc('substr %s %s %s', [VAR('xa'), num(1), SUB(VAR('lstart'), num(1))]),
      setV('lnew', VAR('ev')),
      callProc('substr %s %s %s', [VAR('xa'), VAR('lend'), lenOf(VAR('xa'))]),
      setV('lnew', JOIN(VAR('lnew'), VAR('ev'))),
      callProc('assign %s %s %s', [item('Tok', ADD(argOf('lo'), num(1))), VAR('lnew'), txt('D')]),
      setV('ev', txt('')),
      setV('evtype', txt('Z'))
    ]),
    STOPTHIS()
  ]);
  insertBeforeStmt(delGuard[0], [delBranch]);
  console.log('[P79] del d[k] installed');
});

// ---- P80: len(d), `k in d` and `for k in d` (E40/E41) ----
//
// A dict is stored as key, value, key, value, ... so all three just need the *keys*.
// `dictkeys` rebuilds a list encoding holding only the key records, and the three call
// sites then reuse the existing list machinery unchanged (len = listlen/2).
patch('P80 dict len in for', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const isArgEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((argName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (argName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isVarEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((varName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (varName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('dgacc')) throw new Error('[P80] variable name taken: dgacc');
  newVar('dgacc', '');

  // ---------- (a) dictkeys: the key records of a dict, re-escaped, as an L encoding
  const dk = newProc('dictkeys %s', ['s']);
  attachBody(dk.defId, [
    setV('dgacc', txt('')),
    callProc('listlen %s', [argOf('s')]),
    setV('dgn', VAR('ev')),
    setV('dgi', num(1)),
    REPEATU(GT(VAR('dgi'), VAR('dgn')), [
      callProc('listitem %s %s', [argOf('s'), VAR('dgi')]),
      setV('dgkt', VAR('evtype')),
      callProc('lesc %s', [VAR('ev')]),
      setV('dgacc', JOIN(VAR('dgacc'), JOIN(VAR('lsep'), JOIN(VAR('dgkt'), VAR('ev'))))),
      chgV('dgi', num(2))
    ]),
    setV('ev', VAR('dgacc')),
    setV('evtype', txt('L'))
  ]);
  console.log('[P80] dictkeys registered');

  // ---------- (b) len(d)
  const cf = inDef('callfn %s %s %s');
  const lenFail = find(cf, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const nb = BL()[b.inputs.CONDITION[1]];
    return !!nb && nb.opcode === 'operator_not' && isVarEq(nb.inputs.OPERAND, 'evtype', 'S');
  });
  if (lenFail.length !== 1) throw new Error('[P80] len guard = ' + lenFail.length);
  const notS = BL()[lenFail[0]].inputs.CONDITION[1];
  replaceExpr(notS, () => NOT(OR(EQ(VAR('evtype'), txt('D')), EQ(VAR('evtype'), txt('S')))));
  const lenSet = find(cf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'operator_length');
  if (lenSet.length !== 1) throw new Error('[P80] len value set = ' + lenSet.length);
  replaceStmt(lenSet[0], IFELSE(EQ(VAR('evtype'), txt('D')), [
    callProc('listlen %s', [VAR('ev')]),
    setV('ev', FLOOR(DIV(VAR('ev'), num(2))))
  ], [
    setV('ev', lenOf(VAR('ev')))
  ]));
  console.log('[P80] len(dict) installed');

  // ---------- (c) k in d
  // Anchor on the else-branch failure text: the `if (evtype == "L")` of the `in` operator
  // is the only block whose ELSE raises "in requires strings".
  const litSearch = (d, s) => {
    const seen = new Set(); const stack = [d];
    while (stack.length) {
      const cur = stack.pop();
      if (cur === null || cur === undefined) continue;
      if (typeof cur === 'string') {
        if (seen.has(cur)) continue; seen.add(cur);
        const b = BL()[cur]; if (!b) continue;
        for (const v of Object.values(b.inputs || {})) stack.push(v);
        continue;
      }
      if (Array.isArray(cur)) {
        if (cur[0] === 10 && cur[1] === s) return true;
        for (const e of cur) stack.push(e);
      }
    }
    return false;
  };
  const rs = inDef('rightside %s %s %s %s %s');
  const failIn = find(rs, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
    const slot = JSON.parse(b.mutation.argumentids)[0];
    return litSearch(b.inputs[slot], 'TypeError: in requires strings');
  });
  if (failIn.length !== 1) throw new Error('[P80] in-failure call = ' + failIn.length);
  const inL = find(rs, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else')
    && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string' && reach(b.inputs.SUBSTACK2[1]).has(failIn[0]));
  if (!inL.length) throw new Error('[P80] rightside in-branch = 0');
  // the outer `if ((lt2 == "S") and (evtype == "S"))` also wraps that failure, so take the
  // innermost candidate: its else-branch is just the fail call
  inL.sort((a, b) => reach(BL()[a].inputs.SUBSTACK2[1]).size - reach(BL()[b].inputs.SUBSTACK2[1]).size);
  insertBeforeStmt(inL[0], [
    IF(EQ(VAR('evtype'), txt('D')), [callProc('dictkeys %s', [VAR('ev')])])
  ]);
  console.log('[P80] `in` works on dicts');

  // ---------- (d) for k in d
  const fl = inDef('forloop');
  const forLT = find(fl, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else') && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && (() => {
    const o = BL()[b.inputs.CONDITION[1]];
    if (!o || o.opcode !== 'operator_or') return false;
    return (isVarEq(o.inputs.OPERAND1, 'evtype', 'L') && isVarEq(o.inputs.OPERAND2, 'evtype', 'T'))
      || (isVarEq(o.inputs.OPERAND1, 'evtype', 'T') && isVarEq(o.inputs.OPERAND2, 'evtype', 'L'));
  })());
  if (forLT.length !== 1) throw new Error('[P80] forloop L/T branch = ' + forLT.length);
  insertBeforeStmt(forLT[0], [
    IF(EQ(VAR('evtype'), txt('D')), [callProc('dictkeys %s', [VAR('ev')])])
  ]);
  console.log('[P80] for k in d installed');
});

// ---- P81: slice with a step -- s[::2] / s[::-1] (E7/E8) ----
//
// indexget found the first top-level ':' and treated everything after it as the stop, so
// a second colon (the step) landed in the stop expression.  A third scan cursor (xcol2)
// now records it, and when it is present the whole slice is built by stepping instead of
// by substring.  The no-step path is untouched.
//
// Python defaults handled here: with step > 0 start/stop default to 0/n; with step < 0
// they default to n-1/"before the beginning"; explicit negatives get +n and are clamped.
patch('P81 slice step', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const isVarEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((varName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (varName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['xcol2', 'sgst', 'sglo', 'sghi', 'sghas', 'sghbs', 'sgacc', 'sgi', 'sgkt']) {
    if (taken.has(n)) throw new Error('[P81] variable name taken: ' + n);
  }
  for (const v of ['xcol2', 'sgst', 'sglo', 'sghi', 'sghas', 'sghbs', 'sgacc', 'sgi', 'sgkt']) newVar(v, 0);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  // NB a thunk: every use needs its own argument reporter (sharing one block breaks it)
  const hi = () => argOf('hi');
  const ig = inDef('indexget %s %s');

  // (a) start xcol2 alongside xcol
  const xcolInit = find(ig, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'xcol' && litOf(b.inputs.VALUE) === '0');
  if (xcolInit.length !== 1) throw new Error('[P81] xcol init = ' + xcolInit.length);
  spliceAfter(xcolInit[0], chain([setV('xcol2', num(0))]));

  // (b) the colon scan records the second colon too: turn the inner `if (xcol == 0)` into
  // an if/else whose else notes the *next* colon.  Both tests run in the same iteration,
  // so it has to be an else -- a separate statement would record the first colon twice.
  const colonIf = find(ig, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else') && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string' && (() => {
    const a = BL()[b.inputs.CONDITION[1]];
    if (!a || a.opcode !== 'operator_and') return false;
    return (isVarEq(a.inputs.OPERAND1, 'ed', '0') && isVarEq(a.inputs.OPERAND2, 'eop', ':'))
      || (isVarEq(a.inputs.OPERAND2, 'ed', '0') && isVarEq(a.inputs.OPERAND1, 'eop', ':'));
  })());
  if (colonIf.length !== 1) throw new Error('[P81] colon test = ' + colonIf.length);
  const innerList = find(reach(BL()[colonIf[0]].inputs.SUBSTACK[1]), (b, id) => (b.opcode === 'control_if' || b.opcode === 'control_if_else')
    && b.inputs.CONDITION && isVarEq(b.inputs.CONDITION, 'xcol', '0') && BL()[id].parent === colonIf[0]);
  if (innerList.length !== 1) throw new Error('[P81] xcol==0 test = ' + innerList.length);
  const innerIf = innerList[0];
  const newIf = I('control_if_else', { inputs: { CONDITION: BL()[innerIf].inputs.CONDITION } });
  B.sub(IT, newIf, 'SUBSTACK', BL()[innerIf].inputs.SUBSTACK[1]);
  B.sub(IT, newIf, 'SUBSTACK2', chain([IF(EQ(VAR('xcol2'), num(0)), [setV('xcol2', VAR('xi'))])]));
  replaceStmt(innerIf, newIf);
  console.log('[P81] second colon recorded');

  // (c) build the stepped slice in the else-branch of "if xcol == 0"
  // two "xcol == 0" tests exist (the second one is inside the scan, for dict keys); the
  // slice branch is the one whose else starts with `xlo = 0`
  const xcolIf = find(ig, (b) => b.opcode === 'control_if_else'
    && b.inputs.CONDITION && isVarEq(b.inputs.CONDITION, 'xcol', '0')
    && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string'
    && BL()[b.inputs.SUBSTACK2[1]] && BL()[b.inputs.SUBSTACK2[1]].opcode === 'data_setvariableto'
    && BL()[b.inputs.SUBSTACK2[1]].fields.VARIABLE && BL()[b.inputs.SUBSTACK2[1]].fields.VARIABLE[0] === 'xlo');
  if (xcolIf.length !== 1) throw new Error('[P81] xcol branch = ' + xcolIf.length);
  const sub2 = BL()[xcolIf[0]].inputs.SUBSTACK2;
  if (!sub2 || typeof sub2[1] !== 'string') throw new Error('[P81] slice branch missing');
  const num2 = num(-1);
  const emit = IFELSE(EQ(VAR('xb'), txt('S')), [
    setV('sgacc', JOIN(VAR('sgacc'), letterOf(ADD(VAR('sgi'), num(1)), VAR('xa'))))
  ], [
    callProc('listitem %s %s', [VAR('xa'), ADD(VAR('sgi'), num(1))]),
    setV('sgkt', VAR('evtype')),
    callProc('lesc %s', [VAR('ev')]),
    setV('sgacc', JOIN(VAR('sgacc'), JOIN(VAR('lsep'), JOIN(VAR('sgkt'), VAR('ev')))))
  ]);
  const stepBranch = IF(GT(VAR('xcol2'), num(0)), [
    setV('sgst', num(1)),
    IF(LT(VAR('xcol2'), SUB(hi(), num(1))), [
      callProc('eval %s %s', [ADD(VAR('xcol2'), num(1)), SUB(hi(), num(1))]),
      IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
      IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL('TypeError: slice step must be an integer')]),
      setV('sgst', VAR('ev'))
    ]),
    IF(EQ(VAR('sgst'), num(0)), [FAIL('ValueError: slice step cannot be zero')]),
    // start
    setV('sglo', num(0)),
    setV('sghas', num(0)),
    IF(GT(VAR('xcol'), ADD(VAR('xbr'), num(1))), [
      callProc('eval %s %s', [ADD(VAR('xbr'), num(1)), SUB(VAR('xcol'), num(1))]),
      IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
      IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL('TypeError: slice indices must be integers')]),
      setV('sglo', VAR('ev')),
      setV('sghas', num(1))
    ]),
    // stop
    setV('sghi', num(0)),
    setV('sghbs', num(0)),
    IF(GT(VAR('xcol2'), ADD(VAR('xcol'), num(1))), [
      callProc('eval %s %s', [ADD(VAR('xcol'), num(1)), SUB(VAR('xcol2'), num(1))]),
      IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
      IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL('TypeError: slice indices must be integers')]),
      setV('sghi', VAR('ev')),
      setV('sghbs', num(1))
    ]),
    // defaults and clamping
    IFELSE(GT(VAR('sgst'), num(0)), [
      IF(EQ(VAR('sghas'), num(0)), [setV('sglo', num(0))]),
      IF(LT(VAR('sglo'), num(0)), [chgV('sglo', VAR('xlen'))]),
      IF(LT(VAR('sglo'), num(0)), [setV('sglo', num(0))]),
      IF(GT(VAR('sglo'), VAR('xlen')), [setV('sglo', VAR('xlen'))]),
      IF(EQ(VAR('sghbs'), num(0)), [setV('sghi', VAR('xlen'))]),
      IF(LT(VAR('sghi'), num(0)), [chgV('sghi', VAR('xlen'))]),
      IF(LT(VAR('sghi'), num(0)), [setV('sghi', num(0))]),
      IF(GT(VAR('sghi'), VAR('xlen')), [setV('sghi', VAR('xlen'))])
    ], [
      IFELSE(EQ(VAR('sghas'), num(0)), [setV('sglo', SUB(VAR('xlen'), num(1)))], [
        IF(LT(VAR('sglo'), num(0)), [chgV('sglo', VAR('xlen'))]),
        IF(GT(VAR('sglo'), SUB(VAR('xlen'), num(1))), [setV('sglo', SUB(VAR('xlen'), num(1)))])
      ]),
      IFELSE(EQ(VAR('sghbs'), num(0)), [setV('sghi', num2)], [
        IF(LT(VAR('sghi'), num(0)), [chgV('sghi', VAR('xlen'))])
      ])
    ]),
    // collect
    setV('sgacc', txt('')),
    setV('sgi', VAR('sglo')),
    IFELSE(GT(VAR('sgst'), num(0)), [
      REPEATU(NOT(LT(VAR('sgi'), VAR('sghi'))), [emit, chgV('sgi', VAR('sgst'))])
    ], [
      REPEATU(NOT(GT(VAR('sgi'), VAR('sghi'))), [emit, chgV('sgi', VAR('sgst'))])
    ]),
    setV('ev', VAR('sgacc')),
    IFELSE(EQ(VAR('xb'), txt('S')), [setV('evtype', txt('S'))], [setV('evtype', txt('L'))]),
    STOPTHIS()
  ]);
  insertBeforeStmt(sub2[1], [stepBranch]);
  console.log('[P81] s[::step] installed');
});

// ---- P82: str.format -- "{} {}".format(1, 2) (E16) ----
//
// The S section of methodcall only ever evaluates up to two arguments, so `format` gets
// its own argument scan: every top-level comma between `(` and `)` is evaluated into the
// FmtV/FmtT lists, then `strfmt` walks the receiver and substitutes `{}` (auto index),
// `{2}` (explicit index), `{{` and `}}`.
patch('P82 str.format', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const inSet = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['sfcut', 'sfdep', 'sfk', 'sfq', 'sfacc', 'sfi', 'sfa', 'sfhas', 'sfnum', 'sfn', 'sft', 'sfv']) {
    if (taken.has(n)) throw new Error('[P82] variable name taken: ' + n);
  }
  for (const l of ['FmtV', 'FmtT']) {
    if (Object.values(T(IT).lists).some((x) => x[0] === l)) throw new Error('[P82] list name taken: ' + l);
  }
  for (const v of ['sfcut', 'sfdep', 'sfk', 'sfq', 'sfacc', 'sfi', 'sfa', 'sfhas', 'sfnum', 'sfn', 'sft', 'sfv']) newVar(v, 0);
  B.addList(IT, 'FmtV', []);
  B.addList(IT, 'FmtT', []);

  // ---------- (a) strfmt: substitute into the receiver
  const sf = newProc('strfmt %s', ['s']);
  const chSF = (i) => letterOf(i, argOf('s'));
  attachBody(sf.defId, [
    setV('sfacc', txt('')),
    setV('sfi', num(1)),
    setV('sfa', num(0)),
    REPEATU(GT(VAR('sfi'), lenOf(argOf('s'))), [
      setV('sfq', chSF(VAR('sfi'))),
      IFELSE(EQ(VAR('sfq'), txt('{')), [
        IFELSE(EQ(chSF(ADD(VAR('sfi'), num(1))), txt('{')), [
          setV('sfacc', JOIN(VAR('sfacc'), txt('{'))),
          chgV('sfi', num(1))
        ], [
          setV('sfnum', num(0)),
          setV('sfhas', num(0)),
          setV('sfk', ADD(VAR('sfi'), num(1))),
          REPEATU(OR(GT(VAR('sfk'), lenOf(argOf('s'))), EQ(chSF(VAR('sfk')), txt('}'))), [
            IF(inSet(chSF(VAR('sfk')), '0123456789'), [
              setV('sfnum', ADD(MUL(VAR('sfnum'), num(10)), chSF(VAR('sfk')))),
              setV('sfhas', num(1))
            ]),
            chgV('sfk', num(1))
          ]),
          IF(EQ(VAR('sfhas'), num(0)), [setV('sfnum', VAR('sfa'))]),
          setV('sfa', ADD(VAR('sfnum'), num(1))),
          IF(LT(VAR('sfnum'), llen('FmtV')), [
            setV('sfn', item('FmtV', ADD(VAR('sfnum'), num(1)))),
            setV('sft', item('FmtT', ADD(VAR('sfnum'), num(1)))),
            callProc('strval %s %s', [VAR('sfn'), VAR('sft')]),
            setV('sfacc', JOIN(VAR('sfacc'), VAR('ev')))
          ]),
          setV('sfi', VAR('sfk'))
        ])
      ], [
        IFELSE(EQ(VAR('sfq'), txt('}')), [
          IF(EQ(chSF(ADD(VAR('sfi'), num(1))), txt('}')), [
            setV('sfacc', JOIN(VAR('sfacc'), txt('}'))),
            chgV('sfi', num(1))
          ])
        ], [
          setV('sfacc', JOIN(VAR('sfacc'), VAR('sfq')))
        ])
      ]),
      chgV('sfi', num(1))
    ]),
    setV('ev', VAR('sfacc')),
    setV('evtype', txt('S'))
  ]);
  console.log('[P82] strfmt registered');

  // ---------- (b) hook format into methodcall *before* the S section: that section
  // pre-evaluates the first two arguments and chokes on "1, 2, 3".  Anchored on the
  // instance dispatch (`if (xb == "O")`), which sits right after `lmeth` is set.
  const mc = inDef('methodcall %s %s');
  const argScan = [
    clearL('FmtV'),
    clearL('FmtT'),
    setV('sfcut', ADD(argOf('lo'), num(3))),
    setV('sfdep', num(0)),
    setV('sfk', ADD(argOf('lo'), num(4))),
    REPEATU(GT(VAR('sfk'), SUB(argOf('hi'), num(1))), [
      setV('sfq', item('Tok', VAR('sfk'))),
      IF(OR(EQ(VAR('sfq'), txt('(')), EQ(VAR('sfq'), txt('['))), [chgV('sfdep', num(1))]),
      IF(OR(EQ(VAR('sfq'), txt(')')), EQ(VAR('sfq'), txt(']'))), [chgV('sfdep', num(-1))]),
      IF(AND(EQ(VAR('sfdep'), num(0)), EQ(VAR('sfq'), txt(','))), [
        callProc('eval %s %s', [ADD(VAR('sfcut'), num(1)), SUB(VAR('sfk'), num(1))]),
        IF(EQ(VAR('error'), txt('')), [addTo('FmtV', VAR('ev')), addTo('FmtT', VAR('evtype'))]),
        setV('sfcut', VAR('sfk'))
      ]),
      chgV('sfk', num(1))
    ]),
    IF(LT(VAR('sfcut'), SUB(argOf('hi'), num(1))), [
      callProc('eval %s %s', [ADD(VAR('sfcut'), num(1)), SUB(argOf('hi'), num(1))]),
      IF(EQ(VAR('error'), txt('')), [addTo('FmtV', VAR('ev')), addTo('FmtT', VAR('evtype'))])
    ]),
    IF(EQ(VAR('error'), txt('')), [callProc('strfmt %s', [VAR('xa')])]),
    I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } })
  ];
  const objIf = find(mc, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else')
    && b.inputs.CONDITION && (() => { const e = blk(b.inputs.CONDITION); return !!e && e.opcode === 'operator_equals' && varName(e.inputs.OPERAND1) === 'xb' && litOf(e.inputs.OPERAND2) === 'O'; })());
  if (objIf.length !== 1) throw new Error('[P82] methodcall instance dispatch = ' + objIf.length);
  const fmtIf = IF(AND(EQ(VAR('xb'), txt('S')), EQ(VAR('lmeth'), txt('format'))), argScan);
  insertBeforeStmt(objIf[0], [fmtIf]);
  console.log('[P82] methodcall routes format');
});

// ---- P83: a bare comma sequence is a tuple -- x = 1, 2 and `return 1, 2` (E36/E37) ----
//
// eval only built a tuple when the range was fully parenthesised; everything else with a
// top-level comma fell through to "SyntaxError: expression".  Right before that last
// failure, ask hascomma (the same helper the parenthesised path uses) and build a tuple.
patch('P83 bare tuple', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const ev = inDef('eval %s %s');
  const fails = find(ev, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
    const slot = JSON.parse(b.mutation.argumentids)[0];
    const d = b.inputs[slot];
    if (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 10 && d[1][1] === 'SyntaxError: expression') return true;
    return false;
  });
  if (fails.length !== 1) throw new Error('[P83] eval expression failure = ' + fails.length);
  insertBeforeStmt(fails[0], [
    callProc('hascomma %s %s', [argOf('lo'), argOf('hi')]),
    IF(EQ(VAR('tqhcm'), num(1)), [
      callProc('tuplelit %s %s', [argOf('lo'), argOf('hi')]),
      STOPTHIS()
    ])
  ]);
  console.log('[P83] bare comma sequence becomes a tuple');
});

// ---- P84: unpacking from a container value -- a, b = (1, 2) / q, r = divmod(9, 4) (E33/E34) ----
//
// assignlist required as many comma separated pieces on the right as there are names, so a
// single container value ("(1, 2)", a function's tuple) always raised "unpack count
// mismatch".  When the counts disagree, evaluate the whole right-hand side once; if it is a
// list/tuple of exactly the right length, bind element by element and do the assignment
// here (the normal path never runs).
patch('P84 unpack from container', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['auenc', 'aun', 'auj', 'aum', 'aut']) if (taken.has(n)) throw new Error('[P84] variable name taken: ' + n);
  for (const v of ['auenc', 'aun', 'auj', 'aum', 'aut']) newVar(v, 0);
  const al = inDef('assignlist %s');
  const fails = find(al, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
    const slot = JSON.parse(b.mutation.argumentids)[0];
    const d = b.inputs[slot];
    return Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 10 && d[1][1] === 'ValueError: unpack count mismatch';
  });
  if (fails.length !== 1) throw new Error('[P84] unpack mismatch failure = ' + fails.length);
  insertBeforeStmt(fails[0], [
    callProc('eval %s %s', [ADD(argOf('eqi'), num(1)), VAR('count')]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    IF(NOT(OR(EQ(VAR('evtype'), txt('L')), OR(EQ(VAR('evtype'), txt('T')), EQ(VAR('evtype'), txt('S'))))), [FAIL('TypeError: cannot unpack non-iterable object')]),
    setV('auenc', VAR('ev')),
    setV('aut', VAR('evtype')),
    IFELSE(EQ(VAR('aut'), txt('S')),
      [setV('aun', lenOf(VAR('auenc')))],
      [callProc('listlen %s', [VAR('auenc')]), setV('aun', VAR('ev'))]),
    IF(NOT(EQ(VAR('aun'), llen('AName'))), [
      IFELSE(LT(VAR('aun'), llen('AName')),
        [FAIL('ValueError: not enough values to unpack')],
        [FAIL('ValueError: too many values to unpack')])
    ]),
    clearL('AVal'),
    clearL('AType'),
    setV('auj', num(1)),
    REPEATU(GT(VAR('auj'), VAR('aun')), [
      IFELSE(EQ(VAR('aut'), txt('S')),
        [setV('ev', letterOf(VAR('auj'), VAR('auenc'))), setV('evtype', txt('S'))],
        [callProc('listitem %s %s', [VAR('auenc'), VAR('auj')])]),
      addTo('AVal', VAR('ev')),
      addTo('AType', VAR('evtype')),
      chgV('auj', num(1))
    ]),
    setV('aum', num(1)),
    REPEATU(GT(VAR('aum'), llen('AName')), [
      callProc('aldrop %s', [item('AName', VAR('aum'))]),
      callProc('assign %s %s %s', [item('AName', VAR('aum')), item('AVal', VAR('aum')), item('AType', VAR('aum'))]),
      chgV('aum', num(1))
    ]),
    STOPTHIS()
  ]);
  console.log('[P84] container unpacking installed');
});

// ---- P85: functions as values -- g = f and (lambda x: x * 2)(4) (E30/E31) ----
//
// A `def` name only lives in the FnName list, so `g = f` made atom raise NameError, and a
// parenthesised callee was never called at all (eval only handled `name(`).
//
// Function values already exist: ev = the FnName index, evtype = "F" (that is what strval
// prints and what calluser reads back out of a variable).  So:
//   * atom: when a name is neither a variable nor a keyword, look it up in FnName and hand
//     back the index as an F value;
//   * eval: for `( ... ) ( args )`, find the matching close paren, evaluate the callee, and
//     call it through callfn with the FnName text.
patch('P85 function values', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fnf', 'fni', 'cpd', 'cpe', 'cpi', 'cpf']) if (taken.has(n)) throw new Error('[P85] variable name taken: ' + n);
  for (const v of ['fnf', 'fni', 'cpd', 'cpe', 'cpi', 'cpf']) newVar(v, 0);

  // ---------- (a) atom: a bare function name becomes an F value
  const at = inDef('atom %s');
  const nameFail = find(at, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
    // "NameError: " + V(ev)
    const slot = JSON.parse(b.mutation.argumentids)[0];
    const d = b.inputs[slot];
    const b2 = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    if (!b2 || b2.opcode !== 'operator_join') return false;
    return litOf(b2.inputs.STRING1) === 'NameError: ' && varName(b2.inputs.STRING2) === 'ev';
  });
  if (nameFail.length !== 1) throw new Error('[P85] atom NameError = ' + nameFail.length);
  insertBeforeStmt(nameFail[0], [
    setV('fnf', num(0)),
    setV('fni', num(1)),
    REPEATU(GT(VAR('fni'), llen('FnName')), [
      IF(EQ(item('FnName', VAR('fni')), VAR('ev')), [setV('fnf', VAR('fni'))]),
      chgV('fni', num(1))
    ]),
    IF(GT(VAR('fnf'), num(0)), [
      setV('ev', VAR('fnf')),
      setV('evtype', txt('F')),
      STOPTHIS()
    ])
  ]);
  console.log('[P85] a def name evaluates to a function value');

  // ---------- (b) eval: call a parenthesised callee
  const ev = inDef('eval %s %s');
  const isTokAt = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((argName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (argName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isTokItem = (d, name) => {
    const b = blk(d);
    if (!b || b.opcode !== 'data_itemoflist') return false;
    if (!b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
    return argName(b.inputs.INDEX) === name;
  };
  const tokEq = (d, name, lit) => {
    const b = blk(d);
    if (!b || b.opcode !== 'operator_equals') return false;
    return (isTokItem(b.inputs.OPERAND1, name) && litOf(b.inputs.OPERAND2) === lit)
      || (isTokItem(b.inputs.OPERAND2, name) && litOf(b.inputs.OPERAND1) === lit);
  };
  const parenIf = find(ev, (b) => {
    if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') return false;
    const c = b.inputs.CONDITION && b.inputs.CONDITION[1];
    if (typeof c !== 'string') return false;
    const a = BL()[c];
    if (!a || a.opcode !== 'operator_and') return false;
    return (tokEq(a.inputs.OPERAND1, 'lo', '(') && tokEq(a.inputs.OPERAND2, 'hi', ')'))
      || (tokEq(a.inputs.OPERAND2, 'lo', '(') && tokEq(a.inputs.OPERAND1, 'hi', ')'));
  });
  if (parenIf.length !== 1) throw new Error('[P85] eval paren branch = ' + parenIf.length);
  const callBlock = [
    setV('cpd', num(0)),
    setV('cpe', num(0)),
    setV('cpi', argOf('lo')),
    REPEATU(OR(GT(VAR('cpi'), argOf('hi')), GT(VAR('cpe'), num(0))), [
      IF(EQ(item('Tok', VAR('cpi')), txt('(')), [chgV('cpd', num(1))]),
      IF(EQ(item('Tok', VAR('cpi')), txt(')')), [
        chgV('cpd', num(-1)),
        IF(EQ(VAR('cpd'), num(0)), [setV('cpe', VAR('cpi'))])
      ]),
      chgV('cpi', num(1))
    ]),
    IF(AND(GT(VAR('cpe'), num(0)),
      AND(LT(ADD(VAR('cpe'), num(1)), argOf('hi')),
        AND(EQ(item('Tok', ADD(VAR('cpe'), num(1))), txt('(')), EQ(item('Tok', argOf('hi')), txt(')'))))), [
      setV('cpf', VAR('cpe')),
      callProc('eval %s %s', [argOf('lo'), VAR('cpe')]),
      IF(NOT(EQ(VAR('error'), txt(''))), [chgV('fnlimit', num(-1)), STOPTHIS()]),
      IFELSE(EQ(VAR('evtype'), txt('F')), [
        callProc('callfn %s %s %s', [item('FnName', VAR('ev')), ADD(VAR('cpf'), num(2)), SUB(argOf('hi'), num(1))]),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ], [
        FAIL('TypeError: object is not callable'),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ])
  ];
  insertBeforeStmt(parenIf[0], [IF(EQ(item('Tok', argOf('lo')), txt('(')), callBlock)]);
  console.log('[P85] (expr)(args) calls the value');
});

// ---- P86: nested user call as an argument -- f(h()) ----
//
// calluser resolves the callee into the global `fi`, THEN pushes a frame, THEN evaluates the
// arguments.  A user call inside the arguments overwrites `fi` (its own resolution) and its
// fpop restores *its* value, so the outer call then reads FnPar/FnStart/FnLine of the wrong
// function: `f(h())` said "TypeError: too many arguments" and nested lambdas ran the inner
// body (pre-existing in v4.35; found while testing E31).
//
// Fix: keep `fi` on the VStack (the list the interpreter already uses for nested temporaries)
// across the argument evaluation and put it back before fpn/fpo are read.
patch('P86 callee survives argument calls', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const cu = inDef('calluser %s %s %s');
  const argStart = find(cu, (b) => {
    if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') return false;
    const c = b.inputs.CONDITION && b.inputs.CONDITION[1];
    if (typeof c !== 'string') return false;
    const n = BL()[c];
    if (!n || n.opcode !== 'operator_not') return false;
    const g = blk(n.inputs.OPERAND);
    return !!g && g.opcode === 'operator_gt'
      && argName(g.inputs.OPERAND1) === 'lo' && argName(g.inputs.OPERAND2) === 'hi';
  });
  if (argStart.length !== 1) throw new Error('[P86] calluser argument block = ' + argStart.length);
  insertBeforeStmt(argStart[0], [addTo('VStack', VAR('fi'))]);
  const fpnSet = find(cu, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'fpn'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'data_itemoflist');
  if (fpnSet.length !== 1) throw new Error('[P86] calluser fpn read = ' + fpnSet.length);
  insertBeforeStmt(fpnSet[0], [
    setV('fi', item('VStack', llen('VStack'))),
    I('data_deleteoflist', { fields: B.LISTF('VStack'), inputs: { INDEX: B.REP(txt('last'), [4, '0']) } })
  ]);
  console.log('[P86] the callee survives user calls in the arguments');
});

// ---- P87: `import math as m` and the module constants math.pi / math.e (E52/E53) ----
//
// `import math as m` was accepted (Tok[2] is still "math") but the alias was thrown away, so
// `m.floor(2.5)` raised NameError.  And `math.pi` never even reached the method dispatch:
// eval's attribute branch demands an instance and `math` is not a variable.
//
// The module name now lives in `mthname` (default "math"): the import branch records the
// alias, methodcall's math dispatch accepts either spelling, and eval answers the constants
// before the attribute lookup.
patch('P87 math alias and constants', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('mthname')) throw new Error('[P87] variable name taken: mthname');
  newVar('mthname', 'math');

  // (a) the import branch keeps the alias
  const ex = inDef('execute');
  const hasmath = find(ex, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'hasmath' && litOf(b.inputs.VALUE) === '1');
  if (hasmath.length !== 1) throw new Error('[P87] hasmath set = ' + hasmath.length);
  spliceAfter(hasmath[0], chain([
    setV('mthname', txt('math')),
    IF(EQ(item('Tok', num(3)), txt('as')), [setV('mthname', item('Tok', num(4)))])
  ]));
  console.log('[P87] import math as NAME recorded');

  // (b) methodcall's math dispatch accepts the alias
  const mc = inDef('methodcall %s %s');
  const mathEq = find(mc, (b) => b.opcode === 'operator_equals'
    && ((blk(b.inputs.OPERAND1) && blk(b.inputs.OPERAND1).opcode === 'data_itemoflist' && blk(b.inputs.OPERAND1).fields.LIST && blk(b.inputs.OPERAND1).fields.LIST[0] === 'Tok' && argName(blk(b.inputs.OPERAND1).inputs.INDEX) === 'lo' && litOf(b.inputs.OPERAND2) === 'math')));
  if (mathEq.length !== 1) throw new Error('[P87] math dispatch test = ' + mathEq.length);
  replaceExpr(mathEq[0], () => OR(mathEq[0], EQ(item('Tok', argOf('lo')), VAR('mthname'))));
  console.log('[P87] math dispatch also answers the alias');

  // (c) eval: math.pi / math.e
  const ev = inDef('eval %s %s');
  const tokAt = (off, lit) => I('operator_equals', { inputs: { OPERAND1: B.REP(item('Tok', ADD(argOf('lo'), num(off))), [10, '']), OPERAND2: B.REP(txt(lit), [10, '']) } });
  const attrIf = find(ev, (b) => {
    if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') return false;
    const c = b.inputs.CONDITION && b.inputs.CONDITION[1];
    if (typeof c !== 'string') return false;
    const a = BL()[c];
    if (!a || a.opcode !== 'operator_and') return false;
    const eqAt = (d, off, lit) => {
      const e = blk(d);
      if (!e || e.opcode !== 'operator_equals') return false;
      const t = (x) => {
        const b = blk(x);
        if (!b || b.opcode !== 'data_itemoflist') return false;
        if (!b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
        const ix = blk(b.inputs.INDEX);
        return !!ix && ix.opcode === 'operator_add' && argName(ix.inputs.NUM1) === 'lo' && litOf(ix.inputs.NUM2) === String(off);
      };
      return (t(e.inputs.OPERAND1) && litOf(e.inputs.OPERAND2) === lit);
    };
    const eqHi = (d) => { const e = blk(d); return !!e && e.opcode === 'operator_equals' && argName(e.inputs.OPERAND1) === 'hi'; };
    return (eqAt(a.inputs.OPERAND1, 1, '.') && eqHi(a.inputs.OPERAND2)) || (eqAt(a.inputs.OPERAND2, 1, '.') && eqHi(a.inputs.OPERAND1));
  });
  if (attrIf.length !== 1) throw new Error('[P87] eval attribute branch = ' + attrIf.length);
  const constSet = (v) => [setV('ev', num(v)), setV('evtype', txt('N')), chgV('fnlimit', num(-1)), STOPTHIS()];
  const guard = AND(AND(tokAt(1, '.'), EQ(argOf('hi'), ADD(argOf('lo'), num(2)))), AND(EQ(item('Tok', argOf('lo')), VAR('mthname')), EQ(VAR('hasmath'), num(1))));
  insertBeforeStmt(attrIf[0], [
    IF(guard, [
      IFELSE(EQ(item('Tok', ADD(argOf('lo'), num(2))), txt('pi')), constSet('3.141592653589793'), [
        IF(EQ(item('Tok', ADD(argOf('lo'), num(2))), txt('e')), constSet('2.718281828459045'))
      ])
    ])
  ]);
  console.log('[P87] math.pi / math.e answered');
});

// ---- P88: try/else (E48) ----
//
// Two obstacles:
//   1. prepare rejected `else` after `except` outright ("elif/else without if"), so the
//      program never ran.  `except` (and `try`) join the allowed predecessors.
//   2. `else` after `except` must run only when the try body finished *without* an exception.
//      The interpreter already knows that moment: reaching the `except` line with the try
//      frame still on the stack (pc+1 == TryHand[last]) means normal completion, and there it
//      jumps straight to TryEnd -- skipping the else clause.  At that point look at Elses[pc]
//      (the next line at the same indent): if it is an `else`, jump there with branchjump set
//      so the ordinary `else` handler runs its body; otherwise keep the old TryEnd jump.
//      (Prepare sets Elses[except] to a following else/elif/except/finally line, hence the
//      tokenize check.)
//
// NB the replacement is several statements: replaceStmt() only takes ONE block and would
// overwrite the first block's `next`, so splice the rest in afterwards (see the README note).
patch('P88 try else', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const isTok1 = (x, lit) => {
    const b = blk(x);
    return !!b && b.opcode === 'operator_equals' && blk(b.inputs.OPERAND1) === undefined
      ? false
      : (!!b && b.opcode === 'operator_equals');
  };
  const tok1Eq = (d, lit) => {
    const e = blk(d);
    if (!e || e.opcode !== 'operator_equals') return false;
    const t = blk(e.inputs.OPERAND1);
    return !!t && t.opcode === 'data_itemoflist' && t.fields.LIST && t.fields.LIST[0] === 'Tok'
      && litOf(t.inputs.INDEX) === '1' && litOf(e.inputs.OPERAND2) === lit;
  };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['tcx', 'tce']) if (taken.has(n)) throw new Error('[P88] variable name taken: ' + n);
  for (const v of ['tcx', 'tce']) newVar(v, 0);

  // (a) prepare accepts `else` after except/try
  const prep = inDef('prepare');
  const noIf = find(prep, (b, id) => b.opcode === 'operator_not' && [...reach(id)].some((k) => tok1Eq([2, k], 'while')));
  if (noIf.length !== 1) throw new Error('[P88] prepare else guard = ' + noIf.length);
  const guarded = BL()[noIf[0]].inputs.OPERAND[1];
  replaceExpr(noIf[0], () => NOT(OR(guarded, OR(
    EQ(item('Tok', num(1)), txt('except')),
    EQ(item('Tok', num(1)), txt('try'))))));
  console.log('[P88] prepare accepts else after except');

  // (b) the normal-completion jump
  const ex = inDef('execute');
  const destSet = find(ex, (b) => {
    if (b.opcode !== 'data_setvariableto' || !b.fields.VARIABLE || b.fields.VARIABLE[0] !== 'dest') return false;
    const ib = blk(b.inputs.VALUE);
    return !!ib && ib.opcode === 'data_itemoflist' && ib.fields.LIST && ib.fields.LIST[0] === 'TryEnd';
  });
  if (destSet.length !== 1) throw new Error('[P88] except normal-completion dest = ' + destSet.length);
  const stmts = [
    setV('tcx', item('Elses', VAR('pc'))),
    setV('tce', num(0)),
    IF(GT(VAR('tcx'), num(0)), [
      callProc('tokenize %s', [item('Code', VAR('tcx'))]),
      IF(EQ(item('Tok', num(1)), txt('else')), [setV('tce', num(1))]),
      callProc('tokenize %s', [item('Code', VAR('pc'))])
    ]),
    IFELSE(EQ(VAR('tce'), num(1)), [
      setV('dest', VAR('tcx')),
      setV('branchjump', num(1))
    ], [
      setV('dest', item('TryEnd', llen('TryEnd')))
    ])
  ];
  replaceStmt(destSet[0], stmts[0]);
  spliceAfter(stmts[0], chain(stmts.slice(1)));
  console.log('[P88] try/else runs on normal completion');
});

// ---- P89: for a, b in <container> (E35) ----
//
// forloop insisted on `Tok[3] == "in"`, so a multi-target header died at the guard.  A new
// branch (in front of that guard) collects the target names into a comma separated string,
// evaluates the iterable and starts an ordinary "list" loop whose LoopName is that string.
//
// The unpacking itself is a two-line change in `boundary`'s list branch: a real variable name
// never contains a comma, so when LoopName does, the element is a container and the names are
// bound from it (new helper `unpackto`).  That covers the first element too, because forloop's
// own first-element assignment is routed through the same helper.
patch('P89 for unpacking', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['un', 'uncnt', 'uni', 'unlo', 'unm', 'un2', 'fin2', 'fi2', 'fnames', 'flen', 'flen']) {
    if (taken.has(n)) throw new Error('[P89] variable name taken: ' + n);
  }
  for (const v of ['un', 'uncnt', 'uni', 'unlo', 'unm', 'un2', 'fin2', 'fi2', 'fnames', 'flen', 'flen']) newVar(v, 0);

  // ---------- (a) unpackto: bind `a,b,c` from a container encoding
  const ut = newProc('unpackto %s %s', ['names', 'enc']);
  attachBody(ut.defId, [
    callProc('listlen %s', [argOf('enc')]),
    setV('un', VAR('ev')),
    setV('uncnt', num(1)),
    setV('uni', num(1)),
    REPEATU(GT(VAR('uni'), lenOf(argOf('names'))), [
      IF(EQ(letterOf(VAR('uni'), argOf('names')), txt(',')), [chgV('uncnt', num(1))]),
      chgV('uni', num(1))
    ]),
    IF(NOT(EQ(VAR('un'), VAR('uncnt'))), [
      IFELSE(LT(VAR('un'), VAR('uncnt')),
        [FAIL('ValueError: not enough values to unpack')],
        [FAIL('ValueError: too many values to unpack')])
    ]),
    setV('uni', num(1)),
    setV('unlo', num(1)),
    setV('un2', num(1)),
    REPEATU(GT(VAR('uni'), lenOf(argOf('names'))), [
      IF(EQ(letterOf(VAR('uni'), argOf('names')), txt(',')), [
        callProc('substr %s %s %s', [argOf('names'), VAR('unlo'), SUB(VAR('uni'), num(1))]),
        setV('unm', VAR('ev')),
        callProc('listitem %s %s', [argOf('enc'), VAR('un2')]),
        callProc('assign %s %s %s', [VAR('unm'), VAR('ev'), VAR('evtype')]),
        chgV('un2', num(1)),
        setV('unlo', ADD(VAR('uni'), num(1)))
      ]),
      chgV('uni', num(1))
    ]),
    callProc('substr %s %s %s', [argOf('names'), VAR('unlo'), lenOf(argOf('names'))]),
    setV('unm', VAR('ev')),
    callProc('listitem %s %s', [argOf('enc'), VAR('un2')]),
    callProc('assign %s %s %s', [VAR('unm'), VAR('ev'), VAR('evtype')])
  ]);
  // The unpack marker is LoopStep == 0 (a real loop never has step 0, and boundary's list
  // branch advances by a literal +1 and never reads LoopStep).  Sniffing the name for a
  // comma through operator_contains turned out to be unreliable in this position.
  const bindNames = (nameExpr, encExpr) => IFELSE(
    EQ(item('LoopStep', VAR('lc')), num(0)),
    [callProc('unpackto %s %s', [nameExpr, encExpr])],
    [callProc('assign %s %s %s', [nameExpr, VAR('ev'), VAR('evtype')])]);
  console.log('[P89] unpackto registered');

  // ---------- (b) boundary: a LoopName holding a comma means "unpack this element"
  const bd = inDef('boundary');
  const bAssign = find(bd, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'assign %s %s %s'
    && b.inputs && (() => {
      const ids = JSON.parse(b.mutation.argumentids);
      const nm = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
      const d = b.inputs[ids[0]];
      const ib = blk(d);
      const isLoopName = !!ib && ib.opcode === 'data_itemoflist' && ib.fields.LIST && ib.fields.LIST[0] === 'LoopName';
      // the list branch is the one binding ev/evtype; the str and numeric branches pass a
      // letter expression and a literal type instead
      return isLoopName && nm(b.inputs[ids[1]]) === 'ev' && nm(b.inputs[ids[2]]) === 'evtype';
    })());
  if (bAssign.length !== 1) throw new Error('[P89] boundary LoopName assign = ' + bAssign.length);
  const bNameExpr = (() => { const ids = JSON.parse(BL()[bAssign[0]].mutation.argumentids); return BL()[bAssign[0]].inputs[ids[0]]; })();
  replaceStmt(bAssign[0], bindNames(bNameExpr, VAR('ev')));
  console.log('[P89] boundary unpacks list elements when needed');

  // ---------- (c) forloop: accept `for a, b in <container>`
  const fl = inDef('forloop');
  const first = BL()[defIdOf('forloop')].next;
  insertBeforeStmt(first, [
    IF(AND(EQ(item('Tok', num(1)), txt('for')),
      AND(EQ(item('Tok', num(3)), txt(',')), EQ(item('Tok', VAR('count')), txt(':')))), [
      setV('fin2', num(0)),
      setV('fi2', num(2)),
      REPEATU(GT(VAR('fi2'), VAR('count')), [
        IF(EQ(item('Tok', VAR('fi2')), txt('in')), [setV('fin2', VAR('fi2'))]),
        chgV('fi2', num(1))
      ]),
      IF(EQ(VAR('fin2'), num(0)), [FAIL('SyntaxError: for x in range(...):')]),
      setV('fnames', item('Tok', num(2))),
      setV('fi2', num(4)),
      REPEATU(GT(VAR('fi2'), SUB(VAR('fin2'), num(1))), [
        setV('fnames', JOIN(JOIN(VAR('fnames'), txt(',')), item('Tok', VAR('fi2')))),
        chgV('fi2', num(2))
      ]),
      callProc('eval %s %s', [ADD(VAR('fin2'), num(1)), SUB(VAR('count'), num(1))]),
      IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
      IF(EQ(VAR('evtype'), txt('D')), [callProc('dictkeys %s', [VAR('ev')])]),
      IF(NOT(OR(EQ(VAR('evtype'), txt('L')), EQ(VAR('evtype'), txt('T')))), [FAIL('TypeError: cannot unpack non-iterable object')]),
      setV('ltmp', VAR('ev')),
      callProc('listlen %s', [VAR('ltmp')]),
      setV('flen', VAR('ev')),
      // pushLoop first: its arguments are read before the call, so nothing the
      // first-element binding does afterwards can disturb them
      IFELSE(GT(VAR('flen'), num(0)), [
        callProc('pushLoop %s %s %s %s %s', [txt('list'), VAR('fnames'), num(1), VAR('flen'), num(0)]),
        I('data_replaceitemoflist', { fields: B.LISTF('LoopText'), inputs: { INDEX: B.REP(llen('LoopText'), [4, '0']), ITEM: B.REP(VAR('ltmp'), [10, '']) } }),
        callProc('listitem %s %s', [VAR('ltmp'), num(1)]),
        callProc('unpackto %s %s', [VAR('fnames'), VAR('ev')])
      ], [
        setV('dest', item('Ends', VAR('pc')))
      ]),
      STOPTHIS()
    ])
  ]);
  console.log('[P89] for a, b in container installed');
});

// ---- P90: class attributes and __str__ (E45/E47) ----
//
// The `class` handler only looked for `def` lines, so `class C: n = 1` silently defined an
// empty class and `C.n` was a NameError (`C` is a class name, not a variable, so eval's
// attribute branch -- which demands an instance -- never even ran).
//
// The IAttrId/IAttrName/IAttrVal/IAttrType tables already hold "object -> attribute"
// bindings and their key is just a string (an instance id is a number, so a class name
// cannot collide).  So:
//   * the class body evaluates every simple `name = value` line into that table with the
//     class name as the key;
//   * eval's attribute branch answers for a class name directly, and instance lookups fall
//     back to the class table when the instance has no such attribute;
//   * strval calls `__str__` when the class defines one.
patch('P90 class attributes and str', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (i) => item('Tok', num(i));
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['ccsav', 'canm', 'ccl2']) if (taken.has(n)) throw new Error('[P90] variable name taken: ' + n);
  for (const v of ['ccsav', 'canm', 'ccl2']) newVar(v, 0);
  const isTokOff = (d, off) => {
    const b = blk(d);
    if (!b || b.opcode !== 'data_itemoflist' || !b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
    const ix = blk(b.inputs.INDEX);
    return !!ix && ix.opcode === 'operator_add' && argName(ix.inputs.NUM1) === 'lo' && litOf(ix.inputs.NUM2) === String(off);
  };
  const lookupAttr = (idExpr, nameExpr) => [
    setV('cX', num(0)),
    setV('ck', num(1)),
    REPEATU(GT(VAR('ck'), llen('IAttrId')), [
      IF(AND(EQ(item('IAttrId', VAR('ck')), idExpr), EQ(item('IAttrName', VAR('ck')), nameExpr)), [
        setV('cX', VAR('ck')),
        setV('ck', llen('IAttrId'))
      ]),
      chgV('ck', num(1))
    ])
  ];

  // ---------- (a) the class body keeps `name = value` lines
  const ex = inDef('execute');
  const clsLoop = find(ex, (b) => b.opcode === 'control_repeat_until' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => {
      const q = BL()[id];
      return q && q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'regdef %s';
    }));
  if (clsLoop.length !== 1) throw new Error('[P90] class body loop = ' + clsLoop.length);
  const ckInc = find(reach(BL()[clsLoop[0]].inputs.SUBSTACK[1]), (b) => b.opcode === 'data_changevariableby'
    && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ck');
  if (ckInc.length !== 1) throw new Error('[P90] class body increment = ' + ckInc.length);
  insertBeforeStmt(ckInc[0], [
    IF(AND(NOT(EQ(tokAt(1), txt('def'))),
      AND(EQ(item('Kind', num(1)), txt('I')),
        AND(EQ(tokAt(2), txt('=')), NOT(EQ(tokAt(4), txt('=')))))), [
      // save the name and the class before eval: a nested call may re-tokenize Tok
      setV('ccsav', VAR('ccls')),
      setV('canm', tokAt(1)),
      setV('cax', VAR('pc')),
      setV('pc', VAR('ck')),
      callProc('eval %s %s', [num(3), VAR('count')]),
      IF(EQ(VAR('error'), txt('')), [
        ...lookupAttr(VAR('ccsav'), VAR('canm')),
        IFELSE(EQ(VAR('cX'), num(0)), [
          addTo('IAttrId', VAR('ccsav')),
          addTo('IAttrName', VAR('canm')),
          addTo('IAttrVal', VAR('ev')),
          addTo('IAttrType', VAR('evtype'))
        ], [
          I('data_replaceitemoflist', { fields: B.LISTF('IAttrVal'), inputs: { INDEX: B.REP(VAR('cX'), [4, '0']), ITEM: B.REP(VAR('ev'), [10, '']) } }),
          I('data_replaceitemoflist', { fields: B.LISTF('IAttrType'), inputs: { INDEX: B.REP(VAR('cX'), [4, '0']), ITEM: B.REP(VAR('evtype'), [10, '']) } })
        ])
      ]),
      setV('ccls', VAR('ccsav')),
      setV('pc', VAR('cax'))
    ])
  ]);
  console.log('[P90] class bodies keep name = value lines');

  // ---------- (b) eval: `Class.attr` and the instance -> class fallback
  const ev = inDef('eval %s %s');
  const attrIf = find(ev, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else') && (() => {
    const a = blk(b.inputs.CONDITION);
    if (!a || a.opcode !== 'operator_and') return false;
    const e1 = blk(a.inputs.OPERAND1);
    if (!e1 || e1.opcode !== 'operator_equals' || !isTokOff(e1.inputs.OPERAND1, 1) || litOf(e1.inputs.OPERAND2) !== '.') return false;
    // ... and the other half is `hi == lo + 2` -- the method-call branch tests `hi == ")"` instead
    const e2 = blk(a.inputs.OPERAND2);
    if (!e2 || e2.opcode !== 'operator_equals' || argName(e2.inputs.OPERAND1) !== 'hi') return false;
    const add = blk(e2.inputs.OPERAND2);
    return !!add && add.opcode === 'operator_add' && argName(add.inputs.NUM1) === 'lo' && litOf(add.inputs.NUM2) === '2';
  })());
  if (attrIf.length !== 1) throw new Error('[P90] eval attribute branch = ' + attrIf.length);
  const attrOf = () => item('Tok', ADD(argOf('lo'), num(2)));
  // NB list membership (data_listcontainsitem) compares case-insensitively in Scratch, so
  // `c.v` on the instance `c` would match the class `C`.  compareText is case-sensitive.
  const taken2 = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken2.has('cfnd')) throw new Error('[P90] variable name taken: cfnd');
  newVar('cfnd', 0);
  const isClassName = () => [
    setV('cfnd', num(0)),
    setV('ck', num(1)),
    REPEATU(GT(VAR('ck'), llen('ClsName')), [
      callProc('compareText %s %s', [item('ClsName', VAR('ck')), item('Tok', argOf('lo'))]),
      IF(EQ(VAR('cmp'), num(0)), [setV('cfnd', num(1)), setV('ck', llen('ClsName'))]),
      chgV('ck', num(1))
    ])
  ];
  // fresh copies of the attribute shape: the class name alone is not enough, `C()` also
  // starts with a class name but has no `.attr`
  const attrShape = () => AND(
    EQ(item('Tok', ADD(argOf('lo'), num(1))), txt('.')),
    EQ(argOf('hi'), ADD(argOf('lo'), num(2))));
  insertBeforeStmt(attrIf[0], [
    IF(attrShape(), [
      ...isClassName(),
      IF(EQ(VAR('cfnd'), num(1)), [
        setV('iid', item('Tok', argOf('lo'))),
        ...lookupAttr(VAR('iid'), attrOf()),
        IFELSE(EQ(VAR('cX'), num(0)),
          [FAILB(JOIN(txt('AttributeError: '), attrOf()))],
          [setV('ev', item('IAttrVal', VAR('cX'))), setV('evtype', item('IAttrType', VAR('cX')))]),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ])
  ]);
  const attrFail = find(ev, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && (() => {
      const d = b.inputs[JSON.parse(b.mutation.argumentids)[0]];
      const b2 = blk(d);
      return !!b2 && b2.opcode === 'operator_join' && litOf(b2.inputs.STRING1) === 'AttributeError: ';
    })());
  if (attrFail.length !== 1) throw new Error('[P90] attribute failure = ' + attrFail.length);
  insertBeforeStmt(attrFail[0], [
    // Only when the instance itself has no such attribute (lookupAttr resets cX).  The value
    // has to be loaded here: we are inside the *then* branch of `if cX == 0`, so the
    // original tree's `else: ev = IAttrVal[cX]` will not run.
    IF(EQ(VAR('cX'), num(0)), [
      ...lookupAttr(item('InstCls', VAR('iid')), attrOf()),
      IF(GT(VAR('cX'), num(0)), [
        setV('ev', item('IAttrVal', VAR('cX'))),
        setV('evtype', item('IAttrType', VAR('cX')))
      ])
    ])
  ]);
  // ... and the failure must now only fire when the class lookup failed too
  replaceStmt(attrFail[0], IF(EQ(VAR('cX'), num(0)), [attrFail[0]]));
  console.log('[P90] Class.attr and the instance -> class fallback');

  // ---------- (c) printargs: use __str__ for an instance
  // NB it must NOT live in strval: assign() calls strval on every bound value to refresh the
  // variables panel, and assigning `self` inside callmeth would then re-enter __str__ forever.
  const pa = inDef('printargs');
  const argLoop = find(pa, (b) => b.opcode === 'control_repeat' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => {
      const q = BL()[id];
      return q && q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'strval %s %s';
    }));
  if (argLoop.length !== 1) throw new Error('[P90] printargs argument loop = ' + argLoop.length);
  const svCall = find(reach(BL()[argLoop[0]].inputs.SUBSTACK[1]), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'strval %s %s');
  if (svCall.length !== 1) throw new Error('[P90] printargs strval = ' + svCall.length);
  const hasStr = I('data_listcontainsitem', {
    fields: B.LISTF('FnName'),
    inputs: { ITEM: B.REP(JOIN(item('InstCls', VAR('ev')), txt('.__str__')), [10, '']) }
  });
  const sink = cloneExpr(svCall[0]);
  replaceStmt(svCall[0], IFELSE(AND(EQ(VAR('evtype'), txt('O')), hasStr), [
    callProc('callmeth %s %s %s %s', [VAR('ev'), txt('__str__'), num(1), num(0)])
  ], [sink]));
  console.log('[P90] print uses __str__ for an instance');
});

// ---- P91: dict methods -- keys/values/items/get/pop (E42) ----
//
// methodcall's type guard only allowed L/S/O, so `d.keys()` raised "only lists have methods".
// The D branch goes in front of that guard (the same place P82 hooked `format`) and hands off
// to `dictmeth`, which reuses the encoding helpers from P79/P80.
//
// CPython reprs dict views with a wrapper, so keys()/values()/items() format their list and
// wrap it: dict_keys(['a']), dict_values([1]), dict_items([('a', 1)]).
patch('P91 dict methods', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['dmk', 'dmv', 'dmvt', 'dmkt', 'dmtup', 'dmenc', 'dmn', 'dmi', 'dmf', 'dmc', 'dmp', 'dmq']) {
    if (taken.has(n)) throw new Error('[P91] variable name taken: ' + n);
  }
  for (const v of ['dmk', 'dmv', 'dmvt', 'dmkt', 'dmtup', 'dmenc', 'dmn', 'dmi', 'dmf', 'dmc', 'dmp', 'dmq']) newVar(v, 0);
  const rec = argOf('rec');

  // ---------- (a) the value / item encodings
  const dv = newProc('dictvals %s', ['s']);
  attachBody(dv.defId, [
    setV('dmenc', txt('')),
    callProc('listlen %s', [argOf('s')]),
    setV('dmn', VAR('ev')),
    setV('dmi', num(2)),
    REPEATU(GT(VAR('dmi'), VAR('dmn')), [
      callProc('listitem %s %s', [argOf('s'), VAR('dmi')]),
      setV('dmkt', VAR('evtype')),
      callProc('lesc %s', [VAR('ev')]),
      setV('dmenc', JOIN(VAR('dmenc'), JOIN(VAR('lsep'), JOIN(VAR('dmkt'), VAR('ev'))))),
      chgV('dmi', num(2))
    ]),
    setV('ev', VAR('dmenc')),
    setV('evtype', txt('L'))
  ]);
  const di = newProc('dictitems %s', ['s']);
  attachBody(di.defId, [
    setV('dmenc', txt('')),
    callProc('listlen %s', [argOf('s')]),
    setV('dmn', VAR('ev')),
    setV('dmi', num(1)),
    REPEATU(GT(VAR('dmi'), VAR('dmn')), [
      callProc('listitem %s %s', [argOf('s'), VAR('dmi')]),
      setV('dmkt', VAR('evtype')),
      callProc('lesc %s', [VAR('ev')]),
      setV('dmk', VAR('ev')),
      callProc('listitem %s %s', [argOf('s'), ADD(VAR('dmi'), num(1))]),
      setV('dmvt', VAR('evtype')),
      callProc('lesc %s', [VAR('ev')]),
      // one tuple record: lsep T lsep kt key lsep vt value
      setV('dmtup', JOIN(VAR('lsep'), JOIN(VAR('dmkt'), VAR('dmk')))),
      setV('dmtup', JOIN(VAR('dmtup'), JOIN(VAR('lsep'), JOIN(VAR('dmvt'), VAR('ev'))))),
      callProc('lesc %s', [VAR('dmtup')]),
      setV('dmenc', JOIN(VAR('dmenc'), JOIN(VAR('lsep'), JOIN(txt('T'), VAR('ev'))))),
      chgV('dmi', num(2))
    ]),
    setV('ev', VAR('dmenc')),
    setV('evtype', txt('L'))
  ]);
  console.log('[P91] dictvals / dictitems registered');

  // ---------- (b) dictmeth
  const dm = newProc('dictmeth %s %s %s %s %s', ['rec', 'nm', 'meth', 'lo', 'hi']);
  const wrap = (open, enc) => [
    callProc(enc, [rec]),
    callProc('listfmt %s', [VAR('ev')]),
    setV('ev', JOIN(JOIN(txt(open), VAR('ev')), txt(')'))),
    setV('evtype', txt('S')),
    STOPTHIS()
  ];
  const keyLookup = [
    callProc('hascomma %s %s', [argOf('lo'), argOf('hi')]),
    IFELSE(EQ(VAR('tqhcm'), num(1)),
      [callProc('eval %s %s', [argOf('lo'), SUB(VAR('tqcpz'), num(1))])],
      [callProc('eval %s %s', [argOf('lo'), argOf('hi')])]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    setV('dmk', VAR('ev')),
    setV('dmkt', VAR('evtype')),
    callProc('listlen %s', [rec]),
    setV('dmn', VAR('ev')),
    setV('dmi', num(1)),
    setV('dmf', num(0)),
    REPEATU(OR(GT(VAR('dmi'), VAR('dmn')), GT(VAR('dmf'), num(0))), [
      callProc('listitem %s %s', [rec, VAR('dmi')]),
      IF(EQ(VAR('evtype'), VAR('dmkt')), [
        callProc('compareText %s %s', [VAR('ev'), VAR('dmk')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('dmf', VAR('dmi'))])
      ]),
      chgV('dmi', num(2))
    ])
  ];
  const popDelete = [
    setV('dmp', num(0)),
    setV('dmc', num(0)),
    setV('dmi', num(1)),
    REPEATU(GT(VAR('dmi'), lenOf(rec)), [
      IF(EQ(letterOf(VAR('dmi'), rec), VAR('lsep')), [
        chgV('dmc', num(1)),
        IF(EQ(VAR('dmc'), VAR('dmf')), [setV('dmp', VAR('dmi'))])
      ]),
      chgV('dmi', num(1))
    ]),
    IF(EQ(VAR('dmp'), num(0)), [setV('dmp', num(1))]),
    setV('dmq', num(0)),
    setV('dmc', num(0)),
    setV('dmi', num(1)),
    REPEATU(GT(VAR('dmi'), lenOf(rec)), [
      IF(EQ(letterOf(VAR('dmi'), rec), VAR('lsep')), [
        chgV('dmc', num(1)),
        IF(EQ(VAR('dmc'), ADD(VAR('dmf'), num(2))), [setV('dmq', VAR('dmi'))])
      ]),
      chgV('dmi', num(1))
    ]),
    IF(EQ(VAR('dmq'), num(0)), [setV('dmq', ADD(lenOf(rec), num(1)))]),
    callProc('substr %s %s %s', [rec, num(1), SUB(VAR('dmp'), num(1))]),
    setV('dmtup', VAR('ev')),
    callProc('substr %s %s %s', [rec, VAR('dmq'), lenOf(rec)]),
    setV('dmtup', JOIN(VAR('dmtup'), VAR('ev'))),
    callProc('assign %s %s %s', [argOf('nm'), VAR('dmtup'), txt('D')])
  ];
  attachBody(dm.defId, [
    IF(EQ(argOf('meth'), txt('keys')), wrap('dict_keys(', 'dictkeys %s')),
    IF(EQ(argOf('meth'), txt('values')), wrap('dict_values(', 'dictvals %s')),
    IF(EQ(argOf('meth'), txt('items')), wrap('dict_items(', 'dictitems %s')),
    IF(OR(EQ(argOf('meth'), txt('get')), EQ(argOf('meth'), txt('pop'))), [
      setV('tqhcm', num(0)),
      ...keyLookup,
      IFELSE(GT(VAR('dmf'), num(0)), [
        callProc('listitem %s %s', [rec, ADD(VAR('dmf'), num(1))]),
        IF(EQ(argOf('meth'), txt('pop')), [
          setV('dmvt', VAR('evtype')),
          setV('dmv', VAR('ev')),
          ...popDelete,
          setV('ev', VAR('dmv')),
          setV('evtype', VAR('dmvt'))
        ])
      ], [
        IF(EQ(argOf('meth'), txt('get')), [
          IFELSE(EQ(VAR('tqhcm'), num(1)),
            [callProc('eval %s %s', [ADD(VAR('tqcpz'), num(1)), argOf('hi')])],
            [setV('ev', txt('')), setV('evtype', txt('Z'))])
        ])
      ]),
      STOPTHIS()
    ]),
    FAILB(JOIN(txt('AttributeError: dict has no method '), argOf('meth')))
  ]);
  console.log('[P91] dictmeth registered');

  // ---------- (c) hook it into methodcall, in front of the type guard
  const mc = inDef('methodcall %s %s');
  const typeGuard = find(mc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && (() => {
    const n = blk(b.inputs.CONDITION);
    if (!n || n.opcode !== 'operator_not') return false;
    return [...reach(b.inputs.CONDITION[1])].some((id) => {
      const e = BL()[id];
      return e && e.opcode === 'operator_equals' && varName(e.inputs.OPERAND1) === 'xb' && litOf(e.inputs.OPERAND2) === 'O';
    });
  })());
  if (typeGuard.length !== 1) throw new Error('[P91] methodcall type guard = ' + typeGuard.length);
  insertBeforeStmt(typeGuard[0], [
    IF(EQ(VAR('xb'), txt('D')), [
      callProc('dictmeth %s %s %s %s %s', [VAR('xa'), item('Tok', argOf('lo')), item('Tok', ADD(argOf('lo'), num(2))), ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
      STOPTHIS()
    ])
  ]);
  console.log('[P91] dict methods hooked');
});

// ---- P93: brace-aware depth scans (E12, and the whole family behind it) ----
//
// Every scanner that walks a token span and tracks bracket depth only counted `(` `)`
// `[` `]`, never `{` `}`.  A dict literal therefore ended the span at its first inner
// comma or operator:
//   print({'a': 1, 'b': 2})        -> SyntaxError: expression
//   len({'a': 1, 'b': 2})          -> NameError: name len is not defined (narg == 2)
//   d = {'n': n + 1}               -> SyntaxError: expression   (fixed earlier, in P33)
//
// P50 tried to wrap *every* `x == '(' or x == '['` pair and broke tuple/str/b2: many of
// those ORs are not depth tests at all (they decide "is this an opening bracket?" with a
// real body).  This patch only touches an if whose shape is provably a depth counter:
//   * the condition only compares ONE expression against chars of a single family
//     (`(`/`[` for opens, `)`/`]` for closes) -- nothing else is compared;
//   * that expression is the same in every comparison (compared structurally, since the
//     original project stores one block per comparison);
//   * the body is exactly one `change <var> by +1` (opens) or `-1` (closes);
//   * the expression is a `Tok[...]` read or a plain variable (no side effects: Scratch
//     evaluates both operands of `or`, so a call would run twice).
// For those the new comparison is a pure extension of the same depth count.
patch('P93 brace depth scans', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blkOf = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const idOf = (d) => (typeof d === 'string') ? d : ((d && typeof d[1] === 'string') ? d[1] : null);
  // every operator_equals inside a condition tree
  const collect = (d, out = [], seen = new Set()) => {
    const id = idOf(d);
    if (!id || seen.has(id)) return out;
    seen.add(id);
    const b = BL()[id];
    if (!b) return out;
    if (b.opcode === 'operator_equals') {
      const a = litOf(b.inputs.OPERAND1), c = litOf(b.inputs.OPERAND2);
      out.push({ ch: a !== null ? a : c, x: a !== null ? b.inputs.OPERAND2 : b.inputs.OPERAND1 });
      return out;
    }
    for (const v of Object.values(b.inputs || {})) collect(v, out, seen);
    return out;
  };
  // canonical rendering: block ids replaced by "first seen" numbers, so two structurally
  // identical expressions compare equal even when they are separate blocks
  const canon = (d, map = new Map()) => {
    if (d === null || d === undefined) return 'null';
    if (typeof d === 'string') return 'blk' + (map.has(d) ? map.get(d) : (map.set(d, '#' + map.size), map.get(d)));
    if (Array.isArray(d)) {
      const id = idOf(d);
      if (id && BL()[id]) {
        if (!map.has(id)) map.set(id, '#' + map.size);
        const b = BL()[id];
        const f = Object.entries(b.fields || {}).map(([k, v]) => k + '=' + JSON.stringify(v[0])).join(',');
        const ins = Object.entries(b.inputs || {}).sort(([p], [q]) => p < q ? -1 : 1).map(([k, v]) => k + '=' + canon(v, map)).join(',');
        return '[' + map.get(id) + ' ' + b.opcode + '{' + f + '|' + ins + '}]';
      }
      return '(' + d.map((e) => canon(e, map)).join(',') + ')';
    }
    return JSON.stringify(d);
  };
  // a value expression safe to evaluate twice
  const isSafeX = (d) => {
    const b = blkOf(d);
    if (b && b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Tok') return true;
    return !!(d && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] !== 'ev' && d[1][1] !== 'error');
  };
  // a fresh copy of the operand (each block can have only one parent)
  const dupX = (d) => {
    const c = JSON.parse(JSON.stringify(d));
    if (typeof c === 'string') return cloneExpr(c);
    if (Array.isArray(c) && typeof c[1] === 'string' && BL()[c[1]]) c[1] = cloneExpr(c[1]);
    return c;
  };
  const deltaOf = (b) => {
    const v = b.inputs && b.inputs.VALUE;
    if (!v) return null;
    const raw = (Array.isArray(v) && v[0] === 1 && Array.isArray(v[1])) ? v[1] : v;
    if (Array.isArray(raw) && (raw[0] === 4 || raw[0] === 10) && typeof raw[1] === 'string') return Number(raw[1]);
    return null;
  };
  let opened = 0, closed = 0, skipped = 0;
  for (const id of find(allIds(), (b) => b.opcode === 'control_if')) {
    const condId = idOf(BL()[id].inputs.CONDITION);
    if (!condId) continue;
    const chars = collect(BL()[id].inputs.CONDITION);
    if (!chars.length || chars.some((c) => c.ch === null || c.ch === undefined)) continue;
    const set = [...new Set(chars.map((c) => c.ch))];
    const opens = set.every((c) => c === '(' || c === '[');
    const closes = set.every((c) => c === ')' || c === ']');
    if (!opens && !closes) continue;
    const xs = new Set(chars.map((c) => canon(c.x)));
    if (xs.size !== 1) { skipped++; continue; }
    if (!isSafeX(chars[0].x)) { skipped++; continue; }
    const s = BL()[id].inputs.SUBSTACK;
    if (!s || typeof s[1] !== 'string') continue;
    const only = BL()[s[1]];
    if (only.opcode !== 'data_changevariableby' || only.next) continue;
    if (deltaOf(only) !== (closes ? -1 : 1)) continue;
    const want = closes ? '}' : '{';
    const newEq = I('operator_equals', {
      inputs: { OPERAND1: B.REP(dupX(chars[0].x), [10, '']), OPERAND2: B.REP(txt(want), [10, '']) }
    });
    replaceExpr(condId, () => OR(condId, newEq));
    if (closes) closed++; else opened++;
  }
  console.log('[P93] brace-aware depth scans: ' + opened + ' open + ' + closed + ' close (' + skipped + ' skipped)');
});

// ---- P92: postfix chains -- `.attr` / `[...]` on an arbitrary expression (E54, E11) ----
//
// `eval`'s atom dispatch only recognised postfix operators when the root was a *single
// token*: `.` needed exactly `X . name` (Tok[lo+1]=='.' and hi==lo+2) and `[` needed
// exactly `X [ ... ]` (Tok[lo+1]=='['), so every chain whose root is itself a call,
// subscript or literal died in the final else with `SyntaxError: expression`:
//   C().v   c.inc().v   xs[1].v   f(){,[1]}   {'k': 7}['k']   [1, 2][0]   f()[1]
//
// Two new branches are inserted at the head of that final else-chain (in front of the
// methodcall test), so they only see spans every earlier branch rejected:
//   (A) trailing `.name` -- evaluate the *root* span lo..hi-2, then read the attribute
//       from the resulting instance (IAttr), falling back to the class table (P90), and
//       stop this script;
//   (B) trailing `]` -- find the `[` that matches the last token with a bracket-only
//       depth scan; when it is not the first token (`x[0]` stays on the old path) hand
//       the whole span to `indexget`, which already evaluates its container as
//       `eval(lo, xbr-1)` and therefore handles any expression.  When the `[` *is* the
//       first token the if simply falls through to the untouched original chain.
//
// Both branches leave `eval` early, so each compensates the `fnlimit +1` that eval's
// entry block did (the same thing P90 does before its STOPTHIS).
patch('P92 postfix chains', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (x) => item('Tok', x);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['pxd', 'pxj', 'pxbr', 'atnm', 'atid']) if (taken.has(n)) throw new Error('[P92] variable name taken: ' + n);
  for (const v of ['pxd', 'pxj', 'pxbr', 'atnm', 'atid']) newVar(v, 0);
  // the same instance/class attribute lookup P90 installed inline
  const lookupAttr = (idExpr, nameExpr) => [
    setV('cX', num(0)),
    setV('ck', num(1)),
    REPEATU(GT(VAR('ck'), llen('IAttrId')), [
      IF(AND(EQ(item('IAttrId', VAR('ck')), idExpr), EQ(item('IAttrName', VAR('ck')), nameExpr)), [
        setV('cX', VAR('ck')),
        setV('ck', llen('IAttrId'))
      ]),
      chgV('ck', num(1))
    ])
  ];
  const useAttr = () => [setV('ev', item('IAttrVal', VAR('cX'))), setV('evtype', item('IAttrType', VAR('cX')))];
  // fresh reporters every time (a shared reporter block cannot sit in two inputs)
  const LO = () => argOf('lo');
  const HI = () => argOf('hi');
  const ROOT = () => SUB(HI(), num(2));

  const ev = inDef('eval %s %s');
  const mcIf = find(ev, (b) => b.opcode === 'control_if_else'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
    && BL()[b.inputs.SUBSTACK[1]].mutation
    && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'methodcall %s %s');
  if (mcIf.length !== 1) throw new Error('[P92] eval methodcall branch = ' + mcIf.length);

  // ---------- (A) `... . name`
  const branchA = IF(
    AND(EQ(tokAt(SUB(HI(), num(1))), txt('.')),
      AND(EQ(item('Kind', HI()), txt('I')),
        NOT(GT(LO(), ROOT())))),
    [
      setV('atnm', tokAt(HI())),
      callProc('eval %s %s', [LO(), ROOT()]),
      IF(EQ(VAR('error'), txt('')), [
        IFELSE(EQ(VAR('evtype'), txt('O')), [
          setV('atid', VAR('ev')),
          ...lookupAttr(VAR('atid'), VAR('atnm')),
          IFELSE(EQ(VAR('cX'), num(0)), [
            ...lookupAttr(item('InstCls', VAR('atid')), VAR('atnm')),
            IFELSE(EQ(VAR('cX'), num(0)),
              [FAILB(JOIN(txt('AttributeError: '), VAR('atnm')))],
              useAttr())
          ], useAttr())
        ], [
          FAIL(txt('SyntaxError: attribute access'))
        ])
      ]),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ]);

  // ---------- (B) `... [ ... ]`
  const branchB = IF(EQ(tokAt(HI()), txt(']')), [
    setV('pxd', num(0)),
    setV('pxj', LO()),
    setV('pxbr', num(0)),
    REPEATU(GT(VAR('pxj'), HI()), [
      IF(EQ(tokAt(VAR('pxj')), txt('[')), [
        IF(EQ(VAR('pxd'), num(0)), [setV('pxbr', VAR('pxj'))]),
        chgV('pxd', num(1))
      ]),
      IF(EQ(tokAt(VAR('pxj')), txt(']')), [chgV('pxd', num(-1))]),
      chgV('pxj', num(1))
    ]),
    IF(GT(VAR('pxbr'), ADD(LO(), num(1))), [
      callProc('indexget %s %s', [LO(), HI()]),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ])
  ]);

  insertBeforeStmt(mcIf[0], [branchA, branchB]);
  console.log('[P92] eval: postfix chains (.attr / [i] over an expression) installed');
});

// ---- P94: one shared pow kernel -- integer / half exponents are exact (G2, G3) ----
//
// Both pow implementations went through exp/log and lost the last bit:
//   math.pow(2.0, 3.0)  -> 7.999999999999998   (CPython 8.0)   [e^(3*ln2) rounding]
//   2 ** 0.5            -> 1.414213562373095    (CPython 1.4142135623730951)
//   math.pow(2, 3)      -> 7.999999999999998 / printed as `7.99...` instead of `8.0`
//
// `**` already used exact repeated multiplication for integer exponents; math.pow did
// not.  This patch registers one `powval base exp` procedure that
//   * multiplies out an integer exponent (|exp| <= 1024) -- exact, and negates for
//     exp < 0 (1/x**n),
//   * uses the correctly-rounded `sqrt` for +-0.5 (Scratch's `e ^`/`ln` are 1 ulp off),
//   * falls back to `e^(exp*ln base)` otherwise (with the usual domain error),
//   * re-applies `mkfloat` when either operand was a float, so `4 ** 0.5` prints 2.0;
// and routes both call sites (rightside's `**` non-integer branch and P23's math.pow)
// through it.  The `8.0` that CPython's math.pow always returns is forced by an extra
// mkfloat in the math.pow branch (its result is a float even for two ints).
patch('P94 pow accuracy', () => {
  const MATHOP = (op, x) => I('operator_mathop', { fields: { OPERATOR: [op, null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const hasDot = (x) => I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('.'), [10, '']) } });
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['pvb', 'pve', 'pvq']) if (taken.has(n)) throw new Error('[P94] variable name taken: ' + n);
  for (const v of ['pvb', 'pve', 'pvq']) newVar(v, 0);

  const pv = newProc('powval %s %s', ['base', 'exp']);
  attachBody(pv.defId, [
    setV('pvb', argOf('base')),
    setV('pve', argOf('exp')),
    IFELSE(AND(EQ(MOD(VAR('pve'), num(1)), num(0)), NOT(GT(MATHOP('abs', VAR('pve')), num(1024)))), [
      // integer exponent: exact repeated multiplication
      setV('pvq', num(1)),
      REPEAT(MATHOP('abs', VAR('pve')), [setV('pvq', MUL(VAR('pvq'), VAR('pvb')))]),
      IFELSE(LT(VAR('pve'), num(0)), [setV('ev', DIV(num(1), VAR('pvq')))], [setV('ev', VAR('pvq'))])
    ], [
      IF(LT(VAR('pvb'), num(0)), [FAIL(txt('ValueError: math domain error')), STOPTHIS()]),
      IFELSE(EQ(VAR('pve'), num(0.5)), [
        setV('ev', MATHOP('sqrt', VAR('pvb')))
      ], [
        IFELSE(EQ(VAR('pve'), num(-0.5)), [
          setV('ev', DIV(num(1), MATHOP('sqrt', VAR('pvb'))))
        ], [
          setV('ev', MATHOP('e ^', MUL(VAR('pve'), MATHOP('ln', VAR('pvb')))))
        ])
      ])
    ]),
    setV('evtype', txt('N')),
    IF(OR(hasDot(VAR('pvb')), hasDot(VAR('pve'))), [callProc('mkfloat %s', [VAR('ev')])])
  ]);
  console.log('[P94] powval registered');

  // ---------- (a) rightside: `**` with a non-integer exponent
  const rs = inDef('rightside %s %s %s %s %s');
  const powSet = find(rs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && (() => {
      const v = b.inputs.VALUE;
      const q = (v && typeof v[1] === 'string') ? BL()[v[1]] : null;
      return !!q && q.opcode === 'operator_mathop' && q.fields.OPERATOR && q.fields.OPERATOR[0] === 'e ^';
    })());
  if (powSet.length !== 1) throw new Error('[P94] rightside e^ assignment = ' + powSet.length);
  replaceStmt(powSet[0], callProc('powval %s %s', [argOf('leftval'), VAR('ev')]));
  console.log('[P94] ** routes through powval');

  // ---------- (b) math.pow
  const mc = inDef('methodcall %s %s');
  const mpSet = find(mc, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && (() => {
      const v = b.inputs.VALUE;
      const q = (v && typeof v[1] === 'string') ? BL()[v[1]] : null;
      if (!q || q.opcode !== 'operator_mathop' || !q.fields.OPERATOR || q.fields.OPERATOR[0] !== 'e ^') return false;
      // math.pow computes e^(exp*ln base): the exponent is a multiply, exp()'s is not
      const num = q.inputs.NUM;
      const m = (num && typeof num[1] === 'string') ? BL()[num[1]] : null;
      return !!m && m.opcode === 'operator_multiply';
    })());
  if (mpSet.length !== 1) throw new Error('[P94] methodcall math.pow assignment = ' + mpSet.length);
  replaceStmt(mpSet[0], chain([
    callProc('powval %s %s', [VAR('mav'), VAR('mav2')]),
    callProc('mkfloat %s', [VAR('ev')])
  ]));
  console.log('[P94] math.pow routes through powval (result forced to float)');
});

// ---- P95: augmented assignment to an attribute or a subscript ----
//
// `c.v += 1`, `self.v -= 1`, `self.s += 'b'`, `c.v *= 4`, `a[0] += 5`, `d['k'] += 5` all died:
//   * execute's `+= -= *= /= %=` branch only fires when Tok[2] IS the operator, and the
//     `//= **=` / `&= |= ... ` branches need Kind[1]=='I' + Tok[2]/Tok[3] -- for `c.v += 1`
//     the operator sits at Tok[4], and for `a[0] += 5` indexset demands `Tok[lsp+1]=='='`;
//   * so the statement fell through to the expression-statement fallback and reported
//     `SyntaxError: expression` (attribute) or `SyntaxError: expected = after ]` (index).
//
// Two branches are inserted at the head of that chain (in front of the `c.v = ...` branch),
// both of which *rewrite the statement in place* so the existing, already-correct store
// paths do the writing:
//   (A) `name . attr <op>= rhs`  -> `c.v = <value>`      (P55's attribute branch stores it)
//   (B) `name [ sub ] <op>= rhs` -> `a[0] = <value>`     (indexset stores it, slices included)
// The computed value travels as a single "typed literal" token: Tok[n] = the encoded value,
// Kind[n] = its type char.  atom() gets one new branch for that (the kinds the tokenizer
// itself produces are only S/I/O/N/F, so L/T/D/B are free), and the value keeps its exact
// type -- which matters because indexset would otherwise re-evaluate the right-hand side
// (a second call to a function in it!) and store the wrong type.
//
// The right-hand side is evaluated exactly once, by `rightside` -- the same procedure the
// ordinary `+=` branch uses, so `a + b` type rules stay in one place.
patch('P95 augmented attribute/index assignment', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (i) => item('Tok', i);
  const setTokAt = (i, v) => I('data_replaceitemoflist', { fields: B.LISTF('Tok'), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const setKindAt = (i, v) => I('data_replaceitemoflist', { fields: B.LISTF('Kind'), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][1] !== undefined) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blkOf = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const MERGED = ['+=', '-=', '*=', '/=', '%='];      // one token: '+=' etc.
  const SPLIT = ['**', '//', '<<', '>>', '&', '|', '^']; // two tokens: '**' then '='
  const RWTYPES = ['N', 'S', 'L', 'T', 'D', 'B'];  // every value type may ride a token
  const NEWKINDS = ['L', 'T', 'D', 'B'];            // only these need the new atom branch: N/S have their own
  const orChain = (factory, ops) => ops.reduce((acc, o) => acc ? OR(acc, EQ(factory(), txt(o))) : EQ(factory(), txt(o)), null);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['augop', 'augvs', 'auglsp', 'augd', 'augx', 'augvv', 'augvt']) if (taken.has(n)) throw new Error('[P95] variable name taken: ' + n);
  for (const v of ['augop', 'augvs', 'auglsp', 'augd', 'augx', 'augvv', 'augvt']) newVar(v, 0);
  // NB `factory` must build a FRESH reporter every call: one Scratch block has exactly one
  // parent, and a shared reporter really does misbehave (measured: the whole condition went
  // false), so never hoist `tokAt(...)`/`VAR(...)` out of the chain.
  const TOK4 = () => tokAt(num(4));
  const TOK5 = () => tokAt(num(5));
  const EVT = () => VAR('evtype');

  // ---------- (0) atom: a token may carry a value of its own type (L/T/D/B)
  const at = inDef('atom %s');
  const argNameOf = (d) => { const b = blkOf(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const kindSet = find(at, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'evtype'
    && (() => {
      const v = b.inputs.VALUE;
      const q = (v && typeof v[1] === 'string') ? BL()[v[1]] : null;
      return !!q && q.opcode === 'data_itemoflist' && q.fields.LIST && q.fields.LIST[0] === 'Kind'
        && argNameOf(q.inputs.INDEX) === 'idx';
    })());
  if (kindSet.length !== 1) throw new Error('[P95] atom evtype assignment = ' + kindSet.length);
  spliceAfter(kindSet[0], chain([
    IF(orChain(EVT, NEWKINDS), [STOPTHIS()])
  ]));
  console.log('[P95] atom: typed literal tokens (L/T/D/B)');

  // ---------- the insertion point: execute's `c.v = ...` branch (P55)
  const ex = inDef('execute');
  const isTokAt = (d, idx) => {
    const b = blkOf(d);
    if (!b || b.opcode !== 'data_itemoflist' || !b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
    return litOf(b.inputs.INDEX) === String(idx);
  };
  const isKindAt = (d, idx) => {
    const b = blkOf(d);
    if (!b || b.opcode !== 'data_itemoflist' || !b.fields.LIST || b.fields.LIST[0] !== 'Kind') return false;
    return litOf(b.inputs.INDEX) === String(idx);
  };
  const condEq = (condId, isAt, idx, lit) => [...reach(condId)].some((id) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (isAt(a, idx) && litOf(c) === lit) || (isAt(c, idx) && litOf(a) === lit);
  });
  const attrSet = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && condEq(b.inputs.CONDITION[1], isTokAt, 2, '.')
    && condEq(b.inputs.CONDITION[1], isTokAt, 4, '=')
    && condEq(b.inputs.CONDITION[1], isKindAt, 1, 'I'));
  if (attrSet.length !== 1) throw new Error('[P95] execute attribute-set branch = ' + attrSet.length);

  // ---------- (A) attribute: `c.v <op>= rhs`
  const branchA = IF(
    AND(AND(EQ(item('Kind', num(1)), txt('I')), EQ(tokAt(num(2)), txt('.'))),
      AND(EQ(item('Kind', num(3)), txt('I')),
        OR(orChain(TOK4, MERGED), AND(orChain(TOK4, SPLIT), EQ(TOK5(), txt('=')))))),
    [
      callProc('eval %s %s', [num(1), num(3)]),
      IF(EQ(VAR('error'), txt('')), [
        setV('augvv', VAR('ev')),
        setV('augvt', VAR('evtype')),
        IFELSE(AND(EQ(lenOf(tokAt(num(4))), num(2)), EQ(letterOf(num(2), tokAt(num(4))), txt('='))),
          [setV('augop', letterOf(num(1), tokAt(num(4)))), setV('augvs', num(5))],
          [setV('augop', tokAt(num(4))), setV('augvs', num(6))]),
        callProc('rightside %s %s %s %s %s', [VAR('augvv'), VAR('augvt'), VAR('augop'), VAR('augvs'), VAR('count')]),
        IF(orChain(EVT, RWTYPES), [
          setTokAt(num(4), txt('=')),
          setTokAt(num(5), VAR('ev')),
          setKindAt(num(5), VAR('evtype')),
          setV('count', num(5))
        ])
      ]),
      // `c.v += 1` with a v that does not exist must keep the attribute error instead of
      // letting the expression-statement fallback overwrite it with "SyntaxError: expression"
      IF(NOT(EQ(VAR('error'), txt(''))), [setV('pending', num(1))])
    ]);

  // ---------- (B) subscript: `a[i] <op>= rhs`
  const branchB = IF(
    AND(EQ(item('Kind', num(1)), txt('I')), GT(VAR('count'), num(3))),
    [
      IF(EQ(tokAt(num(2)), txt('[')), [
        setV('auglsp', num(0)),
        setV('augd', num(0)),
        setV('augx', num(1)),
        REPEATU(GT(VAR('augx'), VAR('count')), [
          IF(OR(EQ(tokAt(VAR('augx')), txt('[')), EQ(tokAt(VAR('augx')), txt('{'))), [chgV('augd', num(1))]),
          IF(EQ(tokAt(VAR('augx')), txt(']')), [
            chgV('augd', num(-1)),
            IF(AND(EQ(VAR('augd'), num(0)), EQ(VAR('auglsp'), num(0))), [setV('auglsp', VAR('augx'))])
          ]),
          chgV('augx', num(1))
        ]),
        IF(GT(VAR('auglsp'), num(0)), [
          setV('augop', txt('')),
          IF(AND(EQ(lenOf(tokAt(ADD(VAR('auglsp'), num(1)))), num(2)), EQ(letterOf(num(2), tokAt(ADD(VAR('auglsp'), num(1)))), txt('='))), [
            setV('augop', letterOf(num(1), tokAt(ADD(VAR('auglsp'), num(1))))),
            setV('augvs', ADD(VAR('auglsp'), num(2)))
          ], [
            IF(AND(orChain(() => tokAt(ADD(VAR('auglsp'), num(1))), SPLIT), EQ(tokAt(ADD(VAR('auglsp'), num(2))), txt('='))), [
              setV('augop', tokAt(ADD(VAR('auglsp'), num(1)))),
              setV('augvs', ADD(VAR('auglsp'), num(3)))
            ])
          ]),
          IF(NOT(EQ(VAR('augop'), txt(''))), [
            callProc('eval %s %s', [num(1), VAR('auglsp')]),
            IF(EQ(VAR('error'), txt('')), [
              setV('augvv', VAR('ev')),
              setV('augvt', VAR('evtype')),
              callProc('rightside %s %s %s %s %s', [VAR('augvv'), VAR('augvt'), VAR('augop'), VAR('augvs'), VAR('count')]),
              IF(orChain(EVT, RWTYPES), [
                setTokAt(ADD(VAR('auglsp'), num(1)), txt('=')),
                setTokAt(ADD(VAR('auglsp'), num(2)), VAR('ev')),
                setKindAt(ADD(VAR('auglsp'), num(2)), VAR('evtype')),
                setV('count', ADD(VAR('auglsp'), num(2)))
              ])
            ]),
            IF(NOT(EQ(VAR('error'), txt(''))), [setV('pending', num(1))])
          ])
        ])
      ])
    ]);

  insertBeforeStmt(attrSet[0], [branchA, branchB]);
  console.log('[P95] attribute/subscript augmented assignment installed');
});

// ---- P96: a loop that ends a function body really iterates (F2, plus plain loops) ----
//
// `def f(): for i in range(3): print(i)` printed only `0`; likewise every `yield` inside a
// loop collected a single item (`list(sq(3))` -> `[0]`), while the same loop followed by one
// more statement (`return s`) was correct.
//
// Two line drivers exist.  The top-level one exits only when
//     (pc > len(Code)) AND (len(LoopHead) == 0)
// and the caller-side guard is `pc <= len(Code)`; that pair is what lets `boundary()` (the
// loop-back handler, called at the top of every step) run one more time *after* the loop
// body's last line, when `pc` has already become `LoopEnd`, and jump back to the body.
// `calluser`'s driver tested `pc > fend` and `pc > len(Code)` instead, so a loop whose body
// ended the function left pc = LoopEnd = fend+1, the driver stopped, and the loop ran one
// iteration.  Measured: body line re-runs per iteration (pc stays on the LoopEnd line) and
// LoopEnd = the line after the body.
//
// Fix, in the same two places:
//   1. the driver's exit test requires "no loop opened by this frame is still open";
//      FrLoop holds `len(LoopHead)` at call time (P14 unwinds back to it on return), so a
//      caller's loop cannot keep this frame alive;
//   2. the step guard compares against `fend`, not `len(Code)`: without that, the frame would
//      run the *caller's* next line after its own loop finished (measured: infinite
//      self-recursion of `f()`).
patch('P96 loop at end of function body', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blkOf = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varNameOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
    const b = blkOf(d);
    return b && b.opcode === 'data_variable' ? b.fields.VARIABLE[0] : null;
  };
  const listNameOf = (d) => {
    const b = blkOf(d);
    return b && b.opcode === 'data_lengthoflist' && b.fields.LIST ? b.fields.LIST[0] : null;
  };
  const cu = inDef('calluser %s %s %s');
  // ---------- 1) the driver's exit test: only the "ran off the end of the body" term
  // waits for open loops -- `return` inside a loop (retflag) and errors must still stop it
  const drv = find(cu, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_gt') return false;
      return varNameOf(q.inputs.OPERAND1) === 'fend' || varNameOf(q.inputs.OPERAND2) === 'fend';
    }));
  if (drv.length !== 1) throw new Error('[P96] calluser driver = ' + drv.length);
  const gtFend = find(reach(BL()[drv[0]].inputs.CONDITION[1]), (b) => b.opcode === 'operator_gt'
    && (varNameOf(b.inputs.OPERAND1) === 'fend' || varNameOf(b.inputs.OPERAND2) === 'fend'));
  if (gtFend.length !== 1) throw new Error('[P96] calluser pc > fend = ' + gtFend.length);
  replaceExpr(gtFend[0], () => AND(gtFend[0], NOT(GT(llen('LoopHead'), item('FrLoop', llen('FrLoop'))))));
  // ---------- 2) the per-step guard: `pc <= fend` instead of `pc <= len(Code)`
  const lenCodeIf = find(cu, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_gt') return false;
      return varNameOf(q.inputs.OPERAND1) === 'pc' && listNameOf(q.inputs.OPERAND2) === 'Code';
    }));
  if (lenCodeIf.length !== 1) throw new Error('[P96] calluser step guard = ' + lenCodeIf.length);
  const gt = find(reach(BL()[lenCodeIf[0]].inputs.CONDITION[1]), (b) => b.opcode === 'operator_gt'
    && varNameOf(b.inputs.OPERAND1) === 'pc' && listNameOf(b.inputs.OPERAND2) === 'Code');
  if (gt.length !== 1) throw new Error('[P96] calluser pc > len(Code) = ' + gt.length);
  replaceExpr(gt[0], () => GT(VAR('pc'), VAR('fend')));
  console.log('[P96] calluser: the function driver waits for its own open loops and stays inside the frame');
});

// ---- P97: a generator can drive a for loop (E55) ----
//
// `for v in sq(3):` failed with `TypeError: for expects a string` even though
// `list(sq(3))`, `len()` and `sum()` already accept the collected generator value.  P52
// assembles a generator as one encoded run of `lsep + type + escaped-value` records --
// byte-for-byte the same encoding a list has -- and tags it 'G'.  The generic
// `for x in <expr>:` handler dispatches on the tag:
//     if (evtype == 'L' or evtype == 'T')  -> list path (listlen/listitem/pushLoop 'list')
//     else                                 -> string path, which rejects anything not 'S'
// so the only missing piece is that OR: add `or evtype == 'G'`.  Everything below it only
// calls listlen/listitem on `ltmp`, and those ignore the tag.
patch('P97 for over a generator', () => {
  const blkOf = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const descId = (d) => (typeof d === 'string') ? d : ((d && typeof d[1] === 'string') ? d[1] : null);
  const varNameOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
    const b = blkOf(d);
    return b && b.opcode === 'data_variable' ? b.fields.VARIABLE[0] : null;
  };
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const eqEvtype = (id, lit) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    const a = b.inputs.OPERAND1, c = b.inputs.OPERAND2;
    return (varNameOf(a) === 'evtype' && litOf(c) === lit) || (varNameOf(c) === 'evtype' && litOf(a) === lit);
  };
  const callsProc = (root, pc) => [...reach(root)].some((id) => {
    const q = BL()[id];
    return q && q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === pc;
  });
  const fl = inDef('forloop');
  const cands = find(fl, (b) => {
    if (b.opcode !== 'control_if_else') return false;
    const cond = blkOf(b.inputs.CONDITION);
    if (!cond || cond.opcode !== 'operator_or') return false;
    const ids = [...reach(descId(b.inputs.CONDITION))];
    if (!ids.some((x) => eqEvtype(x, 'L')) || !ids.some((x) => eqEvtype(x, 'T'))) return false;
    if (ids.some((x) => eqEvtype(x, 'G'))) return false;
    const sub = (b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string') ? b.inputs.SUBSTACK[1] : null;
    const sub2 = (b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string') ? b.inputs.SUBSTACK2[1] : null;
    if (!sub || !sub2) return false;
    return callsProc(sub, 'pushLoop %s %s %s %s %s') && callsProc(sub2, 'fail %s');
  });
  if (cands.length !== 1) throw new Error('[P97] forloop iterable dispatch = ' + cands.length);
  const orId = descId(BL()[cands[0]].inputs.CONDITION);
  replaceExpr(orId, () => OR(orId, EQ(VAR('evtype'), txt('G'))));
  console.log('[P97] for x in <generator> is accepted');
});

// ---- P98: a comprehension inside a comprehension (F1) ----
//
// `[[y for y in range(x)] for x in range(3)]` returned `[[]]`, and
// `[[y for y in range(2)] for x in range(2)]` returned `[0, 1, [0, 1]]`: the outer
// comprehension's element expression is itself a `[...]`, so `eval` re-enters
// listlit -> complist, and the inner call overwrites **every** scratch variable the outer
// one is still using (cfor/cif/cilo/cihi/cacc/cv/cstep/cstop/cn/cok/... plus the CComm
// list).  The outer loop then keeps counting with the inner loop's bounds and appends into
// the inner accumulator.
//
// Same shape P46 fixed for listlit, and the same fix: save the whole scratch set around
// every `eval` in complist.  The save/restore live in two small warp procedures
// (`csave`/`crestore`, both called from all 12 eval sites) so the patch costs 24 call
// blocks instead of ~1500 inline ones.  The element value travels in ev/evtype, which is
// deliberately NOT part of the save.
patch('P98 nested comprehension', () => {
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p98n', 'p98i']) if (taken.has(n)) throw new Error('[P98] variable name taken: ' + n);
  for (const v of ['p98n', 'p98i']) newVar(v, 0);
  // the whole scratch set complist uses (reverse-pushed on VStack, like P46)
  const VARS = ['cfor', 'cif', 'cdep', 'ck', 'cilo', 'cihi', 'cacc', 'cn', 'cv', 'cstop', 'cstep', 'cok',
    'clist', 'cltyp', 'cev', 'cet', 'cqidx', 'c1n', 'c1s', 'c1v', 'c1t'];
  const saveL = (X) => [
    setV('p98n', llen(X)),
    setV('p98i', VAR('p98n')),
    REPEATU(NOT(GT(VAR('p98i'), num(0))), [addTo('VStack', item(X, VAR('p98i'))), chgV('p98i', num(-1))]),
    addTo('VStack', VAR('p98n'))
  ];
  const restoreL = (X) => [
    setV('p98n', item('VStack', llen('VStack'))),
    delLast('VStack'),
    clearL(X),
    setV('p98i', num(1)),
    REPEATU(GT(VAR('p98i'), VAR('p98n')), [addTo(X, item('VStack', llen('VStack'))), delLast('VStack'), chgV('p98i', num(1))])
  ];
  const sv = newProc('csave', []);
  attachBody(sv.defId, [...VARS.map((v) => addTo('VStack', VAR(v))), ...saveL('CComm')]);
  const rs = newProc('crestore', []);
  attachBody(rs.defId, [...restoreL('CComm'), ...[...VARS].reverse().flatMap((v) => [
    setV(v, item('VStack', llen('VStack'))), delLast('VStack')
  ])]);
  const cl = inDef('complist %s %s');
  const evals = find(cl, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
  if (evals.length < 4) throw new Error('[P98] complist eval sites = ' + evals.length);
  for (const callId of evals) {
    insertBeforeStmt(callId, [callProc('csave')]);
    spliceAfter(callId, chain([callProc('crestore')]));
  }
  console.log('[P98] complist re-entrant (' + evals.length + ' eval sites via csave/crestore)');
});

// ---- P99: enumerate() and zip() (E23/E24) ----
//
// Both are pure list builders and the pieces already exist: `listitem` decodes the
// lsep-encoded element stream, `lesc` escapes a value so it can be embedded, and a *nested*
// container is just `lsep + 'T' + lesc(inner encoding)` (that is how tuplelit nests inside a
// list).  So
//   enumerate(xs)   -> [(0, xs[0]), (1, xs[1]), ...]
//   zip(a, b, ...)  -> [(a[0], b[0], ...), (a[1], b[1], ...), ...]  (shortest input wins)
// as a list of tuples.
//
// Dispatch details (traced): a call with no top-level comma has `narg == 0` and eval's
// narg==0 branch calls `callfn(fn, lo+2, hi-1)` on the single argument, so `enumerate(xs)`
// lands in callfn with ev/evtype already set -- one branch there is enough.  `zip(a, b)` has
// a comma: it must not go through callfn at all, because callfn begins with `eval(lo,hi)` and
// that span starts with `[` and ends with `]`, which eval takes for a list literal
// (`TypeError: list index must be an integer`).  So a `zip` hook sits in eval before the
// narg dispatch: split the sources with `hascomma` (comma -> tuplelit, else a single eval),
// build, compensate `fnlimit` for the early `stop this script`, and return.
patch('P99 enumerate and zip', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NAMES = ['xss', 'xst', 'xst2', 'xsn', 'xsi', 'xsv', 'xsvt', 'xsp', 'xsa', 'xsk', 'xsl', 'xsw'];
  for (const n of NAMES) if (taken.has(n)) throw new Error('[P99] variable name taken: ' + n);
  for (const v of NAMES) newVar(v, 0);
  const isIter = (v) => OR(OR(EQ(VAR(v), txt('L')), EQ(VAR(v), txt('T'))), OR(EQ(VAR(v), txt('G')), EQ(VAR(v), txt('S'))));
  const appendPair = (acc) => [
    callProc('lesc %s', [VAR('xsp')]),
    setV(acc, JOIN(VAR(acc), VAR('lsep'))),
    setV(acc, JOIN(VAR(acc), txt('T'))),
    setV(acc, JOIN(VAR(acc), VAR('ev')))
  ];
  // ---------- zipbuild: ev/evtype = a tuple of sources (or one source) -> list of tuples
  const zb = newProc('zipbuild', []);
  attachBody(zb.defId, [
    setV('xsw', VAR('ev')),
    setV('xst', VAR('evtype')),
    IF(NOT(OR(EQ(VAR('xst'), txt('T')), isIter('xst'))), [FAIL(txt('TypeError: zip() needs iterables')), STOPTHIS()]),
    IFELSE(EQ(VAR('xst'), txt('T')),
      [callProc('listlen %s', [VAR('xsw')]), setV('xsl', VAR('ev'))],
      [setV('xsl', num(1))]),
    setV('xsn', num(-1)),
    setV('xsk', num(1)),
    REPEATU(GT(VAR('xsk'), VAR('xsl')), [
      IFELSE(EQ(VAR('xst'), txt('T')),
        [callProc('listitem %s %s', [VAR('xsw'), VAR('xsk')]), setV('xss', VAR('ev')), setV('xst2', VAR('evtype'))],
        [setV('xss', VAR('xsw')), setV('xst2', VAR('xst'))]),
      IF(NOT(isIter('xst2')), [FAIL(txt('TypeError: zip() needs iterables')), STOPTHIS()]),
      IFELSE(EQ(VAR('xst2'), txt('S')),
        [setV('xsv', lenOf(VAR('xss')))],
        [callProc('listlen %s', [VAR('xss')]), setV('xsv', VAR('ev'))]),
      IF(OR(EQ(VAR('xsn'), num(-1)), LT(VAR('xsv'), VAR('xsn'))), [setV('xsn', VAR('xsv'))]),
      chgV('xsk', num(1))
    ]),
    setV('xsa', txt('')),
    setV('xsi', num(1)),
    REPEATU(GT(VAR('xsi'), VAR('xsn')), [
      setV('xsp', txt('')),
      setV('xsk', num(1)),
      REPEATU(GT(VAR('xsk'), VAR('xsl')), [
        IFELSE(EQ(VAR('xst'), txt('T')),
          [callProc('listitem %s %s', [VAR('xsw'), VAR('xsk')]), setV('xss', VAR('ev')), setV('xst2', VAR('evtype'))],
          [setV('xss', VAR('xsw')), setV('xst2', VAR('xst'))]),
        IFELSE(EQ(VAR('xst2'), txt('S')),
          [setV('xsv', letterOf(VAR('xsi'), VAR('xss'))), setV('xsvt', txt('S'))],
          [callProc('listitem %s %s', [VAR('xss'), VAR('xsi')]), setV('xsv', VAR('ev')), setV('xsvt', VAR('evtype'))]),
        callProc('lesc %s', [VAR('xsv')]),
        setV('xsp', JOIN(VAR('xsp'), VAR('lsep'))),
        setV('xsp', JOIN(VAR('xsp'), VAR('xsvt'))),
        setV('xsp', JOIN(VAR('xsp'), VAR('ev'))),
        chgV('xsk', num(1))
      ]),
      ...appendPair('xsa'),
      chgV('xsi', num(1))
    ]),
    setV('ev', VAR('xsa')),
    setV('evtype', txt('L'))
  ]);
  console.log('[P99] zipbuild registered');

  // ---------- callfn: enumerate (the single argument is already in ev/evtype)
  const enumBranch = IF(EQ(argOf('fn'), txt('enumerate')), [
    setV('xss', VAR('ev')),
    setV('xst', VAR('evtype')),
    IF(NOT(isIter('xst')), [FAIL(txt('TypeError: enumerate() needs a list or string')), STOPTHIS()]),
    IFELSE(EQ(VAR('xst'), txt('S')), [setV('xsn', lenOf(VAR('xss')))], [callProc('listlen %s', [VAR('xss')]), setV('xsn', VAR('ev'))]),
    setV('xsa', txt('')),
    setV('xsi', num(1)),
    REPEATU(GT(VAR('xsi'), VAR('xsn')), [
      IFELSE(EQ(VAR('xst'), txt('S')),
        [setV('xsv', letterOf(VAR('xsi'), VAR('xss'))), setV('xsvt', txt('S'))],
        [callProc('listitem %s %s', [VAR('xss'), VAR('xsi')]), setV('xsv', VAR('ev')), setV('xsvt', VAR('evtype'))]),
      callProc('lesc %s', [VAR('xsv')]),
      setV('xsp', JOIN(VAR('lsep'), txt('N'))),
      setV('xsp', JOIN(VAR('xsp'), SUB(VAR('xsi'), num(1)))),
      setV('xsp', JOIN(VAR('xsp'), VAR('lsep'))),
      setV('xsp', JOIN(VAR('xsp'), VAR('xsvt'))),
      setV('xsp', JOIN(VAR('xsp'), VAR('ev'))),
      ...appendPair('xsa'),
      chgV('xsi', num(1))
    ]),
    setV('ev', VAR('xsa')),
    setV('evtype', txt('L')),
    setV('pending', num(1))
  ]);
  const cf = inDef('callfn %s %s %s');
  const lit = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const sortedIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_equals') return false;
      return lit(q.inputs.OPERAND2) === 'sorted' || lit(q.inputs.OPERAND1) === 'sorted';
    }));
  if (sortedIf.length !== 1) throw new Error('[P99] callfn sorted branch = ' + sortedIf.length);
  insertBeforeStmt(sortedIf[0], [enumBranch]);
  console.log('[P99] enumerate() installed in callfn');

  // ---------- eval: the zip hook (before the narg dispatch, so callfn never sees the commas)
  const ev2 = inDef('eval %s %s');
  const nargIf = find(ev2, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return (vn(q.inputs.OPERAND1) === 'narg' && lit(q.inputs.OPERAND2) === '0') || (vn(q.inputs.OPERAND2) === 'narg' && lit(q.inputs.OPERAND1) === '0');
    })());
  if (nargIf.length !== 1) throw new Error('[P99] eval narg dispatch = ' + nargIf.length);
  insertBeforeStmt(nargIf[0], [
    IF(EQ(item('Tok', argOf('lo')), txt('zip')), [
      callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IFELSE(EQ(VAR('tqhcm'), num(1)),
        [callProc('tuplelit %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))])],
        [callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))])]),
      IF(EQ(VAR('error'), txt('')), [callProc('zipbuild')]),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ])
  ]);
  console.log('[P99] eval: zip hook installed');
});

// ---- P100: keyword arguments in a user function call (E26) ----
//
// `f(1, c=9)` died with `SyntaxError: expression`: calluser splits its argument span on
// top-level commas and evaluates each piece as an expression, so the piece `c=9` was handed
// to eval() whole.  CPython semantics we need: a piece shaped `name = value` binds the
// parameter called `name` (evaluated at its own position, like any argument), the remaining
// pieces fill the parameters left to right, a name that is not a parameter is an error, and
// a parameter cannot be filled twice.
//
// So: a parallel list UArgN records, per collected argument, '' (positional), the keyword
// name, or '#' once consumed.  The piece's own span tells us which: Tok[fplo] is a NAME and
// Tok[fplo+1] == '=' (and not '=='), and then only `fplo+2 .. fphi` is evaluated.
// The binding loop then becomes: keyword match by name first, else the next unconsumed
// positional; and the "too many arguments" test counts positional pieces.
patch('P100 keyword arguments', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const replaceItem = (list, idx, val) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(val, [4, '0']) } });
  const F = (v) => VAR(v); // fresh reporters every use
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['kwq', 'kwk', 'kwp', 'kwnpos']) if (taken.has(n)) throw new Error('[P100] variable name taken: ' + n);
  for (const v of ['kwq', 'kwk', 'kwp', 'kwnpos']) newVar(v, 0);
  B.addList(IT, 'UArgN', []);
  const cu = inDef('calluser %s %s %s');

  // ---------- (a) clear UArgN together with UArgV/UArgT
  const clearV = find(cu, (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'UArgV');
  if (clearV.length !== 1) throw new Error('[P100] UArgV clear = ' + clearV.length);
  insertBeforeStmt(clearV[0], [clearL('UArgN')]);

  // ---------- (b) the piece evaluation: `name = value` -> record the name, evaluate the value
  const pieceEval = find(cu, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s'
    && (() => {
      const nx = b.next ? BL()[b.next] : null;
      return !!nx && nx.opcode === 'data_addtolist' && nx.fields.LIST && nx.fields.LIST[0] === 'UArgV';
    })());
  if (pieceEval.length !== 1) throw new Error('[P100] argument piece eval = ' + pieceEval.length);
  const kwShape = AND(EQ(item('Kind', F('fplo')), txt('I')),
    AND(EQ(item('Tok', ADD(F('fplo'), num(1))), txt('=')),
      NOT(EQ(item('Tok', ADD(F('fplo'), num(2))), txt('=')))));
  replaceStmt(pieceEval[0], IFELSE(kwShape, [
    addTo('UArgN', item('Tok', F('fplo'))),
    callProc('eval %s %s', [ADD(F('fplo'), num(2)), F('fphi')])
  ], [
    addTo('UArgN', txt('')),
    callProc('eval %s %s', [F('fplo'), F('fphi')])
  ]));
  console.log('[P100] keyword pieces are recognised');

  // ---------- (c) "too many arguments" counts positional pieces
  const wasLen = (d, listName) => {
    const q = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return !!q && q.opcode === 'data_lengthoflist' && q.fields.LIST && q.fields.LIST[0] === listName;
  };
  const tooMany = find(cu, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      return !!q && q.opcode === 'operator_gt' && wasLen(q.inputs.OPERAND1, 'UArgV');
    }));
  if (tooMany.length !== 1) throw new Error('[P100] too-many-arguments check = ' + tooMany.length);
  insertBeforeStmt(tooMany[0], [
    setV('kwnpos', num(0)),
    setV('kwk', num(1)),
    REPEATU(GT(F('kwk'), llen('UArgN')), [
      IF(EQ(item('UArgN', F('kwk')), txt('')), [chgV('kwnpos', num(1))]),
      chgV('kwk', num(1))
    ]),
    // every keyword name must name a parameter (CPython reports this before binding)
    setV('kwk', num(1)),
    REPEATU(GT(F('kwk'), llen('UArgN')), [
      IF(AND(NOT(EQ(item('UArgN', F('kwk')), txt(''))), NOT(EQ(item('UArgN', F('kwk')), txt('#')))), [
        setV('kwq', num(0)),
        setV('kwp', num(1)),
        REPEATU(GT(F('kwp'), F('fpn')), [
          IF(EQ(item('UArgN', F('kwk')), item('FnPar', ADD(F('fpo'), SUB(F('kwp'), num(1))))), [
            setV('kwq', num(1)),
            setV('kwp', F('fpn'))
          ]),
          chgV('kwp', num(1))
        ]),
        IF(EQ(F('kwq'), num(0)), [
          FAILB(JOIN(txt('TypeError: unexpected keyword argument '), item('UArgN', F('kwk')))),
          STOPTHIS()
        ])
      ]),
      chgV('kwk', num(1))
    ])
  ]);
  replaceExpr(BL()[tooMany[0]].inputs.CONDITION[1], () => GT(F('kwnpos'), F('fpn')));
  console.log('[P100] too-many-arguments counts positionals');

  // ---------- (d) the binding loop: keywords first, then the next unconsumed positional
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const bindLoop = find(cu, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_gt') return false;
      return (vnOf(q.inputs.OPERAND1) === 'fj' && vnOf(q.inputs.OPERAND2) === 'fpn')
        || (vnOf(q.inputs.OPERAND2) === 'fj' && vnOf(q.inputs.OPERAND1) === 'fpn');
    }));
  if (bindLoop.length !== 1) throw new Error('[P100] binding loop = ' + bindLoop.length);
  const newLoop = REPEATU(GT(F('fj'), F('fpn')), [
    setV('fu', ADD(F('fpo'), SUB(F('fj'), num(1)))),
    // is this parameter passed by name?
    setV('kwq', num(0)),
    setV('kwk', num(1)),
    REPEATU(GT(F('kwk'), llen('UArgN')), [
      IF(AND(NOT(EQ(item('UArgN', F('kwk')), txt(''))),
        AND(NOT(EQ(item('UArgN', F('kwk')), txt('#'))), EQ(item('UArgN', F('kwk')), item('FnPar', F('fu'))))), [
        setV('kwq', F('kwk')),
        setV('kwk', llen('UArgN'))
      ]),
      chgV('kwk', num(1))
    ]),
    IFELSE(GT(F('kwq'), num(0)), [
      callProc('assign %s %s %s', [item('FnPar', F('fu')), item('UArgV', F('kwq')), item('UArgT', F('kwq'))]),
      replaceItem('UArgN', F('kwq'), txt('#'))
    ], [
      // skip consumed/keyword pieces, then take the next positional
      REPEATU(OR(GT(F('kwp'), llen('UArgV')), EQ(item('UArgN', F('kwp')), txt(''))), [chgV('kwp', num(1))]),
      IFELSE(NOT(GT(F('kwp'), llen('UArgV'))), [
        callProc('assign %s %s %s', [item('FnPar', F('fu')), item('UArgV', F('kwp')), item('UArgT', F('kwp'))]),
        replaceItem('UArgN', F('kwp'), txt('#')),
        chgV('kwp', num(1))
      ], [
        setV('fdd', item('FnDef', F('fu'))),
        IFELSE(EQ(F('fdd'), txt('')), [
          FAILB(JOIN(txt('TypeError: missing argument '), item('FnPar', F('fu')))),
          STOPTHIS()
        ], [
          callProc('substr %s %s %s', [F('fdd'), num(3), lenOf(F('fdd'))]),
          setV('fval', VAR('ev')),
          setV('ftype', letterOf(num(2), F('fdd'))),
          callProc('assign %s %s %s', [item('FnPar', F('fu')), F('fval'), F('ftype')])
        ])
      ])
    ]),
    chgV('fj', num(1))
  ]);

  // NB replaceStmt only relinks ONE statement, so the prelude goes in first and the loop
  // replaces the old loop (its predecessor is then the prelude's tail)
  insertBeforeStmt(bindLoop[0], [setV('kwp', num(1))]);
  replaceStmt(bindLoop[0], newLoop);
  console.log('[P100] binding loop handles keyword arguments');

  // ---------- (e) UArgN has to travel with the frame.  A user call nested inside an argument
  // re-enters calluser, which clears UArgV/UArgT/UArgN; P14's fpush/fpop save the lists that
  // existed when P14 was written (UArgV/UArgT/UComma) but cannot know about UArgN, so it is
  // appended to both: the save goes at the end of fpush, the restore just before fpop drops
  // its list region.
  const fp = defIdOf('fpush');
  let fpLast = null, cur = BL()[fp].next;
  while (cur) { fpLast = cur; cur = BL()[cur].next; }
  spliceAfter(fpLast, chain([
    addTo('LSave', llen('UArgN')),
    setV('epI', num(1)),
    REPEATU(GT(F('epI'), llen('UArgN')), [addTo('LSave', item('UArgN', F('epI'))), chgV('epI', num(1))])
  ]));
  const fo = inDef('fpop');
  const dropLs = find(fo, (b) => b.opcode === 'control_repeat' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => {
      const q = BL()[id];
      return !!q && q.opcode === 'data_deleteoflist' && q.fields.LIST && q.fields.LIST[0] === 'LSave';
    }));
  if (dropLs.length !== 1) throw new Error('[P100] fpop list cleanup = ' + dropLs.length);
  insertBeforeStmt(dropLs[0], [
    setV('epN', item('LSave', F('epI'))),
    chgV('epI', num(1)),
    clearL('UArgN'),
    setV('epJ', num(1)),
    REPEATU(GT(F('epJ'), F('epN')), [addTo('UArgN', item('LSave', F('epI'))), chgV('epI', num(1)), chgV('epJ', num(1))])
  ]);
  console.log('[P100] UArgN is saved/restored with the frame');
});

// ---- P101: sorted(x, reverse=True) (E27) ----
//
// `sorted` lives in callfn (P13), but a call with a top-level comma never gets there: it has
// `narg == 1`, so eval's single-argument fast path does not fire and (like `zip`) the name is
// not "callable" -- the call died with `NameError: name sorted is not defined`.
//
// So the two-argument form is handled by a `sorted` hook in eval, before the narg dispatch:
// `hascomma` finds the top-level comma (`tqcpz`), the piece before it is the list (sorted with
// the existing `lsort`, which returns the result in ev/evtype), the piece after it must be
// `reverse=<value>` -- the value is evaluated and passed through `truth`, so `True`, `1` and
// `0` all behave.  Only `reverse=` is accepted; anything else is reported as an unexpected
// keyword argument.  The reversal itself is a small new `lrev` procedure (listitem decodes,
// lesc re-encodes, walk the indices backwards).
patch('P101 sorted reverse', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['sri', 'srn', 'sra', 'srtl', 'srtv', 'srtt']) if (taken.has(n)) throw new Error('[P101] variable name taken: ' + n);
  for (const v of ['sri', 'srn', 'sra', 'srtl', 'srtv', 'srtt']) newVar(v, 0);
  const S = () => argOf('s');

  // ---------- lrev s : the encoded list, backwards, in ev/evtype
  const lr = newProc('lrev %s', ['s']);
  attachBody(lr.defId, [
    callProc('listlen %s', [S()]),
    setV('srn', VAR('ev')),
    setV('sra', txt('')),
    setV('sri', VAR('srn')),
    REPEATU(LT(VAR('sri'), num(1)), [
      callProc('listitem %s %s', [S(), VAR('sri')]),
      callProc('lesc %s', [VAR('ev')]),
      setV('sra', JOIN(JOIN(JOIN(VAR('sra'), VAR('lsep')), VAR('evtype')), VAR('ev'))),
      chgV('sri', num(-1))
    ]),
    setV('ev', VAR('sra')),
    setV('evtype', txt('L'))
  ]);
  console.log('[P101] lrev registered');

  // ---------- eval: the sorted(x, reverse=...) hook
  const ev2 = inDef('eval %s %s');
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const nargIf = find(ev2, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return (vn(q.inputs.OPERAND1) === 'narg' && litOf(q.inputs.OPERAND2) === '0') || (vn(q.inputs.OPERAND2) === 'narg' && litOf(q.inputs.OPERAND1) === '0');
    })());
  if (nargIf.length !== 1) throw new Error('[P101] eval narg dispatch = ' + nargIf.length);
  const bale = () => [chgV('fnlimit', num(-1)), STOPTHIS()];
  insertBeforeStmt(nargIf[0], [
    IF(EQ(item('Tok', argOf('lo')), txt('sorted')), [
      callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IF(EQ(VAR('tqhcm'), num(1)), [
        IF(NOT(AND(EQ(item('Tok', ADD(VAR('tqcpz'), num(1))), txt('reverse')), EQ(item('Tok', ADD(VAR('tqcpz'), num(2))), txt('=')))), [
          FAILB(JOIN(txt('TypeError: sorted() got an unexpected keyword argument '), item('Tok', ADD(VAR('tqcpz'), num(1))))),
          ...bale()
        ]),
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('tqcpz'), num(1))]),
        IF(EQ(VAR('error'), txt('')), [
          IF(NOT(EQ(VAR('evtype'), txt('L'))), [
            FAIL(txt('TypeError: sorted() requires a list')),
            ...bale()
          ]),
          callProc('lsort %s', [VAR('ev')]),
          setV('srtl', VAR('ev')),
          callProc('eval %s %s', [ADD(VAR('tqcpz'), num(3)), SUB(argOf('hi'), num(1))]),
          IF(EQ(VAR('error'), txt('')), [
            setV('srtv', VAR('ev')),
            setV('srtt', VAR('evtype')),
            callProc('truth %s %s', [VAR('srtv'), VAR('srtt')]),
            IFELSE(EQ(VAR('truthv'), num(1)), [
              callProc('lrev %s', [VAR('srtl')])
            ], [
              setV('ev', VAR('srtl')),
              setV('evtype', txt('L'))
            ])
          ])
        ]),
        ...bale()
      ])
    ])
  ]);
  console.log('[P101] eval: sorted(x, reverse=...) hook installed');
});

// ---- P102: the unpacking branch must not share its LoopName reporter ----
//
// P89 replaced `boundary`'s plain `assign(LoopName[lc], ev, evtype)` with
//     if LoopStep[lc] == 0 -> unpackto(LoopName[lc], ev)   else -> assign(LoopName[lc], ev, evtype)
// and handed the SAME `item N of LoopName` reporter block to both branches.  One Scratch block
// may have only one parent (the rule that cost P95 a build), and the VM really does return a
// stale value for the second user of a shared reporter: measured with a three-case suite
// (`for a, b in zip(...)`, a dict loop, then `for i, x in enumerate(...)`), the second
// iteration of the last loop called `unpackto` with `names = a,b` -- the names of the *first*
// case's loop -- while the element itself (`(1, 'b')`) was correct, so the loop variables kept
// their first-iteration values and the body printed them twice.
//
// Fix: give the else-branch (the plain assign) its own copy of the reporter.
patch('P102 unpack name reporter', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const listItemOf = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return (b && b.opcode === 'data_itemoflist' && b.fields.LIST) ? b.fields.LIST[0] : null;
  };
  const bd = inDef('boundary');
  const bindIf = find(bd, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_equals') return false;
      return listItemOf(q.inputs.OPERAND1) === 'LoopStep' && litOf(q.inputs.OPERAND2) === '0';
    }));
  if (bindIf.length !== 1) throw new Error('[P102] boundary bind branch = ' + bindIf.length);
  const ifNode = BL()[bindIf[0]];
  const branchHeads = ['SUBSTACK', 'SUBSTACK2'].map((k) => {
    const s = ifNode.inputs[k];
    return (s && typeof s[1] === 'string') ? s[1] : null;
  });
  if (!branchHeads[0] || !branchHeads[1]) throw new Error('[P102] bind branch substacks missing');
  // every call in the two branches whose first argument reads LoopName
  const nameArg = (callId) => {
    const b = BL()[callId];
    const ids = JSON.parse(b.mutation.argumentids);
    const d = b.inputs[ids[0]];
    return listItemOf(d) === 'LoopName' ? { key: ids[0], id: d[1] } : null;
  };
  const calls = (root) => [...reach(root)].filter((id) => {
    const q = BL()[id];
    return q && q.opcode === 'procedures_call' && q.mutation && /^(unpackto|assign) %s/.test(q.mutation.proccode);
  });
  const used = new Map();
  for (const root of branchHeads) {
    for (const callId of calls(root)) {
      const a = nameArg(callId);
      if (!a) continue;
      if (!used.has(a.id)) used.set(a.id, []);
      used.get(a.id).push({ callId, key: a.key });
    }
  }
  let fixed = 0;
  for (const [blockId, users] of used) {
    if (users.length < 2) continue;
    // keep the first user, clone for the rest
    for (const u of users.slice(1)) {
      BL()[u.callId].inputs[u.key] = [3, cloneExpr(blockId), [4, '0']];
      fixed++;
    }
  }
  if (!fixed) throw new Error('[P102] no shared LoopName reporter found');
  console.log('[P102] unpack/assign branches use separate LoopName reporters (' + fixed + ')');
});

// ---- P103: `from math import name` (E51) ----
//
// `import math` registers the module in `mthname`/`hasmath` and P23 dispatches `math.f(x)`
// inside `methodcall`; a call written as a bare name (`from math import sqrt` ... `sqrt(16.0)`)
// died at the unsupported-statement guard.  This patch keeps a list `MFrom` of the imported
// function names and answers those calls in eval, right before the argument-count dispatch:
// the single argument is evaluated, the name picks the `operator_mathop`, and the result is
// formatted like CPython's -- `floor`/`ceil`/`trunc` give an int, everything else always
// carries a decimal point (`sqrt(16.0)` and `sqrt(4)` are both `4.0` / `2.0`).
// The constants `pi`/`e` are imported as plain values (P87 already answers `math.pi`).
patch('P103 from math import', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const MATHOP = (op, x) => I('operator_mathop', { fields: { OPERATOR: [op, null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const BALE = () => [chgV('fnlimit', num(-1)), STOPTHIS()];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['mfk', 'mft', 'mff']) if (taken.has(n)) throw new Error('[P103] variable name taken: ' + n);
  for (const v of ['mfk', 'mft', 'mff']) newVar(v, 0);
  B.addList(IT, 'MFrom', []);
  const lit = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);

  // ---------- (a) execute: accept `from math import a, b` (+ pi / e as values)
  const ex = inDef('execute');
  const pendingIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return vn(q.inputs.OPERAND1) === 'pending' && lit(q.inputs.OPERAND2) === '0';
    })());
  if (pendingIf.length !== 1) throw new Error('[P103] execute pending guard = ' + pendingIf.length);
  const importName = (k) => IF(NOT(EQ(item('Tok', VAR(k)), txt(','))), [
    IFELSE(EQ(item('Tok', VAR(k)), txt('pi')),
      [callProc('assign %s %s %s', [txt('pi'), txt('3.141592653589793'), txt('N')])],
      [IFELSE(EQ(item('Tok', VAR(k)), txt('e')),
        [callProc('assign %s %s %s', [txt('e'), txt('2.718281828459045'), txt('N')])],
        [addTo('MFrom', item('Tok', VAR(k)))])])
  ]);
  insertBeforeStmt(pendingIf[0], [
    IF(EQ(VAR('head'), txt('from')), [
      IF(NOT(EQ(item('Tok', num(2)), txt('math'))), [
        FAILB(JOIN(txt('ImportError: no module named '), item('Tok', num(2)))),
        STOPTHIS()
      ]),
      IF(NOT(EQ(item('Tok', num(3)), txt('import'))), [
        FAIL(txt('SyntaxError: from <module> import <name>')),
        STOPTHIS()
      ]),
      setV('hasmath', num(1)),
      setV('mfk', num(4)),
      REPEATU(GT(VAR('mfk'), VAR('count')), [importName('mfk'), chgV('mfk', num(1))]),
      setV('pending', num(1))
    ])
  ]);
  console.log('[P103] execute: from math import ... accepted');

  // ---------- (b) the run start clears the import list
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P103] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [clearL('MFrom')]);
  console.log('[P103] MFrom is cleared at run start');

  // ---------- (c) eval: a bare imported math name
  const FLOATFNS = [['sqrt', 'sqrt'], ['fabs', 'abs'], ['exp', 'e ^'], ['log', 'ln'], ['log10', 'log'],
    ['sin', 'sin'], ['cos', 'cos'], ['tan', 'tan']];
  const INTFNS = [['floor', 'floor'], ['ceil', 'ceiling']];
  let chainIds = IF(OR(EQ(item('Tok', argOf('lo')), txt('pow')), EQ(item('Tok', argOf('lo')), txt('fmod'))),
    [FAIL(txt('TypeError: this math function needs two arguments'))],
    [FAILB(JOIN(txt('AttributeError: math has no '), item('Tok', argOf('lo'))))]);
  for (let i = INTFNS.length - 1; i >= 0; i--) {
    const [name, op] = INTFNS[i];
    chainIds = IFELSE(EQ(item('Tok', argOf('lo')), txt(name)), [setV('ev', MATHOP(op, VAR('mft')))], [chainIds]);
  }
  for (let i = FLOATFNS.length - 1; i >= 0; i--) {
    const [name, op] = FLOATFNS[i];
    const body = (name === 'sqrt')
      ? [IF(LT(VAR('mft'), num(0)), [FAIL(txt('ValueError: math domain error')), ...BALE()]),
        setV('ev', MATHOP('sqrt', VAR('mft'))), setV('mff', num(1))]
      : [setV('ev', MATHOP(op, VAR('mft'))), setV('mff', num(1))];
    chainIds = IFELSE(EQ(item('Tok', argOf('lo')), txt(name)), body, [chainIds]);
  }
  chainIds = IFELSE(EQ(item('Tok', argOf('lo')), txt('trunc')),
    [IFELSE(LT(VAR('mft'), num(0)), [setV('ev', MATHOP('ceiling', VAR('mft')))], [setV('ev', MATHOP('floor', VAR('mft')))])],
    [chainIds]);
  const ev2 = inDef('eval %s %s');
  const nargIf = find(ev2, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return (vn(q.inputs.OPERAND1) === 'narg' && lit(q.inputs.OPERAND2) === '0') || (vn(q.inputs.OPERAND2) === 'narg' && lit(q.inputs.OPERAND1) === '0');
    })());
  if (nargIf.length !== 1) throw new Error('[P103] eval narg dispatch = ' + nargIf.length);
  insertBeforeStmt(nargIf[0], [
    IF(I('data_listcontainsitem', { fields: B.LISTF('MFrom'), inputs: { ITEM: B.REP(item('Tok', argOf('lo')), [10, '']) } }), [
      callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IF(EQ(VAR('error'), txt('')), [
        IF(NOT(EQ(VAR('evtype'), txt('N'))), [FAIL(txt('TypeError: math requires a number')), ...BALE()]),
        setV('mft', VAR('ev')),
        setV('mff', num(0)),
        chainIds,
        setV('evtype', txt('N')),
        IF(EQ(VAR('mff'), num(1)), [callProc('mkfloat %s', [VAR('ev')])])
      ]),
      ...BALE()
    ])
  ]);
  console.log('[P103] eval: bare math names dispatched');
});

// ---- P104: the global statement (E32) ----
//
// `global n` was rejected by the unsupported-statement guard.  The interpreter's frame model
// keeps the caller's variable table in FN/FV/FT and *rebuilds* it on return, which is why a
// plain assignment inside a function cannot touch a global (`n = 2` in a function prints
// `2 1`).  So `global` only has to make that rebuild keep the new value:
//
//   * the statement records the name in GName;
//   * just before calluser rebuilds the caller's table, every declared name is captured once
//     (value + type + panel text) into GSave*;
//   * right after the rebuild those entries are written back into the restored table (or
//     appended when the name did not exist before the call, which is what CPython does).
//
// GName is deliberately NOT per-frame: a global name must survive *every* enclosing frame's
// rebuild, which is what makes `outer()` calling `inner()` twice work (with a per-frame list
// the intermediate frame's restore would drop the change again).  Reading a global inside a
// function already worked (lookup sees the caller's entries).
// Caveat (documented): because the name list is global, a *local* assignment to a name that
// some other function declared `global` also survives its frame -- a corner CPython gets
// right and this model does not.  GName/GSave* are cleared at run start.
patch('P104 global statement', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const setAt = (list, idx, val) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(val, [4, '0']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['gik', 'gij', 'gfound']) if (taken.has(n)) throw new Error('[P104] variable name taken: ' + n);
  for (const v of ['gik', 'gij', 'gfound']) newVar(v, 0);
  for (const l of ['GName', 'GSaveN', 'GSaveV', 'GSaveT', 'GSaveS']) B.addList(IT, l, []);
  const lit = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);

  // ---------- (a) execute: record the declared names
  const ex = inDef('execute');
  const pendingIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return vn(q.inputs.OPERAND1) === 'pending' && lit(q.inputs.OPERAND2) === '0';
    })());
  if (pendingIf.length !== 1) throw new Error('[P104] execute pending guard = ' + pendingIf.length);
  insertBeforeStmt(pendingIf[0], [
    IF(EQ(VAR('head'), txt('global')), [
      setV('gik', num(2)),
      REPEATU(GT(VAR('gik'), VAR('count')), [
        IF(NOT(EQ(item('Tok', VAR('gik')), txt(','))), [
          addTo('GName', item('Tok', VAR('gik')))
        ]),
        chgV('gik', num(1))
      ]),
      setV('pending', num(1))
    ])
  ]);
  console.log('[P104] execute: global statements are recorded');

  // ---------- (b) calluser: capture before the table rebuild
  const cu = inDef('calluser %s %s %s');
  const clearNames = find(cu, (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'Names');
  if (clearNames.length !== 1) throw new Error('[P104] calluser Names clear = ' + clearNames.length);
  const hasShow = find(cu, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'FSV');
  insertBeforeStmt(clearNames[0], [
    clearL('GSaveN'), clearL('GSaveV'), clearL('GSaveT'), clearL('GSaveS'),
    setV('gik', num(1)),
    REPEATU(GT(VAR('gik'), llen('GName')), [
      callProc('lookup %s', [item('GName', VAR('gik'))]),
      IF(GT(VAR('found'), num(0)), [
        IF(NOT(I('data_listcontainsitem', { fields: B.LISTF('GSaveN'), inputs: { ITEM: B.REP(item('GName', VAR('gik')), [10, '']) } })), [
          addTo('GSaveN', item('GName', VAR('gik'))),
          addTo('GSaveV', item('Values', VAR('found'))),
          addTo('GSaveT', item('Types', VAR('found'))),
          IFELSE(GT(llen('Show'), llen('GSaveS')), [addTo('GSaveS', item('Show', llen('GSaveS')))], [addTo('GSaveS', txt(''))])
        ])
      ]),
      chgV('gik', num(1))
    ])
  ]);
  console.log('[P104] calluser captures global values (' + hasShow.length + ' FSV anchors)');

  // ---------- (c) calluser: write them back after the rebuild
  const rebuild = find(cu, (b) => b.opcode === 'control_repeat_until' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => {
      const q = BL()[id];
      return !!q && q.opcode === 'data_addtolist' && q.fields.LIST && q.fields.LIST[0] === 'Names';
    }));
  if (rebuild.length !== 1) throw new Error('[P104] calluser table rebuild = ' + rebuild.length);
  spliceAfter(rebuild[0], chain([
    setV('gij', num(1)),
    REPEATU(GT(VAR('gij'), llen('GSaveN')), [
      callProc('lookup %s', [item('GSaveN', VAR('gij'))]),
      IFELSE(GT(VAR('found'), num(0)), [
        setAt('Values', VAR('found'), item('GSaveV', VAR('gij'))),
        setAt('Types', VAR('found'), item('GSaveT', VAR('gij'))),
        IF(GT(llen('Show'), num(0)), [
          IF(NOT(GT(VAR('found'), llen('Show'))), [setAt('Show', VAR('found'), item('GSaveS', VAR('gij')))])
        ])
      ], [
        // a name that did not exist before the call becomes a fresh global entry
        addTo('Names', item('GSaveN', VAR('gij'))),
        addTo('Values', item('GSaveV', VAR('gij'))),
        addTo('Types', item('GSaveT', VAR('gij'))),
        IF(GT(llen('Show'), num(0)), [addTo('Show', item('GSaveS', VAR('gij')))])
      ]),
      chgV('gij', num(1))
    ])
  ]));
  console.log('[P104] calluser writes global values back');

  // ---------- (d) run start clears everything
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P104] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [
    clearL('GName'), clearL('GSaveN'), clearL('GSaveV'), clearL('GSaveT'), clearL('GSaveS')
  ]);
  console.log('[P104] global tables are cleared at run start');
});

// ---- P105: *args and **kwargs (E28/E29) ----
//
// `regdef` splits the parameter list on top-level commas and stores `Tok[fplo]` as the name,
// so `def f(*a)` recorded a parameter literally called `*`; `f(1, 2, 3)` then died at the
// "too many arguments" guard and `f(a=1)` at "unexpected keyword argument".
//
// This patch teaches both ends about the star forms:
//   * regdef stores the parameter as `*name` / `**name` (the marker plus its own name);
//   * calluser scans FnPar once per call for a marker (`fhas`) and, when there is one, skips
//     the "too many arguments" and "unexpected keyword argument" guards -- the leftover
//     pieces belong to the star parameter;
//   * the binding loop binds the star parameter first: `*a` becomes an 'L' list of every
//     still-unconsumed positional argument, `**k` an 'D' dict of every still-unconsumed
//     keyword argument (`lsep + keytype + keyesc + lsep + valtype + valesc` for each pair,
//     exactly the encoding dictlit builds), and both mark those pieces consumed so a later
//     `**k` sees only what is left.  The loop then simply continues, which is what makes
//     `def f(*a, **k)` work.
patch('P105 star arguments', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const replaceItem = (list, idx, val) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(val, [4, '0']) } });
  const F = (v) => VAR(v); // fresh reporters every use
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fhas', 'fsk', 'fpm', 'fname2', 'fsacc']) if (taken.has(n)) throw new Error('[P105] variable name taken: ' + n);
  for (const v of ['fhas', 'fsk', 'fpm', 'fname2', 'fsacc']) newVar(v, 0);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);

  // ---------- (a) regdef: keep the star marker in the parameter name
  const rd = inDef('regdef %s');
  const parAdd = find(rd, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'DefPar');
  if (parAdd.length !== 1) throw new Error('[P105] DefPar append = ' + parAdd.length);
  replaceStmt(parAdd[0], IFELSE(
    OR(EQ(item('Tok', F('fplo')), txt('*')), EQ(item('Tok', F('fplo')), txt('**'))),
    [addTo('DefPar', JOIN(item('Tok', F('fplo')), item('Tok', ADD(F('fplo'), num(1)))))],
    [addTo('DefPar', item('Tok', F('fplo')))]
  ));
  console.log('[P105] regdef keeps *name / **name');

  // ---------- (b) calluser: is there a star parameter?  (first, so the guards can use it)
  const cu = inDef('calluser %s %s %s');
  const posCount = find(cu, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_gt') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return vn(q.inputs.OPERAND1) === 'kwnpos' && vn(q.inputs.OPERAND2) === 'fpn';
    }));
  if (posCount.length !== 1) throw new Error('[P105] positional count check = ' + posCount.length);
  insertBeforeStmt(posCount[0], [
    setV('fhas', num(0)),
    setV('fsk', num(1)),
    REPEATU(GT(F('fsk'), F('fpn')), [
      setV('fpm', item('FnPar', ADD(F('fpo'), SUB(F('fsk'), num(1))))),
      IF(EQ(letterOf(num(1), F('fpm')), txt('*')), [setV('fhas', num(1))]),
      chgV('fsk', num(1))
    ])
  ]);
  replaceExpr(BL()[posCount[0]].inputs.CONDITION[1], () => AND(BL()[posCount[0]].inputs.CONDITION[1], EQ(F('fhas'), num(0))));
  // the "unexpected keyword argument" failure is skipped as well (the leftovers go to **k)
  const kwFail = find(cu, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && (() => {
      // the failure must be the FIRST statement of the guard (an outer chain would match too)
      const q = BL()[b.inputs.SUBSTACK[1]];
      if (!q || q.opcode !== 'procedures_call' || !q.mutation || q.mutation.proccode !== 'fail %s') return false;
      const d = q.inputs[JSON.parse(q.mutation.argumentids)[0]];
      const j = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      return !!j && j.opcode === 'operator_join' && litOf(j.inputs.STRING1) === 'TypeError: unexpected keyword argument ';
    })());
  if (kwFail.length !== 1) throw new Error('[P105] unexpected-keyword guard = ' + kwFail.length);
  const kwCond = BL()[kwFail[0]].inputs.CONDITION[1];
  replaceExpr(kwCond, () => AND(kwCond, EQ(F('fhas'), num(0))));
  console.log('[P105] the star parameter disables both argument guards');

  // ---------- (c) calluser: bind the star parameter inside the binding loop
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const bindLoop = find(cu, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_gt') return false;
      return vnOf(q.inputs.OPERAND1) === 'fj' && vnOf(q.inputs.OPERAND2) === 'fpn';
    }));
  if (bindLoop.length !== 1) throw new Error('[P105] binding loop = ' + bindLoop.length);
  const bodyHead = BL()[bindLoop[0]].inputs.SUBSTACK[1];
  const afterFu = BL()[bodyHead].next;                 // the original body, minus `fu = ...`
  if (!afterFu) throw new Error('[P105] binding loop body is empty');
  // find the loop's increment (`change fj by 1`) and truncate the chain right before it
  const incs = find(reach(bodyHead), (b) => b.opcode === 'data_changevariableby' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'fj'
    && b.inputs.VALUE && litOf(b.inputs.VALUE) === '1');
  if (incs.length < 1) throw new Error('[P105] binding loop increment = ' + incs.length);
  const inc = incs.find((id) => !BL()[id].next) || incs[incs.length - 1];
  const pred = (() => { for (const id of reach(bodyHead)) if (BL()[id].next === inc) return id; return null; })();
  if (!pred) throw new Error('[P105] cannot find the statement before the loop increment');
  BL()[pred].next = null;
  const fpmSet = setV('fpm', item('FnPar', F('fu')));
  const starIf = IFELSE(EQ(letterOf(num(1), F('fpm')), txt('*')), [
      // the bound name is the marker's tail
      IFELSE(EQ(letterOf(num(2), F('fpm')), txt('*')),
        [callProc('substr %s %s %s', [F('fpm'), num(3), lenOf(F('fpm'))])],
        [callProc('substr %s %s %s', [F('fpm'), num(2), lenOf(F('fpm'))])]),
      setV('fname2', VAR('ev')),
      IFELSE(EQ(letterOf(num(2), F('fpm')), txt('*')), [
        // **k : dict of the remaining keyword arguments
        setV('fsacc', txt('')),
        setV('fsk', num(1)),
        REPEATU(GT(F('fsk'), llen('UArgN')), [
          IF(AND(NOT(EQ(item('UArgN', F('fsk')), txt(''))), NOT(EQ(item('UArgN', F('fsk')), txt('#')))), [
            callProc('lesc %s', [item('UArgN', F('fsk'))]),
            setV('fsacc', JOIN(VAR('fsacc'), VAR('lsep'))),
            setV('fsacc', JOIN(VAR('fsacc'), txt('S'))),
            setV('fsacc', JOIN(VAR('fsacc'), VAR('ev'))),
            callProc('lesc %s', [item('UArgV', F('fsk'))]),
            setV('fsacc', JOIN(VAR('fsacc'), VAR('lsep'))),
            setV('fsacc', JOIN(VAR('fsacc'), item('UArgT', F('fsk')))),
            setV('fsacc', JOIN(VAR('fsacc'), VAR('ev'))),
            replaceItem('UArgN', F('fsk'), txt('#'))
          ]),
          chgV('fsk', num(1))
        ]),
        callProc('assign %s %s %s', [F('fname2'), VAR('fsacc'), txt('D')])
      ], [
        // *a : list of the remaining positional arguments
        setV('fsacc', txt('')),
        setV('fsk', num(1)),
        REPEATU(GT(F('fsk'), llen('UArgN')), [
          IF(EQ(item('UArgN', F('fsk')), txt('')), [
            callProc('lesc %s', [item('UArgV', F('fsk'))]),
            setV('fsacc', JOIN(VAR('fsacc'), VAR('lsep'))),
            setV('fsacc', JOIN(VAR('fsacc'), item('UArgT', F('fsk')))),
            setV('fsacc', JOIN(VAR('fsacc'), VAR('ev'))),
            replaceItem('UArgN', F('fsk'), txt('#'))
          ]),
          chgV('fsk', num(1))
        ]),
        callProc('assign %s %s %s', [F('fname2'), VAR('fsacc'), txt('L')])
      ])
  ], [
    afterFu                        // the plain-parameter body, already chained
  ]);
  // rebuild the loop body: fu = ... ; fpm = FnPar[fu] ; star-or-plain ; fj += 1
  BL()[bodyHead].next = fpmSet;
  BL()[fpmSet].parent = bodyHead;
  BL()[fpmSet].next = starIf;
  BL()[starIf].parent = fpmSet;
  BL()[starIf].next = inc;
  BL()[inc].parent = starIf;
  console.log('[P105] the binding loop understands star parameters');
});

// ---- P106: inheritance -- `class B(A)` (E46) ----
//
// The class handler demanded `Tok[3] == ':'`, so `class B(A):` died with
// `SyntaxError: class Name:`.  This patch accepts the parenthesised form and copies the
// parent's methods into the child *before* the class body is scanned, which is the order that
// makes overriding work: `calluser` looks a method up from the END of FnName, so the child's
// own definition (registered later) wins while every method the child does not define is
// found in the copied block.
//
// The method tables are parallel lists, so one copied entry means one append to each of
// FnName/FnPN/FnPO/FnPar/FnDef/FnStart/FnEnd/FnKind/FnLine/FnTlo/FnThi -- the body of an
// inherited method is simply the parent's line range.
//
// Not covered (documented): inheritance of class attributes (`class A: n = 1` + `class B(A)`)
// and `super()`.
patch('P106 inheritance', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['cpk', 'cpn', 'cpn2', 'cpp', 'cpm', 'cpar', 'cpfound']) if (taken.has(n)) throw new Error('[P106] variable name taken: ' + n);
  for (const v of ['cpk', 'cpn', 'cpn2', 'cpp', 'cpm', 'cpar', 'cpfound']) newVar(v, 0);

  const ex = inDef('execute');
  // the class branch: `if head == "class"`
  const classIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_equals') return false;
      const vn = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1] : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      return vn(q.inputs.OPERAND1) === 'head' && litOf(q.inputs.OPERAND2) === 'class';
    }));
  if (classIf.length !== 1) throw new Error('[P106] class branch = ' + classIf.length);
  const head = BL()[classIf[0]].inputs.SUBSTACK[1];
  const clsAdd = find(reach(head), (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'ClsName');
  if (clsAdd.length !== 1) throw new Error('[P106] ClsName append = ' + clsAdd.length);
  const shapeIf = find(reach(head), (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_equals') return false;
      const itemTok = (d, lit) => {
        const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
        if (!bb || bb.opcode !== 'data_itemoflist' || !bb.fields.LIST || bb.fields.LIST[0] !== 'Tok') return false;
        return litOf(bb.inputs.INDEX) === lit;
      };
      const litChk = (d, ch) => litOf(d) === ch;
      return (itemTok(q.inputs.OPERAND1, '3') && litChk(q.inputs.OPERAND2, ':')) || (itemTok(q.inputs.OPERAND2, '3') && litChk(q.inputs.OPERAND1, ':'));
    }));
  if (shapeIf.length !== 1) throw new Error('[P106] class shape guard = ' + shapeIf.length);
  // ---------- (a) accept `class Name(Parent):`
  {
    const condId = BL()[shapeIf[0]].inputs.CONDITION[1];
    const inner = find(reach(condId), (b) => b.opcode === 'operator_equals'
      && ((Array.isArray(b.inputs.OPERAND1) && b.inputs.OPERAND1[1] === undefined) ? false : true));
    // the guard is NOT(equals(...)) -- rebuild it as NOT(OR(old, Name(Parent): shape))
    const parShape = AND(EQ(item('Tok', num(3)), txt('(')),
      AND(EQ(item('Tok', num(5)), txt(')')), EQ(item('Tok', num(6)), txt(':'))));
    const notNode = BL()[condId];
    if (!notNode || notNode.opcode !== 'operator_not' || typeof notNode.inputs.OPERAND[1] !== 'string') {
      throw new Error('[P106] class shape guard is not a NOT');
    }
    const oldEq = notNode.inputs.OPERAND[1];
    replaceExpr(oldEq, () => OR(oldEq, parShape));
  }
  console.log('[P106] class Name(Parent): accepted');

  // ---------- (b) copy the parent's methods (before the body scan, so overrides win)
  insertBeforeStmt(clsAdd[0], [
    IF(EQ(item('Tok', num(3)), txt('(')), [
      setV('cpar', item('Tok', num(4))),
      // the parent must already be a known class (compareText is case sensitive)
      setV('cpfound', num(0)),
      setV('cpk', num(1)),
      REPEATU(GT(VAR('cpk'), llen('ClsName')), [
        callProc('compareText %s %s', [item('ClsName', VAR('cpk')), VAR('cpar')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('cpfound', num(1)), setV('cpk', llen('ClsName'))]),
        chgV('cpk', num(1))
      ]),
      IF(EQ(VAR('cpfound'), num(0)), [
        FAILB(JOIN(txt('NameError: name '), VAR('cpar'))),
        STOPTHIS()
      ]),
      setV('cpn2', llen('FnName')),
      setV('cpk', num(1)),
      REPEATU(GT(VAR('cpk'), VAR('cpn2')), [
        setV('cpn', item('FnName', VAR('cpk'))),
        IF(GT(lenOf(VAR('cpn')), ADD(lenOf(VAR('cpar')), num(1))), [
          callProc('substr %s %s %s', [VAR('cpn'), num(1), lenOf(VAR('cpar'))]),
          setV('cpp', VAR('ev')),
          IF(AND(EQ(VAR('cpp'), VAR('cpar')), EQ(letterOf(ADD(lenOf(VAR('cpar')), num(1)), VAR('cpn')), txt('.'))), [
            callProc('substr %s %s %s', [VAR('cpn'), ADD(lenOf(VAR('cpar')), num(2)), lenOf(VAR('cpn'))]),
            setV('cpm', VAR('ev')),
            addTo('FnName', JOIN(JOIN(VAR('ccls'), txt('.')), VAR('cpm'))),
            addTo('FnPN', item('FnPN', VAR('cpk'))),
            addTo('FnPO', item('FnPO', VAR('cpk'))),
            addTo('FnPar', item('FnPar', VAR('cpk'))),
            addTo('FnDef', item('FnDef', VAR('cpk'))),
            addTo('FnStart', item('FnStart', VAR('cpk'))),
            addTo('FnEnd', item('FnEnd', VAR('cpk'))),
            addTo('FnKind', item('FnKind', VAR('cpk'))),
            addTo('FnLine', item('FnLine', VAR('cpk'))),
            addTo('FnTlo', item('FnTlo', VAR('cpk'))),
            addTo('FnThi', item('FnThi', VAR('cpk')))
          ])
        ]),
        chgV('cpk', num(1))
      ])
    ])
  ]);
  console.log('[P106] inherited methods are copied into the child class');
});

// ---- P107: try / finally (gap E49) ----
//
// `finally` was already half-known: P51 added it to the Elses chain (so `Elses[try]` points at
// the `finally:` line) and execute() already lists it among the statement heads it refuses to
// evaluate -- but not among the heads that open a block, so `print('fin')` after `finally:`
// died with "IndentationError: unexpected indent" in prepare().
//
// This patch makes try/finally behave:
//   * prepare(): `finally` joins if/else/while/for/elif/def/try/except in the two prevhead
//     chains (they are the "this line opens a block" test and its "expected block" twin);
//   * execute(): a `finally:` line is a no-op statement (it only marks where the tail starts);
//   * the `try` branch pushes a *separate* frame (FinStart/FinEnd/FinMsg/FinC) when its clause
//     is `finally` instead of a handler frame.  Nothing may "catch" there, so the try body runs
//     unprotected and errors stay in `error` -- which is what lets the hook below see them;
//   * a hook appended to trycatch() (which both drivers call after every execute) runs the tail:
//       - an error is passing by  -> remember it in FinMsg, clear it and jump to FinStart, so
//         the tail runs and the hook's next pass re-raises;
//       - the tail has been passed -> pop the frame and re-raise a remembered error.
//   * entries belonging to frames that already returned (FinC > cdepth) are dropped, mirroring
//     how trycatch() discards handler frames from deeper frames.
//
// Not covered (documented): `return`/`break` inside a try with a finally, and the finally of a
// `try/except/finally` when an exception escapes the handler.
patch('P107 try finally', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const last = (list) => item(list, llen(list));
  const replaceLast = (list, val) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(llen(list), [4, '0']), ITEM: B.REP(val, [4, '0']) } });
  const tokAt = (i) => item('Tok', i);
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['tiskind', 'tfm']) if (taken.has(n)) throw new Error('[P107] variable name taken: ' + n);
  for (const v of ['tiskind', 'tfm']) newVar(v, 0);
  for (const l of ['FinStart', 'FinEnd', 'FinMsg', 'FinC']) B.addList(IT, l, []);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);

  // ---------- (a) prepare(): `finally` opens a block
  const prep = inDef('prepare');
  const isPrevEq = (id, lit) => {
    const b = BL()[id];
    if (!b || b.opcode !== 'operator_equals') return false;
    return (vnOf(b.inputs.OPERAND1) === 'prevhead' && litOf(b.inputs.OPERAND2) === lit)
        || (vnOf(b.inputs.OPERAND2) === 'prevhead' && litOf(b.inputs.OPERAND1) === lit);
  };
  // only the *inner* head chain: the enclosing "unexpected indent" condition wraps it in
  // not(...) as well, and patching that one would make every `finally:` line fail outright
  const notFree = (id) => ![...reach(id)].some((x) => BL()[x].opcode === 'operator_not');
  const cand = find(prep, (b, id) => b.opcode === 'operator_or' && notFree(id) && [...reach(id)].some((x) => isPrevEq(x, 'try')));
  const outer = cand.filter((id) => !cand.some((o) => o !== id && reach(o).has(id)));
  if (outer.length !== 4) throw new Error('[P107] prevhead chains = ' + outer.length + ' (expected 4)');
  for (const id of outer) replaceExpr(id, () => OR(id, EQ(F('prevhead'), txt('finally'))));
  console.log('[P107] prepare: finally is a block head (' + outer.length + ' chains)');

  // ---------- (b) execute(): a `finally:` line is a no-op statement
  const ex = inDef('execute');
  const tryBranch = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_equals') return false;
      return (vnOf(q.inputs.OPERAND1) === 'head' && litOf(q.inputs.OPERAND2) === 'try')
          || (vnOf(q.inputs.OPERAND2) === 'head' && litOf(q.inputs.OPERAND1) === 'try');
    }));
  if (tryBranch.length !== 1) throw new Error('[P107] execute try branch = ' + tryBranch.length);
  insertBeforeStmt(tryBranch[0], [IF(EQ(F('head'), txt('finally')), [setV('pending', num(1))])]);
  console.log('[P107] execute: finally line accepted');

  // ---------- (c) the try branch pushes a finally frame instead of a handler frame
  const inner = find(reach(tryBranch[0]), (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const q = BL()[b.inputs.CONDITION[1]];
    if (!q || q.opcode !== 'operator_not') return false;
    return [...reach(q.inputs.OPERAND[1])].some((id) => {
      const z = BL()[id];
      if (!z || z.opcode !== 'operator_equals') return false;
      return (vnOf(z.inputs.OPERAND1) === 'tpc' && litOf(z.inputs.OPERAND2) === '0')
          || (vnOf(z.inputs.OPERAND2) === 'tpc' && litOf(z.inputs.OPERAND1) === '0');
    });
  });
  if (inner.length !== 1) throw new Error('[P107] tpc != 0 guard = ' + inner.length);
  const a1 = find(reach(inner[0]), (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'TryHand')[0];
  if (!a1) throw new Error('[P107] TryHand append not found');
  const a5 = (() => { let id = a1; for (let i = 0; i < 4; i++) id = BL()[id].next; return id; })();
  if (!a5 || BL()[a5].fields.LIST[0] !== 'TryC') throw new Error('[P107] TryC append not found');
  const after = BL()[a5].next;
  if (!after) throw new Error('[P107] nothing follows the frame pushes');
  const pred = (() => { for (const id of reach(inner[0])) if (BL()[id].next === a1) return id; return null; })();
  if (!pred) throw new Error('[P107] cannot find the statement before the frame pushes');
  BL()[a5].next = null;
  const fork = I('control_if_else', { inputs: { CONDITION: B.BOOL(EQ(tokAt(num(1)), txt('finally'))) } });
  B.sub(IT, fork, 'SUBSTACK', chain([
    addTo('FinStart', ADD(F('tpc'), num(1))),
    addTo('FinEnd', item('Ends', F('tpc'))),
    addTo('FinMsg', txt('')),
    addTo('FinC', F('cdepth'))
  ]));
  B.sub(IT, fork, 'SUBSTACK2', a1);
  BL()[pred].next = fork; BL()[fork].parent = pred;
  BL()[fork].next = after; BL()[after].parent = fork;
  console.log('[P107] try with a finally clause pushes a tail frame');

  // ---------- (d) the tail driver, PREPENDED to trycatch (called after every execute)
  //
  // It has to run *before* trycatch's own error walk: an error that has to pass through a
  // finally must get its tail run first, and once the tail is done the restored error must be
  // visible to that same walk so an outer handler can still catch it.
  const tcId = defIdOf('trycatch');
  const tcFirst = BL()[tcId].next;
  if (!tcFirst) throw new Error('[P107] trycatch has no body');
  const drop = () => [delLast('FinStart'), delLast('FinEnd'), delLast('FinMsg'), delLast('FinC')];
  const reRaise = IF(NOT(EQ(F('tfm'), txt(''))), [setV('error', F('tfm'))]);
  const tailDone = [setV('tfm', last('FinMsg')), ...drop(), reRaise];
  const errArm = IF(NOT(EQ(F('error'), txt(''))), [
    IFELSE(EQ(last('FinMsg'), txt('')), [
      // an error is passing by: run the tail first, remember the error
      replaceLast('FinMsg', F('error')),
      setV('error', txt('')),
      setV('pc', last('FinStart'))
    ], [
      // an error raised inside the tail replaces the original one
      ...drop()
    ])
  ]);
  const passed = IFELSE(NOT(LT(F('pc'), last('FinEnd'))), tailDone, [errArm]);
  const watch = IF(GT(llen('FinEnd'), num(0)), [passed]);
  // entries whose function frame already returned can never run their tail
  const sweep = REPEATU(OR(EQ(llen('FinEnd'), num(0)), NOT(GT(last('FinC'), F('cdepth')))), [...drop()]);
  insertBeforeStmt(tcFirst, [sweep, watch]);
  console.log('[P107] tail driver hooked onto trycatch');

  // ---------- (e) clear the tail stack at the start of every run
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'LoopText');
  if (runInit.length !== 1) throw new Error('[P107] run init anchor = ' + runInit.length);
  insertBeforeStmt(runInit[0], [clearL('FinStart'), clearL('FinEnd'), clearL('FinMsg'), clearL('FinC')]);
  console.log('[P107] try/finally ready');
});

// ---- P108: dict comprehensions -- {k: v for x in xs} (gap E43) ----
//
// `{ ... }` is a dict literal (P33) and a top-level `for` inside it was never looked at, so
// `{k: k * 2 for k in range(3)}` went to dictlit and died evaluating the bare name `k`.
//
// complist already knows how to walk the iterable and to append the body to `cacc`, and a dict
// is encoded exactly like the accumulator it builds (a flat run of `lsep + type + text`, key and
// value alternating -- that is what dictpair/dictlit produce).  So this patch clones complist
// into `complistD` and changes only two things:
//   * a scan finds the first depth-0 `:` of the body, and the accumulation appends the key part
//     and the value part as two pieces instead of the whole body as one;
//   * the result is tagged 'D' instead of 'L'.
// The clone keeps the original procedure untouched, so `[...]` comprehensions are unaffected.
patch('P108 dict comprehension', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const tokAt = (x) => item('Tok', x);
  const kindAt = (x) => item('Kind', x);
  const enc = (acc, tv, vv) => JOIN(JOIN(JOIN(acc, VAR('lsep')), tv), vv);
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['dcsub', 'dcdep', 'dck', 'dcfor']) if (taken.has(n)) throw new Error('[P108] variable name taken: ' + n);
  for (const v of ['dcsub', 'dcdep', 'dck', 'dcfor']) newVar(v, 0);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const isCtrl = (b) => b.opcode === 'control_if' || b.opcode === 'control_if_else';
  const condBlock = (b) => (b.inputs && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string') ? BL()[b.inputs.CONDITION[1]] : null;
  const eqVar = (b, name, lit) => !!b && b.opcode === 'operator_equals'
    && ((vnOf(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit)
     || (vnOf(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit));
  // a depth-0 keyword test on Tok that also insists the token is an identifier, so the string
  // literal 'for' inside a dict is not mistaken for a comprehension
  const kwAt = (v, word, i) => AND(EQ(kindAt(i), txt('I')), EQ(tokAt(i), txt(word)));
  const depthStep = (v, onOpen, onClose) => [
    IF(OR(EQ(tokAt(v), txt('(')), OR(EQ(tokAt(v), txt('[')), EQ(tokAt(v), txt('{')))), [chgV(onOpen, num(1))]),
    IF(OR(EQ(tokAt(v), txt(')')), OR(EQ(tokAt(v), txt(']')), EQ(tokAt(v), txt('}')))), [chgV(onClose, num(-1))])
  ];

  // ---------- (a) clone complist into complistD
  const cloneBody = (fromDefId, toDefId) => {
    const map = {};
    let count = 0;
    const copyBlock = (id) => {
      if (map[id]) return map[id];
      const src = BL()[id];
      const nid = B.nid('dc');
      map[id] = nid;
      const b = {
        opcode: src.opcode, next: null, parent: null, inputs: {},
        fields: JSON.parse(JSON.stringify(src.fields || {})),
        shadow: !!src.shadow, topLevel: false
      };
      if (src.mutation) b.mutation = JSON.parse(JSON.stringify(src.mutation));
      BL()[nid] = b;
      count++;
      for (const [k, v] of Object.entries(src.inputs || {})) {
        const nv = JSON.parse(JSON.stringify(v));
        if (typeof nv[1] === 'string') nv[1] = copyBlock(nv[1]);
        b.inputs[k] = nv;
      }
      if (src.next) {
        const nx = copyBlock(src.next);
        b.next = nx;
        BL()[nx].parent = nid;
      }
      return nid;
    };
    const first = copyBlock(BL()[fromDefId].next);
    BL()[toDefId].next = first;
    BL()[first].parent = toDefId;
    return count;
  };
  const srcDef = defIdOf('complist %s %s');
  const dp = newProc('complistD %s %s', ['lo', 'hi']);
  const cloned = cloneBody(srcDef, dp.defId);
  const set = inDef('complistD %s %s');
  console.log('[P108] complist cloned (' + cloned + ' blocks)');

  // ---------- (b) split the body at the first depth-0 colon
  const ciloSet = find(set, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'cilo');
  if (ciloSet.length !== 1) throw new Error('[P108] cilo set = ' + ciloSet.length);
  spliceAfter(ciloSet[0], chain([
    setV('dcsub', num(0)), setV('dcdep', num(0)), setV('dck', argOf('lo')),
    REPEATU(GT(F('dck'), SUB(F('cfor'), num(1))), [
      ...depthStep(F('dck'), 'dcdep', 'dcdep'),
      IF(AND(EQ(F('dcdep'), num(0)), AND(EQ(tokAt(F('dck')), txt(':')), EQ(F('dcsub'), num(0)))), [setV('dcsub', F('dck'))]),
      chgV('dck', num(1))
    ])
  ]));

  // ---------- (c) accumulate key and value as two pieces
  const accIf = find(set, (b) => isCtrl(b) && (() => { const cb = condBlock(b); return eqVar(cb, 'cok', '1'); })());
  // three of them: the range path plus the list and the string iterable paths
  if (accIf.length !== 3) throw new Error('[P108] accumulation guards = ' + accIf.length);
  // P34 inserted `lesc(ev)` in front of every statement that embeds an evaluated value into a
  // container; those statements are new, so the escape has to be added here as well -- without
  // it a container value (nested list/dict/tuple) is spliced in with raw separators.
  const one = () => [callProc('lesc %s', [VAR('ev')]), setV('cacc', enc(VAR('cacc'), VAR('evtype'), VAR('ev')))];
  // P98 wraps every eval in complist with csave/crestore; the two evals this patch adds need
  // the same treatment or a nested comprehension inside a key/value clobbers the outer loop
  const ev2 = (a, b) => [callProc('csave'), callProc('eval %s %s', [a, b]), callProc('crestore')];
  for (const id of accIf) B.sub(IT, id, 'SUBSTACK', chain([
    IFELSE(EQ(F('dcsub'), num(0)), [
      ...ev2(argOf('lo'), SUB(F('cfor'), num(1))),
      ...one()
    ], [
      ...ev2(argOf('lo'), SUB(F('dcsub'), num(1))),
      ...one(),
      ...ev2(ADD(F('dcsub'), num(1)), SUB(F('cfor'), num(1))),
      ...one()
    ])
  ]));

  // ---------- (c2) the save set has to know the new scratch variables
  {
    const sv = defIdOf('csave');
    let t = sv;
    while (BL()[t].next) t = BL()[t].next;
    const MINE = ['dcsub', 'dcdep', 'dck', 'dcfor'];
    spliceAfter(t, chain(MINE.map((v) => addTo('VStack', VAR(v)))));
    const rs = defIdOf('crestore');
    const rsFirst = BL()[rs].next;
    if (!rsFirst) throw new Error('[P108] crestore has no body');
    insertBeforeStmt(rsFirst, [...MINE].reverse().flatMap((v) => [setV(v, item('VStack', llen('VStack'))), delLast('VStack')]));
    console.log('[P108] csave/crestore extended with the dict-comprehension scratch');
  }

  // ---------- (d) the clone answers with a dict
  const typeSet = find(set, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'evtype'
    && litOf(b.inputs.VALUE) === 'L');
  if (typeSet.length !== 1) throw new Error('[P108] evtype set = ' + typeSet.length);
  replaceStmt(typeSet[0], setV('evtype', txt('D')));
  console.log('[P108] complistD builds a dict');

  // ---------- (e) eval: `{ ... }` with a top-level `for` is a dict comprehension
  const ev = inDef('eval %s %s');
  const isTokArg = (d, name) => {
    const tb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    if (!tb || tb.opcode !== 'data_itemoflist' || tb.fields.LIST[0] !== 'Tok') return false;
    const ib = (tb.inputs.INDEX && typeof tb.inputs.INDEX[1] === 'string') ? BL()[tb.inputs.INDEX[1]] : null;
    return !!ib && ib.opcode === 'argument_reporter_string_number' && ib.fields.VALUE[0] === name;
  };
  const dictIf = find(ev, (b) => isCtrl(b) && (() => {
    const cb = condBlock(b);
    if (!cb || cb.opcode !== 'operator_and' || typeof b.inputs.CONDITION[1] !== 'string') return false;
    let open = false, close = false;
    for (const x of reach(b.inputs.CONDITION[1])) {
      const q = BL()[x];
      if (!q || q.opcode !== 'operator_equals') continue;
      const a = q.inputs.OPERAND1, c = q.inputs.OPERAND2;
      if ((isTokArg(a, 'lo') && litOf(c) === '{') || (isTokArg(c, 'lo') && litOf(a) === '{')) open = true;
      if ((isTokArg(a, 'hi') && litOf(c) === '}') || (isTokArg(c, 'hi') && litOf(a) === '}')) close = true;
    }
    return open && close;
  })());
  if (dictIf.length !== 1) throw new Error('[P108] eval dict branch = ' + dictIf.length);
  const dictCall = find(reach(dictIf[0]), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'dictlit %s %s');
  if (dictCall.length !== 1) throw new Error('[P108] dictlit call = ' + dictCall.length);
  insertBeforeStmt(dictCall[0], [
    setV('dcfor', num(0)), setV('dcdep', num(0)), setV('dck', ADD(argOf('lo'), num(1))),
    REPEATU(GT(F('dck'), SUB(argOf('hi'), num(1))), [
      ...depthStep(F('dck'), 'dcdep', 'dcdep'),
      IF(AND(EQ(F('dcdep'), num(0)), AND(kwAt(null, 'for', F('dck')), EQ(F('dcfor'), num(0)))), [setV('dcfor', F('dck'))]),
      chgV('dck', num(1))
    ]),
    IF(GT(F('dcfor'), num(0)), [
      callProc('complistD %s %s', [ADD(argOf('lo'), num(1)), SUB(argOf('hi'), num(1))]),
      STOPTHIS()
    ])
  ]);
  console.log('[P108] eval routes {k: v for ...} to complistD');
});

// ---- P109: dictfmt was not re-entrant, so a dict inside a dict printed garbage ----
//
// `print({'x': {'a': 1}})` produced `{'a': 1, 'a': {'a': 1}}` on v4.44 -- the dict itself was
// correct (len/items/`d['x']['a']` all agreed), only the rendering was wrong: dictfmt renders
// each element with `reprval`, and reprval on a nested dict calls dictfmt again, which then
// overwrites the *outer* call's accumulator and cursor (d1acc/d1n/d1i/d1k/d1v).  The outer loop
// resumes with the inner call's state and emits the inner text twice.
//
// Same class of bug as P46 (listlit) and P98 (complist): save the scratch set around the
// recursive call.  The rendered text travels in ev/evtype, which is deliberately not saved.
patch('P109 dictfmt reentrant', () => {
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const V = ['d1acc', 'd1n', 'd1i', 'd1k', 'd1v'];
  const push = () => V.map((v) => addTo('VStack', VAR(v)));
  const pop = () => [...V].reverse().flatMap((v) => [setV(v, item('VStack', llen('VStack'))), delLast('VStack')]);
  const df = inDef('dictfmt %s');
  const calls = find(df, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'reprval %s %s');
  if (calls.length !== 2) throw new Error('[P109] dictfmt reprval calls = ' + calls.length);
  for (const id of calls) {
    insertBeforeStmt(id, push());
    spliceAfter(id, chain(pop()));
  }
  console.log('[P109] dictfmt saves its scratch around both reprval calls');
});

// ---- P110: a dict lookup by an integer key could match a *value* record ----
//
// A dict is a flat run of element records: key at odd positions, value at even ones.  The
// lookup in indexget scanned every record and compared the text, so
// `d = {0: 0, 1: 2, 2: 4}; print(d[2])` matched the record holding the *value* 2 (the value of
// key 1, position 4) and then returned the record after it -- printing 2 instead of 4.  It only
// shows up when a value happens to equal the key being looked up, which is why string keys never
// hit it.  Restricting the scan to the odd (key) positions fixes it; dictkeys already relies on
// the same convention.
patch('P110 dict key lookup', () => {
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const ig = inDef('indexget %s %s');
  const matches = find(ig, (b) => {
    if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') return false;
    if (!b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const q = BL()[b.inputs.CONDITION[1]];
    if (!q || q.opcode !== 'operator_equals') return false;
    return (vnOf(q.inputs.OPERAND1) === 'evtype' && vnOf(q.inputs.OPERAND2) === 'dgkt')
        || (vnOf(q.inputs.OPERAND2) === 'evtype' && vnOf(q.inputs.OPERAND1) === 'dgkt');
  });
  if (matches.length !== 2) throw new Error('[P110] dict key compare sites = ' + matches.length);
  for (const id of matches) {
    const cond = BL()[id].inputs.CONDITION[1];
    replaceExpr(cond, () => AND(cond, EQ(MOD(VAR('dgi'), num(2)), num(1))));
  }
  console.log('[P110] dict lookup only compares key records (' + matches.length + ' sites)');
});

// ---- P111: set literals {1, 2, 3} and set comprehensions {x for x in xs} (gap E44) ----
//
// `{` ... `}` was always a dict: dictpair then failed with "expected colon in dictionary".
// A set is stored exactly like a list (a flat run of `lsep + type + escaped element`), only the
// type tag differs, so the literal needs no new machinery: hand the token range to `listlit` and
// tag the result 'E'.  A top-level `for` without a colon is a *set* comprehension, which is the
// same call (complist accumulates one element per iteration).  A colon means a dict -- a dict
// literal, or with a `for` the P108 dict comprehension.
//
// What does have to be new is the rest of the type's surface:
//   * setnorm -- {1, 1, 2} is {1, 2}: rebuild the run dropping elements already seen;
//   * setfmt  -- render as {a, b, c}, re-entrant (reprval re-enters for container elements);
//   * strval  -- an 'E' branch in front of the 'D' one.
// `len(s)` / `x in s` / `for x in s` are NOT part of this patch (documented).
patch('P111 sets', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['spiece', 'sacc', 'setn', 'seti', 'seacc', 'sen', 'sei', 'sev']) if (taken.has(n)) throw new Error('[P111] variable name taken: ' + n);
  for (const v of ['spiece', 'sacc', 'setn', 'seti', 'seacc', 'sen', 'sei', 'sev']) newVar(v, 0);
  for (const l of ['SSeen']) B.addList(IT, l, []);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const argName = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return (b && b.opcode === 'argument_reporter_string_number') ? b.fields.VALUE[0] : null;
  };
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const pushVars = (names) => names.map((n) => addTo('VStack', VAR(n)));
  const popVars = (names) => [...names].reverse().flatMap((n) => [setV(n, item('VStack', llen('VStack'))), delLast('VStack')]);

  // ---------- (a) setnorm s: drop repeated elements, answer with an 'E' value
  const sn = newProc('setnorm %s', ['s']);
  attachBody(sn.defId, [
    clearL('SSeen'),
    setV('sacc', txt('')),
    callProc('listlen %s', [argOf('s')]),
    setV('setn', VAR('ev')),
    setV('seti', num(1)),
    REPEATU(GT(F('seti'), F('setn')), [
      ...pushVars(['sacc', 'setn', 'seti']),
      callProc('listitem %s %s', [argOf('s'), F('seti')]),
      callProc('lesc %s', [VAR('ev')]),
      setV('spiece', JOIN(JOIN(VAR('lsep'), VAR('evtype')), VAR('ev'))),
      ...popVars(['sacc', 'setn', 'seti']),
      IF(NOT(I('data_listcontainsitem', { fields: B.LISTF('SSeen'), inputs: { ITEM: B.REP(F('spiece'), [10, '']) } })), [
        addTo('SSeen', F('spiece')),
        setV('sacc', JOIN(VAR('sacc'), F('spiece')))
      ]),
      chgV('seti', num(1))
    ]),
    setV('ev', VAR('sacc')), setV('evtype', txt('E'))
  ]);
  console.log('[P111] setnorm installed');

  // ---------- (b) setfmt s: render {a, b, c}
  const sf = newProc('setfmt %s', ['s']);
  attachBody(sf.defId, [
    setV('seacc', txt('{')),
    callProc('listlen %s', [argOf('s')]),
    setV('sen', VAR('ev')),
    setV('sei', num(1)),
    REPEATU(GT(VAR('sei'), VAR('sen')), [
      ...pushVars(['seacc', 'sen', 'sei']),
      callProc('listitem %s %s', [argOf('s'), VAR('sei')]),
      callProc('reprval %s %s', [VAR('ev'), VAR('evtype')]),
      setV('sev', VAR('ev')),
      ...popVars(['seacc', 'sen', 'sei']),
      IF(GT(VAR('sei'), num(1)), [setV('seacc', JOIN(VAR('seacc'), txt(', ')))]),
      setV('seacc', JOIN(VAR('seacc'), VAR('sev'))),
      chgV('sei', num(1))
    ]),
    setV('ev', JOIN(VAR('seacc'), txt('}'))), setV('evtype', txt('S'))
  ]);
  console.log('[P111] setfmt installed');

  // ---------- (c) strval: an 'E' branch in front of the 'D' one
  const sv = inDef('strval %s %s');
  const dIf = find(sv, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      return q && q.opcode === 'operator_equals'
        && ((argName(q.inputs.OPERAND1) === 'vt' && litOf(q.inputs.OPERAND2) === 'D')
         || (argName(q.inputs.OPERAND2) === 'vt' && litOf(q.inputs.OPERAND1) === 'D'));
    }));
  if (dIf.length !== 1) throw new Error('[P111] strval D branch = ' + dIf.length);
  replaceStmt(dIf[0], IFELSE(EQ(argOf('vt'), txt('E')), [callProc('setfmt %s', [argOf('vv')])], [dIf[0]]));
  console.log('[P111] strval handles E');

  // ---------- (d) eval: a `{` without a top-level colon is a set
  const ev = inDef('eval %s %s');
  const initSet = find(ev, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'dcfor'
    && litOf(b.inputs.VALUE) === '0');
  if (initSet.length !== 1) throw new Error('[P111] dispatch init = ' + initSet.length);
  spliceAfter(initSet[0], chain([setV('dcsub', num(0))]));
  const forIf = find(ev, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      return q && q.opcode === 'operator_equals' && vnOf(q.inputs.OPERAND1) === 'dcfor' && litOf(q.inputs.OPERAND2) === '0';
    }));
  if (forIf.length !== 1) throw new Error('[P111] dispatch for-test = ' + forIf.length);
  insertBeforeStmt(forIf[0], [
    IF(AND(EQ(F('dcdep'), num(0)), AND(EQ(item('Tok', F('dck')), txt(':')), EQ(F('dcsub'), num(0)))), [setV('dcsub', F('dck'))])
  ]);
  const runIf = find(ev, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_gt'
    && vnOf(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1) === 'dcfor');
  if (runIf.length !== 1) throw new Error('[P111] dispatch run-if = ' + runIf.length);
  // one reporter block per use: a block may have only one parent
  const L = () => argOf('lo'), H = () => argOf('hi');
  const setBranch = IF(AND(EQ(F('dcsub'), num(0)), GT(SUB(H(), L()), num(1))), [
    callProc('listlit %s %s', [ADD(L(), num(1)), SUB(H(), num(1))]),
    callProc('setnorm %s', [VAR('ev')]),
    STOPTHIS()
  ]);
  // `for` + colon   -> dict comprehension (P108)
  // `for`, no colon -> set comprehension: the plain comprehension plus the E tag
  // colon only      -> a dict literal, so fall through to dictlit
  // neither         -> a set literal (an empty pair of braces is still a dict)
  replaceStmt(runIf[0], IFELSE(AND(GT(F('dcfor'), num(0)), NOT(EQ(F('dcsub'), num(0)))),
    [callProc('complistD %s %s', [ADD(L(), num(1)), SUB(H(), num(1))]), STOPTHIS()],
    [setBranch]));
  console.log('[P111] eval routes {a, b} and {x for x in xs} to a set');
});

// ---- P112: `except X as e` binds the exception (pre-existing gap) ----
//
// `try: ... except ValueError as e: print(e)` printed `NameError: e` on v4.44/v4.45: the walk in
// trycatch jumps straight to `TryHand` (the clause line + 1), so the `except ... as e:` line is
// never executed and the name was never bound anywhere.  `tlast` already carries the error text
// (it is what a bare `raise` re-raises), so binding it is a local change: tokenize the clause
// line, take the token right after `as`, strip the "Name: " prefix and assign the remainder as a
// string.  CPython's str(e) is the message without the class name, and for a bare
// `ZeroDivisionError` it is the empty string -- both fall out of "text after the first colon, or
// empty when there is none".
//
// The clause line is `TryHand - 1` (TryHand is pushed as `clause + 1`).  Tok has to be put back
// afterwards, exactly like the `try` branch does after its own tokenize.
patch('P112 except as', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const lenTok = () => I('data_lengthoflist', { fields: B.LISTF('Tok') });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['asln', 'asnm', 'asi', 'asmsg', 'ascp']) if (taken.has(n)) throw new Error('[P112] variable name taken: ' + n);
  for (const v of ['asln', 'asnm', 'asi', 'asmsg', 'ascp']) newVar(v, 0);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);

  const tc = inDef('trycatch');
  // the "a handler matched" branch: if tcl == 1
  const hit = find(tc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      return q && q.opcode === 'operator_equals' && vnOf(q.inputs.OPERAND1) === 'tcl' && litOf(q.inputs.OPERAND2) === '1';
    }));
  if (hit.length !== 1) throw new Error('[P112] trycatch hit branch = ' + hit.length);
  const save = find(reach(hit[0]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'tlast'
    && vnOf(b.inputs.VALUE) === 'error');
  if (save.length !== 1) throw new Error('[P112] tlast save = ' + save.length);
  // the statement that clears `error` -- tokenize() stops as soon as error is set, so the
  // clause line can only be read after this point
  const clearErr = BL()[save[0]].next;
  if (!clearErr || BL()[clearErr].opcode !== 'data_setvariableto' || litOf(BL()[clearErr].inputs.VALUE) !== '') {
    throw new Error('[P112] error-clear statement not found');
  }

  spliceAfter(clearErr, chain([
    // the clause line sits just above the handler body
    setV('asln', SUB(item('TryHand', llen('TryHand')), num(1))),
    callProc('tokenize %s', [item('Code', F('asln'))]),
    setV('asnm', txt('')),
    IF(GT(lenTok(), num(2)), [
      setV('asi', num(2)),
      REPEATU(GT(F('asi'), lenTok()), [
        IF(EQ(tokAt(F('asi')), txt('as')), [setV('asnm', tokAt(ADD(F('asi'), num(1))))]),
        chgV('asi', num(1))
      ])
    ]),
    // put the failing line's tokens back before anything else reads Tok
    callProc('tokenize %s', [item('Code', F('pc'))]),
    IF(NOT(EQ(F('asnm'), txt(''))), [
      // message = the text after the first ':' ('' when the error is just a class name)
      setV('asmsg', txt('')),
      setV('ascp', num(0)),
      setV('asi', num(1)),
      REPEATU(GT(F('asi'), lenOf(F('tlast'))), [
        IF(EQ(letterOf(F('asi'), F('tlast')), txt(':')), [IF(EQ(F('ascp'), num(0)), [setV('ascp', F('asi'))])]),
        chgV('asi', num(1))
      ]),
      IF(AND(NOT(EQ(F('ascp'), num(0))), NOT(GT(ADD(F('ascp'), num(1)), lenOf(F('tlast'))))), [
        callProc('substr %s %s %s', [F('tlast'), ADD(F('ascp'), num(2)), lenOf(F('tlast'))]),
        setV('asmsg', VAR('ev'))
      ]),
      callProc('assign %s %s %s', [F('asnm'), F('asmsg'), txt('S')])
    ])
  ]));
  console.log('[P112] except ... as name is bound from the clause line');
});

// ---- P113: a set answers len(), `in` and `for` ----
//
// v4.45 gave sets a literal, a comprehension and a repr, but every *operation* still saw an
// unknown type tag.  A set is encoded exactly like a list (a flat run of lsep + type + text), so
// none of these need a new algorithm -- only a way in:
//   * len(s)      -- the value computation gets an 'E' arm (plain record count, no halving);
//                   the "len requires string" guard has to admit 'E' as well;
//   * `x in s`    -- relabel the value as 'L' just before the existing list scan; the scan is
//                   the same walk, and evtype is scratch that eval resets every time;
//   * `for x in s`-- same relabel in front of forloop's L/T branch.
// Relabelling is safe because the tag is only ever read as "which accessor fits this encoding".
patch('P113 set facade', () => {
  const F = (v) => VAR(v);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const isVarEq = (b, name, lit) => !!b && b.opcode === 'operator_equals'
    && ((vnOf(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit)
     || (vnOf(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit));
  const asList = () => IF(EQ(F('evtype'), txt('E')), [setV('evtype', txt('L'))]);

  // ---------- (a) len(): the guard admits 'E'
  const cf = inDef('callfn %s %s %s');
  const notDS = find(cf, (b, id) => {
    if (b.opcode !== 'operator_not' || typeof b.inputs.OPERAND[1] !== 'string') return false;
    const inner = [...reach(b.inputs.OPERAND[1])].filter((x) => isVarEq(BL()[x], 'evtype', 'D') || isVarEq(BL()[x], 'evtype', 'S'));
    return inner.length === 2;
  });
  if (notDS.length !== 1) throw new Error('[P113] len guard = ' + notDS.length);
  replaceExpr(notDS[0], () => NOT(OR(EQ(F('evtype'), txt('D')), OR(EQ(F('evtype'), txt('S')), EQ(F('evtype'), txt('E'))))));

  // ---------- (b) len(): a set counts its records
  const dLen = find(cf, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && isVarEq(BL()[b.inputs.CONDITION[1]], 'evtype', 'D')
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call' && BL()[x].mutation && BL()[x].mutation.proccode === 'listlen %s'));
  if (dLen.length !== 1) throw new Error('[P113] len dict branch = ' + dLen.length);
  replaceStmt(dLen[0], IFELSE(EQ(F('evtype'), txt('E')), [
    callProc('listlen %s', [F('ev')]),
    setV('ev', F('ev'))
  ], [dLen[0]]));
  console.log('[P113] len(set) installed');

  // ---------- (c) `x in s` and `for x in s`
  for (const proc of ['rightside %s %s %s %s %s', 'forloop']) {
    const set = inDef(proc);
    const dictKeys = find(set, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else')
      && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && isVarEq(BL()[b.inputs.CONDITION[1]], 'evtype', 'D')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call' && BL()[x].mutation && BL()[x].mutation.proccode === 'dictkeys %s'));
    if (dictKeys.length < 1) throw new Error('[P113] ' + proc + ' dict branch = 0');
    // the enclosing condition can reach the same call; keep the innermost site
    dictKeys.sort((a, b) => reach(BL()[a].inputs.SUBSTACK[1]).size - reach(BL()[b].inputs.SUBSTACK[1]).size);
    insertBeforeStmt(dictKeys[0], [asList()]);
    console.log('[P113] ' + proc + ' treats a set like a list');
  }
});

// ---- P114: the builtins that walk a container also accept a set ----
//
// `sum`, `sorted`, `list` and the one-argument `min`/`max` all gate on the same type set --
// `evtype in {L, T, G}` -- and then walk the value with listlen/listitem, which is exactly how a
// set is encoded.  So admitting 'E' to those four gates is enough; `sorted` additionally has to
// answer with a *list* (`sorted({3,1,2})` is `[1, 2, 3]` in CPython), so it re-tags its result.
// `len`'s own {L,T,G} gate is deliberately left alone: a set reaches the length through the
// branches P113 already installed.
patch('P114 set builtins', () => {
  const F = (v) => VAR(v);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const isVarEq = (b, name, lit) => !!b && b.opcode === 'operator_equals'
    && ((vnOf(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit)
     || (vnOf(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit));
  const cf = inDef('callfn %s %s %s');
  const cand = find(cf, (b, id) => b.opcode === 'operator_or'
    && [...reach(id)].some((x) => isVarEq(BL()[x], 'evtype', 'L'))
    && [...reach(id)].some((x) => isVarEq(BL()[x], 'evtype', 'G')));
  const outer = cand.filter((id) => !cand.some((o) => o !== id && reach(o).has(id)));
  const classify = (id) => {
    const p = outer.length && [...cf].find((x) => BL()[x] && (BL()[x].opcode === 'control_if' || BL()[x].opcode === 'control_if_else')
      && BL()[x].inputs.CONDITION && typeof BL()[x].inputs.CONDITION[1] === 'string' && reach(BL()[x].inputs.CONDITION[1]).has(id));
    if (!p) return { kind: '?' };
    const sub = BL()[p].inputs.SUBSTACK && BL()[p].inputs.SUBSTACK[1];
    if (typeof sub !== 'string') return { kind: '?' };
    const first = BL()[sub];
    if (first.opcode === 'data_setvariableto' && first.fields.VARIABLE[0] === 'evtype' && litOf(first.inputs.VALUE) === 'L' && !first.next) {
      return { kind: 'list' };
    }
    const failCall = find(reach(sub), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s')[0];
    if (!failCall) return { kind: '?' };
    const slot = JSON.parse(BL()[failCall].mutation.argumentids)[0];
    const lit = litOf(BL()[failCall].inputs[slot]);
    if (lit && lit.indexOf('sorted()') >= 0) return { kind: 'sorted' };
    if (lit && lit.indexOf('sum()') >= 0) return { kind: 'sum' };
    return { kind: 'minmax' };
  };
  const seen = {};
  for (const id of outer) {
    const k = classify(id).kind;
    if (k === '?') continue;
    if (seen[k]) throw new Error('[P114] duplicate ' + k);
    seen[k] = id;
  }
  for (const k of ['sorted', 'sum', 'minmax', 'list']) {
    if (!seen[k]) throw new Error('[P114] guard not found: ' + k);
    const id = seen[k];
    replaceExpr(id, () => OR(id, EQ(F('evtype'), txt('E'))));
  }
  // sorted() answers with a list
  const sortCall = find(cf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'lsort %s');
  if (sortCall.length !== 1) throw new Error('[P114] lsort call = ' + sortCall.length);
  spliceAfter(sortCall[0], chain([setV('evtype', txt('L'))]));

  // the two-argument hook `sorted(x, reverse=...)` has its own guard (P101 put it in eval):
  // its condition is exactly `not(evtype == 'L')`, so match on that shape
  const ev = inDef('eval %s %s');
  const notL = find(ev, (b) => b.opcode === 'operator_not' && typeof b.inputs.OPERAND[1] === 'string'
    && isVarEq(BL()[b.inputs.OPERAND[1]], 'evtype', 'L'));
  if (notL.length !== 1) throw new Error('[P114] sorted-reverse not = ' + notL.length);
  replaceExpr(notL[0], () => NOT(OR(EQ(F('evtype'), txt('L')), EQ(F('evtype'), txt('E')))));
  console.log('[P114] sum/sorted/list/min/max accept sets');
});

// ---- P115: `'a b'.split()` splits on runs of whitespace ----
//
// The string-method dispatcher defaults its first argument to the empty string, and ssplit's
// empty-separator arm was written as "split into characters" -- so `s.split()` and `s.split('')`
// both produced a character list, and `s.split('')` did not raise.  CPython: no argument means
// "split on runs of whitespace and drop the empty fields", while an explicit empty separator is
// a ValueError.  The two cases differ, so the dispatcher records whether an argument was
// supplied (`smarg`) and routes accordingly:
//   smarg == 0  -> ssplitw, a new whitespace splitter
//   smarg == 1  -> ssplit, and an empty separator raises ValueError
patch('P115 split whitespace', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['smarg', 'spwi', 'spwn', 'spfld']) if (taken.has(n)) throw new Error('[P115] variable name taken: ' + n);
  for (const v of ['smarg', 'spwi', 'spwn', 'spfld']) newVar(v, 0);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const argEq = (b, name, lit) => {
    const a = (b && b.inputs && b.inputs.OPERAND1 && typeof b.inputs.OPERAND1[1] === 'string') ? BL()[b.inputs.OPERAND1[1]] : null;
    const c = (b && b.inputs && b.inputs.OPERAND2 && typeof b.inputs.OPERAND2[1] === 'string') ? BL()[b.inputs.OPERAND2[1]] : null;
    if (!b || b.opcode !== 'operator_equals') return false;
    const nm = (x) => (x && x.opcode === 'argument_reporter_string_number') ? x.fields.VALUE[0] : null;
    return (nm(a) === name && litOf(b.inputs.OPERAND2) === lit) || (nm(c) === name && litOf(b.inputs.OPERAND1) === lit);
  };
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });

  // ---------- (a) the whitespace splitter
  const isWs = (i) => OR(EQ(letterOf(i, argOf('s')), txt(' ')),
    OR(EQ(letterOf(i, argOf('s')), txt('\t')),
      OR(EQ(letterOf(i, argOf('s')), txt('\n')), EQ(letterOf(i, argOf('s')), txt('\r')))));
  const wf = newProc('ssplitw %s', ['s']);
  attachBody(wf.defId, [
    setV('smacc', txt('')),
    setV('spwn', lenOf(argOf('s'))),
    setV('spwi', num(1)),
    REPEATU(GT(VAR('spwi'), VAR('spwn')), [
      IFELSE(isWs(VAR('spwi')), [
        chgV('spwi', num(1))
      ], [
        // one field: everything up to the next whitespace.  The cursor deliberately stays
        // advanced -- nothing in here re-enters eval, so there is nothing to protect it from.
        setV('spfld', txt('')),
        REPEATU(OR(GT(VAR('spwi'), VAR('spwn')), isWs(VAR('spwi'))), [
          setV('spfld', JOIN(VAR('spfld'), letterOf(VAR('spwi'), argOf('s')))),
          chgV('spwi', num(1))
        ]),
        callProc('lesc %s', [VAR('spfld')]),
        setV('smacc', JOIN(VAR('smacc'), JOIN(VAR('lsep'), JOIN(txt('S'), VAR('ev')))))
      ])
    ]),
    setV('ev', VAR('smacc')), setV('evtype', txt('L'))
  ]);
  console.log('[P115] ssplitw installed');

  // ---------- (b) the dispatcher records whether an argument was supplied
  const sma1Init = find(allIds(), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'sma1'
    && litOf(b.inputs.VALUE) === '' && BL()[b.next] && BL()[b.next].opcode === 'data_setvariableto'
    && BL()[b.next].fields.VARIABLE[0] === 'smt1');
  if (sma1Init.length !== 1) throw new Error('[P115] sma1 init = ' + sma1Init.length);
  insertBeforeStmt(sma1Init[0], [setV('smarg', num(0))]);
  // the guard that reads the argument range is the first control_if after the defaults
  let guard = BL()[sma1Init[0]].next;
  let hops = 0;
  while (guard && BL()[guard].opcode !== 'control_if' && hops++ < 40) guard = BL()[guard].next;
  if (!guard || BL()[guard].opcode !== 'control_if') throw new Error('[P115] argument guard not found');
  const gFirst = BL()[guard].inputs.SUBSTACK && BL()[guard].inputs.SUBSTACK[1];
  if (typeof gFirst !== 'string') throw new Error('[P115] argument guard has no body');
  insertBeforeStmt(gFirst, [setV('smarg', num(1))]);
  console.log('[P115] smarg records the presence of an argument');

  // ---------- (c) route the call: no argument -> whitespace split, '' -> ValueError
  const calls = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'ssplit %s %s');
  if (calls.length !== 1) throw new Error('[P115] ssplit call sites = ' + calls.length);
  const args = JSON.parse(BL()[calls[0]].mutation.argumentids);
  const rec = BL()[calls[0]].inputs[args[0]];
  const sep = BL()[calls[0]].inputs[args[1]];
  replaceStmt(calls[0], IFELSE(EQ(VAR('smarg'), num(0)), [
    callProc('ssplitw %s', [rec])
  ], [
    IFELSE(EQ(VAR('sma1'), txt('')), [
      FAIL(txt('ValueError: empty separator'))
    ], [
      callProc('ssplit %s %s', [rec, sep])
    ])
  ]));
  console.log('[P115] split()/split(\'\') routed');
});

// ---- P116: `yield a, b` yields a tuple ----
//
// P83 taught `eval` that a bare comma sequence is a tuple, but the yield statement does not go
// through that path: `yield i, i + 1` evaluated the whole token range `i , i + 1` as one
// expression and died with "TypeError: use str(number)".  Same treatment as P83, at the yield
// site: if the range has a top-level comma, build the tuple with tuplelit instead of eval.
patch('P116 yield tuple', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['ycm']) if (taken.has(n)) throw new Error('[P116] variable name taken: ' + n);
  newVar('ycm', 0);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const ex = inDef('execute');
  // scope to the yield branch first: other statements have a `count > 1` guard too
  const yieldBranch = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      return q && q.opcode === 'operator_equals' && vnOf(q.inputs.OPERAND1) === 'head' && litOf(q.inputs.OPERAND2) === 'yield';
    }));
  if (yieldBranch.length !== 1) throw new Error('[P116] yield statement branch = ' + yieldBranch.length);
  // NB: scope to the branch's *substack* -- reach() follows `next`, so starting from the branch
  // itself would also sweep in every later statement of execute (that is how the first version
  // found two guards, the second being some other statement's `count > 1`).
  const yieldBody = BL()[yieldBranch[0]].inputs.SUBSTACK && BL()[yieldBranch[0]].inputs.SUBSTACK[1];
  if (typeof yieldBody !== 'string') throw new Error('[P116] yield branch has no body');
  const yieldIf = find(reach(yieldBody), (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_gt'
    && vnOf(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1) === 'count'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call' && BL()[x].mutation && BL()[x].mutation.proccode === 'eval %s %s'));
  if (yieldIf.length !== 1) throw new Error('[P116] yield count branch = ' + yieldIf.length);
  const body = BL()[yieldIf[0]].inputs.SUBSTACK[1];
  const evalCall = find(reach(body), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s')[0];
  if (!evalCall) throw new Error('[P116] yield eval call not found');
  insertBeforeStmt(evalCall, [
    setV('ycm', num(0)),
    callProc('hascomma %s %s', [num(2), VAR('count')]),
    IF(EQ(VAR('tqhcm'), num(1)), [
      callProc('tuplelit %s %s', [num(2), VAR('count')]),
      setV('ycm', num(1))
    ])
  ]);
  replaceStmt(evalCall, IF(NOT(EQ(VAR('ycm'), num(1))), [evalCall]));
  console.log('[P116] yield with a bare comma yields a tuple');
});

// ---- P117: dict pop -- rebuild the record run, and leave the lookup cursor consistent ----
//
// P91's pop reused the get() lookup (which finds the *record index* of the key) and then patched
// the encoded string by scanning for separators.  Measured on v4.46 it is wrong in several ways:
//   d = {'a': 1, 'b': 2}; d.pop('a')   -> {}          (wiped the whole dict)
//   d = {'a': 1, 'b': 2}; d.pop('b')   -> unchanged   (deleted nothing)
//   d = {'a': 7}; d.pop('a')           -> 1           (returned the index, not the value)
//   d = {'a': 1}; d.pop('z')           -> 'a'         (no KeyError)
// Rebuilding the run from decoded records is both simpler and correct: walk the records with
// listitem (the same walk dictkeys uses), keep every record except the key and the value that
// follows it, re-escape each one, write it back and answer with the value that was removed.
//
// The lookup cursor (`dmn`, the record count) is refreshed for the following call as well: with
// the pop in place a later `d.get(k)` was reading the pre-pop count.
patch('P117 dict pop', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['popi', 'popn', 'popacc']) if (taken.has(n)) throw new Error('[P117] variable name taken: ' + n);
  for (const v of ['popi', 'popn', 'popacc']) newVar(v, 0);
  B.addList(IT, 'PopKeep', []);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const argName = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return (b && b.opcode === 'argument_reporter_string_number') ? b.fields.VALUE[0] : null;
  };
  const dm = inDef('dictmeth %s %s %s %s %s');
  const popIf = find(dm, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      return (argName(q.inputs.OPERAND1) === 'meth' && litOf(q.inputs.OPERAND2) === 'pop')
          || (argName(q.inputs.OPERAND2) === 'meth' && litOf(q.inputs.OPERAND1) === 'pop');
    })());
  if (popIf.length !== 1) throw new Error('[P117] pop branch = ' + popIf.length);
  const rec = argOf('rec'), nm = argOf('nm');
  const keep = () => IF(AND(NOT(EQ(VAR('popi'), VAR('dmf'))), NOT(EQ(VAR('popi'), ADD(VAR('dmf'), num(1))))), [
    callProc('listitem %s %s', [rec, VAR('popi')]),
    callProc('lesc %s', [VAR('ev')]),
    setV('popacc', JOIN(JOIN(VAR('lsep'), VAR('evtype')), VAR('ev'))),
    addTo('PopKeep', VAR('popacc'))
  ]);
  B.sub(IT, popIf[0], 'SUBSTACK', chain([
    setV('dmvt', VAR('evtype')),
    setV('dmv', VAR('ev')),
    clearL('PopKeep'),
    callProc('listlen %s', [rec]),
    setV('popn', VAR('ev')),
    setV('popi', num(1)),
    REPEATU(GT(VAR('popi'), VAR('popn')), [keep(), chgV('popi', num(1))]),
    setV('dmtup', txt('')),
    setV('popi', num(1)),
    REPEATU(GT(VAR('popi'), llen('PopKeep')), [
      setV('dmtup', JOIN(VAR('dmtup'), item('PopKeep', VAR('popi')))),
      chgV('popi', num(1))
    ]),
    callProc('assign %s %s %s', [nm, VAR('dmtup'), txt('D')]),
    // the run lost two records: keep the shared lookup cursor in step with what is stored now
    setV('dmn', SUB(VAR('popn'), num(2))),
    setV('dmf', num(0)),
    setV('ev', VAR('dmv')),
    setV('evtype', VAR('dmvt'))
  ]));
  console.log('[P117] dict pop rebuilds the record run');

  // a missing key is a KeyError, not a silently reused `ev`
  const getElse = find(dm, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      return (argName(q.inputs.OPERAND1) === 'meth' && litOf(q.inputs.OPERAND2) === 'get')
          || (argName(q.inputs.OPERAND2) === 'meth' && litOf(q.inputs.OPERAND1) === 'get');
    })());
  if (getElse.length !== 1) throw new Error('[P117] get branch = ' + getElse.length);
  insertBeforeStmt(getElse[0], [
    IF(EQ(argOf('meth'), txt('pop')), [
      FAILB(JOIN(txt("KeyError: '"), JOIN(VAR('dmk'), txt("'"))))
    ])
  ]);
  console.log('[P117] pop of a missing key raises KeyError');
});

// ---- P118: the "no such method" messages read like CPython's ----
//
// MiniPy said `AttributeError: list has no method nope` where CPython says
// `AttributeError: 'list' object has no attribute 'nope'`.  Three sites build this string with a
// text literal glued to the method name; rewrite each into CPython's shape (the method variable
// is reused verbatim, only the two literals around it change).
patch('P118 attribute error wording', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const kinds = [['str', "AttributeError: 'str' object has no attribute '"], ['list', "AttributeError: 'list' object has no attribute '"], ['dict', "AttributeError: 'dict' object has no attribute '"]];
  let done = 0;
  for (const [kind, prefix] of kinds) {
    const needle = 'AttributeError: ' + kind + ' has no method ';
    const joins = find(allIds(), (b) => b.opcode === 'operator_join' && litOf(b.inputs.STRING1) === needle);
    if (joins.length !== 1) throw new Error('[P118] ' + kind + ' join = ' + joins.length);
    const id = joins[0];
    const methOperand = JSON.parse(JSON.stringify(BL()[id].inputs.STRING2));
    replaceExpr(id, () => JOIN(JOIN(txt(prefix), methOperand), txt("'")));
    done++;
  }
  console.log('[P118] attribute error wording aligned (' + done + ' sites)');
});

// ---- P120: one argument-reporter block per use ----
//
// A Scratch argument reporter resolves its value through the *current* stack frame, and this
// project has repeatedly been bitten by reusing a single reporter block in several input slots
// (P95 and P102 were two instances, P115 a third).  P91's dict lookup is the clearest one:
// `listlen(rec)`, `listitem(rec, dmi)` and `listitem(rec, dmf + 1)` all pass the same
// `argument_reporter_string_number "rec"` block, and measured with a recorder the *shared* block
// returns the previous call's dict while a freshly built reporter for the same name returns the
// current one -- which is why `d.get(k)` answered about the wrong dictionary right after the
// dictionary changed (see _work/cmp47/t116a.json).
//
// The fix is mechanical: walk every input slot in the project, and wherever one block is used
// more than once, give the extra uses their own clone.  Reporters are pure, so a clone can only
// make the value more correct.
patch('P120 unique reporters', () => {
  // count how many input slots reference each block
  const uses = new Map();
  for (const id of allIds()) {
    const b = BL()[id];
    for (const [slot, v] of Object.entries(b.inputs || {})) {
      if (!v || typeof v[1] !== 'string') continue;
      if (!uses.has(v[1])) uses.set(v[1], []);
      uses.get(v[1]).push({ owner: id, slot, desc: v });
    }
  }
  let cloned = 0;
  let owners = 0;
  for (const [bid, list] of uses) {
    if (list.length < 2) continue;
    const b = BL()[bid];
    if (!b) continue;
    if (b.opcode !== 'argument_reporter_string_number' && b.opcode !== 'argument_reporter_boolean') continue;
    owners++;
    // first use keeps the original, the rest get clones
    for (let i = 1; i < list.length; i++) {
      const { owner, slot, desc } = list[i];
      const copy = cloneExpr(bid);
      BL()[owner].inputs[slot] = desc.length > 2 ? [desc[0], copy, desc[2]] : [desc[0], copy];
      BL()[copy].parent = owner;
      cloned++;
    }
  }
  console.log('[P120] shared argument reporters: ' + owners + ' blocks, ' + cloned + ' clones added');
});

// ---- P121: float literals with an exponent -- accuracy and validation ----
//
// Two independent defects behind `print(1e-5)` and `print(1e21)`:
//
//  * numlit computed `mantissa * 10**exp` with Scratch's `10 ^` operator, i.e. Math.pow(10,exp).
//    That is not the correctly rounded double for negative exponents -- Math.pow(10,-4) is
//    0.00009999999999999999, while CPython's 1e-4 is 0.0001.  Dividing by the *positive* power
//    (1 / 10**4) is correctly rounded, and 10**k is exact for k <= 22, so both ranges now agree
//    with CPython.
//  * numbercheck accepted only digits, one dot and a leading sign, so any literal whose value
//    needs scientific notation (1e21, 1e300, 1.5e-7) was rejected with "invalid number" even
//    though the tokenizer had read the token correctly.  It now also accepts one `e`/`E` with an
//    optional sign and at least one digit after it.
patch('P121 float literals', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['esgn', 'edig', 'epw', 'nee', 'nesg']) if (taken.has(n)) throw new Error('[P121] variable name taken: ' + n);
  for (const v of ['esgn', 'edig', 'epw', 'nee', 'nesg']) newVar(v, 0);
  const pow10 = (x) => I('operator_mathop', { fields: { OPERATOR: ['10 ^', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const inSet = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const chAt = (i, s) => I('operator_letter_of', { inputs: { LETTER: B.REP(i, [4, '0']), STRING: B.REP(s, [10, '']) } });
  const F = (v) => VAR(v);

  // ---------- (a) numlit: parse the exponent sign, divide when it is negative
  const nl = inDef('numlit %s');
  const bad = find(nl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'nres'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'operator_multiply');
  if (bad.length !== 1) throw new Error('[P121] numlit exponent set = ' + bad.length);
  const strip = () => [
    callProc('substr %s %s %s', [F('nex'), num(2), lenOf(F('nex'))]),
    setV('edig', VAR('ev'))
  ];
  const signParse = replaceStmt(bad[0], IFELSE(EQ(chAt(num(1), F('nex')), txt('-')), [
    setV('esgn', num(1)),
    ...strip()
  ], [
    setV('esgn', num(0)),
    IFELSE(EQ(chAt(num(1), F('nex')), txt('+')), strip(), [setV('edig', F('nex'))])
  ]));
  // NB: splice after the *replacement* -- bad[0] is detached once replaceStmt has run
  spliceAfter(signParse, chain([
    IFELSE(EQ(F('esgn'), num(1)), [
      setV('epw', pow10(F('edig'))),
      setV('nres', DIV(F('nmn'), VAR('epw')))
    ], [
      setV('nres', MUL(F('nmn'), pow10(F('edig'))))
    ])
  ]));
  console.log('[P121] numlit divides for a negative exponent');

  // ---------- (b) numbercheck accepts scientific notation
  const ncDef = defIdOf('numbercheck %s');
  attachBody(ncDef, [
    setV('en', num(1)), setV('ed', num(0)), setV('et', num(0)), setV('nee', num(0)), setV('nesg', num(0)), setV('ep', num(1)),
    REPEAT(lenOf(argOf('s')), [
      setV('ec', chAt(F('ep'), argOf('s'))),
      IFELSE(EQ(VAR('ec'), txt('.')), [chgV('ed', num(1))], [
        IFELSE(inSet(F('ec'), '0123456789'), [
          chgV('et', num(1)),
          setV('nesg', num(0))
        ], [
          IFELSE(AND(OR(EQ(F('ec'), txt('e')), EQ(F('ec'), txt('E'))), AND(EQ(F('nee'), num(0)), GT(F('et'), num(0)))), [
            setV('nee', num(1)),
            setV('nesg', num(1))
          ], [
            IFELSE(AND(OR(EQ(F('ec'), txt('+')), EQ(F('ec'), txt('-'))), OR(EQ(F('ep'), num(1)), EQ(F('nesg'), num(1)))), [
              setV('nesg', num(0))
            ], [
              setV('en', num(0))
            ])
          ])
        ])
      ]),
      chgV('ep', num(1))
    ]),
    IF(OR(GT(VAR('ed'), num(1)), EQ(VAR('et'), num(0))), [setV('en', num(0))]),
    IF(EQ(VAR('nee'), num(1)), [
      IF(NOT(inSet(chAt(lenOf(argOf('s')), argOf('s')), '0123456789')), [setV('en', num(0))])
    ])
  ]);
  console.log('[P121] numbercheck accepts scientific notation');
});

// ---- P122: float repr -- CPython's fixed/scientific switch ----
//
// MiniPy prints a float as whatever text the value carries (plus ".0" when it has no dot), so
// `1e16` came out as 10000000000000000.0 where CPython writes 1e+16, and `1e-5` as 0.00001 where
// CPython writes 1e-05.  CPython's repr(float) uses fixed notation for -4 <= exp10 < 16 and
// scientific otherwise, with a sign and at least two exponent digits; JS's shortest round-trip
// digits are the same in both, so only the shape has to be rewritten.
//
// floatfmt does that rewriting, and mkfloat (the one place every float result passes through)
// now calls it.  Two extra call sites keep the float flag from being lost: unary minus on a
// float operand (which otherwise re-enters JS arithmetic and drops the ".0", and is also where
// -0.0 has to be produced) and float().
patch('P122 float repr', () => {
  const names = ['ffs', 'fft', 'ffp', 'ffi', 'ffm', 'ffx', 'ffd', 'ffz', 'ffe', 'fff', 'ffsx', 'unv'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of names) if (taken.has(n)) throw new Error('[P122] variable name taken: ' + n);
  for (const n of names) newVar(n, 0);
  const F = (v) => VAR(v);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const chAt = (i, s) => I('operator_letter_of', { inputs: { LETTER: B.REP(i, [4, '0']), STRING: B.REP(s, [10, '']) } });
  const isDigit = (x) => I('operator_contains', { inputs: { STRING1: B.REP(txt('0123456789'), [10, '']), STRING2: B.REP(x, [10, '']) } });
  // helpers that return statement lists
  const sliceInto = (target, s, a, b) => [
    callProc('substr %s %s %s', [s, a, b]),
    setV(target, VAR('ev'))
  ];
  const stripZeros = (target) => [
    REPEATU(NOT(AND(GT(lenOf(F(target)), num(1)), EQ(chAt(lenOf(F(target)), F(target)), txt('0')))), [
      ...sliceInto(target, F(target), num(1), SUB(lenOf(F(target)), num(1)))
    ])
  ];
  // the exponent needs its *leading* zeros removed ("+007" -> "7"), never its trailing ones
  const stripLeadZeros = (target) => [
    REPEATU(NOT(AND(GT(lenOf(F(target)), num(1)), EQ(chAt(num(1), F(target)), txt('0')))), [
      ...sliceInto(target, F(target), num(2), lenOf(F(target)))
    ])
  ];
  const pad2 = (target, x) => [
    setV(target, x),
    IF(LT(lenOf(F(target)), num(2)), [setV(target, JOIN(txt('0'), F(target)))])
  ];
  const mantFrom = (digVar) => IFELSE(GT(lenOf(F(digVar)), num(1)), [
    ...sliceInto('ffm', F(digVar), num(2), lenOf(F(digVar))),
    setV('ffm', JOIN(chAt(num(1), F(digVar)), JOIN(txt('.'), F('ffm'))))
  ], [
    setV('ffm', F(digVar))
  ]);
  const science = (expText) => [
    setV('ev', JOIN(F('ffs'), JOIN(F('ffm'), JOIN(txt(expText), F('ffx'))))),
    setV('evtype', txt('S')),
    STOPTHIS()
  ];

  const ff = newProc('floatfmt %s', ['s']);
  attachBody(ff.defId, [
    setV('ffs', txt('')), setV('fft', argOf('s')),
    IF(EQ(chAt(num(1), F('fft')), txt('-')), [
      setV('ffs', txt('-')),
      ...sliceInto('fft', F('fft'), num(2), lenOf(F('fft')))
    ]),
    // an exponent already present: normalise `e` + sign + at least two digits
    setV('ffp', num(0)), setV('ffi', num(1)),
    REPEATU(GT(F('ffi'), lenOf(F('fft'))), [
      IF(OR(EQ(chAt(F('ffi'), F('fft')), txt('e')), EQ(chAt(F('ffi'), F('fft')), txt('E'))), [setV('ffp', F('ffi'))]),
      chgV('ffi', num(1))
    ]),
    IFELSE(GT(F('ffp'), num(0)), [
      ...sliceInto('ffm', F('fft'), num(1), SUB(F('ffp'), num(1))),
      ...sliceInto('ffx', F('fft'), ADD(F('ffp'), num(1)), lenOf(F('fft'))),
      setV('ffsx', txt('+')),
      IFELSE(EQ(chAt(num(1), F('ffx')), txt('-')), [
        setV('ffsx', txt('-')),
        ...sliceInto('ffx', F('ffx'), num(2), lenOf(F('ffx')))
      ], [
        IF(EQ(chAt(num(1), F('ffx')), txt('+')), [
          ...sliceInto('ffx', F('ffx'), num(2), lenOf(F('ffx')))
        ])
      ]),
      ...stripLeadZeros('ffx'),
      IF(LT(lenOf(F('ffx')), num(2)), [setV('ffx', JOIN(txt('0'), F('ffx')))]),
      setV('ev', JOIN(F('ffs'), JOIN(F('ffm'), JOIN(txt('e'), JOIN(VAR('ffsx'), F('ffx')))))),
      setV('evtype', txt('S')),
      STOPTHIS()
    ], [
      // no exponent yet: locate the dot
      setV('ffp', num(0)), setV('ffi', num(1)),
      REPEATU(GT(F('ffi'), lenOf(F('fft'))), [
        IF(EQ(chAt(F('ffi'), F('fft')), txt('.')), [setV('ffp', F('ffi'))]),
        chgV('ffi', num(1))
      ]),
      IFELSE(EQ(F('ffp'), num(0)), [
        // an integer-valued float: 17+ digits means the value is >= 1e16
        IFELSE(NOT(LT(lenOf(F('fft')), num(17))), [
          ...sliceInto('ffd', F('fft'), num(1), lenOf(F('fft'))),
          ...stripZeros('ffd'),
          ...pad2('ffx', SUB(lenOf(F('fft')), num(1))),
          mantFrom('ffd'),
          ...science('e+')
        ], [
          setV('ev', JOIN(F('ffs'), JOIN(F('fft'), txt('.0')))),
          setV('evtype', txt('S'))
        ])
      ], [
        ...sliceInto('ffe', F('fft'), num(1), SUB(F('ffp'), num(1))),
        ...sliceInto('fff', F('fft'), ADD(F('ffp'), num(1)), lenOf(F('fft'))),
        IF(AND(EQ(F('ffe'), txt('0')), NOT(LT(lenOf(F('fff')), num(4)))), [
          setV('ffz', num(0)), setV('ffi', num(1)),
          REPEATU(OR(GT(F('ffi'), lenOf(F('fff'))), NOT(EQ(chAt(F('ffi'), F('fff')), txt('0')))), [
            chgV('ffz', num(1)),
            chgV('ffi', num(1))
          ]),
          IF(NOT(LT(F('ffz'), num(4))), [
            ...sliceInto('ffd', F('fff'), ADD(F('ffz'), num(1)), lenOf(F('fff'))),
            ...stripZeros('ffd'),
            ...pad2('ffx', ADD(F('ffz'), num(1))),
            mantFrom('ffd'),
            ...science('e-')
          ])
        ]),
        IF(NOT(LT(lenOf(F('ffe')), num(17))), [
          // a very large value written out in full: let JS round it to the double first
          setV('fft', MUL(F('fft'), num(1))),
          ...sliceInto('ffd', F('fft'), num(1), lenOf(F('fft'))),
          ...stripZeros('ffd'),
          ...pad2('ffx', SUB(lenOf(F('fft')), num(1))),
          mantFrom('ffd'),
          ...science('e+')
        ]),
        setV('ev', JOIN(F('ffs'), F('fft'))),
        setV('evtype', txt('S'))
      ])
    ])
  ]);
  console.log('[P122] floatfmt installed');

  // ---------- mkfloat now formats like CPython
  const mk = defIdOf('mkfloat %s');
  attachBody(mk, [
    callProc('floatfmt %s', [argOf('v')]),
    setV('evtype', txt('N'))
  ]);
  console.log('[P122] mkfloat goes through floatfmt');

  // ---------- unary minus must not lose the float flag (and -0.0 is a float)
  const un = inDef('unary %s %s %s');
  const negSet = find(un, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]] && BL()[b.inputs.VALUE[1]].opcode === 'operator_subtract'
    && litOf(BL()[b.inputs.VALUE[1]].inputs.NUM1) === '0');
  if (negSet.length !== 1) throw new Error('[P122] unary minus set = ' + negSet.length);
  const isFloatText = (x) => OR(I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('.'), [10, '']) } }),
    OR(I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('e'), [10, '']) } }),
       I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('E'), [10, '']) } })));
  insertBeforeStmt(negSet[0], [setV('unv', VAR('ev'))]);
  spliceAfter(negSet[0], chain([
    IF(isFloatText(F('unv')), [
      IFELSE(EQ(VAR('ev'), num(0)), [
        setV('ev', txt('-0.0'))
      ], [
        callProc('mkfloat %s', [VAR('ev')])
      ])
    ])
  ]));
  console.log('[P122] unary minus keeps float text (-0.0 included)');

  // ---------- float() answers with a float
  const cf = inDef('callfn %s %s %s');
  const fBranch = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      return q && q.opcode === 'operator_equals' && litOf(q.inputs.OPERAND2) === 'float';
    }));
  if (fBranch.length !== 1) throw new Error('[P122] float() branch = ' + fBranch.length);
  // the branch's own chain: insert just before its final `pending = 1`
  const fFirst = BL()[fBranch[0]].inputs.SUBSTACK[1];
  let fLast = fFirst, hops = 0;
  while (BL()[fLast].next && hops++ < 200) fLast = BL()[fLast].next;
  if (BL()[fLast].opcode !== 'data_setvariableto' || BL()[fLast].fields.VARIABLE[0] !== 'pending') {
    throw new Error('[P122] float() branch tail = ' + BL()[fLast].opcode);
  }
  insertBeforeStmt(fLast, [
    IF(EQ(argOf('fn'), txt('float')), [callProc('mkfloat %s', [VAR('ev')])])
  ]);
  console.log('[P122] float() produces a float');

  // ---------- a long float literal goes through floatfmt too (123456789012345678.0 needs it)
  const at = inDef('atom %s');
  const nc = find(at, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'numbercheck %s');
  if (nc.length !== 1) throw new Error('[P122] atom numbercheck = ' + nc.length);
  insertBeforeStmt(nc[0], [
    IF(AND(I('operator_contains', { inputs: { STRING1: B.REP(VAR('ev'), [10, '']), STRING2: B.REP(txt('.'), [10, '']) } }),
      NOT(LT(lenOf(VAR('ev')), num(17)))), [
      callProc('mkfloat %s', [VAR('ev')])
    ])
  ]);
  console.log('[P122] long float literals are formatted too');
});

// ---- P123: `return` / `break` inside a try with a finally runs the tail first ----
//
// P107 runs a `finally` tail by keeping a frame (FinStart/FinEnd/FinMsg/FinC) and driving it from
// a hook in trycatch: an error passing by is parked in FinMsg and the tail runs before it is
// re-raised.  A `return` (or `break`/`continue`) is not an error, so it left the body the normal
// way -- the driver saw retflag/dest and never ran the tail:
//     def f():
//         try: return 1
//         finally: print('fin')        # v4.49 prints only "1"
//
// This patch parks those jumps the same way an error is parked: the action is recorded in
// FinRet (1 = return, 2 = break, 3 = continue) together with whatever it needs (FinV/FinVT for
// the value, FinDest for the jump target), `dest` is redirected into the tail, and the hook
// replays the action once the tail has been passed.  A jump that happens *inside* the tail
// itself is deliberately not deferred (pc < FinStart is what marks "still in the protected
// body"), because CPython lets a return in the tail win.
//
// P107 only pushed a tail frame when the *first* clause of the `try` was `finally`, so
// `try/except/finally` kept a plain handler frame and the tail was skipped whenever the handler
// ran (`try: 1/0 / except: return 7 / finally: print('fin')` printed just "7").  Now the try
// branch walks the `Elses` clause chain (except -> ... -> finally) and pushes a tail frame as
// well, marked FinH=1 / FinHand=<handler line>.  Two rules keep the order CPython uses:
//   * an error raised *in the protected body* is left to the trycatch walk, which runs the
//     matching handler first, and the tail runs after that handler;
//   * an error the construct's own handler refuses (the walk is about to discard that frame)
//     parks the error and runs the tail *before* the error reaches an outer handler.
patch('P123 finally runs on return', () => {
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fret', 'fdest', 'wpval', 'fvt', 'fdef', 'finx', 'finf', 'finline']) if (taken.has(n)) throw new Error('[P123] variable name taken: ' + n);
  for (const v of ['fret', 'fdest', 'wpval', 'fvt', 'fdef', 'finx', 'finf', 'finline']) newVar(v, 0);
  for (const l of ['FinRet', 'FinDest', 'FinV', 'FinVT', 'FinH', 'FinHand']) B.addList(IT, l, []);
  const F = (v) => VAR(v);
  const last = (l) => item(l, llen(l));
  const delLast = (l) => I('data_deleteoflist', { fields: B.LISTF(l), inputs: { INDEX: txt('last') } });
  const replaceLast = (l, v) => I('data_replaceitemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(llen(l), [4, '0']), ITEM: B.REP(v, [4, '0']) } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const eqVarLit = (b, name, lit) => !!b && b.opcode === 'operator_equals'
    && ((vnOf(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit)
     || (vnOf(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit));
  const inBody = () => AND(GT(llen('FinEnd'), num(0)),
    AND(EQ(last('FinC'), F('cdepth')), AND(LT(F('pc'), last('FinStart')), LT(F('pc'), last('FinEnd')))));
  // fresh blocks on every call: a block id may only appear at one place in the tree
  const pushExtra = () => [
    addTo('FinRet', num(0)), addTo('FinDest', num(0)), addTo('FinV', txt('')), addTo('FinVT', txt(''))
  ];
  const popExtra = () => [
    delLast('FinRet'), delLast('FinDest'), delLast('FinV'), delLast('FinVT'),
    delLast('FinH'), delLast('FinHand')
  ];
  const dropFrame = () => [...popExtra(), delLast('FinStart'), delLast('FinEnd'), delLast('FinMsg'), delLast('FinC')];

  // ---------- (a) the `try/finally` push grows the two markers and the action fields
  const finC = find(allIds(), (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'FinC');
  if (finC.length !== 1) throw new Error('[P123] FinC push = ' + finC.length);
  spliceAfter(finC[0], chain([addTo('FinH', num(0)), addTo('FinHand', num(0)), ...pushExtra()]));

  // ---------- (a2) `try/except/finally`: walk the clause chain and push a tail frame too
  const handPush = find(allIds(), (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'TryHand');
  if (handPush.length !== 1) throw new Error('[P123] TryHand push = ' + handPush.length);
  const fork = find(allIds(), (b) => b.opcode === 'control_if_else'
    && b.inputs.SUBSTACK2 && b.inputs.SUBSTACK2[1] === handPush[0]);
  if (fork.length !== 1) throw new Error('[P123] finally fork = ' + fork.length);
  let handEnd = handPush[0];
  while (BL()[handEnd].next) handEnd = BL()[handEnd].next;
  if (BL()[handEnd].fields.LIST[0] !== 'TryC') throw new Error('[P123] handler push chain ends at ' + BL()[handEnd].fields.LIST[0]);
  const finPush = chain([
    setV('finx', item('Elses', F('tpc'))),
    setV('finf', num(0)),
    REPEATU(OR(EQ(F('finx'), num(0)), EQ(F('finf'), num(1))), [
      callProc('tokenize %s', [item('Code', F('finx'))]),
      IF(EQ(item('Tok', num(1)), txt('finally')), [setV('finf', num(1)), setV('finline', F('finx'))]),
      IF(EQ(F('finf'), num(0)), [setV('finx', item('Elses', F('finx')))])
    ]),
    IF(EQ(F('finf'), num(1)), [
      addTo('FinStart', ADD(F('finline'), num(1))),
      addTo('FinEnd', item('Ends', F('finline'))),
      addTo('FinMsg', txt('')),
      addTo('FinC', F('cdepth')),
      addTo('FinH', num(1)),
      addTo('FinHand', ADD(F('tpc'), num(1))),
      ...pushExtra()
    ])
  ]);
  BL()[handEnd].next = finPush; BL()[finPush].parent = handEnd;
  console.log('[P123] try/except/finally keeps a tail frame as well');

  // ---------- (b) the hook: pop the extra fields and replay the parked action
  const tc = inDef('trycatch');
  const mentions = (id, list) => [...reach(id)].some((x) => BL()[x].fields && BL()[x].fields.LIST && BL()[x].fields.LIST[0] === list);
  // the sweep that drops frames from functions that already returned
  const sweep = find(tc, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && mentions(b.inputs.CONDITION[1], 'FinC'));
  if (sweep.length !== 1) throw new Error('[P123] sweep = ' + sweep.length);
  const sweepBody = BL()[sweep[0]].inputs.SUBSTACK && BL()[sweep[0]].inputs.SUBSTACK[1];
  if (typeof sweepBody !== 'string') throw new Error('[P123] sweep body');
  spliceAfter(sweepBody, chain(popExtra()));
  // the "tail has been passed" branch
  const done = find(tc, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      return !!q && q.opcode === 'operator_not' && typeof q.inputs.OPERAND[1] === 'string' && mentions(q.inputs.OPERAND[1], 'FinEnd');
    })());
  if (done.length !== 1) throw new Error('[P123] tail-done branch = ' + done.length);
  B.sub(IT, done[0], 'SUBSTACK', chain([
    setV('tfm', last('FinMsg')),
    setV('fret', last('FinRet')),
    setV('fdest', last('FinDest')),
    setV('wpval', last('FinV')),
    setV('fvt', last('FinVT')),
    ...popExtra(),
    delLast('FinStart'), delLast('FinEnd'), delLast('FinMsg'), delLast('FinC'),
    IF(EQ(F('fret'), num(1)), [
      IFELSE(inBody(), [
        // still inside another protected body: park it for the next tail outwards
        replaceLast('FinRet', num(1)),
        replaceLast('FinV', F('wpval')),
        replaceLast('FinVT', F('fvt')),
        setV('pc', last('FinStart'))
      ], [
        // a `return` in the tail itself wins, so only replay when the tail finished normally
        IF(NOT(EQ(F('retflag'), num(1))), [
          setV('ev', F('wpval')),
          setV('evtype', F('fvt')),
          setV('retflag', num(1))
        ])
      ])
    ]),
    IF(EQ(F('fret'), num(2)), [
      IFELSE(inBody(), [
        replaceLast('FinRet', num(2)),
        replaceLast('FinDest', F('fdest')),
        setV('pc', last('FinStart'))
      ], [callProc('popLoop'), setV('pc', F('fdest'))])
    ]),
    IF(EQ(F('fret'), num(3)), [
      IFELSE(inBody(), [
        replaceLast('FinRet', num(3)),
        replaceLast('FinDest', F('fdest')),
        setV('pc', last('FinStart'))
      ], [setV('pc', F('fdest'))])
    ]),
    IF(NOT(EQ(F('tfm'), txt(''))), [setV('error', F('tfm'))])
  ]));
  // the error arm: only an error *outside* the protected body is ours to park.  An error in the
  // body is left to the walk below (its own handler may catch it), an error in the tail replaces
  // whatever was parked.
  const pcInTail = () => NOT(LT(F('pc'), last('FinStart')));
  const pcInBody = () => LT(F('pc'), last('FinHand'));
  B.sub(IT, done[0], 'SUBSTACK2', chain([
    IF(NOT(EQ(F('error'), txt(''))), [
      IF(pcInTail(), [...dropFrame()]),
      IF(AND(NOT(pcInTail()), NOT(pcInBody())), [
        IFELSE(EQ(last('FinMsg'), txt('')), [
          replaceLast('FinMsg', F('error')),
          setV('error', txt('')),
          setV('pc', last('FinStart'))
        ], [...dropFrame()])
      ])
    ])
  ]));

  // ---------- (b2) the walk: a handler that refuses the error still owes its tail
  const walk = find(tc, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && mentions(b.inputs.CONDITION[1], 'TryC')
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_not'));
  if (walk.length !== 1) throw new Error('[P123] trycatch walk = ' + walk.length);
  const walkBody = BL()[walk[0]].inputs.SUBSTACK && BL()[walk[0]].inputs.SUBSTACK[1];
  if (typeof walkBody !== 'string') throw new Error('[P123] walk body');
  const pop4 = find(reach(walkBody), (b) => b.opcode === 'data_deleteoflist' && b.fields.LIST && b.fields.LIST[0] === 'TryHand');
  if (pop4.length !== 1) throw new Error('[P123] walk pop = ' + pop4.length);
  insertBeforeStmt(pop4[0], [
    IF(AND(NOT(EQ(F('error'), txt(''))), AND(GT(llen('FinHand'), num(0)),
      AND(EQ(last('FinHand'), last('TryHand')), NOT(EQ(last('FinHand'), num(0)))))), [
      replaceLast('FinMsg', F('error')),
      setV('error', txt('')),
      setV('pc', last('FinStart'))
    ])
  ]);

  // ---------- (c) `return` parks itself when a tail is pending
  const ex = inDef('execute');
  const retBranch = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => eqVarLit(BL()[x], 'head', 'return')));
  if (retBranch.length !== 1) throw new Error('[P123] return branch = ' + retBranch.length);
  const retFlag = find(reach(retBranch[0]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'retflag'
    && litOf(b.inputs.VALUE) === '1');
  if (retFlag.length !== 1) throw new Error('[P123] retflag set = ' + retFlag.length);
  spliceAfter(retFlag[0], chain([
    IF(inBody(), [
      replaceLast('FinRet', num(1)),
      replaceLast('FinV', VAR('ev')),
      replaceLast('FinVT', VAR('evtype')),
      setV('retflag', num(0)),
      setV('dest', last('FinStart'))
    ])
  ]));

  // ---------- (d) `break` / `continue` park themselves too
  const brkBranch = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && [...reach(b.inputs.CONDITION[1])].some((x) => eqVarLit(BL()[x], 'head', 'break'))
    && [...reach(b.inputs.CONDITION[1])].some((x) => eqVarLit(BL()[x], 'head', 'continue')));
  if (brkBranch.length !== 1) throw new Error('[P123] break branch = ' + brkBranch.length);
  const popLoopCall = find(reach(brkBranch[0]), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'popLoop');
  if (popLoopCall.length !== 1) throw new Error('[P123] popLoop call = ' + popLoopCall.length);
  // `if head == "break": popLoop()` -- the call is the whole substack, so the defer block goes in
  // front of that statement and the call itself is guarded by the flag
  const popIf = find(reach(brkBranch[0]), (b) => b.opcode === 'control_if'
    && b.inputs.SUBSTACK && b.inputs.SUBSTACK[1] === popLoopCall[0]);
  if (popIf.length !== 1) throw new Error('[P123] popLoop guard = ' + popIf.length);
  insertBeforeStmt(popIf[0], [
    setV('fdef', num(0)),
    IF(inBody(), [
      setV('fdef', num(1)),
      // `head` is the literal text: 2 = break, 3 = continue
      IFELSE(EQ(F('head'), txt('break')), [replaceLast('FinRet', num(2))], [replaceLast('FinRet', num(3))]),
      replaceLast('FinDest', F('dest')),
      setV('dest', last('FinStart'))
    ])
  ]);
  replaceStmt(popLoopCall[0], IF(EQ(F('fdef'), num(0)), [popLoopCall[0]]));

  // ---------- (e) clear the extra lists at the start of a run
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'FinC');
  if (runInit.length !== 1) throw new Error('[P123] run init anchor = ' + runInit.length);
  spliceAfter(runInit[0], chain([clearL('FinRet'), clearL('FinDest'), clearL('FinV'), clearL('FinVT'), clearL('FinH'), clearL('FinHand')]));
  console.log('[P123] return/break run the finally tail first');
});

// ---- P124: set methods (add/remove/discard/clear/update/union/...) and set operators ----
//
// P111 gave sets a literal, a comprehension, a canonical order (setnorm) and a face
// (len/in/for via P113, the builtins via P114) -- but nothing that *mutates* one, and none of
// the set operators.  `s.add(2)` said "AttributeError: only lists have methods" (methodcall's
// type guard only lets L/S/O/D through) and `a | b` fell into the bitwise branch
// ("TypeError: bitwise requires integers").
//
// A set is encoded exactly like a list (a flat run of `lsep + type + escaped text`), so:
//   * membership is a walk with listlen/listitem + compareText -- `lhas`;
//   * `|` is the concatenation of the two runs handed to setnorm, `&`/`-` are a filtered walk
//     of the left run (`setfilter`), `^` is `(a - b) | (b - a)`;
//   * the mutators rebuild the run and write it back with `assign name <run> E`, which is the
//     same call the list mutators use (P54's alias propagation is widened to E so `t = s;
//     s.add(1)` is visible through `t`, as CPython's shared object would be).
// Every helper gets its own scratch variables -- the nested calls (setfilter -> lhas) would
// otherwise clobber each other's loop counters.
patch('P124 set methods and operators', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const argName = (d) => { const b = blk(d); return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const varName = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const isArgEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((argName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (argName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isVarEq = (d, name, lit) => { const b = blk(d); return !!b && b.opcode === 'operator_equals' && ((varName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit) || (varName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit)); };
  const isDotContains = (d) => { const b = blk(d); return !!b && b.opcode === 'operator_contains' && litOf(b.inputs.STRING2) === '.'; };
  const VARS = ['lhn', 'lhi', 'lhv', 'lht', 'lhf', 'qfn', 'qfi', 'qfv', 'qft', 'qfa',
    'adp', 'adf', 'den', 'dei', 'dev', 'det', 'deacc', 'def', 'dehit',
    'smop', 'smb', 'smkey', 'smkeyt', 'stn', 'sti', 'stacc', 'scn', 'sna', 'snb', 'srb'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P124] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  const enc = (acc, t, v) => JOIN(JOIN(JOIN(acc, VAR('lsep')), t), v);

  // ---------- (a) lhas <enc> <v> <t>: is this element in the run?
  const lh = newProc('lhas %s %s %s', ['enc', 'v', 't']);
  attachBody(lh.defId, [
    setV('lhf', num(0)),
    callProc('listlen %s', [argOf('enc')]), setV('lhn', VAR('ev')),
    setV('lhi', num(1)),
    REPEATU(OR(GT(VAR('lhi'), VAR('lhn')), EQ(VAR('lhf'), num(1))), [
      callProc('listitem %s %s', [argOf('enc'), VAR('lhi')]),
      setV('lhv', VAR('ev')), setV('lht', VAR('evtype')),
      IF(EQ(VAR('lht'), argOf('t')), [
        IFELSE(EQ(argOf('t'), txt('S')), [
          callProc('compareText %s %s', [VAR('lhv'), argOf('v')]),
          IF(EQ(VAR('cmp'), num(0)), [setV('lhf', num(1))])
        ], [
          IF(EQ(VAR('lhv'), argOf('v')), [setV('lhf', num(1))])
        ])
      ]),
      chgV('lhi', num(1))
    ]),
    setV('ev', VAR('lhf')), setV('evtype', txt('N'))
  ]);
  console.log('[P124] lhas installed');

  // ---------- (b) setadd <enc> <v> <t>: append the element unless it is already there
  const sa = newProc('setadd %s %s %s', ['enc', 'v', 't']);
  attachBody(sa.defId, [
    callProc('lhas %s %s %s', [argOf('enc'), argOf('v'), argOf('t')]),
    setV('adf', VAR('ev')),
    setV('ev', argOf('enc')), setV('evtype', txt('E')),
    IF(EQ(VAR('adf'), num(0)), [
      callProc('lesc %s', [argOf('v')]),
      setV('adp', enc(txt(''), argOf('t'), VAR('ev'))),
      setV('ev', JOIN(argOf('enc'), VAR('adp'))), setV('evtype', txt('E'))
    ])
  ]);

  // ---------- (c) setdel <enc> <v> <t>: drop the first match, def = 1 if one was dropped
  const sd = newProc('setdel %s %s %s', ['enc', 'v', 't']);
  attachBody(sd.defId, [
    setV('def', num(0)), setV('deacc', txt('')),
    callProc('listlen %s', [argOf('enc')]), setV('den', VAR('ev')),
    setV('dei', num(1)),
    REPEATU(GT(VAR('dei'), VAR('den')), [
      callProc('listitem %s %s', [argOf('enc'), VAR('dei')]),
      setV('dev', VAR('ev')), setV('det', VAR('evtype')),
      setV('dehit', num(0)),
      IF(AND(EQ(VAR('def'), num(0)), EQ(VAR('det'), argOf('t'))), [
        IFELSE(EQ(argOf('t'), txt('S')), [
          callProc('compareText %s %s', [VAR('dev'), argOf('v')]),
          IF(EQ(VAR('cmp'), num(0)), [setV('dehit', num(1))])
        ], [
          IF(EQ(VAR('dev'), argOf('v')), [setV('dehit', num(1))])
        ])
      ]),
      IFELSE(EQ(VAR('dehit'), num(1)), [
        setV('def', num(1))
      ], [
        callProc('lesc %s', [VAR('dev')]),
        setV('deacc', enc(VAR('deacc'), VAR('det'), VAR('ev')))
      ]),
      chgV('dei', num(1))
    ]),
    setV('ev', VAR('deacc')), setV('evtype', txt('E'))
  ]);

  // ---------- (d) setfilter <a> <b> <keep>: keep the elements of <a> that are (not) in <b>
  const sf = newProc('setfilter %s %s %s', ['a', 'b', 'keep']);
  attachBody(sf.defId, [
    setV('qfa', txt('')),
    callProc('listlen %s', [argOf('a')]), setV('qfn', VAR('ev')),
    setV('qfi', num(1)),
    REPEATU(GT(VAR('qfi'), VAR('qfn')), [
      callProc('listitem %s %s', [argOf('a'), VAR('qfi')]),
      setV('qfv', VAR('ev')), setV('qft', VAR('evtype')),
      callProc('lhas %s %s %s', [argOf('b'), VAR('qfv'), VAR('qft')]),
      IF(EQ(VAR('ev'), argOf('keep')), [
        callProc('lesc %s', [VAR('qfv')]),
        setV('qfa', enc(VAR('qfa'), VAR('qft'), VAR('ev')))
      ]),
      chgV('qfi', num(1))
    ]),
    setV('ev', VAR('qfa')), setV('evtype', txt('E'))
  ]);

  // ---------- (e) setop <op> <a> <b>
  const so = newProc('setop %s %s %s', ['op', 'a', 'b']);
  attachBody(so.defId, [
    IF(EQ(argOf('op'), txt('|')), [callProc('setnorm %s', [JOIN(argOf('a'), argOf('b'))])]),
    IF(EQ(argOf('op'), txt('&')), [callProc('setfilter %s %s %s', [argOf('a'), argOf('b'), num(1)])]),
    IF(EQ(argOf('op'), txt('-')), [callProc('setfilter %s %s %s', [argOf('a'), argOf('b'), num(0)])]),
    IF(EQ(argOf('op'), txt('^')), [
      callProc('setfilter %s %s %s', [argOf('a'), argOf('b'), num(0)]),
      setV('smb', VAR('ev')),
      callProc('setfilter %s %s %s', [argOf('b'), argOf('a'), num(0)]),
      callProc('setnorm %s', [JOIN(VAR('smb'), VAR('ev'))])
    ])
  ]);
  console.log('[P124] setop installed');

  // ---------- (f) setmeth <rec> <name> <meth> <lo> <hi>
  const sm = newProc('setmeth %s %s %s %s %s', ['rec', 'nm', 'meth', 'lo', 'hi']);
  const argRange = () => [argOf('lo'), argOf('hi')];
  const evalArg = () => callProc('eval %s %s', argRange());
  const none = () => [setV('ev', txt('')), setV('evtype', txt('Z'))];
  const writeBack = (run) => callProc('assign %s %s %s', [argOf('nm'), run, txt('E')]);
  const mutate = (rebuild) => [evalArg(), ...rebuild, writeBack(VAR('ev')), ...none()];
  const keyError = () => IFELSE(EQ(VAR('smkeyt'), txt('S')),
    [FAILB(JOIN(JOIN(txt("KeyError: '"), VAR('smkey')), txt("'")))],
    [FAILB(JOIN(txt('KeyError: '), VAR('smkey')))]);
  // every handled branch must stop the script itself (the FAILB below is unconditional)
  const br = (cond, stmts) => IF(cond, [...stmts, STOPTHIS()]);
  attachBody(sm.defId, [
    br(EQ(argOf('meth'), txt('add')), mutate([callProc('setadd %s %s %s', [argOf('rec'), VAR('ev'), VAR('evtype')])])),
    br(EQ(argOf('meth'), txt('discard')), mutate([callProc('setdel %s %s %s', [argOf('rec'), VAR('ev'), VAR('evtype')])])),
    br(EQ(argOf('meth'), txt('remove')), [
      evalArg(),
      setV('smkey', VAR('ev')), setV('smkeyt', VAR('evtype')),
      callProc('setdel %s %s %s', [argOf('rec'), VAR('smkey'), VAR('smkeyt')]),
      IF(EQ(VAR('def'), num(0)), [keyError()]),
      writeBack(VAR('ev')), ...none()
    ]),
    br(EQ(argOf('meth'), txt('clear')), [writeBack(txt('')), ...none()]),
    br(EQ(argOf('meth'), txt('update')), mutate([
      setV('smb', VAR('ev')),
      callProc('setnorm %s', [JOIN(argOf('rec'), VAR('smb'))])
    ])),
    br(OR(OR(EQ(argOf('meth'), txt('union')), EQ(argOf('meth'), txt('intersection'))),
      OR(EQ(argOf('meth'), txt('difference')), EQ(argOf('meth'), txt('symmetric_difference')))), [
      evalArg(),
      setV('smb', VAR('ev')),
      setV('smop', txt('|')),
      IF(EQ(argOf('meth'), txt('intersection')), [setV('smop', txt('&'))]),
      IF(EQ(argOf('meth'), txt('difference')), [setV('smop', txt('-'))]),
      IF(EQ(argOf('meth'), txt('symmetric_difference')), [setV('smop', txt('^'))]),
      callProc('setop %s %s %s', [VAR('smop'), argOf('rec'), VAR('smb')])
    ]),
    br(EQ(argOf('meth'), txt('copy')), [setV('ev', argOf('rec')), setV('evtype', txt('E'))]),
    br(EQ(argOf('meth'), txt('isdisjoint')), [
      evalArg(),
      setV('smb', VAR('ev')),
      callProc('setfilter %s %s %s', [argOf('rec'), VAR('smb'), num(1)]),
      callProc('listlen %s', [VAR('ev')]),
      IFELSE(EQ(VAR('ev'), num(0)), [setV('ev', num(1))], [setV('ev', num(0))]),
      setV('evtype', txt('B'))
    ]),
    FAILB(JOIN(txt('AttributeError: set has no method '), argOf('meth')))
  ]);
  console.log('[P124] setmeth installed');

  // ---------- (g) methodcall: an 'E' receiver goes to setmeth (in front of the type guard)
  const mc = inDef('methodcall %s %s');
  const typeGuard = find(mc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && (() => {
    const n = blk(b.inputs.CONDITION);
    if (!n || n.opcode !== 'operator_not') return false;
    return [...reach(b.inputs.CONDITION[1])].some((id) => {
      const e = BL()[id];
      return e && e.opcode === 'operator_equals' && varName(e.inputs.OPERAND1) === 'xb' && litOf(e.inputs.OPERAND2) === 'O';
    });
  })());
  if (typeGuard.length !== 1) throw new Error('[P124] methodcall type guard = ' + typeGuard.length);
  insertBeforeStmt(typeGuard[0], [
    IF(EQ(VAR('xb'), txt('E')), [
      callProc('setmeth %s %s %s %s %s', [VAR('xa'), item('Tok', argOf('lo')), item('Tok', ADD(argOf('lo'), num(2))), ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
      STOPTHIS()
    ])
  ]);
  console.log('[P124] set methods hooked');
  // P20's chain splitter counts `{` as an opener (P93 made it brace-aware) but never counts
  // `}`, so a set/dict literal inside the first segment left the depth at 1 and the chain was
  // never split -- `s.union({3}).difference({1})` then handed the whole span to one call.
  const tokMck = (d) => { const b = blk(d); return !!b && b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Tok' && varName(b.inputs.INDEX) === 'mck'; };
  const scan = find(mc, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x] && BL()[x].opcode === 'operator_gt' && varName(BL()[x].inputs.OPERAND1) === 'mck'));
  if (scan.length !== 1) throw new Error('[P124] chain splitter scan = ' + scan.length);
  const scanBody = BL()[scan[0]].inputs.SUBSTACK[1];
  const closeIf = find(reach(scanBody), (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const e = BL()[b.inputs.CONDITION[1]];
      return !!e && e.opcode === 'operator_equals'
        && ((tokMck(e.inputs.OPERAND1) && litOf(e.inputs.OPERAND2) === ')')
         || (tokMck(e.inputs.OPERAND2) && litOf(e.inputs.OPERAND1) === ')'));
    })());
  if (closeIf.length !== 1) throw new Error('[P124] chain splitter closer = ' + closeIf.length);
  // `}` closes a `{` only when one is open in *this* range: methodcall2 hands methodcall the
  // span starting at the receiver's last token, which can be the `}` of a literal receiver.
  insertBeforeStmt(closeIf[0], [
    IF(AND(EQ(item('Tok', VAR('mck')), txt('}')), GT(VAR('mcdepth'), num(0))), [chgV('mcdepth', num(-1))])
  ]);
  console.log('[P124] chain splitter counts } as a closer');

  // ---------- (h) rightside: `a | b`, `a & b`, `a - b`, `a ^ b`
  const rs = inDef('rightside %s %s %s %s %s');
  // vtsave is rightside's own copy of the operand type: our set blocks rewrite vtype (a
  // comparison answers with a bool), so the guards must not look at the live variable
  const bothSets = () => AND(EQ(VAR('lt2'), txt('E')), EQ(VAR('evtype'), txt('E')));
  const hasOp = (cond, lit) => [...reach(cond)].some((x) => isArgEq([2, x], 'op', lit));
  const dotCount = (cond) => [...reach(cond)].filter((x) => isDotContains([2, x])).length;
  // the numeric branch (op in -,*,/,//,%) and the bitwise branch (&,|,^) must leave set-set alone
  const numeric = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && hasOp(b.inputs.CONDITION[1], '-') && hasOp(b.inputs.CONDITION[1], '%') && dotCount(b.inputs.CONDITION[1]) === 0);
  if (numeric.length !== 1) throw new Error('[P124] numeric branch = ' + numeric.length);
  const bitwise = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && hasOp(b.inputs.CONDITION[1], '&') && hasOp(b.inputs.CONDITION[1], '^') && dotCount(b.inputs.CONDITION[1]) === 0);
  if (bitwise.length !== 1) throw new Error('[P124] bitwise branch = ' + bitwise.length);
  for (const id of [numeric[0], bitwise[0]]) {
    const cond = BL()[id].inputs.CONDITION[1];
    replaceExpr(cond, () => AND(cond, NOT(bothSets())));
  }
  // the float probes (P74's two, plus the numeric mkfloat) must not look at a set value either
  const probes = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && dotCount(b.inputs.CONDITION[1]) === 2 && !hasOp(b.inputs.CONDITION[1], '-'));
  const numProbe = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && dotCount(b.inputs.CONDITION[1]) === 2 && hasOp(b.inputs.CONDITION[1], '-'));
  if (probes.length !== 2) throw new Error('[P124] float probes = ' + probes.length);
  if (numProbe.length !== 1) throw new Error('[P124] numeric float probe = ' + numProbe.length);
  for (const id of [...probes, ...numProbe]) {
    const cond = BL()[id].inputs.CONDITION[1];
    replaceExpr(cond, () => AND(cond, NOT(bothSets())));
  }
  const setOp = IF(AND(OR(OR(EQ(argOf('op'), txt('|')), EQ(argOf('op'), txt('&'))),
    OR(EQ(argOf('op'), txt('-')), EQ(argOf('op'), txt('^')))), bothSets()), [
    callProc('setop %s %s %s', [argOf('op'), argOf('leftval'), VAR('ev')])
  ]);
  insertBeforeStmt(numeric[0], [setOp]);
  // ---------- (h2) comparisons of two sets: equality and the subset relations
  // the plain comparison compares the two encoded runs, so `{1, 2} == {2, 1}` said False.
  // Everything here follows from one intersection: |a & b| == |a| means a <= b.
  // the operator branches live inside rightside's `error == ""` guard; restrict the search to
  // that chain, because the block that *combines* the six tests lives inside the branch itself
  const guard = find(rs, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && (() => { let cur = b.inputs.SUBSTACK[1]; while (cur) { if (cur === numeric[0]) return true; cur = BL()[cur].next; } return false; })());
  if (guard.length !== 1) throw new Error('[P124] rightside op guard = ' + guard.length);
  const rsTop = (() => { const out = []; let cur = BL()[guard[0]].inputs.SUBSTACK[1]; while (cur) { out.push(cur); cur = BL()[cur].next; } return out; })();
  const cmp = find(rsTop, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && hasOp(b.inputs.CONDITION[1], '==') && hasOp(b.inputs.CONDITION[1], '!=')
    && hasOp(b.inputs.CONDITION[1], '<') && hasOp(b.inputs.CONDITION[1], '>')
    && hasOp(b.inputs.CONDITION[1], '<=') && hasOp(b.inputs.CONDITION[1], '>=') && dotCount(b.inputs.CONDITION[1]) === 0);
  if (cmp.length !== 1) throw new Error('[P124] comparison branch = ' + cmp.length + ' [' + cmp.join(',') + ']');
  const isOp = (op) => EQ(argOf('op'), txt(op));
  const setCmp = IF(AND(OR(OR(isOp('=='), isOp('!=')), OR(OR(isOp('<'), isOp('<=')), OR(isOp('>'), isOp('>=')))), bothSets()), [
    setV('srb', VAR('ev')),
    callProc('setfilter %s %s %s', [argOf('leftval'), VAR('srb'), num(1)]),
    callProc('listlen %s', [VAR('ev')]),
    setV('scn', VAR('ev')),
    callProc('listlen %s', [argOf('leftval')]),
    setV('sna', VAR('ev')),
    callProc('listlen %s', [VAR('srb')]),
    setV('snb', VAR('ev')),
    setV('ev', num(0)),
    IF(OR(OR(isOp('=='), isOp('>=')), isOp('>')),
      [IF(EQ(VAR('scn'), VAR('snb')), [setV('ev', num(1))])]),
    IF(OR(OR(isOp('=='), isOp('<=')), isOp('<')),
      [IF(EQ(VAR('scn'), VAR('sna')), [setV('ev', num(1))])]),
    IF(isOp('=='), [IF(NOT(EQ(VAR('sna'), VAR('snb'))), [setV('ev', num(0))])]),
    IF(isOp('!='), [
      IFELSE(AND(EQ(VAR('scn'), VAR('sna')), EQ(VAR('sna'), VAR('snb'))),
        [setV('ev', num(0))], [setV('ev', num(1))])
    ]),
    IF(OR(isOp('<'), isOp('>')), [IF(EQ(VAR('sna'), VAR('snb')), [setV('ev', num(0))])]),
    setV('evtype', txt('B'))
  ]);
  // here (and only here) the guard must use the *saved* operand type: the block above answers with
  // a bool, so the live vtype is no longer 'E' by the time this branch is tested
  const cmpCond = BL()[cmp[0]].inputs.CONDITION[1];
  replaceExpr(cmpCond, () => AND(cmpCond, NOT(AND(EQ(VAR('lt2'), txt('E')), EQ(VAR('evtsave'), txt('E'))))));
  insertBeforeStmt(cmp[0], [setCmp]);
  console.log('[P124] set comparisons installed');

  // ---------- (i) set(x): the builtin, in front of list()
  const cf = inDef('callfn %s %s %s');
  const listIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && isArgEq([2, b.inputs.CONDITION[1]], 'fn', 'list'));
  if (listIf.length !== 1) throw new Error('[P124] callfn list branch = ' + listIf.length);
  const asSet = (it) => OR(OR(EQ(VAR(it), txt('L')), EQ(VAR(it), txt('T'))), OR(EQ(VAR(it), txt('E')), EQ(VAR(it), txt('G'))));
  // set('abc') -> the three characters, like list()'s own string branch
  const perChar = () => [
    setV('smb', VAR('ev')),
    setV('stacc', txt('')),
    setV('sti', num(1)),
    REPEATU(GT(VAR('sti'), lenOf(VAR('smb'))), [
      callProc('lesc %s', [letterOf(VAR('sti'), VAR('smb'))]),
      setV('stacc', enc(VAR('stacc'), txt('S'), VAR('ev'))),
      chgV('sti', num(1))
    ]),
    setV('ev', VAR('stacc')), setV('evtype', txt('E')),
    callProc('setnorm %s', [VAR('ev')])
  ];
  insertBeforeStmt(listIf[0], [
    IF(EQ(argOf('fn'), txt('set')), [
      IFELSE(asSet('evtype'), [
        callProc('setnorm %s', [VAR('ev')])
      ], [
        IFELSE(EQ(VAR('evtype'), txt('S')), perChar(),
          [FAIL('TypeError: set() requires an iterable')])
      ]),
      setV('pending', num(1))
    ])
  ]);
  console.log('[P124] set() builtin installed');

  // ---------- (j) P54's alias propagation also covers a set
  const asg = inDef('assign %s %s %s');
  const listAlias = find(asg, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => isArgEq([2, x], 'vt', 'L')));
  if (listAlias.length !== 1) throw new Error('[P124] assign alias guard = ' + listAlias.length);
  const aliasEq = [...reach(BL()[listAlias[0]].inputs.CONDITION[1])].find((x) => isArgEq([2, x], 'vt', 'L'));
  replaceExpr(aliasEq, () => OR(aliasEq, EQ(argOf('vt'), txt('E'))));
  // and `y = x` records the alias for a set too
  const ex = inDef('execute');
  const aliasRec = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => isVarEq([2, x], 'evtype', 'L'))
    && [...reach(b.inputs.CONDITION[1])].some((x) => isVarEq([2, x], 'count', '3')));
  if (aliasRec.length !== 1) throw new Error('[P124] execute alias recording = ' + aliasRec.length);
  const evEq = [...reach(BL()[aliasRec[0]].inputs.CONDITION[1])].filter((x) => isVarEq([2, x], 'evtype', 'L'));
  if (evEq.length !== 1) throw new Error('[P124] execute evtype==L test = ' + evEq.length);
  replaceExpr(evEq[0], () => OR(evEq[0], EQ(VAR('evtype'), txt('E'))));
  console.log('[P124] set aliases recorded');

  // ---------- (k) two small fidelities the new surface exposed
  // an empty set prints `set()`, not `{}` (which is a dict literal in Python)
  const sfHead = BL()[defIdOf('setfmt %s')].next;
  if (!sfHead) throw new Error('[P124] setfmt body');
  insertBeforeStmt(sfHead, [
    callProc('listlen %s', [argOf('s')]),
    IF(EQ(VAR('ev'), num(0)), [setV('ev', txt('set()')), setV('evtype', txt('S')), STOPTHIS()])
  ]);
  // list.copy() -- `x.copy()` answered "object has no attribute 'copy'"
  const appendIf = find(mc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && isVarEq([2, b.inputs.CONDITION[1]], 'lmeth', 'append'));
  if (appendIf.length !== 1) throw new Error('[P124] list append branch = ' + appendIf.length);
  insertBeforeStmt(appendIf[0], [
    IF(AND(EQ(VAR('xb'), txt('L')), EQ(VAR('lmeth'), txt('copy'))), [
      setV('ev', VAR('xa')), setV('evtype', txt('L')), STOPTHIS()
    ])
  ]);
  console.log('[P124] empty set prints set(), list.copy() works');
});

// ---- P125: multi-clause comprehensions -- [e for a in A for b in B if c] (and genexps) ----
//
// complist() understood exactly one `for`: it scanned for the first depth-0 `for`, treated
// everything after `in` (up to an optional `if`) as the iterable and everything before the `for`
// as the element expression.  A second `for` therefore stayed inside the "iterable" part --
// `[x * y for x in range(3) for y in range(2)]` handed `range(3) for y in range(2)` to eval,
// which walked the brackets and died with `SyntaxError: parentheses`.
//
// CPython reads the clause list left to right, so the fix is a recursion: one procedure per
// clause (`cdo`), which finds the next depth-0 `for`/`if`, evaluates that clause and calls
// itself for the rest.  The element expression is always the token range before the *first*
// `for`, so it travels as a separate `lo..be` pair; `if` filters evaluate at the leaves, where
// every binding is in scope.
//
// A recursive call runs a whole inner comprehension, so it clobbers every global the outer loop
// is still counting with -- and `cacc` is *shared* (it is one accumulator for the whole
// comprehension), which rules out reusing P98's csave/crestore (that saves and restores cacc
// too).  `csp`/`crp` push and pop exactly the loop state, leaving the accumulator alone.
//
// The same walk covers `{k: v for ...}` (the leaf splits the body at its depth-0 colon when the
// `dict` flag is set; complistD is re-pointed at the shared driver, which also gives dict
// comprehensions their second `for`) and bare generator expressions (`sum(x for x in xs)`, which
// eval now routes here -- MiniPy materialises them eagerly, like enumerate/zip).
patch('P125 multi-clause comprehensions', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const tokAt = (x) => item('Tok', x);
  const kindAt = (x) => item('Kind', x);
  const enc = (acc, tv, vv) => JOIN(JOIN(JOIN(acc, VAR('lsep')), tv), vv);
  const F = (v) => VAR(v);
  const CLAUSE = ['cdd', 'cci', 'cqq', 'cend', 'cdict', 'cdsub', 'dln', 'dli', 'dlj', 'dlf', 'dlk', 'dlkt', 'dlks', 'dlvv', 'dlvt', 'dlacc'];
  // everything a nested comprehension would otherwise steal from the running loop
  const LOOPSTATE = ['cdd', 'cci', 'cqq', 'cend', 'cdict', 'cdsub',
    'cv', 'cstop', 'cstep', 'clist', 'cltyp', 'cn', 'cqidx', 'cev', 'cet', 'cdep', 'ck'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of CLAUSE) if (taken.has(n)) throw new Error('[P125] variable name taken: ' + n);
  for (const v of CLAUSE) newVar(v, 0);
  const kwAt = (word, idx) => AND(EQ(kindAt(idx), txt('I')), EQ(tokAt(idx), txt(word)));
  const depthStep = (idx, onOpen, onClose) => [
    IF(OR(EQ(tokAt(idx), txt('(')), OR(EQ(tokAt(idx), txt('[')), EQ(tokAt(idx), txt('{')))), [chgV(onOpen, num(1))]),
    IF(OR(EQ(tokAt(idx), txt(')')), OR(EQ(tokAt(idx), txt(']')), EQ(tokAt(idx), txt('}')))), [chgV(onClose, num(-1))])
  ];
  // P98 wraps every eval in a comprehension with csave/crestore; the new scratch must be in that
  // save set or a nested comprehension inside an element expression clobbers the clause state
  {
    const sv = defIdOf('csave');
    let t = sv;
    while (BL()[t].next) t = BL()[t].next;
    spliceAfter(t, chain(CLAUSE.map((v) => addTo('VStack', VAR(v)))));
    const rs = defIdOf('crestore');
    const rsFirst = BL()[rs].next;
    if (!rsFirst) throw new Error('[P125] crestore has no body');
    insertBeforeStmt(rsFirst, [...CLAUSE].reverse().flatMap((v) => [setV(v, item('VStack', llen('VStack'))), delLast('VStack')]));
    console.log('[P125] csave/crestore know the clause scratch');
  }
  // re-entrancy for this patch's own eval sites
  const ev2 = (a, b) => [callProc('csave'), callProc('eval %s %s', [a, b]), callProc('crestore')];
  // the loop state around a recursive call (the accumulator deliberately stays shared)
  const sp = newProc('csp', []);
  attachBody(sp.defId, LOOPSTATE.map((v) => addTo('VStack', VAR(v))));
  const rp = newProc('crp', []);
  attachBody(rp.defId, [...LOOPSTATE].reverse().flatMap((v) => [setV(v, item('VStack', llen('VStack'))), delLast('VStack')]));
  const recurse = (pos) => [callProc('csp'), callProc('cdo %s %s %s %s %s',
    [argOf('lo'), argOf('be'), argOf('hi'), pos, F('cdict')]), callProc('crp')];

  // ---------- (a) crng <lo> <hi>: parse `range(...)`'s arguments -> cv / cstop / cstep
  const rg = newProc('crng %s %s', ['lo', 'hi']);
  attachBody(rg.defId, [
    clearL('CComm'), setV('cdep', num(0)), setV('ck', argOf('lo')),
    REPEATU(GT(F('ck'), argOf('hi')), [
      ...depthStep(F('ck'), 'cdep', 'cdep'),
      IF(AND(EQ(F('cdep'), num(0)), EQ(tokAt(F('ck')), txt(','))), [addTo('CComm', F('ck'))]),
      chgV('ck', num(1))
    ]),
    setV('cn', llen('CComm')),
    IFELSE(EQ(F('cn'), num(0)), [
      callProc('eval %s %s', [argOf('lo'), argOf('hi')]),
      setV('cv', num(0)), setV('cstop', F('ev')), setV('cstep', num(1))
    ], [
      IFELSE(EQ(F('cn'), num(1)), [
        ...ev2(argOf('lo'), SUB(item('CComm', num(1)), num(1))),
        setV('cv', F('ev')),
        ...ev2(ADD(item('CComm', num(1)), num(1)), argOf('hi')),
        setV('cstop', F('ev')), setV('cstep', num(1))
      ], [
        ...ev2(argOf('lo'), SUB(item('CComm', num(1)), num(1))),
        setV('cv', F('ev')),
        ...ev2(ADD(item('CComm', num(1)), num(1)), SUB(item('CComm', num(2)), num(1))),
        setV('cstop', F('ev')),
        ...ev2(ADD(item('CComm', num(2)), num(1)), argOf('hi')),
        setV('cstep', F('ev'))
      ])
    ]),
    IF(EQ(F('cstep'), num(0)), [FAIL(txt('ValueError: range step is zero')), STOPTHIS()])
  ]);
  console.log('[P125] range header parser installed');

  // ---------- (b) cdo <lo> <be> <hi> <pos> <dict>
  const cd = newProc('cdo %s %s %s %s %s', ['lo', 'be', 'hi', 'pos', 'dict']);
  // find the next depth-0 `for` / `if` at or after `fromExpr`, answer in cqq (0 = none)
  const findClause = (fromExpr) => [
    setV('cqq', num(0)), setV('cdd', num(0)), setV('cci', fromExpr),
    REPEATU(GT(F('cci'), argOf('hi')), [
      ...depthStep(F('cci'), 'cdd', 'cdd'),
      IF(AND(EQ(F('cdd'), num(0)), AND(EQ(F('cqq'), num(0)),
        OR(kwAt('for', F('cci')), kwAt('if', F('cci'))))), [setV('cqq', F('cci')), setV('cci', argOf('hi'))]),
      chgV('cci', num(1))
    ])
  ];
  // one accumulator record: escape the value, then append type + text
  const one = () => [callProc('lesc %s', [F('ev')]), setV('cacc', enc(F('cacc'), F('evtype'), F('ev')))];
  const leafBody = () => [
    IFELSE(EQ(F('cdict'), num(0)), [
      ...ev2(argOf('lo'), argOf('be')),
      ...one()
    ], [
      // {k: v ...}: split at the body's first depth-0 colon
      setV('cdsub', num(0)), setV('cdd', num(0)), setV('cci', argOf('lo')),
      REPEATU(GT(F('cci'), argOf('be')), [
        ...depthStep(F('cci'), 'cdd', 'cdd'),
        IF(AND(EQ(F('cdd'), num(0)), AND(EQ(F('cdsub'), num(0)), EQ(tokAt(F('cci')), txt(':')))), [setV('cdsub', F('cci'))]),
        chgV('cci', num(1))
      ]),
      IFELSE(EQ(F('cdsub'), num(0)), [
        ...ev2(argOf('lo'), argOf('be')),
        ...one()
      ], [
        ...ev2(argOf('lo'), SUB(F('cdsub'), num(1))),
        ...one(),
        ...ev2(ADD(F('cdsub'), num(1)), argOf('be')),
        ...one()
      ])
    ])
  ];
  // walk an already-evaluated iterable (clist/cltyp) and recurse once per element
  const walkIterable = () => [
    IF(NOT(OR(OR(EQ(F('cltyp'), txt('L')), EQ(F('cltyp'), txt('S'))), OR(EQ(F('cltyp'), txt('E')), EQ(F('cltyp'), txt('T'))))),
      [FAIL(txt('TypeError: comprehension needs an iterable')), STOPTHIS()]),
    IFELSE(OR(OR(EQ(F('cltyp'), txt('L')), EQ(F('cltyp'), txt('E'))), EQ(F('cltyp'), txt('T'))), [
      callProc('listlen %s', [F('clist')]),
      setV('cn', F('ev')), setV('cqidx', num(1)),
      REPEATU(GT(F('cqidx'), F('cn')), [
        callProc('listitem %s %s', [F('clist'), F('cqidx')]),
        setV('cev', F('ev')), setV('cet', F('evtype')),
        callProc('assign %s %s %s', [tokAt(ADD(F('cqq'), num(1))), F('cev'), F('cet')]),
        ...recurse(ADD(F('cend'), num(1))),
        chgV('cqidx', num(1))
      ])
    ], [
      setV('cn', lenOf(F('clist'))), setV('cqidx', num(1)),
      REPEATU(GT(F('cqidx'), F('cn')), [
        callProc('assign %s %s %s', [tokAt(ADD(F('cqq'), num(1))), letterOf(F('cqidx'), F('clist')), txt('S')]),
        ...recurse(ADD(F('cend'), num(1))),
        chgV('cqidx', num(1))
      ])
    ])
  ];
  attachBody(cd.defId, [
    ...findClause(argOf('pos')),
    IFELSE(EQ(F('cqq'), num(0)), leafBody(), [
      // the clause runs up to just before the next clause
      setV('cend', argOf('hi')),
      setV('cdd', num(0)), setV('cci', ADD(F('cqq'), num(1))),
      REPEATU(GT(F('cci'), argOf('hi')), [
        ...depthStep(F('cci'), 'cdd', 'cdd'),
        IF(AND(EQ(F('cdd'), num(0)), AND(EQ(F('cend'), argOf('hi')),
          OR(kwAt('for', F('cci')), kwAt('if', F('cci'))))), [setV('cend', SUB(F('cci'), num(1))), setV('cci', argOf('hi'))]),
        chgV('cci', num(1))
      ]),
      IFELSE(kwAt('if', F('cqq')), [
        // filter: evaluate it and, when it holds, carry on with the remaining clauses
        ...ev2(ADD(F('cqq'), num(1)), F('cend')),
        callProc('truth %s %s', [F('ev'), F('evtype')]),
        IF(EQ(F('truthv'), num(1)), [...recurse(ADD(F('cend'), num(1)))])
      ], [
        IF(NOT(AND(EQ(kindAt(ADD(F('cqq'), num(1))), txt('I')), EQ(tokAt(ADD(F('cqq'), num(2))), txt('in')))),
          [FAIL(txt('SyntaxError: for <name> in ...')), STOPTHIS()]),
        IFELSE(AND(EQ(tokAt(ADD(F('cqq'), num(3))), txt('range')),
          AND(EQ(tokAt(ADD(F('cqq'), num(4))), txt('(')), EQ(tokAt(F('cend')), txt(')')))), [
          // range(...) iterates arithmetically, so a later clause can depend on an earlier one
          callProc('crng %s %s', [ADD(F('cqq'), num(5)), SUB(F('cend'), num(1))]),
          REPEATU(OR(AND(GT(F('cstep'), num(0)), NOT(LT(F('cv'), F('cstop')))),
                     AND(LT(F('cstep'), num(0)), NOT(GT(F('cv'), F('cstop'))))), [
            callProc('assign %s %s %s', [tokAt(ADD(F('cqq'), num(1))), F('cv'), txt('N')]),
            ...recurse(ADD(F('cend'), num(1))),
            chgV('cv', F('cstep'))
          ])
        ], [
          ...ev2(ADD(F('cqq'), num(3)), F('cend')),
          setV('clist', F('ev')), setV('cltyp', F('evtype')),
          ...walkIterable()
        ])
      ])
    ])
  ]);
  console.log('[P125] clause driver installed');

  // ---------- (c) dlast <d>: a dict comprehension must overwrite a repeated key, not append it
  // (`{x: y for x in range(2) for y in range(2)}` is `{0: 1, 1: 1}`, not four pairs).  Rebuilding
  // the run and keeping the *last* record of each key matches both the value and the key order.
  const dl = newProc('dlast %s', ['d']);
  const dropAt = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(VAR('found'), [10, '']) } });
  attachBody(dl.defId, [
    callProc('listlen %s', [argOf('d')]), setV('dln', F('ev')),
    setV('dlacc', txt('')), setV('dli', num(1)),
    REPEATU(GT(F('dli'), F('dln')), [
      callProc('listitem %s %s', [argOf('d'), F('dli')]),
      setV('dlk', F('ev')), setV('dlkt', F('evtype')),
      setV('dlf', num(0)), setV('dlj', ADD(F('dli'), num(2))),
      REPEATU(OR(GT(F('dlj'), F('dln')), EQ(F('dlf'), num(1))), [
        callProc('listitem %s %s', [argOf('d'), F('dlj')]),
        IF(EQ(F('evtype'), F('dlkt')), [
          IFELSE(EQ(F('dlkt'), txt('S')), [
            callProc('compareText %s %s', [F('ev'), F('dlk')]),
            IF(EQ(F('cmp'), num(0)), [setV('dlf', num(1))])
          ], [
            IF(EQ(F('ev'), F('dlk')), [setV('dlf', num(1))])
          ])
        ]),
        chgV('dlj', num(2))
      ]),
      IF(EQ(F('dlf'), num(0)), [
        callProc('lesc %s', [F('dlk')]), setV('dlks', F('ev')),
        callProc('listitem %s %s', [argOf('d'), ADD(F('dli'), num(1))]),
        setV('dlvv', F('ev')), setV('dlvt', F('evtype')),
        callProc('lesc %s', [F('dlvv')]),
        setV('dlacc', enc(F('dlacc'), F('dlkt'), F('dlks'))),
        setV('dlacc', enc(F('dlacc'), F('dlvt'), F('ev')))
      ]),
      chgV('dli', num(2))
    ]),
    setV('ev', F('dlacc')), setV('evtype', txt('D'))
  ]);
  console.log('[P125] dict comprehension keeps the last value per key');

  // ---------- (d) both comprehension drivers go through cdo
  // P60 saved the loop name's old binding around the comprehension and put it back afterwards
  // (or dropped the row it created); replacing complist's body drops that, so it is re-applied.
  const scopeSave = () => [
    setV('c1n', item('Tok', ADD(F('cfor'), num(1)))),
    callProc('lookup %s', [F('c1n')]),
    setV('c1s', F('found')),
    IF(GT(F('c1s'), num(0)), [
      setV('c1v', item('Values', F('c1s'))),
      setV('c1t', item('Types', F('c1s')))
    ])
  ];
  const scopeRestore = () => [
    IFELSE(EQ(F('c1s'), num(0)), [
      callProc('lookup %s', [F('c1n')]),
      IF(GT(F('found'), num(0)), [dropAt('Names'), dropAt('Values'), dropAt('Types'), dropAt('Show')])
    ], [
      callProc('assign %s %s %s', [F('c1n'), F('c1v'), F('c1t')])
    ])
  ];
  const driver = (isdict, tag) => [
    setV('cfor', num(0)), setV('cdd', num(0)), setV('cci', argOf('lo')),
    REPEATU(GT(F('cci'), argOf('hi')), [
      ...depthStep(F('cci'), 'cdd', 'cdd'),
      IF(AND(EQ(F('cdd'), num(0)), AND(EQ(F('cfor'), num(0)), kwAt('for', F('cci')))), [setV('cfor', F('cci'))]),
      chgV('cci', num(1))
    ]),
    IF(EQ(F('cfor'), num(0)), [FAIL(txt('SyntaxError: comprehension needs for')), STOPTHIS()]),
    setV('cacc', txt('')), setV('cdict', num(isdict)),
    ...scopeSave(),
    callProc('cdo %s %s %s %s %s', [argOf('lo'), SUB(F('cfor'), num(1)), argOf('hi'), F('cfor'), num(isdict)]),
    ...scopeRestore(),
    IF(EQ(F('cdict'), num(1)), [callProc('dlast %s', [F('cacc')]), setV('cacc', F('ev'))]),
    setV('ev', F('cacc')), setV('evtype', txt(tag))
  ];
  attachBody(defIdOf('complist %s %s'), driver(0, 'L'));
  attachBody(defIdOf('complistD %s %s'), driver(1, 'D'));
  console.log('[P125] list and dict comprehensions use the shared driver');
  // ---------- (e) `x in (a, b)` -- a tuple is encoded exactly like a list, but the `in`
  // operator's type chain only knew L/S/D/E, so `x in (1, 2)` said "in requires strings"
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const isVarEq = (b, name, lit) => !!b && b.opcode === 'operator_equals'
    && ((varName(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit)
     || (varName(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit));
  const rsDef = inDef('rightside %s %s %s %s %s');
  const argNameAt = (d) => { const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null; return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null; };
  const hasOp = (cond, lit) => [...reach(cond)].some((x) => { const e = BL()[x]; return !!e && e.opcode === 'operator_equals' && ((argNameAt(e.inputs.OPERAND1) === 'op' && litOf(e.inputs.OPERAND2) === lit) || (argNameAt(e.inputs.OPERAND2) === 'op' && litOf(e.inputs.OPERAND1) === lit)); });
  const inBr = find(rsDef, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && hasOp(b.inputs.CONDITION[1], 'in') && hasOp(b.inputs.CONDITION[1], 'notin'));
  if (inBr.length !== 1) throw new Error('[P125] in-operator branch = ' + inBr.length);
  const tupleIf = find(reach(inBr[0]), (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && isVarEq(BL()[b.inputs.CONDITION[1]], 'evtype', 'L'));
  if (tupleIf.length !== 1) throw new Error('[P125] in-operator list branch = ' + tupleIf.length);
  const tupleCond = BL()[tupleIf[0]].inputs.CONDITION[1];
  replaceExpr(tupleCond, () => OR(tupleCond, EQ(VAR('evtype'), txt('T'))));
  console.log('[P125] `in` accepts a tuple');

});

// ---- P126: generator expressions, and unpacking one (v4.53) ----
//
// `f(x for x in xs)` never reached the comprehension machinery: eval's operator scan finds the
// top-level `in` first and evaluates `x for x` as its left operand, which dies with
// `SyntaxError: expression`.  Measured with a logger on eval's entry: the whole expression *is*
// handed to eval as the argument span (`eval(5, 12)` for `sum(x for x in range(3))`), and that
// call then splits into `eval(5, 7)` + `eval(9, 12)` -- the `for` is simply not a token the
// operator scan knows about.
//
// So the test goes at the very top of eval, in front of the ternary scan and the operator scan:
// a depth-0 `for` in the span means "this is a generator expression", and complist already knows
// how to build one (P125 made it handle any number of clauses).  MiniPy materialises the result
// eagerly, exactly like enumerate/zip: the value is a list, so `len(g)` and a second traversal
// also work, and printing it shows the elements instead of `<generator object at 0x...>`.
//
// The guard `hi - lo > 3` (a clause needs at least `x for y in z`) keeps eval's hot path cheap;
// interpSteps for fib16 stays at 6388.
//
// The second half is the same walk over a *generator value*: `for a, b in g()` said "cannot
// unpack non-iterable object" because P89's guard only accepted L/T while P97 routes the 'G'
// tag through the very same list walk.  Both unpack sites (`for ... in` and `a, b = ...`) now
// accept 'G'.
patch('P126 generator expressions', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (x) => item('Tok', x);
  const kindAt = (x) => item('Kind', x);
  const F = (v) => VAR(v);
  const kwAt = (word, idx) => AND(EQ(kindAt(idx), txt('I')), EQ(tokAt(idx), txt(word)));
  const depthStep = (idx, onOpen, onClose) => [
    IF(OR(EQ(tokAt(idx), txt('(')), OR(EQ(tokAt(idx), txt('[')), EQ(tokAt(idx), txt('{')))), [chgV(onOpen, num(1))]),
    IF(OR(EQ(tokAt(idx), txt(')')), OR(EQ(tokAt(idx), txt(']')), EQ(tokAt(idx), txt('}')))), [chgV(onClose, num(-1))])
  ];

  // ---------- (a) eval: a bare `expr for x in xs` is a comprehension
  // cqq/cdd/cci come from P125 (the clause scanner); they are already declared there
  const evHead = BL()[defIdOf('eval %s %s')].next;
  if (!evHead) throw new Error('[P126] eval has no body');
  const genScan = [
    setV('cqq', num(0)), setV('cdd', num(0)), setV('cci', argOf('lo')),
    REPEATU(GT(F('cci'), argOf('hi')), [
      ...depthStep(F('cci'), 'cdd', 'cdd'),
      IF(AND(EQ(F('cdd'), num(0)), AND(EQ(F('cqq'), num(0)), kwAt('for', F('cci')))), [setV('cqq', F('cci')), setV('cci', argOf('hi'))]),
      chgV('cci', num(1))
    ])
  ];
  insertBeforeStmt(evHead, [
    IF(GT(SUB(argOf('hi'), argOf('lo')), num(3)), [
      ...genScan,
      IF(GT(F('cqq'), num(0)), [
        callProc('complist %s %s', [argOf('lo'), argOf('hi')]),
        STOPTHIS()
      ])
    ])
  ]);
  console.log('[P126] generator expressions go through complist');

  // ---------- (b) `for a, b in <generator>` / `a, b = <generator>`
  const unpGuard = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && Object.values(b.inputs || {}).some((v) => Array.isArray(v[1]) && v[1][1] === 'TypeError: cannot unpack non-iterable object'));
  // two sites: `a, b = <container>` (assignlist) and `for a, b in <container>` (forloop)
  if (unpGuard.length !== 2) throw new Error('[P126] unpack guard fails = ' + unpGuard.length);
  for (const gid of unpGuard) {
    const unpIf = ancestor(gid, (b) => b.opcode === 'control_if');
    const n = BL()[unpIf].inputs.CONDITION;
    const q = BL()[n[1]];
    const unpOr = (q && q.opcode === 'operator_not') ? q.inputs.OPERAND[1] : null;
    if (!unpOr) throw new Error('[P126] unpack guard shape');
    replaceExpr(unpOr, () => OR(unpOr, EQ(VAR('evtype'), txt('G'))));
  }
  console.log('[P126] unpacking accepts a generator');
});

// ---- P127: super(), class attribute inheritance, multiple inheritance (v4.54) ----
//
// P106 gave `class B(A)` method reuse by *copying* the parent's FnName entries under the child
// name, which is why `B().hi()` works -- but four things around it stayed unsupported:
//
//   * `class B(A): pass` + `print(B.n)` -> the class-attribute table (IAttr*, keyed by class name)
//     held only what the class body defined, so `B.n` said `AttributeError: n`;
//   * `super().m()` / `super().__init__(x)` -> `SyntaxError: missing expression` (nothing in eval
//     knows the token `super`);
//   * `class C(A, B):` -> the class-shape guard demanded exactly `class Name(Parent):`;
//   * and `A.hi(self)` (an unbound call through the class name) fell into the string guard.
//
// The first one follows the method trick exactly: at class-creation time copy each parent's
// IAttr rows under the child's name, left to right, so the leftmost parent wins the lookup
// (IAttr is scanned front to back) and the child's own `n = ...` line still overwrites the row
// in place (P90's class-body handler replaces when the name is already there).  Transitive
// inheritance comes for free, because a parent's copied rows are in its own table already.
//
// Two root causes surfaced while testing the above, both fixed here because super() and the
// inherited-method calls cannot work without them:
//
//   * a custom block's *arguments* are not reliable on a repeated call.  scratch-vm keeps one
//     `_argValues` object and one stack frame per block and recycles frames (`_StackFrame.reuse`
//     does not clear `executed`), so the second call of the very same `clssplit` block read the
//     first call's argument.  Symptom: `class C(A, B)` copied nothing once another class with a
//     parent had run before it in the same VM (a "contamination" that only shows up with two
//     cases in one run).  All helpers below therefore take their input through globals
//     (`cspec`, `cpar2`, `cname`, `cinst`/`cmeth`/`clo`/`chi`) instead of through arguments;
//   * `self.m(...)` raised `AttributeError: only lists have methods`.  `self` is the Scratch
//     variable callmeth/callcls set, not an ordinary MiniPy variable, so methodcall's receiver
//     evaluation yields `0`/type `N` and the type guards (`D`/`E`/list-only) fire *before* the
//     instance dispatch.  eval now remembers the receiver token (`cselfr`) and methodcall puts
//     the running instance back before those guards run.
//
// `self.m()` also needs P106's class-method copy: callmeth looks the method up as
// `InstCls[inst] + '.' + name`, and the copy is what makes an inherited method reachable there.
//
// `ClsPar` (parallel to ClsName) records each class's comma-separated parents to drive that copy
// and `super()`.  `callcls <inst> <cls> <meth> <lo> <hi>` is callmeth with the class passed in,
// and `cmet` (the class whose method is running, saved/restored around every method call) tells
// `super()` which parent to reach for.  Multiple parents are copied right to left for *methods*
// (calluser searches FnName from the end, so the leftmost has to be copied last) and left to
// right for *attributes*.
patch('P127 super and class attributes', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const tokAt = (i) => item('Tok', i);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const VARS = ['cmet', 'cps', 'csi', 'cai', 'cch', 'cpiece', 'cup', 'ctmp', 'cpv',
    'cspec', 'cpar2', 'cname',
    'cinst', 'cmeth', 'clo', 'chi', 'cselfr'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P127] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  B.addList(IT, 'ClsPar', []);
  B.addList(IT, 'CQ2', []);
  // split a comma-separated string into list entries (class names have no spaces in them)
  const splitInto = (list, sExpr, pieceVar) => [
    clearL(list), setV(pieceVar, txt('')), setV('csi', num(1)),
    REPEATU(GT(VAR('csi'), ADD(lenOf(sExpr), num(1))), [
      setV('cch', letterOf(VAR('csi'), sExpr)),
      IFELSE(OR(EQ(VAR('csi'), ADD(lenOf(sExpr), num(1))), EQ(VAR('cch'), txt(','))), [
        IF(NOT(EQ(VAR(pieceVar), txt(''))), [addTo(list, VAR(pieceVar))]),
        setV(pieceVar, txt(''))
      ], [
        setV(pieceVar, JOIN(VAR(pieceVar), VAR('cch')))
      ]),
      chgV('csi', num(1))
    ])
  ];

  // ---------- (a) clscopy <par>: copy the parent's methods under the child's name
  const cp = newProc('clscopy', []);
  attachBody(cp.defId, [
    setV('cpn2', llen('FnName')),
    setV('cpk', num(1)),
    REPEATU(GT(VAR('cpk'), VAR('cpn2')), [
      setV('cpn', item('FnName', VAR('cpk'))),
      IF(GT(lenOf(VAR('cpn')), ADD(lenOf(VAR('cpar2')), num(1))), [
        callProc('substr %s %s %s', [VAR('cpn'), num(1), lenOf(VAR('cpar2'))]),
        setV('cpp', VAR('ev')),
        IF(AND(EQ(VAR('cpp'), VAR('cpar2')), EQ(letterOf(ADD(lenOf(VAR('cpar2')), num(1)), VAR('cpn')), txt('.'))), [
          callProc('substr %s %s %s', [VAR('cpn'), ADD(lenOf(VAR('cpar2')), num(2)), lenOf(VAR('cpn'))]),
          setV('cpm', VAR('ev')),
          addTo('FnName', JOIN(JOIN(VAR('ccls'), txt('.')), VAR('cpm'))),
          addTo('FnPN', item('FnPN', VAR('cpk'))),
          addTo('FnPO', item('FnPO', VAR('cpk'))),
          addTo('FnPar', item('FnPar', VAR('cpk'))),
          addTo('FnDef', item('FnDef', VAR('cpk'))),
          addTo('FnStart', item('FnStart', VAR('cpk'))),
          addTo('FnEnd', item('FnEnd', VAR('cpk'))),
          addTo('FnKind', item('FnKind', VAR('cpk'))),
          addTo('FnLine', item('FnLine', VAR('cpk'))),
          addTo('FnTlo', item('FnTlo', VAR('cpk'))),
          addTo('FnThi', item('FnThi', VAR('cpk')))
        ])
      ]),
      chgV('cpk', num(1))
    ])
  ]);

  // ---------- (b) clscopyattr <par>: copy the parent's class attributes under the child's name
  const ca = newProc('clscopyattr', []);
  attachBody(ca.defId, [
    setV('cps', llen('IAttrId')),
    setV('cai', num(1)),
    REPEATU(GT(VAR('cai'), VAR('cps')), [
      IF(EQ(item('IAttrId', VAR('cai')), VAR('cpar2')), [
        addTo('IAttrId', VAR('ccls')),
        addTo('IAttrName', item('IAttrName', VAR('cai'))),
        addTo('IAttrVal', item('IAttrVal', VAR('cai'))),
        addTo('IAttrType', item('IAttrType', VAR('cai')))
      ]),
      chgV('cai', num(1))
    ])
  ]);
  console.log('[P127] class attributes are copied from the parents');

  // ---------- (b2) clssplit <spec>: "A,B" -> the list CQ2 (used by the class branch and super())
  const sp = newProc('clssplit', []);
  attachBody(sp.defId, splitInto('CQ2', VAR('cspec'), 'cpv'));
  // ---------- (b3) clspar <cls>: a class's parents as one comma-separated string
  const cpar = newProc('clspar', []);
  attachBody(cpar.defId, [
    setV('ev', txt('')), setV('evtype', txt('S')),
    setV('ctmp', num(1)),
    REPEATU(GT(VAR('ctmp'), llen('ClsName')), [
      callProc('compareText %s %s', [item('ClsName', VAR('ctmp')), VAR('cname')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('ev', item('ClsPar', VAR('ctmp'))), setV('ctmp', llen('ClsName'))]),
      chgV('ctmp', num(1))
    ])
  ]);

  // ---------- (c) callcls <inst> <cls> <meth> <lo> <hi>
  const cc = newProc('callcls', []);
  attachBody(cc.defId, [
    setV('cfull', JOIN(JOIN(VAR('ccls'), txt('.')), VAR('cmeth'))),
    IFELSE(I('data_listcontainsitem', { fields: B.LISTF('FnName'), inputs: { ITEM: B.REP(VAR('cfull'), [10, '']) } }), [
      addTo('VStack', VAR('self')),
      setV('self', VAR('cinst')),
      callProc('assign %s %s %s', [txt('self'), VAR('cinst'), txt('O')]),
      addTo('VStack', VAR('cmet')),
      setV('cmet', VAR('ccls')),
      callProc('calluser %s %s %s', [VAR('cfull'), VAR('clo'), VAR('chi')]),
      setV('cmet', item('VStack', llen('VStack'))),
      delLast('VStack'),
      setV('clf', item('VStack', llen('VStack'))),
      delLast('VStack'),
      IFELSE(EQ(VAR('clf'), txt('')), [
        callProc('assign %s %s %s', [txt('self'), txt(''), txt('Z')])
      ], [
        callProc('assign %s %s %s', [txt('self'), VAR('clf'), txt('O')])
      ]),
      setV('self', VAR('clf'))
    ], [
      FAILB(JOIN(JOIN(VAR('ccls'), txt(' has no attribute ')), VAR('cmeth')))
    ])
  ]);
  // callmeth records the class whose method is running
  const cmDef = defIdOf('callmeth %s %s %s %s');
  const cmSet = find(reach(cmDef), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ccls');
  if (cmSet.length !== 1) throw new Error('[P127] callmeth ccls set = ' + cmSet.length);
  spliceAfter(cmSet[0], chain([addTo('VStack', VAR('cmet')), setV('cmet', VAR('ccls'))]));
  const cmSelf = find(reach(cmDef), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'self'
    && varName(b.inputs.VALUE) === 'clf');
  if (cmSelf.length !== 1) throw new Error('[P127] callmeth self restore = ' + cmSelf.length);
  spliceAfter(cmSelf[0], chain([setV('cmet', item('VStack', llen('VStack'))), delLast('VStack')]));
  // the constructor path in callfn sets cmet for __init__: the name is built in `cfull` first,
  // so anchor on that assignment (walking its expression for the literal) and take the calluser
  // call inside the following guard
  const cfDef = defIdOf('callfn %s %s %s');
  const exprHas = (id, text) => {
    const seen = new Set();
    const stack = [id];
    while (stack.length) {
      const x = stack.pop();
      if (!x || typeof x !== 'string' || seen.has(x)) continue;
      seen.add(x);
      const b = BL()[x];
      if (!b) continue;
      if (JSON.stringify(b.inputs || {}).includes(text)) return true;
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
    }
    return false;
  };
  const cfullInit = find(reach(cfDef), (b, id) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'cfull' && exprHas(id, '__init__'));
  if (cfullInit.length !== 1) throw new Error('[P127] __init__ name build = ' + cfullInit.length);
  const ctorGuard = find(reach(cfullInit[0]), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
    && typeof b.inputs.SUBSTACK[1] === 'string' && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
      const q = BL()[x];
      return q && q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'calluser %s %s %s';
    }));
  if (ctorGuard.length !== 1) throw new Error('[P127] __init__ guard = ' + ctorGuard.length);
  const ctorCall = find(reach(BL()[ctorGuard[0]].inputs.SUBSTACK[1]), (b) => b.opcode === 'procedures_call'
    && b.mutation && b.mutation.proccode === 'calluser %s %s %s');
  if (ctorCall.length !== 1) throw new Error('[P127] constructor call = ' + ctorCall.length);
  insertBeforeStmt(ctorCall[0], [addTo('VStack', VAR('cmet')), setV('cmet', argOf('fn'))]);
  spliceAfter(ctorCall[0], chain([setV('cmet', item('VStack', llen('VStack'))), delLast('VStack')]));
  console.log('[P127] callmeth and __init__ record the running class');

  // ---------- (c2) P90's class-body `name = value` handler clobbers `ck` -- the loop counter of
  // the class-body scan -- because its attribute lookup uses `ck` too.  With one class it happens
  // to be harmless (the lookup counter starts above the body line and the row it adds pushes the
  // scan past the end), but a *second* class with attributes then re-scans lines: the program
  // spins forever.  Save and restore `ck` around the handler.
  {
    const ccSav = find(allIds(), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'ccsav' && varName(b.inputs.VALUE) === 'ccls');
    if (ccSav.length !== 1) throw new Error('[P127] class-body handler = ' + ccSav.length);
    const caxSet = find(reach(ccSav[0]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'cax') [0];
    if (!caxSet) throw new Error('[P127] class-body cax = 0');
    spliceAfter(caxSet, chain([addTo('VStack', VAR('ck'))]));
    const cclsBack = find(reach(caxSet), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'ccls' && varName(b.inputs.VALUE) === 'ccsav') [0];
    if (!cclsBack) throw new Error('[P127] class-body ccls restore = 0');
    insertBeforeStmt(cclsBack, [setV('ck', item('VStack', llen('VStack'))), delLast('VStack')]);
    console.log('[P127] the class-body handler keeps its loop counter');
  }

  // ---------- (d) class statement: record the parents, accept several, copy both tables
  const ex = inDef('execute');
  const clsAdd = find(ex, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'ClsName');
  if (clsAdd.length !== 1) throw new Error('[P127] ClsName append = ' + clsAdd.length);
  spliceAfter(clsAdd[0], chain([
    IFELSE(EQ(tokAt(num(3)), txt('(')), [
      // `class B(A):` -> "A" ; `class C(A, B):` -> "A,B" (the commas are tokens too)
      setV('ctmp', txt('')),
      setV('csi', num(4)),
      REPEATU(GT(VAR('csi'), SUB(VAR('count'), num(2))), [
        setV('ctmp', JOIN(VAR('ctmp'), tokAt(VAR('csi')))),
        chgV('csi', num(1))
      ]),
      addTo('ClsPar', VAR('ctmp')),
      setV('cspec', VAR('ctmp')), callProc('clssplit', []),
      // methods: right to left, because calluser searches FnName from the end
      setV('csi', llen('CQ2')),
      REPEATU(LT(VAR('csi'), num(1)), [
        setV('cpar2', item('CQ2', VAR('csi'))), callProc('clscopy', []),
        chgV('csi', num(-1))
      ]),
      // attributes: left to right, because IAttr is scanned front to back
      setV('csi', num(1)),
      REPEATU(GT(VAR('csi'), llen('CQ2')), [
        setV('cpar2', item('CQ2', VAR('csi'))), callProc('clscopyattr', []),
        chgV('csi', num(1))
      ])
    ], [
      addTo('ClsPar', txt(''))
    ])
  ]));
  // the shape guard: `class Name(` ... `):` with any number of parents
  {
    const shapeIf = find(reach(BL()[defIdOf('execute')].next), (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((id) => {
        const q = BL()[id];
        if (!q || q.opcode !== 'operator_equals') return false;
        const itemTok = (d, lit) => {
          const bb = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
          if (!bb || bb.opcode !== 'data_itemoflist' || !bb.fields.LIST || bb.fields.LIST[0] !== 'Tok') return false;
          return litOf(bb.inputs.INDEX) === lit;
        };
        return (itemTok(q.inputs.OPERAND1, '3') && litOf(q.inputs.OPERAND2) === ':')
          || (itemTok(q.inputs.OPERAND2, '3') && litOf(q.inputs.OPERAND1) === ':');
      }));
    if (shapeIf.length !== 1) throw new Error('[P127] class shape guard = ' + shapeIf.length);
    const parShape = AND(EQ(tokAt(num(3)), txt('(')),
      AND(EQ(tokAt(SUB(VAR('count'), num(1))), txt(')')), EQ(tokAt(VAR('count')), txt(':'))));
    const orNode = [...reach(BL()[shapeIf[0]].inputs.CONDITION[1])].find((id) => {
      const q = BL()[id];
      return !!q && q.opcode === 'operator_or';
    });
    if (!orNode) throw new Error('[P127] class shape OR');
    replaceExpr(orNode, () => OR(orNode, parShape));
  }
  console.log('[P127] class Name(P1, P2): accepted');

  // ---------- (f) `self.m(...)`: inside a method `self` is the Scratch variable that
  // callmeth/callcls set; it is not an ordinary MiniPy variable, so methodcall's receiver
  // evaluation comes back as `0` with type N and the type guards fail before the instance
  // dispatch is reached.  Remember the receiver token up front (a nested methodcall may
  // re-tokenize Tok) and put the running instance back before those guards run.
  {
    const mcDef = defIdOf('methodcall %s %s');
    const mcHead = BL()[mcDef].next;
    if (!mcHead) throw new Error('[P127] methodcall has no body');
    insertBeforeStmt(mcHead, [setV('cselfr', item('Tok', argOf('lo')))]);
    const typeGuard = find(reach(mcDef), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
        const q = BL()[x];
        return !!q && q.opcode === 'procedures_call' && q.mutation
          && q.mutation.proccode === 'dictmeth %s %s %s %s %s';
      }));
    if (typeGuard.length !== 1) throw new Error('[P127] methodcall type guard = ' + typeGuard.length);
    insertBeforeStmt(typeGuard[0], [
      IF(EQ(VAR('cselfr'), txt('self')), [setV('xa', VAR('self')), setV('xb', txt('O'))])
    ]);
    console.log('[P127] self.m() reaches the instance dispatch');
  }

  // ---------- (d2) iscls <name>: case-sensitive "is this a class name?"
  const ic = newProc('iscls', []);
  attachBody(ic.defId, [
    setV('ev', num(0)), setV('evtype', txt('N')),
    setV('ctmp', num(1)),
    REPEATU(OR(GT(VAR('ctmp'), llen('ClsName')), EQ(VAR('ev'), num(1))), [
      callProc('compareText %s %s', [item('ClsName', VAR('ctmp')), VAR('cname')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('ev', num(1))]),
      chgV('ctmp', num(1))
    ])
  ]);

  // ---------- (e) eval: `super().m(args)` and `Class.m(inst)`
  const evHead = BL()[defIdOf('eval %s %s')].next;
  if (!evHead) throw new Error('[P127] eval has no body');
  const parentOf = () => [
    setV('cname', VAR('cmet')), callProc('clspar', []),
    ...splitInto('CQ2', VAR('ev'), 'cpiece'),
    IFELSE(GT(llen('CQ2'), num(0)), [setV('cup', item('CQ2', num(1)))], [setV('cup', txt(''))])
  ];
  insertBeforeStmt(evHead, [
    IF(AND(EQ(tokAt(argOf('lo')), txt('super')), AND(EQ(tokAt(ADD(argOf('lo'), num(1))), txt('(')),
      AND(EQ(tokAt(ADD(argOf('lo'), num(2))), txt(')')), AND(EQ(tokAt(ADD(argOf('lo'), num(3))), txt('.')),
        EQ(tokAt(argOf('hi')), txt(')')))))), [
      ...parentOf(),
      IF(EQ(VAR('cup'), txt('')), [FAIL(txt('TypeError: super() outside a class')), STOPTHIS()]),
      setV('ctmp', VAR('self')),
      setV('cinst', VAR('ctmp')), setV('ccls', VAR('cup')), setV('cmeth', tokAt(ADD(argOf('lo'), num(4)))),
      setV('clo', ADD(argOf('lo'), num(6))), setV('chi', SUB(argOf('hi'), num(1))), callProc('callcls', []),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ])
  ]);
  // `A.m(self)`: the receiver is a class name, so methodcall's instance dispatch never runs
  const mcIf = find(inDef('eval %s %s'), (b) => b.opcode === 'control_if_else'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
    && BL()[b.inputs.SUBSTACK[1]].mutation
    && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'methodcall %s %s');
  if (mcIf.length !== 1) throw new Error('[P127] eval methodcall branch = ' + mcIf.length);
  insertBeforeStmt(mcIf[0], [
    IF(AND(EQ(tokAt(ADD(argOf('lo'), num(1))), txt('.')), EQ(tokAt(argOf('hi')), txt(')'))), [
      setV('cname', tokAt(argOf('lo'))), callProc('iscls', []),
      IF(EQ(VAR('ev'), num(1)), [
        // The first argument is the instance; anything after the first depth-0 comma is the
        // method's own argument list.  Find that comma *before* evaluating anything: evaluating
        // the whole list would pack all the arguments into the value that becomes `self`.
        setV('csi', ADD(argOf('lo'), num(4))), setV('cch', num(0)), setV('ctmp', num(0)),
        REPEATU(GT(VAR('csi'), SUB(argOf('hi'), num(1))), [
          IF(OR(EQ(tokAt(VAR('csi')), txt('(')), OR(EQ(tokAt(VAR('csi')), txt('[')), EQ(tokAt(VAR('csi')), txt('{')))), [chgV('cch', num(1))]),
          IF(OR(EQ(tokAt(VAR('csi')), txt(')')), OR(EQ(tokAt(VAR('csi')), txt(']')), EQ(tokAt(VAR('csi')), txt('}')))), [chgV('cch', num(-1))]),
          IF(AND(EQ(VAR('cch'), num(0)), AND(EQ(VAR('ctmp'), num(0)), EQ(tokAt(VAR('csi')), txt(',')))), [
            setV('ctmp', VAR('csi'))
          ]),
          chgV('csi', num(1))
        ]),
        IFELSE(EQ(VAR('ctmp'), num(0)), [
          callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
          IF(EQ(VAR('error'), txt('')), [
            setV('cup', VAR('ev')),
            setV('cinst', VAR('cup')), setV('ccls', tokAt(argOf('lo'))), setV('cmeth', tokAt(ADD(argOf('lo'), num(2)))),
            setV('clo', num(1)), setV('chi', num(0)), callProc('callcls', [])
          ])
        ], [
          callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(VAR('ctmp'), num(1))]),
          IF(EQ(VAR('error'), txt('')), [
            setV('cup', VAR('ev')),
            setV('cinst', VAR('cup')), setV('ccls', tokAt(argOf('lo'))), setV('cmeth', tokAt(ADD(argOf('lo'), num(2)))),
            setV('clo', ADD(VAR('ctmp'), num(1))), setV('chi', SUB(argOf('hi'), num(1))), callProc('callcls', [])
          ])
        ]),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ])
  ]);
  console.log('[P127] super() and Class.m(inst) routed through callcls');

  // ---------- (g) reset the new tables at run start
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'ClsName');
  if (runInit.length !== 1) throw new Error('[P127] run init anchor = ' + runInit.length);
  spliceAfter(runInit[0], chain([clearL('ClsPar'), clearL('CQ2')]));
  console.log('[P127] super/class attributes ready');
});

// ---- P128: set() with no argument, issubset/issuperset, isinstance (v4.55) ----
//
// Three small holes left around the collection/type surface:
//
//   * `set()` (no argument) died with `SyntaxError: missing expression` -- P124's `set(x)`
//     handler lives inside callfn and reads the already-evaluated argument, so a call with an
//     empty argument range never gets there.  eval now answers `set ( )` itself, exactly the
//     way P127 answers `super()`.
//   * `s.issubset(t)` / `s.issuperset(t)`: two more entries in P124's setmeth.  A set is a
//     subset of another iff filtering it by the other (keep = 1) leaves it unchanged; the set
//     encoding is canonical (setnorm), so the two strings compare equal exactly when nothing
//     was dropped.  (Counting elements with listlen does *not* work here: the second listlen
//     call in the branch read the argument instead of the receiver -- the same
//     one-value-per-block staleness p127.txt describes.)
//   * `isinstance(x, T)`: a two-argument call, so (like `sorted(x, reverse=...)`) it never
//     reaches callfn.  The type test itself is a table over the interpreter's own type tags
//     (the same ones P76's type() prints), plus a walk up `ClsPar` for user classes.
//
// NB the helpers take their input through globals (`p2c1`/`p2c2`), not through procedure
// arguments -- see the note in p127.txt about repeated custom-block calls.
patch('P128 set(), issubset and isinstance', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const VARS = ['p2sh1', 'p2sh2', 'p2v', 'p2t', 'p2n', 'p2r', 'p2c1', 'p2c2', 'p2cur', 'p2cnt'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P128] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  const bale = () => [chgV('fnlimit', num(-1)), STOPTHIS()];
  const tok = (d) => item('Tok', d);

  // ---------- (a) setmeth: issubset / issuperset
  const smDef = defIdOf('setmeth %s %s %s %s %s');
  // the final `FAILB` of setmeth is its last top-level statement: every branch stops the script,
  // so anything that survives the method-name tests lands there (the message is a JOIN, so a
  // plain text search over the call's inputs would not find it)
  const failCall = (() => {
    const out = [];
    const seen = new Set();
    let cur = BL()[smDef].next;
    while (cur && !seen.has(cur)) {
      seen.add(cur);
      const b = BL()[cur];
      if (b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s') out.push(cur);
      cur = b.next;
    }
    return out;
  })();
  if (failCall.length !== 1) throw new Error('[P128] setmeth fail = ' + failCall.length);
  // one eval of the argument, one setfilter, then a string comparison against the receiver
  const subsetOf = (eqExpr) => [
    setV('p2sh2', argOf('rec')),
    callProc('eval %s %s', [argOf('lo'), argOf('hi')]),
    setV('p2sh1', VAR('ev')),
    callProc('setfilter %s %s %s', [VAR('p2sh2'), VAR('p2sh1'), num(1)]),
    IFELSE(EQ(VAR('ev'), eqExpr), [setV('ev', num(1))], [setV('ev', num(0))]),
    setV('evtype', txt('B')),
    STOPTHIS()
  ];
  insertBeforeStmt(failCall[0], [
    IF(EQ(argOf('meth'), txt('issubset')), subsetOf(VAR('p2sh2'))),
    // issuperset is the same test with the two sets swapped, so compare against the argument
    IF(EQ(argOf('meth'), txt('issuperset')), [
      setV('p2sh2', argOf('rec')),
      callProc('eval %s %s', [argOf('lo'), argOf('hi')]),
      setV('p2sh1', VAR('ev')),
      callProc('setfilter %s %s %s', [VAR('p2sh1'), VAR('p2sh2'), num(1)]),
      IFELSE(EQ(VAR('ev'), VAR('p2sh1')), [setV('ev', num(1))], [setV('ev', num(0))]),
      setV('evtype', txt('B')),
      STOPTHIS()
    ])
  ]);
  console.log('[P128] issubset / issuperset installed');

  // ---------- (b) isanc: is the class in p2c1 (or one of its ancestors) p2c2 ?
  // the result has to live in p2r: clspar answers through `ev`, so using `ev` as the flag would
  // end the climb after one level (and then spin until the counter guard fires)
  const ia = newProc('isanc', []);
  attachBody(ia.defId, [
    setV('p2r', num(0)), setV('p2cur', VAR('p2c1')), setV('p2cnt', num(0)),
    REPEATU(OR(GT(VAR('p2cnt'), num(24)), OR(EQ(VAR('p2r'), num(1)), EQ(VAR('p2cur'), txt('')))), [
      IF(EQ(VAR('p2cur'), VAR('p2c2')), [setV('p2r', num(1))]),
      IF(AND(EQ(VAR('p2r'), num(0)), NOT(EQ(VAR('p2cur'), txt('')))), [
        setV('cname', VAR('p2cur')), callProc('clspar', []),
        setV('cspec', VAR('ev')), callProc('clssplit', []),
        IFELSE(GT(llen('CQ2'), num(0)), [setV('p2cur', item('CQ2', num(1)))], [setV('p2cur', txt(''))])
      ]),
      chgV('p2cnt', num(1))
    ])
  ]);
  console.log('[P128] isanc registered');

  // ---------- (c) eval: `set()` and `isinstance(x, T)`, in front of the narg dispatch
  const ev2 = inDef('eval %s %s');
  const nargIf = find(ev2, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      return (varName(q.inputs.OPERAND1) === 'narg' && litOf(q.inputs.OPERAND2) === '0')
        || (varName(q.inputs.OPERAND2) === 'narg' && litOf(q.inputs.OPERAND1) === '0');
    })());
  if (nargIf.length !== 1) throw new Error('[P128] eval narg dispatch = ' + nargIf.length);
  // one test per builtin name; `int` also accepts a bool (CPython: bool is an int subclass)
  const typeIs = (name, expr) => IF(EQ(VAR('p2n'), txt(name)), [IF(expr, [setV('p2r', num(1))])]);
  const tagIs = (tag) => EQ(VAR('p2t'), txt(tag));
  insertBeforeStmt(nargIf[0], [
    IF(AND(EQ(tok(argOf('lo')), txt('set')), AND(EQ(tok(ADD(argOf('lo'), num(1))), txt('(')),
      AND(EQ(tok(ADD(argOf('lo'), num(2))), txt(')')), EQ(argOf('hi'), ADD(argOf('lo'), num(2)))))), [
      setV('ev', txt('')), setV('evtype', txt('E')),
      ...bale()
    ]),
    IF(EQ(tok(argOf('lo')), txt('isinstance')), [
      callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IFELSE(EQ(VAR('tqhcm'), num(1)), [
        // the class name has to be read *before* the argument is evaluated: a nested eval can
        // re-tokenize Tok (p90.txt has the same warning), so Tok[tqcpz + 1] would not survive it
        setV('p2n', tok(ADD(VAR('tqcpz'), num(1)))),
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('tqcpz'), num(1))]),
        IF(EQ(VAR('error'), txt('')), [
          setV('p2v', VAR('ev')), setV('p2t', VAR('evtype')),
          setV('p2r', num(0)),
          typeIs('bool', tagIs('B')),
          typeIs('int', OR(tagIs('B'), AND(tagIs('N'), NOT(strHas(VAR('p2v'), txt('.')))))),
          typeIs('float', AND(tagIs('N'), strHas(VAR('p2v'), txt('.')))),
          typeIs('str', tagIs('S')),
          typeIs('list', tagIs('L')),
          typeIs('tuple', tagIs('T')),
          typeIs('dict', tagIs('D')),
          typeIs('set', tagIs('E')),
          IF(EQ(VAR('p2n'), txt('object')), [setV('p2r', num(1))]),
          // a user class: the instance's own class, or something up its ClsPar chain
          IF(AND(tagIs('O'), EQ(VAR('p2r'), num(0))), [
            setV('p2c1', item('InstCls', VAR('p2v'))), setV('p2c2', VAR('p2n')),
            callProc('isanc', [])
          ]),
          setV('ev', VAR('p2r')), setV('evtype', txt('B'))
        ])
      ], [
        FAIL(txt('TypeError: isinstance expected 2 arguments, got 1')),
        ...bale()
      ]),
      ...bale()
    ])
  ]);
  console.log('[P128] eval: set() and isinstance() installed');
});

// ---- P129: custom exception classes -- `class MyErr(Exception)` (v4.56) ----
//
// `raise MyErr('boom')` and `except MyErr as e` already work by *name*: P51's raise branch stores the
// token after `raise` (whatever it is) and fails with "<name>: <message>", and trycatch matches a
// handler frame with `startswith(TryName)`, with '' (bare except) and 'Exception' as the two
// catch-alls.  The one thing that stood in the way was the class statement itself: P106's parent
// check demanded that the parent be a class in `ClsName`, and the builtin exception names
// (`Exception`, `ValueError`, ...) are not -- they are values of type C (P16).  So:
//
//   (a) let a builtin exception name through the parent check (nothing is copied from it, there are
//       no `Exception.method` entries);
//   (b) `except Base` also catches `Sub` -- CPython resolves the handler against the class
//       hierarchy.  The raised name is the text before the first ':' of the error message; when it
//       is a user class, walk its ClsPar chain (the `isanc` helper P128 registered).
patch('P129 custom exception classes', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const EXC = ['Exception', 'ValueError', 'TypeError', 'IndexError', 'KeyError', 'NameError', 'ZeroDivisionError',
    'AttributeError', 'RuntimeError', 'AssertionError', 'StopIteration', 'ArithmeticError', 'OverflowError'];
  const tokAt = (i) => item('Tok', i);

  // ---------- (a) the parent check accepts a builtin exception name
  const ex = inDef('execute');
  const nameFail = find(ex, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
    const d = Object.values(b.inputs || {})[0];
    const j = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return !!j && j.opcode === 'operator_join' && litOf(j.inputs.STRING1) === 'NameError: name ';
  });
  if (nameFail.length !== 1) throw new Error('[P129] class parent check = ' + nameFail.length);
  const guard = ancestor(nameFail[0], (b) => b.opcode === 'control_if');
  if (!guard || !BL()[guard].inputs.CONDITION || typeof BL()[guard].inputs.CONDITION[1] !== 'string') {
    throw new Error('[P129] class parent guard');
  }
  let isExc = null;
  for (const c of EXC) { const e = EQ(VAR('cpar'), txt(c)); isExc = isExc ? OR(isExc, e) : e; }
  const condId = BL()[guard].inputs.CONDITION[1];
  replaceExpr(condId, () => AND(condId, NOT(isExc)));
  console.log('[P129] class MyErr(Exception) accepted');

  // ---------- (b) `except Base` catches `Sub`
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p3nm', 'p3k', 'p3len', 'p3v', 'p3cls', 'p3x', 'p3k2', 'p3n2']) {
    if (taken.has(n)) throw new Error('[P129] variable name taken: ' + n);
  }
  for (const v of ['p3nm', 'p3k', 'p3len', 'p3v', 'p3cls', 'p3x', 'p3k2', 'p3n2']) newVar(v, 0);
  const pre = find(reach(defIdOf('trycatch')), (b) => b.opcode === 'procedures_call' && b.mutation
    && b.mutation.proccode === 'sprefix %s %s %s');
  if (pre.length !== 1) throw new Error('[P129] trycatch sprefix = ' + pre.length);
  const preIf = ancestor(pre[0], (b) => b.opcode === 'control_if');
  const preSub = BL()[preIf].inputs.SUBSTACK;
  if (!preSub || typeof preSub[1] !== 'string') throw new Error('[P129] trycatch sprefix substack');
  // the "matched" setter (`if ev == 1: tcl = 1`) is the last statement of that substack
  const matched = find(reach(preSub[1]), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
    && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
      const q = BL()[x];
      return !!q && q.opcode === 'data_setvariableto' && q.fields.VARIABLE && q.fields.VARIABLE[0] === 'tcl';
    }));
  if (matched.length !== 1) throw new Error('[P129] trycatch matched setter = ' + matched.length);
  // extract the raised class name: the text before the first ':' of the message
  // (sfind answers the 0-based position of the match, i.e. the length of the prefix)
  const isUserClass = [
    callProc('sfind %s %s', [VAR('error'), txt(':')]),
    setV('p3k', VAR('ev')),
    IFELSE(GT(VAR('p3k'), num(0)), [
      callProc('substr %s %s %s', [VAR('error'), num(1), VAR('p3k')]),
      setV('p3nm', VAR('ev'))
    ], [setV('p3nm', VAR('error'))]),
    setV('p3len', llen('ClsName')),
    setV('p3k', num(1)),
    REPEATU(OR(GT(VAR('p3k'), VAR('p3len')), EQ(VAR('p2c1'), VAR('p3nm'))), [
      callProc('compareText %s %s', [item('ClsName', VAR('p3k')), VAR('p3nm')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('p2c1', VAR('p3nm'))]),
      chgV('p3k', num(1))
    ]),
    IF(EQ(VAR('p2c1'), VAR('p3nm')), [
      setV('p2c2', VAR('tnm')), callProc('isanc', []),
      IF(EQ(VAR('p2r'), num(1)), [setV('tcl', num(1))])
    ])
  ];
  spliceAfter(matched[0], chain([IF(EQ(VAR('tcl'), num(0)), [setV('p2c1', txt('')), ...isUserClass])]));
  console.log('[P129] a handler also matches a subclass');

  // ---------- (c) a user class name is a value: `print(MyErr)` -> `<class '__main__.MyErr'>`
  // atom() already answers the *builtin* exception names with type C (P16).  The user classes need
  // a case-sensitive membership test, so run P127's `iscls` around the original test and feed its
  // flag into the same branch -- `iscls` answers through `ev`, hence the save/restore.
  const aDef = defIdOf('atom %s');
  const builtinIf = find(reach(aDef), (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_or') return false;
      return [...reach(b.inputs.CONDITION[1])].filter((x) => {
        const e = BL()[x];
        return !!e && e.opcode === 'operator_equals' && litOf(e.inputs.OPERAND2) === 'Exception'
          && varName(e.inputs.OPERAND1) === 'ev';
      }).length === 1;
    })());
  if (builtinIf.length !== 1) throw new Error('[P129] atom builtin class test = ' + builtinIf.length);
  insertBeforeStmt(builtinIf[0], [
    setV('p3v', VAR('ev')),
    setV('cname', VAR('ev')), callProc('iscls', []),
    setV('p3cls', VAR('ev')),
    setV('ev', VAR('p3v'))
  ]);
  {
    const condId = BL()[builtinIf[0]].inputs.CONDITION[1];
    replaceExpr(condId, () => OR(condId, EQ(VAR('p3cls'), num(1))));
  }
  // strval: a user class prints like CPython's `<class '__main__.MyErr'>`
  const svDef = defIdOf('strval %s %s');
  const svC = find(reach(svDef), (b) => {
    if (b.opcode !== 'data_setvariableto' || !b.fields.VARIABLE || b.fields.VARIABLE[0] !== 'ev') return false;
    const d = b.inputs.VALUE;
    if (!d || typeof d[1] !== 'string') return false;
    const j = BL()[d[1]];
    if (!j || j.opcode !== 'operator_join') return false;
    const lits = [];
    for (const x of reach(d[1])) {
      const q = BL()[x];
      if (!q || !q.inputs) continue;
      for (const k of ['STRING1', 'STRING2']) if (q.inputs[k]) { const L = litOf(q.inputs[k]); if (L) lits.push(L); }
    }
    return lits.includes("<class '") && lits.includes("'>");
  });
  if (svC.length !== 1) throw new Error('[P129] strval class spelling = ' + svC.length);
  // the class name is still in `ev` *before* the spelling is built, so test it there (saving the
  // flag) and rewrite the spelling afterwards -- inserting the rewrite before would just be
  // overwritten by the original assignment
  insertBeforeStmt(svC[0], [
    setV('p3v', VAR('ev')),
    setV('cname', VAR('ev')), callProc('iscls', []),
    setV('p3cls', VAR('ev')),
    setV('ev', VAR('p3v'))
  ]);
  spliceAfter(svC[0], chain([
    IF(EQ(VAR('p3cls'), num(1)), [setV('ev', JOIN(JOIN(txt("<class '__main__."), VAR('p3v')), txt("'>")))])
  ]));
  console.log('[P129] class names are values');

  // ---------- (d) an exception instance prints its message (`str(MyErr('z'))` == 'z')
  // CPython keeps the constructor arguments in `args`; here the first one is stored under the
  // hidden attribute `__msg__` when the class is an exception subclass and defines no __init__.
  const cf = inDef('callfn %s %s %s');
  // right after the instance is registered (`iid` is set, `InstCls` appended) and before the
  // __init__ guard
  const instAdd = find(cf, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'InstCls');
  if (instAdd.length !== 1) throw new Error('[P129] InstCls append = ' + instAdd.length);
  spliceAfter(instAdd[0], chain([
    setV('p2c1', argOf('fn')), setV('p2c2', txt('Exception')), callProc('isanc', []),
    IF(EQ(VAR('p2r'), num(1)), [
      // only when there is an argument to store (`MyErr()` keeps the default spelling)
      IF(NOT(GT(argOf('lo'), argOf('hi'))), [
        callProc('eval %s %s', [argOf('lo'), argOf('hi')]),
        IF(EQ(VAR('error'), txt('')), [
          addTo('IAttrId', VAR('iid')), addTo('IAttrName', txt('__msg__')),
          addTo('IAttrVal', VAR('ev')), addTo('IAttrType', VAR('evtype'))
        ])
      ])
    ])
  ]));
  // printargs: an exception instance without __str__ prints its stored message
  const pa = inDef('printargs');
  const strBranch = find(pa, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      return !!q && q.opcode === 'data_listcontainsitem' && q.fields.LIST && q.fields.LIST[0] === 'FnName';
    }));
  if (strBranch.length !== 1) throw new Error('[P129] printargs __str__ branch = ' + strBranch.length);
  const sinkId = BL()[strBranch[0]].inputs.SUBSTACK2 && BL()[strBranch[0]].inputs.SUBSTACK2[1];
  if (!sinkId) throw new Error('[P129] printargs sink');
  const msgLookup = [
    setV('p3x', num(0)), setV('p3k2', num(1)), setV('p3n2', llen('IAttrId')),
    REPEATU(OR(GT(VAR('p3k2'), VAR('p3n2')), GT(VAR('p3x'), num(0))), [
      IF(AND(EQ(item('IAttrId', VAR('p3k2')), VAR('ev')), EQ(item('IAttrName', VAR('p3k2')), txt('__msg__'))), [
        setV('p3x', VAR('p3k2'))
      ]),
      chgV('p3k2', num(1))
    ])
  ];
  // the lookup runs once per printed argument, in front of the `__str__` branch
  insertBeforeStmt(strBranch[0], msgLookup);
  // ... and the branch that fell through to strval() now prefers the stored message
  replaceStmt(sinkId, IFELSE(AND(EQ(VAR('evtype'), txt('O')), GT(VAR('p3x'), num(0))), [
    setV('ev', item('IAttrVal', VAR('p3x'))),
    setV('evtype', item('IAttrType', VAR('p3x')))
  ], [sinkId]));
  console.log('[P129] exception instances print their message');

  // ---------- (e) `raise MyErr()` -- the argument range is empty, and eval() rejects an empty
  // range with `SyntaxError: missing expression`, so the message evaluation has to be guarded
  const raiseIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      return !!q && q.opcode === 'operator_equals' && litOf(q.inputs.OPERAND2) === 'raise'
        && varName(q.inputs.OPERAND1) === 'head';
    })());
  if (raiseIf.length !== 1) throw new Error('[P129] raise branch = ' + raiseIf.length);
  const msgEval = find(reach(raiseIf[0]), (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'eval %s %s') return false;
    // the message range starts at the literal 4 (`raise Name ( 4 ... )
    return Object.values(b.inputs || {}).some((d) => litOf(d) === '4');
  });
  if (msgEval.length !== 1) throw new Error('[P129] raise message eval = ' + msgEval.length);
  const hasArgs = () => AND(NOT(GT(num(4), SUB(VAR('count'), num(1)))), NOT(EQ(tokAt(num(4)), txt(')'))));
  replaceStmt(msgEval[0], IF(hasArgs(), [msgEval[0]]));
  const rSub = BL()[raiseIf[0]].inputs.SUBSTACK;
  if (!rSub || typeof rSub[1] !== 'string') throw new Error('[P129] raise substack');
  // the `if error == ''` right after the (now guarded) eval also has to wait for real arguments:
  // with the eval skipped, `ev` still holds whatever the previous statement left there and the
  // message would silently become that value (`raise MyErr()` produced "MyErr: 0")
  const msgIf = find(reach(rSub[1]), (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      return !!q && q.opcode === 'operator_equals' && varName(q.inputs.OPERAND1) === 'error'
        && litOf(q.inputs.OPERAND2) === ''
        && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
          const s = BL()[x];
          return !!s && s.opcode === 'procedures_call' && s.mutation && s.mutation.proccode === 'strval %s %s';
        });
    })());
  if (msgIf.length !== 1) throw new Error('[P129] raise message branch = ' + msgIf.length);
  {
    const condId = BL()[msgIf[0]].inputs.CONDITION[1];
    replaceExpr(condId, () => AND(condId, hasArgs()));
  }
  console.log('[P129] raise with no arguments');

  // ---------- (f) `except MyErr as e` with an empty message
  // P112 slices the message with `substr(tlast, cp + 2, len)`, guarded by `cp + 1 <= len` -- but
  // the raise branch builds "<name>: " *with* the trailing space, so for `raise MyErr()` the colon
  // is the second-to-last character and substr is called with from > to (the binding then picks up
  // whatever was left in ev, i.e. `0`).  Require one more character.
  const ascpIf = find(reach(defIdOf('trycatch')), (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      if (!q || q.opcode !== 'operator_gt') return false;
      const a = BL()[q.inputs.OPERAND1[1]];
      return !!a && a.opcode === 'operator_add' && litOf(a.inputs.NUM2) === '1'
        && varName(a.inputs.NUM1) === 'ascp';
    }));
  if (ascpIf.length !== 1) throw new Error('[P129] except message guard = ' + ascpIf.length);
  {
    const addId = [...reach(BL()[ascpIf[0]].inputs.CONDITION[1])].find((x) => {
      const q = BL()[x];
      return !!q && q.opcode === 'operator_add' && litOf(q.inputs.NUM2) === '1' && varName(q.inputs.NUM1) === 'ascp';
    });
    if (!addId) throw new Error('[P129] except message add');
    const slot = BL()[addId].inputs.NUM2;
    BL()[addId].inputs.NUM2 = num(2);
  }
  console.log('[P129] an empty exception message binds as the empty string');
});

// ---- P130: sorted(x, key=lambda ...) (v4.57) ----
//
// `sorted(x, reverse=...)` is P101's hook in eval: it splits the call at the first top-level
// comma, sorts with `lsort` and reverses when asked.  A second keyword needs two new things:
//
//   * a way to call a function with a *value* (the element) instead of a token range.  `calluser`
//     takes its arguments from `UArgV`/`UArgT`, which it fills by evaluating the tokens `lo..hi`
//     -- so `callval` appends one synthetic token holding the value (`Tok`+`Kind`; the tokenizer
//     stores a string literal as its bare value, so `('ab', 'S')` and `(12, 'N')` round-trip) and
//     calls `calluser` on that single index.  Numbers, strings, bools and None can be re-evaluated
//     that way; anything else is reported as a TypeError.
//   * a sort that orders by key without comparing the keys as strings.  `lsort` refuses tuples
//     (`TypeError: sort requires all numbers or all strings`), so `srtkey` sorts the *key list*
//     (all numbers or all strings, like CPython's key functions in practice) and then walks the
//     original list picking the first unused element whose key equals the next sorted key -- which
//     also keeps the sort stable, like CPython.
//
// The hook parses *all* the keyword arguments (any order, `key=` and `reverse=` both allowed) and
// stops the script, so P101's single-keyword hook no longer runs for the comma case.
patch('P130 sorted key', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const setItem = (list, idx, val) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(val, [4, '0']) } });
  const enc = (acc, t, v) => JOIN(JOIN(JOIN(acc, VAR('lsep')), t), v);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const VARS = ['p4i', 'p4j', 'p4n', 'p4c', 'p4pos', 'p4end', 'p4next', 'p4klo', 'p4khi', 'p4rlo', 'p4rhi',
    'p4list', 'p4out', 'p4fn', 'p4v', 'p4vt', 'p4vv', 'p4vk', 'p4tok', 'p4len0', 'p4lenk', 'p4kl', 'p4sk',
    'p4ks', 'p4kst', 'p4res', 'p4rt', 'p4bi', 'p4bin'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P130] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  for (const l of ['P4Key', 'P4KeyT', 'P4Used']) B.addList(IT, l, []);
  const bale = () => [chgV('fnlimit', num(-1)), STOPTHIS()];
  const tokAt = (i) => item('Tok', i);

  // ---------- (a) callval: call p4fn with the single value p4v/p4vt
  const cv = newProc('callval', []);
  attachBody(cv.defId, [
    // instances, functions and classes have no literal form, so they cannot ride in as source text
    IF(OR(EQ(VAR('p4vt'), txt('O')), OR(EQ(VAR('p4vt'), txt('F')), EQ(VAR('p4vt'), txt('C')))), [
      FAIL(txt('TypeError: sorted() key function cannot receive this value')),
      STOPTHIS()
    ]),
    // the element travels as its *source form*: repr() gives a literal that the tokenizer reads
    // back (numbers, strings, bools, None, and nested lists/tuples/dicts/sets all round-trip),
    // and `tokenize` replaces Tok with that literal's tokens for the duration of the call
    callProc('reprval %s %s', [VAR('p4v'), VAR('p4vt')]),
    setV('p4vv', VAR('ev')),
    callProc('tokenize %s', [VAR('p4vv')]),
    IFELSE(EQ(VAR('p4bi'), num(1)), [
      callProc('callfn %s %s %s', [VAR('p4bin'), num(1), llen('Tok')])
    ], [
      callProc('calluser %s %s %s', [VAR('p4fn'), num(1), llen('Tok')])
    ]),
    // put the current line's tokens back (p112.txt does exactly this)
    callProc('tokenize %s', [item('Code', VAR('pc'))])
  ]);
  console.log('[P130] callval registered');

  // ---------- (b) srtkey: sort p4list by the key function p4fn
  const sk = newProc('srtkey', []);
  attachBody(sk.defId, [
    callProc('listlen %s', [VAR('p4list')]), setV('p4n', VAR('ev')),
    setV('p4kl', txt('')), clearL('P4Key'), clearL('P4KeyT'), clearL('P4Used'),
    setV('p4i', num(1)),
    REPEATU(GT(VAR('p4i'), VAR('p4n')), [
      callProc('listitem %s %s', [VAR('p4list'), VAR('p4i')]),
      setV('p4v', VAR('ev')), setV('p4vt', VAR('evtype')),
      callProc('callval', []),
      // a bool key sorts as a number (CPython: False < True)
      IFELSE(EQ(VAR('evtype'), txt('B')), [
        setV('p4kl', enc(VAR('p4kl'), txt('N'), VAR('ev')))
      ], [
        setV('p4kl', enc(VAR('p4kl'), VAR('evtype'), VAR('ev')))
      ]),
      addTo('P4Key', VAR('ev')), addTo('P4KeyT', VAR('evtype')), addTo('P4Used', num(0)),
      chgV('p4i', num(1))
    ]),
    callProc('lsort %s', [VAR('p4kl')]), setV('p4sk', VAR('ev')),
    setV('p4res', txt('')),
    setV('p4i', num(1)),
    REPEATU(GT(VAR('p4i'), VAR('p4n')), [
      callProc('listitem %s %s', [VAR('p4sk'), VAR('p4i')]),
      setV('p4ks', VAR('ev')), setV('p4kst', VAR('evtype')),
      setV('p4j', num(1)),
      REPEATU(GT(VAR('p4j'), VAR('p4n')), [
        IF(AND(EQ(item('P4Used', VAR('p4j')), num(0)), EQ(item('P4Key', VAR('p4j')), VAR('p4ks'))), [
          callProc('listitem %s %s', [VAR('p4list'), VAR('p4j')]),
          // escape before embedding: a nested container's own separators must not leak into the
          // outer encoding (this is what lrev does after every listitem)
          callProc('lesc %s', [VAR('ev')]),
          setV('p4res', enc(VAR('p4res'), VAR('evtype'), VAR('ev'))),
          setItem('P4Used', VAR('p4j'), num(1)),
          setV('p4j', VAR('p4n'))
        ]),
        chgV('p4j', num(1))
      ]),
      chgV('p4i', num(1))
    ]),
    setV('ev', VAR('p4res')), setV('evtype', txt('L'))
  ]);
  console.log('[P130] srtkey registered');

  // ---------- (c) eval: the sorted(...) hook, in front of P101's
  const ev2 = inDef('eval %s %s');
  const sortedIf = find(ev2, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const t = (q.inputs.OPERAND1 && typeof q.inputs.OPERAND1[1] === 'string') ? BL()[q.inputs.OPERAND1[1]] : null;
      return !!t && t.opcode === 'data_itemoflist' && t.fields.LIST && t.fields.LIST[0] === 'Tok'
        && litOf(q.inputs.OPERAND2) === 'sorted';
    })());
  if (sortedIf.length !== 1) throw new Error('[P130] sorted hook = ' + sortedIf.length);
  const kwName = (name) => EQ(tokAt(VAR('p4pos')), txt(name));
  const kwOk = () => OR(AND(kwName('key'), EQ(tokAt(ADD(VAR('p4pos'), num(1))), txt('='))),
    AND(kwName('reverse'), EQ(tokAt(ADD(VAR('p4pos'), num(1))), txt('='))));
  const takeKw = (name, loVar, hiVar) => IF(kwName(name), [
    IF(EQ(tokAt(ADD(VAR('p4pos'), num(1))), txt('=')), [
      setV(loVar, ADD(VAR('p4pos'), num(2))), setV(hiVar, VAR('p4end'))
    ])
  ]);
  insertBeforeStmt(sortedIf[0], [
    IF(EQ(tokAt(argOf('lo')), txt('sorted')), [
      callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IF(EQ(VAR('tqhcm'), num(1)), [
        setV('p4c', VAR('tqcpz')),
        // the first piece is the iterable
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('p4c'), num(1))]),
        IF(EQ(VAR('error'), txt('')), [
          IF(NOT(OR(EQ(VAR('evtype'), txt('L')), EQ(VAR('evtype'), txt('E')))), [
            FAIL(txt('TypeError: sorted() requires a list')),
            ...bale()
          ]),
          setV('p4list', VAR('ev')),
          setV('p4klo', num(0)), setV('p4rlo', num(0)),
          setV('p4pos', ADD(VAR('p4c'), num(1))),
          // walk the remaining pieces: name '=' value
          REPEATU(OR(EQ(VAR('p4pos'), num(0)), GT(VAR('p4pos'), SUB(argOf('hi'), num(1)))), [
            callProc('hascomma %s %s', [VAR('p4pos'), SUB(argOf('hi'), num(1))]),
            IFELSE(EQ(VAR('tqhcm'), num(1)), [
              setV('p4end', SUB(VAR('tqcpz'), num(1))), setV('p4next', ADD(VAR('tqcpz'), num(1)))
            ], [
              setV('p4end', SUB(argOf('hi'), num(1))), setV('p4next', num(0))
            ]),
            IF(NOT(kwOk()), [
              FAILB(JOIN(txt('TypeError: sorted() got an unexpected keyword argument '), tokAt(VAR('p4pos')))),
              ...bale()
            ]),
            takeKw('key', 'p4klo', 'p4khi'),
            takeKw('reverse', 'p4rlo', 'p4rhi'),
            setV('p4pos', VAR('p4next'))
          ]),
          // sort (by key when given)
          IFELSE(GT(VAR('p4klo'), num(0)), [
            setV('p4bi', num(0)),
            callProc('eval %s %s', [VAR('p4klo'), VAR('p4khi')]),
            IFELSE(EQ(VAR('error'), txt('')), [
              // a function value is the index into FnName (p85.txt); calluser wants the name
              setV('p4fn', item('FnName', VAR('ev')))
            ], [
              // `key=len` and friends: a bare builtin name is not a value in this interpreter, so
              // keep the name and let callfn dispatch it -- only for a single-token key
              IF(EQ(VAR('p4khi'), VAR('p4klo')), [
                setV('p4bin', tokAt(VAR('p4klo'))),
                setV('p4bi', num(1)),
                setV('error', txt(''))
              ])
            ]),
            IF(EQ(VAR('error'), txt('')), [
              callProc('srtkey', []),
              setV('p4out', VAR('ev'))
            ])
          ], [
            callProc('lsort %s', [VAR('p4list')]),
            setV('p4out', VAR('ev'))
          ]),
          IF(EQ(VAR('error'), txt('')), [
            // reverse=...
            IF(GT(VAR('p4rlo'), num(0)), [
              callProc('eval %s %s', [VAR('p4rlo'), VAR('p4rhi')]),
              IF(EQ(VAR('error'), txt('')), [
                setV('p4rt', VAR('evtype')),
                callProc('truth %s %s', [VAR('ev'), VAR('p4rt')]),
                IF(EQ(VAR('truthv'), num(1)), [
                  callProc('lrev %s', [VAR('p4out')]), setV('p4out', VAR('ev'))
                ])
              ])
            ]),
            setV('ev', VAR('p4out')), setV('evtype', txt('L'))
          ])
        ]),
        ...bale()
      ])
    ])
  ]);
  console.log('[P130] eval: sorted(x, key=...) installed');
});

// ---- P131: a tuple of types -- isinstance(x, (int, str)) and issubclass (v4.58) ----
//
// P128 gave `isinstance(x, T)` a table over the interpreter's own type tags plus a ClsPar walk for
// user classes.  Two shapes were still missing:
//
//   * `isinstance(x, (int, str))` -- the second argument is a parenthesised tuple of names, so the
//     single-name test has to run once per element and be OR-ed;
//   * `issubclass(A, B)` (and `issubclass(A, (B, C))`) -- the same two-argument call shape, but both
//     sides are *names*: user classes (ClsName + ClsPar via P128's `isanc`), the builtin type names
//     (`object` is everybody's base, `bool` is an `int`) and the builtin exception names (all of
//     them subclass `Exception`).
//
// The type-test chain is factored into a procedure (`isname`, reading the globals P128 already uses:
// p2v/p2t/p2n) so both hooks can share it, and the names of a tuple are collected *before* the value
// is evaluated -- a nested eval can re-tokenize Tok (p90.txt), so token positions are only reliable
// until then.
patch('P131 type tuples and issubclass', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const EXC = ['Exception', 'ValueError', 'TypeError', 'IndexError', 'KeyError', 'NameError', 'ZeroDivisionError',
    'AttributeError', 'RuntimeError', 'AssertionError', 'StopIteration', 'ArithmeticError', 'OverflowError'];
  const BUILTIN = ['object', 'int', 'float', 'bool', 'str', 'list', 'tuple', 'dict', 'set'];
  const VARS = ['p5a', 'p5b', 'p5r', 'p5i', 'p5from', 'p5to', 'p5any', 'p5v', 'p5t', 'p5ctmp', 'p5et'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P131] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  B.addList(IT, 'P5Names', []);
  const bale = () => [chgV('fnlimit', num(-1)), STOPTHIS()];
  const tok = (d) => item('Tok', d);
  const tagIs = (tag) => EQ(VAR('p2t'), txt(tag));

  // ---------- (a) isname: p2v/p2t against the name in p2n -> p2r (the P128 chain, factored out)
  const inm = newProc('isname', []);
  const typeIs = (name, expr) => IF(EQ(VAR('p2n'), txt(name)), [IF(expr, [setV('p2r', num(1))])]);
  attachBody(inm.defId, [
    setV('p2r', num(0)),
    typeIs('bool', tagIs('B')),
    typeIs('int', OR(tagIs('B'), AND(tagIs('N'), NOT(strHas(VAR('p2v'), txt('.')))))),
    typeIs('float', AND(tagIs('N'), strHas(VAR('p2v'), txt('.')))),
    typeIs('str', tagIs('S')),
    typeIs('list', tagIs('L')),
    typeIs('tuple', tagIs('T')),
    typeIs('dict', tagIs('D')),
    typeIs('set', tagIs('E')),
    IF(EQ(VAR('p2n'), txt('object')), [setV('p2r', num(1))]),
    // a user class: the instance's own class, or something up its ClsPar chain
    IF(AND(tagIs('O'), EQ(VAR('p2r'), num(0))), [
      setV('p2c1', item('InstCls', VAR('p2v'))), setV('p2c2', VAR('p2n')),
      callProc('isanc', [])
    ])
  ]);
  console.log('[P131] isname registered');

  // ---------- (b) issub: the class in p5a against the name in p5b -> ev (bool)
  const iss = newProc('issub', []);
  let excCond = null;
  for (const c of EXC) { const e = EQ(VAR('p5a'), txt(c)); excCond = excCond ? OR(excCond, e) : e; }
  attachBody(iss.defId, [
    setV('p5r', num(0)),
    IF(EQ(VAR('p5a'), VAR('p5b')), [setV('p5r', num(1))]),
    IF(EQ(VAR('p5b'), txt('object')), [setV('p5r', num(1))]),
    IF(AND(EQ(VAR('p5a'), txt('bool')), EQ(VAR('p5b'), txt('int'))), [setV('p5r', num(1))]),
    // every builtin exception name descends from Exception
    IF(AND(excCond, EQ(VAR('p5b'), txt('Exception'))), [setV('p5r', num(1))]),
    // a user class: walk its parents (isanc answers through p2r, hence the copy)
    IF(EQ(VAR('p5r'), num(0)), [
      setV('cname', VAR('p5a')), callProc('iscls', []),
      IF(EQ(VAR('ev'), num(1)), [
        setV('p2c1', VAR('p5a')), setV('p2c2', VAR('p5b')), callProc('isanc', []),
        IF(EQ(VAR('p2r'), num(1)), [setV('p5r', num(1))])
      ])
    ]),
    setV('ev', VAR('p5r')), setV('evtype', txt('B'))
  ]);
  console.log('[P131] issub registered');

  // ---------- (c) eval: collect the names of the type argument, then run the tests
  const ev2 = inDef('eval %s %s');
  const nargIf = find(ev2, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      return (varName(q.inputs.OPERAND1) === 'narg' && litOf(q.inputs.OPERAND2) === '0')
        || (varName(q.inputs.OPERAND2) === 'narg' && litOf(q.inputs.OPERAND1) === '0');
    })());
  if (nargIf.length !== 1) throw new Error('[P131] eval narg dispatch = ' + nargIf.length);
  // P128's isinstance hook: my hooks go in front of it
  const isinstIf = find(ev2, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_equals') return false;
      const t = (q.inputs.OPERAND1 && typeof q.inputs.OPERAND1[1] === 'string') ? BL()[q.inputs.OPERAND1[1]] : null;
      return !!t && t.opcode === 'data_itemoflist' && t.fields.LIST && t.fields.LIST[0] === 'Tok'
        && litOf(q.inputs.OPERAND2) === 'isinstance';
    })());
  if (isinstIf.length !== 1) throw new Error('[P131] isinstance hook = ' + isinstIf.length);
  // from/to delimit the type argument; a leading '(' means a tuple, so step inside the parens
  const collect = (fromExpr, toExpr) => [
    clearL('P5Names'),
    setV('p5from', fromExpr), setV('p5to', toExpr),
    IF(AND(EQ(tok(VAR('p5from')), txt('(')), EQ(tok(VAR('p5to')), txt(')'))), [
      chgV('p5from', num(1)), chgV('p5to', num(-1))
    ]),
    setV('p5i', VAR('p5from')),
    REPEATU(GT(VAR('p5i'), VAR('p5to')), [
      IF(NOT(EQ(tok(VAR('p5i')), txt(','))), [addTo('P5Names', tok(VAR('p5i')))]),
      chgV('p5i', num(1))
    ])
  ];
  const forEachName = (run) => [
    setV('p5any', num(0)), setV('p5i', num(1)),
    REPEATU(GT(VAR('p5i'), llen('P5Names')), [
      setV('p5b', item('P5Names', VAR('p5i'))),
      ...run,
      chgV('p5i', num(1))
    ])
  ];
  insertBeforeStmt(isinstIf[0], [
    // `issubclass(A, B)` / `issubclass(A, (B, C))` -- both arguments are names
    IF(EQ(tok(argOf('lo')), txt('issubclass')), [
      callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IFELSE(EQ(VAR('tqhcm'), num(1)), [
        setV('p5a', tok(ADD(argOf('lo'), num(2)))),
        // the names are collected before anything is evaluated (a nested eval re-tokenizes Tok)
        ...collect(ADD(VAR('tqcpz'), num(1)), SUB(argOf('hi'), num(1))),
        ...forEachName([
          callProc('issub', []),
          IF(EQ(VAR('ev'), num(1)), [setV('p5any', num(1))])
        ]),
        setV('ev', VAR('p5any')), setV('evtype', txt('B')),
      ], [
        FAIL(txt('TypeError: issubclass expected 2 arguments, got 1')),
        ...bale()
      ]),
      ...bale()
    ]),
    // `isinstance(x, (int, str))` -- a tuple of names instead of one
    IF(EQ(tok(argOf('lo')), txt('isinstance')), [
      callProc('hascomma %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      IF(AND(EQ(VAR('tqhcm'), num(1)), EQ(tok(ADD(VAR('tqcpz'), num(1))), txt('('))), [
        ...collect(ADD(VAR('tqcpz'), num(1)), SUB(argOf('hi'), num(1))),
        callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(VAR('tqcpz'), num(1))]),
        IF(EQ(VAR('error'), txt('')), [
          setV('p2v', VAR('ev')), setV('p2t', VAR('evtype')),
          ...forEachName([
            setV('p2n', VAR('p5b')), callProc('isname', []),
            IF(EQ(VAR('p2r'), num(1)), [setV('p5any', num(1))])
          ]),
          setV('ev', VAR('p5any')), setV('evtype', txt('B')),
        ]),
        ...bale()
      ])
    ])
  ]);
  console.log('[P131] eval: type tuples and issubclass installed');

  // ---------- (d) the class-name test P129 added to atom() calls `iscls`, which uses `ctmp` as its
  // loop counter.  P127's explicit-call hook (`A.m(inst, args)`) keeps the comma position in `ctmp`
  // *across* the eval of the instance expression, so evaluating any identifier in between (e.g. the
  // `self` of `A.setv(self, v)`) silently moved the method's argument range and every such call died
  // with `SyntaxError: parentheses` (a v4.56/v4.57 regression).  Save and restore the scratch state.
  {
    // P129 uses the same p3v/cname/p3cls block in two places (atom's class test and strval's class
    // spelling), so pick the one that lives in `atom %s`
    const ownerProc = (id) => {
      let cur = id;
      for (let i = 0; i < 300 && cur; i++) {
        const b = BL()[cur];
        if (!b) return null;
        if (b.opcode === 'procedures_definition') {
          const p = BL()[b.inputs.custom_block[1]];
          return p && p.mutation ? p.mutation.proccode : null;
        }
        cur = b.parent;
      }
      return null;
    };
    const p3v = allIds().filter((id) => {
      const b = BL()[id];
      return b && b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'p3v'
        && varName(b.inputs.VALUE) === 'ev' && ownerProc(id) === 'atom %s';
    });
    if (p3v.length !== 1) throw new Error('[P131] atom class test = ' + p3v.length);
    const nx = BL()[p3v[0]].next;
    if (!nx || BL()[nx].opcode !== 'data_setvariableto' || !BL()[nx].fields.VARIABLE
      || BL()[nx].fields.VARIABLE[0] !== 'cname' || varName(BL()[nx].inputs.VALUE) !== 'ev') {
      throw new Error('[P131] atom class test shape');
    }
    const back = (() => {
      let cur = p3v[0];
      for (let i = 0; i < 8 && cur; i++) {
        const b = BL()[cur];
        if (b && b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ev'
          && varName(b.inputs.VALUE) === 'p3v') return cur;
        cur = b.next;
      }
      return null;
    })();
    if (!back) throw new Error('[P131] atom class test end');
    insertBeforeStmt(p3v[0], [setV('p5ctmp', VAR('ctmp')), setV('p5et', VAR('evtype'))]);
    spliceAfter(back, chain([setV('ctmp', VAR('p5ctmp')), setV('evtype', VAR('p5et'))]));
    console.log('[P131] atom keeps ctmp/evtype for its caller');
  }

  // ---------- (e) the class-body `name = value` handler (P90) fires for *every* scanned line whose
  // second token is '=' -- including the lines of a method body.  `def go(self, v): r = v` therefore
  // evaluated `v` at class-definition time (`NameError: v`), and `r = 5` quietly became a class
  // attribute; only bodies whose assignments never mention a name survived, which is why the suites
  // never caught it.  A class-body line is indented *exactly* four spaces; a method body is deeper.
  {
    const ex2 = inDef('execute');
    const tokEq = (condId, idx, lit) => [...reach(condId)].some((x) => {
      const q = BL()[x];
      if (!q || q.opcode !== 'operator_equals') return false;
      const t = (q.inputs.OPERAND1 && typeof q.inputs.OPERAND1[1] === 'string') ? BL()[q.inputs.OPERAND1[1]] : null;
      return !!t && t.opcode === 'data_itemoflist' && t.fields.LIST && t.fields.LIST[0] === 'Tok'
        && litOf(t.inputs.INDEX) === idx && litOf(q.inputs.OPERAND2) === lit;
    });
    const hIf = find(ex2, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && tokEq(b.inputs.CONDITION[1], '1', 'def') && tokEq(b.inputs.CONDITION[1], '2', '='));
    if (hIf.length !== 1) throw new Error('[P131] class-body handler = ' + hIf.length);
    const condId = BL()[hIf[0]].inputs.CONDITION[1];
    const lineOf = () => item('Code', VAR('ck'));
    replaceExpr(condId, () => AND(condId,
      AND(EQ(letterOf(num(4), lineOf()), txt(' ')), NOT(EQ(letterOf(num(5), lineOf()), txt(' '))))));
    console.log('[P131] class-body attributes keep to their own indentation');
  }
});

// ---- P132: several `except` clauses, tried in order (v4.59) ----
//
// P51's trycatch keeps one frame per `try`: TryHand = the first clause's body, TryName = that
// clause's name.  When the name does not match, the frame is popped and the error is re-raised --
// so only the FIRST clause can ever catch anything:
//
//     try:    raise ValueError('v')
//     except TypeError: print('T')
//     except ValueError as e: print('V', e)     # v4.58: the ValueError escapes
//
// P123 already walks the same `Elses` clause chain (except -> ... -> finally) to find a tail, so the
// next clause is one list lookup away: `Elses[clauseLine]`.  When the current clause matched nothing,
// this patch walks forward, tests each following clause against the same error (bare `except`,
// `Exception`, a name prefix, or -- P129's extension -- a user class up the ClsPar chain) and, on a
// hit, jumps into that clause's body exactly like the first-clause path does.
patch('P132 several except clauses', () => {
  const last = (l) => item(l, txt('last'));
  const VARS = ['t2x', 't2n', 't2hit', 't2done', 't2off', 't2nm', 't2err', 't2as', 't2i', 't2cp', 't2msg'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P132] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);

  // the pops at the end of trycatch's handler loop: TryHand/TryEnd/TryName/TryLoop/TryC
  const tcDef = defIdOf('trycatch');
  const wantLists = ['TryHand', 'TryEnd', 'TryName', 'TryLoop', 'TryC'];
  const pops = [];
  {
    const seen = new Set();
    const stack = [BL()[tcDef].next];
    while (stack.length) {
      const id = stack.pop();
      if (!id || seen.has(id)) continue;
      seen.add(id);
      const b = BL()[id];
      if (!b) continue;
      if (b.opcode === 'data_deleteoflist' && b.fields.LIST && wantLists.includes(b.fields.LIST[0])) {
        pops.push(id);
      }
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
  }
  if (pops.length !== 5) throw new Error('[P132] trycatch frame pops = ' + pops.length);
  // the five deletions are consecutive: TryHand, TryEnd, TryName, TryLoop, TryC
  const first = pops.find((id) => BL()[id].fields.LIST[0] === 'TryHand');
  if (!first) throw new Error('[P132] TryHand pop');
  {
    let cur = first;
    for (let i = 0; i < 5; i++) {
      const b = BL()[cur];
      if (!b || b.opcode !== 'data_deleteoflist' || !b.fields.LIST
        || b.fields.LIST[0] !== wantLists[i]) {
        throw new Error('[P132] pop chain at ' + i + ': ' + (b && b.fields && b.fields.LIST ? b.fields.LIST[0] : b && b.opcode));
      }
      cur = b.next;
    }
  }
  // the class-name test P129 uses for `except Base` catching `Sub`: the raised class is the text
  // before the first ':' of the message
  const subclassHit = () => [
    callProc('sfind %s %s', [VAR('error'), txt(':')]),
    setV('t2off', VAR('ev')),
    IFELSE(GT(VAR('t2off'), num(0)), [
      callProc('substr %s %s %s', [VAR('error'), num(1), VAR('t2off')]),
      setV('t2nm', VAR('ev'))
    ], [setV('t2nm', VAR('error'))]),
    setV('cname', VAR('t2nm')), callProc('iscls', []),
    IF(EQ(VAR('ev'), num(1)), [
      setV('p2c1', VAR('t2nm')), setV('p2c2', VAR('t2n')), callProc('isanc', []),
      IF(EQ(VAR('p2r'), num(1)), [setV('t2hit', num(1))])
    ])
  ];
  const nextClause = IF(EQ(VAR('tcl'), num(0)), [
    // tokenize() bails out while `error` is set -- it is the "something went wrong" flag -- so the
    // walk has to hide the error while it reads the following clause lines
    setV('t2err', VAR('error')),
    setV('t2x', item('Elses', SUB(last('TryHand'), num(1)))),
    setV('t2done', num(0)),
    // the Elses chain only links clause heads, so it answers 0 when the try has no further
    // clause (TryEnd is the *next* clause, not the end of the try, so it is no bound here)
    REPEATU(OR(EQ(VAR('t2done'), num(1)), EQ(VAR('t2x'), num(0))), [
      setV('error', txt('')),
      callProc('tokenize %s', [item('Code', VAR('t2x'))]),
      setV('error', VAR('t2err')),
      IFELSE(EQ(item('Tok', num(1)), txt('except')), [
        IFELSE(GT(llen('Tok'), num(2)), [setV('t2n', item('Tok', num(2)))], [setV('t2n', txt(''))]),
        setV('t2hit', num(0)),
        IFELSE(OR(EQ(VAR('t2n'), txt('')), EQ(VAR('t2n'), txt('Exception'))), [
          setV('t2hit', num(1))
        ], [
          callProc('sprefix %s %s %s', [VAR('error'), VAR('t2n'), txt('startswith')]),
          IF(EQ(VAR('ev'), num(1)), [setV('t2hit', num(1))]),
          IF(EQ(VAR('t2hit'), num(0)), [
            ...subclassHit()
          ])
        ]),
        IFELSE(EQ(VAR('t2hit'), num(1)), [
          // bind the name after `as` (P112 does this for the first clause): the message is the
          // text after the first ':' of the error text
          setV('t2as', txt('')), setV('t2i', num(1)),
          REPEATU(GT(VAR('t2i'), llen('Tok')), [
            IF(EQ(item('Tok', VAR('t2i')), txt('as')), [setV('t2as', item('Tok', ADD(VAR('t2i'), num(1))))]),
            chgV('t2i', num(1))
          ]),
          IF(NOT(EQ(VAR('t2as'), txt(''))), [
            setV('t2cp', num(0)), setV('t2msg', txt('')), setV('t2i', num(1)),
            REPEATU(GT(VAR('t2i'), lenOf(VAR('t2err'))), [
              IF(AND(EQ(VAR('t2cp'), num(0)), EQ(letterOf(VAR('t2i'), VAR('t2err')), txt(':'))), [setV('t2cp', VAR('t2i'))]),
              chgV('t2i', num(1))
            ]),
            IF(AND(NOT(EQ(VAR('t2cp'), num(0))), NOT(GT(ADD(VAR('t2cp'), num(2)), lenOf(VAR('t2err'))))), [
              callProc('substr %s %s %s', [VAR('t2err'), ADD(VAR('t2cp'), num(2)), lenOf(VAR('t2err'))]),
              setV('t2msg', VAR('ev'))
            ]),
            callProc('assign %s %s %s', [VAR('t2as'), VAR('t2msg'), txt('S')])
          ]),
          setV('tlast', VAR('t2err')),
          setV('error', txt('')),
          setV('pc', ADD(VAR('t2x'), num(1))),
          setV('t2done', num(1))
        ], [
          setV('t2x', item('Elses', VAR('t2x')))
        ])
      ], [
        setV('t2x', num(0))
      ]),
      // put a line's tokens back (the interpreter re-tokenizes as it goes, this is belt and braces)
      setV('error', txt('')),
      callProc('tokenize %s', [item('Code', VAR('pc'))]),
      setV('error', VAR('t2err')),
      IF(EQ(VAR('t2done'), num(1)), [setV('error', txt(''))])
    ])
  ]);
  insertBeforeStmt(first, [nextClause]);
  console.log('[P132] the remaining except clauses are tried in order');
});

// ---- P133: `except (A, B)` -- a tuple of exception names (v4.60) ----
//
// Every clause reader in the try machinery took the name from `Tok[2]`, which for a tuple clause is
// the `(` -- so `except (ValueError, IndexError):` stored "(" and could never match.  Two small
// pieces fix it:
//
//   * `clnames` reads the *clause line text* (`Code[c3line]`) and answers the names comma-joined
//     (`A,B`), for both `except A as e:` and `except (A, B) as e:` -- used by P51's try branch and by
//     P132's walk over the following clauses;
//   * `excmatch` tests one error against such a list: `Exception`, a name prefix, or (P129's rule) a
//     user exception class up its ClsPar chain.
//
// The callers keep their existing single-name path and only add a comma branch in front of it, so a
// plain `except ValueError:` behaves exactly as before (including P129's inline subclass test).
//
// Reading the text instead of the tokens is deliberate: `tokenize` runs again inside the walk and
// inside nested evals, and it was a stale `Tok` that made the first (token based) attempt answer
// "ValueError,,,IndexError" -- the text path cannot be poisoned that way.
patch('P133 except tuple clauses', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const VARS = ['c3nm', 'c3i', 'c3n', 'c3p', 'c3off', 'c3one', 'c3hit', 'c3this',
    'c3line', 'c3s', 'c3c', 'c3k', 'c3pc'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P133] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);

  // ---------- (a) clnames: the names on the clause line Code[c3line], comma-joined -> c3nm
  //
  // Text in, names out: cut the trailing ` as e`, cut the `:`, drop the `except` keyword itself and
  // then keep only identifier characters and commas -- so spaces, tabs and the tuple parentheses
  // disappear on their own.
  const cn = newProc('clnames', []);
  const isNameChar = (chExpr) => [
    setV('found', num(0)), setV('c3k', num(1)),
    REPEATU(OR(GT(VAR('c3k'), num(95)), EQ(VAR('found'), num(1))), [
      callProc('compareText %s %s', [letterOf(VAR('c3k'), VAR('cs')), chExpr]),
      IFELSE(EQ(VAR('cmp'), num(0)), [setV('found', num(1))], [chgV('c3k', num(1))])
    ])
  ];
  // `cs` is ASCII 32..126, so index 17..26 are the digits, 34..59 A-Z, 66..91 a-z and 64 is '_'
  const inR = (lo, hi) => AND(NOT(LT(VAR('c3k'), num(lo))), NOT(GT(VAR('c3k'), num(hi))));
  const cutAt = (sub) => [
    callProc('sfind %s %s', [VAR('c3s'), txt(sub)]),
    IF(NOT(LT(VAR('ev'), num(0))), [
      callProc('substr %s %s %s', [VAR('c3s'), num(1), VAR('ev')]),
      setV('c3s', VAR('ev'))
    ])
  ];
  // drop everything up to and including the keyword itself
  const pastAt = (sub) => [
    callProc('sfind %s %s', [VAR('c3s'), txt(sub)]),
    IF(NOT(LT(VAR('ev'), num(0))), [
      callProc('substr %s %s %s', [VAR('c3s'), ADD(VAR('ev'), num(sub.length + 1)), lenOf(VAR('c3s'))]),
      setV('c3s', VAR('ev'))
    ])
  ];
  attachBody(cn.defId, [
    setV('c3nm', txt('')),
    setV('c3s', item('Code', VAR('c3line'))),
    ...cutAt(' as '),
    ...cutAt(':'),
    ...pastAt('except'),
    setV('c3pc', num(1)), setV('c3n', lenOf(VAR('c3s'))),
    REPEATU(GT(VAR('c3pc'), VAR('c3n')), [
      setV('c3c', letterOf(VAR('c3pc'), VAR('c3s'))),
      IFELSE(EQ(VAR('c3c'), txt(',')), [
        setV('c3nm', JOIN(VAR('c3nm'), txt(',')))
      ], [
        ...isNameChar(VAR('c3c')),
        IF(AND(EQ(VAR('found'), num(1)), OR(OR(inR(17, 26), inR(34, 59)), OR(inR(66, 91), EQ(VAR('c3k'), num(64))))), [
          setV('c3nm', JOIN(VAR('c3nm'), VAR('c3c')))
        ])
      ]),
      chgV('c3pc', num(1))
    ])
  ]);
  console.log('[P133] clnames registered');

  // ---------- (b) excmatch: the error against the comma-joined names in c3nm -> ev
  const em = newProc('excmatch', []);
  // P129's rule, reused: a user exception class matches its own name or any name up its ClsPar chain
  const subHit = () => [
    callProc('sfind %s %s', [VAR('error'), txt(':')]),
    setV('c3off', VAR('ev')),
    IFELSE(GT(VAR('c3off'), num(0)), [
      callProc('substr %s %s %s', [VAR('error'), num(1), VAR('c3off')]),
      setV('c3one', VAR('ev'))
    ], [setV('c3one', VAR('error'))]),
    setV('cname', VAR('c3one')), callProc('iscls', []),
    IF(EQ(VAR('ev'), num(1)), [
      setV('p2c1', VAR('c3one')), setV('p2c2', VAR('c3this')), callProc('isanc', []),
      IF(EQ(VAR('p2r'), num(1)), [setV('c3hit', num(1))])
    ])
  ];
  attachBody(em.defId, [
    setV('c3hit', num(0)), setV('c3p', num(1)), setV('c3n', lenOf(VAR('c3nm'))),
    REPEATU(OR(GT(VAR('c3p'), VAR('c3n')), EQ(VAR('c3hit'), num(1))), [
      // the next name: sfind answers the 0-based index of the comma (or -1), so the piece is
      // c3p .. c3p+index-1 and the next piece starts right after the comma
      callProc('substr %s %s %s', [VAR('c3nm'), VAR('c3p'), VAR('c3n')]),
      callProc('sfind %s %s', [VAR('ev'), txt(',')]),
      setV('c3off', VAR('ev')),
      IFELSE(NOT(LT(VAR('c3off'), num(0))), [
        callProc('substr %s %s %s', [VAR('c3nm'), VAR('c3p'), SUB(ADD(VAR('c3p'), VAR('c3off')), num(1))]),
        setV('c3this', VAR('ev')),
        setV('c3p', ADD(ADD(VAR('c3p'), VAR('c3off')), num(1)))
      ], [
        callProc('substr %s %s %s', [VAR('c3nm'), VAR('c3p'), VAR('c3n')]),
        setV('c3this', VAR('ev')),
        setV('c3p', ADD(VAR('c3n'), num(1)))
      ]),
      // an empty piece (a stray comma) is skipped, `Exception` catches everything else
      IFELSE(NOT(EQ(VAR('c3this'), txt(''))), [
        IFELSE(EQ(VAR('c3this'), txt('Exception')), [
          setV('c3hit', num(1))
        ], [
          callProc('sprefix %s %s %s', [VAR('error'), VAR('c3this'), txt('startswith')]),
          IF(EQ(VAR('ev'), num(1)), [setV('c3hit', num(1))]),
          IF(EQ(VAR('c3hit'), num(0)), [
            ...subHit()
          ])
        ])
      ], [])
    ]),
    setV('ev', VAR('c3hit'))
  ]);
  console.log('[P133] excmatch registered');

  // ---------- (c) the clause name now comes from clnames (P51's try branch, P132's walk)
  const isTok2 = (d) => {
    const q = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return !!q && q.opcode === 'data_itemoflist' && q.fields.LIST && q.fields.LIST[0] === 'Tok'
      && litOf(q.inputs.INDEX) === '2';
  };
  const tnmIf = find(inDef('execute'), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
    && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
      const q = BL()[x];
      return !!q && q.opcode === 'data_setvariableto' && q.fields.VARIABLE && q.fields.VARIABLE[0] === 'tnm'
        && isTok2(q.inputs.VALUE);
    })
    && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      if (!q || q.opcode !== 'operator_gt') return false;
      // tell the try branch (length(Tok) > 2) apart from the raise branch (count > 1)
      const a = (q.inputs.OPERAND1 && typeof q.inputs.OPERAND1[1] === 'string') ? BL()[q.inputs.OPERAND1[1]] : null;
      return !!a && a.opcode === 'data_lengthoflist' && a.fields.LIST && a.fields.LIST[0] === 'Tok';
    }));
  if (tnmIf.length !== 1) throw new Error('[P133] try clause name = ' + tnmIf.length);
  // (replaceStmt swaps in a single statement, so group the two under an always-true IF)
  replaceStmt(tnmIf[0], IF(EQ(num(1), num(1)), [
    setV('c3line', VAR('tpc')), callProc('clnames'), setV('tnm', VAR('c3nm'))
  ]));
  //   P132's walk: `if length(Tok) > 2: t2n = Tok[2] else t2n = ''`
  const t2nIf = find(reach(defIdOf('trycatch')), (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK
    && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
      const q = BL()[x];
      return !!q && q.opcode === 'data_setvariableto' && q.fields.VARIABLE && q.fields.VARIABLE[0] === 't2n';
    })
    && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string'
    && [...reach(b.inputs.SUBSTACK2[1])].some((x) => {
      const q = BL()[x];
      return !!q && q.opcode === 'data_setvariableto' && q.fields.VARIABLE && q.fields.VARIABLE[0] === 't2n';
    }));
  if (t2nIf.length !== 1) throw new Error('[P133] walk clause name = ' + t2nIf.length);
  replaceStmt(t2nIf[0], IF(EQ(num(1), num(1)), [
    setV('c3line', VAR('t2x')), callProc('clnames'), setV('t2n', VAR('c3nm'))
  ]));
  console.log('[P133] clause names come from clnames');

  // ---------- (d) a comma means a tuple clause: test it with excmatch, in front of the prefix test
  {
    const sprefix = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'sprefix %s %s %s');
    // `callProc` inlines its arguments as [12, name, id] primitives, so the tested name is visible
    // in the call's own input JSON (the second argument, e.g. `tnm` / `t2n` / `c3this`)
    const usesVar = (id, name) => JSON.stringify(BL()[id].inputs || {}).includes('[12,"' + name + '",');
    const walk = sprefix.filter((id) => usesVar(id, 't2n'));
    const tryc = sprefix.filter((id) => usesVar(id, 'tnm'));
    if (walk.length !== 1 || tryc.length !== 1) {
      throw new Error('[P133] sprefix sites: walk=' + walk.length + ' try=' + tryc.length + ' of ' + sprefix.length);
    }
    insertBeforeStmt(tryc[0], [
      IF(strHas(VAR('tnm'), txt(',')), [
        setV('c3nm', VAR('tnm')), callProc('excmatch', []),
        IF(EQ(VAR('ev'), num(1)), [setV('tcl', num(1))])
      ])
    ]);
    insertBeforeStmt(walk[0], [
      IF(strHas(VAR('t2n'), txt(',')), [
        setV('c3nm', VAR('t2n')), callProc('excmatch', []),
        IF(EQ(VAR('ev'), num(1)), [setV('t2hit', num(1))])
      ])
    ]);
  }
  console.log('[P133] tuple clauses are matched as a list');
});

// ---- P134: built-in exception message texts (v4.61) ----
//
// MiniPy raises the right *class* almost everywhere but the text after the colon is either missing or
// is an older CPython wording, so `except X as e: print(e)` (P112 binds the text after the first ':')
// reads differently from CPython:
//
//   ZeroDivisionError      -> ''                                (CPython: division by zero)
//   NameError              -> 'nosuch' / 'function nosuchfn'     (name 'nosuch' is not defined)
//   ValueError (list)      -> '3 is not in list'                 (list.index(x): x not in list)
//   ValueError (max)       -> 'max() arg is an empty sequence'   (max() iterable argument is empty)
//   TypeError  (len)       -> 'len requires string'              (object of type 'int' has no len())
//   IndexError (tuple)     -> 'list index out of range'          (tuple index out of range)
//   KeyError               -> "'b'" quoting missing for strings  (KeyError: 'b')
//
// Every one of them is a *message* change: find the `fail %s` call whose message is the old text (it
// is either a plain literal or a JOIN over the variables that built it) and swap the message input.
// Nothing about the control flow, the handler matching (P51/P132/P133 all test a name *prefix*) or
// the `as e` binding changes -- the bound message just becomes non-empty and CPython-shaped.
//
// The `len` case needs the *type name* of the value, which only exists as the tag in `evtype`, so a
// small `tname` proc turns (evtype, value) into `int`/`float`/`str`/... -- it reads the two globals
// and answers through `p6msg` instead of `ev`, so the value under test is never clobbered (P131's
// lesson: a helper that answers via `ev` eats its caller's operand).
//
// P68 clones `callfn` into `callfnW` *after* this patch, so the fix lands in both copies for free.
patch('P134 exception messages', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const VARS = ['p6v', 'p6t', 'p6msg', 'p6msg2', 'p6op'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P134] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);

  const failIds = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation
    && b.mutation.proccode === 'fail %s');
  if (failIds.length < 20) throw new Error('[P134] fail calls = ' + failIds.length);
  const slotOf = (id) => Object.keys(BL()[id].inputs)[0];
  const msgOf = (id) => BL()[id].inputs[slotOf(id)];
  const setMsg = (id, expr) => {
    const k = slotOf(id);
    const v = BL()[id].inputs[k];
    // a text literal is its own input descriptor ([1, [10, 'text']]); anything else is a block id
    if (Array.isArray(expr)) { BL()[id].inputs[k] = expr; return; }
    BL()[id].inputs[k] = v.length > 2 ? [3, expr, v[2]] : [3, expr];
  };
  const blkOf = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const joinOf = (id) => { const j = blkOf(msgOf(id)); return (j && j.opcode === 'operator_join') ? j : null; };
  const firstLit = (j) => litOf(j.inputs.STRING1);
  // does any block under the message carry this text? (the text of a JOIN sits in a subtree)
  const msgHas = (id, needle) => {
    const d = msgOf(id);
    const seen = new Set();
    const stack = typeof d[1] === 'string' ? [d[1]] : [];
    while (stack.length) {
      const x = stack.pop();
      if (seen.has(x)) continue;
      seen.add(x);
      const q = BL()[x];
      if (!q) continue;
      for (const v of Object.values(q.inputs || {})) {
        if (JSON.stringify(v).includes(needle)) return true;
        if (typeof v[1] === 'string') stack.push(v[1]);
      }
    }
    return false;
  };
  const exact = (text) => failIds.filter((id) => litOf(msgOf(id)) === text);

  // ---------- (a) ZeroDivisionError: 'division by zero' (CPython 3.14 uses one wording for all of
  //              / // % on ints and floats).  The bare `ZeroDivisionError` is rightside's arithmetic
  //              branch; the long text is P28's divmod.
  for (const old of ['ZeroDivisionError', 'ZeroDivisionError: integer division or modulo by zero']) {
    const hit = exact(old);
    if (hit.length !== 1) throw new Error('[P134] ' + old + ' sites = ' + hit.length);
    setMsg(hit[0], txt('ZeroDivisionError: division by zero'));
  }
  console.log('[P134] ZeroDivisionError text');

  // ---------- (b) NameError: "name '<x>' is not defined".
  //   `"NameError: " + x`                     (atom lookup, augmented assignment, unknown 2-arg call)
  //   `"NameError: function " + fn`           (callfn: not a function name)
  //   `"NameError: name " + cpar`             (execute: class parent is not a class)
  //   `"NameError: name " + Tok[lo] + " is not defined"`  (P28j -- quotes missing)
  const neText = (operand) => JOIN(JOIN(txt("NameError: name '"), operand), txt("' is not defined"));
  let neFixed = 0;
  for (const id of failIds.slice()) {
    const j = joinOf(id);
    if (!j) continue;
    const head = firstLit(j);
    if (head === 'NameError: ' || head === 'NameError: function ' || head === 'NameError: name ') {
      setMsg(id, neText(j.inputs.STRING2));
      neFixed++;
      continue;
    }
    // the nested form: JOIN(JOIN("NameError: name ", X), " is not defined")
    const inner = blkOf(j.inputs.STRING1);
    if (inner && inner.opcode === 'operator_join' && litOf(inner.inputs.STRING1) === 'NameError: name ') {
      setMsg(id, neText(inner.inputs.STRING2));
      neFixed++;
    }
  }
  // atom lookup, callfn's "function", P28j's unknown-call, execute's class parent, the three
  // augmented assignments and builtin2b's fall-through -- 10 raise sites in all
  if (neFixed !== 10) throw new Error('[P134] NameError sites = ' + neFixed);
  console.log('[P134] ' + neFixed + ' NameError messages');

  // ---------- (c) list.index / list.remove
  {
    const hit = failIds.filter((id) => msgHas(id, 'is not in list'));
    if (hit.length !== 2) throw new Error('[P134] is-not-in-list sites = ' + hit.length);
    // the `index` one sits under the `lmeth == "index"` test, the `remove` one under `lres == 0`
    const under = (id, varname) => {
      let cur = id;
      for (let g = 0; g < 400; g++) {
        const p = BL()[cur] ? BL()[cur].parent : null;
        if (!p) return false;
        cur = p;
        const q = BL()[cur];
        if (!q || (q.opcode !== 'control_if' && q.opcode !== 'control_if_else')) continue;
        const c = q.inputs.CONDITION;
        if (!c || typeof c[1] !== 'string') continue;
        for (const x of reach(c[1])) {
          const e = BL()[x];
          if (e && JSON.stringify(e.inputs || {}).includes('[12,"' + varname + '"')) return true;
        }
      }
      return false;
    };
    // the `remove` one sits under an `lres == 0` test; the `index` one does not (both are inside the
    // `lmeth == "index"` if-else, so that test alone cannot tell them apart)
    const rem = hit.filter((id) => under(id, 'lres'));
    const idx = hit.filter((id) => !under(id, 'lres'));
    if (idx.length !== 1 || rem.length !== 1) {
      throw new Error('[P134] index/remove sites: index=' + idx.length + ' remove=' + rem.length);
    }
    setMsg(idx[0], txt('ValueError: list.index(x): x not in list'));
    setMsg(rem[0], txt('ValueError: list.remove(x): x not in list'));
  }
  console.log('[P134] list.index / list.remove text');

  // ---------- (d) max()/min() of an empty sequence -- and it needs the ValueError prefix, without
  //              which `except ValueError` never saw it at all
  {
    const hit = failIds.filter((id) => {
      const j = joinOf(id);
      return !!j && litOf(j.inputs.STRING2) === '() arg is an empty sequence';
    });
    if (hit.length !== 1) throw new Error('[P134] empty-sequence sites = ' + hit.length);
    const j = joinOf(hit[0]);
    setMsg(hit[0], JOIN(JOIN(txt('ValueError: '), j.inputs.STRING1), txt('() iterable argument is empty')));
  }
  console.log('[P134] max()/min() empty text');

  // ---------- (e) len(): "object of type 'int' has no len()"
  const tn = newProc('tname', []);
  {
    const hit = exact('TypeError: len requires string');
    if (hit.length !== 1) throw new Error('[P134] len sites = ' + hit.length);
    insertBeforeStmt(hit[0], [
      setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', [])
    ]);
    setMsg(hit[0], JOIN(JOIN(txt("TypeError: object of type '"), VAR('p6msg')), txt("' has no len()")));
  }
  attachBody(tn.defId, [
    setV('p6msg', txt('object')),
    IF(EQ(VAR('p6t'), txt('B')), [setV('p6msg', txt('bool'))]),
    IF(EQ(VAR('p6t'), txt('Z')), [setV('p6msg', txt('NoneType'))]),
    IF(EQ(VAR('p6t'), txt('S')), [setV('p6msg', txt('str'))]),
    IF(EQ(VAR('p6t'), txt('L')), [setV('p6msg', txt('list'))]),
    IF(EQ(VAR('p6t'), txt('T')), [setV('p6msg', txt('tuple'))]),
    IF(EQ(VAR('p6t'), txt('D')), [setV('p6msg', txt('dict'))]),
    IF(EQ(VAR('p6t'), txt('E')), [setV('p6msg', txt('set'))]),
    IF(EQ(VAR('p6t'), txt('O')), [setV('p6msg', item('InstCls', VAR('p6v')))]),
    IF(EQ(VAR('p6t'), txt('N')), [
      IFELSE(strHas(VAR('p6v'), txt('.')), [setV('p6msg', txt('float'))], [setV('p6msg', txt('int'))])
    ])
  ]);
  console.log('[P134] len() type name');

  // ---------- (g) int()/float() literal messages.  CPython echoes the *original* text (spaces and
  //              all), so the value is saved before P2's trimsp rewrites `ev`.
  {
    const cf = inDef('callfn %s %s %s');
    const trims = find(cf, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'trimsp %s');
    if (trims.length !== 1) throw new Error('[P134] callfn trimsp sites = ' + trims.length);
    const hit = exact('ValueError: invalid number');
    if (hit.length !== 1) throw new Error('[P134] invalid number sites = ' + hit.length);
    const cm = newProc('castmsg %s', ['fn']);
    attachBody(cm.defId, [
      IFELSE(EQ(argOf('fn'), txt('int')), [
        setV('p6msg', JOIN(JOIN(txt("invalid literal for int() with base 10: '"), VAR('p6v')), txt("'")))
      ], [
        setV('p6msg', JOIN(JOIN(txt("could not convert string to float: '"), VAR('p6v')), txt("'")))
      ])
    ]);
    insertBeforeStmt(trims[0], [setV('p6v', VAR('ev'))]);
    insertBeforeStmt(hit[0], [callProc('castmsg %s', [argOf('fn')])]);
    setMsg(hit[0], JOIN(txt('ValueError: '), VAR('p6msg')));
  }
  console.log('[P134] int()/float() literal text');

  // ---------- (h) int(x, base) names the base and the text
  {
    const bn = inDef('basenum %s %s');
    const hit = find(bn, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'fail %s' && JSON.stringify(b.inputs).includes('invalid literal for int()'));
    if (hit.length !== 1) throw new Error('[P134] basenum sites = ' + hit.length);
    const head = JOIN(txt('ValueError: invalid literal for int() with base '), argOf('b'));
    const tail = JOIN(JOIN(txt("'"), argOf('s')), txt("'"));
    setMsg(hit[0], JOIN(JOIN(head, txt(': ')), tail));
  }
  console.log('[P134] int(x, base) text');

  // ---------- (i) unpack counts: "expected N, got M" (CPython omits "got M" when the source is a
  //              string, and both procs already hold both counts)
  const cnt = (n, m) => JOIN(JOIN(JOIN(JOIN(txt(' (expected '), n), txt(', got ')), m), txt(')'));
  {
    const al = inDef('assignlist %s');
    const ut = inDef('unpackto %s %s');
    const neIds = exact('ValueError: not enough values to unpack');
    const tmIds = exact('ValueError: too many values to unpack');
    if (neIds.length !== 2 || tmIds.length !== 2) {
      throw new Error('[P134] unpack sites: notEnough=' + neIds.length + ' tooMany=' + tmIds.length);
    }
    const alNe = neIds.filter((id) => al.has(id));
    const utNe = neIds.filter((id) => ut.has(id));
    const alTm = tmIds.filter((id) => al.has(id));
    const utTm = tmIds.filter((id) => ut.has(id));
    if (alNe.length !== 1 || utNe.length !== 1 || alTm.length !== 1 || utTm.length !== 1) {
      throw new Error('[P134] unpack split: ' + [alNe.length, utNe.length, alTm.length, utTm.length].join(','));
    }
    setMsg(alNe[0], JOIN(txt('ValueError: not enough values to unpack'), cnt(llen('AName'), VAR('aun'))));
    insertBeforeStmt(alTm[0], [
      IFELSE(EQ(VAR('aut'), txt('S')), [
        setV('p6msg', JOIN(JOIN(txt(' (expected '), llen('AName')), txt(')')))
      ], [
        setV('p6msg', cnt(llen('AName'), VAR('aun')))
      ])
    ]);
    setMsg(alTm[0], JOIN(txt('ValueError: too many values to unpack'), VAR('p6msg')));
    setMsg(utNe[0], JOIN(txt('ValueError: not enough values to unpack'), cnt(VAR('uncnt'), VAR('un'))));
    setMsg(utTm[0], JOIN(txt('ValueError: too many values to unpack'), cnt(VAR('uncnt'), VAR('un'))));
  }
  console.log('[P134] unpack counts');

  // ---------- (j) a non-iterable on the right of `a, b =` names the type
  {
    const al = inDef('assignlist %s');
    const hit = find(al, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'fail %s' && JSON.stringify(b.inputs).includes('cannot unpack non-iterable'));
    if (hit.length !== 1) throw new Error('[P134] non-iterable unpack sites = ' + hit.length);
    insertBeforeStmt(hit[0], [
      setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', [])
    ]);
    setMsg(hit[0], JOIN(JOIN(txt('TypeError: cannot unpack non-iterable '), VAR('p6msg')), txt(' object')));
  }
  console.log('[P134] non-iterable unpack text');

  // ---------- (k) a tuple says "tuple index out of range"
  {
    const ig = reach(defIdOf('indexget %s %s'));
    const hit = find(ig, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'fail %s' && JSON.stringify(b.inputs).includes('IndexError: list index out of range'));
    if (hit.length !== 1) throw new Error('[P134] indexget list-index sites = ' + hit.length);
    const old = hit[0];
    replaceStmt(old, IFELSE(EQ(VAR('xb'), txt('T')), [
      FAIL('IndexError: tuple index out of range')
    ], [
      FAIL('IndexError: list index out of range')
    ]));
  }
  console.log('[P134] tuple index out of range');

  // ---------- (g) KeyError quotes a string key (str(KeyError('b')) is the *repr* of the key)
  const ks = newProc('keystr', []);
  attachBody(ks.defId, [
    IFELSE(EQ(VAR('dgkt'), txt('S')), [
      setV('p6msg', JOIN(JOIN(txt("'"), VAR('dgkey')), txt("'")))
    ], [
      setV('p6msg', VAR('dgkey'))
    ])
  ]);
  {
    const hit = failIds.filter((id) => {
      const j = joinOf(id);
      return !!j && litOf(j.inputs.STRING1) === 'KeyError: ' && JSON.stringify(j.inputs.STRING2).includes('"dgkey"');
    });
    if (hit.length !== 3) throw new Error('[P134] dict KeyError sites = ' + hit.length);
    for (const id of hit) {
      insertBeforeStmt(id, [callProc('keystr', [])]);
      setMsg(id, JOIN(txt('KeyError: '), VAR('p6msg')));
    }
  }
  console.log('[P134] KeyError key repr (3 sites)');

  // ---------- (l) a type mismatch on an arithmetic operator names both types
  //              (CPython: "unsupported operand type(s) for +: 'int' and 'str'"; `**` adds "or pow()")
  {
    const hit = failIds.filter((id) => {
      const l = litOf(msgOf(id));
      return l === 'TypeError: numeric operands' || l === 'TypeError: use str(number)';
    });
    if (hit.length !== 3) throw new Error('[P134] operand-type sites = ' + hit.length);
    for (const id of hit) {
      const m1 = JOIN(JOIN(JOIN(JOIN(txt('unsupported operand type(s) for '), VAR('p6op')), txt(": '")), VAR('p6msg2')), txt("' and '"));
      insertBeforeStmt(id, [
        setV('p6v', argOf('leftval')), setV('p6t', VAR('lt2')), callProc('tname', []), setV('p6msg2', VAR('p6msg')),
        setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
        setV('p6op', argOf('op')),
        IF(EQ(VAR('p6op'), txt('**')), [setV('p6op', txt('** or pow()'))]),
        setV('p6msg', JOIN(JOIN(m1, VAR('p6msg')), txt("'")))
      ]);
      setMsg(id, JOIN(txt('TypeError: '), VAR('p6msg')));
    }
  }
  console.log('[P134] operand type mismatch text');
});

// ---- P135: C3 linearization for super() + the postfix chain no longer jumps the gun (v4.62) ----
//
// Two independent defects kept the diamond (`class D(B, C)`) from working; the checklist item is
// `d159` E4, whose body is `return 'B' + super().hi()`.
//
//  (1) `eval` looks for a postfix chain (`X . m (...)`) *before* it looks for a binary operator, so
//      for `'B' + super().hi()` the chain scan found the depth-0 dot inside the right operand and
//      handed `methodcall2` the receiver `'B' + super()`.  The super() hook then fired on the
//      *inner* span (`super` `(` `)`) -- it only checked the prefix and `Tok[hi] == ')'`, and
//      Tok[lo+3] happened to be the dot of the following `.hi` -- so the "receiver" evaluated to
//      'BA' and `.hi` was looked up on a string: `AttributeError: 'str' object has no attribute`.
//      `'B' + 'xy'.upper()` looked like it worked only because concatenating then upper-casing gives
//      the same text as upper-casing then concatenating.  The chain branch now sits *after* the
//      operator split (moved to the head of the `ecut == 0` else), which is where a chain belongs:
//      the operator decides the operands, and each operand is then free to be a chain.
//
//  (2) `super()` reached for the *running class's first parent*, which is not the C3 order: in the
//      diamond, B's `super()` must continue with C (the next class after B in D's MRO), not with
//      A.  Each class now records its linearization in `ClsMro` (comma-joined, computed at the
//      class statement with the usual C3 merge over the parents' MROs plus the parent list), and
//      `super()` walks the MRO of the *instance's* class (`InstCls[cinst]`) to the entry after
//      `cmet`.  `cmet` is the class whose method is running, so this is `super(Defining, self)`.
//
// The merge is written over comma-joined strings (class names have no commas in them): `shead` /
// `stail` / `shas` are the piece helpers and `m3merge` is the loop -- take the first head that does
// not appear in another list's tail, append it, drop it from every head.  An inconsistent hierarchy
// falls back to the first head instead of raising (CPython raises TypeError; MiniPy stays usable).
//
// Deliberately *not* changed here: the method/attribute tables are still filled by copying the
// parents' rows, so a class that inherits an override (D2/D5 below) still resolves it the old way.
// The MRO is only consulted by super().
patch('P135 C3 mro', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (i) => item('Tok', i);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const VARS = ['m3i', 'm3j', 'm3s', 'm3h', 'm3hd', 'm3has', 'm3q', 'm3r', 'm3n', 'm3t', 'm3cand', 'm3ok', 'm3acc', 'm3go',
    'm3p', 'm3z', 'm3mro', 'm3nm2', 'm3ch'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P135] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  for (const l of ['ClsMro', 'M3L', 'M3M', 'M3N']) B.addList(IT, l, []);

  // split a comma-separated string into list entries (the class names carry no spaces)
  const splitInto = (list, sExpr, pieceVar) => [
    clearL(list), setV(pieceVar, txt('')), setV('m3s', sExpr), setV('m3i', num(1)),
    REPEATU(GT(VAR('m3i'), ADD(lenOf(VAR('m3s')), num(1))), [
      setV('m3ch', letterOf(VAR('m3i'), VAR('m3s'))),
      IFELSE(OR(EQ(VAR('m3i'), ADD(lenOf(VAR('m3s')), num(1))), EQ(VAR('m3ch'), txt(','))), [
        IF(NOT(EQ(VAR(pieceVar), txt(''))), [addTo(list, VAR(pieceVar))]),
        setV(pieceVar, txt(''))
      ], [
        setV(pieceVar, JOIN(VAR(pieceVar), VAR('m3ch')))
      ]),
      chgV('m3i', num(1))
    ])
  ];

  // ---------- (a) shead / stail / shas: the pieces of a comma-joined list of class names
  //              NB shead walks with its *own* counter (m3q): the callers loop with m3i/m3j and
  //              would otherwise be cut short the moment a helper leaves the counter past the end.
  const sh = newProc('shead', []);
  attachBody(sh.defId, [
    setV('m3h', txt('')), setV('m3q', num(1)),
    REPEATU(OR(GT(VAR('m3q'), lenOf(VAR('m3s'))), EQ(letterOf(VAR('m3q'), VAR('m3s')), txt(','))), [
      setV('m3h', JOIN(VAR('m3h'), letterOf(VAR('m3q'), VAR('m3s')))),
      chgV('m3q', num(1))
    ])
  ]);
  const st = newProc('stail', []);
  attachBody(st.defId, [
    setV('m3r', txt('')),
    callProc('sfind %s %s', [VAR('m3s'), txt(',')]),
    IF(NOT(LT(VAR('ev'), num(0))), [
      callProc('substr %s %s %s', [VAR('m3s'), ADD(VAR('ev'), num(2)), lenOf(VAR('m3s'))]),
      setV('m3r', VAR('ev'))
    ])
  ]);
  // NB the answer must not live in `ev`: stail (called for the tail of every piece) answers through
  // `ev` as well, so the flag is kept in m3has and only copied to `ev` at the very end.
  const sa = newProc('shas', []);
  attachBody(sa.defId, [
    setV('m3has', num(0)), setV('m3t', VAR('m3s')),
    REPEATU(OR(EQ(VAR('m3t'), txt('')), EQ(VAR('m3has'), num(1))), [
      setV('m3s', VAR('m3t')), callProc('shead', []),
      callProc('compareText %s %s', [VAR('m3h'), VAR('m3n')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('m3has', num(1))]),
      callProc('stail', []),
      setV('m3t', VAR('m3r'))
    ]),
    setV('ev', VAR('m3has'))
  ]);

  // ---------- (b) clsmro: cname -> the class's linearization (or the name itself when unknown,
  //              e.g. a built-in base like Exception)
  const cm = newProc('clsmro', []);
  attachBody(cm.defId, [
    setV('ev', VAR('cname')), setV('m3p', num(0)), setV('m3z', num(1)),
    REPEATU(OR(GT(VAR('m3z'), llen('ClsName')), EQ(VAR('m3p'), num(1))), [
      callProc('compareText %s %s', [item('ClsName', VAR('m3z')), VAR('cname')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('ev', item('ClsMro', VAR('m3z'))), setV('m3p', num(1))]),
      chgV('m3z', num(1))
    ])
  ]);

  // ---------- (c) m3merge: merge the encoded lists in M3L (the parents' MROs, then the parent list)
  //              into one comma-joined linearization -> ev
  const mg = newProc('m3merge', []);
  attachBody(mg.defId, [
    setV('m3acc', txt('')), setV('m3go', num(1)),
    REPEATU(EQ(VAR('m3go'), num(0)), [
      setV('m3go', num(0)), setV('m3i', num(1)),
      REPEATU(GT(VAR('m3i'), llen('M3L')), [
        IF(NOT(EQ(item('M3L', VAR('m3i')), txt(''))), [setV('m3go', num(1))]),
        chgV('m3i', num(1))
      ]),
      IF(EQ(VAR('m3go'), num(1)), [
        setV('m3cand', txt('')), setV('m3i', num(1)),
        REPEATU(OR(GT(VAR('m3i'), llen('M3L')), NOT(EQ(VAR('m3cand'), txt('')))), [
          setV('m3s', item('M3L', VAR('m3i'))),
          IF(NOT(EQ(VAR('m3s'), txt(''))), [
            callProc('shead', []),
            // shas walks the other lists with shead, which overwrites m3h -- keep the head here
            setV('m3hd', VAR('m3h')),
            setV('m3ok', num(1)), setV('m3j', num(1)),
            REPEATU(OR(GT(VAR('m3j'), llen('M3L')), EQ(VAR('m3ok'), num(0))), [
              IF(NOT(EQ(VAR('m3j'), VAR('m3i'))), [
                setV('m3s', item('M3L', VAR('m3j'))),
                callProc('stail', []),
                IF(NOT(EQ(VAR('m3r'), txt(''))), [
                  setV('m3s', VAR('m3r')), setV('m3n', VAR('m3hd')), callProc('shas', []),
                  IF(EQ(VAR('ev'), num(1)), [setV('m3ok', num(0))])
                ])
              ]),
              chgV('m3j', num(1))
            ]),
            IF(EQ(VAR('m3ok'), num(1)), [setV('m3cand', VAR('m3hd'))])
          ]),
          chgV('m3i', num(1))
        ]),
        // an inconsistent hierarchy: keep the first head instead of failing
        IF(EQ(VAR('m3cand'), txt('')), [
          setV('m3i', num(1)),
          REPEATU(OR(GT(VAR('m3i'), llen('M3L')), NOT(EQ(VAR('m3cand'), txt('')))), [
            setV('m3s', item('M3L', VAR('m3i'))),
            IF(NOT(EQ(VAR('m3s'), txt(''))), [callProc('shead', []), setV('m3cand', VAR('m3h'))]),
            chgV('m3i', num(1))
          ])
        ]),
        IF(NOT(EQ(VAR('m3cand'), txt(''))), [
          IFELSE(EQ(VAR('m3acc'), txt('')), [
            setV('m3acc', VAR('m3cand'))
          ], [
            setV('m3acc', JOIN(JOIN(VAR('m3acc'), txt(',')), VAR('m3cand')))
          ]),
          clearL('M3N'), setV('m3i', num(1)),
          REPEATU(GT(VAR('m3i'), llen('M3L')), [
            setV('m3s', item('M3L', VAR('m3i'))), callProc('shead', []),
            IFELSE(EQ(VAR('m3h'), VAR('m3cand')), [
              callProc('stail', []), addTo('M3N', VAR('m3r'))
            ], [
              addTo('M3N', VAR('m3s'))
            ]),
            chgV('m3i', num(1))
          ]),
          clearL('M3L'), setV('m3i', num(1)),
          REPEATU(GT(VAR('m3i'), llen('M3N')), [
            addTo('M3L', item('M3N', VAR('m3i'))),
            chgV('m3i', num(1))
          ])
        ])
      ])
    ]),
    setV('ev', VAR('m3acc'))
  ]);
  console.log('[P135] C3 merge helpers ready');

  // ---------- (d) the postfix chain must not swallow a binary operator: move methodcall2 from the
  //              head of the final else to the `ecut == 0` branch (after the operator split)
  {
    const evd = inDef('eval %s %s');
    const mc2 = find(evd, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation
      && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'methodcall2 %s %s %s');
    if (mc2.length !== 1) throw new Error('[P135] methodcall2 branch = ' + mc2.length);
    const rawSplit = find(evd, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation
      && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'pair %s %s %s %s'
      && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string');
    if (rawSplit.length !== 1) throw new Error('[P135] operator split branch = ' + rawSplit.length);
    const head = BL()[rawSplit[0]].inputs.SUBSTACK2[1];
    // detach the chain branch from its old place ...
    const pred = predecessorOf(mc2[0]);
    const nx = BL()[mc2[0]].next;
    if (pred) {
      BL()[pred].next = nx;
      if (nx) BL()[nx].parent = pred;
    } else {
      const ref = refOf(mc2[0]);
      if (!ref) throw new Error('[P135] cannot detach the chain branch');
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], nx, ref.v[2]] : [ref.v[0], nx];
      if (nx) BL()[nx].parent = ref.pid;
    }
    BL()[mc2[0]].next = null;
    // ... and put it at the head of the `no operator` branch
    insertBeforeStmt(head, [mc2[0]]);
    console.log('[P135] the postfix chain now runs after the operator split');
  }

  // ---------- (e) the class statement records the linearization
  const ex = inDef('execute');
  const split = find(ex, (b) => b.opcode === 'procedures_call' && b.mutation
    && b.mutation.proccode === 'clssplit');
  if (split.length !== 1) throw new Error('[P135] class split call = ' + split.length);
  spliceAfter(split[0], chain([
    setV('m3nm2', tokAt(num(2))),
    clearL('M3L'), setV('m3i', num(1)),
    REPEATU(GT(VAR('m3i'), llen('CQ2')), [
      setV('cname', item('CQ2', VAR('m3i'))), callProc('clsmro', []), addTo('M3L', VAR('ev')),
      chgV('m3i', num(1))
    ]),
    addTo('M3L', VAR('cspec')),
    callProc('m3merge', []),
    addTo('ClsMro', JOIN(JOIN(VAR('m3nm2'), txt(',')), VAR('ev')))
  ]));
  // a class without parents linearizes to itself
  const noPar = find(ex, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'ClsPar'
    && litOf(b.inputs.ITEM) === '');
  if (noPar.length !== 1) throw new Error('[P135] ClsPar empty append = ' + noPar.length);
  spliceAfter(noPar[0], chain([addTo('ClsMro', tokAt(num(2)))]));
  console.log('[P135] every class records its MRO');

  // ---------- (f) super() uses the instance's MRO
  {
    const hook = find(inDef('eval %s %s'), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'cname'
      && Array.isArray(BL()[b.inputs.SUBSTACK[1]].inputs.VALUE[1])
      && BL()[b.inputs.SUBSTACK[1]].inputs.VALUE[1][0] === 12
      && BL()[b.inputs.SUBSTACK[1]].inputs.VALUE[1][1] === 'cmet');
    if (hook.length !== 1) throw new Error('[P135] super hook = ' + hook.length);
    setStack(hook[0], 'SUBSTACK', [
      setV('ctmp', VAR('self')),
      setV('cinst', VAR('ctmp')),
      // the linearization of the class this instance really has
      setV('cname', item('InstCls', VAR('cinst'))), callProc('clsmro', []),
      ...splitInto('CQ2', VAR('ev'), 'cpiece'),
      setV('cup', txt('')), setV('m3i', num(1)),
      REPEATU(OR(GT(VAR('m3i'), llen('CQ2')), NOT(EQ(VAR('cup'), txt('')))), [
        callProc('compareText %s %s', [item('CQ2', VAR('m3i')), VAR('cmet')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('cup', item('CQ2', ADD(VAR('m3i'), num(1))))]),
        chgV('m3i', num(1))
      ]),
      // the running method's class is not on that MRO: fall back to its own first parent
      IF(EQ(VAR('cup'), txt('')), [
        setV('cname', VAR('cmet')), callProc('clspar', []),
        ...splitInto('CQ2', VAR('ev'), 'cpiece'),
        IF(GT(llen('CQ2'), num(0)), [setV('cup', item('CQ2', num(1)))])
      ]),
      IF(EQ(VAR('cup'), txt('')), [
        FAILB(JOIN(JOIN(txt("AttributeError: 'super' object has no attribute '"),
          tokAt(ADD(argOf('lo'), num(4)))), txt("'"))),
        STOPTHIS()
      ]),
      setV('ccls', VAR('cup')), setV('cmeth', tokAt(ADD(argOf('lo'), num(4)))),
      setV('clo', ADD(argOf('lo'), num(6))), setV('chi', SUB(argOf('hi'), num(1))),
      callProc('callcls', []),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ]);
    console.log('[P135] super() walks the instance MRO');
  }

  // ---------- (g) reset the new table at run start
  {
    const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST
      && b.fields.LIST[0] === 'ClsPar');
    if (runInit.length !== 1) throw new Error('[P135] run init anchor = ' + runInit.length);
    spliceAfter(runInit[0], chain([clearL('ClsMro')]));
  }
  console.log('[P135] C3 order ready');
});

// ---- P136: method/attribute tables follow the C3 MRO (v4.63) ----
//
// P135 gave every class a linearization and routed `super()` through it, but the method and
// attribute tables are still filled by *copying the parents' rows*, and a copy cannot tell "this
// class defines it" from "this class inherited it".  Two consequences (`d191` D2/D5):
//
//   class D(B, C) with B defining nothing and C overriding `hi` -> D().hi() should run C's, but the
//   copy of B carried A's version along and won; likewise `D().n` picked A's attribute instead of C's.
//
// So each row now records its *owner* and the copies only take rows the parent itself defines:
//
//   * `IAttrOwn` (parallel to IAttrId) is written by P90's class-body `name = value` handler (both
//     the append and the in-place replace paths) and by the attribute copy itself (a copied row keeps
//     the original definer, so a grandchild does not copy it again -- it comes along by MRO instead);
//   * for methods there is no such column, but a class's *own* methods are exactly the `FnName`
//     entries added after its copies ran, so `ClsFn1[i]` snapshots `length(FnName)` right after the
//     copies and `clscopy` skips everything at or below the parent's snapshot;
//   * the two copy loops now walk the child's MRO (`M3M`, the pieces of the string P135 stored in
//     `ClsMro`) instead of the direct parent list: methods **down** it (farthest ancestor first, so
//     the nearest one is appended last and wins -- `calluser` searches from the end) and attributes
//     **up** it (nearest first, because IAttr is scanned front to back).
//
// `ClsAt1` is stored for symmetry/debugging (the attribute owner is the explicit column).
patch('P136 mro copy', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable')
      ? BL()[d[1]].fields.VARIABLE[0] : null);
  const VARS = ['m6i', 'm6n', 'm6p', 'm6s', 'm6q', 'm6ch', 'm6pc', 'm6mro', 'm6lim'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P136] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  for (const l of ['M3M', 'IAttrOwn', 'ClsFn1', 'ClsAt1']) B.addList(IT, l, []);

  const replaceItem = (list, idx, val) => I('data_replaceitemoflist', {
    fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(val, [10, '']) }
  });
  // split a comma-joined string into a list (the MRO pieces)
  const splitInto = (list, sExpr, pieceVar) => [
    clearL(list), setV(pieceVar, txt('')), setV('m6s', sExpr), setV('m6q', num(1)),
    REPEATU(GT(VAR('m6q'), ADD(lenOf(VAR('m6s')), num(1))), [
      setV('m6ch', letterOf(VAR('m6q'), VAR('m6s'))),
      IFELSE(OR(EQ(VAR('m6q'), ADD(lenOf(VAR('m6s')), num(1))), EQ(VAR('m6ch'), txt(','))), [
        IF(NOT(EQ(VAR(pieceVar), txt(''))), [addTo(list, VAR(pieceVar))]),
        setV(pieceVar, txt(''))
      ], [
        setV(pieceVar, JOIN(VAR(pieceVar), VAR('m6ch')))
      ]),
      chgV('m6q', num(1))
    ])
  ];

  // ---------- (a) clsfn1: cname -> the parent's own-method boundary (its length(FnName) snapshot)
  const cf = newProc('clsfn1', []);
  attachBody(cf.defId, [
    setV('ev', num(0)), setV('m6p', num(0)), setV('m6i', num(1)),
    REPEATU(OR(GT(VAR('m6i'), llen('ClsName')), EQ(VAR('m6p'), num(1))), [
      callProc('compareText %s %s', [item('ClsName', VAR('m6i')), VAR('cname')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('ev', item('ClsFn1', VAR('m6i'))), setV('m6p', num(1))]),
      chgV('m6i', num(1))
    ])
  ]);

  // ---------- (b) P90's class-body attribute handler also fills IAttrOwn
  {
    const ccsav = find(allIds(), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'ccsav' && varName(b.inputs.VALUE) === 'ccls');
    if (ccsav.length !== 1) throw new Error('[P136] class-body handler = ' + ccsav.length);
    const app = find(reach(ccsav[0]), (b) => b.opcode === 'data_addtolist' && b.fields.LIST
      && b.fields.LIST[0] === 'IAttrType');
    if (app.length !== 1) throw new Error('[P136] IAttrType append = ' + app.length);
    spliceAfter(app[0], chain([addTo('IAttrOwn', VAR('ccsav'))]));
    const rep = find(reach(ccsav[0]), (b) => b.opcode === 'data_replaceitemoflist' && b.fields.LIST
      && b.fields.LIST[0] === 'IAttrType');
    if (rep.length !== 1) throw new Error('[P136] IAttrType replace = ' + rep.length);
    spliceAfter(rep[0], chain([replaceItem('IAttrOwn', VAR('cX'), VAR('ccsav'))]));
    console.log('[P136] the class body records attribute ownership');
  }

  // ---------- (c) clscopyattr copies only the parent's *own* rows (and keeps the owner column)
  {
    const def = defIdOf('clscopyattr');
    attachBody(def, [
      setV('m6n', llen('IAttrId')), setV('m6i', num(1)),
      REPEATU(GT(VAR('m6i'), VAR('m6n')), [
        IF(AND(EQ(item('IAttrId', VAR('m6i')), VAR('cpar2')), EQ(item('IAttrOwn', VAR('m6i')), VAR('cpar2'))), [
          addTo('IAttrId', VAR('ccls')),
          addTo('IAttrName', item('IAttrName', VAR('m6i'))),
          addTo('IAttrVal', item('IAttrVal', VAR('m6i'))),
          addTo('IAttrType', item('IAttrType', VAR('m6i'))),
          addTo('IAttrOwn', VAR('cpar2'))
        ]),
        chgV('m6i', num(1))
      ])
    ]);
    console.log('[P136] attribute copies are owner-filtered');
  }

  // ---------- (d) clscopy skips the parent's inherited entries as well
  {
    // the guard around the FnName append *inside clscopy* (not the class statement's own ifs)
    const fnAdd = find(inDef('clscopy'), (b) => b.opcode === 'data_addtolist' && b.fields.LIST
      && b.fields.LIST[0] === 'FnName');
    if (fnAdd.length !== 1) throw new Error('[P136] clscopy FnName append = ' + fnAdd.length);
    const guard = ancestor(fnAdd[0], (b) => b.opcode === 'control_if');
    if (!guard) throw new Error('[P136] clscopy guard not found');
    const cond = BL()[guard].inputs.CONDITION;
    if (!cond || typeof cond[1] !== 'string') throw new Error('[P136] clscopy guard condition');
    replaceExpr(cond[1], () => AND(cond[1], GT(VAR('cpk'), VAR('m6lim'))));
    console.log('[P136] method copies are owner-filtered');
  }

  // ---------- (d2) P106's copy loop is still inlined in `execute` (first parent only, before the
  //              class name is even appended) and duplicates P127's work.  It also copies the
  //              parent's *inherited* entries, which is exactly what this patch is fixing, so its
  //              loop is neutralised -- the "parent class must exist" check above it stays.
  {
    const inlineFn = find(inDef('execute'), (b) => b.opcode === 'data_addtolist' && b.fields.LIST
      && b.fields.LIST[0] === 'FnName');
    if (inlineFn.length !== 1) throw new Error('[P136] legacy FnName append = ' + inlineFn.length);
    const legacy = ancestor(inlineFn[0], (b) => b.opcode === 'control_repeat_until');
    if (!legacy) throw new Error('[P136] legacy copy loop not found');
    const cond = BL()[legacy].inputs.CONDITION;
    replaceExpr(cond[1], () => EQ(num(1), num(1)));
    console.log('[P136] the legacy inline copy is off');
  }

  // ---------- (e) store the linearization pieces and re-point the two copy loops at them
  {
    const ex = inDef('execute');
    const mroAdd = find(ex, (b) => b.opcode === 'data_addtolist' && b.fields.LIST
      && b.fields.LIST[0] === 'ClsMro' && b.inputs.ITEM && typeof b.inputs.ITEM[1] === 'string'
      && BL()[b.inputs.ITEM[1]] && BL()[b.inputs.ITEM[1]].opcode === 'operator_join');
    if (mroAdd.length !== 1) throw new Error('[P136] ClsMro append = ' + mroAdd.length);
    spliceAfter(mroAdd[0], chain([
      setV('m6mro', item('ClsMro', llen('ClsMro'))),
      ...splitInto('M3M', VAR('m6mro'), 'm6pc'),
      setV('m6i', num(1)),
      REPEATU(GT(VAR('m6i'), llen('M3M')), [
        chgV('m6i', num(1))
      ]),
      setV('m6i', num(1)),
      REPEATU(GT(VAR('m6i'), llen('FnName')), [
        chgV('m6i', num(1))
      ])
    ]));
    // a class without parents: its MRO is itself, and it has nothing to copy
    const noPar = find(ex, (b) => b.opcode === 'data_addtolist' && b.fields.LIST
      && b.fields.LIST[0] === 'ClsMro' && litOf(b.inputs.ITEM) === null
      && b.inputs.ITEM && typeof b.inputs.ITEM[1] === 'string'
      && BL()[b.inputs.ITEM[1]] && BL()[b.inputs.ITEM[1]].opcode === 'data_itemoflist');
    if (noPar.length !== 1) throw new Error('[P136] parentless ClsMro append = ' + noPar.length);
    spliceAfter(noPar[0], chain([
      setV('m6mro', item('ClsMro', llen('ClsMro'))),
      ...splitInto('M3M', VAR('m6mro'), 'm6pc'),
      addTo('ClsFn1', llen('FnName')), addTo('ClsAt1', llen('IAttrId'))
    ]));
    // the two loops
    const mCall = find(ex, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'clscopy');
    const aCall = find(ex, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'clscopyattr');
    if (mCall.length !== 1 || aCall.length !== 1) {
      throw new Error('[P136] copy calls: methods=' + mCall.length + ' attrs=' + aCall.length);
    }
    const mLoop = ancestor(mCall[0], (b) => b.opcode === 'control_repeat_until');
    const aLoop = ancestor(aCall[0], (b) => b.opcode === 'control_repeat_until');
    if (!mLoop || !aLoop) throw new Error('[P136] copy loops not found');
    // methods: walk the MRO *down* (index from the end, stop at index 2 -- index 1 is the child)
    const mCond = BL()[mLoop].inputs.CONDITION;
    replaceExpr(mCond[1], () => LT(VAR('csi'), num(2)));
    const mStart = predecessorOf(mLoop);
    if (!mStart || BL()[mStart].opcode !== 'data_setvariableto' || BL()[mStart].fields.VARIABLE[0] !== 'csi') {
      throw new Error('[P136] method loop start not found');
    }
    replaceExpr(BL()[mStart].inputs.VALUE[1], () => llen('M3M'));
    // attributes: walk the MRO *up* (index from 2)
    const aCond = BL()[aLoop].inputs.CONDITION;
    replaceExpr(aCond[1], () => GT(VAR('csi'), llen('M3M')));
    const aStart = predecessorOf(aLoop);
    if (!aStart || BL()[aStart].opcode !== 'data_setvariableto' || BL()[aStart].fields.VARIABLE[0] !== 'csi') {
      throw new Error('[P136] attribute loop start not found');
    }
    BL()[aStart].inputs.VALUE = B.REP(num(2), [4, '0']);
    // both loops read the parent out of M3M and set the method boundary before copying
    for (const [loop, callId] of [[mLoop, mCall[0]], [aLoop, aCall[0]]]) {
      const body = BL()[loop].inputs.SUBSTACK[1];
      const itemCQ = find(reach(body), (b) => b.opcode === 'data_itemoflist' && b.fields.LIST
        && b.fields.LIST[0] === 'CQ2');
      if (itemCQ.length !== 1) throw new Error('[P136] CQ2 read in a copy loop = ' + itemCQ.length);
      replaceExpr(itemCQ[0], () => item('M3M', VAR('csi')));
      if (callId === mCall[0]) {
        insertBeforeStmt(callId, [
          setV('cname', VAR('cpar2')), callProc('clsfn1', []), setV('m6lim', VAR('ev'))
        ]);
      }
    }
    // the boundary is recorded once the copies are done
    spliceAfter(aLoop, chain([addTo('ClsFn1', llen('FnName')), addTo('ClsAt1', llen('IAttrId'))]));
    console.log('[P136] the copy loops follow the MRO');
  }

  // ---------- (f) reset the new tables at run start
  {
    const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST
      && b.fields.LIST[0] === 'ClsMro');
    if (runInit.length !== 1) throw new Error('[P136] run init anchor = ' + runInit.length);
    spliceAfter(runInit[0], chain([clearL('IAttrOwn'), clearL('ClsFn1'), clearL('ClsAt1')]));
  }
  console.log('[P136] C3 ordered copies ready');
});

// ---- P137: the sorted() hook keeps a state stack (v4.64) ----
//
// P130's `sorted(...)` hook lives in `eval` and keeps its parse state in plain globals (`p4c`,
// `p4pos`, `p4klo`, ...).  Evaluating the iterable *is itself an eval*, so a nested `sorted(...)` --
// e.g. `sorted(sorted(xs, key=lambda p: -p), reverse=True)` -- runs the very same hook and
// overwrites that state.  The outer call then resumes with a clobbered comma position and dies in
// the tokenizer/operator scan: `SyntaxError: parentheses` (probe `d176` S2, the last item on the
// checklist's "P101 legacy" note).
//
// The fix is the usual scratch-frame trick: the hook pushes its whole scalar state onto `P4Stk` as
// it takes over and pops it back on the way out.  A nested call pushes the outer call's *current*
// values, so its own pop restores exactly the state the outer call was in the middle of -- the same
// pattern P127 uses for `cmet`/`self` and P125 for the comprehension loops.
//
// Only the scalars are stacked.  The three srtkey work lists (`P4Key`/`P4KeyT`/`P4Used`) are not:
// they are clobbered only by a nested keyword call *inside a key function*
// (`sorted(xs, key=lambda p: sorted(p, reverse=True)[0])`), which is still a known boundary.
patch('P137 sorted state stack', () => {
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  B.addList(IT, 'P4Stk', []);
  // everything the hook and srtkey keep in globals (p130.txt's list, minus the lists)
  const SAVE = ['p4c', 'p4pos', 'p4end', 'p4next', 'p4klo', 'p4khi', 'p4rlo', 'p4rhi', 'p4list', 'p4out',
    'p4bi', 'p4bin', 'p4fn', 'p4n', 'p4i', 'p4j', 'p4kl', 'p4sk', 'p4ks', 'p4kst', 'p4res', 'p4rt',
    'p4v', 'p4vt', 'p4vv', 'p4vk', 'p4tok', 'p4len0', 'p4lenk'];
  const push = SAVE.map((n) => addTo('P4Stk', VAR(n)));
  const pop = [];
  for (const n of [...SAVE].reverse()) {
    pop.push(setV(n, item('P4Stk', llen('P4Stk'))), delLast('P4Stk'));
  }

  // ---------- the hook: `IF Tok[lo] == "sorted"` whose substack starts with hascomma and whose
  //              *next* statement is the `tqhcm == 1` guard that opens with `p4c = tqcpz`
  const ev = inDef('eval %s %s');
  const startsWith = (id, pred) => {
    const q = (id && typeof id === 'string') ? BL()[id] : null;
    return !!q && pred(q);
  };
  const isHasComma = (q) => q.opcode === 'procedures_call' && q.mutation
    && q.mutation.proccode === 'hascomma %s %s';
  const isP4cSet = (q) => q.opcode === 'data_setvariableto' && q.fields.VARIABLE && q.fields.VARIABLE[0] === 'p4c'
    && q.inputs.VALUE && Array.isArray(q.inputs.VALUE[1]) && q.inputs.VALUE[1][0] === 12
    && q.inputs.VALUE[1][1] === 'tqcpz';
  const pred = (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.SUBSTACK) return false;
    const sub = BL()[b.inputs.SUBSTACK[1]];
    if (!sub || !isHasComma(sub)) return false;
    const g = sub.next ? BL()[sub.next] : null;
    return !!g && g.opcode === 'control_if' && !!g.inputs.SUBSTACK
      && startsWith(g.inputs.SUBSTACK[1], isP4cSet);
  };
  const hooks = find(ev, pred);
  if (hooks.length !== 1) throw new Error('[P137] sorted hook = ' + hooks.length);
  const outer = hooks[0];
  const gid = find(reach(BL()[outer].inputs.SUBSTACK[1]), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
    && startsWith(b.inputs.SUBSTACK[1], isP4cSet));
  if (gid.length !== 1) throw new Error('[P137] sorted comma guard = ' + gid.length);
  const body = BL()[gid[0]].inputs.SUBSTACK[1];
  insertBeforeStmt(body, push);
  // the hook ends with the `fnlimit` compensation + STOP THIS: pop just before that pair
  let tail = body, last = null, n = 0;
  while (tail && n++ < 400) { last = tail; tail = BL()[tail].next; }
  const stop = last;
  if (!stop || BL()[stop].opcode !== 'control_stop') throw new Error('[P137] sorted hook tail is not a stop');
  insertBeforeStmt(stop, pop);
  console.log('[P137] the sorted hook stacks ' + SAVE.length + ' variables');

  // ---------- reset the stack at run start
  const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST
    && b.fields.LIST[0] === 'ClsMro');
  if (runInit.length !== 1) throw new Error('[P137] run init anchor = ' + runInit.length);
  spliceAfter(runInit[0], chain([clearL('P4Stk')]));
  console.log('[P137] sorted() survives nested calls');
});

// ---- P138: sorting compares containers element-wise (v4.65) ----
//
// `lsort` (P13/P18) only knew two shapes: number vs number (Scratch's `>`) and string vs string
// (`compareText`); anything else -- including the very common `sorted([(2, 'b'), (1, 'a')])` -- fell
// into `TypeError: sort requires all numbers or all strings`.  CPython compares tuples and lists
// lexicographically: element by element, first difference wins, and a shorter prefix sorts first.
//
// So the comparison moves into a new `lcmp` procedure that takes its two *encoded* values through
// globals (`lca`/`lcat`/`lcb`/`lcbt`, the same "no custom-block arguments" rule P127 had to adopt)
// and answers in `cmp`:
//
//   * numbers and bools compare numerically, strings with `compareText` (what `lsort` did inline);
//   * tuples/lists walk their elements, pushing the current pair onto `LcStk` before recursing --
//     a nested tuple needs the outer pair back, and a fixed temporary would be clobbered by the
//     deeper level (the same reason P137 stacks the sorted() hook state);
//   * a shorter container that is a prefix of the other is smaller;
//   * everything else fails with CPython's wording, `'<' not supported between instances of 'X'
//     and 'Y'` -- the type names come from P134's `tname`, and the order is CPython's (`b < a`, i.e.
//     the right-hand element is named first).
//
// `lsort` keeps its bubble sort (stable: equal elements are never swapped), so `list.sort()`,
// `sorted()`, `sorted(..., key=...)` (whose keys go through the same sort) and `min`/`max` on
// containers all gain the behaviour at once.
patch('P138 container sort', () => {
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable')
      ? BL()[d[1]].fields.VARIABLE[0] : null);
  const VARS = ['lca', 'lcat', 'lcb', 'lcbt', 'lcn', 'lcm', 'lci', 'p4kv', 'p4kvt'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P138] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);
  B.addList(IT, 'LcStk', []);

  // `replaceStmt` takes a *single* statement (`newId.next` is rewritten), so a multi-statement
  // replacement needs the old block unlinked by hand
  const replaceStmtWith = (oldId, ids) => {
    const head = Array.isArray(ids) ? chain(ids.slice()) : ids;
    const first = insertBeforeStmt(oldId, [head]);
    const nx = BL()[oldId].next;
    let tail = first;
    while (BL()[tail].next && BL()[tail].next !== oldId) tail = BL()[tail].next;
    if (BL()[tail].next !== oldId) throw new Error('[P138] replacement chain is not in front of the target');
    BL()[tail].next = nx;
    if (nx) BL()[nx].parent = tail;
    BL()[oldId].next = null;
    return first;
  };

  // the mismatch message: CPython compares `b < a`, so the *right* operand is named first
  const typeErr = () => {
    const j1 = JOIN(JOIN(txt("TypeError: '<' not supported between instances of '"), VAR('p6msg2')), txt("' and '"));
    return [
      setV('p6v', VAR('lcb')), setV('p6t', VAR('lcbt')), callProc('tname', []), setV('p6msg2', VAR('p6msg')),
      setV('p6v', VAR('lca')), setV('p6t', VAR('lcat')), callProc('tname', []),
      FAILB(JOIN(JOIN(j1, VAR('p6msg')), txt("'")))
    ];
  };
  const sameType = (tag) => OR(EQ(VAR('lcat'), txt(tag)), EQ(VAR('lcbt'), txt(tag)));

  // ---------- (a) lcmp: lca/lcat vs lcb/lcbt -> cmp
  const numFam = (v) => OR(EQ(VAR(v), txt('N')), EQ(VAR(v), txt('B')));
  const isCont = (v) => OR(EQ(VAR(v), txt('T')), EQ(VAR(v), txt('L')));
  const lc = newProc('lcmp', []);
  attachBody(lc.defId, [
    setV('cmp', num(0)),
    // numbers and bools are one numeric family (CPython: False < 0 < True < 2)
    IFELSE(AND(numFam('lcat'), numFam('lcbt')), [
      IF(GT(VAR('lca'), VAR('lcb')), [setV('cmp', num(1))]),
      IF(LT(VAR('lca'), VAR('lcb')), [setV('cmp', num(-1))])
    ], [
      IFELSE(EQ(VAR('lcat'), VAR('lcbt')), [
        IF(EQ(VAR('lcat'), txt('S')), [
          callProc('compareText %s %s', [VAR('lca'), VAR('lcb')])
        ]),
        // tuples and lists: element by element, first difference wins, a shorter prefix is smaller
        IF(isCont('lcat'), [
          callProc('listlen %s', [VAR('lca')]), setV('lcn', VAR('ev')),
          callProc('listlen %s', [VAR('lcb')]), setV('lcm', VAR('ev')),
          setV('lci', num(1)),
          REPEATU(OR(OR(GT(VAR('lci'), VAR('lcn')), GT(VAR('lci'), VAR('lcm'))), NOT(EQ(VAR('cmp'), num(0)))), [
            addTo('LcStk', VAR('lca')), addTo('LcStk', VAR('lcat')),
            addTo('LcStk', VAR('lcb')), addTo('LcStk', VAR('lcbt')),
          callProc('listitem %s %s', [VAR('lca'), VAR('lci')]),
          setV('lca', VAR('ev')), setV('lcat', VAR('evtype')),
          callProc('listitem %s %s', [VAR('lcb'), VAR('lci')]),
          setV('lcb', VAR('ev')), setV('lcbt', VAR('evtype')),
          callProc('lcmp', []),
          setV('lcbt', item('LcStk', llen('LcStk'))), delLast('LcStk'),
          setV('lcb', item('LcStk', llen('LcStk'))), delLast('LcStk'),
          setV('lcat', item('LcStk', llen('LcStk'))), delLast('LcStk'),
          setV('lca', item('LcStk', llen('LcStk'))), delLast('LcStk'),
          chgV('lci', num(1))
        ]),
        IF(EQ(VAR('cmp'), num(0)), [
          IF(LT(VAR('lcn'), VAR('lcm')), [setV('cmp', num(-1))]),
          IF(GT(VAR('lcn'), VAR('lcm')), [setV('cmp', num(1))])
        ])
        ]),
        // the remaining same-type pairs are not orderable at all: None, dict, set, instance,
        // function, exception (strings/containers/numbers were handled above)
        IF(OR(OR(OR(EQ(VAR('lcat'), txt('Z')), EQ(VAR('lcat'), txt('D'))),
          OR(EQ(VAR('lcat'), txt('E')), EQ(VAR('lcat'), txt('O')))),
        OR(EQ(VAR('lcat'), txt('F')), EQ(VAR('lcat'), txt('C')))), [...typeErr()])
      ], [
        ...typeErr()
      ])
    ])
  ]);
  console.log('[P138] lcmp registered');

  // ---------- (b) lsort asks lcmp instead of the two inline cases
  {
    const ls = inDef('lsort %s');
    const cmpIf = find(ls, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => {
        const q = BL()[x];
        return !!q && q.opcode === 'operator_equals' && varName(q.inputs.OPERAND1) === 'lsat'
          && litOf(q.inputs.OPERAND2) === 'N';
      })
      && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string'
      && [...reach(b.inputs.SUBSTACK2[1])].some((x) => {
        const q = BL()[x];
        return !!q && q.opcode === 'procedures_call' && q.mutation
          && q.mutation.proccode === 'fail %s' && JSON.stringify(q.inputs).includes('sort requires');
      }));
    if (cmpIf.length !== 1) throw new Error('[P138] lsort compare branch = ' + cmpIf.length);
    replaceStmtWith(cmpIf[0], [
      setV('lca', VAR('lsav')), setV('lcat', VAR('lsat')),
      setV('lcb', VAR('lsbv')), setV('lcbt', VAR('lsbt')),
      callProc('lcmp', []),
      IF(GT(VAR('cmp'), num(0)), [setV('lswap', num(1))])
    ]);
    // the re-encoding has to escape container elements, exactly like lrev does
    const acc = find(ls, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'lsacc2' && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
      && BL()[b.inputs.VALUE[1]].opcode === 'operator_join');
    if (acc.length !== 1) throw new Error('[P138] lsort re-encode = ' + acc.length);
    const accId = acc[0];
    insertBeforeStmt(accId, [callProc('lesc %s', [item('LSV', VAR('lsix'))])]);
    const enc = BL()[accId].inputs.VALUE;
    replaceExpr(enc[1], () => JOIN(JOIN(JOIN(VAR('lsacc2'), VAR('lsep')), item('LST', VAR('lsix'))), VAR('ev')));
    console.log('[P138] lsort compares containers');
  }

  // ---------- (c) min()/max(): both the single-iterable loop in callfn and the n-ary loop in
  //              `minmax` compare the running best by hand; both go through lcmp now
  const cmpVars = (id) => {
    const out = new Set();
    const seen = new Set();
    const stack = [id];
    while (stack.length) {
      const x = stack.pop();
      if (!x || seen.has(x)) continue;
      seen.add(x);
      const q = BL()[x];
      if (!q) continue;
      for (const v of Object.values(q.inputs || {})) {
        if (Array.isArray(v[1]) && v[1][0] === 12) out.add(v[1][1]);
        if (typeof v[1] === 'string') stack.push(v[1]);
      }
      if (q.next) stack.push(q.next);
    }
    return out;
  };
  const compareBlock = (best, bestT) => [
    setV('lca', VAR('ev')), setV('lcat', VAR('evtype')),
    setV('lcb', VAR(best)), setV('lcbt', VAR(bestT)),
    callProc('lcmp', []),
    IFELSE(EQ(argOf('fn'), txt('max')), [
      IF(GT(VAR('cmp'), num(0)), [setV(best, VAR('lca')), setV(bestT, VAR('lcat'))])
    ], [
      IF(LT(VAR('cmp'), num(0)), [setV(best, VAR('lca')), setV(bestT, VAR('lcat'))])
    ])
  ];
  {
    // callfn: `if mmt == "N" and evtype == "N":` (the string branch below it becomes dead code)
    const cf = inDef('callfn %s %s %s');
    const pickIf = find(cf, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && (() => { const vs = cmpVars(b.inputs.CONDITION[1]); return vs.has('mmt') && vs.has('evtype'); })()
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'control_if_else');
    if (pickIf.length !== 1) throw new Error('[P138] callfn min/max pick = ' + pickIf.length);
    replaceExpr(BL()[pickIf[0]].inputs.CONDITION[1], () => EQ(num(1), num(1)));
    setStack(pickIf[0], 'SUBSTACK', compareBlock('mmv', 'mmt'));
    console.log('[P138] min/max on an iterable compares containers');
  }
  {
    // minmax: `if mtype == "N" and evtype == "N":`
    const mm = inDef('minmax %s %s %s');
    const pickIf = find(mm, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && cmpVars(b.inputs.CONDITION[1]).has('mtype')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'control_if_else');
    if (pickIf.length !== 1) throw new Error('[P138] minmax pick = ' + pickIf.length);
    replaceExpr(BL()[pickIf[0]].inputs.CONDITION[1], () => EQ(num(1), num(1)));
    setStack(pickIf[0], 'SUBSTACK', compareBlock('mbest', 'mtype'));
    console.log('[P138] minmax compares containers');
  }

  // ---------- (d) srtkey embeds its keys, so container keys need the same escaping
  {
    const sk = inDef('srtkey');
    const call = find(sk, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'callval');
    const keyAdd = find(sk, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'P4Key');
    if (call.length !== 1 || keyAdd.length !== 1) {
      throw new Error('[P138] srtkey anchors: callval=' + call.length + ' P4Key=' + keyAdd.length);
    }
    // drop everything between the key call and the P4Key append, then rebuild it
    const first = BL()[call[0]].next;
    let tail = first, g = 0;
    while (tail && tail !== keyAdd[0] && g++ < 50) tail = BL()[tail].next;
    if (tail !== keyAdd[0]) throw new Error('[P138] srtkey key block is not behind callval');
    BL()[call[0]].next = keyAdd[0];
    BL()[keyAdd[0]].parent = call[0];
    spliceAfter(call[0], chain([
      setV('p4kv', VAR('ev')), setV('p4kvt', VAR('evtype')),
      IFELSE(EQ(VAR('p4kvt'), txt('B')), [
        setV('p4kl', JOIN(JOIN(JOIN(VAR('p4kl'), VAR('lsep')), txt('N')), VAR('p4kv')))
      ], [
        callProc('lesc %s', [VAR('p4kv')]),
        setV('p4kl', JOIN(JOIN(JOIN(VAR('p4kl'), VAR('lsep')), VAR('p4kvt')), VAR('ev')))
      ])
    ]));
    // the key tables keep the *raw* value (the matching loop compares them with the decoded keys)
    const oldAdds = find(sk, (b) => b.opcode === 'data_addtolist' && b.fields.LIST
      && (b.fields.LIST[0] === 'P4Key' || b.fields.LIST[0] === 'P4KeyT'));
    for (const id of oldAdds) {
      const v = BL()[id].fields.LIST[0] === 'P4Key' ? VAR('p4kv') : VAR('p4kvt');
      BL()[id].inputs.ITEM = B.REP(v, [4, '0']);
    }
    console.log('[P138] srtkey escapes container keys');
  }

  // ---------- (e) reset the recursion stack at run start
  {
    const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST
      && b.fields.LIST[0] === 'P4Stk');
    if (runInit.length !== 1) throw new Error('[P138] run init anchor = ' + runInit.length);
    spliceAfter(runInit[0], chain([clearL('LcStk')]));
  }
  console.log('[P138] container sort ready');
});

// ---- P139: sequence-operator errors (v4.66) ----
//
// P134 aligned the *generic* operand-type message, but CPython special-cases the two sequence
// operators, and the `*` path had a real bug behind the wrong message:
//
//   'a' + 1      -> can only concatenate str (not "int") to str      (generic wording before)
//   'a' * 'b'    -> can't multiply sequence by non-int of type 'str' (MiniPy returned ''!)
//   'a' * 1.5    -> can't multiply sequence by non-int of type 'float' (returned 'aa')
//   [1] * 'a'    -> can't multiply sequence by non-int of type 'str' (returned 'a')
//   1.5 * None   -> unsupported operand type(s) for *: 'float' and 'NoneType' (returned 0.0)
//
// So `binerr` builds the message from the operand types and the operator:
//
//   * `+` with a *sequence* on the left  -> "can only concatenate <L> (not \"<R>\") to <L>"
//   * `*` with a sequence and a non-index -> "can't multiply sequence by non-int of type '<X>'"
//     (X is the operand that is not an index: the right when the left is a sequence, else the left,
//     else the right when both are sequences)
//   * anything else -> the generic "unsupported operand type(s) for <op>: '<L>' and '<R>'"
//
// `binerr` calls `fail`, so each site just fills the globals and calls it (a parameter of
// `rightside` cannot be read from another proc, so the two operands travel in
// `binL`/`binLT`/`binR`/`binRT` -- the rule P127 had to adopt for its helpers).  The `*` branch
// (the one that repeats strings) gets a guard *before* it repeats anything, so the silently-wrong
// results are gone as well; that guard also covers the arithmetic branch's non-sequence cases
// (`1.5 * None`).
//
// The type *names* come from P134's `tname`, but the tags have to be the originals: P10 rewrites
// bool to number on both operands inside `rightside` (`lt2`, `evtype`), so this patch first saves
// them as `lt0`/`evt0` -- otherwise `'a' + True` would say "int" where CPython says "bool".
patch('P139 sequence ops', () => {
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable')
      ? BL()[d[1]].fields.VARIABLE[0] : null);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const VARS = ['beop', 'binL', 'binLT', 'binR', 'binRT', 'nmL', 'nmR', 'lt0', 'evt0'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P139] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);

  const seqOf = (v) => OR(OR(EQ(VAR(v), txt('S')), EQ(VAR(v), txt('L'))), EQ(VAR(v), txt('T')));
  // an int (or bool) index: type B, or type N without a '.'
  const idxOf = (t, valExpr) => OR(EQ(VAR(t), txt('B')), AND(EQ(VAR(t), txt('N')), NOT(strHas(valExpr, txt('.')))));
  const cat = (a, b) => JOIN(a, b);
  const nameOf = (tagVar, valVar, out) => [
    setV('p6v', VAR(valVar)), setV('p6t', VAR(tagVar)), callProc('tname', []), setV(out, VAR('p6msg'))
  ];
  // the globals every site fills before calling binerr
  const load = (opExpr) => [
    setV('beop', opExpr),
    setV('binL', argOf('leftval')), setV('binLT', VAR('lt0')),
    setV('binR', VAR('ev')), setV('binRT', VAR('evt0'))
  ];

  // ---------- (a) binerr: the message for beop with (binL/binLT) and (binR/binRT)
  const be = newProc('binerr', []);
  attachBody(be.defId, [
    ...nameOf('binLT', 'binL', 'nmL'),
    ...nameOf('binRT', 'binR', 'nmR'),
    // generic: unsupported operand type(s) for <op>: '<L>' and '<R>'
    setV('p6msg2', cat(cat(cat(cat(txt('unsupported operand type(s) for '), VAR('beop')), txt(": '")), VAR('nmL')), txt("' and '"))),
    setV('p6msg', cat(cat(VAR('p6msg2'), VAR('nmR')), txt("'"))),
    // `+` with a sequence on the left
    IF(EQ(VAR('beop'), txt('+')), [
      IF(seqOf('binLT'), [
        setV('p6msg2', cat(cat(cat(txt('can only concatenate '), VAR('nmL')), txt(' (not "')), VAR('nmR'))),
        setV('p6msg', cat(cat(VAR('p6msg2'), txt('") to ')), VAR('nmL')))
      ])
    ]),
    // `*` with a sequence and a non-index
    IF(EQ(VAR('beop'), txt('*')), [
      setV('p6msg2', txt('')),
      IFELSE(AND(seqOf('binLT'), NOT(idxOf('binRT', VAR('binR')))), [
        setV('p6msg2', VAR('nmR'))
      ], [
        IFELSE(AND(seqOf('binRT'), NOT(idxOf('binLT', VAR('binL')))), [
          setV('p6msg2', VAR('nmL'))
        ], [
          IF(AND(seqOf('binLT'), seqOf('binRT')), [setV('p6msg2', VAR('nmR'))])
        ])
      ]),
      IF(NOT(EQ(VAR('p6msg2'), txt(''))), [
        setV('p6msg', cat(cat(txt("can't multiply sequence by non-int of type '"), VAR('p6msg2')), txt("'")))
      ])
    ]),
    FAILB(cat(txt('TypeError: '), VAR('p6msg')))
  ]);
  console.log('[P139] binerr registered');

  // ---------- (b) rightside remembers the *original* operand types (P10 turns bool into number)
  {
    const rs = inDef('rightside %s %s %s %s %s');
    // `lt2 = lefttype` is the first of P10's two assignments (the second normalises bool to 'N')
    const repOf = (b) => (b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string') ? BL()[b.inputs.VALUE[1]] : null;
    const lt2Set = find(rs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'lt2'
      && (() => {
        const r = repOf(b);
        return !!r && r.opcode === 'argument_reporter_string_number' && r.fields.VALUE
          && r.fields.VALUE[0] === 'lefttype';
      })());
    if (lt2Set.length !== 1) throw new Error('[P139] rightside lt2 = ' + lt2Set.length);
    insertBeforeStmt(lt2Set[0], [setV('lt0', argOf('lefttype'))]);
    const evtFix = find(rs, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'evtype'
      && litOf(BL()[b.inputs.SUBSTACK[1]].inputs.VALUE) === 'N');
    if (evtFix.length !== 1) throw new Error('[P139] rightside evtype fix = ' + evtFix.length);
    insertBeforeStmt(evtFix[0], [setV('evt0', VAR('evtype'))]);
    console.log('[P139] rightside keeps the original operand types');
  }

  // ---------- (c) the three operand-type sites now go through binerr
  const litSetOf = (id) => {
    const out = new Set();
    const seen = new Set();
    const stack = [id];
    while (stack.length) {
      const x = stack.pop();
      if (!x || seen.has(x)) continue;
      seen.add(x);
      const q = BL()[x];
      if (!q) continue;
      for (const v of Object.values(q.inputs || {})) {
        const l = litOf(v);
        if (l !== null) out.add(l);
        if (typeof v[1] === 'string') stack.push(v[1]);
      }
      if (q.next) stack.push(q.next);
    }
    return out;
  };
  const isP6msg = (j) => {
    const s2 = j.inputs.STRING2;
    return Array.isArray(s2) && Array.isArray(s2[1]) && s2[1][0] === 12 && s2[1][1] === 'p6msg'
      && litOf(j.inputs.STRING1) === 'TypeError: ';
  };
  const ownerProc = (id) => {
    let cur = id;
    while (cur && BL()[cur].opcode !== 'procedures_definition') cur = BL()[cur].parent;
    if (!cur) return null;
    const proto = BL()[BL()[cur].inputs.custom_block[1]];
    return proto && proto.mutation ? proto.mutation.proccode : null;
  };
  const sites = [];
  for (const [id, b] of Object.entries(BL())) {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') continue;
    if (ownerProc(id) !== 'rightside %s %s %s %s %s') continue;   // skip binerr's own fail
    const v = Object.values(b.inputs || {})[0];
    if (!v || typeof v[1] !== 'string') continue;
    const j = BL()[v[1]];
    if (!j || j.opcode !== 'operator_join' || !isP6msg(j)) continue;
    // the third guard up tells the three sites apart
    let cur = id;
    const guards = [];
    for (let g = 0; g < 40 && cur; g++) {
      const q = BL()[cur];
      if (q && (q.opcode === 'control_if' || q.opcode === 'control_if_else')) {
        const c = q.inputs.CONDITION;
        guards.push(c && typeof c[1] === 'string' ? litSetOf(c[1]) : new Set());
      }
      cur = q ? q.parent : null;
    }
    const a3 = guards[2] || new Set();
    let op = null;
    if (a3.has('//')) op = argOf('op');                       // the shared arithmetic branch
    else if (a3.has('S') && a3.size === 1) op = txt('+');     // the `+` else
    else if (a3.has('**')) op = txt('** or pow()');           // the `**` branch
    else throw new Error('[P139] cannot classify an operand-type site: ' + [...a3].join(','));
    sites.push({ failId: id, op });
  }
  if (sites.length !== 3) throw new Error('[P139] operand-type sites = ' + sites.length);
  const prologue = (failId) => {
    // walk back over P134's message prologue (variable sets, the two tname calls, the `**` check)
    let cur = predecessorOf(failId);
    const run = [];
    for (let g = 0; g < 30 && cur; g++) {
      const q = BL()[cur];
      if (q.opcode === 'data_setvariableto' && q.fields.VARIABLE
        && ['p6v', 'p6t', 'p6msg', 'p6msg2', 'p6op'].includes(q.fields.VARIABLE[0])) {
        run.unshift(cur);
      } else if (q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'tname') {
        run.unshift(cur);
      } else if (q.opcode === 'control_if' && q.inputs.CONDITION && typeof q.inputs.CONDITION[1] === 'string'
        && litSetOf(q.inputs.CONDITION[1]).has('**')) {
        run.unshift(cur);
      } else break;
      cur = predecessorOf(cur);
    }
    return run;
  };
  for (const s of sites) {
    const run = prologue(s.failId);
    if (run.length < 8) throw new Error('[P139] prologue too short (' + run.length + ')');
    // insert in front of the old prologue and then unlink it (the orphaned blocks get pruned)
    const head = insertBeforeStmt(run[0], [...load(s.op), callProc('binerr', [])]);
    let tail = head, g = 0;
    while (tail && BL()[tail].next && BL()[tail].next !== run[0] && g++ < 20) tail = BL()[tail].next;
    if (!tail || BL()[tail].next !== run[0]) throw new Error('[P139] inserted block chain lost');
    BL()[tail].next = s.failId;
    BL()[s.failId].parent = tail;
  }
  console.log('[P139] ' + sites.length + ' operand-type sites use binerr');

  // ---------- (d) every `*` that is not "sequence repeats" or "two numbers" is an error: the old
  //              code silently produced '' / the other operand instead, and which branch would have
  //              handled it depends on the operand types, so the check runs for *all* multiplications
  //              right after P10's normalisation (that is where `lt2`/`evtype`/`ev` are all set)
  {
    const rs = inDef('rightside %s %s %s %s %s');
    const anchor = find(rs, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'evtype'
      && litOf(BL()[b.inputs.SUBSTACK[1]].inputs.VALUE) === 'N');
    if (anchor.length !== 1) throw new Error('[P139] rightside normalisation anchor = ' + anchor.length);
    const numeric = (v) => OR(EQ(VAR(v), txt('N')), EQ(VAR(v), txt('B')));
    const valid = OR(OR(AND(seqOf('lt2'), idxOf('evtype', VAR('ev'))),
      AND(idxOf('lt2', argOf('leftval')), seqOf('evtype'))), AND(numeric('lt2'), numeric('evtype')));
    spliceAfter(anchor[0], chain([
      IF(AND(EQ(argOf('op'), txt('*')), NOT(valid)), [...load(txt('*')), callProc('binerr', [])])
    ]));
    console.log('[P139] sequence multiplication is checked');
  }
  console.log('[P139] sequence operator errors ready');
});

// ---- P140: tuple methods and undefined names in `except` clauses (v4.67) ----
//
// Two small holes that both come from "the machinery only knows the list shape":
//
//   (a) `(1, 2).index(2)` / `(1, 2, 1).count(1)` -- `methodcall` rejects every receiver whose type
//       tag is not L/S/O with `AttributeError: only lists have methods`, and a tuple carries the
//       *same* encoding as a list (that is how `lcmp`/`sorted` compare them), so `index`/`count`
//       just need permission.  Anything else on a tuple has to say
//       `'tuple' object has no attribute 'append'`, like CPython.
//
//   (b) `except NoSuchError:` / `except (ValueError, NoSuchError):` -- the clause reader only ever
//       *compares* names, so an undefined one quietly behaves like "no match" (and the tuple form
//       happily caught the error).  CPython builds the exception tuple first, so an unknown name is
//       a `NameError` even when an earlier name would have matched.  `cknames` therefore validates
//       every name `clnames` produced (builtin exception name or user class) at *matching* time --
//       in trycatch's first-clause test and in the walk over the later clauses -- and parks the
//       message in `x7bad` (a *new* error cannot go through `fail %s`, which is a no-op while an
//       error is already propagating, and the walk restores `error` from `t2err` each iteration).
//       The message is moved into `error` once the frame is popped, so an outer handler catches it
//       and the try's own clauses never do.
//
// The builtin name list is P129's 13 exception names, kept in the new `ExcNames` list so the check
// is a list scan instead of a chain of comparisons.
patch('P140 tuple methods', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const VARS = ['x7tup', 'x7k', 'x7name', 'x7i', 'x7bad'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P140] variable name taken: ' + n);
  for (const v of VARS) newVar(v, v === 'x7bad' ? '' : 0);
  // the "is there a pending NameError" test is `length(x7bad) != 0` on purpose: Scratch's `=` says
  // `0 = ''` is false, so a numeric default would slip through a plain `x7bad == ''` guard.
  const noBad = () => NOT(EQ(lenOf(VAR('x7bad')), num(0)));
  B.addList(IT, 'ExcNames', ['Exception', 'ValueError', 'TypeError', 'IndexError', 'KeyError',
    'NameError', 'ZeroDivisionError', 'AttributeError', 'RuntimeError', 'AssertionError',
    'StopIteration', 'ArithmeticError', 'OverflowError']);

  // ---------- (a) tuples may use index/count; anything else is an AttributeError
  {
    const mc = inDef('methodcall %s %s');
    const guard = find(mc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && litOf(b.inputs.CONDITION[1]) === null
      && [...reach(b.inputs.CONDITION[1])].some((x) => {
        const q = BL()[x];
        return !!q && (litOf(q.inputs.OPERAND1) === 'L' || litOf(q.inputs.OPERAND2) === 'L');
      })
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && [...reach(b.inputs.SUBSTACK[1])].some((x) => {
        const q = BL()[x];
        return !!q && q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'fail %s'
          && JSON.stringify(q.inputs).includes('only lists have methods');
      }));
    if (guard.length !== 1) throw new Error('[P140] methodcall receiver guard = ' + guard.length);
    // a reporter block can only sit in one input, so build a fresh one per use
    const lmeth = () => item('Tok', ADD(argOf('lo'), num(2)));
    insertBeforeStmt(guard[0], [
      setV('x7tup', num(0)),
      IF(EQ(VAR('xb'), txt('T')), [
        IFELSE(OR(EQ(lmeth(), txt('index')), EQ(lmeth(), txt('count'))), [
          setV('xb', txt('L')), setV('x7tup', num(1))
        ], [
          FAILB(JOIN(JOIN(txt("AttributeError: 'tuple' object has no attribute '"), lmeth()), txt("'"))),
          STOPTHIS()
        ])
      ])
    ]);
    // the `list.index` message follows the *real* receiver type
    const idxFail = find(allIds(), (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'fail %s'
      && litOf(Object.values(b.inputs || {})[0]) === 'ValueError: list.index(x): x not in list');
    if (idxFail.length !== 1) throw new Error('[P140] list.index fail = ' + idxFail.length);
    const slot = Object.keys(BL()[idxFail[0]].inputs)[0];
    const oldDesc = BL()[idxFail[0]].inputs[slot];
    const tupleDesc = B.REP(txt('ValueError: tuple.index(x): x not in tuple'), [10, '']);
    BL()[idxFail[0]].inputs[slot] = [1, [10, 'ValueError: list.index(x): x not in list']];
    // keep the original descriptor as the else branch of a small IFELSE in front of the fail
    const pick = IFELSE(EQ(VAR('x7tup'), num(1)), [
      FAIL('ValueError: tuple.index(x): x not in tuple')
    ], [
      FAIL('ValueError: list.index(x): x not in list')
    ]);
    insertBeforeStmt(idxFail[0], [pick]);
    // the old fail is now unreachable -> drop it
    const pred = predecessorOf(idxFail[0]);
    if (pred) {
      BL()[pred].next = BL()[idxFail[0]].next;
      if (BL()[pred].next) BL()[BL()[pred].next].parent = pred;
      BL()[idxFail[0]].next = null;
    }
    console.log('[P140] tuples answer index/count');
  }

  // ---------- (b) unknown names in a clause are a NameError
  const isk = newProc('isknown', []);
  attachBody(isk.defId, [
    setV('ev', num(0)), setV('x7i', num(1)),
    REPEATU(OR(GT(VAR('x7i'), llen('ExcNames')), EQ(VAR('ev'), num(1))), [
      callProc('compareText %s %s', [item('ExcNames', VAR('x7i')), VAR('x7name')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('ev', num(1))]),
      chgV('x7i', num(1))
    ]),
    IF(EQ(VAR('ev'), num(0)), [
      setV('cname', VAR('x7name')), callProc('iscls', [])
    ])
  ]);
  const ck = newProc('cknames', []);
  attachBody(ck.defId, [
    setV('x7k', VAR('c3nm')),
    REPEATU(EQ(VAR('x7k'), txt('')), [
      setV('m3s', VAR('x7k')), callProc('shead', []),
      setV('x7name', VAR('m3h')),
      callProc('isknown', []),
      IF(EQ(VAR('ev'), num(0)), [
        // The message cannot go through `fail %s`: that helper only stores its text while `error`
        // is empty, and this whole check runs *because* an exception is already propagating.  It
        // also must not be written into `error` right here -- the clause walk below saves and
        // restores `error` around each candidate (`t2err`), so the text is parked in `x7bad`
        // until the frame is popped.
        setV('x7bad', JOIN(JOIN(txt("NameError: name '"), VAR('x7name')), txt("' is not defined"))),
        // the frame is popped anyway; clearing the text ends the scan on the first bad name
        setV('x7k', txt(''))
      ]),
      setV('m3s', VAR('x7k')), callProc('stail', []), setV('x7k', VAR('m3r'))
    ])
  ]);
  console.log('[P140] cknames registered');
  {
    // the names are *read* up front (P51's try branch needs them), but CPython only evaluates the
    // clause expression when it actually matches, so the check belongs to the matching paths:
    // the walk over the later clauses (right after its clnames) and trycatch's first-clause test.
    const ownerProc = (id) => {
      let cur = id;
      while (cur && BL()[cur].opcode !== 'procedures_definition') cur = BL()[cur].parent;
      if (!cur) return null;
      const proto = BL()[BL()[cur].inputs.custom_block[1]];
      return proto && proto.mutation ? proto.mutation.proccode : null;
    };
    const setters = find(allIds(), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'c3line');
    if (setters.length !== 2) throw new Error('[P140] c3line setters = ' + setters.length);
    let hooked = 0;
    for (const s of setters) {
      // the walk's own clnames call: the names are read per candidate clause
      let cur = s, n = 0, found = null;
      while (cur && n++ < 10) {
        const q = BL()[cur];
        if (q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'clnames') { found = cur; break; }
        cur = q.next;
      }
      if (found && ownerProc(s) === 'trycatch') {
        spliceAfter(found, chain([callProc('cknames', [])]));
        hooked++;
      }
    }
    // trycatch's first-clause test.  The names are read from `tnm` (this frame's own clause text,
    // set by `tnm = last(TryName)`), *not* from `c3nm`: that scratch global is shared with every
    // `clnames` call, and a nested `try/finally` leaves the keyword `finally` in it, which would
    // make the check blame a name that no clause ever mentioned.
    //
    // The check runs *before* `if (tcl == 1)`: CPython builds the clause expression while matching,
    // so a bad name wins even when an earlier name in the tuple would have matched.  `tcl` is forced
    // back to 0 so that this clause cannot swallow the NameError.
    const tc = inDef('trycatch');
    const tnmSet = find(tc, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'tnm' && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
      && BL()[b.inputs.VALUE[1]].opcode === 'data_itemoflist'
      && BL()[b.inputs.VALUE[1]].fields.LIST && BL()[b.inputs.VALUE[1]].fields.LIST[0] === 'TryName');
    if (tnmSet.length !== 1) throw new Error('[P140] trycatch tnm = ' + tnmSet.length);
    // seed c3nm from the frame right away, so nothing else in this loop can read the stale value
    spliceAfter(tnmSet[0], chain([setV('c3nm', VAR('tnm'))]));
    // `V(x) == <literal>` comes straight from project.json as a *variable reference* input
    // (`[3, [12, name, id], [10, '']]`), not as a reporter block, so compare the array form.
    const isVarCmp = (b, name, value) => b.opcode === 'operator_equals'
      && b.inputs.OPERAND1 && Array.isArray(b.inputs.OPERAND1[1])
      && b.inputs.OPERAND1[1][0] === 12 && b.inputs.OPERAND1[1][1] === name
      && b.inputs.OPERAND2 && b.inputs.OPERAND2[1] && b.inputs.OPERAND2[1][1] === value;
    const hitIf = find(tc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && isVarCmp(BL()[b.inputs.CONDITION[1]], 'tcl', '1'));
    if (hitIf.length !== 1) throw new Error('[P140] trycatch tcl test = ' + hitIf.length);
    insertBeforeStmt(hitIf[0], [
      callProc('cknames', []),
      IF(noBad(), [
        setV('error', VAR('x7bad')), setV('tcl', num(0)), setV('x7bad', txt(''))
      ])
    ]);

    // ---- the walk over the later clauses (P132) needs three touch-ups
    // (a) already done above: `cknames` right after its `clnames`.
    // (the walk's test is an if/else -- `if (V(t2hit)=="1") ... else: t2x = Elses[t2x]`)
    const wHitIf = find(tc, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else')
      && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((i) => isVarCmp(BL()[i], 't2hit', '1')));
    if (wHitIf.length !== 1) throw new Error('[P140] walk t2hit test = ' + wHitIf.length);
    insertBeforeStmt(wHitIf[0], [
      // a bad name means this candidate is never entered -- and there is nothing left to walk to
      IF(noBad(), [setV('t2hit', num(0)), setV('t2x', num(0))])
    ]);
    // (c) the walk restores the saved error at the end of every iteration (`error = t2err`), which
    // would throw the NameError away, so re-apply it once the frame is about to be popped.
    const popDel = find(tc, (b) => b.opcode === 'data_deleteoflist' && b.fields.LIST
      && b.fields.LIST[0] === 'TryHand'
      && JSON.stringify(b.inputs.INDEX || []).includes('last'));
    if (popDel.length !== 1) throw new Error('[P140] trycatch pop = ' + popDel.length);
    insertBeforeStmt(popDel[0], [
      IF(noBad(), [
        setV('error', VAR('x7bad')), setV('x7bad', txt(''))
      ])
    ]);
    if (hooked !== 1) throw new Error('[P140] walk clnames hook = ' + hooked);
    console.log('[P140] clause names are checked when a clause is tested');
  }
  console.log('[P140] tuple methods + clause NameError ready');
});

// ---- P141: calling (or reaching into) a value that cannot take it (v4.68) ----
//
// Two things that CPython only decides *at run time* were parse errors in MiniPy, plus a
// long-standing receiver bug inside methods:
//
//   * `1()`, `'a'()`, `[1]()`, `x()` (x not callable) -> `SyntaxError: missing expression`
//     or `SyntaxError: expression`; CPython says `TypeError: '<type>' object is not callable`.
//   * `(1).foo`, `'a'.foo`, `[].foo`, `None.foo` -> `SyntaxError: attribute access`; CPython says
//     `AttributeError: '<type>' object has no attribute 'foo'`.  The same shape for a *class*
//     (`A.zz`) and for an *instance* (`A().foo`) printed only the bare attribute name.
//   * inside a method, `z.upper()` / `'q'.upper()` / `[1].append(2)` died with
//     `AttributeError: only lists have methods`: `methodcall` keeps its "the receiver is the
//     result of the previous part" state in the global `mcpre`, and the chained call for
//     `A().hi()` leaves it at 1 while the method body runs, so the body's own method call took
//     the chain branch and used the *outer* receiver.  The flag is now consumed on entry
//     (`mcpv = mcpre; mcpre = 0`) and the receiver fallback no longer clobbers `xa`/`xb`.
//
// Type names come from P134's `tname` (value in `p6v`/`p6t`, name in `p6msg`).
patch('P141 not callable / attribute errors', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const J = (a, b) => JOIN(a, b);
  const tokAt = (i) => item('Tok', i);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const condEq = (b, name, value) => b.opcode === 'operator_equals'
    && b.inputs.OPERAND1 && Array.isArray(b.inputs.OPERAND1[1])
    && b.inputs.OPERAND1[1][0] === 12 && b.inputs.OPERAND1[1][1] === name
    && b.inputs.OPERAND2 && b.inputs.OPERAND2[1] && b.inputs.OPERAND2[1][1] === value;
  const failSites = (set) => [...set].filter((i) => {
    const q = BL()[i];
    return q && q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'fail %s';
  });
  // the message of a `fail %s` is built from literals, variables and `item ... of Tok`; flatten it
  const textOf = (id) => {
    const out = [];
    const seen = new Set();
    const walkInputs = (obj) => { for (const v of Object.values(obj || {})) walk(v); };
    const walk = (x) => {
      if (!x) return;
      if (!Array.isArray(x)) { walkInputs(x); return; }
      const t = x[0], v = x[1];
      if (typeof v === 'string') {
        if (t === 10 || t === 4) { out.push(v); return; }
        const b = BL()[v];
        if (!b || seen.has(v)) return;
        seen.add(v);
        if (b.opcode === 'data_variable') { out.push('[' + b.fields.VARIABLE[0] + ']'); return; }
        if (b.opcode === 'data_itemoflist') { out.push('[' + b.fields.LIST[0] + ']'); return; }
        walkInputs(b.inputs);
        return;
      }
      if (Array.isArray(v)) {
        if (v[0] === 12) { out.push('[' + v[1] + ']'); return; }
        if (v.length === 2 && typeof v[1] === 'string') { out.push(v[1]); return; }
        walk(v);
      }
    };
    walkInputs(BL()[id].inputs);
    return out.join('');
  };
  const exact = (set, text) => failSites(set).filter((i) => textOf(i).includes(text));
  // statement order inside eval: several sites are only distinguishable by where they sit
  const order = new Map();
  const fillOrder = () => {
    let n = 0;
    const walkStmts = (id) => {
      let cur = id, g = 0;
      while (cur && g++ < 20000) {
        if (!order.has(cur)) order.set(cur, n++);
        const b = BL()[cur];
        for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
          const v = b.inputs && b.inputs[slot];
          if (v && typeof v[1] === 'string') walkStmts(v[1]);
        }
        cur = b.next;
      }
    };
    walkStmts(BL()[defIdOf('eval %s %s')].next);
  };
  fillOrder();
  // `replaceStmt` sets `new.next = old.next`, which silently truncates a multi-statement chain
  // (the rest of it becomes unreachable and is pruned).  Splice the tail instead.
  const replaceChain = (oldId, list) => {
    const head = chain(list);
    const pred = predecessorOf(oldId);
    const nx = BL()[oldId].next;
    if (pred) { BL()[pred].next = head; BL()[head].parent = pred; }
    else {
      const ref = refOf(oldId);
      if (!ref) throw new Error('[P141] cannot locate ' + oldId);
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], head, ref.v[2]] : [ref.v[0], head];
      BL()[head].parent = ref.pid;
    }
    let tail = head, g = 0;
    while (BL()[tail].next && g++ < 100) tail = BL()[tail].next;
    BL()[tail].next = nx;
    if (nx) BL()[nx].parent = tail;
    BL()[oldId].next = null;
    return head;
  };

  for (const n of ['mcpv', 'x8i', 'x8d', 'x8e', 'x8nc']) {
    if (new Set(Object.values(T(IT).variables).map((x) => x[0])).has(n)) throw new Error('[P141] variable name taken: ' + n);
    newVar(n, 0);
  }
  // value in ev/evtype -> type name in p6msg.  NB: `FAIL()` wraps a plain string in a text
  // literal, so an *expression* message has to go through `fail %s` directly.
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const tnameOf = () => [setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', [])];
  const notCallable = () => [...tnameOf(),
    failMsg(J(J(txt("TypeError: '"), VAR('p6msg')), txt("' object is not callable")))];
  // `<recvExpr>`/`<typeVar>` already evaluated -> the AttributeError CPython prints
  const noAttr = (recvVal, recvType, nameExpr) => [
    setV('p6v', recvVal), setV('p6t', recvType), callProc('tname', []),
    failMsg(J(J(J(J(txt("AttributeError: '"), VAR('p6msg')), txt("' object has no attribute '")), nameExpr), txt("'")))
  ];

  // ---------- (0) methodcall: the chain flag is per call, and the fallback must not clobber xa/xb
  {
    const mc = 'methodcall %s %s';
    const mcd = defIdOf(mc);
    const head = BL()[mcd].next;   // cselfr = Tok[lo]
    if (!head) throw new Error('[P141] methodcall has no body');
    spliceAfter(head, chain([setV('mcpv', VAR('mcpre')), setV('mcpre', num(0))]));
    const recvIf = find(reach(mcd), (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && condEq(BL()[b.inputs.CONDITION[1]], 'mcpre', '1'));
    if (recvIf.length !== 1) throw new Error('[P141] methodcall receiver branch = ' + recvIf.length);
    replaceExpr(BL()[recvIf[0]].inputs.CONDITION[1], () => EQ(VAR('mcpv'), num(1)));
    // `xa = ev` / `xb = evtype` were unconditional; in the chain case they must keep mcval/mctype
    const setEv = find(reach(mcd), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'xa'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][0] === 12 && b.inputs.VALUE[1][1] === 'ev');
    if (setEv.length !== 1) throw new Error('[P141] methodcall xa = ev = ' + setEv.length);
    const x1 = setEv[0];
    const x2 = BL()[x1].next;
    if (!x2 || BL()[x2].opcode !== 'data_setvariableto' || BL()[x2].fields.VARIABLE[0] !== 'xb') {
      throw new Error('[P141] methodcall xb = evtype not found');
    }
    const pred = predecessorOf(x1);
    if (!pred) throw new Error('[P141] methodcall xa predecessor');
    const after = BL()[x2].next;
    BL()[pred].next = null;
    BL()[x1].parent = null;
    const g = IF(EQ(VAR('mcpv'), num(0)), [x1]);
    BL()[g].parent = pred; BL()[pred].next = g;
    BL()[g].next = after; if (after) BL()[after].parent = g;
    console.log('[P141] methodcall receiver state is per call');
  }

  // ---------- (1) the super() hook must only take `super().m(args)`, not a longer chain
  {
    const ev = inDef('eval %s %s');
    // the hook is the `if Tok[lo] == 'super' and ...` guard at eval's head
    const hook = find(ev, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && JSON.stringify([...reach(b.inputs.CONDITION[1])].map((i) => BL()[i].inputs)).includes('"super"'));
    if (hook.length !== 1) throw new Error('[P141] super hook = ' + hook.length);
    const oldHead = BL()[hook[0]].inputs.SUBSTACK[1];
    // scan from the '(' after the method name for its matching ')'
    const scan = [
      setV('x8i', ADD(argOf('lo'), num(5))), setV('x8d', num(0)), setV('x8e', num(0)),
      REPEATU(OR(GT(VAR('x8i'), argOf('hi')), GT(VAR('x8e'), num(0))), [
        IF(OR(EQ(tokAt(VAR('x8i')), txt('(')), OR(EQ(tokAt(VAR('x8i')), txt('[')), EQ(tokAt(VAR('x8i')), txt('{')))), [chgV('x8d', num(1))]),
        IF(OR(EQ(tokAt(VAR('x8i')), txt(')')), OR(EQ(tokAt(VAR('x8i')), txt(']')), EQ(tokAt(VAR('x8i')), txt('}')))), [
          chgV('x8d', num(-1)),
          IF(EQ(VAR('x8d'), num(0)), [setV('x8e', VAR('x8i'))])
        ]),
        chgV('x8i', num(1))
      ])
    ];
    setStack(hook[0], 'SUBSTACK', [...scan, IFELSE(EQ(VAR('x8e'), argOf('hi')), [oldHead], [])]);
    console.log('[P141] super() only claims a self-contained call');
  }

  // ---------- (2) `X(...)` where X is not callable
  const ev = inDef('eval %s %s');
  {
    // `a.b().c()` must split at the *last* depth-0 dot: eval then evaluates `a.b()` (which may
    // itself be `super().hi()`) as the receiver.  With the first dot, `super().hi().upper()`
    // evaluated the bare `super()` and died with `NameError: name 'super' is not defined`.
    const mdotIf = find(ev, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && condEq(BL()[b.inputs.CONDITION[1]], 'mdot', '0')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'mdot');
    if (mdotIf.length !== 1) throw new Error('[P141] mdot first-wins guard = ' + mdotIf.length);
    const assign = BL()[mdotIf[0]].inputs.SUBSTACK[1];
    if (BL()[assign].next) throw new Error('[P141] mdot assignment shape');
    replaceStmt(mdotIf[0], assign);

    // `narg` counts *commas*, so `narg == 0` is a one-argument call: the builtin dispatcher
    // `callfn` is reached for every name it knows, so "not callable" cannot be `callable == 0`
    // (builtins are not in FnName).  Decide once, right after `callable` is computed:
    // a *literal* callee, or a known variable that does not hold a function, is not callable.
    const cset = find(ev, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'callable'
      && b.inputs.VALUE && b.inputs.VALUE[1] && b.inputs.VALUE[1][1] === '1');
    if (cset.length !== 3) throw new Error('[P141] callable = 1 sites = ' + cset.length);
    const calleeKind = () => item('Kind', argOf('lo'));
    // the last one is the `Types[found] == "F"` test, i.e. the end of the callable computation
    const afterCallable = cset.slice().sort((a, b) => (order.get(a) || 0) - (order.get(b) || 0)).pop();
    // ... and it sits inside its own `if`, so the new statements go after that `if`
    const callableIf = find(ev, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string' && b.inputs.SUBSTACK[1] === afterCallable);
    if (callableIf.length !== 1) throw new Error('[P141] callable guard if = ' + callableIf.length);
    spliceAfter(callableIf[0], chain([
      setV('x8nc', num(0)),
      IF(OR(EQ(calleeKind(), txt('N')), EQ(calleeKind(), txt('S'))), [setV('x8nc', num(1))]),
      // the three constants are keywords, not literals, but they are values all the same
      IF(OR(EQ(tokAt(argOf('lo')), txt('True')), OR(EQ(tokAt(argOf('lo')), txt('False')), EQ(tokAt(argOf('lo')), txt('None')))),
        [setV('x8nc', num(1))]),
      IF(AND(NOT(EQ(VAR('found'), num(0))), NOT(EQ(item('Types', VAR('found')), txt('F')))), [setV('x8nc', num(1))])
    ]));

    const nargIf = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && condEq(BL()[b.inputs.CONDITION[1]], 'narg', '0'));
    if (nargIf.length !== 1) throw new Error('[P141] narg == 0 branch = ' + nargIf.length);
    const oldCall = BL()[nargIf[0]].inputs.SUBSTACK[1];
    if (!oldCall || BL()[oldCall].next) throw new Error('[P141] narg == 0 body shape');
    setStack(nargIf[0], 'SUBSTACK', [
      IFELSE(EQ(VAR('x8nc'), num(1)), [
        // evaluating the callee either yields a value (-> not callable) or reports the usual
        // NameError for an unknown name
        callProc('eval %s %s', [argOf('lo'), argOf('lo')]),
        IF(EQ(VAR('error'), txt('')), notCallable()),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ], [oldCall])
    ]);
    // the last resort of the multi-argument dispatch (callable == 0 with commas)
    const lastResort = exact(ev, 'is not defined');
    if (lastResort.length !== 1) throw new Error('[P141] call NameError sites = ' + lastResort.length);
    replaceChain(lastResort[0], [
      IFELSE(EQ(VAR('x8nc'), num(1)), [
        callProc('eval %s %s', [argOf('lo'), argOf('lo')]),
        IF(EQ(VAR('error'), txt('')), notCallable())
      ], [
        failMsg(J(J(txt("NameError: name '"), tokAt(argOf('lo'))), txt("' is not defined")))
      ])
    ]);
    // `(expr)(args)` (P85's shape) said just "object is not callable"
    const p85 = exact(ev, 'TypeError: object is not callable');
    if (p85.length !== 1) throw new Error('[P141] object-is-not-callable sites = ' + p85.length);
    replaceChain(p85[0], notCallable());
    // `[1]()` / `{'a': 1}()` end in the generic parse error
    const generic = exact(ev, 'SyntaxError: expression');
    if (generic.length !== 1) throw new Error('[P141] SyntaxError expression sites = ' + generic.length);
    insertBeforeStmt(generic[0], [
      setV('x8i', argOf('lo')), setV('x8d', num(0)), setV('x8e', num(0)),
      REPEATU(OR(GT(VAR('x8i'), argOf('hi')), GT(VAR('x8e'), num(0))), [
        IF(OR(EQ(tokAt(VAR('x8i')), txt('[')), EQ(tokAt(VAR('x8i')), txt('{'))), [chgV('x8d', num(1))]),
        IF(OR(EQ(tokAt(VAR('x8i')), txt(']')), EQ(tokAt(VAR('x8i')), txt('}'))), [
          chgV('x8d', num(-1)),
          IF(EQ(VAR('x8d'), num(0)), [setV('x8e', VAR('x8i'))])
        ]),
        chgV('x8i', num(1))
      ]),
      IF(AND(GT(VAR('x8e'), num(0)), AND(LT(ADD(VAR('x8e'), num(1)), argOf('hi')),
        AND(EQ(tokAt(ADD(VAR('x8e'), num(1))), txt('(')), EQ(tokAt(argOf('hi')), txt(')'))))), [
        callProc('eval %s %s', [argOf('lo'), VAR('x8e')]),
        IF(EQ(VAR('error'), txt('')), notCallable()),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ]);
    console.log('[P141] non-callable values say TypeError');
  }

  // ---------- (3) attribute access on something that has none
  {
    // map every statement to the control block whose substack holds it
    const containerOf = new Map();
    for (const pid of allIds()) {
      const p = BL()[pid];
      for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
        const v = p.inputs && p.inputs[slot];
        if (v && typeof v[1] === 'string') {
          let cur = v[1], g = 0;
          while (cur && g++ < 8000) { if (!containerOf.has(cur)) containerOf.set(cur, pid); cur = BL()[cur].next; }
        }
      }
    }
    const enclosing = (id) => {
      const out = [];
      let cur = containerOf.get(id), g = 0;
      while (cur && g++ < 40) { out.push(cur); cur = containerOf.get(cur); }
      return out;
    };
    const subtreeHas = (id, pred) => [...reach(id)].some(pred);
    const attrErr = exact(ev, 'SyntaxError: attribute access');
    if (attrErr.length !== 2) throw new Error('[P141] attribute-access sites = ' + attrErr.length);
    const allAttr = exact(ev, 'AttributeError: ');
    const atnmSite = allAttr.filter((i) => textOf(i).includes('[atnm]'));
    if (atnmSite.length !== 1) throw new Error('[P141] atnm attribute site = ' + atnmSite.length);
    const tokSite = allAttr.filter((i) => textOf(i).includes('[Tok]') && !textOf(i).includes('super'));
    if (tokSite.length !== 2) throw new Error('[P141] Tok[lo+2] attribute sites = ' + tokSite.length);
    const tokName = () => tokAt(ADD(argOf('lo'), num(2)));
    for (const id of attrErr) {
      // the trailing-dot path shares its `if/else` with the `atnm` lookup; the 3-token path does not
      const near = enclosing(id).some((c) => subtreeHas(c, (x) => x === atnmSite[0]));
      replaceChain(id, noAttr(VAR('ev'), VAR('evtype'), near ? VAR('atnm') : tokName()));
    }
    // instance case of the trailing-dot path: `'A' object has no attribute 'foo'`
    replaceChain(atnmSite[0], noAttr(VAR('atid'), txt('O'), VAR('atnm')));
    // the two `X.name` sites: the class read (inside `if cfnd == 1`) sits earlier in eval's chain
    // than the instance read, and `find` returns them in block-id order
    const tokSorted = tokSite.slice().sort((a, b) => (order.get(a) || 0) - (order.get(b) || 0));
    for (let i = 0; i < tokSorted.length; i++) {
      const id = tokSorted[i];
      if (i === 0) {
        replaceChain(id, [
          failMsg(J(J(J(J(txt("AttributeError: type object '"), VAR('iid')), txt("' has no attribute '")), tokName()), txt("'")))
        ]);
      } else {
        replaceChain(id, noAttr(VAR('iid'), txt('O'), tokName()));
      }
    }
    console.log('[P141] attribute errors carry the type name');
  }
  console.log('[P141] not-callable / attribute errors ready');
});

// ---- P142: zero-argument calls (v4.69) ----
//
// `list()`, `str()`, `int()`, `float()`, `bool()`, `tuple()`, `dict()`, `nosuch()` -- every call
// with an *empty* argument list died with `SyntaxError: missing expression`, because the argument
// span is `lo+2 .. hi-1` and both dispatchers evaluated that empty span anyway:
//
//   * `eval`'s `name(...)` branch runs its own special handling first (`zip`, `sorted`, `math.*`,
//     `set`, `divmod`, `max/min/pow/round/int`, ...) and each of those reads the arguments;
//   * `callfn` does `eval(lo, hi)` unconditionally right after its class-construction branch.
//
// So a new `zeroarg` proc decides what "no arguments" means, and both places ask it first:
//
//   * values (`list()` -> [], `str()` -> '', `int()` -> 0, `float()` -> 0.0, `bool()` -> False,
//     `tuple()` -> (), `dict()` -> {}, `zip()` -> [] -- MiniPy materializes it anyway);
//   * CPython's `TypeError` for the one-argument builtins (`len()`, `abs()`, `sorted()`, `max()`,
//     `sum()`, `type()`, ...);
//   * anything else (`set()`, `input()`, a user function/class, a variable holding a function)
//     is left alone: `x9known` marks the builtins handled further down, and a name that is none
//     of those (no variable, not in `FnName`/`ClsName`) gets the `NameError` right here, because
//     the empty span would otherwise blow up before `callfn` can report it.
//
// The callee name travels through the global `x9fn` (see P127: block arguments are not reliable on
// a repeated call); `x9go` = 1 means "handled, stop".
patch('P142 zero-argument calls', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (i) => item('Tok', i);
  const J = (a, b) => JOIN(a, b);
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const listHas = (list, v) => I('data_listcontainsitem', { fields: B.LISTF(list), inputs: { ITEM: B.REP(v, [10, '']) } });
  for (const n of ['x9go', 'x9fn', 'x9known', 'x9user']) {
    if (new Set(Object.values(T(IT).variables).map((x) => x[0])).has(n)) throw new Error('[P142] variable name taken: ' + n);
    newVar(n, 0);
  }
  // nothing to compute: the empty value is the answer
  const VALUE = [
    ['list', '', 'L'], ['str', '', 'S'], ['int', '0', 'N'], ['float', '0.0', 'N'],
    ['bool', 0, 'B'], ['tuple', '', 'T'], ['dict', '', 'D'], ['zip', '', 'L']
  ];
  // CPython's wording for the builtins that need an argument
  const ERROR = [
    ['len', 'TypeError: len() takes exactly one argument (0 given)'],
    ['abs', 'TypeError: abs() takes exactly one argument (0 given)'],
    ['ord', 'TypeError: ord() takes exactly one argument (0 given)'],
    ['chr', 'TypeError: chr() takes exactly one argument (0 given)'],
    ['repr', 'TypeError: repr() takes exactly one argument (0 given)'],
    ['any', 'TypeError: any() takes exactly one argument (0 given)'],
    ['all', 'TypeError: all() takes exactly one argument (0 given)'],
    ['type', 'TypeError: type() takes 1 or 3 arguments'],
    ['sorted', 'TypeError: sorted expected 1 argument, got 0'],
    ['sum', 'TypeError: sum() takes at least 1 positional argument (0 given)'],
    ['max', 'TypeError: max expected at least 1 argument, got 0'],
    ['min', 'TypeError: min expected at least 1 argument, got 0'],
    ['enumerate', "TypeError: enumerate() missing required argument 'iterable' (pos 1)"],
    ['round', "TypeError: round() missing required argument 'number' (pos 1)"],
    ['pow', "TypeError: pow() missing required argument 'exp' (pos 2)"],
    ['divmod', 'TypeError: divmod expected 2 arguments, got 0'],
    ['issubclass', 'TypeError: issubclass() takes exactly 2 arguments (0 given)'],
    ['isinstance', 'TypeError: isinstance() takes exactly 2 arguments (0 given)'],
    ['range', 'TypeError: range expected at least 1 argument, got 0']
  ];
  // builtins with a legitimately empty form that somebody further down implements
  const KNOWN = ['set', 'input'];
  const za = newProc('zeroarg', []);
  attachBody(za.defId, [
    setV('x9go', num(0)), setV('x9known', num(0)),
    ...VALUE.map(([name, val, tag]) => IF(EQ(VAR('x9fn'), txt(name)), [
      setV('ev', typeof val === 'number' ? num(val) : txt(val)), setV('evtype', txt(tag)), setV('x9go', num(1))
    ])),
    ...ERROR.map(([name, msg]) => IF(EQ(VAR('x9fn'), txt(name)), [setV('x9go', num(1)), FAIL(msg)])),
    ...KNOWN.map((name) => IF(EQ(VAR('x9fn'), txt(name)), [setV('x9known', num(1))])),
    // an unknown name has to fail *here*: the empty span cannot be handed to callfn
    IF(AND(EQ(VAR('x9go'), num(0)), EQ(VAR('x9known'), num(0))), [
      callProc('lookup %s', [VAR('x9fn')]),
      setV('x9user', num(0)),
      IF(NOT(EQ(VAR('found'), num(0))), [setV('x9user', num(1))]),
      IF(listHas('FnName', VAR('x9fn')), [setV('x9user', num(1))]),
      IF(listHas('ClsName', VAR('x9fn')), [setV('x9user', num(1))]),
      IF(EQ(VAR('x9user'), num(0)), [
        setV('x9go', num(1)),
        failMsg(J(J(txt("NameError: name '"), VAR('x9fn')), txt("' is not defined")))
      ])
    ])
  ]);
  console.log('[P142] zeroarg knows ' + VALUE.length + ' value / ' + ERROR.length + ' error names');

  // ---------- (a) eval: the `name(...)` branch asks first, before its own special branches
  const ev = inDef('eval %s %s');
  const callableIfs = find(ev, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'data_setvariableto'
      && BL()[x].fields.VARIABLE[0] === 'callable'));
  if (callableIfs.length < 1) throw new Error('[P142] eval call branch = ' + callableIfs.length);
  // the outermost candidate is `if Tok[lo+1] == "(" and Tok[hi] == ")"`: the inner ones are the
  // three `callable = 1` guards nested inside it
  const outer = callableIfs.filter((id) => !callableIfs.some((other) => other !== id
    && typeof BL()[other].inputs.SUBSTACK[1] === 'string'
    && reach(BL()[other].inputs.SUBSTACK[1]).has(id)));
  if (outer.length !== 1) throw new Error('[P142] eval call branch (outer) = ' + outer.length);
  const branchHead = BL()[outer[0]].inputs.SUBSTACK[1];
  insertBeforeStmt(branchHead, [
    // `name ( )` exactly: three tokens, empty argument list.  The span test alone is not enough
    // (`self.n = 5` is also three tokens), so the call shape is checked here as well -- and a
    // *literal* callee (`1()`, `'a'()`, `True()`) is left to P141, which reports the TypeError.
    IF(AND(AND(EQ(tokAt(ADD(argOf('lo'), num(1))), txt('(')), EQ(tokAt(argOf('hi')), txt(')'))),
      AND(GT(ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))), NOT(OR(EQ(item('Kind', argOf('lo')), txt('N')),
        OR(EQ(item('Kind', argOf('lo')), txt('S')), OR(EQ(tokAt(argOf('lo')), txt('True')),
          OR(EQ(tokAt(argOf('lo')), txt('False')), EQ(tokAt(argOf('lo')), txt('None'))))))))), [
      setV('x9fn', tokAt(argOf('lo'))),
      callProc('zeroarg', []),
      IF(EQ(VAR('x9go'), num(1)), [
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ])
  ]);
  console.log('[P142] eval asks before zip/sorted/set/math');

  // ---------- (b) callfn: an empty argument span is "no arguments", not "missing expression"
  const cf = inDef('callfn %s %s %s');
  const argEval = find(cf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s'
    && b.next && BL()[b.next].opcode === 'control_if' && BL()[b.next].inputs.CONDITION
    && typeof BL()[b.next].inputs.CONDITION[1] === 'string'
    && JSON.stringify(BL()[BL()[b.next].inputs.CONDITION[1]].inputs).includes('error'));
  // two candidates: the class-construction branch has its own `if not(lo > hi): eval(lo, hi)`,
  // while the general one is the *first* statement of the `else` of the `mode == 0` test
  const mainEval = argEval.filter((id) => !predecessorOf(id));
  if (mainEval.length !== 1) throw new Error('[P142] callfn argument eval = ' + mainEval.length + ' of ' + argEval.length);
  {
    const old = mainEval[0];
    const pred = predecessorOf(old);
    const nx = BL()[old].next;
    const ref = pred ? null : refOf(old);
    const node = IFELSE(GT(argOf('lo'), argOf('hi')), [
      // an inert value: no branch matches, so an unknown name reaches the NameError fallback
      setV('ev', txt('')), setV('evtype', txt('X'))
    ], [old]);
    BL()[old].next = null;
    if (pred) { BL()[pred].next = node; BL()[node].parent = pred; }
    else {
      if (!ref) throw new Error('[P142] cannot locate callfn argument eval');
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], node, ref.v[2]] : [ref.v[0], node];
      BL()[node].parent = ref.pid;
    }
    BL()[node].next = nx;
    if (nx) BL()[nx].parent = node;
  }
  console.log('[P142] callfn tolerates an empty argument span');
  console.log('[P142] zero-argument calls ready');
});

// ---- P143: the type constructors as expressions: tuple(x) and range(...) (v4.70) ----
//
// `tuple([1, 2])`, `tuple('ab')`, `range(3)` outside a `for` -- and therefore `list(range(3))`,
// `sum(range(4))` -- all died with `NameError: name 'tuple'/'range' is not defined`: `callfn` has no
// branch for them (`list`/`set`/`str`/`int`/`float`/`bool` do), and `range` only ever worked as the
// direct source of a `for` (or of a comprehension, through `crng`).
//
//   * `tuple(x)`: tuples and lists share one encoding (P140), so this is the `list` branch with a
//     different tag; a string is split into characters first, exactly like `list('ab')` does (that
//     part is factored into `charsplit`).
//   * `range(...)`: `crng` (P125's comprehension helper) evaluates the 1/2/3 arguments into
//     `cv`/`cstop`/`cstep`, then the list is materialized here.  CPython prints `range(0, 3)`;
//     MiniPy keeps its "evaluate immediately" convention (same as `zip()`/`enumerate()`), so a bare
//     `range(3)` prints `[0, 1, 2]`.
patch('P143 tuple and range as expressions', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const tokAt = (i) => item('Tok', i);
  const J = (a, b) => JOIN(a, b);
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const lit = (() => {
    // `lsep` lives on the Stage (P1's `slash` does too)
    for (const t of [T(IT), T('Stage')]) {
      for (const v of Object.values(t.variables || {})) if (v[0] === 'lsep') return String(v[1]);
    }
    throw new Error('[P143] lsep variable not found');
  })();
  for (const n of ['xArng', 'xAcur']) {
    if (new Set(Object.values(T(IT).variables).map((x) => x[0])).has(n)) throw new Error('[P143] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- (a) `tuple(x)`: the `list` branch with another tag
  const cs = newProc('charsplit', []);   // "ab" -> the list encoding of ["a", "b"] in ev/evtype
  attachBody(cs.defId, [
    setV('gan', VAR('ev')),
    clearL('LConv'),
    setV('gci', num(1)),
    REPEATU(GT(VAR('gci'), lenOf(VAR('gan'))), [
      callProc('lesc %s', [letterOf(VAR('gci'), VAR('gan'))]),
      addTo('LConv', J(J(txt(lit), txt('S')), VAR('ev'))),
      chgV('gci', num(1))
    ]),
    setV('gat', txt('')),
    setV('gci', num(1)),
    REPEATU(GT(VAR('gci'), llen('LConv')), [
      setV('gat', J(VAR('gat'), item('LConv', VAR('gci')))),
      chgV('gci', num(1))
    ]),
    setV('ev', VAR('gat')), setV('evtype', txt('L'))
  ]);
  const cf = inDef('callfn %s %s %s');
  const listBranch = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && JSON.stringify(BL()[x].inputs.OPERAND2 || {}).includes('"list"')));
  if (listBranch.length !== 1) throw new Error('[P143] callfn list branch = ' + listBranch.length);
  spliceAfter(listBranch[0], chain([
    IF(EQ(argOf('fn'), txt('tuple')), [
      // NB: `IF(cond, then)` is two-argument -- an else branch has to go through `IFELSE`
      IFELSE(OR(EQ(VAR('evtype'), txt('L')), OR(EQ(VAR('evtype'), txt('T')), OR(EQ(VAR('evtype'), txt('G')), EQ(VAR('evtype'), txt('E'))))), [
        setV('evtype', txt('T'))
      ], [
        IFELSE(EQ(VAR('evtype'), txt('S')), [
          callProc('charsplit', []), setV('evtype', txt('T'))
        ], [
          // CPython: "'int' object is not iterable"
          setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
          failMsg(J(J(txt("TypeError: '"), VAR('p6msg')), txt("' object is not iterable")))
        ])
      ]),
      setV('pending', num(1))
    ])
  ]));
  console.log('[P143] tuple(x) reuses the list encoding with tag T');

  // ---------- (a2) message alignment: "X() requires an iterable" -> "'<type>' object is not iterable"
  {
    const set = inDef('callfn %s %s %s');
    const hits = [...set].filter((i) => {
      const b = BL()[i];
      return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
        && (JSON.stringify(b.inputs).includes('list() requires an iterable') || JSON.stringify(b.inputs).includes('set() requires an iterable'));
    });
    if (hits.length !== 2) throw new Error('[P143] iterable message sites = ' + hits.length);
    for (const id of hits) {
      insertBeforeStmt(id, [setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', [])]);
      const slot = Object.keys(BL()[id].inputs)[0];
      BL()[id].inputs[slot] = [3, J(J(txt("TypeError: '"), VAR('p6msg')), txt("' object is not iterable")), [10, '']];
    }
    console.log('[P143] list()/set() iterable wording aligned');
  }

  // ---------- (b) `range(...)` as an expression
  const ev = inDef('eval %s %s');
  const callableIfs = find(ev, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'data_setvariableto'
      && BL()[x].fields.VARIABLE[0] === 'callable'));
  const outer = callableIfs.filter((id) => !callableIfs.some((other) => other !== id
    && typeof BL()[other].inputs.SUBSTACK[1] === 'string'
    && reach(BL()[other].inputs.SUBSTACK[1]).has(id)));
  if (outer.length !== 1) throw new Error('[P143] eval call branch = ' + outer.length);
  const branchHead = BL()[outer[0]].inputs.SUBSTACK[1];
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  // range arguments must be plain integers (no '.', and a valid number at all)
  const intArg = (v) => [
    callProc('numbercheck %s', [v]),
    IFELSE(EQ(VAR('en'), num(1)), [
      IF(strHas(v, txt('.')), [FAIL(txt("TypeError: 'float' object cannot be interpreted as an integer"))])
    ], [
      FAIL(txt("TypeError: 'str' object cannot be interpreted as an integer"))
    ])
  ];
  insertBeforeStmt(branchHead, [
    IF(EQ(tokAt(argOf('lo')), txt('range')), [
      callProc('crng %s %s', [ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      ...intArg(VAR('cv')), ...intArg(VAR('cstop')), ...intArg(VAR('cstep')),
      IF(EQ(VAR('cstep'), num(0)), [FAIL(txt('ValueError: range() arg 3 must not be zero'))]),
      setV('xArng', txt('')), setV('xAcur', VAR('cv')),
      REPEATU(OR(AND(GT(VAR('cstep'), num(0)), NOT(LT(VAR('xAcur'), VAR('cstop')))),
        AND(NOT(GT(VAR('cstep'), num(0))), NOT(GT(VAR('xAcur'), VAR('cstop'))))), [
        callProc('lesc %s', [VAR('xAcur')]),
        setV('xArng', J(VAR('xArng'), J(J(txt(lit), txt('N')), VAR('ev')))),
        chgV('xAcur', VAR('cstep'))
      ]),
      setV('ev', VAR('xArng')), setV('evtype', txt('L')),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ])
  ]);
  console.log('[P143] range(...) materializes a list');
  // CPython's wording for a zero step, in both the `for` path and `crng`
  {
    let fixed = 0;
    for (const id of allIds()) {
      const b = BL()[id];
      if (b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
        && JSON.stringify(b.inputs).includes('range step is zero')) {
        const slot = Object.keys(b.inputs)[0];
        b.inputs[slot] = [1, [10, 'ValueError: range() arg 3 must not be zero']];
        fixed++;
      }
    }
    if (fixed < 2) throw new Error('[P143] range step message sites = ' + fixed);
    console.log('[P143] range step wording aligned (' + fixed + ' sites)');
  }
  console.log('[P143] tuple/range ready');
});

// ---- P144: `dict(x)` -- build a dictionary from a sequence of pairs (v4.71) ----
//
// `dict([(1, 2)])`, `dict([[1, 2]])`, `dict(existing)` all died with
// `NameError: name 'dict' is not defined`: `callfn` has branches for `list`/`set`/`str`/`int`/
// `float`/`bool`/`tuple` but none for `dict`, and the *zero-argument* form only worked because
// P142's `zeroarg` answers that one itself.
//
// The record encoding is the one the dict code already uses (see `indexset`'s `D` branch and
// `dictpair`): every entry is `lsep + <key type> + <escaped key> + lsep + <value type> + <escaped value>`.
// Writing it straight out would keep *both* records of a repeated key, so the pairs are first
// collected into four parallel lists and folded there: a repeated key keeps its **first position**
// and its **last value** (exactly what `{1: 2, 3: 4, 1: 5}` prints as `{1: 5, 3: 4}`).
//
// Messages follow CPython: a non-iterable source says `'<type>' object is not iterable`, a source
// element that is not a sequence says `object is not iterable` (bare), and one with the wrong
// length says `dictionary update sequence element #<i> has length <n>; 2 is required`.
patch('P144 dict(x)', () => {
  const J = (a, b) => JOIN(a, b);
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const replaceItem = (list, idx, v) => I('data_replaceitemoflist', {
    fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(v, [10, '']) }
  });
  const lit = (() => {
    for (const t of [T(IT), T('Stage')]) {
      for (const v of Object.values(t.variables || {})) if (v[0] === 'lsep') return String(v[1]);
    }
    throw new Error('[P144] lsep variable not found');
  })();
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['d14s', 'd14n', 'd14n2', 'd14i', 'd14p', 'd14pt', 'd14kt', 'd14ke', 'd14vt', 'd14ve', 'd14f', 'd14j', 'd14acc']) {
    if (taken.has(n)) throw new Error('[P144] variable name taken: ' + n);
    newVar(n, 0);
  }
  for (const l of ['DgK', 'DgE', 'DgV', 'DgW']) B.addList(IT, l, []);
  const seq = (v) => OR(EQ(VAR(v), txt('L')), EQ(VAR(v), txt('T')));
  const iterable = (v) => OR(seq(v), OR(EQ(VAR(v), txt('G')), EQ(VAR(v), txt('E'))));

  const body = [
    // a dict argument is a copy; a string is iterated as characters (`dict('ab')` is a ValueError
    // about element length in CPython, which falls out of the same code path)
    IF(EQ(VAR('evtype'), txt('S')), [callProc('charsplit', [])]),
    IFELSE(iterable('evtype'), [
      clearL('DgK'), clearL('DgE'), clearL('DgV'), clearL('DgW'),
      setV('d14s', VAR('ev')),
      callProc('listlen %s', [VAR('d14s')]), setV('d14n', VAR('ev')),
      setV('d14i', num(1)),
      REPEATU(GT(VAR('d14i'), VAR('d14n')), [
        callProc('listitem %s %s', [VAR('d14s'), VAR('d14i')]),
        setV('d14p', VAR('ev')), setV('d14pt', VAR('evtype')),
        IFELSE(seq('d14pt'), [
          callProc('listlen %s', [VAR('d14p')]), setV('d14n2', VAR('ev'))
        ], [
          IFELSE(EQ(VAR('d14pt'), txt('S')), [
            setV('d14n2', lenOf(VAR('d14p')))
          ], [
            FAIL(txt('TypeError: object is not iterable'))
          ])
        ]),
        IF(NOT(EQ(VAR('d14n2'), num(2))), [
          failMsg(J(J(J(J(txt('ValueError: dictionary update sequence element #'), SUB(VAR('d14i'), num(1))),
            txt(' has length ')), VAR('d14n2')), txt('; 2 is required')))
        ]),
        // key and value (a 2-character string yields its two characters)
        IFELSE(seq('d14pt'), [
          callProc('listitem %s %s', [VAR('d14p'), num(1)])
        ], [
          setV('ev', letterOf(num(1), VAR('d14p'))), setV('evtype', txt('S'))
        ]),
        setV('d14kt', VAR('evtype')), callProc('lesc %s', [VAR('ev')]), setV('d14ke', VAR('ev')),
        IFELSE(seq('d14pt'), [
          callProc('listitem %s %s', [VAR('d14p'), num(2)])
        ], [
          setV('ev', letterOf(num(2), VAR('d14p'))), setV('evtype', txt('S'))
        ]),
        setV('d14vt', VAR('evtype')), callProc('lesc %s', [VAR('ev')]), setV('d14ve', VAR('ev')),
        // an equal key keeps its position and takes the new value
        setV('d14f', num(0)), setV('d14j', num(1)),
        REPEATU(OR(GT(VAR('d14j'), llen('DgK')), GT(VAR('d14f'), num(0))), [
          IF(AND(EQ(item('DgK', VAR('d14j')), VAR('d14kt')), EQ(item('DgE', VAR('d14j')), VAR('d14ke'))), [
            setV('d14f', VAR('d14j'))
          ]),
          chgV('d14j', num(1))
        ]),
        IFELSE(GT(VAR('d14f'), num(0)), [
          replaceItem('DgV', VAR('d14f'), VAR('d14vt')), replaceItem('DgW', VAR('d14f'), VAR('d14ve'))
        ], [
          addTo('DgK', VAR('d14kt')), addTo('DgE', VAR('d14ke')), addTo('DgV', VAR('d14vt')), addTo('DgW', VAR('d14ve'))
        ]),
        chgV('d14i', num(1))
      ]),
      // emit the records in insertion order
      setV('d14acc', txt('')), setV('d14j', num(1)),
      REPEATU(GT(VAR('d14j'), llen('DgK')), [
        setV('d14acc', J(VAR('d14acc'), J(J(txt(lit), item('DgK', VAR('d14j'))), item('DgE', VAR('d14j'))))),
        setV('d14acc', J(VAR('d14acc'), J(J(txt(lit), item('DgV', VAR('d14j'))), item('DgW', VAR('d14j'))))),
        chgV('d14j', num(1))
      ]),
      setV('ev', VAR('d14acc')), setV('evtype', txt('D')), setV('pending', num(1))
    ], [
      IFELSE(EQ(VAR('evtype'), txt('D')), [
        setV('pending', num(1))   // `dict(d)` copies
      ], [
        setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
        failMsg(J(J(txt("TypeError: '"), VAR('p6msg')), txt("' object is not iterable")))
      ])
    ])
  ];

  const cf = inDef('callfn %s %s %s');
  const tupleBranch = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && JSON.stringify(BL()[x].inputs.OPERAND2 || {}).includes('"tuple"')));
  if (tupleBranch.length !== 1) throw new Error('[P144] callfn tuple branch = ' + tupleBranch.length);
  spliceAfter(tupleBranch[0], chain([IF(EQ(argOf('fn'), txt('dict')), body)]));
  console.log('[P144] dict(x) builds from pairs (last value wins, first position kept)');
  console.log('[P144] dict ready');
});

// ---- P145: `%` formatting -- flags, hex/octal, %r, %c and the error cases (v4.72) ----
//
// P77's `pctfmt`/`pctitem` handled `%d`, `%f`, `%s` with a `-`, a width and a `.`precision, and
// silently ignored everything else:
//
//   * `'%05d' % 42` -> `[   42]` (no zero padding), `'%+d' % 5` -> `5` (no sign flag);
//   * `'%x' % 255` -> `255`, `'%o' % 8` -> `8` (no hex/octal), `'%r' % 'a'` -> `a` (no repr),
//     `'%c' % 65` -> `65` (no character);
//   * `'%q' % 1` printed `1` instead of raising, and `'%d' % (1, 2)` / `'a' % 1` silently dropped
//     the extra argument instead of CPython's
//     `TypeError: not all arguments converted during string formatting`.
//
// `pctitem` is rewritten with a real flag parser (`-`, `0`, `+`, ` `) and the extra conversions;
// `pctfmt` gets the two checks it never had (unknown conversion character -> `ValueError` with the
// code in hex and the index; left-over arguments -> `TypeError`).
//
// Still missing (documented): `%e`/`%E`, the `%(name)s` mapping form and `*` width/precision.
patch('P145 percent formatting flags', () => {
  const J = (a, b) => JOIN(a, b);
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const alnum = '0123456789abcdef';
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p15z', 'p15s', 'p15pl', 'p15b', 'p15v', 'p15d', 'p15t', 'p15x', 'p15h', 'p15i']) {
    if (taken.has(n)) throw new Error('[P145] variable name taken: ' + n);
    newVar(n, 0);
  }
  const digit = (v) => strHas(txt('0123456789'), v);

  // ---------- (a) pctitem: flags + the extra conversions
  const pi = defIdOf('pctitem %s %s %s %s');
  const body = chain([
    setV('pwi', num(1)), setV('pwid', num(0)), setV('ppr', num(0)), setV('phas', num(0)),
    setV('pleft', num(0)), setV('pok', num(0)),
    setV('p15z', num(0)), setV('p15s', num(0)), setV('p15pl', num(0)),
    // flags, in any order: `-`, `0`, `+`, ` `
    REPEATU(OR(GT(VAR('pwi'), lenOf(argOf('spec'))), NOT(strHas(txt('-0+ '), letterOf(VAR('pwi'), argOf('spec'))))), [
      IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('-')), [setV('pleft', num(1))]),
      IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('0')), [setV('p15z', num(1))]),
      IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('+')), [setV('p15pl', num(1))]),
      IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt(' ')), [setV('p15s', num(1))]),
      chgV('pwi', num(1))
    ]),
    // width
    REPEATU(OR(GT(VAR('pwi'), lenOf(argOf('spec'))), EQ(letterOf(VAR('pwi'), argOf('spec')), txt('.'))), [
      IF(digit(letterOf(VAR('pwi'), argOf('spec'))), [
        setV('pwid', ADD(MUL(VAR('pwid'), num(10)), letterOf(VAR('pwi'), argOf('spec'))))
      ]),
      chgV('pwi', num(1))
    ]),
    // precision
    IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('.')), [
      chgV('pwi', num(1)), setV('phas', num(1)),
      REPEATU(GT(VAR('pwi'), lenOf(argOf('spec'))), [
        IF(digit(letterOf(VAR('pwi'), argOf('spec'))), [
          setV('ppr', ADD(MUL(VAR('ppr'), num(10)), letterOf(VAR('pwi'), argOf('spec'))))
        ]),
        chgV('pwi', num(1))
      ])
    ]),
    setV('ptx', txt('')),
    // ---- integers: d / i
    IF(OR(EQ(argOf('conv'), txt('d')), EQ(argOf('conv'), txt('i'))), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: %d format: a number is required'))]),
      setV('pnn', FLOOR(argOf('vv'))),
      IF(LT(argOf('vv'), num(0)), [setV('pnn', I('operator_mathop', { fields: { OPERATOR: ['ceiling', null] }, inputs: { NUM: B.REP(argOf('vv'), [4, '0']) } }))]),
      setV('ptx', VAR('pnn')), setV('pok', num(1))
    ]),
    // ---- floats: f / F
    IF(OR(EQ(argOf('conv'), txt('f')), EQ(argOf('conv'), txt('F'))), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: must be real number, not str'))]),
      IF(EQ(VAR('phas'), num(0)), [setV('ppr', num(6))]),
      setV('pqq', num(1)),
      REPEAT(VAR('ppr'), [setV('pqq', MUL(VAR('pqq'), num(10)))]),
      setV('psg', txt('')),
      setV('pab', argOf('vv')),
      IF(LT(VAR('pab'), num(0)), [setV('psg', txt('-')), setV('pab', SUB(num(0), VAR('pab')))]),
      setV('pmu', MUL(VAR('pab'), VAR('pqq'))),
      setV('pn2', FLOOR(ADD(VAR('pmu'), num('0.5')))),
      setV('pin', FLOOR(DIV(VAR('pn2'), VAR('pqq')))),
      setV('pfr', SUB(VAR('pn2'), MUL(VAR('pin'), VAR('pqq')))),
      IFELSE(EQ(VAR('ppr'), num(0)), [
        setV('ptx', J(VAR('psg'), VAR('pin')))
      ], [
        setV('pfs', VAR('pfr')),
        REPEATU(NOT(LT(lenOf(VAR('pfs')), VAR('ppr'))), [setV('pfs', J(txt('0'), VAR('pfs')))]),
        setV('ptx', J(J(J(VAR('psg'), VAR('pin')), txt('.')), VAR('pfs')))
      ]),
      setV('pok', num(1))
    ]),
    // ---- hex / octal: x / X / o
    IF(OR(EQ(argOf('conv'), txt('x')), OR(EQ(argOf('conv'), txt('X')), EQ(argOf('conv'), txt('o')))), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: %x format: an integer is required'))]),
      setV('p15b', num(16)),
      IF(EQ(argOf('conv'), txt('o')), [setV('p15b', num(8))]),
      // NB: `EQ` is Scratch's `=`, which compares strings case-insensitively -- `conv == "X"` would
      // also be true for "x".  Case matters here, so use MiniPy's own `compareText` (what `==` uses).
      setV('p15t', txt(alnum)),
      callProc('compareText %s %s', [argOf('conv'), txt('X')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('p15t', txt('0123456789ABCDEF'))]),
      setV('p15v', FLOOR(argOf('vv'))),
      setV('p15x', txt('')),
      IF(LT(argOf('vv'), num(0)), [setV('p15x', txt('-')), setV('p15v', SUB(num(0), VAR('p15v')))]),
      setV('ptx', txt('')),
      REPEATU(NOT(GT(VAR('p15v'), num(0))), [
        setV('p15d', MOD(VAR('p15v'), VAR('p15b'))),
        // most significant digit first: prepend, do not append
        setV('ptx', J(letterOf(ADD(VAR('p15d'), num(1)), VAR('p15t')), VAR('ptx'))),
        setV('p15v', FLOOR(DIV(VAR('p15v'), VAR('p15b'))))
      ]),
      IF(EQ(VAR('ptx'), txt('')), [setV('ptx', txt('0'))]),
      setV('ptx', J(VAR('p15x'), VAR('ptx'))),
      setV('pok', num(1))
    ]),
    // ---- character: c
    IF(EQ(argOf('conv'), txt('c')), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: %c requires int or char'))]),
      IF(OR(LT(argOf('vv'), num(32)), GT(argOf('vv'), num(126))), [FAIL(txt('ValueError: %c arg not in range(32, 127)'))]),
      setV('ptx', letterOf(SUB(argOf('vv'), num(31)), VAR('cs'))), setV('pok', num(1))
    ]),
    // ---- strings: s / r
    IF(EQ(argOf('conv'), txt('s')), [callProc('strval %s %s', [argOf('vv'), argOf('vt')]), setV('ptx', VAR('ev')), setV('pok', num(1))]),
    IF(EQ(argOf('conv'), txt('r')), [callProc('reprval %s %s', [argOf('vv'), argOf('vt')]), setV('ptx', VAR('ev')), setV('pok', num(1))]),
    IF(EQ(VAR('pok'), num(0)), [callProc('strval %s %s', [argOf('vv'), argOf('vt')]), setV('ptx', VAR('ev'))]),
    // ---- the `+` / ` ` flags prefix a sign when the text has none
    IF(AND(OR(EQ(VAR('p15pl'), num(1)), EQ(VAR('p15s'), num(1))), NOT(EQ(letterOf(num(1), VAR('ptx')), txt('-')))), [
      IFELSE(EQ(VAR('p15pl'), num(1)), [setV('ptx', J(txt('+'), VAR('ptx')))], [setV('ptx', J(txt(' '), VAR('ptx')))])
    ]),
    // ---- padding: spaces, or zeros kept behind the sign
    IF(LT(lenOf(VAR('ptx')), VAR('pwid')), [
      setV('ppad', txt('')),
      IFELSE(AND(EQ(VAR('p15z'), num(1)), EQ(VAR('pleft'), num(0))), [setV('p15t', txt('0'))], [setV('p15t', txt(' '))]),
      REPEAT(SUB(VAR('pwid'), lenOf(VAR('ptx'))), [setV('ppad', J(VAR('ppad'), VAR('p15t')))]),
      IFELSE(EQ(VAR('pleft'), num(1)), [
        setV('ptx', J(VAR('ptx'), VAR('ppad')))
      ], [
        IFELSE(AND(EQ(VAR('p15z'), num(1)), OR(EQ(letterOf(num(1), VAR('ptx')), txt('-')), EQ(letterOf(num(1), VAR('ptx')), txt('+')))), [
          callProc('substr %s %s %s', [VAR('ptx'), num(2), lenOf(VAR('ptx'))]),
          setV('ptx', J(letterOf(num(1), VAR('ptx')), J(VAR('ppad'), VAR('ev'))))
        ], [
          setV('ptx', J(VAR('ppad'), VAR('ptx')))
        ])
      ])
    ]),
    setV('ev', VAR('ptx')), setV('evtype', txt('S'))
  ]);
  BL()[pi].next = body;
  BL()[body].parent = pi;
  console.log('[P145] pctitem rewritten with flags + x/o/r/c');

  // ---------- (b) pctfmt: unknown conversion + left-over arguments
  const pf = inDef('pctfmt %s %s %s');
  const itemCall = find(pf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'pctitem %s %s %s %s');
  if (itemCall.length !== 1) throw new Error('[P145] pctitem call sites = ' + itemCall.length);
  insertBeforeStmt(itemCall[0], [
    IF(NOT(strHas(txt('diouxXeEfFgGrcs'), VAR('pvc'))), [
      // ord(pvc) out of the alphabet, then hex, then CPython's wording
      setV('p15x', num(0)), setV('p15i', num(1)),
      REPEATU(OR(GT(VAR('p15i'), lenOf(VAR('cs'))), GT(VAR('p15x'), num(0))), [
        callProc('compareText %s %s', [letterOf(VAR('p15i'), VAR('cs')), VAR('pvc')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('p15x', ADD(VAR('p15i'), num(31)))]),
        chgV('p15i', num(1))
      ]),
      setV('p15h', txt('')), setV('p15b', VAR('p15x')),
      REPEATU(NOT(GT(VAR('p15b'), num(0))), [
        setV('p15d', MOD(VAR('p15b'), num(16))),
        setV('p15h', J(letterOf(ADD(VAR('p15d'), num(1)), txt(alnum)), VAR('p15h'))),
        setV('p15b', FLOOR(DIV(VAR('p15b'), num(16))))
      ]),
      IF(EQ(VAR('p15h'), txt('')), [setV('p15h', txt('0'))]),
      failMsg([txt("ValueError: unsupported format character '"), VAR('pvc'), txt("' (0x"), VAR('p15h'),
        txt(') at index '), SUB(VAR('pvi'), num(1))].reduce((a, b) => J(a, b)))
    ])
  ]);
  const outSet = find(pf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ev'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][0] === 12 && b.inputs.VALUE[1][1] === 'pvout');
  if (outSet.length !== 1) throw new Error('[P145] pctfmt out site = ' + outSet.length);
  insertBeforeStmt(outSet[0], [
    IF(LT(SUB(VAR('pvk'), num(1)), llen('PVal')), [
      FAIL(txt('TypeError: not all arguments converted during string formatting'))
    ])
  ]);
  console.log('[P145] pctfmt validates the conversion and the argument count');
  console.log('[P145] percent formatting ready');
});

// ---- P146: `%e` formatting, `*` width, and the indentation message (v4.73) ----
//
// Three loose ends from the last rounds:
//
//   * `'%e' % 1234.5` printed `1234.5` (the conversion fell through to `%s`); now it prints
//     `1.234500e+03`.  The value is normalized into [1, 10) to get the exponent, the mantissa is
//     rounded with the same arithmetic the `%f` branch uses, and the exponent gets a sign and at
//     least two digits (`e+03`, `e-05`).  `%E` only differs in the letter's case.
//   * `'%*d' % (5, 3)` used to hit "unsupported format character '*'": `*` is now accepted by the
//     spec scan and replaced by the next argument before `pctitem` runs (the width comes first,
//     like CPython).
//   * `try:` / `finally:` with no indented block said only `IndentationError: expected block`;
//     CPython names the header and the line -- `expected an indented block after 'finally' statement
//     on line 3`, with `after function definition` / `after class definition` for `def` / `class`.
//
// `EQ` is Scratch's case-insensitive `=`, so telling `%e` from `%E` needs MiniPy's `compareText`.
patch('P146 percent e and star plus indent message', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p16c', 'p16e', 'p16s', 'p16m', 'p16i', 'p16v', 'p16w', 'p16l', 'p16r']) {
    if (taken.has(n)) throw new Error('[P146] variable name taken: ' + n);
    newVar(n, 0);
  }
  // innermost enclosing control block of a statement (parents are not reliable during patching)
  const containerOf = (procSet, id) => {
    let best = null, bestSize = Infinity;
    for (const pid of procSet) {
      const p = BL()[pid];
      for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
        const v = p.inputs && p.inputs[slot];
        if (v && typeof v[1] === 'string' && reach(v[1]).has(id)) {
          const size = reach(v[1]).size;
          if (size < bestSize) { bestSize = size; best = pid; }
        }
      }
    }
    return best;
  };

  // ---------- (a) `%e` / `%E` in pctitem
  const pi = inDef('pctitem %s %s %s %s');
  const hexFail = [...pi].filter((i) => {
    const b = BL()[i];
    return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
      && JSON.stringify(b.inputs).includes('%x format');
  });
  if (hexFail.length !== 1) throw new Error('[P146] pctitem %x fail = ' + hexFail.length);
  // the fail sits in its own `if (vt != 'N')`, so the hex *branch* is one level further out
  const innerIf = containerOf(pi, hexFail[0]);
  const hexIf = innerIf ? containerOf(pi, innerIf) : null;
  if (!hexIf) throw new Error('[P146] pctitem hex branch not found');
  insertBeforeStmt(hexIf, [
    IF(OR(EQ(argOf('conv'), txt('e')), EQ(argOf('conv'), txt('E'))), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: must be real number, not str'))]),
      IF(EQ(VAR('phas'), num(0)), [setV('ppr', num(6))]),
      setV('psg', txt('')),
      setV('p16m', argOf('vv')),
      IF(LT(VAR('p16m'), num(0)), [setV('psg', txt('-')), setV('p16m', SUB(num(0), VAR('p16m')))]),
      setV('p16e', num(0)),
      // 0 stays 0.000000e+00; anything else is normalized into [1, 10)
      IF(GT(VAR('p16m'), num(0)), [
        REPEATU(NOT(GT(VAR('p16m'), num('9.9999999999'))), [
          setV('p16m', DIV(VAR('p16m'), num(10))), chgV('p16e', num(1))
        ]),
        REPEATU(NOT(LT(VAR('p16m'), num(1))), [
          setV('p16m', MUL(VAR('p16m'), num(10))), chgV('p16e', num(-1))
        ])
      ]),
      // mantissa with `ppr` decimals (same arithmetic as the %f branch)
      setV('pqq', num(1)),
      REPEAT(VAR('ppr'), [setV('pqq', MUL(VAR('pqq'), num(10)))]),
      setV('pmu', MUL(VAR('p16m'), VAR('pqq'))),
      setV('pn2', FLOOR(ADD(VAR('pmu'), num('0.5')))),
      setV('pin', FLOOR(DIV(VAR('pn2'), VAR('pqq')))),
      setV('pfr', SUB(VAR('pn2'), MUL(VAR('pin'), VAR('pqq')))),
      // rounding up to 10.000 rolls the exponent over
      IF(NOT(LT(VAR('pin'), num(10))), [setV('pin', num(1)), chgV('p16e', num(1)), setV('pfr', num(0))]),
      IFELSE(EQ(VAR('ppr'), num(0)), [
        setV('ptx', J(VAR('psg'), VAR('pin')))
      ], [
        setV('pfs', VAR('pfr')),
        REPEATU(NOT(LT(lenOf(VAR('pfs')), VAR('ppr'))), [setV('pfs', J(txt('0'), VAR('pfs')))]),
        setV('ptx', J(J(J(VAR('psg'), VAR('pin')), txt('.')), VAR('pfs')))
      ]),
      // the exponent: `e`/`E`, a sign, then at least two digits
      callProc('compareText %s %s', [argOf('conv'), txt('E')]),
      IFELSE(EQ(VAR('cmp'), num(0)), [setV('p16c', txt('E'))], [setV('p16c', txt('e'))]),
      IFELSE(LT(VAR('p16e'), num(0)), [
        setV('p16s', J(VAR('p16c'), txt('-'))), setV('p16e', SUB(num(0), VAR('p16e')))
      ], [
        setV('p16s', J(VAR('p16c'), txt('+')))
      ]),
      IFELSE(LT(VAR('p16e'), num(10)), [setV('p16m', J(txt('0'), VAR('p16e')))], [setV('p16m', VAR('p16e'))]),
      setV('ptx', J(VAR('ptx'), J(VAR('p16s'), VAR('p16m')))),
      setV('pok', num(1))
    ])
  ]);
  console.log('[P146] %e/%E implemented');

  // ---------- (b) `*` width / precision in pctfmt
  const pf = inDef('pctfmt %s %s %s');
  {
    // Scratch's `contains` puts the haystack in STRING1
    const scanCmp = find(pf, (b) => b.opcode === 'operator_contains' && b.inputs.STRING1
      && Array.isArray(b.inputs.STRING1[1]) && typeof b.inputs.STRING1[1][1] === 'string'
      && b.inputs.STRING1[1][1] === '-+ 0123456789.');
    if (scanCmp.length !== 1) throw new Error('[P146] pctfmt spec scan = ' + scanCmp.length);
    BL()[scanCmp[0]].inputs.STRING1 = [1, [10, '-+ 0123456789.*']];
  }
  const itemCall = find(pf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'pctitem %s %s %s %s');
  if (itemCall.length !== 1) throw new Error('[P146] pctitem call sites = ' + itemCall.length);
  // the value argument is read *before* the call, so the `*` substitution has to happen before
  // that read -- otherwise the width eats the value and pctitem formats the width instead
  const argRead = find(pf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'pvv'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && BL()[b.inputs.VALUE[1]].opcode === 'data_itemoflist'
    && BL()[b.inputs.VALUE[1]].fields.LIST && BL()[b.inputs.VALUE[1]].fields.LIST[0] === 'PVal');
  if (argRead.length !== 1) throw new Error('[P146] pctfmt argument read = ' + argRead.length);
  insertBeforeStmt(argRead[0], [
    // each `*` takes the next argument (the width is read before the value, like CPython)
    REPEATU(NOT(strHas(VAR('pvspec'), txt('*'))), [
      IF(GT(VAR('pvk'), llen('PVal')), [FAIL(txt('TypeError: not enough arguments for format string'))]),
      IF(NOT(EQ(item('PTyp', VAR('pvk')), txt('N'))), [FAIL(txt('TypeError: * wants int'))]),
      callProc('strval %s %s', [item('PVal', VAR('pvk')), txt('N')]),
      setV('p16w', VAR('ev')),
      chgV('pvk', num(1)),
      callProc('sfind %s %s', [VAR('pvspec'), txt('*')]),
      setV('p16i', VAR('ev')),
      setV('p16l', txt('')), setV('p16r', txt('')),
      IF(GT(VAR('p16i'), num(0)), [
        callProc('substr %s %s %s', [VAR('pvspec'), num(1), VAR('p16i')]), setV('p16l', VAR('ev'))
      ]),
      IF(NOT(GT(ADD(VAR('p16i'), num(2)), lenOf(VAR('pvspec')))), [
        callProc('substr %s %s %s', [VAR('pvspec'), ADD(VAR('p16i'), num(2)), lenOf(VAR('pvspec'))]), setV('p16r', VAR('ev'))
      ]),
      setV('pvspec', J(VAR('p16l'), J(VAR('p16w'), VAR('p16r'))))
    ])
  ]);
  console.log('[P146] * width/precision substituted from the arguments');

  // ---------- (c) the missing-block message
  {
    const ex = inDef('prepare');
    const sites = [...ex].filter((i) => {
      const b = BL()[i];
      return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
        && JSON.stringify(b.inputs).includes('IndentationError: expected block');
    });
    if (sites.length !== 2) throw new Error('[P146] expected-block sites = ' + sites.length);
    for (const id of sites) {
      insertBeforeStmt(id, [
        setV('p16m', joinAll([txt("'"), VAR('prevhead'), txt("' statement")])),
        IF(EQ(VAR('prevhead'), txt('def')), [setV('p16m', txt('function definition'))]),
        IF(EQ(VAR('prevhead'), txt('class')), [setV('p16m', txt('class definition'))])
      ]);
      const slot = Object.keys(BL()[id].inputs)[0];
      BL()[id].inputs[slot] = [3, joinAll([
        txt('IndentationError: expected an indented block after '), VAR('p16m'),
        // `backline` already carries the 1-based line number the console prints
        txt(' on line '), VAR('backline')
      ]), [10, '']];
    }
    console.log('[P146] indentation message names the header and line');
  }
  console.log('[P146] percent e / star / indent ready');
});

// ---- P147: `'%(name)s' % mapping` -- the key form of `%` formatting (v4.74) ----
//
// `'%(a)s=%(b)d' % {'a': 'x', 'b': 3}` printed
// `ValueError: unsupported format character '(' (0x28) at index 1`: P77's `pctfmt` never learned the
// mapping form, so `(` was treated as the conversion character.  (`dict(a=1)` keyword construction
// is still missing -- that is a different mechanism, the builtin call's keyword arguments.)
//
// The key is read in `pctfmt`'s spec scan (between `(` and `)`), and the value comes from the
// *single* dict argument instead of the next positional one, via a new `dget` proc that walks the
// record list (`listitem` already unescapes keys).  A missing key raises CPython's `KeyError: 'a'`.
//
// The positional path is untouched: the check + the three reads are wrapped in the `else` of a new
// `if (no key)` so that the mapping lookup replaces them instead of running before them.
patch('P147 percent mapping form', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const tokFmt = (i) => letterOf(i, argOf('fmt'));
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['pvkey', 'pvd', 'p17f', 'p17i', 'p17n']) {
    if (taken.has(n)) throw new Error('[P147] variable name taken: ' + n);
    newVar(n, 0);
  }
  const pf = inDef('pctfmt %s %s %s');
  // innermost enclosing control block (parents are unreliable while patching)
  const containerOf = (id) => {
    let best = null, bestSize = Infinity;
    for (const pid of pf) {
      const p = BL()[pid];
      for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
        const v = p.inputs && p.inputs[slot];
        if (v && typeof v[1] === 'string' && reach(v[1]).has(id)) {
          const size = reach(v[1]).size;
          if (size < bestSize) { bestSize = size; best = pid; }
        }
      }
    }
    return best;
  };

  // ---------- (a) the spec scan learns `(name)`
  const specInit = find(pf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'pvspec'
    && b.inputs.VALUE && b.inputs.VALUE[1] && b.inputs.VALUE[1][1] === '');
  if (specInit.length !== 1) throw new Error('[P147] pvspec init = ' + specInit.length);
  spliceAfter(specInit[0], chain([
    setV('pvkey', txt('')),
    IF(EQ(tokFmt(VAR('pvi')), txt('(')), [
      chgV('pvi', num(1)),
      REPEATU(OR(GT(VAR('pvi'), lenOf(argOf('fmt'))), EQ(tokFmt(VAR('pvi')), txt(')'))), [
        setV('pvkey', J(VAR('pvkey'), tokFmt(VAR('pvi')))),
        chgV('pvi', num(1))
      ]),
      chgV('pvi', num(1))
    ])
  ]));
  console.log('[P147] %(name) is read in the spec scan');

  // ---------- (b) dget: look the key up in the mapping
  const dg = newProc('dget', []);
  attachBody(dg.defId, [
    setV('p17f', num(0)), setV('p17i', num(1)),
    callProc('listlen %s', [VAR('pvd')]), setV('p17n', VAR('ev')),
    REPEATU(OR(GT(VAR('p17i'), VAR('p17n')), EQ(VAR('p17f'), num(1))), [
      callProc('listitem %s %s', [VAR('pvd'), VAR('p17i')]),
      IF(EQ(VAR('ev'), VAR('pvkey')), [
        setV('p17f', num(1)),
        callProc('listitem %s %s', [VAR('pvd'), ADD(VAR('p17i'), num(1))]),
        setV('pvv', VAR('ev')), setV('pvt', VAR('evtype'))
      ]),
      chgV('p17i', num(2))
    ]),
    IF(EQ(VAR('p17f'), num(0)), [
      // CPython: KeyError: 'a'  (the mapping form only ever uses string keys)
      failMsg(joinAll([txt('KeyError: '), J(J(txt("'"), VAR('pvkey')), txt("'"))]))
    ])
  ]);
  console.log('[P147] dget looks a mapping key up');

  // ---------- (c) route the value through the mapping when a key was given
  // two sites carry that message: P146's `*` substitution and the original positional check.
  // The original one comes first in program order -- build a statement order map to pick it.
  const order = new Map();
  {
    let n = 0;
    const walk = (id) => {
      let cur = id, g = 0;
      while (cur && g++ < 20000) {
        if (!order.has(cur)) order.set(cur, n++);
        const b = BL()[cur];
        for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
          const v = b.inputs && b.inputs[slot];
          if (v && typeof v[1] === 'string') walk(v[1]);
        }
        cur = b.next;
      }
    };
    walk(BL()[defIdOf('pctfmt %s %s %s')].next);
  }
  const notEnough = [...pf].filter((i) => {
    const b = BL()[i];
    return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
      && JSON.stringify(b.inputs).includes('not enough arguments');
  });
  if (notEnough.length !== 2) throw new Error('[P147] not-enough-arguments sites = ' + notEnough.length);
  const checkIf = notEnough.map((id) => containerOf(id)).filter(Boolean)
    .sort((a, b) => (order.get(a) || 0) - (order.get(b) || 0))[0];
  // the four statements that produce pvv/pvt: check, read value, read type, advance
  const seg = [checkIf];
  for (let i = 0; i < 3; i++) {
    const nx = BL()[seg[seg.length - 1]].next;
    if (!nx) throw new Error('[P147] argument read chain is short (' + seg.length + ')');
    seg.push(nx);
  }
  const after = BL()[seg[3]].next;
  const pred = predecessorOf(checkIf);
  const ref = pred ? null : refOf(checkIf);
  // detach the segment
  if (pred) { BL()[pred].next = null; BL()[checkIf].parent = null; }
  BL()[seg[3]].next = null;
  const node = IFELSE(NOT(EQ(VAR('pvkey'), txt(''))), [
    IF(NOT(EQ(item('PTyp', num(1)), txt('D'))), [FAIL(txt('TypeError: format requires a mapping'))]),
    setV('pvd', item('PVal', num(1))),
    callProc('dget', []),
    // the mapping counts as consumed for the "not all arguments converted" check
    setV('pvk', ADD(llen('PVal'), num(1)))
  ], [checkIf]);
  if (pred) { BL()[pred].next = node; BL()[node].parent = pred; }
  else {
    if (!ref) throw new Error('[P147] cannot place the mapping branch');
    BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], node, ref.v[2]] : [ref.v[0], node];
    BL()[node].parent = ref.pid;
  }
  BL()[node].next = after;
  if (after) BL()[after].parent = node;
  console.log('[P147] mapping values bypass the positional read');
  console.log('[P147] percent mapping ready');
});

// ---- P148: `dict(a=1, b=2)` -- keyword arguments for the `dict` constructor (v4.75) ----
//
// `dict(a=1)` died with `SyntaxError: expression` (the span `a=1` was handed to `eval` whole) and
// `dict(a=1, b=2)` with `NameError: name 'dict' is not defined` (a call with a top-level comma walks
// eval's builtin branches, `dict` is in none of them, so it fell through to P141's last resort).
//
// Two hooks:
//
//   * eval's last resort: a `dict(...)` span with a top-level comma goes to `callfn` instead of
//     failing with NameError.  Only `dict` -- routing every unknown name there would turn
//     `len(1, 2)` from an error into a wrong answer.
//   * callfn's `dict` branch, before the positional body: the keyword form builds the records here.
//     A piece must be `name = value` (the name is the string key, the value is evaluated); a
//     repeated name raises CPython's `SyntaxError: keyword argument repeated: a`; a piece that is
//     not `name = value` is the *mapping* argument (`dict(d, a=1)`, anything else says
//     `TypeError: '<type>' object is not iterable`).  With no `=` at all, several pieces say
//     `TypeError: dict expected at most 1 argument, got N`.
patch('P148 dict keyword arguments', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const tokAt = (i) => item('Tok', i);
  const kindAt = (i) => item('Kind', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const lit = (() => {
    for (const t of [T(IT), T('Stage')]) {
      for (const v of Object.values(t.variables || {})) if (v[0] === 'lsep') return String(v[1]);
    }
    throw new Error('[P148] lsep variable not found');
  })();
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p18c', 'p18e', 'p18i', 'p18d', 'p18lo', 'p18hi', 'p18k', 'p18h']) {
    if (taken.has(n)) throw new Error('[P148] variable name taken: ' + n);
    newVar(n, 0);
  }
  B.addList(IT, 'DKwC', []);   // piece boundaries (comma positions)
  B.addList(IT, 'DKwN', []);   // keyword names seen so far

  // is p18k already in DKwN?  -> p18h
  const kh = newProc('kwhas', []);
  attachBody(kh.defId, [
    setV('p18h', num(0)), setV('p18i', num(1)),
    REPEATU(OR(GT(VAR('p18i'), llen('DKwN')), EQ(VAR('p18h'), num(1))), [
      IF(AND(EQ(VAR('p18h'), num(0)), EQ(item('DKwN', VAR('p18i')), VAR('p18k'))), [setV('p18h', num(1))]),
      chgV('p18i', num(1))
    ])
  ]);

  // a scan of a token span: top-level commas -> p18c, a top-level `=` -> p18e
  const scanSpan = (from, to) => [
    setV('p18c', num(0)), setV('p18e', num(0)), setV('p18lo', from), setV('p18hi', to), setV('p18d', num(0)),
    REPEATU(GT(VAR('p18lo'), VAR('p18hi')), [
      IF(OR(EQ(tokAt(VAR('p18lo')), txt('(')), OR(EQ(tokAt(VAR('p18lo')), txt('[')), EQ(tokAt(VAR('p18lo')), txt('{')))), [chgV('p18d', num(1))]),
      IF(OR(EQ(tokAt(VAR('p18lo')), txt(')')), OR(EQ(tokAt(VAR('p18lo')), txt(']')), EQ(tokAt(VAR('p18lo')), txt('}')))), [chgV('p18d', num(-1))]),
      IF(AND(EQ(VAR('p18d'), num(0)), EQ(tokAt(VAR('p18lo')), txt(','))), [chgV('p18c', num(1))]),
      IF(AND(EQ(VAR('p18d'), num(0)), AND(EQ(tokAt(VAR('p18lo')), txt('=')), NOT(EQ(tokAt(ADD(VAR('p18lo'), num(1))), txt('='))))), [setV('p18e', num(1))]),
      chgV('p18lo', num(1))
    ])
  ];

  // ---------- (a) eval: `dict(...)` with a top-level comma reaches callfn
  const ev = inDef('eval %s %s');
  const x8Ifs = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && JSON.stringify([...reach(b.inputs.CONDITION[1])].map((i) => BL()[i].inputs || {})).includes('x8nc'));
  // the last-resort one is the branch whose else fails with the NameError text
  const textOf = (id) => {
    const out = [];
    for (const x of reach(id)) {
      const b = BL()[x];
      if (b.opcode === 'procedures_call' && b.mutation) out.push(b.mutation.proccode);
      for (const v of Object.values(b.inputs || {})) if (v && Array.isArray(v[1]) && v[1][0] === 10) out.push(String(v[1][1]));
    }
    return out.join('');
  };
  const lastResort = x8Ifs.filter((id) => BL()[id].inputs.SUBSTACK2 && typeof BL()[id].inputs.SUBSTACK2[1] === 'string'
    && textOf(BL()[id].inputs.SUBSTACK2[1]).includes('is not defined'));
  if (lastResort.length !== 1) throw new Error('[P148] eval last resort = ' + lastResort.length + ' of ' + x8Ifs.length);
  insertBeforeStmt(lastResort[0], [
    ...scanSpan(ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))),
    IF(AND(EQ(tokAt(argOf('lo')), txt('dict')), GT(VAR('p18c'), num(0))), [
      callProc('callfn %s %s %s', [tokAt(argOf('lo')), ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
      chgV('fnlimit', num(-1)),
      STOPTHIS()
    ])
  ]);
  console.log('[P148] eval routes dict(...) with commas to callfn');

  // ---------- (b) callfn: the keyword form, *before* the argument span is evaluated
  // (callfn evaluates `lo..hi` as one expression right after its class branch, so a `k=v` span has
  // to be intercepted ahead of that -- the `dict` branch itself is far too late)
  const cf = inDef('callfn %s %s %s');
  // the *main* argument evaluation: everything callfn does before it (the class-construction branch)
  // must stay ahead of the keyword handling, so pick the `eval(lo, hi)` that is NOT in the
  // `if (fn in ClsName)` branch
  const clsBranch = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && JSON.stringify([...reach(b.inputs.CONDITION[1])].map((i) => BL()[i].fields || {})).includes('ClsName'));
  if (clsBranch.length !== 1) throw new Error('[P148] callfn class branch = ' + clsBranch.length);
  const clsContent = reach(BL()[clsBranch[0]].inputs.SUBSTACK[1]);
  const argEvals = find(cf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s')
    .filter((id) => !clsContent.has(id));
  if (argEvals.length !== 1) throw new Error('[P148] callfn main argument eval = ' + argEvals.length);
  const argGuard = argEvals;
  const kwShape = () => AND(EQ(kindAt(VAR('p18lo')), txt('I')),
    AND(EQ(tokAt(ADD(VAR('p18lo'), num(1))), txt('=')),
      NOT(EQ(tokAt(ADD(VAR('p18lo'), num(2))), txt('=')))));
  insertBeforeStmt(argGuard[0], [
    IF(EQ(argOf('fn'), txt('dict')), [
      ...scanSpan(argOf('lo'), argOf('hi')),
      IF(EQ(VAR('p18e'), num(1)), [
      clearL('DKwC'), clearL('DKwN'),
      // piece boundaries
      setV('p18i', argOf('lo')), setV('p18d', num(0)),
      REPEATU(GT(VAR('p18i'), argOf('hi')), [
        IF(OR(EQ(tokAt(VAR('p18i')), txt('(')), OR(EQ(tokAt(VAR('p18i')), txt('[')), EQ(tokAt(VAR('p18i')), txt('{')))), [chgV('p18d', num(1))]),
        IF(OR(EQ(tokAt(VAR('p18i')), txt(')')), OR(EQ(tokAt(VAR('p18i')), txt(']')), EQ(tokAt(VAR('p18i')), txt('}')))), [chgV('p18d', num(-1))]),
        IF(AND(EQ(VAR('p18d'), num(0)), EQ(tokAt(VAR('p18i')), txt(','))), [addTo('DKwC', VAR('p18i'))]),
        chgV('p18i', num(1))
      ]),
      addTo('DKwC', ADD(argOf('hi'), num(1))),
      setV('d14acc', txt('')), setV('p18d', txt('')),
      setV('p18i', argOf('lo')), setV('p18c', num(1)),
      REPEATU(GT(VAR('p18c'), llen('DKwC')), [
        setV('p18lo', VAR('p18i')), setV('p18hi', SUB(item('DKwC', VAR('p18c')), num(1))),
        IF(NOT(GT(VAR('p18lo'), VAR('p18hi'))), [
          IFELSE(kwShape(), [
            // `name = value`
            setV('p18k', tokAt(VAR('p18lo'))), callProc('kwhas', []),
            IF(EQ(VAR('p18h'), num(1)), [
              failMsg(joinAll([txt('SyntaxError: keyword argument repeated: '), VAR('p18k')]))
            ]),
            addTo('DKwN', VAR('p18k')),
            callProc('lesc %s', [VAR('p18k')]), setV('d14ke', VAR('ev')),
            callProc('eval %s %s', [ADD(VAR('p18lo'), num(2)), VAR('p18hi')]),
            IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
            setV('d14vt', VAR('evtype')),
            callProc('lesc %s', [VAR('ev')]), setV('d14ve', VAR('ev')),
            setV('d14acc', J(VAR('d14acc'), J(J(J(txt(lit), txt('S')), VAR('d14ke')),
              J(J(txt(lit), VAR('d14vt')), VAR('d14ve')))))
          ], [
            // anything else is the *mapping* argument
            callProc('eval %s %s', [VAR('p18lo'), VAR('p18hi')]),
            IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
            IFELSE(EQ(VAR('evtype'), txt('D')), [
              setV('p18d', VAR('ev'))
            ], [
              setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
              failMsg(J(J(txt("TypeError: '"), VAR('p6msg')), txt("' object is not iterable")))
            ])
          ])
        ]),
        setV('p18i', ADD(item('DKwC', VAR('p18c')), num(1))),
        chgV('p18c', num(1))
      ]),
      // a mapping argument is appended as-is: the keyword records come first, so a keyword wins an
      // overlapping key (CPython keeps the mapping's position instead -- a cosmetic difference)
      IF(NOT(EQ(VAR('p18d'), txt(''))), [setV('d14acc', J(VAR('d14acc'), VAR('p18d')))]),
      setV('ev', VAR('d14acc')), setV('evtype', txt('D')), setV('pending', num(1)),
      STOPTHIS()
    ]),
    // no `=` but several pieces: CPython counts the arguments
    IF(AND(EQ(VAR('p18e'), num(0)), GT(VAR('p18c'), num(0))), [
      failMsg(joinAll([txt('TypeError: dict expected at most 1 argument, got '), ADD(VAR('p18c'), num(1))])),
      STOPTHIS()
    ])
    ])
  ]);
  console.log('[P148] callfn intercepts dict keyword arguments before the argument eval');
  console.log('[P148] dict kwargs ready');
});

// ---- P149: a dict iterates as its keys + `'{a}'.format(a=1)` (v4.76) ----
//
// (a) `list(d)`, `tuple(d)`, `set(d)`, `enumerate(d)`, `zip(d, …)`, `min(d)`/`max(d)`, `any(d)`/`all(d)`
//     and `sorted(d)` all refused a dict: `callfn`'s branches (and eval's `sorted` branch) only accept
//     L/T/G/E, so a `D` fell through to "requires an iterable"/"requires a list".  CPython iterates a
//     dict as its *keys*, and `dictkeys` (P91) already turns a dict into the list encoding of them --
//     so this is one whitelisted call in `callfn` (before its branch chain) plus one in eval's
//     `sorted` branch (which never reaches callfn).  `len(d)`/`str(d)`/`print(d)` stay untouched.
//
// (b) `'{a}={b}'.format(a=1, b=2)` died with `SyntaxError: expression`: the `format` path of
//     `methodcall` splits the argument span on commas and evaluates every piece, so `a=1` went to
//     eval whole.  A parallel list `FmtN` records each piece's keyword name ('' for positional),
//     `strfmt` resolves a non-numeric `{...}` through it (`KeyError: 'a'` when missing) and its
//     automatic numbering skips the keyword entries so `'{} {a}'.format(1, a=2)` lines up.
patch('P149 dict keys and format keywords', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const tokAt = (i) => item('Tok', i);
  const kindAt = (i) => item('Kind', i);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const ITERATORS = ['list', 'tuple', 'set', 'enumerate', 'zip', 'sorted', 'min', 'max', 'any', 'all'];
  // a reporter block can only sit in ONE input, so every comparison gets a fresh one
  const isIterator = (fnOf) => ITERATORS.map((n) => EQ(fnOf(), txt(n))).reduce((a, b) => OR(a, b));
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['sfname', 'sfnidx', 'sfnf']) {
    if (taken.has(n)) throw new Error('[P149] variable name taken: ' + n);
    newVar(n, 0);
  }
  B.addList(IT, 'FmtN', []);
  // chain-safe single-statement replacement: `replaceStmt` copies `old.next` onto the new head
  const replaceChain = (oldId, list) => {
    const head = chain(list);
    const pred = predecessorOf(oldId);
    const nx = BL()[oldId].next;
    if (pred) { BL()[pred].next = head; BL()[head].parent = pred; }
    else {
      const ref = refOf(oldId);
      if (!ref) throw new Error('[P149] cannot locate ' + oldId);
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], head, ref.v[2]] : [ref.v[0], head];
      BL()[head].parent = ref.pid;
    }
    let tail = head, g = 0;
    while (BL()[tail].next && g++ < 100) tail = BL()[tail].next;
    BL()[tail].next = nx;
    if (nx) BL()[nx].parent = tail;
    BL()[oldId].next = null;
    return head;
  };

  // ---------- (a) callfn: a dict argument becomes its keys before the branch chain
  const cf = inDef('callfn %s %s %s');
  const setBranch = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && JSON.stringify(BL()[x].inputs.OPERAND2 || {}).includes('"set"')));
  if (setBranch.length !== 1) throw new Error('[P149] callfn set branch = ' + setBranch.length);
  insertBeforeStmt(setBranch[0], [
    IF(AND(EQ(VAR('evtype'), txt('D')), isIterator(() => argOf('fn'))), [
      callProc('dictkeys %s', [VAR('ev')])
    ])
  ]);
  console.log('[P149] callfn iterates a dict as its keys');

  // ---------- (a2) eval's `sorted` branch (it runs before callfn)
  const ev = inDef('eval %s %s');
  const sortedFail = [...ev].filter((i) => {
    const b = BL()[i];
    return b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
      && JSON.stringify(b.inputs).includes('sorted() requires a list');
  });
  if (sortedFail.length < 1) throw new Error('[P149] sorted type check = ' + sortedFail.length);
  for (const id of sortedFail) {
    insertBeforeStmt(id, [IF(EQ(VAR('evtype'), txt('D')), [callProc('dictkeys %s', [VAR('ev')])])]);
  }
  console.log('[P149] sorted() accepts a dict (' + sortedFail.length + ' sites)');

  console.log('[P149] dict iteration ready (the format-keyword half is deferred)');
});

// ---- P150: `'{a}={b}'.format(a=1, b=2)` -- keyword arguments for `str.format` (v4.77) ----
//
// P82 gave `format` its own argument scan: every top-level comma between `(` and `)` is evaluated
// into FmtV/FmtT, then `strfmt` walks the receiver and substitutes `{}` (automatic), `{2}`
// (explicit), `{{` and `}}`.  A piece that is `name = value` was handed to `eval` whole and died with
// `SyntaxError: expression`, and a `{name}` field was read as "no digits" and treated as automatic.
//
// Three hooks:
//
//   * `methodcall`'s format scan hands every piece to the new procedure `fmtarg`, which decides
//     positional vs keyword: a piece whose first top-level `=` has a name-shaped left side is a
//     keyword (`==`/`<=`/`>=`/`!=` are single tokens, so plain `EQ(tok, '=')` is enough).  The
//     positionals are pushed first and the keyword values after them, with `fwpos` counting the
//     positionals -- so a positional index never collides with a keyword value, and a keyword
//     *after* a positional is still found at `fwpos + (its position among the keywords)`.
//     Pieces keep CPython's order rules: a repeated keyword and a positional after a keyword fail.
//   * `strfmt` accumulates the raw field text and resolves a non-numeric, non-empty field through
//     the `FmtK` list of keyword names (`KeyError: 'a'` when missing); the automatic counter stays
//     untouched by named fields, so `'{} {a}'.format(1, a=2)` still lines up.
//   * the explicit-index bound becomes `fwpos` instead of `len(FmtV)`: with no keywords the two are
//     equal (so nothing changes), with keywords it correctly stops `'{0}'.format(a=1)` from
//     answering a keyword value as positional argument 0.
patch('P150 format keywords', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fwpos', 'fwseen', 'fweq', 'fwdep', 'fwq', 'fwk', 'fwname', 'fwidx', 'fwj', 'fwrec']) {
    if (taken.has(n)) throw new Error('[P150] variable name taken: ' + n);
    newVar(n, 0);
  }
  if (Object.values(T(IT).lists).some((x) => x[0] === 'FmtK')) throw new Error('[P150] list name taken: FmtK');
  B.addList(IT, 'FmtK', []);   // keyword names, positionally aligned with the keyword values in FmtV

  // replace the whole statement span [first..last] with a fresh chain.  `replaceStmt` copies
  // `old.next` onto the new head (which truncates a multi-block chain) and cannot drop the blocks
  // after the replaced one, so a span needs its own helper: the tail after `last` is re-linked to
  // the end of the new chain and the replaced blocks are left orphaned for `pruneUnreachable`.
  const replaceSpan = (first, last, ids) => {
    const pred = predecessorOf(first);
    const nx = BL()[last].next;
    const head = chain(ids);
    if (pred) { BL()[pred].next = head; BL()[head].parent = pred; }
    else {
      const ref = refOf(first);
      if (!ref) throw new Error('[P150] cannot place span');
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], head, ref.v[2]] : [ref.v[0], head];
      BL()[head].parent = ref.pid;
    }
    let tail = head, g = 0;
    while (BL()[tail].next && g++ < 500) tail = BL()[tail].next;
    BL()[tail].next = nx;
    if (nx) BL()[nx].parent = tail;
    BL()[first].next = null;
    BL()[last].next = null;
    return head;
  };

  // ---------- (a) fmtarg: one argument piece -> positional or keyword
  const fa = newProc('fmtarg %s %s', ['flo', 'fhi']);
  attachBody(fa.defId, [
    // where is the first top-level `=` of the piece?  (fweq = 0 means "none")
    setV('fweq', num(0)), setV('fwdep', num(0)), setV('fwk', argOf('flo')),
    REPEATU(GT(VAR('fwk'), argOf('fhi')), [
      setV('fwq', tokAt(VAR('fwk'))),
      IF(OR(EQ(VAR('fwq'), txt('(')), EQ(VAR('fwq'), txt('['))), [chgV('fwdep', num(1))]),
      IF(OR(EQ(VAR('fwq'), txt(')')), EQ(VAR('fwq'), txt(']'))), [chgV('fwdep', num(-1))]),
      IF(AND(EQ(VAR('fwdep'), num(0)), AND(EQ(VAR('fwq'), txt('=')), EQ(VAR('fweq'), num(0)))), [setV('fweq', VAR('fwk'))]),
      chgV('fwk', num(1))
    ]),
    IFELSE(GT(VAR('fweq'), num(0)), [
      // ---- `name = value`
      setV('fwname', txt('')),
      setV('fwk', argOf('flo')),
      REPEATU(GT(VAR('fwk'), SUB(VAR('fweq'), num(1))), [
        setV('fwname', J(VAR('fwname'), tokAt(VAR('fwk')))),
        chgV('fwk', num(1))
      ]),
      // repeated keyword?
      setV('fwidx', num(0)), setV('fwj', num(1)),
      REPEATU(OR(GT(VAR('fwj'), llen('FmtK')), GT(VAR('fwidx'), num(0))), [
        IF(EQ(item('FmtK', VAR('fwj')), VAR('fwname')), [setV('fwidx', VAR('fwj'))]),
        chgV('fwj', num(1))
      ]),
      IF(GT(VAR('fwidx'), num(0)), [
        failMsg(joinAll([txt('SyntaxError: keyword argument repeated: '), VAR('fwname')]))
      ]),
      IF(EQ(VAR('error'), txt('')), [
        callProc('eval %s %s', [ADD(VAR('fweq'), num(1)), argOf('fhi')]),
        IF(EQ(VAR('error'), txt('')), [
          addTo('FmtV', VAR('ev')), addTo('FmtT', VAR('evtype')), addTo('FmtK', VAR('fwname')),
          setV('fwseen', num(1))
        ])
      ])
    ], [
      // ---- positional
      IF(EQ(VAR('fwseen'), num(1)), [
        failMsg(txt('SyntaxError: positional argument follows keyword argument'))
      ]),
      IF(EQ(VAR('error'), txt('')), [
        callProc('eval %s %s', [argOf('flo'), argOf('fhi')]),
        IF(EQ(VAR('error'), txt('')), [
          addTo('FmtV', VAR('ev')), addTo('FmtT', VAR('evtype')),
          chgV('fwpos', num(1))
        ])
      ])
    ])
  ]);
  console.log('[P150] fmtarg registered');

  // ---------- (b) strfmt: resolve `{name}`
  const sf = inDef('strfmt %s');
  const sfIds = sf;   // inDef already returns the reachable set
  // the scan loop of a `{...}` field: the only repeat_until in strfmt whose condition is an `or`
  const scanRepeat = find(sfIds, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or');
  if (scanRepeat.length !== 1) throw new Error('[P150] strfmt field scan = ' + scanRepeat.length);
  // accumulate the raw field text next to the digit scan
  prependStack(scanRepeat[0], 'SUBSTACK', setV('fwname', J(VAR('fwname'), letterOf(VAR('sfk'), argOf('s')))));
  const sfnumInit = find(sfIds, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'sfnum'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '0');
  if (sfnumInit.length !== 1) throw new Error('[P150] strfmt sfnum init = ' + sfnumInit.length);
  insertBeforeStmt(sfnumInit[0], [setV('fwname', txt(''))]);
  // the substitution tail: `if sfhas == 0 { sfnum = sfa }` .. `sfi = sfk`
  const sfhasIf = find(sfIds, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && Array.isArray(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1]) && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'sfhas');
  if (sfhasIf.length !== 1) throw new Error('[P150] strfmt sfhas branch = ' + sfhasIf.length);
  const sfiSet = find(sfIds, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'sfi'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && BL()[b.inputs.VALUE[1]] === undefined && b.inputs.VALUE[1][0] === 12 && b.inputs.VALUE[1][1] === 'sfk');
  if (sfiSet.length !== 1) throw new Error('[P150] strfmt sfi tail = ' + sfiSet.length);
  // sanity: the span really is the four statements in order and ends the branch
  const sfaSet = BL()[sfhasIf[0]].next;
  const emitIf = sfaSet && BL()[sfaSet].next;
  if (!sfaSet || BL()[sfaSet].fields.VARIABLE[0] !== 'sfa' || !emitIf || BL()[emitIf].opcode !== 'control_if'
    || !BL()[emitIf].inputs.CONDITION || BL()[BL()[emitIf].inputs.CONDITION[1]].opcode !== 'operator_lt'
    || BL()[emitIf].next !== sfiSet[0] || BL()[sfiSet[0]].next) {
    throw new Error('[P150] strfmt tail shape changed');
  }
  const namedCond = () => AND(EQ(VAR('sfhas'), num(0)), NOT(EQ(VAR('fwname'), txt(''))));
  const namedBody = [
    setV('fwidx', num(0)), setV('fwj', num(1)),
    REPEATU(OR(GT(VAR('fwj'), llen('FmtK')), GT(VAR('fwidx'), num(0))), [
      IF(EQ(item('FmtK', VAR('fwj')), VAR('fwname')), [setV('fwidx', VAR('fwj'))]),
      chgV('fwj', num(1))
    ]),
    IFELSE(GT(VAR('fwidx'), num(0)), [
      setV('sfn', item('FmtV', ADD(VAR('fwpos'), VAR('fwidx')))),
      setV('sft', item('FmtT', ADD(VAR('fwpos'), VAR('fwidx')))),
      callProc('strval %s %s', [VAR('sfn'), VAR('sft')]),
      setV('sfacc', J(VAR('sfacc'), VAR('ev')))
    ], [
      failMsg(J(J(txt("KeyError: '"), VAR('fwname')), txt("'")))
    ])
  ];
  const positionalBody = [
    IF(EQ(VAR('sfhas'), num(0)), [setV('sfnum', VAR('sfa'))]),
    setV('sfa', ADD(VAR('sfnum'), num(1))),
    IF(LT(VAR('sfnum'), VAR('fwpos')), [
      setV('sfn', item('FmtV', ADD(VAR('sfnum'), num(1)))),
      setV('sft', item('FmtT', ADD(VAR('sfnum'), num(1)))),
      callProc('strval %s %s', [VAR('sfn'), VAR('sft')]),
      setV('sfacc', J(VAR('sfacc'), VAR('ev')))
    ])
  ];
  replaceSpan(sfhasIf[0], sfiSet[0], [IFELSE(namedCond(), namedBody, positionalBody), setV('sfi', VAR('sfk'))]);
  console.log('[P150] strfmt resolves a named field');

  // ---------- (c) methodcall: route the pieces through fmtarg
  // P82 hung the whole argument scan (its own comma split + direct `eval` per piece) on a router
  // `if (xb == 'S' and lmeth == 'format')`, and the `strfmt` call sits at its very end.  Replacing
  // only that inner guard would leave the old scan ahead of it -- and the old scan evaluates `a=1`
  // whole, which is exactly the SyntaxError being fixed.  So replace the router's substack.
  const mc = inDef('methodcall %s %s');
  const strfmtCall = find(mc, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'strfmt %s');
  if (strfmtCall.length !== 1) throw new Error('[P150] methodcall strfmt call = ' + strfmtCall.length);
  const routerIf = find(mc, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    const lits = new Set();
    for (const c of reach(b.inputs.CONDITION[1])) {
      for (const v of Object.values(BL()[c].inputs || {})) if (v && Array.isArray(v[1]) && v[1][0] === 10) lits.add(String(v[1][1]));
    }
    return lits.has('format') && lits.has('S');
  });
  if (routerIf.length !== 1) throw new Error('[P150] methodcall format router = ' + routerIf.length);
  if (!reach(BL()[routerIf[0]].inputs.SUBSTACK[1]).has(strfmtCall[0])) throw new Error('[P150] strfmt is not under the format router');
  setStack(routerIf[0], 'SUBSTACK', [
    // P82 used to hand `xa` (the receiver) to `strfmt` *after* evaluating every piece -- but a piece
    // like `a[1]` goes through `indexget`, whose own parameters are named `xa`/`xb`, and a piece like
    // `s.upper()` goes through `methodcall`, which reloads `xa` from the inner receiver.  So the
    // format string silently became the argument (`'{}'.format(a[1])` printed the raw list, and
    // `'{}'.format('ab'.upper())` printed `ab`).  Capture the receiver first.
    setV('fwrec', VAR('xa')),
    clearL('FmtV'), clearL('FmtT'), clearL('FmtK'),
    setV('fwpos', num(0)), setV('fwseen', num(0)),
    setV('sfcut', ADD(argOf('lo'), num(3))),
    setV('sfdep', num(0)),
    setV('sfk', ADD(argOf('lo'), num(4))),
    REPEATU(GT(VAR('sfk'), SUB(argOf('hi'), num(1))), [
      setV('sfq', item('Tok', VAR('sfk'))),
      IF(OR(EQ(VAR('sfq'), txt('(')), EQ(VAR('sfq'), txt('['))), [chgV('sfdep', num(1))]),
      IF(OR(EQ(VAR('sfq'), txt(')')), EQ(VAR('sfq'), txt(']'))), [chgV('sfdep', num(-1))]),
      IF(AND(EQ(VAR('sfdep'), num(0)), EQ(VAR('sfq'), txt(','))), [
        IF(EQ(VAR('error'), txt('')), [callProc('fmtarg %s %s', [ADD(VAR('sfcut'), num(1)), SUB(VAR('sfk'), num(1))])]),
        setV('sfcut', VAR('sfk'))
      ]),
      chgV('sfk', num(1))
    ]),
    IF(AND(EQ(VAR('error'), txt('')), LT(VAR('sfcut'), SUB(argOf('hi'), num(1)))), [
      callProc('fmtarg %s %s', [ADD(VAR('sfcut'), num(1)), SUB(argOf('hi'), num(1))])
    ]),
    IF(EQ(VAR('error'), txt('')), [callProc('strfmt %s', [VAR('fwrec')])]),
    STOPTHIS()
  ]);
  console.log('[P150] methodcall routes format pieces through fmtarg');

  console.log('[P150] format keywords ready');
});

// ---- P151: `'{a:>5}'.format(a=1)` -- format specs in `str.format` fields (v4.78) ----
//
// `strfmt` read a field as "digits or nothing": `'{a:>5}'` accumulated the `5` of the spec and
// treated the field as explicit positional index 5 (nothing matched, so the substitution vanished),
// and `'{:>5}'.format(1)` printed an empty line.  CPython's spec is
// `[[fill]align][sign][#][0][width][,][.precision][type]`.
//
// Two new procedures keep the field parser small:
//
//   * `fldspec(spec, vt)` parses that mini-language into what `pctitem` (P77/P145) already
//     understands: fill char + alignment (`<`/`>`/`^`/`=`), the `+`/space sign, the `0` flag, width,
//     `.precision` and the conversion character.  Zero-fill is handed to `pctitem` (it inserts the
//     zeros after the sign); every other fill is applied here, so `flditem` pads the finished text.
//   * `flditem(vv, vt)` formats one value: with no spec it is the old `strval`, with a spec it runs
//     `fldspec` + `pctitem` + the padding.
//
// The alignment default follows the value type (strings left, numbers right), which is why
// `fldspec` needs `vt`.  `strfmt` only splits the field at its first top-level `:` -- everything
// before it is the name/index, everything after it is the spec.
patch('P151 format field specs', () => {
  const J = (a, b) => JOIN(a, b);
  const contains = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NAMES = ['fwspec', 'fwi', 'fwfill', 'fwaln', 'fwsign', 'fwzero', 'fwwid', 'fwprec', 'fwconv',
    'fwbody', 'fwpad', 'fwtext', 'fwnp', 'fwl', 'fwr', 'fwpl', 'fwpr', 'fwsg', 'fwsave'];
  for (const n of NAMES) {
    if (taken.has(n)) throw new Error('[P151] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- (a) fldspec: CPython's spec -> pctitem's spec + conv (+ our padding plan)
  const fl = newProc('fldspec %s %s', ['fs', 'vt']);
  const chS = (i) => letterOf(i, argOf('fs'));
  attachBody(fl.defId, [
    setV('fwfill', txt(' ')), setV('fwaln', txt('')), setV('fwsign', txt('')),
    setV('fwzero', num(0)), setV('fwwid', num(0)), setV('fwprec', txt('')),
    setV('fwconv', txt('')), setV('fwpad', num(0)), setV('fwi', num(1)),
    // [[fill]align]
    IF(NOT(GT(VAR('fwi'), lenOf(argOf('fs')))), [
      IFELSE(contains(chS(VAR('fwi')), '<>^='), [
        setV('fwaln', chS(VAR('fwi'))),
        chgV('fwi', num(1))
      ], [
        IF(AND(NOT(GT(ADD(VAR('fwi'), num(1)), lenOf(argOf('fs')))), contains(chS(ADD(VAR('fwi'), num(1))), '<>^=')), [
          setV('fwfill', chS(VAR('fwi'))),
          setV('fwaln', chS(ADD(VAR('fwi'), num(1)))),
          chgV('fwi', num(2))
        ])
      ])
    ]),
    // [sign] [#]
    IF(NOT(GT(VAR('fwi'), lenOf(argOf('fs')))), [
      IF(OR(EQ(chS(VAR('fwi')), txt('+')), EQ(chS(VAR('fwi')), txt(' '))), [
        setV('fwsign', chS(VAR('fwi'))),
        chgV('fwi', num(1))
      ]),
      // `-` means "only negative numbers carry a sign", which is the default
      IF(EQ(chS(VAR('fwi')), txt('-')), [chgV('fwi', num(1))]),
      IF(EQ(chS(VAR('fwi')), txt('#')), [chgV('fwi', num(1))])
    ]),
    // [0]
    IF(AND(NOT(GT(VAR('fwi'), lenOf(argOf('fs')))), EQ(chS(VAR('fwi')), txt('0'))), [
      setV('fwzero', num(1)),
      chgV('fwi', num(1))
    ]),
    // [width] -- `,` and `_` are grouping hints and are skipped
    REPEATU(OR(GT(VAR('fwi'), lenOf(argOf('fs'))),
      NOT(OR(contains(chS(VAR('fwi')), '0123456789'), OR(EQ(chS(VAR('fwi')), txt(',')), EQ(chS(VAR('fwi')), txt('_')))))), [
      IF(contains(chS(VAR('fwi')), '0123456789'), [
        setV('fwwid', ADD(MUL(VAR('fwwid'), num(10)), chS(VAR('fwi'))))
      ]),
      chgV('fwi', num(1))
    ]),
    // [.precision]
    IF(AND(NOT(GT(VAR('fwi'), lenOf(argOf('fs')))), EQ(chS(VAR('fwi')), txt('.'))), [
      setV('fwprec', txt('.')),
      chgV('fwi', num(1)),
      REPEATU(OR(GT(VAR('fwi'), lenOf(argOf('fs'))), NOT(contains(chS(VAR('fwi')), '0123456789'))), [
        setV('fwprec', J(VAR('fwprec'), chS(VAR('fwi')))),
        chgV('fwi', num(1))
      ])
    ]),
    // [type]
    IF(NOT(GT(VAR('fwi'), lenOf(argOf('fs')))), [setV('fwconv', chS(VAR('fwi')))]),
    // `0` fill is pctitem's job (it must go after the sign); anything else is padded below
    IFELSE(EQ(VAR('fwzero'), num(1)), [
      setV('fwbody', J(J(VAR('fwsign'), txt('0')), J(VAR('fwwid'), VAR('fwprec')))),
      setV('fwpad', num(0))
    ], [
      setV('fwbody', J(VAR('fwsign'), VAR('fwprec'))),
      setV('fwpad', num(1))
    ]),
    // the default alignment depends on the value: text left, numbers right
    IF(EQ(VAR('fwaln'), txt('')), [
      IFELSE(EQ(argOf('vt'), txt('S')), [setV('fwaln', txt('L'))], [setV('fwaln', txt('R'))])
    ]),
    IF(EQ(VAR('fwaln'), txt('<')), [setV('fwaln', txt('L'))]),
    // `>` is ordinary right alignment; `=` pads *after* the sign (`'{:=5}'.format(-42)` -> `-  42`)
    IF(EQ(VAR('fwaln'), txt('>')), [setV('fwaln', txt('R'))]),
    IF(EQ(VAR('fwaln'), txt('=')), [setV('fwaln', txt('E'))]),
    IF(EQ(VAR('fwaln'), txt('^')), [setV('fwaln', txt('C'))])
  ]);
  console.log('[P151] fldspec registered');

  // ---------- (b) flditem: format one value (with or without a spec)
  const fi = newProc('flditem %s %s', ['vv', 'vt']);
  attachBody(fi.defId, [
    IFELSE(GT(lenOf(VAR('fwspec')), num(1)), [
      // `fwspec` still carries its leading ':'
      callProc('substr %s %s %s', [VAR('fwspec'), num(2), lenOf(VAR('fwspec'))]),
      setV('fwtext', VAR('ev')),
      callProc('fldspec %s %s', [VAR('fwtext'), argOf('vt')]),
      callProc('pctitem %s %s %s %s', [argOf('vv'), argOf('vt'), VAR('fwbody'), VAR('fwconv')]),
      setV('fwtext', VAR('ev')),
      IF(AND(EQ(VAR('fwpad'), num(1)), LT(lenOf(VAR('fwtext')), VAR('fwwid'))), [
        setV('fwnp', SUB(VAR('fwwid'), lenOf(VAR('fwtext')))),
        setV('fwsg', txt('')),
        // `=` alignment: keep a leading sign out of the padding
        IF(EQ(VAR('fwaln'), txt('E')), [
          IF(OR(OR(EQ(letterOf(num(1), VAR('fwtext')), txt('-')), EQ(letterOf(num(1), VAR('fwtext')), txt('+'))),
            EQ(letterOf(num(1), VAR('fwtext')), txt(' '))), [
            setV('fwsg', letterOf(num(1), VAR('fwtext'))),
            callProc('substr %s %s %s', [VAR('fwtext'), num(2), lenOf(VAR('fwtext'))]),
            setV('fwtext', VAR('ev'))
          ])
        ]),
        setV('fwl', num(0)), setV('fwr', num(0)),
        IFELSE(EQ(VAR('fwaln'), txt('L')), [
          setV('fwr', VAR('fwnp'))
        ], [
          IFELSE(EQ(VAR('fwaln'), txt('C')), [
            setV('fwl', FLOOR(DIV(VAR('fwnp'), num(2)))),
            setV('fwr', SUB(VAR('fwnp'), VAR('fwl')))
          ], [
            setV('fwl', VAR('fwnp'))
          ])
        ]),
        setV('fwpl', txt('')),
        REPEAT(VAR('fwl'), [setV('fwpl', J(VAR('fwpl'), VAR('fwfill')))]),
        setV('fwpr', txt('')),
        REPEAT(VAR('fwr'), [setV('fwpr', J(VAR('fwpr'), VAR('fwfill')))]),
        setV('fwtext', J(VAR('fwsg'), J(J(VAR('fwpl'), VAR('fwtext')), VAR('fwpr'))))
      ]),
      setV('ev', VAR('fwtext')),
      setV('evtype', txt('S'))
    ], [
      callProc('strval %s %s', [argOf('vv'), argOf('vt')])
    ])
  ]);
  console.log('[P151] flditem registered');

  // ---------- (c) strfmt: the field text splits at the first ':' into name and spec
  const sf = inDef('strfmt %s');
  // the field scan is the `repeat until sfk > len(s) or letter(sfk) == '}'` loop; P150 added a
  // second `or` loop (the keyword lookup) that must not be confused with it
  const scanRepeat = find(sf, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_letter_of'));
  if (scanRepeat.length !== 1) throw new Error('[P151] strfmt field scan = ' + scanRepeat.length);
  const chSF = (i) => letterOf(i, argOf('s'));
  setStack(scanRepeat[0], 'SUBSTACK', [
    IFELSE(EQ(VAR('fwspec'), txt('')), [
      IFELSE(EQ(chSF(VAR('sfk')), txt(':')), [
        setV('fwspec', txt(':'))
      ], [
        setV('fwname', J(VAR('fwname'), chSF(VAR('sfk')))),
        IF(contains(chSF(VAR('sfk')), '0123456789'), [
          setV('sfnum', ADD(MUL(VAR('sfnum'), num(10)), chSF(VAR('sfk')))),
          setV('sfhas', num(1))
        ])
      ])
    ], [
      setV('fwspec', J(VAR('fwspec'), chSF(VAR('sfk'))))
    ]),
    chgV('sfk', num(1))
  ]);
  // reset the spec text once per field, next to P150's name reset
  const sfnumInit = find(sf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'sfnum'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '0');
  if (sfnumInit.length !== 1) throw new Error('[P151] strfmt sfnum init = ' + sfnumInit.length);
  insertBeforeStmt(sfnumInit[0], [setV('fwspec', txt(''))]);
  // both substitution branches go through flditem
  const svCalls = find(sf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'strval %s %s');
  if (svCalls.length !== 2) throw new Error('[P151] strfmt strval sites = ' + svCalls.length);
  for (const id of svCalls) replaceStmt(id, callProc('flditem %s %s', [VAR('sfn'), VAR('sft')]));
  console.log('[P151] strfmt applies the field spec');

  // ---------- (d) f-strings use the same spec parser.  P77 only split off the *last* character as
  // the conversion type, so `f'{n:>5}'` handed `>` to pctitem as the spec and `5` as the conversion
  // (nothing matched, `strval` answered).  `fz3 + fz4` rebuilds the original spec text; the field
  // spec variable is saved around the call so a nested f-string inside a `.format` argument cannot
  // clobber the outer spec.
  const fstr = inDef('fstr %s');
  const fpi = find(fstr, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'pctitem %s %s %s %s');
  if (fpi.length !== 1) throw new Error('[P151] fstr pctitem site = ' + fpi.length);
  insertBeforeStmt(fpi[0], [
    setV('fwsave', VAR('fwspec')),
    setV('fwspec', J(txt(':'), J(VAR('fz3'), VAR('fz4'))))
  ]);
  {
    const newCall = replaceStmt(fpi[0], callProc('flditem %s %s', [VAR('ev'), VAR('evtype')]));
    spliceAfter(newCall, chain([setV('fwspec', VAR('fwsave'))]));
  }
  console.log('[P151] f-string specs share the parser');

  console.log('[P151] format field specs ready');
});

// ---- P152: `%g`/`%G` + `b` + the `%` type (v4.79) ----
//
// `'%g' % 0.00001` printed `0.00001` and `'%g' % 100000000` printed `100000000` (the conversion fell
// through to `%s`), `'{a:.1%}'.format(a=0.25)` printed `0.25`, and `'{a:b}'.format(a=5)` printed `5`.
// All three live in `pctitem` (P77/P145/P146), which is shared by `%`, f-strings and `.format`.
//
//   * `g`/`G` -- general format.  The precision P (default 6, `0` means 1) is the number of
//     *significant* digits: normalize the value to `m` in [1, 10) to get the decimal exponent X,
//     round `m` to P-1 decimals (a roll-over to 10 promotes X), then use exponential form when
//     `X < -4` or `X >= P` and fixed form with `P-1-X` decimals otherwise; either way the
//     insignificant trailing zeros (and a bare `.`) are dropped.
//   * `b` -- binary: the hex/octal branch already picks its base and alphabet from `p15b`/`p15t`,
//     so `b` only needs those two statements to branch on the conversion plus one more `or` term.
//   * `%` -- percent: multiply by 100, format as `f` (default precision 6) and append `%`.
//
// The two format-driven conversions are implemented by *recursing into `pctitem`* for the numeric
// body (so the tested `e`/`f` arithmetic and rounding are reused verbatim) with a spec that carries
// no width; the outer call's width/zero-fill block then pads the finished text, which is what puts
// `'{a:8.1%}'.format(a=0.25)` at `   25.0%`.  The recursion clobbers pctitem's own flag variables,
// so they are saved into `p52*` locals and restored before the width block runs.
patch('P152 g and b and percent', () => {
  const J = (a, b) => JOIN(a, b);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const CEIL = (x) => I('operator_mathop', { fields: { OPERATOR: ['ceiling', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NAMES = ['p52w', 'p52l', 'p52z', 'p52a', 'p52b', 'p52c', 'p52p', 'p52e', 'p52m', 'p52s',
    'p52d', 'p52n', 'p52i', 'p52q', 'p52u', 'p52t', 'p52f', 'p52g', 'p52h'];
  for (const n of NAMES) {
    if (taken.has(n)) throw new Error('[P152] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- (a) gstrip: drop the insignificant trailing zeros of a decimal string
  const gs = newProc('gstrip %s', ['s']);
  const lastOf = (v) => letterOf(lenOf(v), v);
  attachBody(gs.defId, [
    setV('p52t', argOf('s')),
    IF(strHas(VAR('p52t'), txt('.')), [
      REPEATU(OR(NOT(GT(lenOf(VAR('p52t')), num(0))),
        OR(EQ(lastOf(VAR('p52t')), txt('.')), NOT(EQ(lastOf(VAR('p52t')), txt('0'))))), [
        callProc('substr %s %s %s', [VAR('p52t'), num(1), SUB(lenOf(VAR('p52t')), num(1))]),
        setV('p52t', VAR('ev'))
      ]),
      IF(AND(GT(lenOf(VAR('p52t')), num(0)), EQ(lastOf(VAR('p52t')), txt('.'))), [
        callProc('substr %s %s %s', [VAR('p52t'), num(1), SUB(lenOf(VAR('p52t')), num(1))]),
        setV('p52t', VAR('ev'))
      ])
    ]),
    setV('ev', VAR('p52t')), setV('evtype', txt('S'))
  ]);
  console.log('[P152] gstrip registered');

  // ---------- (b) pctg: general format
  const pg = newProc('pctg %s %s %s', ['vv', 'vt', 'conv']);
  attachBody(pg.defId, [
    // P (default 6, and 0 means 1) + the sign the mantissa needs
    setV('p52p', num(6)),
    IF(EQ(VAR('phas'), num(1)), [setV('p52p', VAR('ppr'))]),
    IF(EQ(VAR('p52p'), num(0)), [setV('p52p', num(1))]),
    setV('p52f', txt('')),
    IF(EQ(VAR('p15pl'), num(1)), [setV('p52f', txt('+'))]),
    IF(AND(EQ(VAR('p15pl'), num(0)), EQ(VAR('p15s'), num(1))), [setV('p52f', txt(' '))]),
    // magnitude + exponent X
    setV('p52m', argOf('vv')),
    IF(LT(VAR('p52m'), num(0)), [setV('p52m', SUB(num(0), VAR('p52m')))]),
    setV('p52e', num(0)),
    IF(GT(VAR('p52m'), num(0)), [
      REPEATU(NOT(GT(VAR('p52m'), num('9.9999999999'))), [setV('p52m', DIV(VAR('p52m'), num(10))), chgV('p52e', num(1))]),
      REPEATU(NOT(LT(VAR('p52m'), num(1))), [setV('p52m', MUL(VAR('p52m'), num(10))), chgV('p52e', num(-1))])
    ]),
    // round the mantissa to P-1 decimals; 10.000... promotes the exponent
    setV('p52q', num(1)),
    REPEAT(SUB(VAR('p52p'), num(1)), [setV('p52q', MUL(VAR('p52q'), num(10)))]),
    setV('p52u', FLOOR(ADD(MUL(VAR('p52m'), VAR('p52q')), num('0.5')))),
    IF(NOT(LT(VAR('p52u'), MUL(num(10), VAR('p52q')))), [chgV('p52e', num(1))]),
    // `e`/`E` for the exponent letter, chosen from the `g`/`G` conversion (EQ is Scratch's
    // case-insensitive `=`, so `compareText` is the only way to tell them apart)
    callProc('compareText %s %s', [argOf('conv'), txt('G')]),
    IFELSE(EQ(VAR('cmp'), num(0)), [setV('p52c', txt('E'))], [setV('p52c', txt('e'))]),
    IFELSE(OR(LT(VAR('p52e'), num(-4)), NOT(LT(VAR('p52e'), VAR('p52p')))), [
      // exponential: the tested `e` branch formats mantissa and exponent, then the mantissa's
      // trailing zeros go away (the exponent must survive the strip)
      setV('p52d', SUB(VAR('p52p'), num(1))),
      callProc('pctitem %s %s %s %s', [argOf('vv'), argOf('vt'), J(txt('.'), VAR('p52d')), VAR('p52c')]),
      setV('p52n', VAR('ev')),
      // `sfind` returns a 0-based index, so the letter sits at p52i+1
      callProc('sfind %s %s', [VAR('p52n'), VAR('p52c')]),
      setV('p52i', VAR('ev')),
      IF(GT(VAR('p52i'), num(0)), [
        callProc('substr %s %s %s', [VAR('p52n'), num(1), VAR('p52i')]),
        callProc('gstrip %s', [VAR('ev')]), setV('p52g', VAR('ev')),
        callProc('substr %s %s %s', [VAR('p52n'), ADD(VAR('p52i'), num(1)), lenOf(VAR('p52n'))]), setV('p52h', VAR('ev')),
        setV('p52n', J(VAR('p52g'), VAR('p52h')))
      ]),
      setV('ev', VAR('p52n'))
    ], [
      // fixed point with P-1-X decimals
      setV('p52d', SUB(SUB(VAR('p52p'), num(1)), VAR('p52e'))),
      IF(LT(VAR('p52d'), num(0)), [setV('p52d', num(0))]),
      callProc('pctitem %s %s %s %s', [argOf('vv'), argOf('vt'), J(txt('.'), VAR('p52d')), txt('f')]),
      callProc('gstrip %s', [VAR('ev')])
    ])
  ]);
  console.log('[P152] pctg registered');

  // ---------- (c) pctitem: the `%` and `g` branches, and `b` inside the hex branch
  const pi = inDef('pctitem %s %s %s %s');
  const byLits = (lits) => find(pi, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const got = new Set();
      for (const x of reach(b.inputs.CONDITION[1])) {
        for (const v of Object.values(BL()[x].inputs || {})) if (v && Array.isArray(v[1]) && v[1][0] === 10) got.add(String(v[1][1]));
      }
      return lits.every((l) => got.has(l));
    })());
  const fBranch = byLits(['f', 'F']);
  if (fBranch.length !== 1) throw new Error('[P152] pctitem f branch = ' + fBranch.length);
  const hexBranch = byLits(['o', 'X', 'x']);
  if (hexBranch.length !== 1) throw new Error('[P152] pctitem hex branch = ' + hexBranch.length);

  // --- the two recursive conversions share the flag save/restore
  const saveFlags = () => [
    setV('p52w', VAR('pwid')), setV('p52l', VAR('pleft')), setV('p52z', VAR('p15z')),
    setV('p52a', VAR('p15pl')), setV('p52b', VAR('p15s'))
  ];
  const restoreFlags = () => [
    setV('pwid', VAR('p52w')), setV('pleft', VAR('p52l')), setV('p15z', VAR('p52z')),
    setV('p15pl', VAR('p52a')), setV('p15s', VAR('p52b'))
  ];
  insertBeforeStmt(fBranch[0], [
    // `%` -- percent: value * 100 formatted as a float, then the sign
    IF(EQ(argOf('conv'), txt('%')), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: must be real number, not str'))]),
      IF(EQ(VAR('phas'), num(0)), [setV('ppr', num(6))]),
      setV('p52f', txt('')),
      IF(EQ(VAR('p15pl'), num(1)), [setV('p52f', txt('+'))]),
      IF(AND(EQ(VAR('p15pl'), num(0)), EQ(VAR('p15s'), num(1))), [setV('p52f', txt(' '))]),
      ...saveFlags(),
      callProc('pctitem %s %s %s %s', [MUL(argOf('vv'), num(100)), argOf('vt'), J(txt('.'), VAR('ppr')), txt('f')]),
      ...restoreFlags(),
      setV('ptx', J(VAR('ev'), txt('%'))),
      setV('pok', num(1))
    ]),
    // `g`/`G` -- general format
    IF(OR(EQ(argOf('conv'), txt('g')), EQ(argOf('conv'), txt('G'))), [
      IF(NOT(EQ(argOf('vt'), txt('N'))), [FAIL(txt('TypeError: must be real number, not str'))]),
      ...saveFlags(),
      callProc('pctg %s %s %s', [argOf('vv'), argOf('vt'), argOf('conv')]),
      ...restoreFlags(),
      setV('ptx', VAR('ev')),
      setV('pok', num(1))
    ])
  ]);
  console.log('[P152] pctitem handles % and g/G');

  // --- `b`: the hex branch already picks base and alphabet from p15b/p15t
  {
    const cond = BL()[hexBranch[0]].inputs.CONDITION[1];
    BL()[hexBranch[0]].inputs.CONDITION = B.BOOL(OR(cond, EQ(argOf('conv'), txt('b'))));
    const sub = BL()[hexBranch[0]].inputs.SUBSTACK[1];
    const set16 = find(new Set([...reach(sub)]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'p15b'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '16');
    const set8 = find(new Set([...reach(sub)]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'p15b'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '8');
    const setAlpha = find(new Set([...reach(sub)]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'p15t'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '0123456789abcdef');
    if (set16.length !== 1 || set8.length !== 1 || setAlpha.length !== 1) {
      throw new Error('[P152] hex branch shape = ' + set16.length + '/' + set8.length + '/' + setAlpha.length);
    }
    replaceStmt(set16[0], IFELSE(EQ(argOf('conv'), txt('b')), [setV('p15b', num(2))], [setV('p15b', num(16))]));
    const octIf = find(new Set([...reach(sub)]), (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string' && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'p15b');
    if (octIf.length !== 1) throw new Error('[P152] hex octal if = ' + octIf.length);
    BL()[octIf[0]].inputs.CONDITION = B.BOOL(AND(NOT(EQ(argOf('conv'), txt('b'))), BL()[octIf[0]].inputs.CONDITION[1]));
    replaceStmt(setAlpha[0], IFELSE(EQ(argOf('conv'), txt('b')), [setV('p15t', txt('01'))], [setV('p15t', txt('0123456789abcdef'))]));
    console.log('[P152] pctitem handles b');
  }

  console.log('[P152] g/G, b and % ready');
});

// ---- P153: `'{a!r}'` conversion + `'{a:,}'` grouping (v4.80) ----
//
// Two gaps left in the format spec:
//
//   * `!r` / `!s` (and `!a`) -- CPython converts the value *before* the spec is applied, and the
//     field grammar is `name [ "!" conversion ] [ ":" spec ]`.  `strfmt` only split on `:`, so
//     `'{a!r}'.format(a='xy')` looked up a keyword literally named `a!r` and raised `KeyError: 'a!r'`.
//   * `,` / `_` -- grouping separators.  `fldspec` skipped them, so `'{:,}'.format(1234567)` just
//     printed `1234567`.  CPython allows the separator *before* the width (`,.2f`) or *after* it
//     (`12,.2f`).
//
// `strfmt`'s field scan gets a third state (name -> `!` -> conversion), `flditem` rebuilds its body
// around a value/type pair that the conversion may replace, `fldspec` passes the separator through,
// and `pctitem` picks the separator up in both its flag loop and its width loop and runs the new
// `group` procedure just before the width/zero-fill block (so the padding counts the separators).
patch('P153 format conversion and grouping', () => {
  const J = (a, b) => JOIN(a, b);
  const contains = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NAMES = ['fwv', 'fwt', 'fwcom', 'p53c', 'p53u', 'p53a', 'p53b', 'p53d', 'p53e', 'p53f', 'p53g', 'p53h'];
  for (const n of NAMES) {
    if (taken.has(n)) throw new Error('[P153] variable name taken: ' + n);
    newVar(n, 0);
  }
  const setBody = (defId, ids) => {
    const first = chain(ids);
    BL()[defId].next = first;
    if (first) BL()[first].parent = defId;
    return first;
  };

  // ---------- (a) group: insert the separator every three digits of the integer part
  const gr = newProc('group %s %s', ['s', 'sep']);
  attachBody(gr.defId, [
    setV('p53a', argOf('s')), setV('p53b', txt('')), setV('p53c', txt('')),
    // keep a leading sign out of the grouping
    IF(OR(OR(EQ(letterOf(num(1), VAR('p53a')), txt('-')), EQ(letterOf(num(1), VAR('p53a')), txt('+'))),
      EQ(letterOf(num(1), VAR('p53a')), txt(' '))), [
      setV('p53b', letterOf(num(1), VAR('p53a'))),
      callProc('substr %s %s %s', [VAR('p53a'), num(2), lenOf(VAR('p53a'))]),
      setV('p53a', VAR('ev'))
    ]),
    // the fraction (with its dot) is copied through untouched
    callProc('sfind %s %s', [VAR('p53a'), txt('.')]),
    setV('p53d', VAR('ev')),
    IF(GT(VAR('p53d'), num(0)), [
      callProc('substr %s %s %s', [VAR('p53a'), ADD(VAR('p53d'), num(1)), lenOf(VAR('p53a'))]),
      setV('p53c', VAR('ev')),
      callProc('substr %s %s %s', [VAR('p53a'), num(1), VAR('p53d')]),
      setV('p53a', VAR('ev'))
    ]),
    setV('p53e', txt('')), setV('p53f', lenOf(VAR('p53a'))), setV('p53g', num(1)),
    REPEATU(GT(VAR('p53g'), lenOf(VAR('p53a'))), [
      setV('p53e', J(VAR('p53e'), letterOf(VAR('p53g'), VAR('p53a')))),
      setV('p53h', SUB(VAR('p53f'), VAR('p53g'))),
      IF(AND(GT(VAR('p53h'), num(0)), EQ(MOD(VAR('p53h'), num(3)), num(0))), [
        setV('p53e', J(VAR('p53e'), argOf('sep')))
      ]),
      chgV('p53g', num(1))
    ]),
    setV('ev', J(VAR('p53b'), J(VAR('p53e'), VAR('p53c')))), setV('evtype', txt('S'))
  ]);
  console.log('[P153] group registered');

  // ---------- (b) strfmt: the field text is `name [!conv] [:spec]`
  const sf = inDef('strfmt %s');
  const scanRepeat = find(sf, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_letter_of'));
  if (scanRepeat.length !== 1) throw new Error('[P153] strfmt field scan = ' + scanRepeat.length);
  const chSF = (i) => letterOf(i, argOf('s'));
  setStack(scanRepeat[0], 'SUBSTACK', [
    IFELSE(EQ(VAR('fwspec'), txt('')), [
      IFELSE(EQ(chSF(VAR('sfk')), txt('!')), [
        setV('fwspec', txt('!'))
      ], [
        IFELSE(EQ(chSF(VAR('sfk')), txt(':')), [
          setV('fwspec', txt(':'))
        ], [
          setV('fwname', J(VAR('fwname'), chSF(VAR('sfk')))),
          IF(contains(chSF(VAR('sfk')), '0123456789'), [
            setV('sfnum', ADD(MUL(VAR('sfnum'), num(10)), chSF(VAR('sfk')))),
            setV('sfhas', num(1))
          ])
        ])
      ])
    ], [
      // `!` was just seen: this character is the conversion, anything else is appended as before
      IFELSE(EQ(VAR('fwspec'), txt('!')), [
        setV('fwspec', J(txt('!'), chSF(VAR('sfk'))))
      ], [
        setV('fwspec', J(VAR('fwspec'), chSF(VAR('sfk'))))
      ])
    ]),
    chgV('sfk', num(1))
  ]);
  console.log('[P153] strfmt reads the ! conversion');

  // ---------- (c) flditem: apply the conversion, then the spec (the body is rebuilt wholesale)
  setBody(defIdOf('flditem %s %s'), [
    setV('fwv', argOf('vv')), setV('fwt', argOf('vt')),
    IF(AND(GT(lenOf(VAR('fwspec')), num(1)), EQ(letterOf(num(1), VAR('fwspec')), txt('!'))), [
      IFELSE(EQ(letterOf(num(2), VAR('fwspec')), txt('s')), [
        callProc('strval %s %s', [VAR('fwv'), VAR('fwt')])
      ], [
        // `r` is repr; `a` (ascii) is repr here too -- MiniPy has no ascii()
        callProc('reprval %s %s', [VAR('fwv'), VAR('fwt')])
      ]),
      setV('fwv', VAR('ev')), setV('fwt', VAR('evtype')),
      callProc('substr %s %s %s', [VAR('fwspec'), num(3), lenOf(VAR('fwspec'))]),
      setV('fwspec', VAR('ev'))
    ]),
    IFELSE(GT(lenOf(VAR('fwspec')), num(1)), [
      callProc('substr %s %s %s', [VAR('fwspec'), num(2), lenOf(VAR('fwspec'))]),
      setV('fwtext', VAR('ev')),
      callProc('fldspec %s %s', [VAR('fwtext'), VAR('fwt')]),
      callProc('pctitem %s %s %s %s', [VAR('fwv'), VAR('fwt'), VAR('fwbody'), VAR('fwconv')]),
      setV('fwtext', VAR('ev')),
      IF(AND(EQ(VAR('fwpad'), num(1)), LT(lenOf(VAR('fwtext')), VAR('fwwid'))), [
        setV('fwnp', SUB(VAR('fwwid'), lenOf(VAR('fwtext')))),
        setV('fwsg', txt('')),
        IF(EQ(VAR('fwaln'), txt('E')), [
          IF(OR(OR(EQ(letterOf(num(1), VAR('fwtext')), txt('-')), EQ(letterOf(num(1), VAR('fwtext')), txt('+'))),
            EQ(letterOf(num(1), VAR('fwtext')), txt(' '))), [
            setV('fwsg', letterOf(num(1), VAR('fwtext'))),
            callProc('substr %s %s %s', [VAR('fwtext'), num(2), lenOf(VAR('fwtext'))]),
            setV('fwtext', VAR('ev'))
          ])
        ]),
        setV('fwl', num(0)), setV('fwr', num(0)),
        IFELSE(EQ(VAR('fwaln'), txt('L')), [
          setV('fwr', VAR('fwnp'))
        ], [
          IFELSE(EQ(VAR('fwaln'), txt('C')), [
            setV('fwl', FLOOR(DIV(VAR('fwnp'), num(2)))),
            setV('fwr', SUB(VAR('fwnp'), VAR('fwl')))
          ], [
            setV('fwl', VAR('fwnp'))
          ])
        ]),
        setV('fwpl', txt('')),
        REPEAT(VAR('fwl'), [setV('fwpl', J(VAR('fwpl'), VAR('fwfill')))]),
        setV('fwpr', txt('')),
        REPEAT(VAR('fwr'), [setV('fwpr', J(VAR('fwpr'), VAR('fwfill')))]),
        setV('fwtext', J(VAR('fwsg'), J(J(VAR('fwpl'), VAR('fwtext')), VAR('fwpr'))))
      ]),
      setV('ev', VAR('fwtext')), setV('evtype', txt('S'))
    ], [
      callProc('strval %s %s', [VAR('fwv'), VAR('fwt')])
    ])
  ]);
  console.log('[P153] flditem applies the conversion');

  // ---------- (d) fldspec: keep the grouping separator instead of skipping it
  const fl = inDef('fldspec %s %s');
  {
    const fsIds = fl;
    const widthLoop = find(fsIds, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_contains'
        && JSON.stringify(BL()[x].inputs.STRING1 || {}).includes('0123456789'))
      // the precision loop has the same digit test but no `,`/`_` comparison
      && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'));
    if (widthLoop.length !== 1) throw new Error('[P153] fldspec width loop = ' + widthLoop.length);
    prependStack(widthLoop[0], 'SUBSTACK', chain([
      IF(EQ(letterOf(VAR('fwi'), argOf('fs')), txt(',')), [setV('fwcom', txt(','))]),
      IF(EQ(letterOf(VAR('fwi'), argOf('fs')), txt('_')), [setV('fwcom', txt('_'))])
    ]));
    const initW = find(fsIds, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fwwid'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '0');
    if (initW.length !== 1) throw new Error('[P153] fldspec init = ' + initW.length);
    insertBeforeStmt(initW[0], [setV('fwcom', txt(''))]);
    // both bodies carry the separator (in front of the width, which pctitem parses as flags+digits).
    // `num()`/`txt()` are inlined primitives, not blocks, so the zero-fill body is the one holding an
    // inline *string* `'0'` -- a JSON test for `"0"` also matches the `[4, '0']` shadow every numeric
    // input carries, which is how this was first written (and how it silently filled with zeros).
    const bodies = find(fsIds, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fwbody');
    if (bodies.length !== 2) throw new Error('[P153] fldspec fwbody sites = ' + bodies.length);
    const isZeroBody = (id) => {
      const v = BL()[id].inputs.VALUE;
      if (!v || typeof v[1] !== 'string') return false;
      for (const x of reach(v[1])) {
        for (const iv of Object.values(BL()[x].inputs || {})) {
          if (Array.isArray(iv[1]) && iv[1][0] === 10 && String(iv[1][1]) === '0') return true;
        }
      }
      return false;
    };
    if (bodies.filter(isZeroBody).length !== 1) throw new Error('[P153] fldspec zero body');
    for (const id of bodies) {
      BL()[id].inputs.VALUE = B.REP(isZeroBody(id)
        ? J(VAR('fwsign'), J(txt('0'), J(VAR('fwcom'), J(VAR('fwwid'), VAR('fwprec')))))
        : J(VAR('fwsign'), J(VAR('fwcom'), VAR('fwprec'))), [4, '0']);
    }
    console.log('[P153] fldspec keeps the separator');
  }

  // ---------- (e) pctitem: the grouping flags and the grouping step
  const pi = inDef('pctitem %s %s %s %s');
  {
    // find the flag loop *before* widening its character set
    const loops = find(pi, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_contains'
        && JSON.stringify(BL()[x].inputs.STRING1 || {}).includes('-0+ ')));
    if (loops.length !== 1) throw new Error('[P153] pctitem flag loop = ' + loops.length);
    const flagSet = find(pi, (b) => b.opcode === 'operator_contains'
      && Array.isArray(b.inputs.STRING1) && Array.isArray(b.inputs.STRING1[1]) && b.inputs.STRING1[1][1] === '-0+ ');
    if (flagSet.length !== 1) throw new Error('[P153] pctitem flag set = ' + flagSet.length);
    BL()[flagSet[0]].inputs.STRING1 = [1, [10, '-0+ ,_']];
    const initPl = find(pi, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'p15pl'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][1] === '0');
    if (initPl.length !== 1) throw new Error('[P153] pctitem p15pl init = ' + initPl.length);
    insertBeforeStmt(initPl[0], [setV('p53c', num(0)), setV('p53u', num(0))]);
    // the flag loop's substack ends with `pwi++`; insert the separator checks before it
    {
      const sub = BL()[loops[0]].inputs.SUBSTACK[1];
      let last = sub, g = 0;
      while (BL()[last].next && g++ < 50) last = BL()[last].next;
      if (BL()[last].opcode !== 'data_changevariableby') throw new Error('[P153] flag loop tail');
      insertBeforeStmt(last, [
        IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt(',')), [setV('p53c', num(1))]),
        IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('_')), [setV('p53u', num(1))])
      ]);
    }
    const widthLoops = find(pi, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
        && JSON.stringify(BL()[x].inputs.OPERAND2 || {}).includes('"."')));
    if (widthLoops.length !== 1) throw new Error('[P153] pctitem width loop = ' + widthLoops.length);
    {
      const sub = BL()[widthLoops[0]].inputs.SUBSTACK[1];
      let last = sub, g = 0;
      while (BL()[last].next && g++ < 50) last = BL()[last].next;
      insertBeforeStmt(last, [
        IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt(',')), [setV('p53c', num(1))]),
        IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('_')), [setV('p53u', num(1))])
      ]);
    }
    // grouping runs before the width block, so the padding counts the separators
    const widthIf = find(pi, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'ppad');
    if (widthIf.length !== 1) throw new Error('[P153] pctitem width block = ' + widthIf.length);
    insertBeforeStmt(widthIf[0], [
      IF(OR(EQ(VAR('p53c'), num(1)), EQ(VAR('p53u'), num(1))), [
        IFELSE(EQ(VAR('p53u'), num(1)), [
          callProc('group %s %s', [VAR('ptx'), txt('_')])
        ], [
          callProc('group %s %s', [VAR('ptx'), txt(',')])
        ]),
        setV('ptx', VAR('ev'))
      ])
    ]);
    console.log('[P153] pctitem groups the integer part');
  }

  console.log('[P153] conversion + grouping ready');
});

// ---- P154: `'{a:#x}'` / `#b` / `#o` prefixes + `!r`/`!s` inside f-strings (v4.81) ----
//
// Two leftovers from the last two rounds:
//
//   * `#` -- the alternate form.  `fldspec` skipped the character, so `'{a:#x}'.format(255)`
//     printed `ff`.  The prefix belongs to `pctitem` (which already chooses the base and the digit
//     alphabet), so `#` becomes one more flag: `fldspec` records it in `fwsharp` and puts it in
//     `fwbody`, `pctitem`'s flag loop sets `p54h`, and the hex/octal/binary branch prepends
//     `0x`/`0X`/`0o`/`0b`.  With zero fill the zeros go *after* the prefix (`'{:#010x}'.format(255)`
//     = `0x000000ff`), which the width block cannot know, so that one case pads here and clears
//     `p15z` to keep the width block out of it.
//   * `f'{x!r}'` -- P77's `fstr` splits a field at its top-level `:`, so the `!r` stayed glued to the
//     expression and `eval` choked on it.  `fstr` now scans for a top-level `!` (skipping `!=`)
//     *before* that split, cuts `!conv` out of the field text and remembers the conversion; the
//     spec handed to `flditem` is built as `!conv[:spec]`, which P153's `flditem` already knows how
//     to apply.  A field with a conversion but no spec also has to go through `flditem` (the old
//     routing only did that when `fz2 > 0`).
patch('P154 sharp prefix and fstring conversion', () => {
  const J = (a, b) => JOIN(a, b);
  const contains = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fz7', 'fz8', 'fz9', 'fzbang', 'fwsharp', 'p54h', 'p54p', 'p54z']) {
    if (taken.has(n)) throw new Error('[P154] variable name taken: ' + n);
    newVar(n, 0);
  }
  const replaceChain = (oldId, list) => {
    const head = chain(list);
    const pred = predecessorOf(oldId);
    const nx = BL()[oldId].next;
    if (pred) { BL()[pred].next = head; BL()[head].parent = pred; }
    else {
      const ref = refOf(oldId);
      if (!ref) throw new Error('[P154] cannot place ' + oldId);
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], head, ref.v[2]] : [ref.v[0], head];
      BL()[head].parent = ref.pid;
    }
    let t = head, g = 0;
    while (BL()[t].next && g++ < 200) t = BL()[t].next;
    BL()[t].next = nx; if (nx) BL()[nx].parent = t;
    BL()[oldId].next = null;
    return head;
  };
  const isVarRef = (x, name) => {
    const b = BL()[x];
    return !!b && Object.values(b.inputs || {}).some((v) => Array.isArray(v[1]) && v[1][0] === 12 && v[1][1] === name);
  };
  const condLits = (condId) => {
    const out = new Set();
    for (const x of reach(condId)) {
      for (const v of Object.values(BL()[x].inputs || {})) {
        if (Array.isArray(v[1]) && (v[1][0] === 10 || v[1][0] === 4)) out.add(String(v[1][1]));
      }
    }
    return out;
  };

  // ---------- (a) fstr: cut a top-level `!conv` out of the field text
  const fs = inDef('fstr %s');
  const fz2Init = find(fs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fz2'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
  if (fz2Init.length !== 1) throw new Error('[P154] fstr fz2 init = ' + fz2Init.length);
  insertBeforeStmt(fz2Init[0], [
    setV('fz7', num(0)), setV('fz9', txt('')), setV('fz5', num(0)), setV('fz8', num(1)),
    REPEATU(GT(VAR('fz8'), lenOf(VAR('fexpr'))), [
      IF(contains(letterOf(VAR('fz8'), VAR('fexpr')), '([{'), [chgV('fz5', num(1))]),
      IF(contains(letterOf(VAR('fz8'), VAR('fexpr')), ')]}'), [chgV('fz5', num(-1))]),
      IF(AND(EQ(VAR('fz5'), num(0)), AND(EQ(letterOf(VAR('fz8'), VAR('fexpr')), txt('!')), EQ(VAR('fz7'), num(0)))), [
        // `!=` is a comparison, not a conversion
        IF(NOT(EQ(letterOf(ADD(VAR('fz8'), num(1)), VAR('fexpr')), txt('='))), [setV('fz7', VAR('fz8'))])
      ]),
      chgV('fz8', num(1))
    ]),
    IF(GT(VAR('fz7'), num(0)), [
      setV('fz9', letterOf(ADD(VAR('fz7'), num(1)), VAR('fexpr'))),
      // keep whatever follows (usually `:spec`), so the existing `:` split still works
      callProc('substr %s %s %s', [VAR('fexpr'), ADD(VAR('fz7'), num(2)), lenOf(VAR('fexpr'))]),
      setV('fz8', VAR('ev')),
      callProc('substr %s %s %s', [VAR('fexpr'), num(1), SUB(VAR('fz7'), num(1))]),
      setV('fexpr', J(VAR('ev'), VAR('fz8')))
    ])
  ]);
  // the spec handed to flditem becomes `!conv[:spec]`
  const fsSet = find(fs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fwspec'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
    && [...reach(b.inputs.VALUE[1])].some((x) => isVarRef(x, 'fz3')));
  if (fsSet.length !== 1) throw new Error('[P154] fstr fwspec set = ' + fsSet.length);
  insertBeforeStmt(fsSet[0], [
    setV('fzbang', txt('')),
    IF(NOT(EQ(VAR('fz9'), txt(''))), [setV('fzbang', J(txt('!'), VAR('fz9')))])
  ]);
  BL()[fsSet[0]].inputs.VALUE = B.REP(J(VAR('fzbang'), J(txt(':'), J(VAR('fz3'), VAR('fz4')))), [4, '0']);
  // a conversion without a spec must go through flditem too
  const routeIf = find(fs, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_gt'
    && isVarRef(b.inputs.CONDITION[1], 'fz2'));
  if (routeIf.length !== 1) throw new Error('[P154] fstr route = ' + routeIf.length);
  BL()[routeIf[0]].inputs.CONDITION = B.BOOL(OR(BL()[routeIf[0]].inputs.CONDITION[1], NOT(EQ(VAR('fz9'), txt('')))));
  console.log('[P154] f-strings accept !r / !s');

  // ---------- (b) fldspec: record `#` and carry it in the pctitem spec
  const fl = inDef('fldspec %s %s');
  const sharpIf = find(fl, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && Array.isArray(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1]) && String(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1]) === '#');
  if (sharpIf.length !== 1) throw new Error('[P154] fldspec sharp if = ' + sharpIf.length);
  setStack(sharpIf[0], 'SUBSTACK', [setV('fwsharp', txt('#')), chgV('fwi', num(1))]);
  const initW = find(fl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fwwid'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
  if (initW.length !== 1) throw new Error('[P154] fldspec init = ' + initW.length);
  insertBeforeStmt(initW[0], [setV('fwsharp', txt(''))]);
  {
    const bodies = find(fl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fwbody');
    if (bodies.length !== 2) throw new Error('[P154] fldspec fwbody = ' + bodies.length);
    const isZeroBody = (id) => {
      const v = BL()[id].inputs.VALUE;
      if (!v || typeof v[1] !== 'string') return false;
      for (const x of reach(v[1])) {
        for (const iv of Object.values(BL()[x].inputs || {})) {
          if (Array.isArray(iv[1]) && iv[1][0] === 10 && String(iv[1][1]) === '0') return true;
        }
      }
      return false;
    };
    if (bodies.filter(isZeroBody).length !== 1) throw new Error('[P154] fldspec zero body');
    for (const id of bodies) {
      BL()[id].inputs.VALUE = B.REP(isZeroBody(id)
        ? J(VAR('fwsign'), J(txt('0'), J(VAR('fwcom'), J(VAR('fwsharp'), J(VAR('fwwid'), VAR('fwprec'))))))
        : J(VAR('fwsign'), J(VAR('fwcom'), J(VAR('fwsharp'), VAR('fwprec')))), [4, '0']);
    }
  }
  console.log('[P154] fldspec keeps #');

  // ---------- (c) pctitem: the `#` flag and the prefix in the hex/octal/binary branch
  const pi = inDef('pctitem %s %s %s %s');
  const flagSet = find(pi, (b) => b.opcode === 'operator_contains'
    && Array.isArray(b.inputs.STRING1) && Array.isArray(b.inputs.STRING1[1]) && String(b.inputs.STRING1[1][1]) === '-0+ ,_');
  if (flagSet.length !== 1) throw new Error('[P154] pctitem flag set = ' + flagSet.length);
  BL()[flagSet[0]].inputs.STRING1 = [1, [10, '-0+ ,_#']];
  const initPl = find(pi, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'p15pl'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
  if (initPl.length !== 1) throw new Error('[P154] pctitem init = ' + initPl.length);
  insertBeforeStmt(initPl[0], [setV('p54h', num(0))]);
  {
    const loops = find(pi, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_contains'
        && JSON.stringify(BL()[x].inputs.STRING1 || {}).includes('-0+ ')));
    if (loops.length !== 1) throw new Error('[P154] pctitem flag loop = ' + loops.length);
    const sub = BL()[loops[0]].inputs.SUBSTACK[1];
    let last = sub, g = 0;
    while (BL()[last].next && g++ < 60) last = BL()[last].next;
    insertBeforeStmt(last, [
      IF(EQ(letterOf(VAR('pwi'), argOf('spec')), txt('#')), [setV('p54h', num(1))])
    ]);
  }
  {
    const hexIf = find(pi, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && ['o', 'X', 'x'].every((l) => condLits(b.inputs.CONDITION[1]).has(l)));
    if (hexIf.length !== 1) throw new Error('[P154] pctitem hex branch = ' + hexIf.length);
    // `'{:b}'.format(1.5)` used to floor the value and print `1` -- the conversion needs an integer
    {
      const typeCheck = find(new Set([...reach(BL()[hexIf[0]].inputs.SUBSTACK[1])]), (b) => b.opcode === 'control_if'
        && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
        && BL()[b.inputs.CONDITION[1]].opcode === 'operator_not'
        && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
        && JSON.stringify([...reach(b.inputs.SUBSTACK[1])].map((i) => BL()[i].inputs || {})).includes('%x format'));
      if (typeCheck.length !== 1) throw new Error('[P154] pctitem hex type check = ' + typeCheck.length);
      BL()[typeCheck[0]].inputs.CONDITION = B.BOOL(OR(BL()[typeCheck[0]].inputs.CONDITION[1],
        NOT(EQ(FLOOR(argOf('vv')), argOf('vv')))));
    }
    const hexSub = reach(BL()[hexIf[0]].inputs.SUBSTACK[1]);
    const tail = find(new Set([...hexSub]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ptx'
      && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
      && [...reach(b.inputs.VALUE[1])].some((x) => isVarRef(x, 'p15x')));
    if (tail.length !== 1) throw new Error('[P154] pctitem hex tail = ' + tail.length);
    replaceChain(tail[0], [
      setV('p54p', txt('')),
      IF(EQ(VAR('p54h'), num(1)), [
        callProc('compareText %s %s', [argOf('conv'), txt('X')]),
        IFELSE(EQ(VAR('cmp'), num(0)), [setV('p54p', txt('0X'))], [
          IFELSE(EQ(argOf('conv'), txt('o')), [setV('p54p', txt('0o'))], [
            IFELSE(EQ(argOf('conv'), txt('b')), [setV('p54p', txt('0b'))], [setV('p54p', txt('0x'))])
          ])
        ])
      ]),
      // `#` with zero fill puts the zeros after the prefix, which the width block cannot do
      IFELSE(AND(EQ(VAR('p54h'), num(1)), EQ(VAR('p15z'), num(1))), [
        setV('p54z', txt('')),
        REPEAT(SUB(VAR('pwid'), ADD(lenOf(VAR('p15x')), ADD(lenOf(VAR('p54p')), lenOf(VAR('ptx'))))), [
          setV('p54z', J(VAR('p54z'), txt('0')))
        ]),
        setV('ptx', J(VAR('p15x'), J(VAR('p54p'), J(VAR('p54z'), VAR('ptx'))))),
        setV('p15z', num(0))
      ], [
        setV('ptx', J(VAR('p15x'), J(VAR('p54p'), VAR('ptx'))))
      ])
    ]);
  }
  // `'%#x' % 255` -- the `%` spec scan has to accept the flag as well
  {
    const pf = inDef('pctfmt %s %s %s');
    const scanCmp = find(pf, (b) => b.opcode === 'operator_contains' && Array.isArray(b.inputs.STRING1)
      && Array.isArray(b.inputs.STRING1[1]) && String(b.inputs.STRING1[1][1]) === '-+ 0123456789.*');
    if (scanCmp.length !== 1) throw new Error('[P154] pctfmt spec scan = ' + scanCmp.length);
    BL()[scanCmp[0]].inputs.STRING1 = [1, [10, '-+ 0123456789.*#']];
    console.log('[P154] percent specs accept #');
  }
  console.log('[P154] # prefix ready');
});

// ---- P155: `'{a.n}'` / `'{a[1]}'` / `'{0[1]}'` -- attributes and subscripts in format fields (v4.82) ----
//
// CPython's replacement field is `name_or_index ( "." attr | "[" index "]" )* [ "!" conv ] [ ":" spec ]`,
// and the text inside `[...]` is a *literal*: `str.isdigit()` decides whether it is an integer index or
// a string key -- `'{a[k]}'.format(a={'k': 9})` is `a['k']`, and `'{a[i]}'.format(a=[1])` is the
// TypeError `list indices must be integers or slices, not str`.  The bracket is not an expression.
//
// `strfmt` only understood a bare name or index: `'{a.n}'` looked up the keyword `a.n` (`KeyError`) and
// `'{a[1]}'` read the digits as an *explicit positional index* and printed nothing.
//
// The field scan now separates the base from the *path* (from the first top-level `.` or `[`) and
// rewrites each `[...]` component into what the interpreter evaluates: digits stay bare, anything else
// is quoted.  `fpath` then applies the path to the resolved value by handing the job back to the
// interpreter itself:
//
//     assign("__fmt", value, type); tokenize("__fmt" + path); eval(1, len(Tok))
//
// so nesting (`{a.b[0]}`), string keys, negative-index TypeErrors and every message come out exactly as
// they do for the same expression in ordinary code -- there is no second implementation of indexing to
// keep in sync.  The scratch variable is removed again right after the evaluation (MiniPy has no `del`,
// so the four parallel lists are trimmed by hand) to keep the variable panel clean; a program that
// already owns `__fmt` will see it overwritten.
patch('P155 format field paths', () => {
  const J = (a, b) => JOIN(a, b);
  const contains = (x, s) => I('operator_contains', { inputs: { STRING1: B.REP(txt(s), [10, '']), STRING2: B.REP(x, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fwpath', 'fwcon', 'fwbr', 'fwok', 'fwj2']) {
    if (taken.has(n)) throw new Error('[P155] variable name taken: ' + n);
    newVar(n, 0);
  }
  const delAt = (list, idx) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']) } });

  // ---------- (a) fpath: apply an eval-ready path to an already-computed value
  const fp = newProc('fpath %s %s %s', ['vv', 'vt', 'path']);
  attachBody(fp.defId, [
    callProc('assign %s %s %s', [txt('__fmt'), argOf('vv'), argOf('vt')]),
    callProc('tokenize %s', [J(txt('__fmt'), argOf('path'))]),
    callProc('eval %s %s', [num(1), llen('Tok')]),
    // look the scratch name up *after* the eval (eval moves `found` around) and drop it again
    callProc('lookup %s', [txt('__fmt')]),
    IF(GT(VAR('found'), num(0)), [
      delAt('Names', VAR('found')), delAt('Values', VAR('found')),
      delAt('Types', VAR('found')), delAt('Show', VAR('found'))
    ])
  ]);
  console.log('[P155] fpath registered');

  // ---------- (b) strfmt: base + path, with each `[...]` rewritten the way CPython reads it
  const sf = inDef('strfmt %s');
  const scanRepeat = find(sf, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_letter_of'));
  if (scanRepeat.length !== 1) throw new Error('[P155] strfmt field scan = ' + scanRepeat.length);
  const chS = (i) => letterOf(i, argOf('s'));
  setStack(scanRepeat[0], 'SUBSTACK', [
    IFELSE(EQ(VAR('fwspec'), txt('')), [
      IFELSE(EQ(VAR('fwbr'), num(1)), [
        // inside `[...]`: only `]` ends it
        IFELSE(EQ(chS(VAR('sfk')), txt(']')), [
          // all digits -> an integer index, otherwise a string key
          setV('fwok', num(1)),
          IF(EQ(lenOf(VAR('fwcon')), num(0)), [setV('fwok', num(0))]),
          setV('fwj2', num(1)),
          REPEATU(OR(NOT(EQ(VAR('fwok'), num(1))), GT(VAR('fwj2'), lenOf(VAR('fwcon')))), [
            IF(NOT(contains(letterOf(VAR('fwj2'), VAR('fwcon')), '0123456789')), [setV('fwok', num(0))]),
            chgV('fwj2', num(1))
          ]),
          IFELSE(EQ(VAR('fwok'), num(1)), [
            setV('fwpath', J(VAR('fwpath'), J(txt('['), J(VAR('fwcon'), txt(']')))))
          ], [
            setV('fwpath', J(VAR('fwpath'), J(txt("['"), J(VAR('fwcon'), txt("']")))))
          ]),
          setV('fwbr', num(0))
        ], [
          setV('fwcon', J(VAR('fwcon'), chS(VAR('sfk'))))
        ])
      ], [
        IFELSE(OR(EQ(chS(VAR('sfk')), txt('!')), EQ(chS(VAR('sfk')), txt(':'))), [
          IFELSE(EQ(chS(VAR('sfk')), txt('!')), [setV('fwspec', txt('!'))], [setV('fwspec', txt(':'))])
        ], [
          IFELSE(EQ(chS(VAR('sfk')), txt('[')), [
            setV('fwbr', num(1)), setV('fwcon', txt(''))
          ], [
            IFELSE(EQ(chS(VAR('sfk')), txt('.')), [
              // a `.` starts the path; the attribute name itself is copied by the branch below
              setV('fwpath', J(VAR('fwpath'), txt('.')))
            ], [
              IFELSE(NOT(EQ(VAR('fwpath'), txt(''))), [
                setV('fwpath', J(VAR('fwpath'), chS(VAR('sfk'))))
              ], [
                setV('fwname', J(VAR('fwname'), chS(VAR('sfk')))),
                IF(contains(chS(VAR('sfk')), '0123456789'), [
                  setV('sfnum', ADD(MUL(VAR('sfnum'), num(10)), chS(VAR('sfk')))),
                  setV('sfhas', num(1))
                ])
              ])
            ])
          ])
        ])
      ])
    ], [
      IFELSE(EQ(VAR('fwspec'), txt('!')), [
        setV('fwspec', J(txt('!'), chS(VAR('sfk'))))
      ], [
        setV('fwspec', J(VAR('fwspec'), chS(VAR('sfk'))))
      ])
    ]),
    chgV('sfk', num(1))
  ]);
  // reset the path state alongside the name/spec resets of P150/P151
  const sfnumInit = find(sf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'sfnum'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
  if (sfnumInit.length !== 1) throw new Error('[P155] strfmt sfnum init = ' + sfnumInit.length);
  insertBeforeStmt(sfnumInit[0], [setV('fwpath', txt('')), setV('fwcon', txt('')), setV('fwbr', num(0))]);
  // both substitution branches resolve the path before formatting
  const items = find(sf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'flditem %s %s');
  if (items.length !== 2) throw new Error('[P155] strfmt flditem sites = ' + items.length);
  for (const id of items) {
    insertBeforeStmt(id, [
      IF(NOT(EQ(VAR('fwpath'), txt(''))), [
        callProc('fpath %s %s %s', [VAR('sfn'), VAR('sft'), VAR('fwpath')]),
        setV('sfn', VAR('ev')), setV('sft', VAR('evtype'))
      ])
    ]);
  }
  console.log('[P155] strfmt applies the field path');

  // ---------- (c) `{`/`}` must count as brackets in the format argument scan.  Both P82's comma split
  // and P150's `fmtarg` only tracked `(`/`[`, so a dict literal argument had its commas taken for
  // argument separators: `'{a[k]} {a[j]}'.format(a={'k': 1, 'j': 2})` died with `SyntaxError: parentheses`.
  {
    const braceDepth = (set, tokVar, open) => {
      const pair = open ? ['(', '['] : [')', ']'];
      const ch = open ? '{' : '}';
      const hit = find(set, (b) => {
        if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
        const root = BL()[b.inputs.CONDITION[1]];
        if (root.opcode !== 'operator_or') return false;
        const eqs = Object.values(root.inputs || {}).map((v) => (v && typeof v[1] === 'string') ? BL()[v[1]] : null).filter(Boolean);
        if (eqs.length !== 2 || eqs.some((e) => e.opcode !== 'operator_equals')) return false;
        const lits = eqs.map((e) => {
          const d = e.inputs.OPERAND2;
          return (d && Array.isArray(d[1]) && d[1][0] === 10) ? String(d[1][1]) : null;
        });
        const vars = eqs.map((e) => {
          const d = e.inputs.OPERAND1;
          return (d && Array.isArray(d[1]) && d[1][0] === 12) ? String(d[1][1]) : null;
        });
        return pair.every((l) => lits.includes(l)) && vars.every((v) => v === tokVar);
      });
      if (hit.length !== 1) throw new Error('[P155] brace depth site (' + ch + ') = ' + hit.length);
      BL()[hit[0]].inputs.CONDITION = B.BOOL(OR(BL()[hit[0]].inputs.CONDITION[1], EQ(VAR(tokVar), txt(ch))));
    };
    const mcSet = inDef('methodcall %s %s');
    braceDepth(mcSet, 'sfq', true);
    braceDepth(mcSet, 'sfq', false);
    const faSet = inDef('fmtarg %s %s');
    braceDepth(faSet, 'fwq', true);
    braceDepth(faSet, 'fwq', false);
    console.log('[P155] format argument scans track braces');
  }

  console.log('[P155] field paths ready');
});

// ---- P156: CPython's wording for format errors + the missing-field errors (v4.83) ----
//
// Two kinds of "wrong words" were left:
//
//   * `.format` type errors reused the `%` wording.  `'{:d}'.format('x')` said
//     `TypeError: %d format: a number is required` where CPython says
//     `ValueError: Unknown format code 'd' for object of type 'str'`.  `pctitem` is shared by `%`,
//     f-strings and `.format`, so a `pcsrc` flag (1 = format, 0 = percent) is set by the two entry
//     points (`flditem`, `pctfmt`) and each type check picks its wording.  The type name comes from
//     the existing `tname` procedure (P144).
//   * the field errors were silent.  `'{} {}'.format(1)` printed `1 ` and `'{0}'.format(a=1)`
//     printed nothing; CPython raises
//     `IndexError: Replacement index 1 out of range for positional args tuple`, and mixing automatic
//     and explicit numbering (`'{} {0}'.format(1, 2)`) raises
//     `ValueError: cannot switch from automatic field numbering to manual field specification`.
//     `strfmt` now tracks the mode in `fwm` (named fields do not take part) and fails out of range
//     instead of dropping the substitution.
patch('P156 format error wording', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['pcsrc', 'fwm']) {
    if (taken.has(n)) throw new Error('[P156] variable name taken: ' + n);
    newVar(n, 0);
  }
  const isVarDesc = (d, name) => Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name;

  // ---------- (a) pctitem: the two entry points say where the call came from
  const fl = inDef('flditem %s %s');
  const fpi = find(fl, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'pctitem %s %s %s %s');
  if (fpi.length !== 1) throw new Error('[P156] flditem pctitem site = ' + fpi.length);
  insertBeforeStmt(fpi[0], [setV('pcsrc', num(1))]);
  const pf = inDef('pctfmt %s %s %s');
  const ppi = find(pf, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'pctitem %s %s %s %s');
  if (ppi.length !== 1) throw new Error('[P156] pctfmt pctitem site = ' + ppi.length);
  insertBeforeStmt(ppi[0], [setV('pcsrc', num(0))]);
  console.log('[P156] pctitem knows its caller');

  // ---------- (b) the type checks: `%` wording for percent, `ValueError: Unknown format code` for format
  const pi = inDef('pctitem %s %s %s %s');
  const failText = (b) => {
    if (!b || b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return null;
    const v = Object.values(b.inputs || {})[0];
    return (v && Array.isArray(v[1]) && v[1][0] === 10) ? String(v[1][1]) : null;
  };
  const TEXTS = [
    'TypeError: %d format: a number is required',
    'TypeError: must be real number, not str',
    'TypeError: %x format: an integer is required',
    'TypeError: %c requires int or char'
  ];
  // which CPython message stands in for each site on the `%` side (null = keep MiniPy's text)
  const PCT = {
    'TypeError: %d format: a number is required': 'num',
    'TypeError: must be real number, not str': 'real',
    'TypeError: %x format: an integer is required': 'int',
    'TypeError: %c requires int or char': null
  };
  const textSites = find(pi, (b) => TEXTS.includes(failText(b)));
  if (textSites.length < 5) throw new Error('[P156] pctitem type checks = ' + textSites.length);
  for (const id of textSites) {
    const kind = PCT[failText(BL()[id])];
    const valueErr = [
      setV('p6v', argOf('vv')), setV('p6t', argOf('vt')), callProc('tname', []),
      failMsg(joinAll([
        txt("ValueError: Unknown format code '"), argOf('conv'),
        txt("' for object of type '"), VAR('p6msg'), txt("'")
      ]))
    ];
    const pctErr = kind === null ? [id] : [
      setV('p6v', argOf('vv')), setV('p6t', argOf('vt')), callProc('tname', []),
      failMsg(joinAll(kind === 'real'
        ? [txt('TypeError: must be real number, not '), VAR('p6msg')]
        : [txt('TypeError: %'), argOf('conv'),
           txt(kind === 'num' ? ' format: a real number is required, not ' : ' format: an integer is required, not '),
           VAR('p6msg')]))
    ];
    replaceStmt(id, IFELSE(EQ(VAR('pcsrc'), num(1)), valueErr, pctErr));
  }
  console.log('[P156] ' + textSites.length + ' type checks worded per caller');

  // ---------- (c) strfmt: the missing-field errors
  const sf = inDef('strfmt %s');
  {
    const sfIds = sf;
    // automatic vs explicit numbering is checked by converting the `if sfhas == 0` into an if/else
    const sfhasIf = find(sfIds, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && isVarDesc(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1, 'sfhas')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'sfnum');
    if (sfhasIf.length !== 1) throw new Error('[P156] strfmt sfhas if = ' + sfhasIf.length);
    const autoSub = BL()[sfhasIf[0]].inputs.SUBSTACK[1];
    prependStack(sfhasIf[0], 'SUBSTACK', IF(EQ(VAR('fwm'), txt('M')), [
      failMsg(txt('ValueError: cannot switch from manual field specification to automatic field numbering'))
    ]));
    spliceAfter(autoSub, chain([setV('fwm', txt('A'))]));
    BL()[sfhasIf[0]].opcode = 'control_if_else';
    {
      const manual = chain([
        IF(EQ(VAR('fwm'), txt('A')), [
          failMsg(txt('ValueError: cannot switch from automatic field numbering to manual field specification'))
        ]),
        setV('fwm', txt('M'))
      ]);
      BL()[sfhasIf[0]].inputs.SUBSTACK2 = [2, manual];
      BL()[manual].parent = sfhasIf[0];
    }
    // out of range: the substitution used to be dropped silently
    const emitIf = find(sfIds, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_lt'
      && isVarDesc(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1, 'sfnum')
      && isVarDesc(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2, 'fwpos'));
    if (emitIf.length !== 1) throw new Error('[P156] strfmt emit if = ' + emitIf.length);
    BL()[emitIf[0]].opcode = 'control_if_else';
    {
      const failChain = chain([
        failMsg(joinAll([
          txt('IndexError: Replacement index '), VAR('sfnum'),
          txt(' out of range for positional args tuple')
        ]))
      ]);
      BL()[emitIf[0]].inputs.SUBSTACK2 = [2, failChain];
      BL()[failChain].parent = emitIf[0];
    }
    // the mode is per format call: reset it next to the other scan state
    const mc = inDef('methodcall %s %s');
    const fwposSet = find(mc, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'fwpos'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
    if (fwposSet.length !== 1) throw new Error('[P156] methodcall fwpos init = ' + fwposSet.length);
    insertBeforeStmt(fwposSet[0], [setV('fwm', txt(''))]);
  }
  console.log('[P156] missing-field errors installed');

  console.log('[P156] format error wording ready');
});

// ---- P157: `dict(**d)` unpacking + `sum(d)` over the keys (v4.84) ----
//
// Two items from the "still missing" list:
//
//   * `dict(**d)` -- P148 taught `dict` the `name = value` form, but a `**` piece fell through to the
//     *mapping* branch, which evaluated `**d` whole and died with `SyntaxError: missing expression`.
//     Now the piece is recognised as `** expr`, the expression must be a dict
//     (`TypeError: dict() argument after ** must be a mapping, not int`), its keys are checked against
//     the names already collected (`TypeError: dict() got multiple values for keyword argument 'a'`,
//     which is what CPython raises for `dict(a=1, **{'a': 2})`) and its records are appended **at the
//     piece's position**, so `dict(b=2, **{'a': 1})` keeps CPython's order (b first).
//   * `sum(d)` -- a dict already iterates as its keys (P149), but `sum` was not in that whitelist, so
//     `sum({'a': 1})` said `TypeError: sum() requires a list`.  Adding `sum` makes it sum the keys,
//     which then fails exactly like CPython (`unsupported operand type(s) for +: 'int' and 'str'`)
//     and answers `1` for `sum({1: 2})`.
patch('P157 dict unpack and sum keys', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p18n', 'p18j', 'p18v', 'p18s', 'p18w']) {
    if (taken.has(n)) throw new Error('[P157] variable name taken: ' + n);
    newVar(n, 0);
  }
  const isVarDesc = (d, name) => Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name;
  // a boolean input is [2, blockId]; the comparison lives one level down
  const eqVar = (d, name) => {
    const b = (Array.isArray(d) && typeof d[1] === 'string') ? BL()[d[1]] : null;
    if (!b || b.opcode !== 'operator_equals') return false;
    const o = b.inputs.OPERAND1;
    return Array.isArray(o) && Array.isArray(o[1]) && o[1][0] === 12 && o[1][1] === name;
  };

  // ---------- (a) `**expr` inside dict(...)
  const cf = inDef('callfn %s %s %s');
  const kwIf = find(cf, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK
    && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call'
      && BL()[x].mutation && BL()[x].mutation.proccode === 'kwhas'));
  if (kwIf.length !== 1) throw new Error('[P157] dict keyword if = ' + kwIf.length);
  {
    const oldSub2 = BL()[kwIf[0]].inputs.SUBSTACK2[1];
    const starCond = EQ(tokAt(VAR('p18lo')), txt('**'));
    const merge = [
      callProc('eval %s %s', [ADD(VAR('p18lo'), num(1)), VAR('p18hi')]),
      IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
      IFELSE(EQ(VAR('evtype'), txt('D')), [
        setV('p18v', VAR('ev')),
        // every key must be new, and it joins the name list so a later keyword clash is caught too
        callProc('dictkeys %s', [VAR('p18v')]),
        setV('p18w', VAR('ev')),
        callProc('listlen %s', [VAR('p18w')]),
        setV('p18n', VAR('ev')),
        setV('p18j', num(1)),
        REPEATU(GT(VAR('p18j'), VAR('p18n')), [
          callProc('listitem %s %s', [VAR('p18w'), VAR('p18j')]),
          setV('p18k', VAR('ev')),
          callProc('kwhas', []),
          IF(EQ(VAR('p18h'), num(1)), [
            failMsg(joinAll([txt("TypeError: dict() got multiple values for keyword argument '"), VAR('p18k'), txt("'")]))
          ]),
          addTo('DKwN', VAR('p18k')),
          chgV('p18j', num(1))
        ]),
        setV('d14acc', J(VAR('d14acc'), VAR('p18v')))
      ], [
        setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
        failMsg(joinAll([txt('TypeError: dict() argument after ** must be a mapping, not '), VAR('p6msg')]))
      ])
    ];
    BL()[kwIf[0]].inputs.SUBSTACK2 = [2, IFELSE(starCond, merge, [oldSub2])];
    BL()[BL()[kwIf[0]].inputs.SUBSTACK2[1]].parent = kwIf[0];
    console.log('[P157] dict(**d) merges');
  }

  // ---------- (b) `sum(d)` sums the keys, like every other iterating builtin
  const iterIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_and'
    && eqVar(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1, 'evtype')
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
    && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'dictkeys %s');
  if (iterIf.length !== 1) throw new Error('[P157] callfn dict iteration = ' + iterIf.length);
  {
    const cond = BL()[iterIf[0]].inputs.CONDITION[1];
    BL()[cond].inputs.OPERAND2 = B.BOOL(OR(BL()[cond].inputs.OPERAND2[1], EQ(argOf('fn'), txt('sum'))));
    console.log('[P157] sum() accepts a dict');
  }

  // ---------- (c) the `**` piece has to reach that handler at all: P148 only entered it for a
  // top-level `=`, and a piece list without `=` went straight to the "expected at most 1 argument"
  // error (`dict(**d)`, `dict(**d, **e)`).  The scan learns one more flag, `p18s`, set alongside
  // the `=` detector that P148's `scanSpan` emits inside the `if fn == 'dict'` branch.
  {
    const condHasLit = (id, ch) => {
      for (const x of reach(id)) {
        for (const v of Object.values(BL()[x].inputs || {})) {
          if (Array.isArray(v[1]) && v[1][0] === 10 && String(v[1][1]) === ch) return true;
        }
      }
      return false;
    };
    const dictIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && condHasLit(b.inputs.CONDITION[1], 'dict')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call'
        && BL()[x].mutation && BL()[x].mutation.proccode === 'kwhas'));
    if (dictIf.length !== 1) throw new Error('[P157] dict branch = ' + dictIf.length);
    const scope = new Set([...reach(BL()[dictIf[0]].inputs.SUBSTACK[1])]);
    const initE = find(scope, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'p18e'
      && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
    if (initE.length !== 1) throw new Error('[P157] p18e init = ' + initE.length);
    insertBeforeStmt(initE[0], [setV('p18s', num(0))]);
    const eqIf = find(scope, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && condHasLit(b.inputs.CONDITION[1], '=')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'p18e');
    if (eqIf.length !== 1) throw new Error('[P157] p18e scan if = ' + eqIf.length);
    insertBeforeStmt(eqIf[0], [
      IF(AND(EQ(VAR('p18d'), num(0)), EQ(tokAt(VAR('p18lo')), txt('**'))), [
        setV('p18s', num(1))
      ])
    ]);
    // the handler (and the "several pieces" error) must look at `p18s` as well
    const entryIf = find(cf, (b) => b.opcode === 'control_if' && eqVar(b.inputs.CONDITION, 'p18e'));
    if (entryIf.length !== 1) throw new Error('[P157] entry if = ' + entryIf.length);
    BL()[entryIf[0]].inputs.CONDITION = B.BOOL(OR(BL()[entryIf[0]].inputs.CONDITION[1], EQ(VAR('p18s'), num(1))));
    const manyIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_and'
      && eqVar(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1, 'p18e')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && JSON.stringify([...reach(b.inputs.SUBSTACK[1])].map((i) => BL()[i].inputs || {})).includes('at most 1 argument'));
    if (manyIf.length !== 1) throw new Error('[P157] many-arg if = ' + manyIf.length);
    BL()[manyIf[0]].inputs.CONDITION = B.BOOL(AND(BL()[manyIf[0]].inputs.CONDITION[1], EQ(VAR('p18s'), num(0))));
    console.log('[P157] the dict handler sees ** pieces');
  }

  console.log('[P157] dict unpack and sum ready');
});

// ---- P158: any space-based indentation width (v4.85) ----
//
// `prepare` counted a line's leading spaces and then *required* that count to be a multiple of four
// (`if not indent % 4 == 0: fail('IndentationError: use 4 spaces')`), so two-space code -- which is
// what a lot of Python in the wild uses -- could not run at all.  Nothing else in the interpreter
// divides or multiplies by four: the count is used purely as a *level* (compared with the previous
// line's, pushed into `Indents`, -1 for blank/comment lines), so dropping that one guard makes any
// consistent spacing work while four-space code keeps behaving exactly as before.
//
// Tabs are still rejected earlier, by `checkASCII`: the valid character set is the sprite's costume
// names (plain ASCII), and a tab has no costume -- that is a separate, deeper limitation.
patch('P158 free indentation', () => {
  const prep = inDef('prepare');
  const failCall = [];
  for (const id of prep) {
    const b = BL()[id];
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') continue;
    for (const v of Object.values(b.inputs || {})) {
      if (v && Array.isArray(v[1]) && v[1][0] === 10 && /use 4 spaces/.test(String(v[1][1]))) failCall.push(id);
    }
  }
  if (failCall.length !== 1) throw new Error('[P158] 4-space fail = ' + failCall.length);
  // the `if not indent % 4 == 0` that guards it
  const guard = find(prep, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_not'
    && (() => {
      const eq = BL()[BL()[b.inputs.CONDITION[1]].inputs.OPERAND[1]];
      if (!eq || eq.opcode !== 'operator_equals') return false;
      const mod = eq.inputs.OPERAND1 && typeof eq.inputs.OPERAND1[1] === 'string' ? BL()[eq.inputs.OPERAND1[1]] : null;
      return !!mod && mod.opcode === 'operator_mod'
        && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string' && reach(b.inputs.SUBSTACK[1]).has(failCall[0]);
    })());
  if (guard.length !== 1) throw new Error('[P158] indent guard = ' + guard.length);
  {
    // the guard is the *first* statement of its substack (the else of the blank/comment test), so it
    // is removed through the parent's slot rather than through a predecessor
    const id = guard[0];
    const pred = predecessorOf(id);
    const nx = BL()[id].next;
    if (pred) { BL()[pred].next = nx; if (nx) BL()[nx].parent = pred; }
    else {
      const ref = refOf(id);
      if (!ref) throw new Error('[P158] cannot drop the guard');
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], null, ref.v[2]] : [ref.v[0], null];
    }
    BL()[id].next = null;
  }
  // a line may also be *deeper* than the previous one only by exactly four (the `indent == previndent + 4`
  // test behind "unexpected indent"): any deeper indent should open the block instead
  {
    const isVarDesc = (d, name) => (Array.isArray(d) && d[0] === 12 && d[1] === name)
      || (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name);
    const plus4 = find(prep, (b) => b.opcode === 'operator_add' && isVarDesc(b.inputs.NUM1, 'previndent')
      && Array.isArray(b.inputs.NUM2[1]) && String(b.inputs.NUM2[1][1]) === '4');
    if (plus4.length !== 1) throw new Error('[P158] previndent + 4 = ' + plus4.length);
    const ref = refOf(plus4[0]);
    if (!ref || BL()[ref.pid].opcode !== 'operator_equals') throw new Error('[P158] previndent + 4 parent');
    replaceExpr(ref.pid, () => GT(VAR('indent'), VAR('previndent')));
    console.log('[P158] any deeper indent opens a block');
  }
  console.log('[P158] indentation width is free (spaces)');
});

// ---- P159: TAB is a legal character, and counts as indentation (v4.86) ----
//
// Two separate walls kept tabs out:
//
//   * `checkASCII` decides whether a character is legal by switching to a costume *named* after it
//     (the target has 95 costumes, one per printable ASCII character) and asking whether the costume
//     number changed.  A tab has no costume, so any line containing one died with
//     `SyntaxError: ASCII text required`.  The guard now lets a tab through as well.
//   * `prepare` counted a line's leading whitespace by skipping spaces only, so a tab-indented line
//     looked flush-left.  The skip accepts tabs too (one unit each, like a space -- `indent` is only
//     ever used as a *level*, so any consistent width works; P158 already removed the "multiple of
//     four" rules).
patch('P159 tabs', () => {
  const TAB = '\t';
  // ---------- (a) checkASCII lets a tab through
  const ca = inDef('checkASCII %s');
  const guard = find(ca, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_and'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && JSON.stringify([...reach(b.inputs.SUBSTACK[1])].map((i) => BL()[i].inputs || {})).includes('ASCII text required'));
  if (guard.length !== 1) throw new Error('[P159] checkASCII guard = ' + guard.length);
  {
    const cond = BL()[guard[0]].inputs.CONDITION[1];
    const old = BL()[cond].inputs.OPERAND2;
    if (!old || typeof old[1] !== 'string') throw new Error('[P159] checkASCII operand2');
    // the same character test the guard already used, plus "not a tab"
    BL()[cond].inputs.OPERAND2 = B.BOOL(AND(old[1], NOT(EQ(letterOf(VAR('ci'), argOf('source')), txt(TAB)))));
  }
  console.log('[P159] checkASCII accepts tabs');

  // ---------- (b) prepare counts a leading tab as indentation
  const prep = inDef('prepare');
  const spaceEq = find(prep, (b) => b.opcode === 'operator_equals'
    && b.inputs.OPERAND2 && Array.isArray(b.inputs.OPERAND2[1]) && String(b.inputs.OPERAND2[1][1]) === ' '
    && b.inputs.OPERAND1 && typeof b.inputs.OPERAND1[1] === 'string'
    && BL()[b.inputs.OPERAND1[1]].opcode === 'operator_letter_of');
  if (spaceEq.length !== 1) throw new Error('[P159] prepare space test = ' + spaceEq.length);
  replaceExpr(spaceEq[0], () => OR(
    EQ(letterOf(VAR('ej'), VAR('es')), txt(' ')),
    EQ(letterOf(VAR('ej'), VAR('es')), txt(TAB))
  ));
  console.log('[P159] leading tabs count as indentation');
  // ---------- (c) tokenize treats a tab as whitespace too (otherwise the tab becomes a token and
  // the line dies with `SyntaxError: expression`, and `prevhead` -- the previous line's first token --
  // stops being `if`/`for`/... which breaks the "unexpected indent" test)
  {
    const tok = inDef('tokenize %s');
    const isVar = (d, name) => (Array.isArray(d) && d[0] === 12 && d[1] === name)
      || (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name);
    const spaceEq = find(tok, (b) => b.opcode === 'operator_equals'
      && b.inputs.OPERAND2 && Array.isArray(b.inputs.OPERAND2[1]) && String(b.inputs.OPERAND2[1][1]) === ' '
      && isVar(b.inputs.OPERAND1, 'ec'));
    if (spaceEq.length !== 1) throw new Error('[P159] tokenize space test = ' + spaceEq.length);
    replaceExpr(spaceEq[0], () => OR(
      EQ(VAR('ec'), txt(' ')),
      EQ(VAR('ec'), txt(TAB))
    ));
    console.log('[P159] the tokenizer skips tabs');
  }

});

// ---- P160: nested replacement fields inside a format spec (v4.87) ----
//
// A format spec is itself a format string: `'{:{w}}'.format(3, w=5)` pads to the *value* of `w`, and
// `'{:{}.{}f}'.format(3.14159, 8, 2)` uses two of them.  Two things stood in the way:
//
//   * `strfmt`'s field scan stopped at the *first* `}` it met, so the field `{:{w}}` was read as
//     `spec = ':{w'` and the trailing `}` was dropped -- nested braces need a depth counter, and only
//     a `}` that closes nothing ends the field.
//   * `flditem` handed the raw spec text to `fldspec`, whose parser skipped `{`/`}`, so the width was
//     lost (`'{:{w}}'` printed `3`).
//
// With the field text intact, the spec is expanded: every `{...}` is resolved like a top-level field
// -- empty means "the next automatic positional index" (sharing the outer field's counter, as CPython
// does), all-digits is an explicit positional index, anything else is a keyword looked up in `FmtK`
// -- and the value is converted with `strval` and spliced into the spec text.  Out-of-range indices
// and unknown names fail with CPython's messages.
patch('P160 nested specs', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  // Scratch's `contains` is "STRING1 contains STRING2"; this helper takes the haystack first
  const hasNeedle = (hay, needle) => I('operator_contains', { inputs: { STRING1: B.REP(hay, [10, '']), STRING2: B.REP(needle, [10, '']) } });
  const isDigit = (ch) => I('operator_contains', { inputs: { STRING1: B.REP(txt('0123456789'), [10, '']), STRING2: B.REP(ch, [10, '']) } });
  const isVarDesc = (d, name) => (Array.isArray(d) && d[0] === 12 && d[1] === name)
    || (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['fwn0', 'fwn1', 'fwn2', 'fwn3', 'fwn4', 'fwn6', 'fwv2', 'fwt2', 'fwspd']) {
    if (taken.has(n)) throw new Error('[P160] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- (a) the field scan counts nested braces so the spec keeps its closing brace
  const sf = inDef('strfmt %s');
  const scanRepeat = find(sf, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_or'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_letter_of'));
  if (scanRepeat.length !== 1) throw new Error('[P160] strfmt field scan = ' + scanRepeat.length);
  const chSF = (i) => letterOf(i, argOf('s'));
  BL()[scanRepeat[0]].inputs.CONDITION = B.BOOL(OR(
    GT(VAR('sfk'), lenOf(argOf('s'))),
    AND(EQ(chSF(VAR('sfk')), txt('}')), EQ(VAR('fwspd'), num(0)))
  ));
  {
    // the spec branch: `fwspec == '!'` is the conversion marker, everything else accumulates
    const bangIf = find(sf, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && isVarDesc(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1, 'fwspec')
      && Array.isArray(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1])
      && String(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2[1][1]) === '!');
    if (bangIf.length !== 1) throw new Error('[P160] strfmt spec branch = ' + bangIf.length);
    setStack(bangIf[0], 'SUBSTACK2', [
      IFELSE(EQ(chSF(VAR('sfk')), txt('{')), [
        chgV('fwspd', num(1)),
        setV('fwspec', J(VAR('fwspec'), chSF(VAR('sfk'))))
      ], [
        IFELSE(EQ(chSF(VAR('sfk')), txt('}')), [
          chgV('fwspd', num(-1)),
          setV('fwspec', J(VAR('fwspec'), chSF(VAR('sfk'))))
        ], [
          setV('fwspec', J(VAR('fwspec'), chSF(VAR('sfk'))))
        ])
      ])
    ]);
  }
  const sfnumInit = find(sf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'sfnum'
    && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && String(b.inputs.VALUE[1][1]) === '0');
  if (sfnumInit.length !== 1) throw new Error('[P160] strfmt sfnum init = ' + sfnumInit.length);
  insertBeforeStmt(sfnumInit[0], [setV('fwspd', num(0))]);
  console.log('[P160] the field scan tracks nested braces');

  // ---------- (b) flditem expands `{...}` in the spec before parsing it
  const fl = inDef('flditem %s %s');
  const specCall = find(fl, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fldspec %s %s');
  if (specCall.length !== 1) throw new Error('[P160] fldspec call = ' + specCall.length);
  const ch = (i) => letterOf(i, VAR('fwtext'));
  const emitNested = [
    callProc('strval %s %s', [VAR('fwv2'), VAR('fwt2')]),
    setV('fwn1', J(VAR('fwn1'), VAR('ev')))
  ];
  insertBeforeStmt(specCall[0], [
    IF(hasNeedle(VAR('fwtext'), txt('{')), [
      setV('fwn1', txt('')), setV('fwn0', num(1)),
      REPEATU(GT(VAR('fwn0'), lenOf(VAR('fwtext'))), [
        IFELSE(EQ(ch(VAR('fwn0')), txt('{')), [
          // ---- a nested field: collect its name, then resolve it like any other field
          setV('fwn2', txt('')),
          chgV('fwn0', num(1)),
          REPEATU(OR(GT(VAR('fwn0'), lenOf(VAR('fwtext'))), OR(EQ(ch(VAR('fwn0')), txt('}')), EQ(ch(VAR('fwn0')), txt('{')))), [
            setV('fwn2', J(VAR('fwn2'), ch(VAR('fwn0')))),
            chgV('fwn0', num(1))
          ]),
          setV('fwn3', num(0)), setV('fwn4', num(0)),
          // "all digits" test (an empty name is the automatic form, handled below)
          IF(NOT(EQ(VAR('fwn2'), txt(''))), [
            setV('fwn4', num(1)),
            setV('fwn6', num(1)),
            REPEATU(OR(NOT(EQ(VAR('fwn4'), num(1))), GT(VAR('fwn6'), lenOf(VAR('fwn2')))), [
              IF(NOT(isDigit(letterOf(VAR('fwn6'), VAR('fwn2')))), [setV('fwn4', num(0))]),
              chgV('fwn6', num(1))
            ])
          ]),
          IFELSE(EQ(VAR('fwn2'), txt('')), [
            // automatic: the next positional slot, shared with the outer fields
            setV('fwn3', ADD(VAR('sfa'), num(1))),
            setV('sfa', ADD(VAR('sfa'), num(1)))
          ], [
            IF(EQ(VAR('fwn4'), num(1)), [
              setV('fwn3', num(0)), setV('fwn6', num(1)),
              REPEATU(GT(VAR('fwn6'), lenOf(VAR('fwn2'))), [
                setV('fwn3', ADD(MUL(VAR('fwn3'), num(10)), letterOf(VAR('fwn6'), VAR('fwn2')))),
                chgV('fwn6', num(1))
              ]),
              setV('fwn3', ADD(VAR('fwn3'), num(1)))
            ])
          ]),
          IFELSE(GT(VAR('fwn3'), num(0)), [
            // positional (automatic or explicit)
            IF(NOT(LT(SUB(VAR('fwn3'), num(1)), VAR('fwpos'))), [
              failMsg(joinAll([
                txt('IndexError: Replacement index '), SUB(VAR('fwn3'), num(1)),
                txt(' out of range for positional args tuple')
              ]))
            ]),
            setV('fwv2', item('FmtV', VAR('fwn3'))), setV('fwt2', item('FmtT', VAR('fwn3'))),
            ...emitNested
          ], [
            // a keyword name: the values sit after the positionals in FmtV
            setV('fwn6', num(1)),
            REPEATU(OR(GT(VAR('fwn6'), llen('FmtK')), GT(VAR('fwn3'), num(0))), [
              IF(EQ(item('FmtK', VAR('fwn6')), VAR('fwn2')), [setV('fwn3', VAR('fwn6'))]),
              chgV('fwn6', num(1))
            ]),
            IFELSE(GT(VAR('fwn3'), num(0)), [
              setV('fwv2', item('FmtV', ADD(VAR('fwpos'), VAR('fwn3')))),
              setV('fwt2', item('FmtT', ADD(VAR('fwpos'), VAR('fwn3')))),
              ...emitNested
            ], [
              failMsg(joinAll([txt("KeyError: '"), VAR('fwn2'), txt("'")]))
            ])
          ]),
          chgV('fwn0', num(1))
        ], [
          setV('fwn1', J(VAR('fwn1'), ch(VAR('fwn0')))),
          chgV('fwn0', num(1))
        ])
      ]),
      setV('fwtext', VAR('fwn1'))
    ])
  ]);
  console.log('[P160] nested specs expanded');
});

// ---- P161: `%c` accepts a one-character string, and says what CPython says (v4.88) ----
//
// CPython's `%c` takes an int *or* a one-character string (`'%c' % 'a'` is `'a'`), and its type error
// is `TypeError: %c requires an int or a unicode character, not str` (MiniPy said
// `%c requires int or char`, which also mis-described a list as "int or char").  For `.format` the
// wording stays `ValueError: Unknown format code 'c' for object of type 'str'` (P156).
//
// The range stays ASCII 32..126: MiniPy's character set *is* the sprite's costume table (printable
// ASCII), so `'%c' % 300` cannot produce U+012C -- CPython can, and that limitation is documented.
//
// IMPORTANT: the `conv == 'c'` branch of `pctitem` is shared by `%` and by `.format` (they differ only
// in the `pcsrc` flag, 1 = format / 0 = percent, see P156).  `.format` already handles an int and must
// keep raising `ValueError: Unknown format code 'c' ...` for a string, so the new one-character path is
// gated on `pcsrc == 0`.
patch('P161 percent c', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const isVarDesc = (d, name) => (Array.isArray(d) && d[0] === 12 && d[1] === name)
    || (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name);
  const litOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) ? String(d[1][1]) : null;
  // conv is a custom-block argument, so its reference is a reporter block, not a variable descriptor
  const isConvRef = (d) => {
    if (isVarDesc(d, 'conv')) return true;
    const b = (Array.isArray(d) && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return !!b && b.opcode === 'argument_reporter_string_number' && b.fields.VALUE && b.fields.VALUE[0] === 'conv';
  };

  const pi = inDef('pctitem %s %s %s %s');
  const cIf = find(pi, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && isConvRef(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1)
    && litOf(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2) === 'c');
  if (cIf.length !== 1) throw new Error('[P161] %c branch = ' + cIf.length);

  // ---------- (a) the %-side wording for the type check
  const failC = find(pi, (b) => {
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') return false;
    const v = Object.values(b.inputs || {})[0];
    return v && Array.isArray(v[1]) && v[1][0] === 10 && /%c requires int or char/.test(String(v[1][1]));
  });
  if (failC.length !== 1) throw new Error('[P161] %c type fail = ' + failC.length);
  {
    // P156 wrapped it as `if pcsrc == 1 then <value error> else <percent error>`
    let wrapper = null;
    for (const pid of pi) {
      const p = BL()[pid];
      if (p.opcode !== 'control_if_else') continue;
      const s2 = p.inputs.SUBSTACK2 && p.inputs.SUBSTACK2[1];
      if (typeof s2 === 'string' && (s2 === failC[0] || reach(s2).has(failC[0]))) { wrapper = pid; break; }
    }
    if (!wrapper) throw new Error('[P161] %c wrapper not found');
    setStack(wrapper, 'SUBSTACK2', [
      setV('p6v', argOf('vv')), setV('p6t', argOf('vt')), callProc('tname', []),
      failMsg(joinAll([txt('TypeError: %c requires an int or a unicode character, not '), VAR('p6msg')]))
    ]);
    console.log('[P161] %c type wording');
  }

  // ---------- (b) a one-character string passes straight through
  {
    const head = BL()[cIf[0]].inputs.SUBSTACK[1];
    const s2 = BL()[head].next;
    const s3 = s2 ? BL()[s2].next : null;
    const items = [head, s2, s3];
    if (items.some((x) => !x)) throw new Error('[P161] %c branch shape');
    const pok = BL()[items[2]].next;
    BL()[items[2]].next = null;
    setStack(cIf[0], 'SUBSTACK', [
      IFELSE(AND(EQ(VAR('pcsrc'), num(0)), AND(EQ(argOf('vt'), txt('S')), EQ(lenOf(argOf('vv')), num(1)))), [
        setV('ptx', argOf('vv'))
      ], items),
      pok
    ]);
    console.log('[P161] %c accepts a single character');
  }
});

// ---- P162: a dict has one record per key (first position, last value), and `==` ignores order ----
//
// CPython's dict literal collapses repeated keys: `{'a': 1, 'a': 2}` is `{'a': 2}`, `len` is 1 and
// `d['a']` is 2 -- MiniPy kept both records (it printed `{'a': 1, 'a': 2}` and `d['a']` was 1).
// `{'a': 1, 'b': 2, 'a': 3}` is `{'a': 3, 'b': 2}`: the *first* position is kept, the *last* value
// wins.  A second gap: two dicts with the same pairs compare unequal when the key order differs,
// because the generic comparison path falls back to comparing the raw record strings.
//
// Three edits:
//
//   * `dlast` (P125) already rebuilt the records of a comprehension "keeping the last record of each
//     key" -- that drops the wrong duplicate: for `{k: 1 for k in ['x', 'y', 'x']}` it dropped the
//     first `x` and kept the last position, so the order came out `y, x` while CPython says `x, y`.
//     Its body is rebuilt to emit *every* key at its first position, taking the value from the last
//     duplicate.  That is the one canonical form, and every construction site now goes through it.
//   * `dictlit` (a `{...}` literal) and the `dict(...)` keyword form (P148/P157) call `dlast` on the
//     run they built.  The keyword form also puts the *mapping* argument first (CPython's position)
//     before the keywords, so `dict(d, a=2)` keeps d's order and the keyword still wins the value.
//   * `veq`/`ceq` compare two values structurally: dicts by key/value (the order must not matter,
//     nested dicts recurse), lists and tuples position by position, strings case-sensitively.
//     `rightside` gets a container `==`/`!=` branch ahead of the generic comparison -- that path
//     compared the raw record strings, which is case-*insensitive* (`['A'] == ['a']` was True) and
//     order-sensitive for dicts.
patch('P162 dict canonical form and equality', () => {
  const J = (a, b) => JOIN(a, b);
  const enc = (acc, tv, vv) => JOIN(JOIN(JOIN(acc, VAR('lsep')), tv), vv);
  const F = (v) => VAR(v);
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });
  const pushVars = (names) => names.map((n) => addTo('VStack', F(n)));
  const popVars = (names) => [...names].reverse().flatMap((n) => [setV(n, item('VStack', llen('VStack'))), delLast('VStack')]);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const CSTATE = ['qcn', 'qcm', 'qci', 'qcj', 'qcs', 'qck', 'qckt', 'qcv', 'qcvt', 'qcv2', 'qcvt2', 'qcok'];
  for (const n of CSTATE) {
    if (taken.has(n)) throw new Error('[P162] variable name taken: ' + n);
    newVar(n, 0);
  }
  // a bare variable reporter serialises as the inline descriptor [12, name, id] inside the input
  const isVarDesc = (d, name) => Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12 && d[1][1] === name;
  // does the subtree read that variable?  (`data_variable` reporters are *inline*, not blocks)
  const mentionsVar = (id, name) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some((v) => {
    if (Array.isArray(v[1]) && v[1][0] === 12 && v[1][1] === name) return true;
    return typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'data_variable'
      && BL()[v[1]].fields.VARIABLE[0] === name;
  }));
  const mentionsLit = (id, ch) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some(
    (v) => Array.isArray(v[1]) && v[1][0] === 10 && String(v[1][1]) === ch));
  // replace the statement span [first..last] with a fresh chain: `replaceStmt` keeps `old.next` but
  // cannot drop the block after it, so two statements need their own helper (same as P150's).
  const replaceSpan = (first, last, ids) => {
    const pred = predecessorOf(first);
    const nx = BL()[last].next;
    const head = chain(ids);
    if (pred) { BL()[pred].next = head; BL()[head].parent = pred; }
    else {
      const ref = refOf(first);
      if (!ref) throw new Error('[P162] cannot place span');
      BL()[ref.pid].inputs[ref.slot] = ref.v.length > 2 ? [ref.v[0], head, ref.v[2]] : [ref.v[0], head];
      BL()[head].parent = ref.pid;
    }
    let tail = head, g = 0;
    while (BL()[tail].next && g++ < 500) tail = BL()[tail].next;
    BL()[tail].next = nx;
    if (nx) BL()[nx].parent = tail;
    BL()[first].next = null;
    BL()[last].next = null;
    return head;
  };

  // ---------- (a) dlast: keep the first position, take the last value
  // Two scans per pair: the first asks whether this key was already emitted (if so the pair is
  // dropped -- that is what collapses the duplicates), the second walks forward to the last pair
  // with the same key and copies its value in.
  attachBody(defIdOf('dlast %s'), [
    callProc('listlen %s', [argOf('d')]), setV('dln', F('ev')),
    setV('dlacc', txt('')), setV('dli', num(1)),
    REPEATU(GT(F('dli'), F('dln')), [
      callProc('listitem %s %s', [argOf('d'), F('dli')]),
      setV('dlk', F('ev')), setV('dlkt', F('evtype')),
      callProc('listitem %s %s', [argOf('d'), ADD(F('dli'), num(1))]),
      setV('dlvv', F('ev')), setV('dlvt', F('evtype')),
      // (1) did an earlier pair already use this key?
      setV('dlf', num(0)), setV('dlj', num(1)),
      REPEATU(OR(GT(F('dlj'), SUB(F('dli'), num(2))), EQ(F('dlf'), num(1))), [
        callProc('listitem %s %s', [argOf('d'), F('dlj')]),
        IF(EQ(F('evtype'), F('dlkt')), [
          IFELSE(EQ(F('dlkt'), txt('S')), [
            callProc('compareText %s %s', [F('ev'), F('dlk')]),
            IF(EQ(F('cmp'), num(0)), [setV('dlf', num(1))])
          ], [
            IF(EQ(F('ev'), F('dlk')), [setV('dlf', num(1))])
          ])
        ]),
        chgV('dlj', num(2))
      ]),
      IF(EQ(F('dlf'), num(0)), [
        // (2) the last duplicate's value wins
        setV('dlf', num(0)), setV('dlj', ADD(F('dli'), num(2))),
        REPEATU(GT(F('dlj'), F('dln')), [
          callProc('listitem %s %s', [argOf('d'), F('dlj')]),
          setV('dlf', num(0)),
          IF(EQ(F('evtype'), F('dlkt')), [
            IFELSE(EQ(F('dlkt'), txt('S')), [
              callProc('compareText %s %s', [F('ev'), F('dlk')]),
              IF(EQ(F('cmp'), num(0)), [setV('dlf', num(1))])
            ], [
              IF(EQ(F('ev'), F('dlk')), [setV('dlf', num(1))])
            ])
          ]),
          IF(EQ(F('dlf'), num(1)), [
            callProc('listitem %s %s', [argOf('d'), ADD(F('dlj'), num(1))]),
            setV('dlvv', F('ev')), setV('dlvt', F('evtype'))
          ]),
          chgV('dlj', num(2))
        ]),
        callProc('lesc %s', [F('dlk')]), setV('dlks', F('ev')),
        callProc('lesc %s', [F('dlvv')]),
        setV('dlacc', enc(F('dlacc'), F('dlkt'), F('dlks'))),
        setV('dlacc', enc(F('dlacc'), F('dlvt'), F('ev')))
      ]),
      chgV('dli', num(2))
    ]),
    setV('ev', F('dlacc')), setV('evtype', txt('D'))
  ]);
  console.log('[P162] dlast keeps the first position and the last value');

  // ---------- (b) veq / ceq: value equality, and container equality
  // `veq va ta vb tb` compares two values: containers recurse into `ceq`, strings are compared
  // case-sensitively (`compareText`), everything else with Scratch's `=` (case-insensitive, but for
  // numbers and booleans that is exactly right).
  // `veq` and `ceq` call each other, so both definitions are created up front (a `callProc` needs
  // the callee to exist) and the bodies are attached afterwards.
  const cq = newProc('ceq %s %s %s %s', ['ca', 'ct', 'cb', 'cu']);
  const vq = newProc('veq %s %s %s %s', ['va', 'ta', 'vb', 'tb']);
  attachBody(vq.defId, [
    setV('qcok', num(0)),
    IF(EQ(argOf('ta'), argOf('tb')), [
      IFELSE(OR(OR(EQ(argOf('ta'), txt('D')), EQ(argOf('ta'), txt('L'))), EQ(argOf('ta'), txt('T'))), [
        // a callee clobbers these globals, so the state is parked on the shared stack
        ...pushVars(CSTATE),
        callProc('ceq %s %s %s %s', [argOf('va'), argOf('ta'), argOf('vb'), argOf('tb')]),
        ...popVars(CSTATE),
        setV('qcok', F('ev'))
      ], [
        IFELSE(EQ(argOf('ta'), txt('S')), [
          callProc('compareText %s %s', [argOf('va'), argOf('vb')]),
          IF(EQ(F('cmp'), num(0)), [setV('qcok', num(1))])
        ], [
          IF(EQ(argOf('va'), argOf('vb')), [setV('qcok', num(1))])
        ])
      ])
    ]),
    setV('ev', F('qcok')), setV('evtype', txt('B'))
  ]);
  // `ceq ca ct cb cu`: two containers of the same type -- a dict is a run of key/value pairs (the
  // order must not matter, so every key of a is looked up in b), a list or a tuple is a flat run
  // compared position by position.
  attachBody(cq.defId, [
    callProc('listlen %s', [argOf('ca')]), setV('qcn', F('ev')),
    callProc('listlen %s', [argOf('cb')]), setV('qcm', F('ev')),
    setV('qcok', num(0)),
    IF(EQ(F('qcn'), F('qcm')), [
      setV('qcok', num(1)),
      IFELSE(EQ(argOf('ct'), txt('D')), [
        setV('qci', num(1)),
        REPEATU(OR(GT(F('qci'), F('qcn')), EQ(F('qcok'), num(0))), [
          callProc('listitem %s %s', [argOf('ca'), F('qci')]),
          setV('qck', F('ev')), setV('qckt', F('evtype')),
          callProc('listitem %s %s', [argOf('ca'), ADD(F('qci'), num(1))]),
          setV('qcv', F('ev')), setV('qcvt', F('evtype')),
          // look the key up in b; `cs` keeps the *index* (the loop counter has already moved on)
          setV('qcj', num(1)), setV('qcs', num(0)),
          REPEATU(OR(GT(F('qcj'), F('qcm')), GT(F('qcs'), num(0))), [
            callProc('listitem %s %s', [argOf('cb'), F('qcj')]),
            IF(EQ(F('evtype'), F('qckt')), [
              IFELSE(EQ(F('qckt'), txt('S')), [
                callProc('compareText %s %s', [F('ev'), F('qck')]),
                IF(EQ(F('cmp'), num(0)), [setV('qcs', F('qcj'))])
              ], [
                IF(EQ(F('ev'), F('qck')), [setV('qcs', F('qcj'))])
              ])
            ]),
            chgV('qcj', num(2))
          ]),
          IFELSE(EQ(F('qcs'), num(0)), [
            setV('qcok', num(0))
          ], [
            callProc('listitem %s %s', [argOf('cb'), ADD(F('qcs'), num(1))]),
            setV('qcv2', F('ev')), setV('qcvt2', F('evtype')),
            ...pushVars(CSTATE),
            callProc('veq %s %s %s %s', [F('qcv'), F('qcvt'), F('qcv2'), F('qcvt2')]),
            ...popVars(CSTATE),
            IF(EQ(F('ev'), num(0)), [setV('qcok', num(0))])
          ]),
          chgV('qci', num(2))
        ])
      ], [
        setV('qci', num(1)),
        REPEATU(OR(GT(F('qci'), F('qcn')), EQ(F('qcok'), num(0))), [
          callProc('listitem %s %s', [argOf('ca'), F('qci')]),
          setV('qcv', F('ev')), setV('qcvt', F('evtype')),
          callProc('listitem %s %s', [argOf('cb'), F('qci')]),
          setV('qcv2', F('ev')), setV('qcvt2', F('evtype')),
          ...pushVars(CSTATE),
          callProc('veq %s %s %s %s', [F('qcv'), F('qcvt'), F('qcv2'), F('qcvt2')]),
          ...popVars(CSTATE),
          IF(EQ(F('ev'), num(0)), [setV('qcok', num(0))]),
          chgV('qci', num(1))
        ])
      ])
    ]),
    setV('ev', F('qcok')), setV('evtype', txt('B'))
  ]);
  console.log('[P162] veq/ceq compare values and containers structurally');

  // ---------- (c) rightside: `C == C` / `C != C` for the containers, before the generic comparison
  {
    const rs = inDef('rightside %s %s %s %s %s');
    const genIf = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'evtsave')
      && mentionsLit(b.inputs.CONDITION[1], '!=')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_setvariableto'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'cmp');
    if (genIf.length !== 1) throw new Error('[P162] rightside generic comparison = ' + genIf.length);
    // The generic branch would run right after the hook and overwrite `ev` (it sees lt2 == 'D' but
    // evtype == 'B'), so the container case is cut out of its condition as well.  The test reads
    // `evtsave` (the right operand's type as saved at entry) rather than `evtype`, because the hook
    // itself overwrites `evtype` before the generic condition is evaluated.
    const contCase = () => AND(OR(EQ(argOf('op'), txt('==')), EQ(argOf('op'), txt('!='))),
      AND(EQ(F('lt2'), F('evtsave')),
        OR(OR(EQ(F('lt2'), txt('D')), EQ(F('lt2'), txt('L'))), EQ(F('lt2'), txt('T')))));
    const condId = BL()[genIf[0]].inputs.CONDITION[1];
    const andId = AND(condId, NOT(contCase()));
    BL()[genIf[0]].inputs.CONDITION = B.BOOL(andId);
    if (BL()[condId]) BL()[condId].parent = andId;
    insertBeforeStmt(genIf[0], [
      IF(contCase(), [
        callProc('veq %s %s %s %s', [argOf('leftval'), F('lt2'), F('ev'), F('evtsave')]),
        IF(EQ(argOf('op'), txt('!=')), [setV('ev', SUB(num(1), F('ev')))]),
        setV('evtype', txt('B'))
      ])
    ]);
    console.log('[P162] rightside answers D == D itself');
  }

  // ---------- (d) a `{...}` literal canonicalises its records
  {
    const dl = inDef('dictlit %s %s');
    const evSet = find(dl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'ev'
      && isVarDesc(b.inputs.VALUE, 'dgn'));
    if (evSet.length !== 1) throw new Error('[P162] dictlit ev set = ' + evSet.length);
    const evtSet = BL()[evSet[0]].next;
    if (!evtSet || BL()[evtSet].opcode !== 'data_setvariableto' || BL()[evtSet].fields.VARIABLE[0] !== 'evtype') {
      throw new Error('[P162] dictlit evtype set not found');
    }
    replaceSpan(evSet[0], evtSet, [callProc('dlast %s', [F('dgn')])]);
    console.log('[P162] dict literals are canonical');
  }

  // ---------- (e) `dict(...)`: mapping first (CPython's position), then canonicalise
  // NB the whole span [mapping append .. evtype set] is replaced in one `replaceSpan`: doing it in
  // two steps leaves the orphaned `if` still pointing at the ev set, and `predecessorOf` finds the
  // orphan first, so the new chain ends up hanging off a dead block (and is pruned).
  {
    const cf = inDef('callfn %s %s %s');
    const mapIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'p18d')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].fields && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'd14acc');
    if (mapIf.length !== 1) throw new Error('[P162] callfn mapping append = ' + mapIf.length);
    const evSet = BL()[mapIf[0]].next;
    if (!evSet || BL()[evSet].opcode !== 'data_setvariableto' || BL()[evSet].fields.VARIABLE[0] !== 'ev') {
      throw new Error('[P162] callfn ev set not found');
    }
    const evtSet = BL()[evSet].next;
    if (!evtSet || BL()[evtSet].opcode !== 'data_setvariableto' || BL()[evtSet].fields.VARIABLE[0] !== 'evtype') {
      throw new Error('[P162] callfn evtype set not found');
    }
    replaceSpan(mapIf[0], evtSet, [
      IF(NOT(EQ(F('p18d'), txt(''))), [setV('d14acc', J(F('p18d'), F('d14acc')))]),
      callProc('dlast %s', [F('d14acc')])
    ]);
    console.log('[P162] dict() puts the mapping first and canonicalises');
  }
});

// ---- P163: dictionary views are real values -- d.keys() / d.values() / d.items() (v4.90) ----
//
// `.keys()` used to answer with the *display string* `dict_keys(['a'])`: `print` looked right, but
// `list(d.keys())` split that sentence into single characters, `len` was 19, `for k in d.keys()`
// walked the letters and `sorted(d.keys())` said "sorted() requires a list".
//
// Three new type tags carry the payload instead of the sentence:
//
//   K = dict_keys, V = dict_values, I = dict_items
//
// and in every one of them the value is the plain list encoding (`lsep + type + text` records), so
// the iterating machinery can treat it as an `L` after one assignment.  `strval` is the only place
// that knows the wrapper, which keeps `print(d.keys())` at `dict_keys(['a'])`.
//
// Patched sites: `dictmeth` (answer a view), `strval` (its repr), `tname` and `type()` (their type
// names), `callfn`'s iterable whitelist (`list/tuple/set/sorted/min/max/any/all/sum/enumerate/zip`)
// and its `len` branch, `forloop`, `rightside`'s `in`, and `indexget` (CPython's
// `TypeError: 'dict_keys' object is not subscriptable`).
patch('P163 dict views', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const F = (v) => VAR(v);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const argNameAt = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return b && b.opcode === 'argument_reporter_string_number' ? b.fields.VALUE[0] : null;
  };
  const mentionsVar = (id, name) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some((v) => {
    if (Array.isArray(v[1]) && v[1][0] === 12 && v[1][1] === name) return true;
    return typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'data_variable'
      && BL()[v[1]].fields.VARIABLE[0] === name;
  }));
  const mentionsLit = (id, ch) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some(
    (v) => Array.isArray(v[1]) && v[1][0] === 10 && String(v[1][1]) === ch));
  // NB an argument reporter is always a *block*: `Array.isArray(v[1]) && typeof v[1] === 'string'`
  // is a contradiction (that combination cost one build: the anchor found nothing)
  const mentionsArg = (id, name) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some(
    (v) => typeof v[1] === 'string' && BL()[v[1]]
      && BL()[v[1]].opcode === 'argument_reporter_string_number' && BL()[v[1]].fields.VALUE[0] === name));
  // A reporter block can sit in exactly ONE input: `isView` takes a *thunk* and builds a fresh
  // reporter for each comparison.  (Sharing one `argOf('vt')` across the three tests made every one
  // of them fall back to its shadow `''`, so the whole branch was dead -- the condition looked right
  // in the dump and a separately built probe compared true.)
  const isView = (mk) => OR(OR(EQ(mk(), txt('K')), EQ(mk(), txt('V'))), EQ(mk(), txt('I')));
  const isViewVar = (name) => isView(() => F(name));
  // the statements of one chain (siblings only) -- `find` needs an iterable of ids, not a chain head
  const siblings = (id) => {
    const out = [];
    let s = id;
    while (s && BL()[s]) { out.push(s); s = BL()[s].next; }
    return out;
  };

  // ---------- (a) dictmeth answers a view value instead of a sentence
  {
    const dm = inDef('dictmeth %s %s %s %s %s');
    for (const [meth, enc, tag] of [['keys', 'dictkeys %s', 'K'], ['values', 'dictvals %s', 'V'], ['items', 'dictitems %s', 'I']]) {
      const ifs = find(dm, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
        && typeof b.inputs.CONDITION[1] === 'string' && mentionsLit(b.inputs.CONDITION[1], meth)
        && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
        && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
        && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === enc);
      if (ifs.length !== 1) throw new Error('[P163] dictmeth ' + meth + ' branch = ' + ifs.length);
      setStack(ifs[0], 'SUBSTACK', [callProc(enc, [argOf('rec')]), setV('evtype', txt(tag)), STOPTHIS()]);
    }
    console.log('[P163] dict methods answer K/V/I views');
  }

  // ---------- (b) strval renders the wrapper (print / str still say dict_keys([...]))
  {
    const def = defIdOf('strval %s %s');
    const first = BL()[def].next;
    if (!first) throw new Error('[P163] strval has no body');
    const wrapText = (open) => J(txt(open), J(F('ev'), txt(')')));
    const body = [
      callProc('listfmt %s', [F('ev')]),
      IFELSE(EQ(argOf('vt'), txt('K')), [setV('ev', wrapText('dict_keys('))],
        [IFELSE(EQ(argOf('vt'), txt('V')), [setV('ev', wrapText('dict_values('))],
          [setV('ev', wrapText('dict_items('))])]),
      setV('evtype', txt('S'))
    ];
    const ife = IFELSE(isView(() => argOf('vt')), body, [first]);
    BL()[ife].parent = def;
    BL()[def].next = ife;
    console.log('[P163] strval renders dict view wrappers');
  }

  // ---------- (c) tname knows the three view names
  {
    const def = defIdOf('tname');
    let t = def;
    while (BL()[t].next) t = BL()[t].next;
    spliceAfter(t, chain([
      IF(EQ(F('p6t'), txt('K')), [setV('p6msg', txt('dict_keys'))]),
      IF(EQ(F('p6t'), txt('V')), [setV('p6msg', txt('dict_values'))]),
      IF(EQ(F('p6t'), txt('I')), [setV('p6msg', txt('dict_items'))])
    ]));
    console.log('[P163] tname knows the dict views');
  }

  // ---------- (d) type(): the class form is the one that survives, so the views are filled in just
  // before the branch tags its answer as a string
  {
    const cf = inDef('callfn %s %s %s');
    const typeIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsArg(b.inputs.CONDITION[1], 'fn')
      && mentionsLit(b.inputs.CONDITION[1], 'type'));
    if (typeIf.length !== 1) throw new Error('[P163] callfn type branch = ' + typeIf.length);
    const sub = BL()[typeIf[0]].inputs.SUBSTACK[1];
    const marks = find(siblings(sub), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'evtype'
      && litOf(b.inputs.VALUE) === 'S');
    if (marks.length !== 1) throw new Error('[P163] type() result marker = ' + marks.length);
    insertBeforeStmt(marks[0], [
      IF(EQ(F('evtype'), txt('K')), [setV('ev', txt("<class 'dict_keys'>"))]),
      IF(EQ(F('evtype'), txt('V')), [setV('ev', txt("<class 'dict_values'>"))]),
      IF(EQ(F('evtype'), txt('I')), [setV('ev', txt("<class 'dict_items'>"))]),
      // a set is type 'E' and the chain had no case for it (`type({1})` said `<class 'int'>`)
      IF(EQ(F('evtype'), txt('E')), [setV('ev', txt("<class 'set'>"))])
    ]);
    console.log('[P163] type() names the dict views');
  }

  // ---------- (e) the iterating builtins accept a view (its payload *is* a list)
  {
    const cf = inDef('callfn %s %s %s');
    const iterIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'evtype')
      && mentionsLit(b.inputs.CONDITION[1], 'D')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'dictkeys %s');
    if (iterIf.length !== 1) throw new Error('[P163] callfn iterable branch = ' + iterIf.length);
    const cond = BL()[iterIf[0]].inputs.CONDITION[1];
    const andB = BL()[cond];
    if (andB.opcode !== 'operator_and' || !andB.inputs.OPERAND1 || typeof andB.inputs.OPERAND1[1] !== 'string') {
      throw new Error('[P163] iterable condition shape');
    }
    const typeTest = andB.inputs.OPERAND1[1];
    const extended = OR(typeTest, isViewVar('evtype'));
    andB.inputs.OPERAND1 = B.BOOL(extended);
    if (BL()[typeTest]) BL()[typeTest].parent = extended;
    setStack(iterIf[0], 'SUBSTACK', [
      IFELSE(EQ(F('evtype'), txt('D')), [callProc('dictkeys %s', [F('ev')])], [setV('evtype', txt('L'))])
    ]);
    console.log('[P163] list()/tuple()/sorted()/... accept a view');
  }

  // ---------- (f) len(view)
  {
    const cf = inDef('callfn %s %s %s');
    const lenIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsArg(b.inputs.CONDITION[1], 'fn')
      && mentionsLit(b.inputs.CONDITION[1], 'len'));
    if (lenIf.length !== 1) throw new Error('[P163] callfn len branch = ' + lenIf.length);
    const sub = BL()[lenIf[0]].inputs.SUBSTACK[1];
    const ife = BL()[sub];
    if (!ife || ife.opcode !== 'control_if_else' || typeof ife.inputs.CONDITION[1] !== 'string') {
      throw new Error('[P163] len branch shape');
    }
    const listTest = ife.inputs.CONDITION[1];
    const extended = OR(listTest, isViewVar('evtype'));
    ife.inputs.CONDITION = B.BOOL(extended);
    if (BL()[listTest]) BL()[listTest].parent = extended;
    console.log('[P163] len() counts a view');
  }

  // ---------- (g) forloop: a view iterates like its payload list
  {
    const fl = inDef('forloop');
    const dictIfs = find(fl, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'evtype')
      && mentionsLit(b.inputs.CONDITION[1], 'D')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'dictkeys %s');
    if (dictIfs.length < 1) throw new Error('[P163] forloop dict branches = ' + dictIfs.length);
    for (const id of dictIfs) insertBeforeStmt(id, [IF(isViewVar('evtype'), [setV('evtype', txt('L'))])]);
    console.log('[P163] for x in view (' + dictIfs.length + ' sites)');
  }

  // ---------- (h) `x in view`
  {
    const rs = inDef('rightside %s %s %s %s %s');
    const inIf = find(rs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsArg(b.inputs.CONDITION[1], 'op')
      && mentionsLit(b.inputs.CONDITION[1], 'in') && mentionsLit(b.inputs.CONDITION[1], 'notin'));
    if (inIf.length !== 1) throw new Error('[P163] rightside in branch = ' + inIf.length);
    // the `in` statement is a plain `control_if` whose SUBSTACK is the S/container if/else
    const branch = BL()[inIf[0]].inputs.SUBSTACK[1];
    const dictIfs = find(reach(branch), (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'evtype')
      && mentionsLit(b.inputs.CONDITION[1], 'D')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'dictkeys %s');
    if (dictIfs.length !== 1) throw new Error('[P163] in-branch dict test = ' + dictIfs.length);
    insertBeforeStmt(dictIfs[0], [IF(isViewVar('evtype'), [setV('evtype', txt('L'))])]);
    console.log('[P163] `in` searches a view');
  }

  // ---------- (i) indexget: CPython refuses to subscript a view
  {
    const ig = inDef('indexget %s %s');
    const guard = find(ig, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'xb')
      && mentionsLit(b.inputs.CONDITION[1], 'D')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'fail %s');
    if (guard.length !== 1) throw new Error('[P163] indexget guard = ' + guard.length);
    insertBeforeStmt(guard[0], [
      IF(isViewVar('xb'), [
        setV('p6t', F('xb')), callProc('tname', []),
        callProc('fail %s', [joinAll([txt("TypeError: '"), F('p6msg'), txt("' object is not subscriptable")])])
      ])
    ]);
    console.log('[P163] subscripting a view says so');
  }

  // ---------- (j) zip(): P99's `isIter` test only knew L/T/G/S, so a view source said
  // "zip() needs iterables".  The payload is a list, so accepting the tag is enough.
  {
    const zb = inDef('zipbuild');
    const fails = find(zb, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && BL()[b.inputs.CONDITION[1]].opcode === 'operator_not'
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && mentionsLit(b.inputs.SUBSTACK[1], 'TypeError: zip() needs iterables'));
    if (fails.length !== 2) throw new Error('[P163] zipbuild iterable checks = ' + fails.length);
    for (const id of fails) {
      const notB = BL()[BL()[id].inputs.CONDITION[1]];
      const inner = notB.inputs.OPERAND[1];
      // which variable does the inner test look at?
      let name = null;
      for (const x of reach(inner)) {
        const q = BL()[x];
        if (q.opcode !== 'operator_equals') continue;
        for (const v of [q.inputs.OPERAND1, q.inputs.OPERAND2]) {
          if (Array.isArray(v[1]) && v[1][0] === 12) { name = v[1][1]; break; }
          if (typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'data_variable') { name = BL()[v[1]].fields.VARIABLE[0]; break; }
        }
        if (name) break;
      }
      if (!name) throw new Error('[P163] zipbuild check variable not found');
      const extended = OR(inner, isViewVar(name));
      notB.inputs.OPERAND = B.BOOL(extended);
      if (BL()[inner]) BL()[inner].parent = extended;
    }
    console.log('[P163] zip() accepts a view');
  }
});

// ---- P164: `if [1] == [1]:` -- `==` must not look like an augmented operator (v4.91) ----
//
// A statement that starts with a keyword and whose *second* token is `[` was rewritten as a
// subscript assignment: P95's `name[sub] <op>= rhs` branch checks the token after the closing `]`
// with "it is two characters long and the second one is `=`" -- which is true of `==` (and `!=`,
// `<=`, `>=`).  So
//
//     if [1] == [1]:          ->  read as  if[1] = [1]:   (evaluate `if[1]`, then store)
//     while [1] == [1] and n < 2:
//
// ran `eval(1, auglsp)` -- a span that still contains the `if` keyword -- and died with
// `NameError: name 'if' is not defined`.  (`if xs[0] == 1:` is fine: its second token is not `[`.)
//
// Fix (A): the merged operator must also start with one of `+-*/%`, i.e. be one of `+= -= *= /= %=`
// (`**=`/`//=`/`&= ...` come from the SPLIT branch, which wants a bare `=` after the operator).
// The same test sits in the attribute branch (`c.v == 1` would be rewritten the same way), so both
// sites get it.
//
// Fix (B): a statement keyword that handles its own line must never fall through to the
// "expression statement" fallback; `if`/`while`/`for` were missing from the keyword guard there.
patch('P164 augmented op vs comparison', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const CONT = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const ex = inDef('execute');
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });

  // ---------- (A) `letter(2, tok) == '='` must also mean "the operator starts with +-*/%"
  // The AND is found through its inputs, not through `parent`: during the build a reporter's
  // `parent` is only set when it is chained, so the expression parents are still null here.
  let fixed = 0;
  for (const [id, b] of Object.entries(BL())) {
    if (b.opcode !== 'operator_and') continue;
    for (const slot of ['OPERAND1', 'OPERAND2']) {
      const d = b.inputs[slot];
      if (!d || typeof d[1] !== 'string') continue;
      const eq = BL()[d[1]];
      if (!eq || eq.opcode !== 'operator_equals') continue;
      const sides = [eq.inputs.OPERAND1, eq.inputs.OPERAND2];
      const litSide = sides.find((s) => litOf(s) === '=');
      const exprSide = sides.find((s) => s && typeof s[1] === 'string');
      if (!litSide || !exprSide) continue;
      const lo = BL()[exprSide[1]];
      if (!lo || lo.opcode !== 'operator_letter_of' || litOf(lo.inputs.LETTER) !== '2') continue;
      const strD = lo.inputs.STRING;
      const tokB = (strD && typeof strD[1] === 'string') ? BL()[strD[1]] : null;
      if (!tokB || tokB.opcode !== 'data_itemoflist' || !tokB.fields.LIST || tokB.fields.LIST[0] !== 'Tok') continue;
      // rebuild the very same index expression (a block can sit in only one input)
      const idxDesc = tokB.inputs.INDEX;
      const idxBlk = (idxDesc && typeof idxDesc[1] === 'string') ? BL()[idxDesc[1]] : null;
      let freshIdx;
      if (litOf(idxDesc) !== null) freshIdx = num(Number(litOf(idxDesc)));
      else if (idxBlk && idxBlk.opcode === 'operator_add') freshIdx = ADD(F('auglsp'), num(1));
      else continue;
      const extra = CONT(txt('+-*/%'), letterOf(num(1), tokAt(freshIdx)));
      const oldId = b.inputs[slot][1];
      const wrapped = AND(oldId, extra);
      b.inputs[slot] = B.BOOL(wrapped);
      if (BL()[oldId]) BL()[oldId].parent = wrapped;
      fixed++;
    }
  }
  if (fixed !== 2) throw new Error('[P164] augmented-operator sites = ' + fixed);
  console.log('[P164] `==`/`!=`/`<=`/`>=` are no longer read as augmented operators');

  // ---------- (B) the expression-statement fallback must not touch a keyword statement
  {
    const fIfe = find(ex, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK2
      && typeof b.inputs.SUBSTACK2[1] === 'string'
      && BL()[b.inputs.SUBSTACK2[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK2[1]].mutation && BL()[b.inputs.SUBSTACK2[1]].mutation.proccode === 'eval %s %s'
      && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => litOf(BL()[x].inputs && BL()[x].inputs.OPERAND2) === 'await'));
    if (fIfe.length !== 1) throw new Error('[P164] fallback guard = ' + fIfe.length);
    const tok1 = () => tokAt(num(1));
    const condId = BL()[fIfe[0]].inputs.CONDITION[1];
    const extra = OR(EQ(tok1(), txt('if')), OR(EQ(tok1(), txt('while')), EQ(tok1(), txt('for'))));
    const newCond = OR(condId, extra);
    BL()[fIfe[0]].inputs.CONDITION = B.BOOL(newCond);
    if (BL()[condId]) BL()[condId].parent = newCond;
    console.log('[P164] the expression fallback skips if/while/for');
  }

  // ---------- (C) a `name[...]` statement is only an assignment when `=` really follows the `]`
  // Without this, `a[0] == 1` (a legal, pointless expression statement) fell into indexset, which
  // demands `Tok[auglsp+1] == '='` and failed with `SyntaxError: expected = after ]`.  The scan in
  // (B) of P95 already left `auglsp` at the matching `]`, and an augmented assignment has been
  // rewritten to a plain `=` by then, so one test covers both.
  {
    const idxIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'indexset %s %s'
      && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string');
    if (idxIf.length !== 1) throw new Error('[P164] execute indexset branch = ' + idxIf.length);
    const condId = BL()[idxIf[0]].inputs.CONDITION[1];
    const extra = AND(GT(F('count'), num(3)), EQ(tokAt(ADD(F('auglsp'), num(1))), txt('=')));
    const wrapped = AND(condId, extra);
    BL()[idxIf[0]].inputs.CONDITION = B.BOOL(wrapped);
    if (BL()[condId]) BL()[condId].parent = wrapped;
    console.log('[P164] name[...] is an assignment only with a following =');
  }

  // ---------- (D) `a[0] //= 2` (and `**= &= |= <<= >>=`) never worked: P95 wrote
  // `IF(mergedTest, [merged body], [split body])`, but the patch helper `IF` takes only two
  // arguments -- the split branch was silently dropped, so those operators fell through to
  // indexset and died with `SyntaxError: expected = after ]`.  The missing else is built here.
  {
    const SPLIT = ['**', '//', '<<', '>>', '&', '|', '^'];
    const orChain = (factory, ops) => ops.reduce((acc, o) => acc ? OR(acc, EQ(factory(), txt(o))) : EQ(factory(), txt(o)), null);
    const isTokIdx = (d, idx) => {
      const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      if (!b || b.opcode !== 'data_itemoflist' || !b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
      return litOf(b.inputs.INDEX) === String(idx);
    };
    const mergedIfs = find(ex, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((x) => {
        const q = BL()[x];
        return q && q.opcode === 'operator_equals' && litOf(q.inputs.OPERAND2) === '='
          && (() => {
            const lo = (q.inputs.OPERAND1 && typeof q.inputs.OPERAND1[1] === 'string') ? BL()[q.inputs.OPERAND1[1]] : null;
            return lo && lo.opcode === 'operator_letter_of' && litOf(lo.inputs.LETTER) === '2'
              && isTokIdx(lo.inputs.STRING, 0) === false && !!lo.inputs.STRING;
          })();
      }));
    if (mergedIfs.length !== 1) throw new Error('[P164] merged-operator if = ' + mergedIfs.length);
    const oldSub = BL()[mergedIfs[0]].inputs.SUBSTACK[1];
    const splitBody = [
      IF(AND(orChain(() => tokAt(ADD(F('auglsp'), num(1))), SPLIT), EQ(tokAt(ADD(F('auglsp'), num(2))), txt('='))), [
        setV('augop', tokAt(ADD(F('auglsp'), num(1)))),
        setV('augvs', ADD(F('auglsp'), num(3)))
      ])
    ];
    const ife = I('control_if_else', { inputs: { CONDITION: BL()[mergedIfs[0]].inputs.CONDITION } });
    setStack(ife, 'SUBSTACK', [oldSub]);
    setStack(ife, 'SUBSTACK2', splitBody);
    replaceStmt(mergedIfs[0], ife);
    console.log('[P164] the dropped `**= //= &= |= <<= >>=` branch is back');
  }
});

// ---- P165: `f(*xs)` and `f(**d)` -- unpacking at the call site (v4.92) ----
//
// A call argument must be `name=value` (P100) or an expression; a piece that starts with `*` or
// `**` was handed to eval whole and died with `SyntaxError: missing expression`.
//
// calluser already splits the span on top-level commas (UComma) and evaluates each piece into
// UArgV/UArgT with the keyword name in UArgN, so the fix is one more dispatch in that piece loop:
//
//   *  piece starts with `**` -> evaluate the rest, require a dict, and append every key/value as
//      a *keyword* argument (a non-string key is `TypeError: keywords must be strings`)
//   *  piece starts with `*`  -> evaluate the rest, require an iterable (a dict iterates its keys,
//      a string iterates its characters) and append every element as a *positional* argument
//
// The positional/keyword bookkeeping then just works: "too many arguments" counts the ''-tagged
// entries, keyword binding matches by name, and `**` entries are simply more keywords.
patch('P165 call site unpacking', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const failMsg = (expr) => callProc('fail %s', [expr]);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const mentionsVar = (id, name) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some((v) => {
    if (Array.isArray(v[1]) && v[1][0] === 12 && v[1][1] === name) return true;
    return typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'data_variable'
      && BL()[v[1]].fields.VARIABLE[0] === name;
  }));
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NEW = ['spsrc', 'spsrct', 'spn', 'spi', 'spfn', 'spfound', 'sps'];
  for (const n of NEW) {
    if (taken.has(n)) throw new Error('[P165] variable name taken: ' + n);
    newVar(n, 0);
  }

  const cu = inDef('calluser %s %s %s');
  // P100's dispatch: `name = value` (keyword) vs a plain expression (positional)
  const kwIfe = find(cu, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'fplo')
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_addtolist'
    && BL()[b.inputs.SUBSTACK[1]].fields.LIST[0] === 'UArgN'
    && b.inputs.SUBSTACK2 && typeof b.inputs.SUBSTACK2[1] === 'string');
  if (kwIfe.length !== 1) throw new Error('[P165] calluser piece dispatch = ' + kwIfe.length);
  const oldPos = BL()[kwIfe[0]].inputs.SUBSTACK2[1];

  // P14 collects the piece with two statements *after* the dispatch (`addTo UArgV`, `addTo UArgT`).
  // A splat appends a whole run itself, so those two move into the two single-argument branches.
  const tailVId = BL()[kwIfe[0]].next;
  const tailV = tailVId ? BL()[tailVId] : null;
  const tailTId = tailV ? tailV.next : null;
  const tailT = tailTId ? BL()[tailTId] : null;
  if (!tailV || tailV.opcode !== 'data_addtolist' || tailV.fields.LIST[0] !== 'UArgV') {
    throw new Error('[P165] UArgV append not found: ' + (tailV ? tailV.opcode + '/' + JSON.stringify(tailV.fields) : 'null'));
  }
  if (!tailT || tailT.opcode !== 'data_addtolist' || tailT.fields.LIST[0] !== 'UArgT') {
    throw new Error('[P165] UArgT append not found: ' + (tailT ? tailT.opcode + '/' + JSON.stringify(tailT.fields) : 'null'));
  }
  const afterPair = tailT.next;
  const lastOf = (head) => {
    let s = head, prev = null;
    while (s) { prev = s; s = BL()[s].next; }
    return prev;
  };
  spliceAfter(lastOf(BL()[kwIfe[0]].inputs.SUBSTACK[1]), chain([addTo('UArgV', F('ev')), addTo('UArgT', F('evtype'))]));
  spliceAfter(lastOf(oldPos), chain([addTo('UArgV', F('ev')), addTo('UArgT', F('evtype'))]));
  BL()[kwIfe[0]].next = afterPair;
  if (afterPair) BL()[afterPair].parent = kwIfe[0];
  tailV.next = null;
  tailT.next = null;

  // one element: `*expr`
  const starBody = [
    callProc('eval %s %s', [ADD(F('fplo'), num(1)), F('fphi')]),
    IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
    setV('spsrc', F('ev')), setV('spsrct', F('evtype')),
    IF(EQ(F('spsrct'), txt('D')), [
      callProc('dictkeys %s', [F('spsrc')]),
      setV('spsrc', F('ev')), setV('spsrct', txt('L'))
    ]),
    IFELSE(EQ(F('spsrct'), txt('S')), [
      setV('spn', lenOf(F('spsrc')))
    ], [
      IF(NOT(OR(OR(EQ(F('spsrct'), txt('L')), EQ(F('spsrct'), txt('T'))), OR(EQ(F('spsrct'), txt('G')), EQ(F('spsrct'), txt('E'))))), [
        setV('p6v', F('spsrc')), setV('p6t', F('spsrct')), callProc('tname', []),
        failMsg(joinAll([argOf('fn'), txt('() argument after * must be an iterable, not '), F('p6msg')])),
        STOPTHIS()
      ]),
      callProc('listlen %s', [F('spsrc')]), setV('spn', F('ev'))
    ]),
    setV('spi', num(1)),
    REPEATU(GT(F('spi'), F('spn')), [
      IFELSE(EQ(F('spsrct'), txt('S')), [
        setV('ev', letterOf(F('spi'), F('spsrc'))), setV('evtype', txt('S'))
      ], [
        callProc('listitem %s %s', [F('spsrc'), F('spi')])
      ]),
      addTo('UArgN', txt('')),
      addTo('UArgV', F('ev')), addTo('UArgT', F('evtype')),
      chgV('spi', num(1))
    ])
  ];
  // one element: `**expr` -- `**` is a SINGLE token when it is one, but two `*` tokens otherwise,
  // so the expression start is computed (the trailing `**` shape is what the tokenizer gives)
  const dstarBody = [
    IFELSE(EQ(tokAt(F('fplo')), txt('**')), [setV('sps', ADD(F('fplo'), num(1)))], [setV('sps', ADD(F('fplo'), num(2)))]),
    callProc('eval %s %s', [F('sps'), F('fphi')]),
    IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
    setV('spsrc', F('ev')), setV('spsrct', F('evtype')),
    IFELSE(EQ(F('spsrct'), txt('D')), [
      callProc('listlen %s', [F('spsrc')]), setV('spn', F('ev')),
      setV('spi', num(1)),
      REPEATU(GT(F('spi'), F('spn')), [
        callProc('listitem %s %s', [F('spsrc'), F('spi')]),
        IFELSE(EQ(F('evtype'), txt('S')), [
          addTo('UArgN', F('ev')),
          callProc('listitem %s %s', [F('spsrc'), ADD(F('spi'), num(1))]),
          addTo('UArgV', F('ev')), addTo('UArgT', F('evtype'))
        ], [
          failMsg(txt('TypeError: keywords must be strings')), STOPTHIS()
        ]),
        chgV('spi', num(2))
      ])
    ], [
      setV('p6v', F('spsrc')), setV('p6t', F('spsrct')), callProc('tname', []),
      failMsg(joinAll([argOf('fn'), txt('() argument after ** must be a mapping, not '), F('p6msg')])),
      STOPTHIS()
    ])
  ];
  // `**` may arrive as one token or as two `*` tokens depending on where it sits, so both shapes
  // count (the expression itself always starts two tokens after `**` either way)
  const dstarShape = () => OR(EQ(tokAt(F('fplo')), txt('**')),
    AND(EQ(tokAt(F('fplo')), txt('*')), EQ(tokAt(ADD(F('fplo'), num(1))), txt('*'))));
  const nested = IFELSE(dstarShape(), dstarBody, [
    IFELSE(EQ(tokAt(F('fplo')), txt('*')), starBody, [oldPos])
  ]);
  setStack(kwIfe[0], 'SUBSTACK2', [nested]);
  console.log('[P165] calluser understands *args / **kwargs');

  // ---------- a call with NO top-level comma never reaches calluser's piece loop: eval's fast
  // paths evaluate the single argument first (`f(**d)` died with `SyntaxError: missing
  // expression`).  A hook at the very head of eval catches `NAME ( * ... )` / `NAME ( ** ... )`
  // and hands the raw span to calluser -- but only when NAME really is a user function, so the
  // builtin paths (`dict(**d)`, P157) and every other branch stay untouched.
  {
    const ev = inDef('eval %s %s');
    const first = BL()[defIdOf('eval %s %s')].next;
    if (!first) throw new Error('[P165] eval has no body');
    const argTok = () => tokAt(ADD(argOf('lo'), num(2)));
    const starShape = OR(OR(EQ(argTok(), txt('*')), EQ(argTok(), txt('**'))),
      AND(EQ(argTok(), txt('*')), EQ(tokAt(ADD(argOf('lo'), num(3))), txt('*'))));
    const body = [
      setV('spfn', tokAt(argOf('lo'))), setV('spfound', num(0)), setV('spi', num(1)),
      REPEATU(OR(GT(F('spi'), llen('FnName')), EQ(F('spfound'), num(1))), [
        IF(EQ(item('FnName', F('spi')), F('spfn')), [setV('spfound', num(1))]),
        chgV('spi', num(1))
      ]),
      IF(AND(EQ(F('spfound'), num(1)), AND(starShape, EQ(tokAt(ADD(argOf('lo'), num(1))), txt('(')))), [
        callProc('calluser %s %s %s', [tokAt(argOf('lo')), ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))]),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ];
    insertBeforeStmt(first, body);
    console.log('[P165] a single `*`/`**` argument reaches calluser');
  }

  // ---------- calluser's comma scan only tracked `(`/`[`, so the comma inside a dict literal
  // (`f(1, **{'b': 2})`) split the piece in the wrong place and eval saw `{` alone
  // (`SyntaxError: parentheses`).  `{`/`}` join the depth scan.
  {
    const depthIfs = find(cu, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string' && mentionsVar(b.inputs.CONDITION[1], 'fk')
      && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'data_changevariableby'
      && BL()[b.inputs.SUBSTACK[1]].fields.VARIABLE[0] === 'fd');
    if (depthIfs.length !== 2) throw new Error('[P165] calluser depth scan = ' + depthIfs.length);
    for (const id of depthIfs) {
      const condId = BL()[id].inputs.CONDITION[1];
      const lit = mentionsVar(condId, 'fk') ? null : null;
      // one of them opens (the `(`/`[` one), the other closes; decide by the direction it adds
      const dir = litOf(BL()[BL()[id].inputs.SUBSTACK[1]].inputs.VALUE);
      const add = dir === '1' ? txt('{') : txt('}');
      replaceExpr(condId, () => OR(condId, EQ(tokAt(F('fk')), add)));
    }
    console.log('[P165] calluser counts braces when splitting arguments');
  }
});

// ---- P166: `print(*xs)` -- unpacking in a *builtin* call (v4.93) ----
//
// P165 taught a user function call to unpack (`f(*xs)`), but a builtin is a statement of its own:
// `print` goes through `printargs`, which builds one row in `printbuf` and inserts `psep` between
// arguments.  A `*`-piece was handed to eval whole and died with `SyntaxError: missing expression`.
//
// printargs already splits the argument list on top-level commas (`Comma`) and, for each piece,
// evaluates `plo..phi` and appends the rendered value; the separator before a piece is `pi > 1`
// ("not the first argument", and `pi` is part of the state `fpush` saves, so a nested print inside
// an argument cannot corrupt it).
//
//   * a piece that starts with `*` (but not `**`) evaluates `plo+1..phi`, requires an iterable
//     (a dict iterates its keys, a string its characters) and appends every element.  The *first*
//     element keeps the piece's own `pi > 1` test, every later element always gets the separator.
//     (A separate "have we printed anything?" flag was tried first and broke nested prints:
//     `print(f())` where `f` prints came out as `" 1"`, because that flag is not in fpush's save
//     list -- the print state there is `pi`/`plo`/`phi`/`printbuf`/`psep`/`pstart`/...)
patch('P166 print star unpack', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const mentionsVar = (id, name) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some((v) => {
    if (Array.isArray(v[1]) && v[1][0] === 12 && v[1][1] === name) return true;
    return typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'data_variable'
      && BL()[v[1]].fields.VARIABLE[0] === name;
  }));
  const siblings = (id) => {
    const out = [];
    let s = id;
    while (s && BL()[s]) { out.push(s); s = BL()[s].next; }
    return out;
  };
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['pps', 'ppst', 'ppn', 'ppi']) {
    if (taken.has(n)) throw new Error('[P166] variable name taken: ' + n);
    newVar(n, 0);
  }

  const pa = inDef('printargs');
  const loops = find(pa, (b) => b.opcode === 'control_repeat' && b.inputs.TIMES
    && typeof b.inputs.TIMES[1] === 'string'
    && BL()[b.inputs.TIMES[1]].opcode === 'data_lengthoflist'
    && BL()[b.inputs.TIMES[1]].fields.LIST && BL()[b.inputs.TIMES[1]].fields.LIST[0] === 'Comma'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string');
  if (loops.length !== 1) throw new Error('[P166] printargs argument loop = ' + loops.length);
  const body = BL()[loops[0]].inputs.SUBSTACK[1];
  const pieceIf = BL()[body].next;
  if (!pieceIf || BL()[pieceIf].opcode !== 'control_if') throw new Error('[P166] per-piece if not found');
  const orig = BL()[pieceIf].inputs.SUBSTACK[1];

  // `*expr` as a piece
  const starTest = AND(EQ(tokAt(F('plo')), txt('*')), NOT(EQ(tokAt(ADD(F('plo'), num(1))), txt('*'))));
  const sepSet = () => setV('printbuf', JOIN(F('printbuf'), F('psep')));
  const splat = [
    callProc('eval %s %s', [ADD(F('plo'), num(1)), F('phi')]),
    IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
    setV('pps', F('ev')), setV('ppst', F('evtype')),
    IF(EQ(F('ppst'), txt('D')), [callProc('dictkeys %s', [F('pps')]), setV('pps', F('ev')), setV('ppst', txt('L'))]),
    IFELSE(EQ(F('ppst'), txt('S')), [
      setV('ppn', lenOf(F('pps')))
    ], [
      IF(NOT(OR(OR(EQ(F('ppst'), txt('L')), EQ(F('ppst'), txt('T'))), OR(EQ(F('ppst'), txt('G')), EQ(F('ppst'), txt('E'))))), [
        setV('p6t', F('ppst')), callProc('tname', []),
        callProc('fail %s', [JOIN(txt('TypeError: print() argument after * must be an iterable, not '), F('p6msg'))]),
        STOPTHIS()
      ]),
      callProc('listlen %s', [F('pps')]), setV('ppn', F('ev'))
    ]),
    setV('ppi', num(1)),
    REPEATU(GT(F('ppi'), F('ppn')), [
      IFELSE(EQ(F('ppst'), txt('S')), [
        setV('ev', letterOf(F('ppi'), F('pps'))), setV('evtype', txt('S'))
      ], [
        callProc('listitem %s %s', [F('pps'), F('ppi')])
      ]),
      // the first element is separated exactly like a plain piece (pi is fpush-saved), the rest always are
      IFELSE(EQ(F('ppi'), num(1)), [
        IF(GT(F('pi'), num(1)), [sepSet()])
      ], [
        sepSet()
      ]),
      callProc('strval %s %s', [F('ev'), F('evtype')]),
      setV('printbuf', JOIN(F('printbuf'), F('ev'))),
      chgV('ppi', num(1))
    ])
  ];
  setStack(pieceIf, 'SUBSTACK', [IFELSE(starTest, splat, [orig])]);
  console.log('[P166] print(*xs) works');
});

// ---- P167: more string methods (v4.94) ----
//
// ljust / rjust / center, lstrip / rstrip, swapcase / capitalize, partition / rpartition,
// splitlines, removeprefix / removesuffix, expandtabs, isupper / islower / isspace / isalnum.
//
// The string-method dispatch in `methodcall` is a chain of `if smmeth == "name"` statements followed
// by a guard that lists every known name (P75 added index/title/zfill/isdigit/isalpha that way).
// The arguments are already evaluated by then: `sma1`/`smt1` is the first, and when there is a
// top-level comma (its position is `mcut`) `sma2`/`smt2` is the second.
//
// Case matters: Scratch's `=` and `contains` both ignore case, so comparisons of *content*
// (`substr(v,1,len(p)) == p`, "is this an upper-case letter", the swapcase decision) go through
// `compareText` (which sets `cmp`), and the case tests ask `scase` for the upper/lower form and
// compare with `compareText` instead of testing membership in the alphabet.
patch('P167 more string methods', () => {
  const J = (a, b) => JOIN(a, b);
  const joinAll = (parts) => parts.reduce((a, b) => J(a, b));
  const F = (v) => VAR(v);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const CONT = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const LSEP = () => VAR('lsep');
  const TAB = String.fromCharCode(9);
  const LF = String.fromCharCode(10);
  const CR = String.fromCharCode(13);
  const WS = ' ' + TAB;
  const ALNUM = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] === 'string') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NEW = ['s7fill', 's7pad', 's7k', 's7r', 's7d', 's7l', 's7ti', 's7tj', 's7acc', 's7u', 's7lo', 's7i',
    's7p1', 's7p2', 's7p3', 's7p4', 's7x', 's7j', 's7ok', 's7x1', 's7tacc', 's7tcol', 's7ti2', 's7tc', 's7tk', 's7tw',
    's7lacc', 's7li', 's7ok2', 's7has', 's7ci', 's7cc', 's7cu', 's7cl',
   'd9i', 'd9j', 'd9m', 'd9acc', 'd9k', 'd9kt', 'd9ks', 'd9v', 'd9vt', 'd9n', 'd9f', 'd9c', 'd9p'];
  for (const n of NEW) {
    if (taken.has(n)) throw new Error('[P167] variable name taken: ' + n);
    newVar(n, 0);
  }
  B.addList(IT, 'SSLine', []);
  // call `substr` and keep the result: every one of these helpers ends with ev = <string>
  const keepSub = (v, a, b) => [callProc('substr %s %s %s', [v, a, b])];

  // ---------- (1) spad v w fill mode -> ljust(l) / rjust(r) / center(c)
  {
    const p = newProc('spad %s %s %s %s', ['v', 'w', 'fill', 'mode']);
    const mkPad = (count, into) => [
      setV(into, txt('')), setV('s7k', num(1)),
      REPEATU(GT(F('s7k'), count), [setV(into, J(F(into), argOf('fill'))), chgV('s7k', num(1))])
    ];
    attachBody(p.defId, [
      setV('s7d', SUB(argOf('w'), lenOf(argOf('v')))),
      IF(NOT(GT(argOf('w'), lenOf(argOf('v')))), [
        setV('s7l', num(0)), setV('s7r', num(0))
      ]),
      IF(GT(argOf('w'), lenOf(argOf('v'))), [
        IFELSE(EQ(argOf('mode'), txt('l')), [
          setV('s7l', num(0)), setV('s7r', F('s7d'))
        ], [
          IFELSE(EQ(argOf('mode'), txt('r')), [
            setV('s7l', F('s7d')), setV('s7r', num(0))
          ], [
            // CPython's centre(): the extra character goes *left* when both the margin and the
            // width are odd (marg // 2 + (marg & width & 1))
            setV('s7r', num(0)),
            IF(AND(EQ(MOD(F('s7d'), num(2)), num(1)), EQ(MOD(argOf('w'), num(2)), num(1))), [setV('s7r', num(1))]),
            setV('s7l', ADD(DIV(SUB(F('s7d'), MOD(F('s7d'), num(2))), num(2)), F('s7r'))),
            setV('s7r', SUB(F('s7d'), F('s7l')))
          ])
        ])
      ]),
      ...mkPad(F('s7l'), 's7pad'),
      setV('ev', J(F('s7pad'), argOf('v'))),
      ...mkPad(F('s7r'), 's7pad'),
      setV('ev', J(F('ev'), F('s7pad'))),
      setV('evtype', txt('S'))
    ]);
  }

  // ---------- (2) strim v mode -> lstrip(l) / rstrip(r)
  {
    const p = newProc('strim %s %s', ['v', 'mode']);
    attachBody(p.defId, [
      IFELSE(EQ(argOf('mode'), txt('l')), [
        setV('s7ti', num(1)),
        REPEATU(OR(GT(F('s7ti'), lenOf(argOf('v'))), NOT(CONT(txt(WS), letterOf(F('s7ti'), argOf('v'))))), [chgV('s7ti', num(1))]),
        ...keepSub(argOf('v'), F('s7ti'), lenOf(argOf('v')))
      ], [
        setV('s7tj', lenOf(argOf('v'))),
        REPEATU(OR(LT(F('s7tj'), num(1)), NOT(CONT(txt(WS), letterOf(F('s7tj'), argOf('v'))))), [chgV('s7tj', num(-1))]),
        ...keepSub(argOf('v'), num(1), F('s7tj'))
      ])
    ]);
  }

  // ---------- (3) sfold v mode -> swapcase(sc) / capitalize(ca)
  {
    const p = newProc('sfold %s %s', ['v', 'mode']);
    attachBody(p.defId, [
      setV('s7acc', txt('')),
      IFELSE(EQ(argOf('mode'), txt('ca')), [
        IF(GT(lenOf(argOf('v')), num(0)), [
          callProc('scase %s %s', [letterOf(num(1), argOf('v')), txt('upper')]),
          setV('s7acc', F('ev')),
          IF(GT(lenOf(argOf('v')), num(1)), [
            ...keepSub(argOf('v'), num(2), lenOf(argOf('v'))),
            callProc('scase %s %s', [F('ev'), txt('lower')]),
            setV('s7acc', J(F('s7acc'), F('ev')))
          ])
        ]),
        setV('ev', F('s7acc')), setV('evtype', txt('S'))
      ], [
        setV('s7i', num(1)),
        REPEATU(GT(F('s7i'), lenOf(argOf('v'))), [
          setV('s7lo', letterOf(F('s7i'), argOf('v'))),
          callProc('scase %s %s', [F('s7lo'), txt('upper')]), setV('s7u', F('ev')),
          callProc('scase %s %s', [F('s7lo'), txt('lower')]), setV('s7p1', F('ev')),
          callProc('compareText %s %s', [F('s7lo'), F('s7u')]),
          IFELSE(EQ(F('cmp'), num(0)), [
            setV('s7acc', J(F('s7acc'), F('s7p1')))
          ], [
            callProc('compareText %s %s', [F('s7lo'), F('s7p1')]),
            IFELSE(EQ(F('cmp'), num(0)), [
              setV('s7acc', J(F('s7acc'), F('s7u')))
            ], [
              setV('s7acc', J(F('s7acc'), F('s7lo')))
            ])
          ]),
          chgV('s7i', num(1))
        ]),
        setV('ev', F('s7acc')), setV('evtype', txt('S'))
      ])
    ]);
  }

  // ---------- (4) spart v sep mode -> partition(p) / rpartition(rp), a 3-tuple
  {
    const p = newProc('spart %s %s %s', ['v', 'sep', 'mode']);
    // NB a *top-level* tuple is just its element records with `evtype = "T"`; the
    // `lsep + "T" + <records>` form is for a tuple that is an element of another container
    // (that is what `dictitems` builds).  Wrapping it here made `partition` answer
    // `(('a', '=', 'b'),)` instead of `('a', '=', 'b')`.
    const tuple3 = [
      callProc('lesc %s', [F('s7p1')]), setV('s7p1', F('ev')),
      callProc('lesc %s', [F('s7p2')]), setV('s7p2', F('ev')),
      callProc('lesc %s', [F('s7p3')]), setV('s7p3', F('ev')),
      setV('ev', joinAll([J(J(LSEP(), txt('S')), F('s7p1')), J(J(LSEP(), txt('S')), F('s7p2')), J(J(LSEP(), txt('S')), F('s7p3'))])),
      setV('evtype', txt('T'))
    ];
    attachBody(p.defId, [
      IF(EQ(lenOf(argOf('sep')), num(0)), [
        callProc('fail %s', [txt('ValueError: empty separator')]), STOPTHIS()
      ]),
      IFELSE(EQ(argOf('mode'), txt('rp')), [
        setV('s7ok', num(0)), setV('s7j', SUB(lenOf(argOf('v')), lenOf(argOf('sep')))),
        REPEATU(OR(LT(F('s7j'), num(1)), EQ(F('s7ok'), num(1))), [
          ...keepSub(argOf('v'), F('s7j'), ADD(F('s7j'), SUB(lenOf(argOf('sep')), num(1)))),
          callProc('compareText %s %s', [F('ev'), argOf('sep')]),
          IF(EQ(F('cmp'), num(0)), [setV('s7ok', num(1))]),
          IF(EQ(F('s7ok'), num(0)), [chgV('s7j', num(-1))])
        ])
      ], [
        // first occurrence: scan forward (the same shape as the reverse scan above)
        setV('s7ok', num(0)), setV('s7j', num(1)),
        REPEATU(OR(GT(F('s7j'), SUB(ADD(lenOf(argOf('v')), num(1)), lenOf(argOf('sep')))), EQ(F('s7ok'), num(1))), [
          ...keepSub(argOf('v'), F('s7j'), ADD(F('s7j'), SUB(lenOf(argOf('sep')), num(1)))),
          callProc('compareText %s %s', [F('ev'), argOf('sep')]),
          IF(EQ(F('cmp'), num(0)), [setV('s7ok', num(1))]),
          IF(EQ(F('s7ok'), num(0)), [chgV('s7j', num(1))])
        ])
      ]),
      IFELSE(EQ(F('s7ok'), num(1)), [
        ...keepSub(argOf('v'), num(1), SUB(F('s7j'), num(1))), setV('s7p1', F('ev')),
        setV('s7p2', argOf('sep')),
        ...keepSub(argOf('v'), ADD(F('s7j'), lenOf(argOf('sep'))), lenOf(argOf('v'))), setV('s7p3', F('ev'))
      ], [
        IFELSE(EQ(argOf('mode'), txt('rp')), [
          setV('s7p1', txt('')), setV('s7p2', txt('')), setV('s7p3', argOf('v'))
        ], [
          setV('s7p1', argOf('v')), setV('s7p2', txt('')), setV('s7p3', txt(''))
        ])
      ]),
      ...tuple3
    ]);
  }

  // ---------- (5) saffix v p mode -> removeprefix(pre) / removesuffix(suf)
  {
    const p = newProc('saffix %s %s %s', ['v', 'p', 'mode']);
    attachBody(p.defId, [
      setV('s7ok', num(0)),
      IF(GT(lenOf(argOf('v')), SUB(lenOf(argOf('p')), num(1))), [
        IFELSE(EQ(argOf('mode'), txt('pre')), [
          ...keepSub(argOf('v'), num(1), lenOf(argOf('p'))),
          callProc('compareText %s %s', [F('ev'), argOf('p')]),
          IF(EQ(F('cmp'), num(0)), [
            setV('s7ok', num(1)),
            ...keepSub(argOf('v'), ADD(lenOf(argOf('p')), num(1)), lenOf(argOf('v'))),
            setV('s7p1', F('ev'))
          ])
        ], [
          ...keepSub(argOf('v'), ADD(SUB(lenOf(argOf('v')), lenOf(argOf('p'))), num(1)), lenOf(argOf('v'))),
          callProc('compareText %s %s', [F('ev'), argOf('p')]),
          IF(EQ(F('cmp'), num(0)), [
            setV('s7ok', num(1)),
            ...keepSub(argOf('v'), num(1), SUB(lenOf(argOf('v')), lenOf(argOf('p')))),
            setV('s7p1', F('ev'))
          ])
        ])
      ]),
      IFELSE(EQ(F('s7ok'), num(1)), [
        setV('ev', F('s7p1'))
      ], [
        setV('ev', argOf('v'))
      ]),
      setV('evtype', txt('S'))
    ]);
  }

  // ---------- (6) stabs v n -> expandtabs
  {
    const p = newProc('stabs %s %s', ['v', 'n']);
    attachBody(p.defId, [
      setV('s7tacc', txt('')), setV('s7tcol', num(0)), setV('s7ti2', num(1)),
      REPEATU(GT(F('s7ti2'), lenOf(argOf('v'))), [
        setV('s7tc', letterOf(F('s7ti2'), argOf('v'))),
        IFELSE(EQ(F('s7tc'), txt(TAB)), [
          IFELSE(EQ(argOf('n'), num(0)), [
            setV('s7tw', num(0))
          ], [
            setV('s7tw', SUB(argOf('n'), MOD(F('s7tcol'), argOf('n'))))
          ]),
          setV('s7tk', num(1)),
          REPEATU(GT(F('s7tk'), F('s7tw')), [setV('s7tacc', J(F('s7tacc'), txt(' '))), chgV('s7tk', num(1))]),
          chgV('s7tcol', F('s7tw'))
        ], [
          setV('s7tacc', J(F('s7tacc'), F('s7tc'))),
          chgV('s7tcol', num(1))
        ]),
        chgV('s7ti2', num(1))
      ]),
      setV('ev', F('s7tacc')), setV('evtype', txt('S'))
    ]);
  }

  // ---------- (7) sslines v -> splitlines (split on \n, a trailing \r is dropped)
  {
    const p = newProc('sslines %s', ['v']);
    const flush = [
      callProc('lesc %s', [F('s7lacc')]),
      addTo('SSLine', J(J(LSEP(), txt('S')), F('ev'))),
      setV('s7lacc', txt(''))
    ];
    attachBody(p.defId, [
      clearL('SSLine'), setV('s7lacc', txt('')), setV('s7li', num(1)),
      REPEATU(GT(F('s7li'), lenOf(argOf('v'))), [
        setV('s7p1', letterOf(F('s7li'), argOf('v'))),
        IFELSE(EQ(F('s7p1'), txt(LF)), [
          ...flush
        ], [
          IF(NOT(EQ(F('s7p1'), txt(CR))), [setV('s7lacc', J(F('s7lacc'), F('s7p1')))])
        ]),
        chgV('s7li', num(1))
      ]),
      IF(NOT(EQ(F('s7lacc'), txt(''))), [...flush]),
      setV('s7p2', txt('')), setV('s7li', num(1)),
      REPEATU(GT(F('s7li'), llen('SSLine')), [
        setV('s7p2', J(F('s7p2'), item('SSLine', F('s7li')))),
        chgV('s7li', num(1))
      ]),
      setV('ev', F('s7p2')), setV('evtype', txt('L'))
    ]);
  }

  // ---------- (8) sclass2 v mode -> isupper / islower / isspace / isalnum
  {
    const p = newProc('sclass2 %s %s', ['v', 'mode']);
    attachBody(p.defId, [
      setV('s7ok2', num(1)), setV('s7has', num(0)),
      IF(EQ(lenOf(argOf('v')), num(0)), [setV('s7ok2', num(0))]),
      setV('s7ci', num(1)),
      REPEATU(GT(F('s7ci'), lenOf(argOf('v'))), [
        setV('s7cc', letterOf(F('s7ci'), argOf('v'))),
        IFELSE(EQ(argOf('mode'), txt('isspace')), [
          IF(NOT(CONT(txt(WS), F('s7cc'))), [setV('s7ok2', num(0))])
        ], [
          IFELSE(EQ(argOf('mode'), txt('isalnum')), [
            IF(NOT(CONT(txt(ALNUM), F('s7cc'))), [setV('s7ok2', num(0))])
          ], [
            callProc('scase %s %s', [F('s7cc'), txt('upper')]), setV('s7cu', F('ev')),
            callProc('scase %s %s', [F('s7cc'), txt('lower')]), setV('s7cl', F('ev')),
            callProc('compareText %s %s', [F('s7cu'), F('s7cl')]),
            IF(NOT(EQ(F('cmp'), num(0))), [
              setV('s7has', num(1)),
              IFELSE(EQ(argOf('mode'), txt('isupper')), [
                callProc('compareText %s %s', [F('s7cc'), F('s7cl')]),
                IF(EQ(F('cmp'), num(0)), [setV('s7ok2', num(0))])
              ], [
                callProc('compareText %s %s', [F('s7cc'), F('s7cu')]),
                IF(EQ(F('cmp'), num(0)), [setV('s7ok2', num(0))])
              ])
            ])
          ])
        ]),
        chgV('s7ci', num(1))
      ]),
      IF(AND(NOT(EQ(argOf('mode'), txt('isspace'))),
        AND(NOT(EQ(argOf('mode'), txt('isalnum'))), EQ(F('s7has'), num(0)))), [setV('s7ok2', num(0))]),
      setV('ev', F('s7ok2')), setV('evtype', txt('B'))
    ]);
  }
  console.log('[P167] string-method procedures registered');

  // ---------- (9) the dispatch: new `if smmeth == ...` lines in front of the known-name guard
  {
    const mc = inDef('methodcall %s %s');
    // the guard is the AND whose condition mentions the names P75 added (`zfill`); its message is
    // built with JOINs, so it cannot be found by the text
    const hasLit = (id, ch) => [...reach(id)].some((x) => Object.values(BL()[x].inputs || {}).some(
      (v) => Array.isArray(v[1]) && v[1][0] === 10 && String(v[1][1]) === ch));
    const guards = find(mc, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
      && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_and'
      && hasLit(b.inputs.CONDITION[1], 'zfill')
      && hasLit(b.inputs.CONDITION[1], 'isalpha'));
    if (guards.length !== 1) throw new Error('[P167] string method guard = ' + guards.length);
    // the second operand of the AND is the NOT(<new names from P75>) part
    const andB = BL()[BL()[guards[0]].inputs.CONDITION[1]];
    const notNew = (andB.inputs.OPERAND2 && typeof andB.inputs.OPERAND2[1] === 'string') ? BL()[andB.inputs.OPERAND2[1]] : null;
    if (!notNew || notNew.opcode !== 'operator_not') throw new Error('[P167] guard shape');

    const fillFor = () => [
      setV('s7fill', txt(' ')),
      IF(GT(F('mcut'), num(0)), [setV('s7fill', F('sma2'))])
    ];
    const MINE = ['ljust', 'rjust', 'center', 'lstrip', 'rstrip', 'swapcase', 'capitalize',
      'partition', 'rpartition', 'splitlines', 'removeprefix', 'removesuffix', 'expandtabs',
      'isupper', 'islower', 'isspace', 'isalnum'];
    const eqName = (n) => EQ(F('smmeth'), txt(n));
    const body = [
      IF(eqName('ljust'), [...fillFor(), callProc('spad %s %s %s %s', [F('smrec'), F('sma1'), F('s7fill'), txt('l')])]),
      IF(eqName('rjust'), [...fillFor(), callProc('spad %s %s %s %s', [F('smrec'), F('sma1'), F('s7fill'), txt('r')])]),
      IF(eqName('center'), [...fillFor(), callProc('spad %s %s %s %s', [F('smrec'), F('sma1'), F('s7fill'), txt('c')])]),
      IF(eqName('lstrip'), [callProc('strim %s %s', [F('smrec'), txt('l')])]),
      IF(eqName('rstrip'), [callProc('strim %s %s', [F('smrec'), txt('r')])]),
      IF(eqName('swapcase'), [callProc('sfold %s %s', [F('smrec'), txt('sc')])]),
      IF(eqName('capitalize'), [callProc('sfold %s %s', [F('smrec'), txt('ca')])]),
      IF(eqName('partition'), [callProc('spart %s %s %s', [F('smrec'), F('sma1'), txt('p')])]),
      IF(eqName('rpartition'), [callProc('spart %s %s %s', [F('smrec'), F('sma1'), txt('rp')])]),
      IF(eqName('splitlines'), [callProc('sslines %s', [F('smrec')])]),
      IF(eqName('removeprefix'), [callProc('saffix %s %s %s', [F('smrec'), F('sma1'), txt('pre')])]),
      IF(eqName('removesuffix'), [callProc('saffix %s %s %s', [F('smrec'), F('sma1'), txt('suf')])]),
      IF(eqName('expandtabs'), [
        setV('s7tw', num(8)),
        IF(EQ(F('smarg'), num(1)), [setV('s7tw', F('sma1'))]),
        callProc('stabs %s %s', [F('smrec'), F('s7tw')])
      ]),
      IF(eqName('isupper'), [callProc('sclass2 %s %s', [F('smrec'), F('smmeth')])]),
      IF(eqName('islower'), [callProc('sclass2 %s %s', [F('smrec'), F('smmeth')])]),
      IF(eqName('isspace'), [callProc('sclass2 %s %s', [F('smrec'), F('smmeth')])]),
      IF(eqName('isalnum'), [callProc('sclass2 %s %s', [F('smrec'), F('smmeth')])])
    ];
    insertBeforeStmt(guards[0], body);
    const mineTest = MINE.reduce((acc, n) => acc ? OR(acc, EQ(F('smmeth'), txt(n))) : EQ(F('smmeth'), txt(n)), null);
    const notOld = notNew.inputs.OPERAND[1];
    notNew.inputs.OPERAND = B.BOOL(OR(notOld, mineTest));
    if (BL()[notOld]) BL()[notOld].parent = notNew.inputs.OPERAND[1];
    console.log('[P167] ' + MINE.length + ' string methods dispatched');
  }

  // ---------- (10) two cheap dict methods: copy() and clear()
  {
    const dm = inDef('dictmeth %s %s %s %s %s');
    // dictmeth's body ends with `FAILB("AttributeError: dict has no method " + meth)`; the message
    // is built from JOINs, so the chain tail is the reliable anchor
    let tail = BL()[defIdOf('dictmeth %s %s %s %s %s')].next, prev = null;
    while (tail) { const nx = BL()[tail].next; if (!nx) break; prev = tail; tail = nx; }
    const lastB = tail ? BL()[tail] : null;
    if (!lastB || lastB.opcode !== 'procedures_call' || !lastB.mutation || lastB.mutation.proccode !== 'fail %s') {
      throw new Error('[P167] dictmeth tail is not the fallthrough fail');
    }
    const fails = [tail];
    if (fails.length !== 1) throw new Error('[P167] dictmeth fallthrough = ' + fails.length);
    insertBeforeStmt(fails[0], [
      IF(EQ(argOf('meth'), txt('copy')), [
        setV('ev', argOf('rec')), setV('evtype', txt('D')), STOPTHIS()
      ]),
      IF(EQ(argOf('meth'), txt('clear')), [
        callProc('assign %s %s %s', [argOf('nm'), txt(''), txt('D')]),
        setV('ev', txt('')), setV('evtype', txt('Z')), STOPTHIS()
      ])
    ]);
    console.log('[P167] dict copy()/clear() dispatched');

    // ---------- (11) setdefault(k, d) and popitem()
    // Both need the receiver written back, which `dictmeth` does with `assign(nm, records, "D")`
    // (the receiver's *name token* is the `nm` argument).
    const keyEq = (aType, bType) => [
      IF(EQ(F(aType), F(bType)), [
        IFELSE(EQ(F(aType), txt('S')), [
          callProc('compareText %s %s', [F('ev'), F('d9k')]),
          IF(EQ(F('cmp'), num(0)), [setV('d9f', F('d9i'))])
        ], [
          IF(EQ(F('ev'), F('d9k')), [setV('d9f', F('d9i'))])
        ])
      ])
    ];
    const keyEval = [
      callProc('hascomma %s %s', [argOf('lo'), argOf('hi')]),
      IFELSE(EQ(F('tqhcm'), num(1)), [
        callProc('eval %s %s', [argOf('lo'), SUB(F('tqcpz'), num(1))])
      ], [
        callProc('eval %s %s', [argOf('lo'), argOf('hi')])
      ]),
      IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
      setV('d9k', F('ev')), setV('d9kt', F('evtype'))
    ];
    const mkTuple2 = () => [
      callProc('lesc %s', [F('d9k')]), setV('d9ks', F('ev')),
      callProc('lesc %s', [F('d9v')]),
      setV('ev', joinAll([J(J(LSEP(), F('d9kt')), F('d9ks')), J(J(LSEP(), F('d9vt')), F('ev'))])),
      setV('evtype', txt('T'))
    ];
    insertBeforeStmt(fails[0], [
      IF(EQ(argOf('meth'), txt('setdefault')), [
        ...keyEval,
        callProc('listlen %s', [argOf('rec')]), setV('d9n', F('ev')),
        setV('d9f', num(0)), setV('d9i', num(1)),
        REPEATU(OR(GT(F('d9i'), F('d9n')), GT(F('d9f'), num(0))), [
          callProc('listitem %s %s', [argOf('rec'), F('d9i')]),
          ...keyEq('evtype', 'd9kt'),
          chgV('d9i', num(2))
        ]),
        IFELSE(GT(F('d9f'), num(0)), [
          callProc('listitem %s %s', [argOf('rec'), ADD(F('d9f'), num(1))])
        ], [
          setV('d9v', txt('')), setV('d9vt', txt('Z')),
          IF(EQ(F('tqhcm'), num(1)), [
            callProc('eval %s %s', [ADD(F('tqcpz'), num(1)), argOf('hi')]),
            IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
            setV('d9v', F('ev')), setV('d9vt', F('evtype'))
          ]),
          callProc('lesc %s', [F('d9k')]), setV('d9ks', F('ev')),
          callProc('lesc %s', [F('d9v')]),
          callProc('assign %s %s %s', [argOf('nm'),
            joinAll([argOf('rec'), J(LSEP(), F('d9kt')), F('d9ks'), J(LSEP(), F('d9vt')), F('ev')]), txt('D')]),
          setV('ev', F('d9v')), setV('evtype', F('d9vt'))
        ]),
        STOPTHIS()
      ]),
      IF(EQ(argOf('meth'), txt('popitem')), [
        callProc('listlen %s', [argOf('rec')]), setV('d9n', F('ev')),
        IF(EQ(F('d9n'), num(0)), [
          callProc('fail %s', [txt("KeyError: 'popitem(): dictionary is empty'")]), STOPTHIS()
        ]),
        // the last pair sits at the flat indices (n-1, n)
        callProc('listitem %s %s', [argOf('rec'), SUB(F('d9n'), num(1))]),
        setV('d9k', F('ev')), setV('d9kt', F('evtype')),
        callProc('listitem %s %s', [argOf('rec'), F('d9n')]),
        setV('d9v', F('ev')), setV('d9vt', F('evtype')),
        // where does the last pair start?  count separators and remember the (n-1)-th
        setV('d9c', num(0)), setV('d9p', num(0)), setV('d9i', num(1)),
        REPEATU(GT(F('d9i'), lenOf(argOf('rec'))), [
          IF(EQ(letterOf(F('d9i'), argOf('rec')), LSEP()), [
            chgV('d9c', num(1)),
            IF(EQ(F('d9c'), SUB(F('d9n'), num(1))), [setV('d9p', F('d9i'))])
          ]),
          chgV('d9i', num(1))
        ]),
        IFELSE(EQ(F('d9p'), num(0)), [
          callProc('assign %s %s %s', [argOf('nm'), txt(''), txt('D')])
        ], [
          callProc('substr %s %s %s', [argOf('rec'), num(1), SUB(F('d9p'), num(1))]),
          callProc('assign %s %s %s', [argOf('nm'), F('ev'), txt('D')])
        ]),
        ...mkTuple2(),
        STOPTHIS()
      ])
    ]);
    console.log('[P167] dict setdefault()/popitem() dispatched');

    // ---------- (12) update(m): merge m into the receiver
    // The records are *strings*, so the merge rebuilds the run: every pair of the receiver keeps its
    // position and takes m's value when the key matches, then m's new keys are appended -- which is
    // exactly CPython's order.
    {
      const scanMatch = (src, idxVar, onFound) => [
        callProc('listitem %s %s', [src, F(idxVar)]),
        IF(EQ(F('evtype'), F('d9kt')), [
          IFELSE(EQ(F('d9kt'), txt('S')), [
            callProc('compareText %s %s', [F('ev'), F('d9k')]),
            IF(EQ(F('cmp'), num(0)), onFound)
          ], [
            IF(EQ(F('ev'), F('d9k')), onFound)
          ])
        ])
      ];
      const du = newProc('dupd %s %s', ['rec', 'm']);
      attachBody(du.defId, [
        setV('d9acc', txt('')), setV('d9i', num(1)),
        callProc('listlen %s', [argOf('rec')]), setV('d9n', F('ev')),
        callProc('listlen %s', [argOf('m')]), setV('d9m', F('ev')),
        REPEATU(GT(F('d9i'), F('d9n')), [
          callProc('listitem %s %s', [argOf('rec'), F('d9i')]),
          setV('d9k', F('ev')), setV('d9kt', F('evtype')),
          callProc('listitem %s %s', [argOf('rec'), ADD(F('d9i'), num(1))]),
          setV('d9v', F('ev')), setV('d9vt', F('evtype')),
          setV('d9j', num(1)),
          REPEATU(GT(F('d9j'), F('d9m')), [
            ...scanMatch(argOf('m'), 'd9j', [
              callProc('listitem %s %s', [argOf('m'), ADD(F('d9j'), num(1))]),
              setV('d9v', F('ev')), setV('d9vt', F('evtype'))
            ]),
            chgV('d9j', num(2))
          ]),
          callProc('lesc %s', [F('d9k')]), setV('d9ks', F('ev')),
          callProc('lesc %s', [F('d9v')]),
          setV('d9acc', joinAll([F('d9acc'), J(LSEP(), F('d9kt')), F('d9ks'), J(LSEP(), F('d9vt')), F('ev')])),
          chgV('d9i', num(2))
        ]),
        setV('d9j', num(1)),
        REPEATU(GT(F('d9j'), F('d9m')), [
          callProc('listitem %s %s', [argOf('m'), F('d9j')]),
          setV('d9k', F('ev')), setV('d9kt', F('evtype')),
          setV('d9f', num(0)), setV('d9i', num(1)),
          REPEATU(OR(GT(F('d9i'), F('d9n')), GT(F('d9f'), num(0))), [
            ...scanMatch(argOf('rec'), 'd9i', [setV('d9f', F('d9i'))]),
            chgV('d9i', num(2))
          ]),
          IF(EQ(F('d9f'), num(0)), [
            callProc('listitem %s %s', [argOf('m'), ADD(F('d9j'), num(1))]),
            setV('d9v', F('ev')), setV('d9vt', F('evtype')),
            callProc('lesc %s', [F('d9k')]), setV('d9ks', F('ev')),
            callProc('lesc %s', [F('d9v')]),
            setV('d9acc', joinAll([F('d9acc'), J(LSEP(), F('d9kt')), F('d9ks'), J(LSEP(), F('d9vt')), F('ev')]))
          ]),
          chgV('d9j', num(2))
        ]),
        setV('ev', F('d9acc')), setV('evtype', txt('D'))
      ]);
      insertBeforeStmt(fails[0], [
        IF(EQ(argOf('meth'), txt('update')), [
          callProc('eval %s %s', [argOf('lo'), argOf('hi')]),
          IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
          IFELSE(EQ(F('evtype'), txt('D')), [
            callProc('dupd %s %s', [argOf('rec'), F('ev')]),
            callProc('assign %s %s %s', [argOf('nm'), F('ev'), txt('D')]),
            setV('ev', txt('')), setV('evtype', txt('Z'))
          ], [
            setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname', []),
            callProc('fail %s', [joinAll([txt("TypeError: '"), F('p6msg'), txt("' object is not iterable")])])
          ]),
          STOPTHIS()
        ])
      ]);
      console.log('[P167] dict update() dispatched');
    }
  }
});

// ---- P168: chained comparisons -- `1 < 2 < 3` (v4.95) ----
//
// MiniPy read `a op1 b op2 c` as `a op1 (b op2 c)`: `1 < 3 < 2` answered `True` (CPython: `False`),
// `'a' < 'b' < 'c'` raised `TypeError: incompatible comparison`, and `while 0 <= n < 3:` never ran
// its body (the middle operand was also evaluated twice).  CPython evaluates a chain as
// `(a op1 b) and (b op2 c) and ...`, evaluating every operand **once** and stopping at the first
// false comparison.
//
// `eval` scans for an operator, puts its token index in `ecut` and calls
// `pair(lo, hi, cut, Tok[cut])`; `pair` evaluates the left span and hands the *rest* to
// `rightside`, which is exactly why the remaining chain became the right operand.  The fix is a hook
// at the head of `pair`: when the span holds two or more depth-0 comparison operators, `chain`
// walks them from the left.
//
// Each step evaluates the next operand once, parks its value in the scratch variable `__chain` and
// overwrites that operand's first token with a reference to it (text `__chain`, kind `I`), so
// `rightside(c1v, c1t, op, k, k)` compares two *values*.  The token and its kind are restored right
// after and the scratch name is dropped from the four variable tables at the end (the trick P155
// uses for `__fmt`).  The chain answers the first false comparison, else the last comparison's value.
patch('P168 chained comparisons', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const setTokAt = (i, v) => I('data_replaceitemoflist', { fields: B.LISTF('Tok'), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const setKindAt = (i, v) => I('data_replaceitemoflist', { fields: B.LISTF('Kind'), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const NEW = ['q8cut', 'q8op', 'q8dep', 'q8i', 'q8tok', 'q8n', 'q8v1', 'q8t1', 'q8v2', 'q8t2',
    'q8res', 'q8rest', 'q8done', 'q8sav', 'q8savk', 'q8ncut', 'q8nop', 'q8fcut', 'q8fop'];
  for (const n of NEW) {
    if (taken.has(n)) throw new Error('[P168] variable name taken: ' + n);
    newVar(n, 0);
  }
  // the comparison operators that may chain (each is a single token in MiniPy)
  const isOpTok = (expr) => {
    let acc = null;
    for (const o of ['<', '>', '<=', '>=', '==', '!=', 'in', 'is']) {
      acc = acc ? OR(acc, EQ(expr(), txt(o))) : EQ(expr(), txt(o));
    }
    return acc;
  };
  const depthStep = () => [
    IF(OR(EQ(F('q8tok'), txt('(')), OR(EQ(F('q8tok'), txt('[')), EQ(F('q8tok'), txt('{')))), [chgV('q8dep', num(1))]),
    IF(OR(EQ(F('q8tok'), txt(')')), OR(EQ(F('q8tok'), txt(']')), EQ(F('q8tok'), txt('}')))), [chgV('q8dep', num(-1))])
  ];

  // ---------- chain lo hi cut op
  const ch = newProc('chain %s %s %s %s', ['lo', 'hi', 'cut', 'op']);
  attachBody(ch.defId, [
    setV('q8cut', argOf('cut')), setV('q8op', argOf('op')),
    callProc('eval %s %s', [argOf('lo'), SUB(F('q8cut'), num(1))]),
    IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
    setV('q8v1', F('ev')), setV('q8t1', F('evtype')),
    setV('q8done', num(0)),
    REPEATU(EQ(F('q8done'), num(1)), [
      // where is the next comparison operator of this chain?
      setV('q8ncut', num(0)), setV('q8nop', txt('')), setV('q8dep', num(0)), setV('q8i', ADD(F('q8cut'), num(1))),
      REPEATU(GT(F('q8i'), argOf('hi')), [
        setV('q8tok', tokAt(F('q8i'))),
        ...depthStep(),
        IF(AND(EQ(F('q8dep'), num(0)), AND(EQ(F('q8ncut'), num(0)), isOpTok(() => F('q8tok')))), [
          setV('q8ncut', F('q8i')), setV('q8nop', F('q8tok'))
        ]),
        chgV('q8i', num(1))
      ]),
      IFELSE(GT(F('q8ncut'), num(0)), [
        // the middle operand, evaluated exactly once
        callProc('eval %s %s', [ADD(F('q8cut'), num(1)), SUB(F('q8ncut'), num(1))]),
        IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
        setV('q8v2', F('ev')), setV('q8t2', F('evtype')),
        // park it in the scratch variable and point the operand's first token at it
        callProc('assign %s %s %s', [txt('__chain'), F('q8v2'), F('q8t2')]),
        setV('q8sav', tokAt(ADD(F('q8cut'), num(1)))), setV('q8savk', item('Kind', ADD(F('q8cut'), num(1)))),
        setTokAt(ADD(F('q8cut'), num(1)), txt('__chain')),
        setKindAt(ADD(F('q8cut'), num(1)), txt('I')),
        callProc('rightside %s %s %s %s %s', [F('q8v1'), F('q8t1'), F('q8op'),
          ADD(F('q8cut'), num(1)), ADD(F('q8cut'), num(1))]),
        callProc('truth %s %s', [F('ev'), F('evtype')]),
        setTokAt(ADD(F('q8cut'), num(1)), F('q8sav')),
        setKindAt(ADD(F('q8cut'), num(1)), F('q8savk')),
        IFELSE(EQ(F('truthv'), num(0)), [
          setV('q8res', num(0)), setV('q8rest', txt('B')), setV('q8done', num(1))
        ], [
          setV('q8v1', F('q8v2')), setV('q8t1', F('q8t2')),
          setV('q8cut', F('q8ncut')), setV('q8op', F('q8nop'))
        ])
      ], [
        callProc('rightside %s %s %s %s %s', [F('q8v1'), F('q8t1'), F('q8op'), ADD(F('q8cut'), num(1)), argOf('hi')]),
        setV('q8res', F('ev')), setV('q8rest', F('evtype')), setV('q8done', num(1))
      ])
    ]),
    setV('ev', F('q8res')), setV('evtype', F('q8rest')),
    // the scratch name has done its job
    callProc('lookup %s', [txt('__chain')]),
    IF(GT(F('found'), num(0)), [
      I('data_deleteoflist', { fields: B.LISTF('Names'), inputs: { INDEX: B.REP(VAR('found'), [10, '']) } }),
      I('data_deleteoflist', { fields: B.LISTF('Values'), inputs: { INDEX: B.REP(VAR('found'), [10, '']) } }),
      I('data_deleteoflist', { fields: B.LISTF('Types'), inputs: { INDEX: B.REP(VAR('found'), [10, '']) } }),
      I('data_deleteoflist', { fields: B.LISTF('Show'), inputs: { INDEX: B.REP(VAR('found'), [10, '']) } })
    ])
  ]);
  console.log('[P168] chain registered');

  // ---------- hook at the head of pair
  {
    const pr = inDef('pair %s %s %s %s');
    const leftEval = find(pr, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
    if (leftEval.length !== 1) throw new Error('[P168] pair left eval = ' + leftEval.length);
    const countOps = [
      setV('q8n', num(0)), setV('q8dep', num(0)), setV('q8i', argOf('lo')),
      REPEATU(GT(F('q8i'), argOf('hi')), [
        setV('q8tok', tokAt(F('q8i'))),
        ...depthStep(),
        IF(AND(EQ(F('q8dep'), num(0)), isOpTok(() => F('q8tok'))), [chgV('q8n', num(1))]),
        chgV('q8i', num(1))
      ])
    ];
    const findFirst = [
      setV('q8fcut', num(0)), setV('q8fop', txt('')), setV('q8dep', num(0)), setV('q8i', argOf('lo')),
      REPEATU(GT(F('q8i'), argOf('hi')), [
        setV('q8tok', tokAt(F('q8i'))),
        ...depthStep(),
        IF(AND(EQ(F('q8dep'), num(0)), AND(EQ(F('q8fcut'), num(0)), isOpTok(() => F('q8tok')))), [
          setV('q8fcut', F('q8i')), setV('q8fop', F('q8tok'))
        ]),
        chgV('q8i', num(1))
      ])
    ];
    insertBeforeStmt(leftEval[0], [
      // only a comparison cut may start a chain: with `and`/`or` the arguments must be split first
      // (`1 < 2 < 3 or 9 < 1` has four comparison tokens in one span)
      IF(isOpTok(() => argOf('op')), [
        ...countOps,
        IF(GT(F('q8n'), num(1)), [
          ...findFirst,
          callProc('chain %s %s %s %s', [argOf('lo'), argOf('hi'), F('q8fcut'), F('q8fop')]),
          STOPTHIS()
        ])
      ])
    ]);
    console.log('[P168] pair evaluates chains');
  }
});

// ---- P169: an in-place mutation of a container must survive the function frame (v4.96) ----
//
// `calluser` snapshots the caller's variable table into FN/FV/FT and lets the callee run on
// that table; on return the table is rebuilt from the snapshot, so *every* write the callee
// made is discarded.  That is right for a rebinding (`c = [5]` really is a new local in
// CPython) but wrong for an in-place mutation: `c[0] = 5`, `c.append(1)`, `d['a'] = 5` and
// `del a[0]` change the object the caller sees, and CPython keeps that change.
//
// Containers are record strings here, so there is no identity to follow -- instead every
// *mutating write-back* announces itself: right after the `assign(name, newtext, type)` that
// indexset / indexdel / slicewrite / methodcall / dictmeth / setmeth end with, `publish <name>`
// copies the freshly stored value into every frame snapshot entry that still holds that
// container (`wscan` walks FN/FV/FT), so each enclosing frame -- and finally the top level --
// sees the new text.
//
// Names need care, because a callee name can shadow a caller name:
//   * a *parameter* is bound by the call, and `def f(c): c[0] = 9` called as `f(d)` must reach
//     `d`, not the globals' unrelated `c` -- so `calluser` records every parameter in ArN/ArO
//     (`pmap`), ArO = '' when the argument was not a plain variable name, and `wpub` looks the
//     mutated name up there: a parameter publishes to the name it was passed by, and only
//     names that are *not* parameters publish to their own name (`wscan`);
//   * a list alias made inside the callee (`b = c`) is followed through AliasN/AliasT, which
//     P54 maintains;
//   * the snapshot stack is per frame (FrAr + pbegin/pend), and it must not be saved by
//     fpush/fpop -- P14 computes its save lists from the variables/lists that existed when
//     P14 ran, so state added later is never snapshotted.  (Verified in the build log.)
patch('P169 container mutation', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const setAt = (list, idx, v) => I('data_replaceitemoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(idx, [4, '0']), ITEM: B.REP(v, [4, '0']) } });
  const delLast = (list) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: txt('last') } });

  const takenV = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['w1v', 'w1t', 'w1i', 'w1k', 'w1hit', 'w1s', 'w1e', 'w1arg', 'w1n', 'w1r']) {
    if (takenV.has(n)) throw new Error('[P169] variable name taken: ' + n);
    newVar(n, 0);
  }
  const takenL = new Set(Object.values(T(IT).lists).map((x) => x[0]));
  for (const l of ['ArN', 'ArO', 'FrAr']) {
    if (takenL.has(l)) throw new Error('[P169] list name taken: ' + l);
    B.addList(IT, l, []);
  }

  // ---------- wscan <name>: carry w1v/w1t into every snapshot entry that holds <name>
  const ws = newProc('wscan %s', ['nm']);
  attachBody(ws.defId, [
    setV('w1i', num(1)),
    REPEATU(GT(F('w1i'), llen('FN')), [
      IF(EQ(item('FN', F('w1i')), argOf('nm')), [
        setAt('FV', F('w1i'), F('w1v')),
        setAt('FT', F('w1i'), F('w1t'))
      ]),
      chgV('w1i', num(1))
    ])
  ]);

  // ---------- wpub <name>: a parameter publishes to the name it was passed by
  const wp = newProc('wpub %s', ['nm']);
  attachBody(wp.defId, [
    setV('w1hit', num(0)), setV('w1r', txt('')), setV('w1k', num(1)),
    // the innermost binding wins: entries are a stack, so keep the last match
    REPEATU(GT(F('w1k'), llen('ArN')), [
      IF(EQ(item('ArN', F('w1k')), argOf('nm')), [
        setV('w1hit', num(1)),
        setV('w1r', item('ArO', F('w1k')))
      ]),
      chgV('w1k', num(1))
    ]),
    IFELSE(EQ(F('w1hit'), num(0)),
      [callProc('wscan %s', [argOf('nm')])],
      [IF(NOT(EQ(F('w1r'), txt(''))), [callProc('wscan %s', [F('w1r')])])])
  ]);

  // ---------- publish <name>: called right after a mutating write-back
  const pub = newProc('publish %s', ['vn']);
  attachBody(pub.defId, [
    IF(GT(F('cdepth'), num(0)), [
      callProc('lookup %s', [argOf('vn')]),
      IF(GT(F('found'), num(0)), [
        setV('w1t', item('Types', F('found'))),
        IF(OR(OR(EQ(F('w1t'), txt('L')), EQ(F('w1t'), txt('T'))), OR(EQ(F('w1t'), txt('D')), EQ(F('w1t'), txt('E')))), [
          setV('w1v', item('Values', F('found'))),
          callProc('wpub %s', [argOf('vn')]),
          // an alias made in this scope has to travel too (P54's table)
          setV('w1k', num(1)),
          REPEATU(GT(F('w1k'), llen('AliasN')), [
            IF(EQ(item('AliasN', F('w1k')), argOf('vn')), [callProc('wpub %s', [item('AliasT', F('w1k'))])]),
            IF(EQ(item('AliasT', F('w1k')), argOf('vn')), [callProc('wpub %s', [item('AliasN', F('w1k'))])]),
            chgV('w1k', num(1))
          ])
        ])
      ])
    ])
  ]);

  // ---------- per-frame parameter bookkeeping
  const pb = newProc('pbegin', []);
  attachBody(pb.defId, [addTo('FrAr', ADD(llen('ArN'), num(1)))]);
  const pm = newProc('pmap %s %s', ['pn', 'an']);
  attachBody(pm.defId, [
    addTo('ArN', argOf('pn')),
    // Resolve the argument name through the enclosing frames' bindings (`f(y)` called as `g(y)`
    // must still reach the name the outermost caller used).  The inner loop stops at llen(ArO),
    // so the entry just appended -- which has no ArO yet -- cannot be followed.
    setV('w1r', argOf('an')), setV('w1k', num(1)),
    REPEATU(GT(F('w1k'), num(8)), [
      setV('w1hit', num(0)), setV('w1i', num(1)),
      REPEATU(GT(F('w1i'), llen('ArO')), [
        IF(AND(EQ(item('ArN', F('w1i')), F('w1r')), NOT(EQ(item('ArO', F('w1i')), txt('')))), [
          setV('w1r', item('ArO', F('w1i'))),
          setV('w1hit', num(1)),
          setV('w1i', llen('ArO'))
        ]),
        chgV('w1i', num(1))
      ]),
      IF(EQ(F('w1hit'), num(0)), [setV('w1k', num(8))]),
      chgV('w1k', num(1))
    ]),
    addTo('ArO', F('w1r'))
  ]);
  const pe = newProc('pend', []);
  attachBody(pe.defId, [
    setV('w1n', SUB(item('FrAr', llen('FrAr')), num(1))),
    REPEAT(SUB(llen('ArN'), F('w1n')), [delLast('ArN'), delLast('ArO')]),
    delLast('FrAr')
  ]);
  // parg <lo> <fragment index>: the plain variable name this argument fragment is, else ""
  const pa = newProc('parg %s %s', ['lo', 'fx']);
  attachBody(pa.defId, [
    setV('w1arg', txt('')),
    setV('w1s', argOf('lo')),
    IF(GT(argOf('fx'), num(1)), [setV('w1s', ADD(item('UComma', SUB(argOf('fx'), num(1))), num(1)))]),
    setV('w1e', SUB(item('UComma', argOf('fx')), num(1))),
    IF(AND(EQ(F('w1s'), F('w1e')), EQ(item('Kind', F('w1s')), txt('I'))), [
      callProc('lookup %s', [tokAt(F('w1s'))]),
      IF(GT(F('found'), num(0)), [setV('w1arg', tokAt(F('w1s')))])
    ]),
    // a keyword argument `name = value` whose value is a plain name aliases that name too
    IF(AND(EQ(ADD(F('w1s'), num(2)), F('w1e')), EQ(tokAt(ADD(F('w1s'), num(1))), txt('='))), [
      IF(EQ(item('Kind', F('w1e')), txt('I')), [
        callProc('lookup %s', [tokAt(F('w1e'))]),
        IF(GT(F('found'), num(0)), [setV('w1arg', tokAt(F('w1e')))])
      ])
    ])
  ]);
  console.log('[P169] publish/wscan/wpub/pbegin/pmap/pend/parg registered');

  // ---------- (a) calluser: frame bookkeeping around the parameter binding loop
  {
    const cu = inDef('calluser %s %s %s');
    const fp = find(cu, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fpush');
    if (fp.length !== 1) throw new Error('[P169] fpush call = ' + fp.length);
    insertBeforeStmt(fp[0], [callProc('pbegin')]);
    const fo = find(cu, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fpop');
    if (fo.length !== 1) throw new Error('[P169] fpop call = ' + fo.length);
    insertBeforeStmt(fo[0], [callProc('pend')]);

    // every param binding is an assign whose name is `item(FnPar, fu)`
    const varNameOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && d[0] === 12) return d[1];
      // NB: B.VAR() is itself a descriptor ([3,[12,name,id],[10,'']]), so the inner slot
      // may be an array rather than a block id -- both forms occur in this build.
      if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
      if (typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') return BL()[d[1]].fields.VARIABLE[0];
      return null;
    };
    const binds = find(cu, (b) => {
      if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'assign %s %s %s') return false;
      const argIds = JSON.parse(b.mutation.argumentids);
      const nm = b.inputs[argIds[0]];
      if (!nm || typeof nm[1] !== 'string') return false;
      const q = BL()[nm[1]];
      return q && q.opcode === 'data_itemoflist' && q.fields.LIST && q.fields.LIST[0] === 'FnPar';
    });
    if (binds.length !== 3) throw new Error('[P169] calluser param binds = ' + binds.length);
    let viaFrag = 0, viaDefault = 0;
    for (const bid of binds) {
      const argIds = JSON.parse(BL()[bid].mutation.argumentids);
      const val = BL()[bid].inputs[argIds[1]];
      const q = val && typeof val[1] === 'string' ? BL()[val[1]] : null;
      const fragIdx = (q && q.opcode === 'data_itemoflist' && q.fields.LIST && q.fields.LIST[0] === 'UArgV')
        ? varNameOf(q.inputs.INDEX) : null;
      const tail = [callProc('pmap %s %s', [item('FnPar', F('fu')), fragIdx ? F('w1arg') : txt('')])];
      if (fragIdx) {
        tail.unshift(callProc('parg %s %s', [argOf('lo'), F(fragIdx)]));
        viaFrag++;
      } else viaDefault++;
      spliceAfter(bid, chain(tail));
    }
    console.log('[P169] calluser: pbegin/pend + ' + binds.length + ' param binds (' + viaFrag + ' by fragment, ' + viaDefault + ' default)');
  }

  // ---------- (b) every mutating write-back announces the new value
  {
    const instrument = (proccode) => {
      const def = inDef(proccode);
      const calls = find(def, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'assign %s %s %s');
      for (const cid of calls) {
        const argIds = JSON.parse(BL()[cid].mutation.argumentids);
        const d = BL()[cid].inputs[argIds[0]];
        // the name expression is already in the assign call: hand publish a fresh copy
        const arg = (d && typeof d[1] === 'string')
          ? [3, cloneExpr(d[1]), (d.length > 2 ? d[2] : [4, '0'])]
          : JSON.parse(JSON.stringify(d));
        spliceAfter(cid, callProc('publish %s', [arg]));
      }
      return calls.length;
    };
    const counts = ['indexset %s %s', 'indexdel %s %s', 'slicewrite %s %s %s %s %s',
      'methodcall %s %s', 'dictmeth %s %s %s %s %s', 'setmeth %s %s %s %s %s']
      .map((pc) => pc.split(' ')[0] + '=' + instrument(pc));
    console.log('[P169] write-back hooks: ' + counts.join(' '));
  }
});

// ---- P170: containers inside containers, and list.pop(i) (v4.97) ----
//
// Three old bugs, all of them silent wrong answers:
//
//  (1) `a[0] = [5]` (base `indexset`, list branch).  A list is the text
//      `lsep typ lesc(text) lsep typ lesc(text) ...` -- every element value must be escaped so
//      that no separator can appear inside it.  The list branch of indexset embedded the freshly
//      evaluated `lval` **raw**, so `c = [[0],[0]]; c[0] = [5]` became `[[], 5, [0]]`
//      (the value's own separators were read as element boundaries).  The dict branch escapes
//      (and P138 already fixed lsort's re-encode); this is the missing one.
//  (2) `d['a'] = {'b': 1}` (base `indexset`, dict branch).  The key's type and escaped text are
//      captured *before* the value is evaluated, but a dict/list literal evaluates through the
//      same scratch variables (`dgkt`/`dgesc`/...), so the key was overwritten by the literal's
//      own bookkeeping -- `d['a'] = {'b': 1}` stored the pair under key `'1'`.  The key fragment
//      is now built once, into a variable nothing else touches.
//  (3) `a.insert(0, [1])` (P13).  insert hands `slicewrite` a *pre-encoded* element
//      (`lsep + type + text`), and it built that text from the raw value -- same bug as (1).
//
//  (4) `a.pop(i)` ignored its argument completely and always removed the last element
//      (`a = [1,2,3]; a.pop(0)` answered `3` and left `[1, 2]`).  The branch is rewritten to
//      evaluate the index, normalise negatives, bounds-check with CPython's wording and remove
//      exactly that element (`lpopv`), with CPython's TypeError for a non-integer index.
patch('P170 container elements + pop(i)', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const FAILB = (expr) => callProc('fail %s', [expr]);
  const J = (a, b) => JOIN(a, b);

  const takenV = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['lvesc', 'dgkf', 'w3s', 'w3n', 'w3i', 'w3v', 'w3t']) {
    if (takenV.has(n)) throw new Error('[P170] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- small structural helpers (this build stores VAR() as a descriptor, [3,[12,name,id],..])
  const varNameOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && d[0] === 12) return d[1];
    if (Array.isArray(d[1]) && d[1][0] === 12) return d[1][1];
    if (typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') return BL()[d[1]].fields.VARIABLE[0];
    return null;
  };
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const eqVarLit = (d, name, lit) => {
    if (!d || typeof d[1] !== 'string') return false;
    const b = BL()[d[1]];
    if (!b || b.opcode !== 'operator_equals') return false;
    return (varNameOf(b.inputs.OPERAND1) === name && litOf(b.inputs.OPERAND2) === lit)
        || (varNameOf(b.inputs.OPERAND2) === name && litOf(b.inputs.OPERAND1) === lit);
  };
  const mentionsVar = (d, name) => {
    const seen = new Set();
    const stack = [d];
    while (stack.length) {
      const v = stack.pop();
      if (!v) continue;
      if (varNameOf(v) === name) return true;
      if (typeof v[1] === 'string') { if (seen.has(v[1])) continue; seen.add(v[1]); const b = BL()[v[1]]; if (b) for (const x of Object.values(b.inputs || {})) stack.push(x); }
      if (Array.isArray(v[1])) stack.push(v[1]);
    }
    return false;
  };
  const topChain = (proccode) => {
    const out = [];
    let cur = BL()[defIdOf(proccode)].next;
    while (cur) { out.push(cur); cur = BL()[cur].next; }
    return out;
  };

  // ---------- (1) indexset: escape the element before embedding it
  {
    const iset = inDef('indexset %s %s');
    // only the *list* branch's re-encode is on the top-level statement chain; the dict branch's
    // identical-looking join sits inside a SUBSTACK (and its lval is already escaped)
    const cand = topChain('indexset %s %s').filter((id) => {
      const b = BL()[id];
      return b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'lnew'
        && mentionsVar(b.inputs.VALUE, 'lval');
    });
    if (cand.length !== 1) throw new Error('[P170] indexset list re-encode = ' + cand.length);
    insertBeforeStmt(cand[0], [callProc('lesc %s', [VAR('lval')]), setV('lvesc', VAR('ev'))]);
    const old = BL()[cand[0]].inputs.VALUE;
    replaceExpr(old[1], () => J(J(J(VAR('lnew'), VAR('lsep')), VAR('ltyp')), VAR('lvesc')));
    console.log('[P170] indexset escapes the element it stores');
  }

  // ---------- (2) indexset dict branch: keep the key fragment out of the value's reach
  {
    const asg = find(inDef('indexset %s %s'), (b) => {
      if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'assign %s %s %s') return false;
      const keys = Object.keys(b.inputs);
      return litOf(b.inputs[keys[2]]) === 'D' && mentionsVar(b.inputs[keys[1]], 'dgesc');
    });
    if (asg.length !== 1) throw new Error('[P170] indexset dict assign = ' + asg.length);
    const target = asg[0];
    const esc = find(inDef('indexset %s %s'), (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'lesc %s' && mentionsVar(b.inputs[Object.keys(b.inputs)[0]], 'dgkey'));
    if (esc.length !== 1) throw new Error('[P170] indexset key lesc = ' + esc.length);
    const dgescSet = find(inDef('indexset %s %s'), (b) => b.opcode === 'data_setvariableto'
      && b.fields.VARIABLE[0] === 'dgesc' && b.inputs.VALUE && Array.isArray(b.inputs.VALUE[1]) && b.inputs.VALUE[1][0] === 12);
    if (dgescSet.length !== 1) throw new Error('[P170] dgesc set = ' + dgescSet.length);
    spliceAfter(dgescSet[0], chain([setV('dgkf', J(J(VAR('lsep'), VAR('dgkt')), VAR('dgesc')))]));
    const ai = Object.keys(BL()[target].inputs);
    const val = BL()[target].inputs[ai[1]];
    replaceExpr(val[1], () => J(J(VAR('xa'), VAR('dgkf')), J(J(VAR('lsep'), VAR('ltyp')), VAR('lval'))));
    console.log('[P170] indexset keeps the dict key fragment');
  }

  // ---------- (3) insert(): the pre-encoded element has to be escaped too
  {
    const mc = inDef('methodcall %s %s');
    const sw = find(mc, (b) => b.opcode === 'procedures_call' && b.mutation
      && b.mutation.proccode === 'slicewrite %s %s %s %s %s');
    const ins = sw.filter((id) => {
      const keys = Object.keys(BL()[id].inputs);
      return mentionsVar(BL()[id].inputs[keys[4]], 'lnt') && mentionsVar(BL()[id].inputs[keys[4]], 'lneed');
    });
    if (ins.length !== 1) throw new Error('[P170] insert slicewrite = ' + ins.length);
    insertBeforeStmt(ins[0], [callProc('lesc %s', [VAR('lneed')]), setV('lneed', VAR('ev'))]);
    console.log('[P170] insert escapes the inserted element');
  }

  // ---------- (4) pop(i)
  {
    const lp = newProc('lpopv %s %s', ['s', 'idx']);
    attachBody(lp.defId, [
      setV('w3s', argOf('s')),
      callProc('listitem %s %s', [VAR('w3s'), argOf('idx')]),
      setV('w3v', VAR('ev')), setV('w3t', VAR('evtype')),
      setV('lstart', num(0)), setV('lend', num(0)), setV('lcount', num(0)), setV('lx', num(1)),
      REPEATU(OR(GT(VAR('lx'), lenOf(VAR('w3s'))), GT(VAR('lend'), num(0))), [
        IF(EQ(letterOf(VAR('lx'), VAR('w3s')), VAR('lsep')), [
          chgV('lcount', num(1)),
          IF(EQ(VAR('lcount'), argOf('idx')), [setV('lstart', VAR('lx'))]),
          IF(EQ(VAR('lcount'), ADD(argOf('idx'), num(1))), [setV('lend', VAR('lx'))])
        ]),
        chgV('lx', num(1))
      ]),
      IF(EQ(VAR('lend'), num(0)), [setV('lend', ADD(lenOf(VAR('w3s')), num(1)))]),
      callProc('substr %s %s %s', [VAR('w3s'), num(1), SUB(VAR('lstart'), num(1))]),
      setV('lnew', VAR('ev')),
      callProc('substr %s %s %s', [VAR('w3s'), VAR('lend'), lenOf(VAR('w3s'))]),
      setV('ev', J(VAR('lnew'), VAR('ev'))),
      setV('evtype', txt('L'))
    ]);

    const mc = inDef('methodcall %s %s');
    const popIf = find(mc, (b) => b.opcode === 'control_if' && eqVarLit(b.inputs.CONDITION, 'lmeth', 'pop'));
    if (popIf.length !== 1) throw new Error('[P170] methodcall pop branch = ' + popIf.length);
    const badIndex = () => [
      setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname'),
      FAILB(J(J(txt("TypeError: '"), VAR('p6msg')), txt("' object cannot be interpreted as an integer"))),
      STOPTHIS()
    ];
    setStack(popIf[0], 'SUBSTACK', [
      setV('w3s', VAR('xa')),
      callProc('listlen %s', [VAR('w3s')]),
      setV('w3n', VAR('ev')),
      IF(EQ(VAR('w3n'), num(0)), [FAIL(txt('IndexError: pop from empty list')), STOPTHIS()]),
      setV('w3i', SUB(VAR('w3n'), num(1))),
      IF(GT(argOf('hi'), ADD(argOf('lo'), num(4))), [
        callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        IFELSE(NOT(EQ(VAR('evtype'), txt('N'))), badIndex(), [
          // CPython takes an *integer*: a float is rejected even when it is whole (`pop(1.0)`)
          IF(I('operator_contains', { inputs: { STRING1: B.REP(VAR('ev'), [10, '']), STRING2: B.REP(txt('.'), [10, '']) } }), badIndex()),
          setV('w3i', VAR('ev')),
          IF(LT(VAR('w3i'), num(0)), [chgV('w3i', VAR('w3n'))]),
          IF(OR(LT(VAR('w3i'), num(0)), NOT(LT(VAR('w3i'), VAR('w3n')))), [
            FAIL(txt('IndexError: pop index out of range')), STOPTHIS()
          ])
        ])
      ]),
      callProc('lpopv %s %s', [VAR('w3s'), ADD(VAR('w3i'), num(1))]),
      callProc('assign %s %s %s', [tokAt(argOf('lo')), VAR('ev'), txt('L')]),
      callProc('publish %s', [tokAt(argOf('lo'))]),
      setV('ev', VAR('w3v')), setV('evtype', VAR('w3t'))
    ]);
    console.log('[P170] pop(i) honours its index');
  }
});

// ---- P171: mutating a container that lives down a *path* (v4.98) ----
//
// `a[0].append(2)`, `d['k'].append(2)`, `a[0].sort()`, `k.xs.append(2)` and `a[0][1] = 9` all
// did nothing (or died with `SyntaxError: expression`).  Containers are record strings with no
// identity, so the mutated copy has to be written back through the path it came from.
//
// What the interpreter does today: `eval` sees `X . name ( ... )` with the dot past `lo+1` and
// calls `methodcall2(lo, mdot, hi)`, which evaluates the receiver span and re-enters `methodcall`
// with `mcpre = 1` ("the receiver is this pre-evaluated value").  The dispatch itself runs and
// mutates a copy -- but its write-back targets `Tok[mdot-1]`, the *last token* of the receiver
// expression (a `]` or a name), so the change lands nowhere.
//
// The fix is to give that write-back a real destination:
//   * `pvok lo hi`   -- is this span a plain lvalue path (`name` + `[...]`/`.name` accessors)?
//   * `pathset lo hi vt vv` -- store the value into that path, recursively: for a trailing
//     `[...]` it evaluates the index, reads the head container, rebuilds it with the element
//     replaced and recurses into the head; for a trailing `.name` it writes the instance
//     attribute (the IAttr table is a heap, so no recursion is needed); a bare name is `assign`.
//     The element write itself is delegated to the existing `indexset` by tokenizing the
//     synthetic statement `__pw[__pi]=__pv` (so escaping, dict keys, slices and every error
//     message stay in one place) and re-tokenizing the real line afterwards.
// `methodcall2` parks the receiver in `__recv`, points `Tok[mdot-1]` at it, runs the dispatch and
// writes `__recv` back through the path when it actually changed.  `execute` gets one new branch
// for statements with two or more accessors (`a[0][1] = 9`, `k.xs[0] = 9`, `k.a.b = 9`).
patch('P171 path assignment', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const setTok = (i, v) => I('data_replaceitemoflist', { fields: B.LISTF('Tok'), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const setKind = (i, v) => I('data_replaceitemoflist', { fields: B.LISTF('Kind'), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const delAt = (list, i) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const FAILB = (expr) => callProc('fail %s', [expr]);
  const J = (a, b) => JOIN(a, b);
  // NB: these take a *thunk* -- a reporter block can only sit in one input, and each of the
  // three comparisons needs its own Tok[i] block (sharing one silently makes two of them false).
  const OPEN = (f) => OR(OR(EQ(f(), txt('(')), EQ(f(), txt('['))), EQ(f(), txt('{')));
  const CLOSE = (f) => OR(OR(EQ(f(), txt(')')), EQ(f(), txt(']'))), EQ(f(), txt('}')));

  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['w5i', 'w5t', 'w5d', 'w5eq', 'w6ok', 'w6cap', 'w6i', 'w6d',
    'w7v', 'w7t', 'w7lo', 'w7hi', 'w7i', 'w7d', 'w7br', 'w7nm', 'w7nv', 'w7nt', 'w7pc', 'w7dep',
    'w8old', 'w8oldt', 'w8sv', 'w8svk']) {
    if (taken.has(n)) throw new Error('[P171] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- pvok lo hi : is the span an lvalue path?  w6ok = 1, w6cap = accessor count
  const pv = newProc('pvok %s %s', ['lo', 'hi']);
  attachBody(pv.defId, [
    setV('w6ok', num(0)), setV('w6cap', num(0)),
    IF(AND(EQ(item('Kind', argOf('lo')), txt('I')), NOT(GT(argOf('lo'), argOf('hi')))), [
      setV('w6ok', num(1)),
      setV('w6i', ADD(argOf('lo'), num(1))),
      REPEATU(OR(GT(F('w6i'), argOf('hi')), EQ(F('w6ok'), num(0))), [
        IFELSE(EQ(tokAt(F('w6i')), txt('[')), [
          setV('w6d', num(1)),
          chgV('w6i', num(1)),
          REPEATU(OR(GT(F('w6i'), argOf('hi')), EQ(F('w6d'), num(0))), [
            IF(OPEN(() => tokAt(F('w6i'))), [chgV('w6d', num(1))]),
            IF(CLOSE(() => tokAt(F('w6i'))), [chgV('w6d', num(-1))]),
            chgV('w6i', num(1))
          ]),
          IF(NOT(EQ(F('w6d'), num(0))), [setV('w6ok', num(0))]),
          chgV('w6cap', num(1))
        ], [
          IFELSE(AND(EQ(tokAt(F('w6i')), txt('.')),
            AND(NOT(GT(ADD(F('w6i'), num(1)), argOf('hi'))), EQ(item('Kind', ADD(F('w6i'), num(1))), txt('I')))), [
            chgV('w6i', num(2)),
            chgV('w6cap', num(1))
          ], [
            setV('w6ok', num(0))
          ])
        ])
      ]),
      IF(NOT(EQ(F('w6i'), ADD(argOf('hi'), num(1)))), [setV('w6ok', num(0))])
    ])
  ]);

  // ---------- aset iid name vt vv : instance attribute (IAttr is a heap, so this is the leaf case)
  const as = newProc('aset %s %s %s %s', ['iid', 'nm', 'vt', 'vv']);
  attachBody(as.defId, [
    setV('cX', num(0)), setV('ck', num(1)),
    REPEATU(GT(F('ck'), llen('IAttrId')), [
      IF(AND(EQ(item('IAttrId', F('ck')), argOf('iid')), EQ(item('IAttrName', F('ck')), argOf('nm'))), [
        setV('cX', F('ck')), setV('ck', llen('IAttrId'))
      ]),
      chgV('ck', num(1))
    ]),
    IFELSE(EQ(F('cX'), num(0)), [
      addTo('IAttrId', argOf('iid')), addTo('IAttrName', argOf('nm')),
      addTo('IAttrVal', argOf('vv')), addTo('IAttrType', argOf('vt'))
    ], [
      I('data_replaceitemoflist', { fields: B.LISTF('IAttrVal'), inputs: { INDEX: B.REP(F('cX'), [4, '0']), ITEM: B.REP(argOf('vv'), [4, '0']) } }),
      I('data_replaceitemoflist', { fields: B.LISTF('IAttrType'), inputs: { INDEX: B.REP(F('cX'), [4, '0']), ITEM: B.REP(argOf('vt'), [4, '0']) } })
    ])
  ]);

  // ---------- pdrop : the scratch names only exist while a path write is in flight
  const pd = newProc('pdrop', []);
  const dropName = (nm) => [
    callProc('lookup %s', [txt(nm)]),
    IF(GT(F('found'), num(0)), [delAt('Names', F('found')), delAt('Values', F('found')), delAt('Types', F('found')), delAt('Show', F('found'))])
  ];
  attachBody(pd.defId, ['__recv', '__pi', '__pw', '__pv'].flatMap(dropName));

  // ---------- pathset lo hi vt vv
  const ps = newProc('pathset %s %s %s %s', ['lo', 'hi', 'vt', 'vv']);
  attachBody(ps.defId, [
    chgV('w7dep', num(1)),
    setV('w7v', argOf('vv')), setV('w7t', argOf('vt')),
    setV('w7lo', argOf('lo')), setV('w7hi', argOf('hi')),
    IFELSE(EQ(tokAt(F('w7hi')), txt(']')), [
      // the '[' that matches the final ']'
      setV('w7d', num(0)), setV('w7i', SUB(F('w7hi'), num(1))), setV('w7br', num(0)),
      REPEATU(OR(LT(F('w7i'), F('w7lo')), NOT(EQ(F('w7br'), num(0)))), [
        IF(EQ(tokAt(F('w7i')), txt(']')), [chgV('w7d', num(1))]),
        IF(EQ(tokAt(F('w7i')), txt('[')), [
          IFELSE(EQ(F('w7d'), num(0)), [setV('w7br', F('w7i'))], [chgV('w7d', num(-1))])
        ]),
        chgV('w7i', num(-1))
      ]),
      // indices are evaluated while this line's tokens are still live
      callProc('eval %s %s', [ADD(F('w7br'), num(1)), SUB(F('w7hi'), num(1))]),
      IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
      callProc('assign %s %s %s', [txt('__pi'), F('ev'), F('evtype')]),
      callProc('eval %s %s', [F('w7lo'), SUB(F('w7br'), num(1))]),
      IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
      IF(OR(EQ(F('evtype'), txt('T')), EQ(F('evtype'), txt('S'))), [
        // a tuple/string element cannot be written back: leave it alone (the mutation is lost,
        // exactly as it was before this patch) instead of inventing a new error
        STOPTHIS()
      ]),
      callProc('assign %s %s %s', [txt('__pw'), F('ev'), F('evtype')]),
      callProc('assign %s %s %s', [txt('__pv'), F('w7v'), F('w7t')]),
      // let indexset do the element write: escaping, dict keys and error wording live there
      setV('w7pc', VAR('pc')),
      callProc('tokenize %s', [txt('__pw[__pi]=__pv')]),
      callProc('indexset %s %s', [num(1), llen('Tok')]),
      IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
      callProc('lookup %s', [txt('__pw')]),
      setV('w7nv', item('Values', F('found'))), setV('w7nt', item('Types', F('found'))),
      callProc('tokenize %s', [item('Code', F('w7pc'))]),
      callProc('pathset %s %s %s %s', [F('w7lo'), SUB(F('w7br'), num(1)), F('w7nt'), F('w7nv')])
    ], [
      IFELSE(AND(EQ(tokAt(SUB(F('w7hi'), num(1))), txt('.')), EQ(item('Kind', F('w7hi')), txt('I'))), [
        setV('w7nm', tokAt(F('w7hi'))),
        callProc('eval %s %s', [F('w7lo'), SUB(F('w7hi'), num(2))]),
        IF(NOT(EQ(F('error'), txt(''))), [STOPTHIS()]),
        IF(NOT(EQ(F('evtype'), txt('O'))), [FAIL(txt('SyntaxError: attribute access')), STOPTHIS()]),
        callProc('aset %s %s %s %s', [F('ev'), F('w7nm'), F('w7t'), F('w7v')])
      ], [
        callProc('assign %s %s %s', [tokAt(F('w7lo')), F('w7v'), F('w7t')]),
        callProc('publish %s', [tokAt(F('w7lo'))])
      ])
    ]),
    chgV('w7dep', num(-1)),
    IF(EQ(F('w7dep'), num(0)), [callProc('pdrop')])
  ]);
  console.log('[P171] pvok / pathset / aset / pdrop registered');

  // ---------- (a) methodcall2: park the receiver, then write it back through the path
  {
    const m2 = defIdOf('methodcall2 %s %s %s');
    const MLO = () => argOf('lo');
    const MMDOT = () => argOf('mdot');
    const MHI = () => argOf('hi');
    const RB = () => SUB(argOf('mdot'), num(1));
    const runDispatch = () => [
      setV('mcpre', num(1)),
      callProc('methodcall %s %s', [RB(), MHI()]),
      setV('mcpre', num(0))
    ];
    BL()[m2].next = null;
    attachBody(m2, [
      callProc('eval %s %s', [MLO(), RB()]),
      IF(EQ(F('error'), txt('')), [
        setV('mcval', F('ev')), setV('mctype', F('evtype')),
        callProc('pvok %s %s', [MLO(), RB()]),
        IFELSE(EQ(F('w6ok'), num(1)), [
          setV('w8old', F('mcval')), setV('w8oldt', F('mctype')),
          callProc('assign %s %s %s', [txt('__recv'), F('mcval'), F('mctype')]),
          setV('w8sv', tokAt(RB())), setV('w8svk', item('Kind', RB())),
          setTok(RB(), txt('__recv')), setKind(RB(), txt('I')),
          ...runDispatch(),
          setTok(RB(), F('w8sv')), setKind(RB(), F('w8svk')),
          callProc('lookup %s', [txt('__recv')]),
          IF(AND(GT(F('found'), num(0)), NOT(EQ(item('Values', F('found')), F('w8old')))), [
            callProc('pathset %s %s %s %s', [MLO(), RB(), item('Types', F('found')), item('Values', F('found'))])
          ])
        ], runDispatch())
      ])
    ]);
    console.log('[P171] methodcall2 writes the receiver back through its path');
  }

  // ---------- (b) execute: statements whose lvalue has two or more accessors
  {
    const ex = inDef('execute');
    const idxIf = find(ex, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK
      && typeof b.inputs.SUBSTACK[1] === 'string'
      && BL()[b.inputs.SUBSTACK[1]].opcode === 'procedures_call'
      && BL()[b.inputs.SUBSTACK[1]].mutation && BL()[b.inputs.SUBSTACK[1]].mutation.proccode === 'indexset %s %s'
      && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string');
    if (idxIf.length !== 1) throw new Error('[P171] execute indexset branch = ' + idxIf.length);
    const T5 = () => tokAt(F('w5i'));
    insertBeforeStmt(idxIf[0], [IF(AND(EQ(item('Kind', num(1)), txt('I')), GT(F('count'), num(3))), [
      setV('w5d', num(0)), setV('w5eq', num(0)), setV('w5i', num(1)),
      REPEATU(GT(F('w5i'), F('count')), [
        setV('w5t', T5()),
        IF(OPEN(() => F('w5t')), [chgV('w5d', num(1))]),
        IF(CLOSE(() => F('w5t')), [chgV('w5d', num(-1))]),
        IF(AND(EQ(F('w5d'), num(0)), AND(EQ(F('w5t'), txt('=')), EQ(F('w5eq'), num(0)))), [setV('w5eq', F('w5i'))]),
        chgV('w5i', num(1))
      ]),
      IF(GT(F('w5eq'), num(3)), [
        callProc('pvok %s %s', [num(1), SUB(F('w5eq'), num(1))]),
        IF(AND(EQ(F('w6ok'), num(1)), GT(F('w6cap'), num(1))), [
          callProc('eval %s %s', [ADD(F('w5eq'), num(1)), F('count')]),
          IF(EQ(F('error'), txt('')), [
            callProc('pathset %s %s %s %s', [num(1), SUB(F('w5eq'), num(1)), F('evtype'), F('ev')]),
            setV('pending', num(1))
          ])
        ])
      ])
    ])]);
    console.log('[P171] execute: multi-accessor statements go through pathset');
  }
});

// ---- P172: `sum(xs, start)` (v4.99) ----
//
// `sum(xs)` works (the branch is in `callfn`'s builtin dispatch, reached when the call has no
// top-level comma), but `sum(xs, 10)` has one -- so it never reaches that branch and dies with
// `NameError: name 'sum' is not defined` from the multi-argument builtin path.
//
// P99 solved the same shape for `zip` with a hook in `eval` placed *in front of* the `narg`
// dispatch (that is the branch that evaluates a lone argument and hands the name to `callfn`).
// P172 adds one more hook there for `sum`: with exactly one top-level comma it evaluates the
// **start** first and parks it in `sstart`, then evaluates the sequence (so `ev`/`evtype` hold it),
// re-enters `callfn` on the sequence's span -- which runs the existing, already correct summation
// -- and finally adds the start to the result here.  Nothing inside the sum branch is touched, so
// every existing behaviour (sets, generators, the error wording) stays exactly as it was.
// The start has to be a number: CPython's `sum([1], 'a')` raises
// `TypeError: unsupported operand type(s) for +: 'int' and 'str'`, which is what this reports.
patch('P172 sum start', () => {
  const F = (v) => VAR(v);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['ssum', 'sstart', 'sstartt', 'ssum2']) {
    if (taken.has(n)) throw new Error('[P172] variable name taken: ' + n);
  }
  newVar('ssum', 0); newVar('sstart', 0); newVar('sstartt', ''); newVar('ssum2', 0);
  const hasDot = (x) => I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('.'), [10, '']) } });

  const ev = inDef('eval %s %s');
  const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
  const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') ? String(d[1])
    : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
  const nargIfe = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((id) => {
      const q = BL()[id];
      if (!q || q.opcode !== 'operator_equals') return false;
      return (vnOf(q.inputs.OPERAND1) === 'narg' && litOf(q.inputs.OPERAND2) === '0')
        || (vnOf(q.inputs.OPERAND2) === 'narg' && litOf(q.inputs.OPERAND1) === '0');
    }));
  if (nargIfe.length !== 1) throw new Error('[P172] eval narg dispatch = ' + nargIfe.length);

  const LO = () => argOf('lo');
  const first = () => ADD(argOf('lo'), num(2));
  const firstEnd = () => SUB(VAR('tqcpz'), num(1));
  const second = () => ADD(VAR('tqcpz'), num(1));
  const last = () => SUB(argOf('hi'), num(1));

  insertBeforeStmt(nargIfe[0], [
    IF(EQ(item('Tok', LO()), txt('sum')), [
      callProc('hascomma %s %s', [first(), last()]),
      IF(EQ(VAR('tqhcm'), num(1)), [
        // the start value
        callProc('eval %s %s', [second(), last()]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        IFELSE(NOT(EQ(VAR('evtype'), txt('N'))), [
          setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname'),
          callProc('fail %s', [JOIN(JOIN(txt("TypeError: unsupported operand type(s) for +: 'int' and '"), VAR('p6msg')), txt("'"))]),
          STOPTHIS()
        ], [
          setV('sstart', VAR('ev')), setV('sstartt', VAR('evtype'))
        ]),
        // the sequence: callfn runs the ordinary summation over this span
        callProc('eval %s %s', [first(), firstEnd()]),
        IF(EQ(VAR('error'), txt('')), [
          callProc('callfn %s %s %s', [txt('sum'), first(), firstEnd()]),
          IF(EQ(VAR('error'), txt('')), [
            setV('ssum', VAR('ev')),
            IFELSE(EQ(VAR('ssum'), num(0)), [
              setV('ev', VAR('sstart')), setV('evtype', VAR('sstartt'))
            ], [
              setV('ssum2', ADD(VAR('ssum'), VAR('sstart'))),
              // Scratch's + drops a trailing ".0", so a float result would print as an int
              IF(AND(NOT(hasDot(F('ssum2'))), OR(hasDot(F('ssum')), hasDot(F('sstart')))), [
                setV('ssum2', JOIN(VAR('ssum2'), txt('.0')))
              ]),
              setV('ev', VAR('ssum2')), setV('evtype', txt('N'))
            ])
          ])
        ]),
        chgV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ])
  ]);
  console.log('[P172] eval: sum(xs, start) hook installed');

  // ---------- reset on RUN
  {
    const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'AliasN');
    if (runInit.length !== 1) throw new Error('[P172] run init anchor = ' + runInit.length);
    insertBeforeStmt(runInit[0], [setV('sstart', num(0)), setV('sstartt', txt('N'))]);
  }
});

// ---- P173: `b = a[0]` then mutating `b` reaches `a[0]` (v4.100) ----
//
// An element read into a variable is a *copy* of the record string -- nothing links it back to the
// path it came from, so `a = [[1]]; b = a[0]; b.append(2)` left `a` at `[[1]]` (CPython: `[[1, 2]]`).
// P54's AliasN/AliasT only records name-to-name aliases and cannot express this.
//
// The first attempt stored the path as **tokens** and replayed them through P171's `pathset`; it
// kept corrupting the value, because installing tokens into the interpreter's global `Tok` and
// restoring them around nested writes is far too fragile (the write landed on the wrong name).
// P173 keeps no tokens at all:
//   * when `execute` sees `name = <path>` whose path is a base name plus **exactly one** accessor,
//     it evaluates the accessor *right there* and stores it as a value -- `[` gets the index value
//     and type, `.` gets the attribute name.  Evaluating at record time is also closer to Python:
//     the alias points at the slot that was read, not at whatever the index expression means later;
//   * the alias table is `PthN`/`PthB` (name / base name) plus `PthS`/`PthK` (position and length in
//     the accessor table `PtM`/`PtT`/`PtY` = mode / text / type);
//   * writing back is pure value surgery: `lsetv` splices a new element into a list record,
//     `dsetv` rebuilds a dict record with one key replaced or appended, and an attribute goes into
//     the IAttr heap with P171's `aset`.  Then `assign(base, ...)` plus `publish(base)` so the
//     enclosing function frames see it too (P169).
// Multi-accessor paths (`b = a[0][1]`) and paths whose base is not a plain name (`b = f()[0]`) are
// deliberately not recorded -- those keep the old behaviour instead of risking a wrong write.
// A rebinding drops the alias (`aldrop` is hooked) and everything is cleared on RUN.
patch('P173 path aliases', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const kindAt = (i) => item('Kind', i);
  const delAt = (list, i) => I('data_deleteoflist', { fields: B.LISTF(list), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });

  const takenV = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p10i', 'p10x', 'p10c', 'p10m', 'p10a', 'p10f', 'p10b', 'p10s', 'p10v', 'p10t', 'p10dep', 'p10ok',
    'p11s', 'p11n', 'p11i', 'p11c', 'p11a', 'p11b', 'p11x', 'p11e', 'p11r',
    'p11n2', 'p11p', 'p11k', 'p11kt', 'p11acc', 'p11f', 'p11m', 'p11v', 'p11t', 'p11k2', 'p11k2t']) {
    if (takenV.has(n)) throw new Error('[P173] variable name taken: ' + n);
    newVar(n, 0);
  }
  const takenL = new Set(Object.values(T(IT).lists).map((x) => x[0]));
  for (const l of ['PthN', 'PthB', 'PthS', 'PthK', 'PtM', 'PtT', 'PtY']) {
    if (takenL.has(l)) throw new Error('[P173] list name taken: ' + l);
    B.addList(IT, l, []);
  }

  // ---------- lsetv <rec> <idx> <vt> <vv>: replace one element of a list record
  const ls = newProc('lsetv %s %s %s %s', ['s', 'idx', 'vt', 'vv']);
  attachBody(ls.defId, [
    setV('p11s', argOf('s')),
    callProc('listlen %s', [F('p11s')]), setV('p11n', F('ev')),
    setV('p11i', argOf('idx')),
    IF(LT(F('p11i'), num(0)), [chgV('p11i', F('p11n'))]),
    IF(OR(LT(F('p11i'), num(0)), NOT(LT(F('p11i'), F('p11n')))), [
      FAIL(txt('IndexError: list assignment index out of range')), STOPTHIS()
    ]),
    setV('p11c', num(0)), setV('p11a', num(0)), setV('p11b', num(0)), setV('p11x', num(1)),
    REPEATU(OR(GT(F('p11x'), lenOf(F('p11s'))), GT(F('p11b'), num(0))), [
      IF(EQ(letterOf(F('p11x'), F('p11s')), VAR('lsep')), [
        chgV('p11c', num(1)),
        IF(EQ(F('p11c'), ADD(F('p11i'), num(1))), [setV('p11a', F('p11x'))]),
        IF(EQ(F('p11c'), ADD(F('p11i'), num(2))), [setV('p11b', F('p11x'))])
      ]),
      chgV('p11x', num(1))
    ]),
    IF(EQ(F('p11b'), num(0)), [setV('p11b', ADD(lenOf(F('p11s')), num(1)))]),
    callProc('lesc %s', [argOf('vv')]), setV('p11e', F('ev')),
    callProc('substr %s %s %s', [F('p11s'), num(1), SUB(F('p11a'), num(1))]),
    setV('p11r', F('ev')),
    callProc('substr %s %s %s', [F('p11s'), F('p11b'), lenOf(F('p11s'))]),
    setV('ev', JOIN(JOIN(JOIN(JOIN(F('p11r'), VAR('lsep')), argOf('vt')), F('p11e')), F('ev'))),
    setV('evtype', txt('L'))
  ]);

  // ---------- dsetv <rec> <key> <kt> <vt> <vv>: rebuild a dict record with one pair replaced
  const ds = newProc('dsetv %s %s %s %s %s', ['s', 'key', 'kt', 'vt', 'vv']);
  const encPair = (acc, kt, ke, vt, ve) => JOIN(JOIN(JOIN(JOIN(JOIN(JOIN(acc, VAR('lsep')), kt), ke), VAR('lsep')), vt), ve);
  attachBody(ds.defId, [
    setV('p11s', argOf('s')), setV('p11k', argOf('key')), setV('p11kt', argOf('kt')),
    setV('p11acc', txt('')), setV('p11f', num(0)),
    callProc('listlen %s', [F('p11s')]), setV('p11n2', F('ev')),
    setV('p11p', num(1)),
    REPEATU(NOT(LT(F('p11p'), F('p11n2'))), [
      callProc('listitem %s %s', [F('p11s'), F('p11p')]),
      setV('p11k2', F('ev')), setV('p11k2t', F('evtype')),
      callProc('listitem %s %s', [F('p11s'), ADD(F('p11p'), num(1))]),
      setV('p11v', F('ev')), setV('p11t', F('evtype')),
      setV('p11m', num(0)),
      IF(EQ(F('p11k2t'), F('p11kt')), [
        IFELSE(EQ(F('p11k2t'), txt('S')), [
          callProc('compareText %s %s', [F('p11k2'), F('p11k')]),
          IF(EQ(VAR('cmp'), num(0)), [setV('p11m', num(1))])
        ], [
          IF(EQ(F('p11k2'), F('p11k')), [setV('p11m', num(1))])
        ])
      ]),
      IF(EQ(F('p11m'), num(1)), [
        setV('p11v', argOf('vv')), setV('p11t', argOf('vt')), setV('p11f', num(1))
      ]),
      callProc('lesc %s', [F('p11k2')]), setV('p11e', F('ev')),
      callProc('lesc %s', [F('p11v')]),
      setV('p11acc', encPair(F('p11acc'), F('p11k2t'), F('p11e'), F('p11t'), F('ev'))),
      chgV('p11p', num(2))
    ]),
    IF(EQ(F('p11f'), num(0)), [
      callProc('lesc %s', [F('p11k')]), setV('p11e', F('ev')),
      callProc('lesc %s', [argOf('vv')]),
      setV('p11acc', encPair(F('p11acc'), argOf('kt'), F('p11e'), argOf('vt'), F('ev')))
    ]),
    setV('ev', F('p11acc')), setV('evtype', txt('D'))
  ]);

  // ---------- paldrop <name>
  const pd = newProc('paldrop %s', ['vn']);
  attachBody(pd.defId, [
    setV('p10i', num(1)),
    REPEATU(GT(F('p10i'), llen('PthN')), [
      IFELSE(EQ(item('PthN', F('p10i')), argOf('vn')), [
        delAt('PthN', F('p10i')), delAt('PthB', F('p10i')), delAt('PthS', F('p10i')), delAt('PthK', F('p10i'))
      ], [
        chgV('p10i', num(1))
      ])
    ])
  ]);

  // ---------- palwrite <name>
  const pw = newProc('palwrite %s', ['vn']);
  attachBody(pw.defId, [
    IF(LT(F('p10dep'), num(4)), [
      chgV('p10dep', num(1)),
      setV('p10f', num(0)), setV('p10b', txt('')), setV('p10s', num(0)), setV('p10i', num(1)),
      REPEATU(GT(F('p10i'), llen('PthN')), [
        // entries are a stack: the innermost binding of this name wins
        IF(EQ(item('PthN', F('p10i')), argOf('vn')), [
          setV('p10f', num(1)),
          setV('p10b', item('PthB', F('p10i'))),
          setV('p10s', item('PthS', F('p10i')))
        ]),
        chgV('p10i', num(1))
      ]),
      IF(EQ(F('p10f'), num(1)), [
        callProc('lookup %s', [argOf('vn')]),
        IF(GT(F('found'), num(0)), [
          setV('p10v', item('Values', F('found'))), setV('p10t', item('Types', F('found'))),
          callProc('lookup %s', [F('p10b')]),
          IF(GT(F('found'), num(0)), [
            IFELSE(EQ(item('PtM', F('p10s')), txt('[')), [
              // `name[i] = v`
              IFELSE(EQ(item('Types', F('found')), txt('D')), [
                callProc('dsetv %s %s %s %s %s', [item('Values', F('found')), item('PtT', F('p10s')), item('PtY', F('p10s')), F('p10t'), F('p10v')]),
                callProc('assign %s %s %s', [F('p10b'), F('ev'), txt('D')]),
                callProc('publish %s', [F('p10b')])
              ], [
                IFELSE(EQ(item('Types', F('found')), txt('L')), [
                  callProc('lsetv %s %s %s %s', [item('Values', F('found')), item('PtT', F('p10s')), F('p10t'), F('p10v')]),
                  callProc('assign %s %s %s', [F('p10b'), F('ev'), txt('L')]),
                  callProc('publish %s', [F('p10b')])
                ], [
                  // tuples and strings cannot be written into: leave them as they were
                  STOPTHIS()
                ])
              ])
            ], [
              // `name.attr = v` -- the attribute table is a heap, so this needs no write-back
              IFELSE(EQ(item('Types', F('found')), txt('O')), [
                callProc('aset %s %s %s %s', [item('Values', F('found')), item('PtT', F('p10s')), F('p10t'), F('p10v')])
              ], [
                STOPTHIS()
              ])
            ])
          ])
        ])
      ]),
      // P54's name aliases (c = b) have to travel too: the mutation reaches  inside ssign,
      // which does not publish, so walk the pairs here (the depth guard bounds the recursion)
      setV('p10i', num(1)),
      REPEATU(GT(F('p10i'), llen('AliasN')), [
        IF(AND(EQ(item('AliasN', F('p10i')), argOf('vn')), NOT(EQ(item('AliasT', F('p10i')), argOf('vn')))), [
          callProc('palwrite %s', [item('AliasT', F('p10i'))])
        ]),
        IF(AND(EQ(item('AliasT', F('p10i')), argOf('vn')), NOT(EQ(item('AliasN', F('p10i')), argOf('vn')))), [
          callProc('palwrite %s', [item('AliasN', F('p10i'))])
        ]),
        chgV('p10i', num(1))
      ]),
      chgV('p10dep', num(-1))
    ])
  ]);
  console.log('[P173] lsetv / dsetv / paldrop / palwrite registered');

  // ---------- a rebinding drops the path alias
  {
    const ad = defIdOf('aldrop %s');
    const first = BL()[ad].next;
    if (!first) throw new Error('[P173] aldrop body missing');
    insertBeforeStmt(first, [callProc('paldrop %s', [argOf('vn')])]);
  }

  // ---------- every mutating write-back publishes, so hook publish
  {
    const pub = defIdOf('publish %s');
    const body = BL()[pub].next;
    if (!body) throw new Error('[P173] publish body missing');
    insertBeforeStmt(body, [callProc('palwrite %s', [argOf('vn')])]);
  }

  // ---------- execute: record `name = <base><one accessor>`
  {
    const idOf = (d) => (typeof d === 'string') ? d : ((d && typeof d[1] === 'string') ? d[1] : null);
    const reachSet = (root) => {
      const seen = new Set(); const st = [root];
      while (st.length) {
        const id = st.pop();
        if (!id || seen.has(id)) continue;
        const b = BL()[id];
        if (!b) continue;
        seen.add(id);
        for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') st.push(v[1]);
        if (b.next) st.push(b.next);
      }
      return seen;
    };
    const subOf = (id) => (BL()[id].inputs.SUBSTACK && typeof BL()[id].inputs.SUBSTACK[1] === 'string')
      ? reachSet(BL()[id].inputs.SUBSTACK[1]) : new Set();
    const litOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
      if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
      return null;
    };
    const tokIs = (d, idx) => {
      const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
      if (!b || b.opcode !== 'data_itemoflist' || !b.fields.LIST || b.fields.LIST[0] !== 'Tok') return false;
      const ix = b.inputs.INDEX;
      return (Array.isArray(ix) && ix[0] === 4 && String(ix[1]) === String(idx))
        || (Array.isArray(ix[1]) && ix[1][0] === 4 && String(ix[1][1]) === String(idx));
    };
    const withIds = [];
    for (const id of reachSet(defIdOf('execute'))) {
      const b = BL()[id];
      if (b.opcode !== 'control_if') continue;
      const c = idOf(b.inputs.CONDITION);
      if (!c) continue;
      let hit = false;
      for (const x of reachSet(c)) {
        const q = BL()[x];
        if (!q || q.opcode !== 'operator_equals') continue;
        const la = litOf(q.inputs.OPERAND1), lb = litOf(q.inputs.OPERAND2);
        if ((tokIs(q.inputs.OPERAND1, 2) && lb === '=') || (tokIs(q.inputs.OPERAND2, 2) && la === '=')) hit = true;
      }
      if (hit) withIds.push(id);
    }
    const asgBranch = withIds.filter((id) => [...subOf(id)].some((x) => {
      const q = BL()[x];
      return q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'assign %s %s %s';
    }));
    if (asgBranch.length !== 1) throw new Error('[P173] execute assignment branch = ' + asgBranch.length + ' (cands ' + withIds.length + ')');
    const asgCalls = [...subOf(asgBranch[0])].filter((x) => {
      const q = BL()[x];
      return q.opcode === 'procedures_call' && q.mutation && q.mutation.proccode === 'assign %s %s %s';
    });
    if (asgCalls.length !== 1) throw new Error('[P173] assignment assign call = ' + asgCalls.length);

    // the accessor walk: p10m = 0 (nothing yet) / 1 (recorded) / 2 (give up)
    const scan = [
      setV('p10m', num(0)), setV('p10x', num(4)), setV('p10ok', num(0)),
      REPEATU(OR(GT(F('p10x'), F('count')), NOT(EQ(F('p10m'), num(0)))), [
        IFELSE(EQ(tokAt(F('p10x')), txt('[')), [
          setV('p10a', F('p10x')), setV('p10c', num(1)),
          chgV('p10x', num(1)),
          REPEATU(OR(GT(F('p10x'), F('count')), EQ(F('p10c'), num(0))), [
            IF(OR(EQ(tokAt(F('p10x')), txt('[')), EQ(tokAt(F('p10x')), txt('{'))), [chgV('p10c', num(1))]),
            IF(OR(EQ(tokAt(F('p10x')), txt(']')), EQ(tokAt(F('p10x')), txt('}'))), [chgV('p10c', num(-1))]),
            chgV('p10x', num(1))
          ]),
          IFELSE(EQ(F('p10c'), num(0)), [
            callProc('eval %s %s', [ADD(F('p10a'), num(1)), SUB(F('p10x'), num(2))]),
            IF(EQ(F('error'), txt('')), [
              addTo('PtM', txt('[')), addTo('PtT', F('ev')), addTo('PtY', F('evtype')),
              setV('p10m', num(1)), setV('p10ok', num(1))
            ]),
            IF(NOT(EQ(F('error'), txt(''))), [setV('p10m', num(2)), setV('error', txt(''))])
          ], [
            setV('p10m', num(2))
          ])
        ], [
          IFELSE(AND(EQ(tokAt(F('p10x')), txt('.')), EQ(kindAt(ADD(F('p10x'), num(1))), txt('I'))), [
            addTo('PtM', txt('.')), addTo('PtT', tokAt(ADD(F('p10x'), num(1)))), addTo('PtY', txt('')),
            setV('p10m', num(1)), setV('p10ok', num(1)),
            chgV('p10x', num(1))
          ], [
            setV('p10m', num(2))
          ])
        ])
      ]),
      IF(EQ(F('p10ok'), num(1)), [
        callProc('paldrop %s', [VAR('name')]),
        addTo('PthN', VAR('name')), addTo('PthB', tokAt(num(3))),
        addTo('PthS', llen('PtM')), addTo('PthK', num(1))
      ])
    ];

    spliceAfter(asgCalls[0], chain([
      callProc('pvok %s %s', [num(3), F('count')]),
      IF(AND(EQ(F('w6ok'), num(1)), EQ(F('w6cap'), num(1))), [
        IF(EQ(kindAt(num(3)), txt('I')), [
          ...scan
        ])
      ])
    ]));
    console.log('[P173] execute records single-accessor path aliases');
  }

  // ---------- clear on RUN (same anchor P54 and P172 use)
  {
    const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'AliasN');
    if (runInit.length !== 1) throw new Error('[P173] run init anchor = ' + runInit.length);
    spliceAfter(runInit[0], chain([
      clearL('PthN'), clearL('PthB'), clearL('PthS'), clearL('PthK'), clearL('PtM'), clearL('PtT'), clearL('PtY')
    ]));
  }
});

// ---- P174: rfind / rindex / casefold / strip(字符集) (v4.101) ----
//
// Four gaps left in the string surface:
//   * `rfind` / `rindex` do not exist at all (`'abc'.rfind('b')` -> AttributeError);
//   * `casefold()` likewise -- and in an ASCII-only interpreter it is exactly `lower()`;
//   * `strip` / `lstrip` / `rstrip` only know "whitespace": P167's `strim` has no character set, so
//     `'xxabcxx'.strip('x')` returns the string unchanged (`strip(字符集)` was documented as a gap).
// The string dispatch is the list of `if smmeth == "name"` branches P18 installed at the end of
// `methodcall`'s S section, followed by a guard `if not <known names> then AttributeError`; the
// first argument is already in `sma1` and the comma position in `mcut`, so:
//   * `srfind` walks the record backwards with `substr` + `compareText` (Scratch's `=` ignores
//     case, so a content test has to go through `compareText`);
//   * the character-set trim uses `sinstr` -- a case-sensitive "is this character in the set"
//     loop -- because `contains` is case-insensitive too;
//   * the guard's condition tree is wrapped the same way P75 did it (its anchor is the
//     `not smmeth == "join"` inside that very guard);
//   * the argument-less forms of strip/lstrip/rstrip keep going to P167's `strim`.
patch('P174 string methods 4', () => {
  const F = (v) => VAR(v);
  const tokAt = (i) => item('Tok', i);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['r2i', 'r2f', 'r2l', 's8a', 's8b', 's8i', 's8f']) {
    if (taken.has(n)) throw new Error('[P174] variable name taken: ' + n);
    newVar(n, 0);
  }

  // ---------- sinstr <char> <set>: case-sensitive membership (sets s8f)
  const si = newProc('sinstr %s %s', ['ch', 'set']);
  attachBody(si.defId, [
    setV('s8f', num(0)), setV('s8i', num(1)),
    REPEATU(OR(GT(F('s8i'), lenOf(argOf('set'))), EQ(F('s8f'), num(1))), [
      callProc('compareText %s %s', [letterOf(F('s8i'), argOf('set')), argOf('ch')]),
      IF(EQ(VAR('cmp'), num(0)), [setV('s8f', num(1))]),
      chgV('s8i', num(1))
    ])
  ]);

  // ---------- strim2 <v> <set> <mode>: strip any of the characters in <set>
  const s2 = newProc('strim2 %s %s %s', ['v', 'set', 'mode']);
  attachBody(s2.defId, [
    setV('s8a', num(1)), setV('s8b', lenOf(argOf('v'))),
    // prime the flag: the loop's exit test reads the result of the previous round
    setV('s8f', num(1)),
    IF(NOT(EQ(argOf('mode'), txt('r'))), [
      REPEATU(OR(GT(F('s8a'), F('s8b')), NOT(EQ(F('s8f'), num(1)))), [
        IF(NOT(GT(F('s8a'), F('s8b'))), [
          callProc('sinstr %s %s', [letterOf(F('s8a'), argOf('v')), argOf('set')])
        ]),
        IF(EQ(F('s8f'), num(1)), [chgV('s8a', num(1))])
      ])
    ]),
    setV('s8f', num(1)),
    IF(NOT(EQ(argOf('mode'), txt('l'))), [
      REPEATU(OR(LT(F('s8b'), F('s8a')), NOT(EQ(F('s8f'), num(1)))), [
        IF(NOT(LT(F('s8b'), F('s8a'))), [
          callProc('sinstr %s %s', [letterOf(F('s8b'), argOf('v')), argOf('set')])
        ]),
        IF(EQ(F('s8f'), num(1)), [chgV('s8b', num(-1))])
      ])
    ]),
    IFELSE(LT(F('s8b'), F('s8a')),
      [setV('ev', txt('')), setV('evtype', txt('S'))],
      [callProc('substr %s %s %s', [argOf('v'), F('s8a'), F('s8b')])])
  ]);

  // ---------- srfind <rec> <needle>: the highest 0-based index, or -1 (empty needle -> len)
  const sr = newProc('srfind %s %s', ['s', 'p']);
  attachBody(sr.defId, [
    setV('r2f', num(-1)),
    IFELSE(EQ(lenOf(argOf('p')), num(0)), [
      setV('r2f', lenOf(argOf('s')))
    ], [
      setV('r2l', lenOf(argOf('p'))),
      // 1-based: the last start that can still fit the needle is len(s) - len(p) + 1
      setV('r2i', ADD(SUB(lenOf(argOf('s')), lenOf(argOf('p'))), num(1))),
      REPEATU(OR(LT(F('r2i'), num(1)), NOT(EQ(F('r2f'), num(-1)))), [
        IF(NOT(LT(F('r2i'), num(1))), [
          callProc('substr %s %s %s', [argOf('s'), F('r2i'), SUB(ADD(F('r2i'), F('r2l')), num(1))]),
          callProc('compareText %s %s', [F('ev'), argOf('p')]),
          IF(EQ(VAR('cmp'), num(0)), [setV('r2f', SUB(F('r2i'), num(1)))])
        ]),
        chgV('r2i', num(-1))
      ])
    ]),
    setV('ev', F('r2f')), setV('evtype', txt('N'))
  ]);
  console.log('[P174] sinstr / strim2 / srfind registered');

  // ---------- the dispatch branches, in front of the "known names" guard
  {
    const mc = (() => {
      for (const id of allIds()) {
        const b = BL()[id];
        if (b.opcode === 'procedures_definition' && b.inputs && b.inputs.custom_block) {
          const pr = BL()[b.inputs.custom_block[1]];
          if (pr && pr.mutation && pr.mutation.proccode === 'methodcall %s %s') return id;
        }
      }
      throw new Error('[P174] methodcall not found');
    })();
    const litOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
      if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
      return null;
    };
    // NB: P75 already wrapped this condition in `and(not(...), not(...))`, so the guard's top block
    // is no longer the `not` -- locate the `not` itself and then the `if` that contains it.
    const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
    const eqJoin = (id) => {
      const e = BL()[id];
      if (!e || e.opcode !== 'operator_equals') return false;
      return (vnOf(e.inputs.OPERAND1) === 'smmeth' && litOf(e.inputs.OPERAND2) === 'join')
        || (vnOf(e.inputs.OPERAND2) === 'smmeth' && litOf(e.inputs.OPERAND1) === 'join');
    };
    const mcReach = reach(mc);
    let notId = null, guardId = null;
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'operator_not' && [...reach(id)].some(eqJoin)) { notId = id; break; }
    }
    if (!notId) throw new Error('[P174] not(known names) not found');
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'control_if' && q.inputs.CONDITION && typeof q.inputs.CONDITION[1] === 'string'
        && reach(q.inputs.CONDITION[1]).has(notId)) { guardId = id; break; }
    }
    if (!guardId) throw new Error('[P174] guard if not found');
    const guard = [guardId];
    insertBeforeStmt(guard[0], [
      IF(EQ(F('smmeth'), txt('rfind')), [callProc('srfind %s %s', [F('smrec'), F('sma1')])]),
      IF(EQ(F('smmeth'), txt('rindex')), [
        callProc('srfind %s %s', [F('smrec'), F('sma1')]),
        IF(LT(F('ev'), num(0)), [FAIL(txt('ValueError: substring not found'))])
      ]),
      IF(EQ(F('smmeth'), txt('casefold')), [callProc('scase %s %s', [F('smrec'), txt('lower')])]),
      // strip(字符集) -- only when an argument is actually there; otherwise P167's strim
      // there is a real argument when the span between ( and ) is not empty
      IF(AND(NOT(GT(ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1)))), OR(EQ(F('smmeth'), txt('strip')), OR(EQ(F('smmeth'), txt('lstrip')), EQ(F('smmeth'), txt('rstrip'))))), [
        IFELSE(EQ(F('smmeth'), txt('strip')), [
          callProc('strim2 %s %s %s', [F('smrec'), F('sma1'), txt('b')])
        ], [
          IFELSE(EQ(F('smmeth'), txt('lstrip')), [
            callProc('strim2 %s %s %s', [F('smrec'), F('sma1'), txt('l')])
          ], [
            callProc('strim2 %s %s %s', [F('smrec'), F('sma1'), txt('r')])
          ])
        ]),
        setV('pending', num(1))
      ])
    ]);
    const knownNew = OR(EQ(F('smmeth'), txt('rfind')), OR(EQ(F('smmeth'), txt('rindex')), EQ(F('smmeth'), txt('casefold'))));
    replaceExpr(notId, () => AND(notId, NOT(knownNew)));
    console.log('[P174] methodcall accepts rfind / rindex / casefold');
  }
});

// ---- P175: `enumerate(xs, start)` (v4.102) ----
//
// P99 installed `enumerate(xs)` inside `callfn`: the single argument arrives already evaluated
// (`ev`/`evtype`) and one branch builds `[(i, xs[i]), ...]` with the index expression
// `xsi - 1`.  The two-argument form never gets there -- `eval`'s `narg == 0` branch is the one that
// evaluates a lone argument and hands the name to `callfn`, so `enumerate(xs, 5)` fell through to
// the multi-argument builtin dispatch and died with `NameError: name 'enumerate' is not defined`.
//
// Two changes, mirroring what P172 did for `sum(xs, start)`:
//   * the builder's index expression gains a global offset `enoff` (`xsi - 1 + enoff`);
//   * `eval` gets one more hook in front of the `narg` dispatch (where P99's `zip` hook and P172's
//     `sum` hook already sit): with exactly one top-level comma it evaluates the *start* first,
//     checks it is an integer, parks it in `enoff`, then evaluates the sequence (so `ev`/`evtype`
//     hold it) and re-enters `callfn` on the sequence's span.
// CPython wants a real int (`enumerate('ab', 1.0)` is a TypeError); a float -- recognised by a `.`
// in the text, the same test P172/P170 use -- is rejected.
//
// NB the earlier attempt to find the builder searched `JSON.stringify(VALUE)` for `xsi` and found
// nothing: a variable inside a nested JOIN lives in the *child* block, so the search has to walk the
// expression tree.
patch('P175 enumerate start', () => {
  const F = (v) => VAR(v);
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['enoff', 'e2c', 'e2p', 'e2d', 'e2i', 'e2t']) {
    if (taken.has(n)) throw new Error('[P175] variable name taken: ' + n);
  }
  B.addVar(IT, 'enoff', 0);
  for (const n of ['e2c', 'e2p', 'e2d', 'e2i', 'e2t']) newVar(n, 0);

  // ---------- the builder adds the offset
  {
    const cf = inDef('callfn %s %s %s');
    const walkIds = (root) => {
      const seen = new Set(); const st = [root];
      while (st.length) {
        const id = st.pop();
        if (!id || seen.has(id)) continue;
        const b = BL()[id];
        if (!b) continue;
        seen.add(id);
        if (b.inputs) for (const v of Object.values(b.inputs)) if (v && typeof v[1] === 'string') st.push(v[1]);
      }
      return seen;
    };
    // NB an inline variable is `[12,name,id]` *or* `[3,[12,name,id],shadow]` -- both shapes occur,
    // and a variable inside a nested JOIN lives in a child block, so this has to walk the tree.
    const inlineVar = (v) => {
      if (!Array.isArray(v)) return null;
      if (v[0] === 12) return v[1];
      if (Array.isArray(v[1]) && v[1][0] === 12) return v[1][1];
      return null;
    };
    const mentions = (root, vn) => [...walkIds(root)].some((id) => {
      const b = BL()[id];
      if (b.opcode === 'data_variable' && b.fields.VARIABLE[0] === vn) return true;
      return Object.values(b.inputs || {}).some((v) => inlineVar(v) === vn);
    });
    const joins = find(cf, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'xsp' && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string'
      && mentions(b.inputs.VALUE[1], 'xsi'));
    if (joins.length !== 1) throw new Error('[P175] enumerate index join = ' + joins.length);
    const subs = [...walkIds(BL()[joins[0]].inputs.VALUE[1])].filter((x) => BL()[x].opcode === 'operator_subtract'
      && mentions(x, 'xsi'));
    if (subs.length !== 1) throw new Error('[P175] xsi subtract = ' + subs.length);
    replaceExpr(subs[0], () => ADD(SUB(F('xsi'), num(1)), F('enoff')));
    console.log('[P175] enumerate index carries the offset');
  }

  // ---------- eval: the two-argument hook, in front of the narg dispatch
  {
    const ev = inDef('eval %s %s');
    const vnOf = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
      : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
    const litOf = (d) => (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') ? String(d[1])
      : (d && Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4) ? String(d[1][1]) : null);
    const nargIfe = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && [...reach(b.inputs.CONDITION[1])].some((id) => {
        const q = BL()[id];
        if (!q || q.opcode !== 'operator_equals') return false;
        return (vnOf(q.inputs.OPERAND1) === 'narg' && litOf(q.inputs.OPERAND2) === '0')
          || (vnOf(q.inputs.OPERAND2) === 'narg' && litOf(q.inputs.OPERAND1) === '0');
      }));
    if (nargIfe.length !== 1) throw new Error('[P175] eval narg dispatch = ' + nargIfe.length);
    const notInt = () => [
      setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname'),
      callProc('fail %s', [JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object cannot be interpreted as an integer"))]),
      STOPTHIS()
    ];
    insertBeforeStmt(nargIfe[0], [
      IF(EQ(item('Tok', argOf('lo')), txt('enumerate')), [
        // own depth-aware comma scan: hascomma does not count braces, so numerate(f({1: 2}), 3) would split wrong
        setV('e2c', num(0)), setV('e2p', num(0)), setV('e2d', num(0)), setV('e2i', ADD(argOf('lo'), num(2))),
        REPEATU(GT(F('e2i'), SUB(argOf('hi'), num(1))), [
          setV('e2t', item('Tok', F('e2i'))),
          IF(OR(OR(EQ(F('e2t'), txt('(')), EQ(F('e2t'), txt('['))), EQ(F('e2t'), txt('{'))), [chgV('e2d', num(1))]),
          IF(OR(OR(EQ(F('e2t'), txt(')')), EQ(F('e2t'), txt(']'))), EQ(F('e2t'), txt('}'))), [chgV('e2d', num(-1))]),
          IF(AND(EQ(F('e2d'), num(0)), EQ(F('e2t'), txt(','))), [
            chgV('e2c', num(1)),
            IF(EQ(F('e2c'), num(1)), [setV('e2p', F('e2i'))])
          ]),
          chgV('e2i', num(1))
        ]),
        IF(AND(EQ(F('e2c'), num(1)), GT(F('e2p'), num(0))), [
          // the start value
          callProc('eval %s %s', [ADD(F('e2p'), num(1)), SUB(argOf('hi'), num(1))]),
          IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
          IFELSE(NOT(EQ(VAR('evtype'), txt('N'))), notInt(), [
            IF(I('operator_contains', { inputs: { STRING1: B.REP(VAR('ev'), [10, '']), STRING2: B.REP(txt('.'), [10, '']) } }), notInt())
          ]),
          setV('enoff', VAR('ev')),
          // the sequence: callfn's own enumerate branch builds the pairs
          callProc('eval %s %s', [ADD(argOf('lo'), num(2)), SUB(F('e2p'), num(1))]),
          IF(EQ(VAR('error'), txt('')), [
            callProc('callfn %s %s %s', [txt('enumerate'), ADD(argOf('lo'), num(2)), SUB(F('e2p'), num(1))])
          ]),
          setV('enoff', num(0)),
          chgV('fnlimit', num(-1)),
          STOPTHIS()
        ])
      ])
    ]);
    console.log('[P175] eval: enumerate(xs, start) hook installed');
  }

  // ---------- reset the offset on RUN
  {
    const runInit = find(allIds(), (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'AliasN');
    if (runInit.length !== 1) throw new Error('[P175] run init anchor = ' + runInit.length);
    insertBeforeStmt(runInit[0], [setV('enoff', num(0))]);
  }
});

// ---- P176: bin() / hex() / oct() (v4.103) ----
//
// The three radix constructors were missing entirely (`bin(5)` -> `NameError: name 'bin' is not
// defined`), even though `'%x' % 255` and `int('ff', 16)` already worked.  CPython spells them
// `0b101` / `0xff` / `0o10`, with a `-` in front of the prefix for negative values, and raises
// `TypeError: 'float' object cannot be interpreted as an integer` for a non-integer.
//
// The builtins live in `callfn`'s `if fn == "name"` chain, where the single argument is already in
// `ev`/`evtype` and a branch finishes by setting `pending` (that is where P13 put `sorted`).  P176
// adds one branch there plus a small `radix value base digits` helper that keeps dividing by the
// base and picks characters out of the digit string.
patch('P176 bin/hex/oct', () => {
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['r3v', 'r3a', 'r3x', 'r3r', 'r3n', 'r3p']) {
    if (taken.has(n)) throw new Error('[P176] variable name taken: ' + n);
    newVar(n, 0);
  }
  const hasDot = (x) => I('operator_contains', { inputs: { STRING1: B.REP(x, [10, '']), STRING2: B.REP(txt('.'), [10, '']) } });
  const notInt = () => [
    setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname'),
    callProc('fail %s', [JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object cannot be interpreted as an integer"))])
  ];

  // ---------- radix <value> <base> <digits>: the digits of a non-negative integer
  const rd = newProc('radix %s %s %s', ['v', 'base', 'digs']);
  attachBody(rd.defId, [
    setV('r3x', argOf('v')), setV('r3a', txt('')),
    IFELSE(EQ(F('r3x'), num(0)), [
      setV('r3a', txt('0'))
    ], [
      REPEATU(LT(F('r3x'), argOf('base')), [
        setV('r3r', MOD(F('r3x'), argOf('base'))),
        setV('r3a', JOIN(letterOf(ADD(F('r3r'), num(1)), argOf('digs')), F('r3a'))),
        setV('r3x', FLOOR(DIV(F('r3x'), argOf('base'))))
      ]),
      setV('r3a', JOIN(letterOf(ADD(F('r3x'), num(1)), argOf('digs')), F('r3a')))
    ]),
    setV('ev', F('r3a')), setV('evtype', txt('S'))
  ]);

  // ---------- the builtin branch
  {
    const cf = inDef('callfn %s %s %s');
    const pendingIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1]
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'pending');
    if (pendingIf.length !== 1) throw new Error('[P176] callfn pending guard = ' + pendingIf.length);
    insertBeforeStmt(pendingIf[0], [
      IF(OR(OR(EQ(argOf('fn'), txt('bin')), EQ(argOf('fn'), txt('hex'))), EQ(argOf('fn'), txt('oct'))), [
        IFELSE(NOT(EQ(F('evtype'), txt('N'))), notInt(), [
          IF(hasDot(F('ev')), notInt()),
          setV('r3n', txt('')), setV('r3v', F('ev')),
          IF(LT(F('r3v'), num(0)), [setV('r3n', txt('-')), setV('r3v', MUL(F('r3v'), num(-1)))]),
          IFELSE(EQ(argOf('fn'), txt('bin')), [
            callProc('radix %s %s %s', [F('r3v'), num(2), txt('01')])
          ], [
            IFELSE(EQ(argOf('fn'), txt('hex')), [
              callProc('radix %s %s %s', [F('r3v'), num(16), txt('0123456789abcdef')])
            ], [
              callProc('radix %s %s %s', [F('r3v'), num(8), txt('01234567')])
            ])
          ]),
          IFELSE(EQ(argOf('fn'), txt('bin')), [
            setV('r3p', txt('0b'))
          ], [
            IFELSE(EQ(argOf('fn'), txt('hex')), [setV('r3p', txt('0x'))], [setV('r3p', txt('0o'))])
          ]),
          setV('ev', JOIN(JOIN(F('r3n'), F('r3p')), F('ev'))),
          setV('evtype', txt('S')),
          setV('pending', num(1))
        ])
      ])
    ]);
    console.log('[P176] bin / hex / oct installed');
  }
});

// ---- P177: `find(sub, start)` / `rfind(sub, start)` (v4.104) ----
//
// P18/P75/P174 gave the string type `find`/`rfind` with a single argument; the two-argument form
// (`'abcabc'.find('b', 2)` -> 4) still reported `TypeError: find() takes exactly one argument`.
// The string dispatch evaluates the first argument into `sma1` and the second into `sma2` (the
// first comma's position is in `mcut`), so the two-argument form is detectable with `mcut > 0`.
//
// `sfind2 rec needle start` walks forward from 1-based `start + 1` and `srfind2` walks backwards
// from the last position that still fits down to `start + 1`; both compare with `compareText`
// (Scratch's `=` ignores case) and answer a 0-based index or -1.  An empty needle answers `start`
// itself, which is what CPython does (`'abc'.find('', 1)` is 1).
patch('P177 find/rfind start', () => {
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p13s', 'p13p', 'p13i', 'p13l', 'p13n', 'p13f', 'p13st']) {
    if (taken.has(n)) throw new Error('[P177] variable name taken: ' + n);
    newVar(n, 0);
  }
  const notInt = () => [
    setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname'),
    callProc('fail %s', [JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object cannot be interpreted as an integer"))])
  ];

  // ---------- sfind2 <rec> <needle> <start>: first index at or after start, else -1
  const sf = newProc('sfind2 %s %s %s', ['s', 'p', 'st']);
  attachBody(sf.defId, [
    setV('p13s', argOf('s')), setV('p13p', argOf('p')), setV('p13st', argOf('st')),
    setV('p13f', num(-1)),
    setV('p13l', lenOf(argOf('p'))), setV('p13n', lenOf(argOf('s'))),
    IFELSE(EQ(F('p13l'), num(0)), [
      // an empty needle matches at start itself (clamped to the length)
      IFELSE(GT(F('p13st'), lenOf(argOf('s'))), [setV('p13f', num(-1))], [setV('p13f', F('p13st'))])
    ], [
      setV('p13i', ADD(F('p13st'), num(1))),
      REPEATU(OR(GT(ADD(SUB(F('p13i'), num(1)), F('p13l')), F('p13n')), NOT(EQ(F('p13f'), num(-1)))), [
        callProc('substr %s %s %s', [F('p13s'), F('p13i'), SUB(ADD(F('p13i'), F('p13l')), num(1))]),
        callProc('compareText %s %s', [F('ev'), F('p13p')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('p13f', SUB(F('p13i'), num(1)))]),
        chgV('p13i', num(1))
      ])
    ]),
    setV('ev', F('p13f')), setV('evtype', txt('N'))
  ]);

  // ---------- srfind2 <rec> <needle> <start>: last index at or after start, else -1
  const sr = newProc('srfind2 %s %s %s', ['s', 'p', 'st']);
  attachBody(sr.defId, [
    setV('p13s', argOf('s')), setV('p13p', argOf('p')), setV('p13st', argOf('st')),
    setV('p13f', num(-1)),
    setV('p13l', lenOf(argOf('p'))), setV('p13n', lenOf(argOf('s'))),
    IFELSE(EQ(F('p13l'), num(0)), [
      // an empty needle matches at the very end, and not at all once start is past it
      IFELSE(GT(F('p13st'), lenOf(argOf('s'))), [setV('p13f', num(-1))], [setV('p13f', lenOf(argOf('s')))])
    ], [
      setV('p13i', ADD(SUB(F('p13n'), F('p13l')), num(1))),
      REPEATU(OR(LT(F('p13i'), ADD(F('p13st'), num(1))), NOT(EQ(F('p13f'), num(-1)))), [
        callProc('substr %s %s %s', [F('p13s'), F('p13i'), SUB(ADD(F('p13i'), F('p13l')), num(1))]),
        callProc('compareText %s %s', [F('ev'), F('p13p')]),
        IF(EQ(VAR('cmp'), num(0)), [setV('p13f', SUB(F('p13i'), num(1)))]),
        chgV('p13i', num(-1))
      ])
    ]),
    setV('ev', F('p13f')), setV('evtype', txt('N'))
  ]);
  console.log('[P177] sfind2 / srfind2 registered');

  // ---------- the dispatch branch, in front of the "known names" guard
  {
    const mc = defIdOf('methodcall %s %s');
    const litOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
      if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
      return null;
    };
    const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
    const eqJoin = (id) => {
      const e = BL()[id];
      if (!e || e.opcode !== 'operator_equals') return false;
      return (vnOf(e.inputs.OPERAND1) === 'smmeth' && litOf(e.inputs.OPERAND2) === 'join')
        || (vnOf(e.inputs.OPERAND2) === 'smmeth' && litOf(e.inputs.OPERAND1) === 'join');
    };
    const mcReach = reach(mc);
    let notId = null, guardId = null;
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'operator_not' && [...reach(id)].some(eqJoin)) { notId = id; break; }
    }
    if (!notId) throw new Error('[P177] not(known names) not found');
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'control_if' && q.inputs.CONDITION && typeof q.inputs.CONDITION[1] === 'string'
        && reach(q.inputs.CONDITION[1]).has(notId)) { guardId = id; break; }
    }
    if (!guardId) throw new Error('[P177] guard if not found');
    insertBeforeStmt(guardId, [
      IF(AND(GT(F('mcut'), num(0)), OR(EQ(F('smmeth'), txt('find')), EQ(F('smmeth'), txt('rfind')))), [
        IFELSE(NOT(EQ(F('smt2'), txt('N'))), notInt(), [
          IFELSE(EQ(F('smmeth'), txt('find')), [
            callProc('sfind2 %s %s %s', [F('smrec'), F('sma1'), F('sma2')])
          ], [
            callProc('srfind2 %s %s %s', [F('smrec'), F('sma1'), F('sma2')])
          ])
        ])
      ])
    ]);
    console.log('[P177] methodcall accepts find/rfind with a start');
  }
});

// ---- P178: `int('0b101', 2)` -- a base prefix in the string (v4.105) ----
//
// CPython strips an optional `0b`/`0o`/`0x` prefix from the string when it *matches* the base
// (`int('0b101', 2)` is 5); with any other base the letters are ordinary digits, so
// `int('0b101', 16)` is `0xb101`.  MiniPy's `basenum` (P71) walked every character against the
// digit table, so the `b`/`o`/`x` was reported as an invalid literal.
//
// P178 inserts one step right after `basenum` has dealt with the sign: when the base is 2/8/16 and
// the text starts with `0` followed by the matching letter, skip both characters.  The skip only
// happens when at least one character follows, so a bare `'0x'`/`'0b'` falls through to the digit
// loop and raises the ordinary `ValueError: invalid literal for int() with base 16: '0x'`.
patch('P178 int base prefix', () => {
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('bp2')) throw new Error('[P178] variable name taken: bp2');
  newVar('bp2', '');

  const bs = inDef('basenum %s %s');
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  // the `if letter(1, bstr) == '+'` step marks the end of the sign handling
  const plusIf = find(bs, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && litOf(b.inputs.CONDITION[1]) === null
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      return q && q.opcode === 'operator_letter_of' && litOf(q.inputs.LETTER) === '1';
    })
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      return q && q.opcode === 'operator_equals' && litOf(q.inputs.OPERAND2) === '+';
    }));
  if (plusIf.length !== 1) throw new Error('[P178] basenum sign step = ' + plusIf.length);

  spliceAfter(plusIf[0], chain([
    // `0b` / `0o` / `0x` -- only when it matches the base and something follows it
    IF(AND(GT(lenOf(F('bstr')), ADD(F('bi'), num(1))), EQ(letterOf(F('bi'), F('bstr')), txt('0'))), [
      setV('bp2', letterOf(ADD(F('bi'), num(1)), F('bstr'))),
      IF(OR(OR(AND(EQ(argOf('b'), num(2)), EQ(F('bp2'), txt('b'))), AND(EQ(argOf('b'), num(8)), EQ(F('bp2'), txt('o')))),
        AND(EQ(argOf('b'), num(16)), EQ(F('bp2'), txt('x')))), [
        chgV('bi', num(2))
      ])
    ])
  ]));
  console.log('[P178] basenum skips a matching base prefix');
});

// ---- P179: `count(sub, start)` (v4.106) ----
//
// P177 gave `find`/`rfind` a start argument; `count(sub, start)` was still `TypeError: count()
// takes exactly one argument`.  The string dispatch already evaluates the first argument into
// `sma1` and the second into `sma2` (first comma position in `mcut`), so the two-argument form is
// detectable with `mcut > 0` -- the same shape P177 uses.  (A *third* argument is not available:
// there is no `sma3`, so `find(sub, start, end)` still needs the argument scanner widened first.)
//
// `scount2 rec needle start` walks forward from 1-based `start + 1`, compares with `compareText`
// (Scratch's `=` ignores case) and advances by the needle length after a hit, so matches never
// overlap -- `'aaa'.count('aa')` is 1.  An empty needle counts the positions from `start` to the
// end inclusive, which is what CPython does (`'abc'.count('', 1)` is 3).
patch('P179 count start', () => {
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['p14s', 'p14p', 'p14t', 'p14st']) {
    if (taken.has(n)) throw new Error('[P179] variable name taken: ' + n);
    newVar(n, 0);
  }
  const notInt = () => [
    setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname'),
    callProc('fail %s', [JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object cannot be interpreted as an integer"))])
  ];

  // ---------- scount2 <rec> <needle> <start>: the matches of the slice from `start` on
  // NB: delegating to the existing `scount` on that slice is both shorter and safer than walking
  // the string again -- the first version's own loop never terminated and hung the interpreter.
  const sc = newProc('scount2 %s %s %s', ['s', 'p', 'st']);
  attachBody(sc.defId, [
    setV('p14s', argOf('s')), setV('p14p', argOf('p')), setV('p14st', argOf('st')),
    IF(LT(F('p14st'), num(0)), [setV('p14st', num(0))]),
    IFELSE(GT(F('p14st'), lenOf(F('p14s'))), [
      setV('ev', num(0)), setV('evtype', txt('N'))
    ], [
      callProc('substr %s %s %s', [F('p14s'), ADD(F('p14st'), num(1)), lenOf(F('p14s'))]),
      setV('p14t', F('ev')),
      IFELSE(EQ(lenOf(F('p14p')), num(0)), [
        // an empty needle matches at every position of the slice, ends included
        setV('ev', ADD(lenOf(F('p14t')), num(1))), setV('evtype', txt('N'))
      ], [
        callProc('scount %s %s', [F('p14t'), F('p14p')])
      ])
    ])
  ]);
  console.log('[P179] scount2 registered');

  // ---------- the dispatch branch, in front of the "known names" guard
  {
    const mc = defIdOf('methodcall %s %s');
    const litOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
      if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
      return null;
    };
    const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
    const eqJoin = (id) => {
      const e = BL()[id];
      if (!e || e.opcode !== 'operator_equals') return false;
      return (vnOf(e.inputs.OPERAND1) === 'smmeth' && litOf(e.inputs.OPERAND2) === 'join')
        || (vnOf(e.inputs.OPERAND2) === 'smmeth' && litOf(e.inputs.OPERAND1) === 'join');
    };
    const mcReach = reach(mc);
    let notId = null, guardId = null;
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'operator_not' && [...reach(id)].some(eqJoin)) { notId = id; break; }
    }
    if (!notId) throw new Error('[P179] not(known names) not found');
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'control_if' && q.inputs.CONDITION && typeof q.inputs.CONDITION[1] === 'string'
        && reach(q.inputs.CONDITION[1]).has(notId)) { guardId = id; break; }
    }
    if (!guardId) throw new Error('[P179] guard if not found');
    insertBeforeStmt(guardId, [
      IF(AND(GT(F('mcut'), num(0)), EQ(F('smmeth'), txt('count'))), [
        IFELSE(NOT(EQ(F('smt2'), txt('N'))), notInt(), [
          callProc('scount2 %s %s %s', [F('smrec'), F('sma1'), F('sma2')])
        ])
      ])
    ]);
    console.log('[P179] methodcall accepts count with a start');
  }
});

// ---- P180: reversed() and count('') (v4.107) ----
//
// Two small gaps found by a probe:
//
//  (a) `reversed(x)` does not exist (`NameError: name 'reversed' is not defined`), even though the
//      list-reverse kernel `lrev` does (P101).  CPython hands back an iterator, but every use a
//      teaching interpreter meets -- `list(reversed(x))`, `for v in reversed(x)`, `sum(reversed(x))`
//      -- works if the reversed *list* is returned, so that is what this does.  Lists, tuples and
//      dicts (which iterate as their keys) go straight to `lrev`; a string is split into characters
//      first (`charsplit`); anything else reports CPython's `TypeError: '<type>' object is not
//      reversible`.
//
//  (b) the one-argument `'abc'.count('')` answered 0 where CPython answers 4 (an empty needle
//      matches at every position including the end).  The fix lives in the dispatch rather than in
//      `scount`: right before the "known names" guard, a branch for `count` with no second argument
//      and an empty needle sets the answer directly.
patch('P180 reversed and count empty', () => {
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('rv1')) throw new Error('[P180] variable name taken: rv1');
  newVar('rv1', 0);

  // ---------- (a) reversed(x) in callfn's builtin chain, in front of the pending guard
  {
    const cf = inDef('callfn %s %s %s');
    const pendingIf = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
      && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1 && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1]
      && BL()[b.inputs.CONDITION[1]].inputs.OPERAND1[1][1] === 'pending');
    if (pendingIf.length !== 1) throw new Error('[P180] callfn pending guard = ' + pendingIf.length);
    insertBeforeStmt(pendingIf[0], [
      IF(EQ(argOf('fn'), txt('reversed')), [
        IFELSE(OR(OR(EQ(F('evtype'), txt('L')), EQ(F('evtype'), txt('T'))), EQ(F('evtype'), txt('D'))), [
          // a dict iterates as its keys, so first turn it into that list
          IFELSE(EQ(F('evtype'), txt('D')), [
            callProc('dictkeys %s', [F('ev')]),
            setV('rv1', F('ev'))
          ], [
            setV('rv1', F('ev'))
          ]),
          callProc('lrev %s', [F('rv1')])
        ], [
          IFELSE(EQ(F('evtype'), txt('S')), [
            setV('rv1', F('ev')),
            callProc('charsplit'),
            callProc('lrev %s', [F('ev')])
          ], [
            setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname'),
            callProc('fail %s', [JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object is not reversible"))])
          ])
        ]),
        setV('pending', num(1))
      ])
    ]);
    console.log('[P180] reversed() installed');
  }

  // ---------- (b) count('') with one argument
  {
    const mc = defIdOf('methodcall %s %s');
    const litOf = (d) => {
      if (!d) return null;
      if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
      if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
      return null;
    };
    const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
    const eqJoin = (id) => {
      const e = BL()[id];
      if (!e || e.opcode !== 'operator_equals') return false;
      return (vnOf(e.inputs.OPERAND1) === 'smmeth' && litOf(e.inputs.OPERAND2) === 'join')
        || (vnOf(e.inputs.OPERAND2) === 'smmeth' && litOf(e.inputs.OPERAND1) === 'join');
    };
    const mcReach = reach(mc);
    let notId = null, guardId = null;
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'operator_not' && [...reach(id)].some(eqJoin)) { notId = id; break; }
    }
    if (!notId) throw new Error('[P180] not(known names) not found');
    for (const id of mcReach) {
      const q = BL()[id];
      if (q && q.opcode === 'control_if' && q.inputs.CONDITION && typeof q.inputs.CONDITION[1] === 'string'
        && reach(q.inputs.CONDITION[1]).has(notId)) { guardId = id; break; }
    }
    if (!guardId) throw new Error('[P180] guard if not found');
    insertBeforeStmt(guardId, [
      IF(AND(AND(EQ(F('smmeth'), txt('count')), NOT(GT(F('mcut'), num(0)))), EQ(lenOf(F('sma1')), num(0))), [
        setV('ev', ADD(lenOf(F('smrec')), num(1))), setV('evtype', txt('N'))
      ])
    ]);
    console.log("[P180] count('') answers len + 1");
  }
});

// ---- P181: `join` over any string iterable, with CPython's type error (v4.108) ----
//
// `','.join([1])` answered `'1'` -- it silently stringified a non-string element, where CPython
// raises `TypeError: sequence item 0: expected str instance, int found`.  That is a silent wrong
// answer, so P181 adds the check.  At the same time the argument only had to be a *list*:
// `','.join({'a': 1})` and `','.join('ab')` reported `TypeError: join needs a list` although CPython
// joins a dict's keys, a tuple, a set and a string's characters.
//
// Both live in the join branch of the string dispatch (P18): before its own
// `if smt1 != "L" then fail`, the argument is normalised to a list -- a dict goes through
// `dictkeys`, a string through `charsplit`, and a tuple/set just changes its tag (tuples and sets
// already share the list encoding); then, right before `sjoin`, every element is checked and the
// first non-string reports CPython's message with its **0-based** position.
patch('P181 join type check', () => {
  const F = (v) => VAR(v);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['jn1', 'jn2', 'jn3']) {
    if (taken.has(n)) throw new Error('[P181] variable name taken: ' + n);
    newVar(n, 0);
  }

  const mc = defIdOf('methodcall %s %s');
  // NB: find() wants the *reachable set*, not the definition id
  const mcSet = reach(mc);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const joinFail = find(mcSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && Object.values(b.inputs).some((v) => Array.isArray(v[1]) && v[1][1] === 'TypeError: join needs a list'));
  if (joinFail.length !== 1) throw new Error('[P181] join guard = ' + joinFail.length);
  // NB: expression blocks have no parent during the build, so find the enclosing if by containment
  let guardIf = null;
  for (const id of find(mcSet, (b) => b.opcode === 'control_if')) {
    const sub = BL()[id].inputs.SUBSTACK;
    if (sub && typeof sub[1] === 'string' && reach(sub[1]).has(joinFail[0])) { guardIf = id; break; }
  }
  if (!guardIf) throw new Error('[P181] join guard if not found');
  const sjoin = find(mcSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'sjoin %s %s');
  if (sjoin.length !== 1) throw new Error('[P181] sjoin call = ' + sjoin.length);
  insertBeforeStmt(sjoin[0], [
    callProc('listlen %s', [F('sma1')]), setV('jn2', F('ev')),
    setV('jn1', num(1)),
    REPEATU(OR(GT(F('jn1'), F('jn2')), EQ(F('jn3'), num(1))), [
      callProc('listitem %s %s', [F('sma1'), F('jn1')]),
      IFELSE(NOT(EQ(F('evtype'), txt('S'))), [
        setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname'),
        callProc('fail %s', [JOIN(JOIN(JOIN(JOIN(txt('TypeError: sequence item '), SUB(F('jn1'), num(1))),
          txt(': expected str instance, ')), VAR('p6msg')), txt(' found'))]),
        setV('jn3', num(1))
      ], []),
      chgV('jn1', num(1))
    ]),
    setV('jn3', num(0)),
    IF(NOT(EQ(F('error'), txt(''))), [
      I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } })
    ])
  ]);
  console.log('[P181] join normalises its iterable and checks the element types');
});

// ---- P182: `join` accepts a tuple or a dict's keys (v4.109) ----
//
// P181 taught `join` to reject non-string elements, but its argument still had to be a *list*:
// `'|'.join(('x', 'y'))` reported `TypeError: join needs a list` although CPython joins a tuple,
// and `','.join({'a': 1, 'b': 2})` likewise although CPython joins a dict's keys.  (A string --
// `'-'.join('ab')` -- is a third case that stays a gap for now.)
//
// Both changes sit in the join branch of the string dispatch (P18):
//   * the guard `if smt1 != "L" then fail` also lets a tuple through -- P140 encodes tuples
//     exactly like lists, so `sjoin` needs no change at all (nor does P181's element check, which
//     runs after the guard and therefore covers the new shapes);
//   * a dict is turned into its keys with `dictkeys` just before that guard.
patch('P182 join tuple and dict', () => {
  const F = (v) => VAR(v);
  const mc = defIdOf('methodcall %s %s');
  // NB: find() wants the *reachable set*, not the definition id
  const mcSet = reach(mc);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  // expression blocks carry no parent during the build, so walk the statement chain by hand
  const inChain = (stackId, target) => {
    let cur = stackId, n = 0;
    while (typeof cur === 'string' && cur && n++ < 5000) {
      if (cur === target) return true;
      cur = BL()[cur] && BL()[cur].next;
    }
    return false;
  };

  const joinFail = find(mcSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && Object.values(b.inputs).some((v) => Array.isArray(v[1]) && v[1][1] === 'TypeError: join needs a list'));
  if (joinFail.length !== 1) throw new Error('[P182] join guard = ' + joinFail.length);
  // the *innermost* if holding it: exactly one of them keeps the fail in its own substack chain
  const guardIf = find(mcSet, (b) => b.opcode === 'control_if'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && inChain(b.inputs.SUBSTACK[1], joinFail[0]));
  if (guardIf.length !== 1) throw new Error('[P182] join guard if = ' + guardIf.length);
  const condId = BL()[guardIf[0]].inputs.CONDITION[1];

  // ---------- (a) the guard also lets a tuple through (P140 gives tuples the list encoding)
  const eqs = [...reach(condId)].filter((x) => {
    const q = BL()[x];
    if (!q || q.opcode !== 'operator_equals') return false;
    return (vnOf(q.inputs.OPERAND1) === 'smt1' && litOf(q.inputs.OPERAND2) === 'L')
      || (vnOf(q.inputs.OPERAND2) === 'smt1' && litOf(q.inputs.OPERAND1) === 'L');
  });
  if (eqs.length !== 1) throw new Error('[P182] smt1 == L test = ' + eqs.length);
  const eqId = eqs[0];
  // the guard reads `if not (smt1 == "L") then fail`, so widen the test it negates -- never add
  // another `not` around the comparison itself, that would invert the whole guard
  const orId = OR(eqId, EQ(F('smt1'), txt('T')));
  const gcond = BL()[condId];
  if (gcond.opcode === 'operator_not') {
    gcond.inputs.OPERAND = [2, orId];
  } else if (condId === eqId) {
    BL()[guardIf[0]].inputs.CONDITION = [2, NOT(orId)];
  } else {
    throw new Error('[P182] unexpected join guard ' + gcond.opcode);
  }

  // ---------- (b) a dict joins its keys
  insertBeforeStmt(guardIf[0], [
    IFELSE(EQ(F('smt1'), txt('D')), [
      callProc('dictkeys %s', [F('sma1')]), setV('sma1', F('ev')), setV('smt1', txt('L'))
    ], [])
  ]);
  console.log('[P182] join accepts a dict (keys) and a tuple');
});

// ---- P183: tuples are first-class in slicing and `+` (v4.110) ----
//
// P140 gave tuples the list encoding and P142/P143 taught `index`/`count`/`tuple(x)` about them,
// but two places in the *sequence* path still treated a tuple as an opaque record string:
//
//   t = (1, 2, 3)
//   t[0:2]        -> printed the raw internal record (lsep + "N"), CPython: (1, 2)
//                    (P8/P9's slice read only rebuilds element records for `xb == "L"`, every
//                     other receiver -- tuples included -- falls through to `substr`, i.e. it
//                     sliced the *encoded string* by character)
//   ('a',) + ('b',) -> TypeError: can only concatenate tuple (not "tuple") to tuple
//                    (the `+` sequence branch tests `lt2 == "L" and evtype == "L"`, so tuples
//                     fell through to P139's generic operand-type error even though the two
//                     operand types matched)
//
// Two small edits, both just widening an existing test:
//
//   * slice read: `xb == "L"` becomes `xb == "L" or xb == "T"` in the two places that ask
//     (the length fix and the element-rebuild if/else), and the rebuilt result's tag becomes
//     `xb` instead of the literal "L" -- so lists keep answering "L" and tuples answer "T";
//   * `+`: the branch reads `op == "+" and (lt2 == "L" or lt2 == "T") and evtype == lt2`,
//     and it stores `lt2` as the result tag.  Requiring both operands to be the *same* tag
//     keeps the mixed cases wrong on purpose -- `[1] + (2,)` must still go to `binerr`, which
//     then says `can only concatenate list (not "tuple") to list`, exactly like CPython.
patch('P183 tuple slice and concat', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const repOf = (b) => (b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string') ? BL()[b.inputs.VALUE[1]] : null;
  const litsUnder = (id) => {
    const out = new Set(), seen = new Set(), st = [id];
    while (st.length) {
      const x = st.pop();
      if (!x || seen.has(x)) continue;
      seen.add(x);
      const q = BL()[x];
      if (!q) continue;
      for (const v of Object.values(q.inputs || {})) {
        const l = litOf(v);
        if (l !== null) out.add(l);
        if (typeof v[1] === 'string') st.push(v[1]);
      }
    }
    return out;
  };
  // the two places that ask `xb == "L"`: the length fix (a plain if) and the slice tail (if/else)
  const xbIfs = (opcode) => {
    const out = [];
    for (const id of find(ig, (b) => b.opcode === opcode)) {
      const cond = BL()[id].inputs.CONDITION;
      if (!cond || typeof cond[1] !== 'string') continue;
      const eqs = [...reach(cond[1])].filter((x) => {
        const q = BL()[x];
        return q && q.opcode === 'operator_equals' && vnOf(q.inputs.OPERAND1) === 'xb' && litOf(q.inputs.OPERAND2) === 'L';
      });
      if (eqs.length) out.push({ id, eq: eqs[0] });
    }
    return out;
  };
  // widen `xb == "L"` to `xb == "L" or xb == "T"`
  const widen = (hit) => {
    BL()[hit.id].inputs.CONDITION = [2, OR(hit.eq, EQ(F('xb'), txt('T')))];
  };

  // ---------- (a) slicing a tuple rebuilds the element records, tag "T"
  // (the *length* fix that P8/P9 inserted already reads `xb == "L" or xb == "T"` -- P140 widened
  //  it when it taught `len` about tuples -- so only the slice tail needs the same treatment)
  const ig = inDef('indexget %s %s');
  const sliceIfs = xbIfs('control_if_else').filter((h) => {
    // the `[::step]` path already accepts tuples (its condition mentions "T"), so skip it
    if (litsUnder(BL()[h.id].inputs.CONDITION[1]).has('T')) return false;
    const sub2 = BL()[h.id].inputs.SUBSTACK2;
    return sub2 && typeof sub2[1] === 'string'
      && find(reach(sub2[1]), (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'substr %s %s %s').length > 0;
  });
  if (sliceIfs.length !== 1) {
    const dump = xbIfs('control_if_else').map((h) => {
      const cond = BL()[h.id].inputs.CONDITION[1];
      const ls = [...litsUnder(cond)].join(',');
      const sub = BL()[h.id].inputs.SUBSTACK, sub2 = BL()[h.id].inputs.SUBSTACK2;
      const first = (x) => (x && typeof x[1] === 'string') ? BL()[x[1]].opcode + '/' + JSON.stringify(BL()[x[1]].mutation || {}).slice(0, 40) : String(x);
      return h.id + ' lits=' + ls + ' then=' + first(sub) + ' else=' + first(sub2);
    });
    throw new Error('[P183] xb if/elses = ' + sliceIfs.length + '\n' + dump.join('\n'));
  }
  const sliceIf = sliceIfs[0].id;
  widen(sliceIfs[0]);
  const sub = BL()[sliceIf].inputs.SUBSTACK;
  const tagSet = find(reach(sub[1]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'evtype' && litOf(b.inputs.VALUE) === 'L');
  if (tagSet.length !== 1) throw new Error('[P183] slice evtype tag = ' + tagSet.length);
  BL()[tagSet[0]].inputs.VALUE = F('xb');
  console.log('[P183] tuple slices rebuild their elements');

  // ---------- (b) `+` concatenates two tuples as well as two lists
  const rs = inDef('rightside %s %s %s %s %s');
  const catSet = find(rs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'ev' && repOf(b) && repOf(b).opcode === 'operator_join'
    && BL()[b.next] && BL()[b.next].opcode === 'data_setvariableto'
    && BL()[b.next].fields.VARIABLE && BL()[b.next].fields.VARIABLE[0] === 'evtype'
    && litOf(BL()[b.next].inputs.VALUE) === 'L');
  if (catSet.length !== 1) throw new Error('[P183] concat site = ' + catSet.length);
  const tagSet2 = BL()[catSet[0]].next;
  // walk up to the `+`  branch: a control_if whose condition mentions both "L" and "+"
  let branch = null;
  for (let cur = BL()[catSet[0]].parent, g = 0; cur && g < 40; g++, cur = BL()[cur].parent) {
    const q = BL()[cur];
    const cond = q.inputs && q.inputs.CONDITION;
    if (q.opcode === 'control_if' && cond && typeof cond[1] === 'string') {
      const ls = litsUnder(cond[1]);
      if (ls.has('L') && ls.has('+')) { branch = cur; break; }
    }
  }
  if (!branch) throw new Error('[P183] concat branch not found');
  // the inner `and`: (lt2 == "L") and (evtype == "L")
  const inner = [...reach(BL()[branch].inputs.CONDITION[1])].filter((x) => {
    const q = BL()[x];
    if (!q || q.opcode !== 'operator_and') return false;
    const ls = litsUnder(x);
    return ls.has('L') && !ls.has('+');
  });
  if (inner.length !== 1) throw new Error('[P183] concat inner and = ' + inner.length);
  const eqL = find(reach(inner[0]), (b) => b.opcode === 'operator_equals'
    && vnOf(b.inputs.OPERAND1) === 'lt2' && litOf(b.inputs.OPERAND2) === 'L');
  const eqE = find(reach(inner[0]), (b) => b.opcode === 'operator_equals'
    && vnOf(b.inputs.OPERAND1) === 'evtype' && litOf(b.inputs.OPERAND2) === 'L');
  if (eqL.length !== 1 || eqE.length !== 1) throw new Error('[P183] concat equals = ' + eqL.length + '/' + eqE.length);
  BL()[inner[0]].inputs.OPERAND1 = [2, OR(eqL[0], EQ(F('lt2'), txt('T')))];
  BL()[eqE[0]].inputs.OPERAND2 = F('lt2');   // evtype == lt2: both operands must carry the same tag
  BL()[tagSet2].inputs.VALUE = F('lt2');
  console.log('[P183] + concatenates two tuples');

  // ---------- (c) the `+` fallback that raises the operand-type error still asked for two *lists*
  // (`op == "+" and not (evtype == "L" and lt2 == "L")`), so a tuple pair -- which the branch above
  // has just concatenated -- fell through to it.  Mirror the branch's test instead.
  const fallback = [];
  for (const id of find(rs, (b) => b.opcode === 'control_if')) {
    const cond = BL()[id].inputs.CONDITION;
    if (!cond || typeof cond[1] !== 'string') continue;
    const hit = [...reach(cond[1])].some((x) => {
      const q = BL()[x];
      if (q.opcode !== 'operator_not') return false;
      const o = q.inputs.OPERAND;
      if (!o || typeof o[1] !== 'string' || BL()[o[1]].opcode !== 'operator_and') return false;
      const xs = [...reach(o[1])];
      const has = (v, l) => xs.some((y) => BL()[y].opcode === 'operator_equals'
        && vnOf(BL()[y].inputs.OPERAND1) === v && litOf(BL()[y].inputs.OPERAND2) === l);
      return has('evtype', 'L') && has('lt2', 'L');
    });
    if (hit) fallback.push(id);
  }
  if (fallback.length !== 1) throw new Error('[P183] + fallback = ' + fallback.length);
  const okPlus = AND(EQ(F('evtype'), F('lt2')), OR(EQ(F('lt2'), txt('L')), EQ(F('lt2'), txt('T'))));
  BL()[fallback[0]].inputs.CONDITION = [2, AND(EQ(argOf('op'), txt('+')), NOT(okPlus))];
  console.log('[P183] the + operand-type fallback knows tuples');

  // ---------- (d) `[::step]` built the right elements but always tagged the result "L"
  const stepTag = find(ig, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'evtype' && litOf(b.inputs.VALUE) === 'L');
  if (stepTag.length !== 1) throw new Error('[P183] step-slice tag = ' + stepTag.length);
  BL()[stepTag[0]].inputs.VALUE = F('xb');
  console.log('[P183] stepped slices keep the receiver tag');
});

// ---- P184: a string literal is never a comma (v4.111) ----
//
// Every scanner that splits a token span on a top-level comma compares the *token text*:
//
//   setV('eop', item('Tok', VAR('ek')))
//   if eop == ',' and depth == 0 then <split here>
//
// but the tokenizer stores a string literal as its **decoded content**, so `','` is a token whose
// text is exactly `,` -- indistinguishable from a real comma by text alone.  Result (all of these
// are valid Python that MiniPy rejected):
//
//   len(',')                     -> NameError: name 'len' is not defined   (two "arguments": , and )
//   len('x' + ',' + 'y')         -> NameError: name 'len' is not defined
//   len(','.join(['ab']))        -> NameError: name 'len' is not defined
//   max(','.join(['ab']))        -> SyntaxError: missing expression
//   f(','), [',', 'a'], (',',), {',' : 1}, for x in ',' ...  -- the same split, everywhere
//
// (`print` escaped this only because P7's `printargs` comma scan already skips string tokens:
// `if not (item('Kind', ek) == "S") then <bracket/comma logic>`.)
//
// The token list has a companion `Kind` list (`S` = string, `O` = punctuation, `I` = name,
// `N` = number), so the fix is to make the same test everywhere: a comma is a comma only when the
// token is **not** a string literal.  Two mechanical steps:
//
//   (a) every `setV(V, item('Tok', i))` gets a companion `setV(VK, item('Kind', i))` right after it
//       (and every *other* assignment to V clears VK to ""), so `V` always has its kind at hand;
//   (b) every comparison `X == ","` where X is a `Tok[...]` read or such a variable is rewritten
//       to `X == "," and <kind> != "S"`.
//
// Only comparisons against a *token* are touched: the scanners that walk a *string's characters*
// (`letter(i, s) == ","`, used by `%`-format parsing, `clssplit`, mro splitting and friends) treat a
// comma as text on purpose and are left alone.
patch('P184 a string literal is not a comma', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const isTokRead = (b) => !!b && b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'Tok';
  const dupInput = (d) => {
    const c = JSON.parse(JSON.stringify(d));
    if (typeof c[1] === 'string' && BL()[c[1]]) c[1] = cloneExpr(c[1]);
    return c;
  };

  // ---------- (a) keep each token variable's kind next to it
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const comp = new Map();
  const sets = find(allIds(), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0]);
  for (const id of sets) {
    const v = BL()[id].fields.VARIABLE[0];
    const src = blk(BL()[id].inputs.VALUE);
    if (!isTokRead(src)) continue;
    if (!comp.has(v)) {
      const n = v + 'K';
      if (taken.has(n)) throw new Error('[P184] variable name taken: ' + n);
      newVar(n, 0);
      taken.add(n);
      comp.set(v, n);
    }
  }
  let kindSets = 0;
  for (const id of sets) {
    const v = BL()[id].fields.VARIABLE[0];
    if (!comp.has(v)) continue;
    const src = blk(BL()[id].inputs.VALUE);
    const val = isTokRead(src) ? item('Kind', dupInput(src.inputs.INDEX)) : txt('');
    spliceAfter(id, chain([setV(comp.get(v), val)]));
    kindSets++;
  }
  console.log('[P184] ' + comp.size + ' token variables keep their kind (' + kindSets + ' assignments)');

  // ---------- (b) `X == ","` only when X is not a string literal
  let wrapped = 0;
  for (const id of find(allIds(), (b) => b.opcode === 'operator_equals')) {
    const b = BL()[id];
    const l1 = litOf(b.inputs.OPERAND1), l2 = litOf(b.inputs.OPERAND2);
    if (l2 !== ',' && l1 !== ',') continue;
    const other = l2 === ',' ? b.inputs.OPERAND1 : b.inputs.OPERAND2;
    const ob = blk(other);
    let kindExpr = null;
    if (isTokRead(ob)) kindExpr = item('Kind', dupInput(ob.inputs.INDEX));
    else {
      const v = vnOf(other);
      if (v && comp.has(v)) kindExpr = F(comp.get(v));
    }
    if (!kindExpr) continue;
    const k = kindExpr;
    replaceExpr(id, () => AND(id, NOT(EQ(k, txt('S')))));
    wrapped++;
  }
  if (!wrapped) throw new Error('[P184] no comma test was rewritten');
  console.log('[P184] ' + wrapped + ' comma tests now ignore string literals');
});

// ---- P185: min/max/sorted over a string, and two min/max messages (v4.112) ----
//
// CPython iterates a string as its characters, so `max('ba')` is `'b'`, `min('ba')` is `'a'`,
// `sorted('ba')` is `['a', 'b']` and `max('-'.join(['ab', 'cd']))` is `'d'`.  MiniPy refused all of
// them:
//
//   max('ba')                  -> TypeError: 'max' object is not iterable
//   min('ba')                  -> TypeError: 'min' object is not iterable
//   sorted('ba')               -> TypeError: sorted() requires a list
//   max('-'.join(['ab','cd'])) -> TypeError: 'max' object is not iterable
//
// Two causes, both just a missing `S`:
//   * `callfn`'s one-argument min/max (P78) whitelists `evtype` L/T/G, and on a mismatch it built the
//     message from `argOf('fn')` -- which is why a *type* error said `'max' object is not iterable`;
//   * `eval`'s `sorted` branch (and its P101/P130 variants) tests `evtype == "L"` only.
//
// P143's `charsplit` already turns a string into the list encoding of its characters (P180 uses it
// for `reversed`), so a string operand is normalised exactly the way P149 normalises a dict:
//
//   * min/max: `if evtype == "S" then charsplit` right in front of the iterable check
//     (`callfn` receives the *token span*, not the value, so at its entry `evtype` is still stale --
//      the normalization has to sit next to the check that needs it);
//   * eval's sorted sites: `if evtype == "S" then charsplit` before each type check;
//   * the not-iterable message now goes through `tname`, so `max(5)` says
//     `TypeError: 'int' object is not iterable` (CPython) instead of naming the function;
//   * an empty sequence says `ValueError: max() arg is an empty sequence` -- P134 had added the
//     prefix but kept MiniPy's old wording ("max() iterable argument is empty").
//
// Still a gap (left for later): the *two*-argument form `max('a', 'b')` -- that call is dispatched to
// `builtin2` (the numeric two-argument builtins), not to `minmax`, so it still says
// `TypeError: max requires numbers`.
patch('P185 min/max/sorted over a string', () => {
  const F = (v) => VAR(v);
  const J = (a, b) => JOIN(a, b);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const setMsg = (failId, msgId) => {
    const b = BL()[failId];
    const slot = Object.keys(b.inputs)[0];
    const old = b.inputs[slot];
    b.inputs[slot] = old.length > 2 ? [old[0], msgId, old[2]] : [old[0], msgId];
  };
  const cf = inDef('callfn %s %s %s');

  // ---------- (a) find the min/max "not iterable" check -- the only `object is not iterable`
  // message in callfn built from `argOf('fn')`
  const notIter = [];
  for (const id of cf) {
    const b = BL()[id];
    if (b.opcode !== 'procedures_call' || !b.mutation || b.mutation.proccode !== 'fail %s') continue;
    const v = Object.values(b.inputs || {})[0];
    if (!v || typeof v[1] !== 'string') continue;
    const tree = [...reach(v[1])];
    const hasFn = tree.some((x) => {
      const q = BL()[x];
      return q.opcode === 'argument_reporter_string_number' && q.fields.VALUE && q.fields.VALUE[0] === 'fn';
    });
    const hasText = tree.some((x) => JSON.stringify(BL()[x]).includes('object is not iterable'));
    if (hasFn && hasText) notIter.push(id);
  }
  if (notIter.length !== 1) throw new Error('[P185] not-iterable site = ' + notIter.length);
  // find the innermost if whose substack *contains* the fail -- `parent` links are unreliable on
  // chains the older patches built, so look from the outside in and keep the smallest one
  const enclosingIf = (target) => {
    const cands = [];
    for (const id of allIds()) {
      const b = BL()[id];
      if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') continue;
      for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
        const sub = b.inputs[slot];
        if (sub && typeof sub[1] === 'string' && reach(sub[1]).has(target)) { cands.push(id); break; }
      }
    }
    cands.sort((a, b) => {
      const size = (x) => {
        const s = BL()[x].inputs.SUBSTACK;
        return (s && typeof s[1] === 'string') ? reach(s[1]).size : 0;
      };
      return size(a) - size(b);
    });
    return cands;
  };
  const notIterCands = enclosingIf(notIter[0]);
  if (!notIterCands.length) throw new Error('[P185] not-iterable if not found');
  const notIterIf = notIterCands[0];

  // a string becomes its characters, so the L/T/G whitelist below accepts it
  insertBeforeStmt(notIterIf, [IF(EQ(F('evtype'), txt('S')), [callProc('charsplit', [])])]);
  console.log('[P185] min()/max() iterate a string as its characters');

  // the not-iterable message names the type, not the function
  insertBeforeStmt(notIter[0], [setV('p6v', F('ev')), setV('p6t', F('evtype')), callProc('tname', [])]);
  setMsg(notIter[0], J(J(txt("TypeError: '"), F('p6msg')), txt("' object is not iterable")));
  console.log('[P185] the not-iterable message uses the type name');

  // ---------- (b) every `sorted() requires a list` check (eval's, plus callfn's own branch)
  // The `fail` sits *inside* the `if not (evtype in ...)` branch, so the normalization has to go in
  // front of that if -- inserting before the fail itself would run too late.
  const sortedFails = [];
  for (const id of allIds()) {
    const b = BL()[id];
    if (b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
      && JSON.stringify(b.inputs).includes('sorted() requires a list')) sortedFails.push(id);
  }
  if (!sortedFails.length) throw new Error('[P185] sorted type checks = 0');
  const guardIfs = new Set();
  for (const id of sortedFails) {
    // the check that fails is the one whose *own* substack chain holds the `fail`
    const hits = [];
    for (const gid of allIds()) {
      const b = BL()[gid];
      if (b.opcode !== 'control_if' && b.opcode !== 'control_if_else') continue;
      for (const slot of ['SUBSTACK', 'SUBSTACK2']) {
        const sub = b.inputs[slot];
        if (!sub || typeof sub[1] !== 'string') continue;
        let cur = sub[1], seen = new Set();
        while (typeof cur === 'string' && cur && !seen.has(cur)) {
          seen.add(cur);
          if (cur === id) { hits.push(gid); break; }
          const q = BL()[cur];
          cur = q && q.next;
        }
      }
    }
    if (hits.length !== 1) throw new Error('[P185] sorted guard ifs = ' + hits.length + ' for ' + id);
    guardIfs.add(hits[0]);
  }
  for (const id of guardIfs) {
    insertBeforeStmt(id, [IF(EQ(F('evtype'), txt('S')), [callProc('charsplit', [])])]);
  }
  console.log('[P185] sorted() accepts a string (' + guardIfs.size + ' guards)');

  // NB: the empty-sequence wording stays as it is -- the local CPython (the oracle the suites
  // compare against) says `max() iterable argument is empty`, and `d190` B9/B17 lock that in.
});

// ---- P186: the two-argument max()/min() accept any comparable values (v4.113) ----
//
// P185 taught the *iterable* forms (`max('ba')`, `sorted('ba')`) about strings, but the two-argument
// call still refused them:
//
//   max('a', 'b')   -> TypeError: max requires numbers     (CPython: b)
//   min('b', 'a')   -> TypeError: min requires numbers     (CPython: a)
//   max(a, b)       -> same, with a and b any two strings
//
// `max(1, 5, 3)` and even `max('a', 'c', 'b')` were fine: three or more arguments go through P6's
// `minmax %s %s %s` (which compares numbers with `>` and strings with `compareText`).  Only the
// *exactly two* argument case is diverted earlier -- `eval` has an if/else whose condition is
// `fn in (int, round, pow, min, max) and narg == 1` whose THEN calls `builtin2` (the numeric
// two-argument builtins, where `builtin2b` hard-fails with "max requires numbers"), and P6 had
// already replaced its ELSE with the `minmax` routing.
//
// So this patch mirrors P6 on the THEN side: if the function is max/min, call `minmax` with the same
// token span P6 uses (`lo + 2` .. `hi - 1`); every other two-argument builtin keeps the old chain.
//
// Doing only that exposed a second, worse bug in `minmax` itself -- **it never looked at the last
// argument**:
//
//   max(1, 2, 3)      -> 2   (CPython 3)
//   max(1, 2, 3, 4)   -> 3   (CPython 4)
//   max('a', 'b', 'c')-> 'b' (CPython 'c')
//
// `minmax` collects the top-level commas in `MComma` and appends `hi + 1` as a sentinel, so a k
// argument call leaves a k element list: element 1 is evaluated before the loop and element i (i >= 2)
// is `eval(MComma[i-1] + 1, MComma[i] - 1)`, driven by `mpi` running 1 .. k-1.  The loop condition was
// written `repeat until (mpi >= len(MComma) - 1)`, which stops one iteration too early (for two
// arguments it never ran at all).  The bound is `len(MComma)`, so the `- 1` is simply wrong.
patch('P186 n-ary max/min and two-arg max/min', () => {
  const ev = inDef('eval %s %s');
  const multiIf = find(ev, (b) => b.opcode === 'control_if_else' && b.inputs.SUBSTACK
    && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === 'builtin2 %s %s %s %s'));
  if (!multiIf.length) throw new Error('[P186] eval two-argument dispatch not found');
  // reach() descends into nested substacks, so keep the innermost match (same rule P6 used)
  multiIf.sort((a, b) => reach(BL()[a].inputs.SUBSTACK[1]).size - reach(BL()[b].inputs.SUBSTACK[1]).size);
  multiIf.length = 1;
  const oldThen = BL()[multiIf[0]].inputs.SUBSTACK[1];
  if (typeof oldThen !== 'string') throw new Error('[P186] no THEN chain');
  const fnTok = () => item('Tok', argOf('lo'));
  const mm = IFELSE(OR(EQ(fnTok(), txt('max')), EQ(fnTok(), txt('min'))),
    [callProc('minmax %s %s %s', [fnTok(), ADD(argOf('lo'), num(2)), SUB(argOf('hi'), num(1))])],
    [oldThen]);
  setStack(multiIf[0], 'SUBSTACK', [mm]);
  console.log('[P186] two-argument max/min go through minmax');

  // ---------- (b) minmax: stop one element too early
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const inMinmax = inDef('minmax %s %s %s');
  const lts = find(inMinmax, (b) => {
    if (b.opcode !== 'operator_lt' || vnOf(b.inputs.OPERAND1) !== 'mpi') return false;
    const sub = (b.inputs.OPERAND2 && typeof b.inputs.OPERAND2[1] === 'string') ? BL()[b.inputs.OPERAND2[1]] : null;
    if (!sub || sub.opcode !== 'operator_subtract') return false;
    const len1 = (sub.inputs.NUM1 && typeof sub.inputs.NUM1[1] === 'string') ? BL()[sub.inputs.NUM1[1]] : null;
    return !!len1 && len1.opcode === 'data_lengthoflist' && len1.fields.LIST && len1.fields.LIST[0] === 'MComma';
  });
  if (lts.length !== 1) throw new Error('[P186] minmax loop bound = ' + lts.length);
  const oldIn = BL()[lts[0]].inputs.OPERAND2;
  BL()[lts[0]].inputs.OPERAND2 = oldIn.length > 2 ? [oldIn[0], llen('MComma'), oldIn[2]] : [oldIn[0], llen('MComma')];
  console.log('[P186] minmax visits every argument');
});

// ---- P187: nested max()/min() no longer clobber each other (v4.114) ----
//
// `max(min(5, 2), 3)` answered 2 (CPython 3) and `min(max(1, 4), 2)` answered 4 (CPython 2): an
// inner min/max wiped the scratch the outer one was still using.  `minmax` keeps its state in three
// globals (`mpi`, `mbest`, `mtype`) and in the list `MComma`, which it *cleared* on entry, and it
// evaluates every argument with `eval` -- which of course can call min/max again.
//
// `fn`/`lo`/`hi` are safe (real procedure arguments, so each call has its own frame); the globals are
// not.  This patch therefore gives every call its own slice:
//
//   * `MComma` becomes **append-only**.  Before scanning, a call records where its slice will start
//     in the scalar `mcb` (no nested call can happen while scanning) and pushes that base onto the
//     stack list `MCnt` afterwards.  A bound is read as `MComma[base + i - 1]`, and the call trims its
//     own slice (and pops `MCnt`) before returning, so a nested call appends *after* the outer slice
//     and removes only its own.
//   * `mpi`/`mbest`/`mtype` are pushed on the stack lists `MS1`/`MS2`/`MS3` right before the argument
//     `eval` and restored right after it, so the outer loop continues with its own values.
//
// The argument `eval` is the only place a nested call can happen, so one save/restore pair (plus the
// slice bookkeeping) is enough.  The loop condition and the result also have to consult the slice
// rather than the raw list length.
patch('P187 nested max/min', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const stack = (name) => item(name, llen(name));
  const delLast = (name) => I('data_deleteoflist', { fields: B.LISTF(name), inputs: { INDEX: [1, [10, 'last']] } });
  const takenV = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  const takenL = new Set(Object.values(T(IT).lists || {}).map((x) => x[0]));
  if (takenV.has('mcb')) throw new Error('[P187] variable taken: mcb');
  newVar('mcb', 0);
  for (const n of ['MCnt', 'MS1', 'MS2', 'MS3']) {
    if (takenL.has(n)) throw new Error('[P187] list taken: ' + n);
    B.addList(IT, n, []);
  }

  const mm = inDef('minmax %s %s %s');
  const base = () => stack('MCnt');                       // 1-based first index of this call's slice
  const count = () => SUB(ADD(llen('MComma'), num(1)), stack('MCnt'));

  // ---------- (a) append-only bounds: remember the base before the scan, push it after
  const clears = find(mm, (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'MComma');
  if (clears.length !== 1) throw new Error('[P187] MComma clear = ' + clears.length);
  replaceStmt(clears[0], setV('mcb', ADD(llen('MComma'), num(1))));

  const sentinel = find(mm, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'MComma'
    && b.inputs.ITEM && typeof b.inputs.ITEM[1] === 'string'
    && (() => { const q = BL()[b.inputs.ITEM[1]]; return q && q.opcode === 'operator_add'; })());
  if (sentinel.length !== 1) throw new Error('[P187] sentinel add = ' + sentinel.length);
  spliceAfter(sentinel[0], chain([addTo('MCnt', F('mcb'))]));
  console.log('[P187] min/max keeps its bounds on a stack');

  // ---------- (b) the three bound reads use the slice
  const mcReads = find(mm, (b) => b.opcode === 'data_itemoflist' && b.fields.LIST && b.fields.LIST[0] === 'MComma');
  if (mcReads.length !== 3) throw new Error('[P187] MComma reads = ' + mcReads.length);
  const kindOf = (b) => {
    const l = litOf(b.inputs.INDEX);
    if (l !== null) return 'lit:' + l;
    const v = vnOf(b.inputs.INDEX);
    if (v) return 'var:' + v;
    const q = blk(b.inputs.INDEX);
    if (q && q.opcode === 'operator_add') return 'add:' + (vnOf(q.inputs.NUM1) || litOf(q.inputs.NUM1));
    return 'other';
  };
  const reads = mcReads.map((id) => ({ id, kind: kindOf(BL()[id]) }));
  const one = reads.filter((r) => r.kind === 'lit:1');
  const cur = reads.filter((r) => r.kind === 'var:mpi');
  const next = reads.filter((r) => r.kind === 'add:mpi');
  if (one.length !== 1 || cur.length !== 1 || next.length !== 1) {
    throw new Error('[P187] bound reads = ' + JSON.stringify(reads.map((r) => r.kind)));
  }
  BL()[one[0].id].inputs.INDEX = B.REP(ADD(base(), num(0)), [4, '0']);
  BL()[cur[0].id].inputs.INDEX = B.REP(ADD(base(), SUB(F('mpi'), num(1))), [4, '0']);
  BL()[next[0].id].inputs.INDEX = B.REP(ADD(base(), F('mpi')), [4, '0']);
  console.log('[P187] bound reads use the call slice');

  // ---------- (c) the loop counts this call's bounds, not the whole list
  const lts = find(mm, (b) => b.opcode === 'operator_lt' && vnOf(b.inputs.OPERAND1) === 'mpi'
    && blk(b.inputs.OPERAND2) && blk(b.inputs.OPERAND2).opcode === 'data_lengthoflist'
    && blk(b.inputs.OPERAND2).fields.LIST && blk(b.inputs.OPERAND2).fields.LIST[0] === 'MComma');
  if (lts.length !== 1) throw new Error('[P187] loop bound = ' + lts.length);
  const oldIn = BL()[lts[0]].inputs.OPERAND2;
  BL()[lts[0]].inputs.OPERAND2 = oldIn.length > 2 ? [oldIn[0], count(), oldIn[2]] : [oldIn[0], count()];
  console.log('[P187] the loop runs over this call bounds');

  // ---------- (d) save/restore mpi/mbest/mtype around the argument eval
  const evals = find(mm, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'eval %s %s');
  if (evals.length !== 2) throw new Error('[P187] evals = ' + evals.length);
  const loopEval = evals.find((id) => Object.values(BL()[id].inputs).some((v) => {
    const q = blk(v);
    return q && q.opcode === 'operator_add';
  }));
  if (!loopEval) throw new Error('[P187] loop eval not found');
  insertBeforeStmt(loopEval, [addTo('MS1', F('mpi')), addTo('MS2', F('mbest')), addTo('MS3', F('mtype'))]);
  spliceAfter(loopEval, chain([
    setV('mpi', stack('MS1')), delLast('MS1'),
    setV('mbest', stack('MS2')), delLast('MS2'),
    setV('mtype', stack('MS3')), delLast('MS3')
  ]));
  console.log('[P187] the argument eval saves and restores min/max state');

  // ---------- (e) drop this call's slice before returning
  const result = find(mm, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'ev' && vnOf(b.inputs.VALUE) === 'mbest');
  if (result.length !== 1) throw new Error('[P187] result site = ' + result.length);
  insertBeforeStmt(result[0], [REPEAT(count(), [delLast('MComma')]), delLast('MCnt')]);
  console.log('[P187] a returning min/max trims its slice');
});

// ---- P188: tuples repeat with `*` (v4.115) ----
//
// `(1, 2) * 2` said `TypeError: unsupported operand type(s) for *: 'tuple' and 'int'` and
// `2 * (1, 2)` printed the raw record twice (`<lsep>N1<lsep>N2<lsep>N1<lsep>N2`) instead of
// `(1, 2, 1, 2)`: CPython repeats a tuple exactly like a list.
//
// Two things were in the way, and fixing only the first (v4.110 tried that and had to be reverted)
// is not enough:
//
//   * the two repetition branches in `rightside` test the sequence side with `lt2 == "L"` /
//     `evtype == "L"` (v4.110's patch widened exactly those, and the result tag followed the
//     sequence side);
//   * the **string** repetition branch right after them is written
//     `op == "*" and (lt2 == "S" or evtype != "N") and not (lt2 == "L" or evtype == "L")`,
//     so once the list branch had produced a tuple (`evtype == "T"`) the *string* branch also
//     matched and overwrote the value -- that is why v4.110's attempt printed an empty line.
//
// So the string branch now insists on a real string (`lt2 == "S" or evtype == "S"`), and the two list
// branches accept a tuple and answer with that side's tag.  Invalid combinations still fail: P139's
// `*` validity check already treats tuples as sequences, so `(1, 2) * 1.5` and `(1, 2) * "a"` keep
// raising CPython's "can't multiply sequence by non-int of type ...".
patch('P188 tuple repetition', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const blk = (d) => (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
  const rs = inDef('rightside %s %s %s %s %s');

  // ---------- (a) the string repetition branch must have a real string on one side
  // its condition is the only one that combines `lt2 == "S" or not evtype == "N"` with
  // `not (lt2 == "L" or evtype == "L")`
  const strOr = () => {
    const out = [];
    for (const id of find(rs, (b) => b.opcode === 'control_if')) {
      const cond = BL()[id].inputs.CONDITION;
      if (!cond || typeof cond[1] !== 'string') continue;
      const xs = [...reach(cond[1])];
      const hasLNot = xs.some((y) => {
        const q = BL()[y];
        if (q.opcode !== 'operator_not') return false;
        const o = blk(q.inputs.OPERAND);
        if (!o || o.opcode !== 'operator_or') return false;
        const ys = [...reach(q.inputs.OPERAND[1])];
        const eq = (v, l) => ys.some((z) => BL()[z].opcode === 'operator_equals'
          && vnOf(BL()[z].inputs.OPERAND1) === v && litOf(BL()[z].inputs.OPERAND2) === l);
        return eq('lt2', 'L') && eq('evtype', 'L');
      });
      if (!hasLNot) continue;
      const orId = xs.find((y) => {
        const q = BL()[y];
        if (q.opcode !== 'operator_or') return false;
        const a = blk(q.inputs.OPERAND1), c = blk(q.inputs.OPERAND2);
        return !!a && !!c && a.opcode === 'operator_equals' && vnOf(a.inputs.OPERAND1) === 'lt2'
          && litOf(a.inputs.OPERAND2) === 'S' && c.opcode === 'operator_not';
      });
      if (orId) out.push({ branch: id, or: orId });
    }
    return out;
  };
  const ors = strOr();
  if (ors.length !== 1) throw new Error('[P188] string-repeat test = ' + ors.length);
  const oldOr = BL()[ors[0].or].inputs.OPERAND2;
  const newOr = EQ(F('evtype'), txt('S'));
  BL()[ors[0].or].inputs.OPERAND2 = oldOr.length > 2 ? [oldOr[0], newOr, oldOr[2]] : [oldOr[0], newOr];
  console.log('[P188] string repetition requires a string operand');

  // ---------- (b) the two sequence repetition branches also take a tuple
  const mulHits = [];
  for (const id of find(rs, (b) => b.opcode === 'control_if')) {
    const cond = BL()[id].inputs.CONDITION;
    if (!cond || typeof cond[1] !== 'string') continue;
    const xs = [...reach(cond[1])];
    // a flat `op == "*" and seq in (L) and the other side is a number` test
    const eqs = xs.filter((y) => BL()[y].opcode === 'operator_equals');
    if (eqs.length !== 3 || xs.some((y) => ['operator_not', 'operator_or'].includes(BL()[y].opcode))) continue;
    const eq = (v, l) => xs.some((y) => BL()[y].opcode === 'operator_equals'
      && vnOf(BL()[y].inputs.OPERAND1) === v && litOf(BL()[y].inputs.OPERAND2) === l);
    const isStar = eqs.some((y) => litOf(BL()[y].inputs.OPERAND2) === '*' && !vnOf(BL()[y].inputs.OPERAND1) && !litOf(BL()[y].inputs.OPERAND1));
    if (!isStar) continue;
    if (eq('lt2', 'L') && eq('evtype', 'N')) mulHits.push({ id, side: 'lt2', other: 'evtype' });
    else if (eq('lt2', 'N') && eq('evtype', 'L')) mulHits.push({ id, side: 'evtype', other: 'lt2' });
  }
  if (mulHits.length !== 2) throw new Error('[P188] sequence * branches = ' + mulHits.length);
  for (const h of mulHits) {
    const seq = OR(EQ(F(h.side), txt('L')), EQ(F(h.side), txt('T')));
    BL()[h.id].inputs.CONDITION = [2, AND(EQ(argOf('op'), txt('*')), AND(seq, EQ(F(h.other), txt('N'))))];
    const sub = BL()[h.id].inputs.SUBSTACK;
    const tag = find(reach(sub[1]), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
      && b.fields.VARIABLE[0] === 'evtype' && litOf(b.inputs.VALUE) === 'L');
    if (tag.length !== 1) throw new Error('[P188] ' + h.side + ' repeat tag = ' + tag.length);
    BL()[tag[0]].inputs.VALUE = F(h.side);
  }
  console.log('[P188] tuples repeat like lists');
});

// ---- P189: `join` over a string (v4.116) ----
//
// P182 taught `join` about tuples and about a dict's keys; the last half of the v4.108 revert --
// **strings** -- was still missing:
//
//   '-'.join('ab')      -> TypeError: join needs a list     (CPython: a-b)
//   ','.join('')        -> same                             (CPython: '')
//   ''.join('ab')       -> same                             (CPython: ab)
//   ','.join('a,b')     -> same                             (CPython: a,,,b)
//
// v4.108 tried to normalise *every* iterable and broke the string case with
// `AttributeError: 'list' object has no attribute 'join'`: that attempt ran `charsplit` on `ev`, which
// at that moment held the **receiver** (the separator), not the argument.  The dict half of P182
// already shows the safe shape -- move the *argument* (`sma1`) into `ev`, call the kernel, copy the
// result back into `sma1`, retag -- so this patch does exactly that for `smt1 == "S"`:
//
//   if smt1 == "S" then (ev = sma1; charsplit; sma1 = ev; smt1 = "L")
//
// `charsplit` (P143) turns a string into the list encoding of its characters, which is what the
// element check (P181) and `sjoin` already expect, and the receiver is never touched.
patch('P189 join over a string', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const mc = defIdOf('methodcall %s %s');
  const mcSet = reach(mc);
  const joinFail = find(mcSet, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && Object.values(b.inputs).some((v) => Array.isArray(v[1]) && v[1][1] === 'TypeError: join needs a list'));
  if (joinFail.length !== 1) throw new Error('[P189] join guard = ' + joinFail.length);
  // the innermost if that holds the fail in its *own* statement chain
  const inChain = (stackId, target) => {
    let cur = stackId, n = 0;
    while (typeof cur === 'string' && cur && n++ < 5000) {
      if (cur === target) return true;
      cur = BL()[cur] && BL()[cur].next;
    }
    return false;
  };
  const guardIf = find(mcSet, (b) => b.opcode === 'control_if'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && inChain(b.inputs.SUBSTACK[1], joinFail[0]));
  if (guardIf.length !== 1) throw new Error('[P189] join guard if = ' + guardIf.length);

  insertBeforeStmt(guardIf[0], [
    IFELSE(EQ(F('smt1'), txt('S')), [
      setV('ev', F('sma1')),
      callProc('charsplit', []),
      setV('sma1', F('ev')),
      setV('smt1', txt('L'))
    ], []),
    // a set already carries its elements in the list encoding (P110/P124), so it only needs the tag
    IFELSE(EQ(F('smt1'), txt('E')), [setV('smt1', txt('L'))], [])
  ]);
  console.log('[P189] join() accepts a string (its characters) and a set');
});

// ---- P190: `index(x, start)` for lists, tuples and strings (v4.117) ----
//
// CPython's `index` takes a start position (an end too, which is still a gap):
//
//   [1, 2, 1].index(1, 1)      -> 2      MiniPy: ValueError: list.index(x): x not in list
//   [1, 2, 1].index(1, -1)     -> 2      MiniPy: TypeError ... 'tuple' and 'int'
//   (1, 2, 1).index(1, 1)      -> 2      MiniPy: ValueError: tuple.index(x): x not in tuple
//   'abca'.index('a', 1)       -> 3      MiniPy: 0
//
// Two different causes:
//
//   * strings (P75): the `index` branch calls `sfind(smrec, sma1)` and ignores the second argument
//     entirely.  P177's `sfind2 <rec> <needle> <start>` already *is* "find from a start", and the
//     string dispatch has the start in `sma2` with its comma position in `mcut`, so the branch
//     becomes `if mcut > 0 then sfind2 else sfind`, both followed by the same ValueError.
//   * lists/tuples (P13): the branch evaluates the *whole* argument span as one expression, so a
//     second argument turns into a tuple and the search looks for that tuple.  It now scans the span
//     for its first top-level comma first (the shape the `insert` branch uses, plus braces and
//     P184's "a string literal is not a comma" guard), evaluates the needle and the start
//     separately, normalises a negative start against the length and starts the scan there.
//     The branch's own `lneed = ev` / `lnt = evtype` pair right after the evaluation has to go: with
//     two arguments the *last* thing `eval` leaves in `ev` is the start, so that pair would overwrite
//     the needle with it (the first attempt did exactly that and every two-argument call failed).
//
// The result stays `lres - 1` (0-based) because `lres` is still the 1-based position of the first
// match at or after the start.  `index(x, start, end)` stays a gap (the second comma), as does
// `find`/`rfind`/`count`'s `end` for strings.
patch('P190 index with a start', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const tokAt = (x) => item('Tok', x);
  const kindAt = (x) => item('Kind', x);
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  if (taken.has('lsstart')) throw new Error('[P190] variable taken: lsstart');
  newVar('lsstart', 0);

  const mc = defIdOf('methodcall %s %s');
  const hasEq = (condId, v, l) => [...reach(condId)].some((x) => {
    const q = BL()[x];
    return q.opcode === 'operator_equals' && vnOf(q.inputs.OPERAND1) === v && litOf(q.inputs.OPERAND2) === l;
  });

  // ---------- (a) strings: P75's `index` branch
  const idxIf = find(reach(mc), (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.SUBSTACK || typeof b.inputs.SUBSTACK[1] !== 'string') return false;
    const cond = b.inputs.CONDITION;
    if (!cond || typeof cond[1] !== 'string' || !hasEq(cond[1], 'smmeth', 'index')) return false;
    return [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === 'sfind %s %s');
  });
  if (idxIf.length !== 1) throw new Error('[P190] string index branch = ' + idxIf.length);
  const notFound = 'ValueError: substring not found';
  setStack(idxIf[0], 'SUBSTACK', [
    IFELSE(GT(F('mcut'), num(0)), [
      callProc('sfind2 %s %s %s', [F('smrec'), F('sma1'), F('sma2')]),
      IF(LT(F('ev'), num(0)), [FAIL(txt(notFound))])
    ], [
      callProc('sfind %s %s', [F('smrec'), F('sma1')]),
      IF(LT(F('ev'), num(0)), [FAIL(txt(notFound))])
    ])
  ]);
  console.log('[P190] str.index(sub, start)');

  // ---------- (b) lists and tuples: P13's `index`/`count` branch (same proc, list section)
  const lcIf = find(reach(mc), (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.SUBSTACK || typeof b.inputs.SUBSTACK[1] !== 'string') return false;
    const cond = b.inputs.CONDITION;
    if (!cond || typeof cond[1] !== 'string' || !hasEq(cond[1], 'lmeth', 'index')) return false;
    return [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === 'listlen %s');
  });
  if (lcIf.length !== 1) throw new Error('[P190] list index/count branch = ' + lcIf.length);
  const sub = BL()[lcIf[0]].inputs.SUBSTACK[1];
  const firstEval = find(reach(sub), (b) => b.opcode === 'procedures_call' && b.mutation
    && b.mutation.proccode === 'eval %s %s');
  if (firstEval.length !== 1) throw new Error('[P190] list index eval = ' + firstEval.length);

  // the comma scan runs right before the needle/start evaluation (it must be inserted first:
  // replacing the eval detaches that block, which would make a later insertBeforeStmt impossible)
  insertBeforeStmt(firstEval[0], [
    setV('mcut', num(0)), setV('sd', num(0)), setV('sk', ADD(argOf('lo'), num(4))),
    REPEATU(GT(VAR('sk'), SUB(argOf('hi'), num(1))), [
      IF(NOT(EQ(kindAt(F('sk')), txt('S'))), [
        IF(OR(EQ(tokAt(F('sk')), txt('(')), OR(EQ(tokAt(F('sk')), txt('[')), EQ(tokAt(F('sk')), txt('{')))), [chgV('sd', num(1))]),
        IF(OR(EQ(tokAt(F('sk')), txt(')')), OR(EQ(tokAt(F('sk')), txt(']')), EQ(tokAt(F('sk')), txt('}')))), [chgV('sd', num(-1))]),
        IF(AND(EQ(VAR('sd'), num(0)), AND(EQ(tokAt(F('sk')), txt(',')), EQ(VAR('mcut'), num(0)))), [setV('mcut', VAR('sk'))])
      ]),
      chgV('sk', num(1))
    ])
  ]);
  // the needle/start evaluation replaces the branch's single-expression evaluation.
  // the *start* is evaluated first and the *needle* last, because the branch's own
  // `lneed = ev` / `lnt = evtype` pair (which follows this statement) reads `ev` -- so the last thing
  // evaluated has to be the needle (the first attempt evaluated the start last and every two-argument
  // call searched for the start value).
  replaceStmt(firstEval[0], IFELSE(AND(GT(F('mcut'), num(0)), EQ(F('lmeth'), txt('index'))), [
    callProc('eval %s %s', [ADD(F('mcut'), num(1)), SUB(argOf('hi'), num(1))]),
    IF(OR(AND(NOT(EQ(F('evtype'), txt('N'))), NOT(EQ(F('evtype'), txt('B')))), strHas(F('ev'), txt('.'))),
      [FAIL(txt('TypeError: slice indices must be integers or have an __index__ method'))]),
    setV('lsstart', F('ev')),
    callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(F('mcut'), num(1))])
  ], [
    callProc('eval %s %s', [ADD(argOf('lo'), num(4)), SUB(argOf('hi'), num(1))]),
    setV('lsstart', num(0))
  ]));
  // the scan cursor starts at the requested index (negative start normalised, then clamped)
  const sixSet = find(reach(sub), (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'lsix' && litOf(b.inputs.VALUE) === '1');
  if (sixSet.length !== 1) throw new Error('[P190] lsix init = ' + sixSet.length);
  replaceStmt(sixSet[0], IF(EQ(num(1), num(1)), [
    IF(LT(F('lsstart'), num(0)), [setV('lsstart', ADD(F('lsstart'), F('lsn')))]),
    IF(LT(F('lsstart'), num(0)), [setV('lsstart', num(0))]),
    setV('lsix', ADD(F('lsstart'), num(1)))
  ]));
  console.log('[P190] list.index(x, start)');
});

// ---- P191: `split(sep, maxsplit)` and the empty-field fixes (v4.118) ----
//
// `'a,b,c'.split(',', 1)` answered `['a', 'b', 'c']` (the second argument was ignored) and
// `'a,b,c'.split(',', 0)` the same, where CPython gives `['a', 'b,c']` / `['a,b,c']`.  Two silent
// wrong answers came along with it, both from `ssplit`'s "only add a field when the separator
// matched" shape:
//
//   ''.split(',')   -> []            (CPython: [''])
//   ','.split(',')  -> ['']          (CPython: ['', ''])
//   'a,'.split(',') -> ['a']         (CPython: ['a', ''])
//
// `ssplit` walks the string looking for the separator; every time it matches it adds the field before
// it and moves on, and the tail is added by a final `if cursor <= len`.  The tail test was
// `cursor > len` -> skip, so a trailing separator (whose cursor lands exactly at len+1) lost its
// empty tail, and an empty receiver never entered the loop at all.  The test becomes
// `cursor <= len + 1`, which is the "there is one more field, possibly empty" condition.
//
// maxsplit itself travels in the global `smmax` (-1 = unlimited), set by the dispatcher from the
// second argument: the string dispatch already has it in `sma2` with its type in `smt2` and the comma
// position in `mcut`.  A non-integer maxsplit raises CPython's
// `TypeError: '<type>' object cannot be interpreted as an integer` (floats are caught by the `.` test,
// the same rule P170/P176/P190 use).  `ssplit` counts its matches in `smcnt` and the search loop also
// stops once the limit is reached, which leaves the unsplit remainder to the tail add.
//
// Still gaps: `split(None, maxsplit)` (the whitespace splitter has no limit) and `rsplit`.
patch('P191 split with maxsplit', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const strHas = (a, b) => I('operator_contains', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['smmax', 'smcnt']) {
    if (taken.has(n)) throw new Error('[P191] variable taken: ' + n);
    newVar(n, 0);
  }

  // ---------- (a) the dispatcher records the limit before it calls ssplit
  // P115 routed the call as `if smarg == 0 then ssplitw else (if sma1 == "" then fail else ssplit)`;
  // that outer if/else is the one whose branches hold those two calls
  const splitIf = find(allIds(), (b) => {
    if (b.opcode !== 'control_if_else') return false;
    const sub = b.inputs.SUBSTACK, sub2 = b.inputs.SUBSTACK2;
    if (!sub || typeof sub[1] !== 'string' || !sub2 || typeof sub2[1] !== 'string') return false;
    const has = (root, pc) => [...reach(root)].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === pc);
    return has(sub[1], 'ssplitw %s') && has(sub2[1], 'ssplit %s %s');
  });
  if (splitIf.length !== 1) throw new Error('[P191] split dispatch if = ' + splitIf.length);
  const notInt = () => [
    setV('p6v', F('sma2')), setV('p6t', F('smt2')), callProc('tname'),
    callProc('fail %s', [JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object cannot be interpreted as an integer"))])
  ];
  insertBeforeStmt(splitIf[0], [
    IFELSE(GT(F('mcut'), num(0)), [
      IFELSE(OR(NOT(EQ(F('smt2'), txt('N'))), strHas(F('sma2'), txt('.'))), notInt(), [
        setV('smmax', F('sma2'))
      ])
    ], [
      setV('smmax', num(-1))
    ]),
    IF(LT(F('smmax'), num(0)), [setV('smmax', num(-1))])
  ]);
  console.log('[P191] the dispatcher records maxsplit');

  // ---------- (b) ssplit honours the limit and keeps empty fields
  const sp = inDef('ssplit %s %s');
  const loops = find(sp, (b) => b.opcode === 'control_repeat_until' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]] && BL()[b.inputs.CONDITION[1]].opcode === 'operator_gt'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'data_setvariableto'
      && BL()[id].fields.VARIABLE && BL()[id].fields.VARIABLE[0] === 'smlo'));
  if (loops.length !== 1) throw new Error('[P191] ssplit main loop = ' + loops.length);
  const condId = BL()[loops[0]].inputs.CONDITION[1];
  const limit = AND(GT(F('smmax'), num(-1)), NOT(LT(F('smcnt'), F('smmax'))));
  replaceExpr(condId, () => OR(condId, limit));
  insertBeforeStmt(loops[0], [setV('smcnt', num(0))]);
  // count the matches: the branch that adds a field when `cmp == 0`
  const matchIf = find(sp, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_equals'
    && vnOf(BL()[b.inputs.CONDITION[1]].inputs.OPERAND1) === 'cmp'
    && litOf(BL()[b.inputs.CONDITION[1]].inputs.OPERAND2) === '0');
  if (matchIf.length !== 1) throw new Error('[P191] ssplit match branch = ' + matchIf.length);
  const mFirst = BL()[matchIf[0]].inputs.SUBSTACK[1];
  insertBeforeStmt(mFirst, [chgV('smcnt', num(1))]);
  // the tail field also exists when the cursor sits right after a trailing separator
  const tailIf = find(sp, (b) => b.opcode === 'control_if' && b.inputs.CONDITION
    && typeof b.inputs.CONDITION[1] === 'string'
    && BL()[b.inputs.CONDITION[1]].opcode === 'operator_not'
    && (() => {
      const o = BL()[b.inputs.CONDITION[1]].inputs.OPERAND;
      const q = (o && typeof o[1] === 'string') ? BL()[o[1]] : null;
      return !!q && q.opcode === 'operator_gt' && vnOf(q.inputs.OPERAND1) === 'smlo' && vnOf(q.inputs.OPERAND2) === 'smn';
    })());
  if (tailIf.length !== 1) throw new Error('[P191] ssplit tail branch = ' + tailIf.length);
  replaceExpr(BL()[tailIf[0]].inputs.CONDITION[1], () => NOT(GT(F('smlo'), ADD(F('smn'), num(1)))));
  console.log('[P191] ssplit counts matches, stops at the limit and keeps empty fields');
});

// ---- P192: `dict.pop(key, default)` (v4.119) ----
//
// `d.pop('x', 9)` raised `KeyError: 'x'` where CPython returns the default and leaves the dict alone.
// The dict branch of `dictmeth` (P91) looks the key up and then either returns its value (and, for
// `pop`, rebuilds the record run without it) or -- when the key is missing -- runs the *`get`* arm,
// which is where P117 put the
//
//   if meth == "pop" then fail(KeyError: '<key>')
//
// So the only thing missing is the "second argument = default" case, which `get` already implements
// as `if tqhcm == 1 then eval(tqcpz + 1, hi) else (ev = ""; evtype = "Z")`.  This patch wraps the
// KeyError branch in the same test: with a default the default expression is evaluated into `ev`
// (`eval` leaves the value and its type there), otherwise the old failure stands.
//
// Still a gap: `d.pop('x', 9, 8)` (CPython raises "too many arguments").
patch('P192 dict pop default', () => {
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const argName = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return (b && b.opcode === 'argument_reporter_string_number') ? b.fields.VALUE[0] : null;
  };
  const isMeth = (q, name) => !!q && q.opcode === 'operator_equals'
    && ((argName(q.inputs.OPERAND1) === 'meth' && litOf(q.inputs.OPERAND2) === name)
      || (argName(q.inputs.OPERAND2) === 'meth' && litOf(q.inputs.OPERAND1) === name));

  const dm = inDef('dictmeth %s %s %s %s %s');
  const keyFailIf = find(dm, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    if (!isMeth(BL()[b.inputs.CONDITION[1]], 'pop')) return false;
    const sub = b.inputs.SUBSTACK;
    if (!sub || typeof sub[1] !== 'string') return false;
    return [...reach(sub[1])].some((id) => JSON.stringify(BL()[id]).includes('KeyError'));
  });
  if (keyFailIf.length !== 1) throw new Error('[P192] pop KeyError branch = ' + keyFailIf.length);
  const failStmt = BL()[keyFailIf[0]].inputs.SUBSTACK[1];
  if (typeof failStmt !== 'string') throw new Error('[P192] KeyError statement not found');

  replaceStmt(keyFailIf[0], IF(EQ(argOf('meth'), txt('pop')), [
    IFELSE(GT(VAR('tqhcm'), num(0)), [
      callProc('eval %s %s', [ADD(VAR('tqcpz'), num(1)), argOf('hi')])
    ], [failStmt])
  ]));
  console.log('[P192] dict.pop(key, default) returns the default');
});

// ---- P193: `dict | dict` merges and `split(None)` (v4.120) ----
//
// `{1: 2} | {3: 4}` raised `TypeError: bitwise requires integers` (CPython: `{1: 2, 3: 4}`), and so did
// the in-place form `d |= {3: 4}`.
//
// The bitwise branch of `rightside` is `if op in ("^", "&", "|") and not (both sets)`, and for operands
// that are not numbers it walks a hand-written bit-string path that ends in
// `fail("TypeError: bitwise requires integers")`.  Two additions:
//
//   * in front of that branch, `if op == "|" and lt2 == "D" then`, and then
//     `if both dicts then dupd(leftval, ev) (the `dict.update` merger from P167, which rebuilds the
//      record and leaves it in `ev`) else binerr("|")` -- so `{1: 2} | [1]` reports CPython's
//     `unsupported operand type(s) for |: 'dict' and 'list'` instead of the bitwise wording;
//   * the bitwise branch's own condition also excludes two dicts, so it does not overwrite the merged
//     value afterwards.
//
// `dupd %s %s` takes the target record and the record to merge in, so the left operand is passed as
// `argOf('leftval')` (the value `rightside` was handed) and the right one is `ev`.
//
// Still a gap: `dict | non-dict` keeps an error (with CPython's wording), `dict | dict` in a
// comprehension or a `|` chain is fine because `dupd` returns a plain dict record, and a
// `split(None, maxsplit)` still raises because the whitespace splitter has no limit.
patch('P193 dict merge with |', () => {
  const F = (v) => VAR(v);
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const vnOf = (d) => (Array.isArray(d) && Array.isArray(d[1]) && d[1][0] === 12) ? d[1][1] : null;
  const rs = inDef('rightside %s %s %s %s %s');
  const popOf = (op) => OR(EQ(F('lt2'), txt(op)), EQ(F('evtype'), txt(op)));
  // the bitwise branch: `op in ("^", "|", "&")` with all three literals in its condition
  const bitIf = find(rs, (b) => {
    if (b.opcode !== 'control_if' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    if (!b.inputs.SUBSTACK || typeof b.inputs.SUBSTACK[1] !== 'string') return false;
    // the numeric bitwise branch is the one that ends in the "bitwise requires integers" failure
    const hasFail = [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === 'fail %s'
      && JSON.stringify(BL()[id].inputs).includes('bitwise requires integers'));
    if (!hasFail) return false;
    const xs = [...reach(b.inputs.CONDITION[1])];
    const has = (l) => xs.some((x) => BL()[x].opcode === 'operator_equals' && litOf(BL()[x].inputs.OPERAND2) === l);
    return has('^') && has('|') && has('&');
  });
  if (bitIf.length !== 1) throw new Error('[P193] bitwise branch = ' + bitIf.length);
  const bothDict = AND(EQ(F('lt2'), txt('D')), EQ(F('evtype'), txt('D')));
  insertBeforeStmt(bitIf[0], [
    IF(AND(EQ(argOf('op'), txt('|')), popOf('D')), [
      IFELSE(bothDict, [
        callProc('dupd %s %s', [argOf('leftval'), F('ev')]),
        setV('evtype', txt('D'))
      ], [
        setV('beop', txt('|')),
        setV('binL', argOf('leftval')), setV('binLT', F('lt0')),
        setV('binR', F('ev')), setV('binRT', F('evt0')),
        callProc('binerr', [])
      ])
    ])
  ]);
  // keep the bit-string path from running over the merged value
  const cond = BL()[bitIf[0]].inputs.CONDITION;
  const old = cond[1];
  replaceExpr(old, () => AND(old, NOT(AND(EQ(F('lt2'), txt('D')), EQ(F('evtype'), txt('D'))))));
  console.log('[P193] dict | dict merges (and dict | other reports the operand types)');

  // ---------- (b) `split(None)` is the whitespace splitter, not an empty separator
  //
  // P115 routes the call as `if smarg == 0 then ssplitw else (if sma1 == "" then fail else ssplit)`,
  // and a `None` argument arrives as the empty string with the type tag "Z", so `split(None)` -- and
  // `s.split(None)` / `s.split(None, maxsplit)` -- hit the ValueError arm.  The inner if/else only
  // needs widening: a None argument means "runs of whitespace", exactly what `ssplitw` already does,
  // while an explicit empty string still raises.  The whitespace splitter has no limit, so a
  // maxsplit keeps the old error rather than answering wrongly.
  const innerIf = find(allIds(), (b) => {
    if (b.opcode !== 'control_if_else' || !b.inputs.CONDITION || typeof b.inputs.CONDITION[1] !== 'string') return false;
    if (!b.inputs.SUBSTACK || typeof b.inputs.SUBSTACK[1] !== 'string') return false;
    const q = BL()[b.inputs.CONDITION[1]];
    if (!q || q.opcode !== 'operator_equals' || vnOf(q.inputs.OPERAND1) !== 'sma1' || litOf(q.inputs.OPERAND2) !== '') return false;
    return [...reach(b.inputs.SUBSTACK[1])].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === 'fail %s'
      && JSON.stringify(BL()[id].inputs).includes('empty separator'));
  });
  if (innerIf.length !== 1) throw new Error('[P193] split empty-separator branch = ' + innerIf.length);
  // the receiver reporter is the one the whitespace call in the other arm already holds
  const outerIf = find(allIds(), (b) => {
    if (b.opcode !== 'control_if_else' || !b.inputs.SUBSTACK || !b.inputs.SUBSTACK2) return false;
    const has = (root, pc) => [...reach(root[1])].some((id) => BL()[id].opcode === 'procedures_call'
      && BL()[id].mutation && BL()[id].mutation.proccode === pc);
    return has(b.inputs.SUBSTACK, 'ssplitw %s') && has(b.inputs.SUBSTACK2, 'ssplit %s %s');
  });
  if (outerIf.length !== 1) throw new Error('[P193] split dispatch if = ' + outerIf.length);
  const wCall = find(reach(outerIf[0]), (b) => b.opcode === 'procedures_call'
    && b.mutation && b.mutation.proccode === 'ssplitw %s');
  if (wCall.length !== 1) throw new Error('[P193] ssplitw call = ' + wCall.length);
  const wArgs = JSON.parse(BL()[wCall[0]].mutation.argumentids);
  const wRec = BL()[wCall[0]].inputs[wArgs[0]];
  const dupInput = (d) => {
    if (typeof d === 'string') return cloneExpr(d);
    const c = JSON.parse(JSON.stringify(d));
    if (Array.isArray(c) && typeof c[1] === 'string' && BL()[c[1]]) c[1] = cloneExpr(c[1]);
    return c;
  };
  replaceExpr(BL()[innerIf[0]].inputs.CONDITION[1],
    () => OR(EQ(F('smt1'), txt('Z')), EQ(F('sma1'), txt(''))));
  setStack(innerIf[0], 'SUBSTACK', [
    IFELSE(AND(EQ(F('smt1'), txt('Z')), LT(F('smmax'), num(0))), [
      callProc('ssplitw %s', [dupInput(wRec)])
    ], [
      FAIL(txt('ValueError: empty separator'))
    ])
  ]);
  console.log('[P193] split(None) uses the whitespace splitter');
});

// ---- P194: the bitwise operators accept negative integers (v4.121) ----
//
//   -1 | 0   -> ValueError: bitwise needs non-negative integers   (CPython: -1)
//   -2 & 3   -> same                                              (CPython: 2)
//   -1 ^ 1   -> same                                              (CPython: -2)
//   -1 << 2  -> same                                              (CPython: -4)
//   -8 >> 1  -> same                                              (CPython: -4)
//
// P25's `intCheck()` deliberately rejects a negative operand -- `bitop` walks the two operands bit
// by bit with `mod 2` / `floor(/2)`, which only describes non-negative integers.  The two guards
// (`if 任一侧 < 0 then fail`) are what the probes hit.
//
//   * `<<` / `>>` need no fix at all: the shift arm already computes `bt_r = base * 2` repeated and
//     `floor(base / 2)` repeated, which matches CPython for a negative base (`-1 << 2 = -4`,
//     `-8 >> 1 = -4`, `-3 >> 1 = -2`).  Its guard is lifted and replaced by the check that actually
//     belongs there: a negative **shift count** is CPython's `ValueError: negative shift count`.
//   * `& | ^` need two's complement.  The result of these three is the same as computing them on the
//     W-bit two's-complement representations and then reading the result back as signed, for any
//     W with `2^(W-1) > max(|a|, |b|)`.  So the arm first picks the smallest such power of two
//     (starting at 2, doubling until it exceeds `2 * max(|a|, |b|)`, capped at 2^53 so everything
//     stays exact in a double), maps a negative operand `x` to `x + 2^W`, runs the existing `bitop`
//     on the mapped pair, and maps a result `>= 2^(W-1)` back with `result - 2^W`.
//
// The arm still runs the **old** path unchanged when neither operand is negative (`bt_neg`):
// the copies `bt_a`/`bt_b` are taken either way, but the width scan and the sign fix only happen
// for the negative case, so a large non-negative result such as `(1 << 40) | 1` is untouched.
//
// Exactness: the mapping is exact while `max(|a|, |b|) < 2^52` (the sum `x + 2^W < 2^53`).
// Beyond that MiniPy's doubles have already lost the low bits, the same limit the `2**53 + 1`
// probe documents.
patch('P194 negative bitwise', () => {
  const F = (v) => VAR(v);
  const rs = inDef('rightside %s %s %s %s %s');
  const inChain = (stackId, target) => {
    let cur = stackId, n = 0;
    while (typeof cur === 'string' && cur && n++ < 5000) {
      if (cur === target) return true;
      cur = BL()[cur] && BL()[cur].next;
    }
    return false;
  };

  // ---------- (a) the two "non-negative" guards in intCheck() are lifted
  const negFail = find(rs, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && JSON.stringify(b.inputs).includes('bitwise needs non-negative'));
  if (negFail.length !== 2) throw new Error('[P194] negative bitwise fails = ' + negFail.length);
  const guards = find(rs, (b) => b.opcode === 'control_if'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && negFail.some((f) => inChain(b.inputs.SUBSTACK[1], f)));
  if (guards.length !== 2) throw new Error('[P194] negative bitwise guards = ' + guards.length);
  for (const g of guards) replaceExpr(BL()[g].inputs.CONDITION[1], () => EQ(num(0), num(1)));
  console.log('[P194] the non-negative guard is lifted in both arms');

  // ---------- (b) a negative shift count keeps CPython's wording
  const shiftSet = find(rs, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE
    && b.fields.VARIABLE[0] === 'bt_r'
    && Object.values(b.inputs).some((v) => typeof v[1] === 'string' && BL()[v[1]]
      && BL()[v[1]].opcode === 'argument_reporter_string_number' && BL()[v[1]].fields.VALUE[0] === 'leftval'));
  if (shiftSet.length !== 1) throw new Error('[P194] shift base set = ' + shiftSet.length);
  insertBeforeStmt(shiftSet[0], [
    IF(LT(F('ev'), num(0)), [FAIL(txt('ValueError: negative shift count'))])
  ]);
  console.log('[P194] a negative shift count is CPython\'s ValueError');

  // ---------- (c) two's complement for `& | ^` when a side is negative
  newVar('bt_m', 0); newVar('bt_n', 0); newVar('bt_w', 2); newVar('bt_neg', 0);
  const bitCall = find(rs, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'bitop %s %s %s');
  if (bitCall.length !== 1) throw new Error('[P194] bitop call = ' + bitCall.length);
  const argIds = JSON.parse(BL()[bitCall[0]].mutation.argumentids);
  insertBeforeStmt(bitCall[0], [
    setV('bt_a', argOf('leftval')), setV('bt_b', F('ev')), setV('bt_neg', num(0)),
    IF(OR(LT(F('bt_a'), num(0)), LT(F('bt_b'), num(0))), [
      setV('bt_neg', num(1)),
      // the smallest width with 2^(W-1) > max(|a|, |b|)
      setV('bt_m', F('bt_a')),
      IF(LT(F('bt_m'), num(0)), [setV('bt_m', SUB(num(0), F('bt_m')))]),
      setV('bt_n', F('bt_b')),
      IF(LT(F('bt_n'), num(0)), [setV('bt_n', SUB(num(0), F('bt_n')))]),
      IF(GT(F('bt_n'), F('bt_m')), [setV('bt_m', F('bt_n'))]),
      setV('bt_w', num(2)),
      REPEATU(OR(GT(F('bt_w'), MUL(F('bt_m'), num(2))), NOT(LT(F('bt_w'), num(9007199254740992)))), [
        setV('bt_w', MUL(F('bt_w'), num(2)))
      ]),
      IF(LT(F('bt_a'), num(0)), [setV('bt_a', ADD(F('bt_a'), F('bt_w')))]),
      IF(LT(F('bt_b'), num(0)), [setV('bt_b', ADD(F('bt_b'), F('bt_w')))])
    ])
  ]);
  BL()[bitCall[0]].inputs[argIds[1]] = B.REP(F('bt_a'), [4, '0']);
  BL()[bitCall[0]].inputs[argIds[2]] = B.REP(F('bt_b'), [4, '0']);
  spliceAfter(bitCall[0], chain([
    IF(EQ(F('bt_neg'), num(1)), [
      IF(NOT(LT(F('ev'), DIV(F('bt_w'), num(2)))), [setV('ev', SUB(F('ev'), F('bt_w')))])
    ])
  ]));
  console.log('[P194] negative & | ^ go through two\'s complement');
});

// ---- P195: bool on the left of a bitwise op, and `~-1` (v4.122) ----
//
// Two gaps the v4.120/v4.121 probes turned up, both from a check that was written before the thing
// it guards grew:
//
//   True | 1     -> TypeError: bitwise requires integers        (CPython: 1)
//   True & 1     -> same                                        (CPython: 1)
//   True | False -> same                                        (CPython: True)
//   True << 2    -> same                                        (CPython: 4)
//   ~-1          -> SyntaxError: unexpected token               (CPython: 0)
//   ~+1          -> same                                        (CPython: -2)
//
// (a) `1 & True` and `-1 | True` are fine -- only a bool on the **left** fails.  P10 normalises the
//     left operand's type by rewriting every reader of `lefttype` in `rightside` to the normalised
//     `lt2` (`if lt2 == "B" then lt2 = "N"`), but P25's bitwise arms were inserted *after* P10 ran,
//     so their type test still reads `argOf('lefttype')` and sees "B".  The two occurrences are the
//     `intCheck()` type tests (one per arm); this patch points them at `lt2` as well.
//
// (b) CPython keeps the result a bool when **both** `& | ^` operands were bools (`True | False` is
//     `True`, while `True | 1` is `1`).  P139 already keeps the original operand types in `lt0` /
//     `evt0`, so one statement after the `& | ^` arm's `evtype = "N"` restores the `B` tag when both
//     originals were bools.  (`(a)` alone would answer `1` for `True | False` -- right value, wrong
//     repr.)
//
// (c) `~-1` never reaches the unary machinery: `eval` splits a span at its lowest-rank operator, and
//     the scan's "is this sign unary?" test is `eprev` (the token before the current one) being one of
//     `( + - * / % // == < > <= >= != and or **` -- a list that predates `~` (P57 added `~` to the
//     *unary gate* but not to this chain).  So `~-1` split at the `-`, the left half became the span
//     `~` alone, and `atom` reported `unexpected token`.  `~5` worked because there the scan finds no
//     operator and the unary gate handles the span; `-~1` worked because `~` is never a binary
//     operator.  Adding `~` to the `eprev` chain makes the `-`/`+` after a `~` unary again.
patch('P195 bool bitwise + tilde sign', () => {
  const rs = inDef('rightside %s %s %s %s %s');
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const repName = (d) => {
    const b = (d && typeof d[1] === 'string') ? BL()[d[1]] : null;
    return (b && b.opcode === 'argument_reporter_string_number') ? b.fields.VALUE[0] : null;
  };

  // ---------- (a) the bitwise type check reads the normalised left type
  const vid = B.varIdOf('lt2');
  const sites = find(rs, (b) => b.opcode === 'operator_equals' && litOf(b.inputs.OPERAND2) === 'N'
    && repName(b.inputs.OPERAND1) === 'lefttype');
  if (sites.length !== 2) throw new Error('[P195] bitwise lefttype tests = ' + sites.length);
  let rewrites = 0;
  for (const id of sites) {
    const b = BL()[id];
    for (const [slot, v] of Object.entries(b.inputs)) {
      if (repName(v) !== 'lefttype') continue;
      b.inputs[slot] = v.length > 2 ? [v[0], [12, 'lt2', vid], v[2]] : [v[0], [12, 'lt2', vid]];
      rewrites++;
    }
  }
  if (rewrites !== 2) throw new Error('[P195] bitwise lefttype rewrites = ' + rewrites);
  console.log('[P195] the bitwise type check accepts a bool on the left');

  // ---------- (b) `& | ^` of two bools stays a bool
  const bitCall = find(rs, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'bitop %s %s %s');
  if (bitCall.length !== 1) throw new Error('[P195] bitop call = ' + bitCall.length);
  let cur = bitCall[0], evtypeSet = null;
  for (let i = 0; i < 20 && cur; i++) {
    cur = BL()[cur].next;
    if (!cur) break;
    const q = BL()[cur];
    if (q.opcode === 'data_setvariableto' && q.fields.VARIABLE && q.fields.VARIABLE[0] === 'evtype'
      && litOf(q.inputs.VALUE) === 'N') { evtypeSet = cur; break; }
  }
  if (!evtypeSet) throw new Error('[P195] `& | ^` evtype set not found');
  spliceAfter(evtypeSet, chain([
    IF(AND(EQ(VAR('lt0'), txt('B')), EQ(VAR('evt0'), txt('B'))), [setV('evtype', txt('B'))])
  ]));
  console.log('[P195] `& | ^` of two bools answers a bool');

  // ---------- (c) `~` counts as an operator for the "previous token" test
  // that test lives in `eval`'s operator scan (the `eprev` chain), not in `rightside`
  const ev = inDef('eval %s %s');
  const isPrevEq = (b) => b.opcode === 'operator_equals' && JSON.stringify(b.inputs).includes('"eprev"');
  const ors = find(ev, (b, id) => b.opcode === 'operator_or' && [...reach(id)].some((x) => isPrevEq(BL()[x])));
  const tops = ors.filter((id) => !ors.some((o) => o !== id && reach(o).has(id)));
  if (tops.length !== 1) throw new Error('[P195] eprev operator chain tops = ' + tops.length);
  const before = ors.length;
  replaceExpr(tops[0], () => OR(tops[0], EQ(VAR('eprev'), txt('~'))));
  console.log('[P195] `~` added to the previous-token operator test (' + before + ' chain nodes)');

  // ---------- (d) `-`/`+`/`~` accept a bool and answer an int
  // `unary` refuses anything whose evtype is not "N" -- so `~True` / `-True` said
  // `TypeError: numeric operand` (CPython: -2 / -1).  Widen the check to bools and make the numeric
  // branches leave an int behind (a bool on entry would otherwise keep the `B` tag).
  const un = inDef('unary %s %s %s');
  const numFail = find(un, (b) => b.opcode === 'procedures_call' && b.mutation && b.mutation.proccode === 'fail %s'
    && JSON.stringify(b.inputs).includes('numeric operand'));
  if (numFail.length !== 1) throw new Error('[P195] unary numeric fail = ' + numFail.length);
  const inChain2 = (stackId, target) => {
    let cur = stackId, n = 0;
    while (typeof cur === 'string' && cur && n++ < 200) { if (cur === target) return true; cur = BL()[cur].next; }
    return false;
  };
  const numIf = find(un, (b) => b.opcode === 'control_if' && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && inChain2(b.inputs.SUBSTACK[1], numFail[0]));
  if (numIf.length !== 1) throw new Error('[P195] unary numeric guard = ' + numIf.length);
  replaceExpr(BL()[numIf[0]].inputs.CONDITION[1],
    () => AND(NOT(EQ(VAR('evtype'), txt('N'))), NOT(EQ(VAR('evtype'), txt('B')))));
  const elseBody = (() => {
    const ref = refOf(numIf[0]);
    return (ref && ref.slot === 'SUBSTACK2') ? numIf[0] : null;
  })();
  if (!elseBody) throw new Error('[P195] unary numeric guard is not in the else branch');
  let tail = elseBody;
  while (BL()[tail].next) tail = BL()[tail].next;
  spliceAfter(tail, chain([setV('evtype', txt('N'))]));
  console.log('[P195] unary -/+/~ accept a bool and answer an int');
});

// ---- P196: min(xs, key=f) / max(xs, key=f) (v4.123) ----
//
//   min([3, 1, 2], key=lambda x: x)           -> SyntaxError: expression   (CPython: 1)
//   max(['bb', 'a', 'ccc'], key=len)          -> same                      (CPython: 'ccc')
//   min([(1, 5), (2, 3)], key=lambda p: p[1]) -> same                      (CPython: (2, 3))
//
// `eval` only understands `name=value` when it dispatches a call to `calluser` (P100/P165); a builtin
// call with a keyword falls into the "count the top-level commas" branch, where the `=` makes `eval`
// fail with `SyntaxError: expression`.  So the keyword form needs its own hook, in the same place the
// `sum(xs, start)` / `enumerate(xs, start)` / `sorted(x, key=...)` hooks live: inside the call branch
// of `eval`, in front of the `narg == 0` dispatch (there `narg` already counts the top-level commas).
//
//   * the hook only fires for `min`/`max` with at least one top-level comma **and** a top-level
//     `name =` piece.  Without a keyword piece it writes nothing but its own `mk*` scratch, so the
//     existing `builtin2` / `minmax` paths are untouched; with one it owns the call and stops the
//     script at the end (the same shape P130 uses for `sorted`).
//   * positional pieces: exactly one is the iterable (a string becomes its characters through
//     `charsplit`, a dict its keys through `dictkeys`, a list/tuple/set stays as is, anything else is
//     CPython's `TypeError: '<t>' object is not iterable`); two or more are evaluated and collected
//     into an encoded list, so `min(3, 1, 2, key=f)` works as well.
//   * the key function: `eval` of the `key=` value yields a function value (an index into `FnName`) --
//     or, for a single-token builtin name such as `len`/`abs`, the name itself.  Those are exactly the
//     two shapes P130's `callval` accepts (`p4fn` / `p4bi` / `p4bin`), so no new calling machinery.
//   * `minkey` walks the elements, calls the key through `callval` (which re-tokenizes the value as a
//     literal, calls it, and restores the line's tokens) and keeps the best element.  Comparing the
//     keys reuses P138's `lcmp`, so numbers, bools, strings, tuples and lists compare the CPython way
//     and a mixed pair raises CPython's `<` TypeError.  Ties keep the first element, because the best
//     element is only replaced on a *strict* comparison.
//
// `min([], key=f)` reports CPython's `ValueError: min() iterable argument is empty` (the wording the
// local CPython uses -- P185's lesson: ask the local interpreter, not memory).
patch('P196 min/max key', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const varName = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
    : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable')
      ? BL()[d[1]].fields.VARIABLE[0] : null);
  const enc = (acc, t, v) => JOIN(JOIN(JOIN(acc, VAR('lsep')), t), v);
  const tokAt = (i) => item('Tok', i);
  const VARS = ['mkpos', 'mkdep', 'mktok', 'mkhi', 'mkklo', 'mkkhi', 'mkbad', 'mkend', 'mkpn', 'mkpe',
    'mkacc', 'mkn', 'mki', 'mkbv', 'mkbt', 'mkbk', 'mkbkt', 'mkck', 'mkckt', 'mkmx', 'mkfn'];
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of VARS) if (taken.has(n)) throw new Error('[P196] variable name taken: ' + n);
  for (const v of VARS) newVar(v, 0);

  // ---------- (a) minkey: walk p4list, keep the best element by the key p4fn / p4bi / p4bin
  const take = () => [
    setV('mkbv', VAR('p4v')), setV('mkbt', VAR('p4vt')),
    setV('mkbk', VAR('mkck')), setV('mkbkt', VAR('mkckt'))
  ];
  const mk = newProc('minkey', []);
  attachBody(mk.defId, [
    callProc('listlen %s', [VAR('p4list')]), setV('mkn', VAR('ev')),
    IF(EQ(VAR('mkn'), num(0)), [
      FAILB(JOIN(VAR('mkfn'), txt('() iterable argument is empty'))),
      STOPTHIS()
    ]),
    callProc('listitem %s %s', [VAR('p4list'), num(1)]),
    setV('mkbv', VAR('ev')), setV('mkbt', VAR('evtype')),
    setV('p4v', VAR('mkbv')), setV('p4vt', VAR('mkbt')),
    callProc('callval', []),
    setV('mkbk', VAR('ev')), setV('mkbkt', VAR('evtype')),
    setV('mki', num(2)),
    REPEATU(GT(VAR('mki'), VAR('mkn')), [
      callProc('listitem %s %s', [VAR('p4list'), VAR('mki')]),
      setV('p4v', VAR('ev')), setV('p4vt', VAR('evtype')),
      callProc('callval', []),
      setV('mkck', VAR('ev')), setV('mkckt', VAR('evtype')),
      // lcmp answers `cmp` for lca vs lcb; a strict difference replaces the best element
      setV('lca', VAR('mkck')), setV('lcat', VAR('mkckt')),
      setV('lcb', VAR('mkbk')), setV('lcbt', VAR('mkbkt')),
      callProc('lcmp', []),
      IFELSE(EQ(VAR('mkmx'), num(1)), [
        IF(GT(VAR('cmp'), num(0)), take())
      ], [
        IF(LT(VAR('cmp'), num(0)), take())
      ]),
      chgV('mki', num(1))
    ]),
    setV('ev', VAR('mkbv')), setV('evtype', VAR('mkbt'))
  ]);
  console.log('[P196] minkey registered');

  // ---------- (b) the eval hook, in front of the `narg == 0` dispatch
  const ev2 = inDef('eval %s %s');
  const nargIf = find(ev2, (b) => (b.opcode === 'control_if' || b.opcode === 'control_if_else')
    && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      return !!q && q.opcode === 'operator_equals'
        && varName(q.inputs.OPERAND1) === 'narg' && litOf(q.inputs.OPERAND2) === '0';
    })());
  if (nargIf.length !== 1) throw new Error('[P196] narg dispatch = ' + nargIf.length);
  const open = (v) => OR(EQ(VAR(v), txt('(')), OR(EQ(VAR(v), txt('[')), EQ(VAR(v), txt('{'))));
  const close = (v) => OR(EQ(VAR(v), txt(')')), OR(EQ(VAR(v), txt(']')), EQ(VAR(v), txt('}'))));

  // scan 1: find the first `key =` and any other top-level `name =`
  const scanKw = [
    setV('mkpos', ADD(argOf('lo'), num(2))),
    setV('mkhi', SUB(argOf('hi'), num(1))),
    setV('mkdep', num(0)), setV('mkklo', num(0)), setV('mkkhi', num(0)),
    setV('mkend', num(0)), setV('mkbad', txt('')),
    REPEATU(GT(VAR('mkpos'), VAR('mkhi')), [
      setV('mktok', tokAt(VAR('mkpos'))),
      IF(open('mktok'), [chgV('mkdep', num(1))]),
      IF(close('mktok'), [chgV('mkdep', num(-1))]),
      IF(AND(EQ(VAR('mkdep'), num(0)), EQ(tokAt(ADD(VAR('mkpos'), num(1))), txt('='))), [
        IFELSE(EQ(VAR('mktok'), txt('key')), [
          IF(EQ(VAR('mkklo'), num(0)), [
            setV('mkklo', ADD(VAR('mkpos'), num(2))),
            setV('mkend', VAR('mkpos'))
          ])
        ], [
          setV('mkbad', VAR('mktok'))
        ])
      ]),
      chgV('mkpos', num(1))
    ])
  ];
  // scan 2: the key value starts at `mkklo` and ends before the next top-level comma (else at hi-1)
  const scanKeyEnd = [
    IF(GT(VAR('mkklo'), num(0)), [
      setV('mkkhi', VAR('mkhi')), setV('mkpos', VAR('mkklo')), setV('mkdep', num(0)),
      REPEATU(GT(VAR('mkpos'), VAR('mkhi')), [
        setV('mktok', tokAt(VAR('mkpos'))),
        IF(open('mktok'), [chgV('mkdep', num(1))]),
        IF(close('mktok'), [chgV('mkdep', num(-1))]),
        IF(AND(EQ(VAR('mkdep'), num(0)), AND(EQ(VAR('mktok'), txt(',')), EQ(VAR('mkkhi'), VAR('mkhi')))), [
          setV('mkkhi', SUB(VAR('mkpos'), num(1)))
        ]),
        chgV('mkpos', num(1))
      ])
    ])
  ];
  // the positional part is [lo+2 .. mkend-2]: one piece is the iterable, several become a list
  const scanPieces = [
    setV('mkhi', SUB(VAR('mkend'), num(2))),
    setV('mkn', num(0)), setV('mkdep', num(0)), setV('mkpos', ADD(argOf('lo'), num(2))),
    REPEATU(GT(VAR('mkpos'), VAR('mkhi')), [
      setV('mktok', tokAt(VAR('mkpos'))),
      IF(open('mktok'), [chgV('mkdep', num(1))]),
      IF(close('mktok'), [chgV('mkdep', num(-1))]),
      IF(AND(EQ(VAR('mkdep'), num(0)), EQ(VAR('mktok'), txt(','))), [chgV('mkn', num(1))]),
      chgV('mkpos', num(1))
    ]),
    IFELSE(EQ(VAR('mkn'), num(0)), [
      callProc('eval %s %s', [ADD(argOf('lo'), num(2)), VAR('mkhi')])
    ], [
      setV('mkacc', txt('')), setV('mkpos', ADD(argOf('lo'), num(2))),
      REPEATU(EQ(VAR('mkpos'), num(0)), [
        setV('mkpe', VAR('mkhi')), setV('mkpn', num(0)), setV('mkdep', num(0)), setV('mki', VAR('mkpos')),
        REPEATU(GT(VAR('mki'), VAR('mkhi')), [
          setV('mktok', tokAt(VAR('mki'))),
          IF(open('mktok'), [chgV('mkdep', num(1))]),
          IF(close('mktok'), [chgV('mkdep', num(-1))]),
          IF(AND(EQ(VAR('mkdep'), num(0)), EQ(VAR('mktok'), txt(','))), [
            IF(EQ(VAR('mkpn'), num(0)), [
              setV('mkpe', SUB(VAR('mki'), num(1))),
              setV('mkpn', ADD(VAR('mki'), num(1)))
            ])
          ]),
          chgV('mki', num(1))
        ]),
        callProc('eval %s %s', [VAR('mkpos'), VAR('mkpe')]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        callProc('lesc %s', [VAR('ev')]),
        setV('mkacc', enc(VAR('mkacc'), VAR('evtype'), VAR('ev'))),
        setV('mkpos', VAR('mkpn'))
      ]),
      setV('ev', VAR('mkacc')), setV('evtype', txt('L'))
    ])
  ];
  const body = [
    ...scanKw,
    ...scanKeyEnd,
    IF(GT(VAR('mkend'), num(0)), [
      IFELSE(NOT(EQ(VAR('mkbad'), txt(''))), [
        FAILB(JOIN(JOIN(JOIN(tokAt(argOf('lo')), txt("() got an unexpected keyword argument '")), VAR('mkbad')), txt("'"))),
        STOPTHIS()
      ], [
        ...scanPieces,
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        // the iterable
        IF(EQ(VAR('evtype'), txt('S')), [callProc('charsplit', [])]),
        IF(EQ(VAR('evtype'), txt('D')), [callProc('dictkeys %s', [VAR('ev')])]),
        IF(NOT(OR(EQ(VAR('evtype'), txt('L')), OR(EQ(VAR('evtype'), txt('T')), EQ(VAR('evtype'), txt('E'))))), [
          setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
          FAILB(JOIN(JOIN(txt("TypeError: '"), VAR('p6msg')), txt("' object is not iterable"))),
          STOPTHIS()
        ]),
        setV('p4list', VAR('ev')),
        // the key function
        setV('p4bi', num(0)),
        callProc('eval %s %s', [VAR('mkklo'), VAR('mkkhi')]),
        IFELSE(EQ(VAR('error'), txt('')), [
          setV('p4fn', item('FnName', VAR('ev')))
        ], [
          IFELSE(EQ(VAR('mkkhi'), VAR('mkklo')), [
            setV('p4bin', tokAt(VAR('mkklo'))), setV('p4bi', num(1)), setV('error', txt(''))
          ], [
            FAILB(JOIN(tokAt(argOf('lo')), txt('() key must be a function'))),
            STOPTHIS()
          ])
        ]),
        IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
        IFELSE(EQ(tokAt(argOf('lo')), txt('max')), [setV('mkmx', num(1))], [setV('mkmx', num(0))]),
        setV('mkfn', tokAt(argOf('lo'))),
        callProc('minkey', []),
        setV('fnlimit', num(-1)),
        STOPTHIS()
      ])
    ])
  ];
  insertBeforeStmt(nargIf[0], [
    IF(AND(OR(EQ(tokAt(argOf('lo')), txt('min')), EQ(tokAt(argOf('lo')), txt('max'))), GT(VAR('narg'), num(0))), body)
  ]);
  console.log('[P196] eval: min/max with key= installed');
});

// ---- P197: starred assignment targets -- a, *rest = [1, 2, 3] (v4.124) ----
//
//   a, *rest = [1, 2, 3]     -> SyntaxError: invalid assignment target   (CPython: a=1, rest=[2, 3])
//   *init, last = [1, 2, 3]  -> SyntaxError: missing expression          (CPython: init=[1, 2], last=3)
//
// `assignlist` walks the target with a fixed stride -- `if Kind[mi] != "I" then fail` and `mi += 2` --
// so a `*` (punctuation) stops it with `invalid assignment target`, and a target that *starts* with
// `*` never reaches `assignlist` at all (the statement dispatcher reads `*` as an operator).
//
// The fix has three parts, all inside `assignlist`:
//
//   * the name loop learns the `*name` form: a punctuation `*` followed by a name bumps `mi` by one
//     and records the star in a parallel list `AStar` (one 0/1 per name) and in the `auexs` flag,
//     and the stride becomes `2 + auex`;
//   * when any name is starred, the whole right-hand side is evaluated **once** (P84's container
//     unpacking already does that for a count mismatch) and the binding happens here: the names
//     before the star take the first elements, the names after it take the last ones, and the
//     starred name takes the middle slice **as a list** (CPython gives a list even for a tuple
//     source).  Strings iterate as characters, dicts as their keys, lists/tuples/sets element-wise;
//     anything else is CPython's `TypeError: cannot unpack non-iterable <type> object`;
//   * `a, *r = []` reports CPython's `ValueError: not enough values to unpack (expected at least N,
//     got M)`, and a lone `*r = [...]` is CPython's
//     `SyntaxError: starred assignment target must be in a list or tuple`.
//
// The `*` in the target is also accepted where the statement dispatcher would otherwise treat it as
// an operator: it only has to recognise `*` + name at the very start of a statement as an assignment
// target (part (d)) and hand the line to `assignlist` as usual.
patch('P197 starred assignment', () => {
  const STOPTHIS = () => I('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const litOf = (d) => {
    if (!d) return null;
    if (Array.isArray(d) && (d[0] === 10 || d[0] === 4) && typeof d[1] !== 'object') return String(d[1]);
    if (Array.isArray(d[1]) && (d[1][0] === 10 || d[1][0] === 4)) return String(d[1][1]);
    return null;
  };
  const tokAt = (i) => item('Tok', i);
  const taken = new Set(Object.values(T(IT).variables).map((x) => x[0]));
  for (const n of ['auex', 'auexs', 'auk', 'aui', 'aux', 'auhi', 'aubuf']) {
    if (taken.has(n)) throw new Error('[P197] variable name taken: ' + n);
  }
  for (const v of ['auex', 'auexs', 'auk', 'aui', 'aux', 'auhi', 'aubuf']) newVar(v, 0);
  B.addList(IT, 'AStar', []);

  const al = inDef('assignlist %s');
  // ---------- (a) the star form in the name loop
  const nameAppend = find(al, (b) => b.opcode === 'data_addtolist' && b.fields.LIST && b.fields.LIST[0] === 'AName');
  if (nameAppend.length !== 1) throw new Error('[P197] AName append = ' + nameAppend.length);
  const anameClear = find(al, (b) => b.opcode === 'data_deletealloflist' && b.fields.LIST && b.fields.LIST[0] === 'AName');
  if (anameClear.length !== 1) throw new Error('[P197] AName clear = ' + anameClear.length);
  spliceAfter(anameClear[0], chain([clearL('AStar'), setV('auexs', num(0))]));
  const kindIf = find(al, (b) => b.opcode === 'control_if'
    && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && JSON.stringify(b.inputs.CONDITION).includes('"AName"') === false
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'data_itemoflist'
      && BL()[x].fields.LIST && BL()[x].fields.LIST[0] === 'Kind')
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call'
      && BL()[x].mutation && BL()[x].mutation.proccode === 'fail %s'
      && JSON.stringify(BL()[x].inputs).includes('invalid assignment target')));
  if (kindIf.length !== 1) throw new Error('[P197] name-kind check = ' + kindIf.length);
  insertBeforeStmt(kindIf[0], [
    IFELSE(AND(EQ(item('Kind', VAR('mi')), txt('O')),
      AND(EQ(tokAt(VAR('mi')), txt('*')), EQ(item('Kind', ADD(VAR('mi'), num(1))), txt('I')))), [
      setV('auex', num(1)), setV('auexs', num(1)), chgV('mi', num(1))
    ], [
      setV('auex', num(0))
    ])
  ]);
  const miBump = find(al, (b) => b.opcode === 'data_changevariableby' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'mi'
    && litOf(b.inputs.VALUE) === '2');
  if (miBump.length !== 1) throw new Error('[P197] mi stride = ' + miBump.length);
  // NB: the stride stays 2 -- the star case bumps `mi` by one *before* the name is appended, so
  // `name , name` still advances by two from the name itself (`*name , name` was three from the `*`).
  spliceAfter(nameAppend[0], chain([addTo('AStar', VAR('auex'))]));
  console.log('[P197] the name loop understands `*name`');

  // ---------- (b) the extended binding, once a star was seen
  const elemAt = (idx) => IFELSE(EQ(VAR('aut'), txt('S')),
    [setV('ev', letterOf(VAR(idx), VAR('auenc'))), setV('evtype', txt('S'))],
    [callProc('listitem %s %s', [VAR('auenc'), VAR(idx)])]);
  const notEnough = () => [
    FAILB(JOIN(JOIN(JOIN(txt('ValueError: not enough values to unpack (expected at least '),
      SUB(llen('AName'), num(1))), txt(', got ')), JOIN(VAR('aun'), txt(')')))),
    STOPTHIS()
  ];
  const starBody = [
    setV('aui', num(1)), setV('auk', num(0)),
    REPEATU(GT(VAR('aui'), llen('AName')), [
      IF(EQ(item('AStar', VAR('aui')), num(1)), [setV('auk', VAR('aui'))]),
      chgV('aui', num(1))
    ]),
    IF(AND(EQ(llen('AName'), num(1)), EQ(VAR('auk'), num(1))), [
      FAIL(txt('SyntaxError: starred assignment target must be in a list or tuple')), STOPTHIS()
    ]),
    // the whole right-hand side is evaluated exactly once
    callProc('eval %s %s', [ADD(argOf('eqi'), num(1)), VAR('count')]),
    IF(NOT(EQ(VAR('error'), txt(''))), [STOPTHIS()]),
    IF(NOT(OR(EQ(VAR('evtype'), txt('L')), OR(EQ(VAR('evtype'), txt('T')),
      OR(EQ(VAR('evtype'), txt('S')), OR(EQ(VAR('evtype'), txt('E')), EQ(VAR('evtype'), txt('D'))))))), [
      setV('p6v', VAR('ev')), setV('p6t', VAR('evtype')), callProc('tname', []),
      FAILB(JOIN(JOIN(txt('TypeError: cannot unpack non-iterable '), VAR('p6msg')), txt(' object'))),
      STOPTHIS()
    ]),
    IF(EQ(VAR('evtype'), txt('D')), [callProc('dictkeys %s', [VAR('ev')])]),
    setV('auenc', VAR('ev')), setV('aut', VAR('evtype')),
    IFELSE(EQ(VAR('aut'), txt('S')),
      [setV('aun', lenOf(VAR('auenc')))],
      [callProc('listlen %s', [VAR('auenc')]), setV('aun', VAR('ev'))]),
    IF(LT(VAR('aun'), SUB(llen('AName'), num(1))), notEnough()),
    setV('aui', num(1)),
    REPEATU(GT(VAR('aui'), llen('AName')), [
      IFELSE(EQ(VAR('aui'), VAR('auk')), [
        // the starred name: the middle slice, always as a list
        setV('auhi', SUB(VAR('aun'), SUB(llen('AName'), VAR('aui')))),
        setV('aubuf', txt('')), setV('aux', VAR('aui')),
        REPEATU(GT(VAR('aux'), VAR('auhi')), [
          elemAt('aux'),
          callProc('lesc %s', [VAR('ev')]),
          setV('aubuf', JOIN(JOIN(JOIN(VAR('aubuf'), VAR('lsep')), VAR('evtype')), VAR('ev'))),
          chgV('aux', num(1))
        ]),
        setV('ev', VAR('aubuf')), setV('evtype', txt('L'))
      ], [
        IFELSE(LT(VAR('aui'), VAR('auk')), [
          elemAt('aui')
        ], [
          setV('aux', SUB(VAR('aun'), SUB(llen('AName'), VAR('aui')))),
          elemAt('aux')
        ])
      ]),
      callProc('aldrop %s', [item('AName', VAR('aui'))]),
      callProc('assign %s %s %s', [item('AName', VAR('aui')), VAR('ev'), VAR('evtype')]),
      chgV('aui', num(1))
    ]),
    STOPTHIS()
  ];
  // the loop is the repeat-until that owns the kind check
  const nameLoop = find(al, (b) => b.opcode === 'control_repeat_until'
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => x === kindIf[0]));
  if (nameLoop.length !== 1) throw new Error('[P197] name loop = ' + nameLoop.length);
  spliceAfter(nameLoop[0], chain([IF(EQ(VAR('auexs'), num(1)), starBody)]));
  console.log('[P197] starred targets bind element/middle-slice');

  // ---------- (c) a statement that *starts* with `*name` is an unpacking target
  // `execute`'s branch for `name , ... = ...` tests `Kind[1] == "I" and Tok[2] == ","`; the starred
  // form has its comma one token further along, so the branch gets a second alternative.
  const ex = inDef('execute');
  const headBranch = find(ex, (b) => b.opcode === 'control_if'
    && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && litOf(BL()[x].inputs.OPERAND2) === 'I'
      && BL()[x].inputs.OPERAND1 && typeof BL()[x].inputs.OPERAND1[1] === 'string'
      && BL()[BL()[x].inputs.OPERAND1[1]].opcode === 'data_itemoflist'
      && BL()[BL()[x].inputs.OPERAND1[1]].fields.LIST && BL()[BL()[x].inputs.OPERAND1[1]].fields.LIST[0] === 'Kind')
    && [...reach(b.inputs.CONDITION[1])].some((x) => BL()[x].opcode === 'operator_equals'
      && litOf(BL()[x].inputs.OPERAND2) === ',')
    && b.inputs.SUBSTACK && typeof b.inputs.SUBSTACK[1] === 'string'
    && [...reach(b.inputs.SUBSTACK[1])].some((x) => BL()[x].opcode === 'procedures_call'
      && BL()[x].mutation && BL()[x].mutation.proccode === 'assignlist %s'));
  if (headBranch.length !== 1) throw new Error('[P197] `name , ... =` branch = ' + headBranch.length);
  const occ = (x) => BL()[x].inputs.CONDITION[1];
  replaceExpr(occ(headBranch[0]), () => OR(occ(headBranch[0]),
    AND(EQ(tokAt(num(1)), txt('*')), AND(EQ(item('Kind', num(2)), txt('I')),
      AND(EQ(tokAt(num(3)), txt(',')), NOT(EQ(item('Kind', num(3)), txt('S'))))))));
  console.log('[P197] a leading `*name` reaches assignlist');
});

// ---- P198: `for <name> in <list>` iterates the whole list (v4.125) ----
//
//   for x in [[9], [8], [7]]:    -> only ONE iteration    (CPython: three)
//   for x in [[1, 2, 3], [4, 5]]: -> three iterations     (CPython: two, the last one empty)
//   for x in [9, 8, 7]:           -> correct (three)      <- flat sources were always fine
//
// `forloop` has two list paths: the tuple-target one (`for a, b in ...`, added by P89) and the base
// one (`for name in ...`).  Both compute the length with `listlen` and push it as `LoopStop`, but
// their statement order differs:
//
//   P89:   pushLoop(... flen ...) ; LoopText[...] = ltmp ; listitem ; unpackto
//   base:  listitem ; assign ; pushLoop(... ln ...) ; LoopText[...] = ltmp
//
// and P89's comment already says why the first shape is the safe one: "pushLoop first: its arguments
// are read before the call, so nothing the first-element binding does afterwards can disturb them".
// The base path does the binding *first*, and with a **container** first element (`[[9], ...]` ->
// the element is the list `[9]`, which goes through `listitem`'s un-escaping path) the pushed length
// ends up as `1`: instrumenting the built project shows `ln` = 3 right after `listlen`, and `ln` = 1
// immediately after the `pushLoop` call, i.e. `LoopStop` = 1 -> exactly one iteration.  Flat sources
// have a number/string element, take the short `listitem` path and never disturb it, which is why
// this only ever showed up for a list **of containers**.
//
// The fix is therefore the same reordering P89 uses: push the loop (and record `LoopText`) *before*
// binding the first element.  No new variables, no new blocks -- the four existing statements are
// just relinked.
patch('P198 for-in-list order', () => {
  const fl = inDef('forloop');
  const isEvRef = (v) => !!v && ((Array.isArray(v[1]) && v[1][0] === 12 && v[1][1] === 'ev')
    || (typeof v[1] === 'string' && BL()[v[1]] && BL()[v[1]].opcode === 'data_variable' && BL()[v[1]].fields.VARIABLE[0] === 'ev'));
  // the base path: `ln = ev` right after `listlen(ltmp)`
  const lnSet = find(fl, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE && b.fields.VARIABLE[0] === 'ln'
    && isEvRef(b.inputs.VALUE));
  if (lnSet.length !== 1) throw new Error('[P198] `ln = ev` = ' + lnSet.length);
  // its enclosing `if ln > 0`
  const guard = find(fl, (b) => b.opcode === 'control_if_else'
    && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && (() => {
      const q = BL()[b.inputs.CONDITION[1]];
      if (!q || q.opcode !== 'operator_gt') return false;
      const nm = (d) => (Array.isArray(d && d[1]) && d[1][0] === 12) ? d[1][1]
        : ((d && typeof d[1] === 'string' && BL()[d[1]] && BL()[d[1]].opcode === 'data_variable') ? BL()[d[1]].fields.VARIABLE[0] : null);
      const lit = (d) => (Array.isArray(d) && Array.isArray(d[1]) && (d[1][0] === 4 || d[1][0] === 10)) ? String(d[1][1]) : null;
      return nm(q.inputs.OPERAND1) === 'ln' && lit(q.inputs.OPERAND2) === '0';
    })());
  if (guard.length !== 1) throw new Error('[P198] `if ln > 0` = ' + guard.length);
  const body = BL()[guard[0]].inputs.SUBSTACK;
  if (!body || typeof body[1] !== 'string') throw new Error('[P198] list branch body missing');
  const stmts = [];
  let cur = body[1];
  while (typeof cur === 'string' && cur) { stmts.push(cur); cur = BL()[cur].next; }
  const push = stmts.filter((id) => BL()[id].opcode === 'procedures_call' && BL()[id].mutation
    && BL()[id].mutation.proccode === 'pushLoop %s %s %s %s %s'
    && JSON.stringify(BL()[id].inputs).includes('"ln"'));
  const text = stmts.filter((id) => BL()[id].opcode === 'data_replaceitemoflist'
    && BL()[id].fields.LIST && BL()[id].fields.LIST[0] === 'LoopText');
  if (push.length !== 1 || text.length !== 1) throw new Error('[P198] pushLoop=' + push.length + ' LoopText=' + text.length);
  const rest = stmts.filter((id) => id !== push[0] && id !== text[0]);
  const order = [push[0], text[0], ...rest];
  setStack(guard[0], 'SUBSTACK', order);
  BL()[order[order.length - 1]].next = null;
  console.log('[P198] the base for-in-list path pushes the loop before binding (' + order.length + ' statements)');
});

// ---- P199: physical special keys + one-row keypad with full names (Controller) ----
//
// (1) Every special (punctuation) key of a US keyboard is READ FROM THE KEYBOARD
//     with the sensing reporter `key (join <char> and "") pressed?` - the hat
//     block's dropdown cannot name these characters, the reporter can carry
//     anything through a `join`.  32 chars are polled once per frame in a new
//     Controller proc `keypoll`, with rise-edge detection through the new list
//     `KDown`, so holding a key inserts ONE character.  The five punctuation
//     hats that existed before ( . , - / = ) are removed so nothing lands twice.
//
// (2) The on-screen keypad becomes ONE row of five keys, spelled out in full:
//         TAB   ENTER   BACKSPACE   CASE   SPEED
//     The old row (2 x 12, 13.25px keys, abbreviations TAB/ENT/BK/Aa/SP) is
//     replaced wholesale - painting 24 keys of which 19 were symbols and the
//     leftovers of a v2 palette no longer makes sense.  Behaviour is unchanged:
//     TAB = 4 spaces, ENTER = new line, BACKSPACE = delete left, CASE = A/a
//     switch, SPEED = fast / slow run.
patch('P199 symbol keys + one-row keypad', () => {
  const fs = require('fs');
  const crypto = require('crypto');
  const CTRL = 'Controller';
  B.setCtx(CTRL);
  const CB = () => T(CTRL).blocks;
  // ctx-aware builders (head.txt's helpers are Interpreter-bound, same as P56)
  const ci = (op, opts) => B.B(CTRL, op, opts);
  const cchain = (ids) => B.chain(CTRL, ids);
  const csub = (parentId, slot, ids) => {
    const first = ids.length ? cchain(ids) : null;
    CB()[parentId].inputs[slot] = [2, first];
    if (first) CB()[first].parent = parentId;
    return first;
  };
  const cvar = (n) => B.VAR(n);
  const csetV = (n, v) => ci('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [10, '']) } });
  const cjoin = (a, b) => ci('operator_join', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const ceq = (a, b) => ci('operator_equals', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cgt = (a, b) => ci('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const csub2 = (a, b) => ci('operator_subtract', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const cif = (c, ids) => { const id = ci('control_if', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', ids); return id; };
  const cifelse = (c, a, b) => {
    const id = ci('control_if_else', { inputs: { CONDITION: B.BOOL(c) } });
    csub(id, 'SUBSTACK', a); csub(id, 'SUBSTACK2', b); return id;
  };
  const citem = (l, i) => ci('data_itemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const creplace = (l, i, v) => ci('data_replaceitemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const defOf = (proccode) => {
    for (const [id, b] of Object.entries(CB())) {
      if (b.opcode === 'procedures_definition' && b.inputs && b.inputs.custom_block) {
        const pr = CB()[b.inputs.custom_block[1]];
        if (pr && pr.mutation && pr.mutation.proccode === proccode) return id;
      }
    }
    throw new Error('[P199] controller def not found: ' + proccode);
  };
  const ccall = (proccode, args) => {
    const defId = defOf(proccode);
    const proto = CB()[CB()[defId].inputs.custom_block[1]];
    const ids = JSON.parse(proto.mutation.argumentids);
    const inputs = {};
    for (let i = 0; i < ids.length; i++) inputs[ids[i]] = B.REP((args || [])[i], [10, '']);
    return ci('procedures_call', { inputs, mutation: { tagName: 'mutation', children: [], proccode, argumentids: proto.mutation.argumentids, warp: proto.mutation.warp || 'true' } });
  };
  const attach = (defId, ids) => { const first = ids.length ? cchain(ids) : null; CB()[defId].next = first; if (first) CB()[first].parent = defId; return first; };

  // ---- 1. all punctuation a US keyboard can produce (32 characters)
  const SYM = ['`', '-', '=', '[', ']', '\\', ';', "'", ',', '.', '/',
    '~', '!', '@', '#', '$', '%', '^', '&', '*', '(', ')', '_', '+',
    '{', '}', '|', ':', '"', '<', '>', '?'];

  B.addList(CTRL, 'KDown', SYM.map(() => 0));   // last frame's state, per character
  B.addVar(CTRL, 'kdv', 0);                     // this frame's state of the char being polled

  // key (join <char> and "") pressed?   <- the reporter carries any character
  const ckey = (ch) => ci('sensing_keypressed', { inputs: { KEY_OPTION: B.REP(cjoin(B.txt(ch), B.txt('')), [10, 'space']) } });

  const poll = [];
  SYM.forEach((ch, i) => {
    poll.push(csetV('kdv', B.num(0)));
    poll.push(cif(ckey(ch), [
      csetV('kdv', B.num(1)),
      cif(ceq(citem('KDown', B.num(i + 1)), B.num(0)), [ccall('insert %s', [B.txt(ch)])])
    ]));
    poll.push(creplace('KDown', B.num(i + 1), cvar('kdv')));
  });
  const kp = B.makeProcedure(CTRL, 'keypoll', [], true);
  attach(kp.defId, poll);
  console.log('[P199] keypoll polls ' + SYM.length + ' characters');

  // run it once per frame, inside the Controller's existing mouse-polling loop
  const forevers = Object.entries(CB()).filter(([, b]) => b.opcode === 'control_forever');
  if (forevers.length !== 1) throw new Error('[P199] expected 1 forever loop, got ' + forevers.length);
  let tail = CB()[forevers[0][0]].inputs.SUBSTACK[1];
  if (!tail) throw new Error('[P199] forever loop is empty');
  while (CB()[tail].next) tail = CB()[tail].next;
  const call = ccall('keypoll', []);
  CB()[tail].next = call;
  CB()[call].parent = tail;
  console.log('[P199] keypoll wired into the Controller main loop');

  // ---- 2. punctuation hats -> the poller (otherwise every char lands twice)
  for (const ch of ['.', ',', '-', '/', '=']) {
    const hats = Object.entries(CB()).filter(([, b]) => b.opcode === 'event_whenkeypressed' && b.fields.KEY_OPTION[0] === ch);
    if (hats.length !== 1) throw new Error('[P199] expected 1 hat for "' + ch + '", got ' + hats.length);
    delete CB()[hats[0][0]];
  }
  console.log('[P199] removed 5 punctuation hats (. , - / =)');

  // ---- 3. the keypad: one row, five keys, full names
  const KEYW = { TAB: 22, ENTER: 30, BACKSPACE: 46, CASE: 25, SPEED: 28 };   // 308..467, 2px gaps
  const KX0 = 308;                                                          // svg x of the row
  // click thresholds in Scratch coordinates (svg x - 240), mid-gap between keys
  const TH = [91, 123, 171, 198];

  const allText = (id, acc) => {
    const b = CB()[id]; if (!b) return acc;
    for (const f of Object.values(b.fields || {})) if (typeof f[0] === 'string') acc.push(f[0]);
    for (const inp of Object.values(b.inputs || {})) {
      for (const x of [].concat(inp)) {
        if (typeof x === 'string') { if (CB()[x]) allText(x, acc); else acc.push(x); }
        else if (x !== null && typeof x === 'object') for (const y of x) if (typeof y === 'string') acc.push(y);
      }
    }
    return acc;
  };
  let region = null;
  for (const [id, b] of Object.entries(CB())) {
    if (b.opcode !== 'control_if') continue;
    const cond = [].concat(b.inputs.CONDITION || []).find((x) => typeof x === 'string');
    if (!cond) continue;
    const txt2 = allText(cond, []);
    if (txt2.includes('67') && txt2.includes('231') && txt2.includes('ux')) region = id;
  }
  if (!region) throw new Error('[P199] keypad region not found');
  // the guard also covers 8px of empty space below the old two-row keypad: pull its
  // lower edge up to the new (single, 23px tall) row so dead clicks stay dead
  let guard = 0;
  for (const [id, b] of Object.entries(CB())) {
    if (b.opcode !== 'operator_gt') continue;
    if (JSON.stringify(b.inputs || {}).includes('"-154"') && JSON.stringify(b.inputs || {}).includes('uy')) {
      b.inputs.OPERAND2 = [1, [4, '-147']];
      guard++;
    }
  }
  if (guard !== 1) throw new Error('[P199] keypad guard sites = ' + guard);

  const capsToggle = [
    csetV('caps', csub2(B.num(1), cvar('caps'))),
    cifelse(ceq(cvar('caps'), B.num(1)),
      [csetV('status', B.txt('Case UPPER on  (CASE lit)'))],
      [csetV('status', B.txt('Case lower on  (CASE off)'))]),
    csetV('dirty', B.num(1))
  ];
  const speedToggle = [
    csetV('speed', csub2(B.num(1), cvar('speed'))),
    cifelse(ceq(cvar('speed'), B.num(1)),
      [csetV('status', B.txt('Speed FAST  (SPEED lit)'))],
      [csetV('status', B.txt('Speed SLOW  (1 line/frame)'))]),
    csetV('dirty', B.num(1))
  ];
  csub(region, 'SUBSTACK', [
    cifelse(cgt(B.num(TH[0]), cvar('ux')), [ccall('tab', [])], [
      cifelse(cgt(B.num(TH[1]), cvar('ux')), [ccall('newline', [])], [
        cifelse(cgt(B.num(TH[2]), cvar('ux')), [ccall('backspace', [])], [
          cifelse(cgt(B.num(TH[3]), cvar('ux')), capsToggle, speedToggle)
        ])
      ])
    ])
  ]);
  console.log('[P199] keypad = one row: TAB | ENTER | BACKSPACE | CASE | SPEED');

  // ---- 4. backdrop: swap the old 2 x 12 key row for that single row
  const row = (() => {
    let x = KX0;
    let out = '<g font-family="Arial,Helvetica,sans-serif" font-size="6" font-weight="700" text-anchor="middle" fill="#333">';
    for (const label of Object.keys(KEYW)) {
      const w = KEYW[label];
      out += '<rect x="' + x + '" y="303" width="' + w + '" height="23" fill="#fcfcfc" stroke="#d6d6d6" stroke-width="0.7"/>';
      out += '<text x="' + (x + w / 2) + '" y="318">' + label + '</text>';
      x += w + 2;
    }
    return out + '</g>';
  })();
  const oldRow = /<g font-family="Arial,Helvetica,sans-serif" font-size="5\.4" font-weight="700" text-anchor="middle" fill="#333">[\s\S]*?<\/g>/;
  let touched = 0;
  for (const c of (T('Stage').costumes || [])) {
    const nm = c.md5ext || (c.assetId + '.' + (c.dataFormat || 'svg'));
    if (!/\.svg$/.test(nm)) continue;
    const ent = entries.find((e) => e.name === nm);
    if (!ent) continue;
    let svg = ent.data.toString('utf8');
    if (svg.indexOf('>TAB</text>') < 0) continue;    // not the keyboard backdrop
    const hits = (svg.match(new RegExp(oldRow.source, 'g')) || []).length;
    if (hits !== 1) throw new Error('[P199] keypad groups found = ' + hits);
    svg = svg.replace(oldRow, row);
    const buf = Buffer.from(svg, 'utf8');
    const md5 = crypto.createHash('md5').update(buf).digest('hex');
    const newName = md5 + '.' + (c.dataFormat || 'svg');
    ent.name = newName;
    ent.data = buf;
    if (c.assetId) c.assetId = md5;
    c.md5ext = newName;
    touched++;
    console.log('[P199] backdrop ' + nm + ' -> ' + newName + ' (24-key row -> 5-key row)');
  }
  if (!touched) throw new Error('[P199] keyboard backdrop not found');

  // ---- head.txt's prune/relink only walk the Interpreter: do the Controller here
  {
    const blocks = CB();
    const keep = new Set();
    const stack = Object.keys(blocks).filter((id) => blocks[id].topLevel);
    while (stack.length) {
      const id = stack.pop();
      if (!id || keep.has(id)) continue;
      const b = blocks[id]; if (!b) continue;
      keep.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
    let dropped = 0;
    for (const id of Object.keys(blocks)) if (!keep.has(id)) { delete blocks[id]; dropped++; }
    for (const id of Object.keys(blocks)) blocks[id].parent = null;
    for (const id of Object.keys(blocks)) {
      const b = blocks[id];
      if (b.next && blocks[b.next]) blocks[b.next].parent = id;
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string' && blocks[v[1]]) blocks[v[1]].parent = id;
    }
    console.log('[P199] controller pruned ' + dropped + ' stale blocks');
  }
  B.setCtx('Interpreter');
});

// ---- PUNDO: a real 50-step undo stack (Controller target, side patch) ----
//
// v4.126 keeps ONE snapshot: `backup` refills the Stage list `Snapshot` with the
// current program, `undo` copies it back and never clears it - so pressing UNDO
// twice restores the same state.  This patch replaces only the *storage*:
//
//     backup  ->  push the current program as one frame onto `Undo` (lines) with
//                 its size in `UndoLen`; when 50 frames are stored the oldest is
//                 dropped first, so the stack is a sliding window of 50.
//     undo    ->  pop the newest frame and rebuild `Code` from it.
//
// Everything about *when* a frame is taken stays as it is: `prepEdit` plus the
// `saved` flag already coalesce a run of typing into one step (plain `insert`
// leaves `saved` at 1, while newline / backspace / cursor move / a mouse click
// set it to 0), and the structural paths (loadCode / example / editLine) call
// `backup` directly.
//
// ONE addition to that gate: a run of typing is now capped two ways, because
// without either a long uninterrupted stretch (a paragraph typed without Enter,
// or a pause in the middle) collapses into a single undo step, which makes the 50
// frames mostly useless:
//
//   * by character count - after CHARS characters the run closes, so the next
//     character opens a fresh step:
//         typing 25 characters with no Enter / cursor move -> frames at 0, 10, 20
//   * by idle time - if more than IDLE seconds pass between two edits the run
//     closes as well:
//         "ab" ... 5 s pause ... "c" -> the "c" opens a new step
//
// (Enter, joining two lines, moving the cursor, a mouse click and the
//  structural paths still close the run immediately, as before)
//
// AND, reported from use: `undo` could land on a ZERO-line program.  An empty
// `Code` list is a dead editor - `insert` does `replace item 1 of Code`, and on a
// missing item that is a silent no-op, so every later keystroke disappears.
// Zero lines are reachable (a frame captured while the program was empty, an
// IMPORT of empty text), so `Code` is now kept at one empty line at all three
// points where it could become empty: `backup` normalises before it copies,
// `undo` normalises after it restores, `loadCode %s` normalises after an import.
//
// The old `Snapshot` list is left declared but unused (its five block uses all
// live in the two bodies replaced here).
patch('PUNDO 50-step undo', () => {
  const CTRL = 'Controller';
  B.setCtx(CTRL);
  const CB = () => T(CTRL).blocks;
  // ctx-aware builders (head.txt's helpers are Interpreter-bound, same as P56/P199)
  const ci = (op, opts) => B.B(CTRL, op, opts);
  const cchain = (ids) => B.chain(CTRL, ids);
  const csub = (parentId, slot, ids) => {
    const first = ids.length ? cchain(ids) : null;
    CB()[parentId].inputs[slot] = [2, first];
    if (first) CB()[first].parent = parentId;
    return first;
  };
  const cvar = (n) => B.VAR(n);
  const csetV = (n, v) => ci('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [10, '']) } });
  const cchg = (n, v) => ci('data_changevariableby', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
  const cjoin = (a, b) => ci('operator_join', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const ceq = (a, b) => ci('operator_equals', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cgt = (a, b) => ci('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cadd = (a, b) => ci('operator_add', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const csub2 = (a, b) => ci('operator_subtract', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const clenL = (l) => ci('data_lengthoflist', { fields: B.LISTF(l) });
  const citem = (l, i) => ci('data_itemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const caddTo = (l, v) => ci('data_addtolist', { fields: B.LISTF(l), inputs: { ITEM: B.REP(v, [10, '']) } });
  const cclearL = (l) => ci('data_deletealloflist', { fields: B.LISTF(l) });
  const cdel = (l, i) => ci('data_deleteoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const cif = (c, ids) => { const id = ci('control_if', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', ids); return id; };
  const cifelse = (c, a, b) => {
    const id = ci('control_if_else', { inputs: { CONDITION: B.BOOL(c) } });
    csub(id, 'SUBSTACK', a); csub(id, 'SUBSTACK2', b); return id;
  };
  const crepeat = (n, ids) => { const id = ci('control_repeat', { inputs: { TIMES: B.REP(n, [4, '0']) } }); csub(id, 'SUBSTACK', ids); return id; };
  const defOf = (proccode) => {
    for (const [id, b] of Object.entries(CB())) {
      if (b.opcode === 'procedures_definition' && b.inputs && b.inputs.custom_block) {
        const pr = CB()[b.inputs.custom_block[1]];
        if (pr && pr.mutation && pr.mutation.proccode === proccode) return id;
      }
    }
    throw new Error('[PUNDO] controller def not found: ' + proccode);
  };
  const ccall = (proccode, args) => {
    const defId = defOf(proccode);
    const proto = CB()[CB()[defId].inputs.custom_block[1]];
    const ids = JSON.parse(proto.mutation.argumentids);
    const inputs = {};
    for (let i = 0; i < ids.length; i++) inputs[ids[i]] = B.REP((args || [])[i], [10, '']);
    return ci('procedures_call', { inputs, mutation: { tagName: 'mutation', children: [], proccode, argumentids: proto.mutation.argumentids, warp: proto.mutation.warp || 'true' } });
  };
  const attach = (defId, ids) => { const first = ids.length ? cchain(ids) : null; CB()[defId].next = first; if (first) CB()[first].parent = defId; return first; };

  const DEPTH = 50;                                  // frames kept (25..50 was the ask)
  const CHARS = 10;                                  // typing run closes after this many characters
  const IDLE = 2;                                    // ... or after this many seconds without an edit
  B.addList('Stage', 'Undo', []);                    // one item per program line, all frames back to back
  B.addList('Stage', 'UndoLen', []);                 // frame sizes: UndoLen[k] = line count of frame k
  B.addVar('Stage', 'un', 0);                        // frame size being pushed / popped
  B.addVar('Stage', 'ucnt', 0);                      // characters typed in the current run
  B.addVar('Stage', 'utime', 0);                     // clock (seconds) of the last edit

  // ---- prepEdit: the per-keystroke gate.  `saved = 0` means "the next edit opens
  // a new frame"; the counter and the clock close a run that got too long / too old.
  const nowSec = () => ci('operator_multiply', { inputs: { NUM1: B.REP(ci('sensing_dayssince2000', {}), [4, '0']), NUM2: B.REP(B.num(86400), [4, '0']) } });
  attach(defOf('prepEdit'), [
    cif(cgt(csub2(nowSec(), cvar('utime')), B.num(IDLE)), [csetV('saved', B.num(0))]),
    csetV('utime', nowSec()),
    cchg('ucnt', B.num(1)),
    cifelse(ceq(cvar('saved'), B.num(0)), [
      ccall('backup', []),
      csetV('saved', B.num(1)),
      csetV('ucnt', B.num(1))          // this character is the first of the new run
    ], [
      cif(cgt(cvar('ucnt'), B.num(CHARS - 1)), [csetV('saved', B.num(0))])
    ])
  ]);
  console.log('[PUNDO] a typing run closes every ' + CHARS + ' characters or ' + IDLE + ' s of silence');

  // ---- `Code` must never be empty (see the note at the top)
  const fixEmpty = () => cif(ceq(clenL('Code'), B.num(0)), [caddTo('Code', B.txt('')), csetV('dirty', B.num(1))]);
  // head.txt's spliceAfter walks the Interpreter; this one walks the Controller
  const cspliceAfter = (afterId, firstId) => {
    const bl = CB();
    const nx = bl[afterId].next;
    bl[afterId].next = firstId;
    bl[firstId].parent = afterId;
    let t = firstId;
    while (bl[t].next) t = bl[t].next;
    bl[t].next = nx;
    if (nx) bl[nx].parent = t;
    return firstId;
  };

  // ---- backup: push the current program as one frame
  attach(defOf('backup'), [
    fixEmpty(),
    // full? drop the oldest frame first (its lines leave `Undo`, its size leaves `UndoLen`)
    cif(cgt(clenL('UndoLen'), B.num(DEPTH - 1)), [
      csetV('un', citem('UndoLen', B.num(1))),
      crepeat(cvar('un'), [cdel('Undo', B.num(1))]),
      cdel('UndoLen', B.num(1))
    ]),
    csetV('ui', B.num(1)),
    crepeat(clenL('Code'), [
      caddTo('Undo', citem('Code', cvar('ui'))),
      cchg('ui', B.num(1))
    ]),
    caddTo('UndoLen', clenL('Code'))
  ]);

  // ---- undo: pop the newest frame and rebuild Code from it
  attach(defOf('undo'), [
    cifelse(cgt(clenL('UndoLen'), B.num(0)), [
      csetV('un', citem('UndoLen', clenL('UndoLen'))),
      cclearL('Code'),
      csetV('ui', B.num(1)),
      crepeat(cvar('un'), [
        caddTo('Code', citem('Undo', cadd(csub2(clenL('Undo'), cvar('un')), cvar('ui')))),
        cchg('ui', B.num(1))
      ]),
      fixEmpty(),                       // never hand back a 0-line program
      crepeat(cvar('un'), [cdel('Undo', clenL('Undo'))]),
      cdel('UndoLen', clenL('UndoLen')),
      csetV('selected', B.num(1)),
      csetV('page', B.num(1)),
      csetV('hscroll', B.num(0)),
      csetV('saved', B.num(0)),          // the next keystroke opens a fresh step
      csetV('dirty', B.num(1)),
      csetV('status', cjoin(B.txt('Undo: '), cjoin(clenL('UndoLen'), B.txt(' left'))))
    ], [
      csetV('status', B.txt('Nothing to undo')),
      csetV('dirty', B.num(1))
    ])
  ]);
  console.log('[PUNDO] backup pushes a frame, undo pops one (depth ' + DEPTH + ')');

  // ---- an IMPORT of empty text leaves Code with no lines: repair it right there
  {
    const lcId = defOf('loadCode %s');
    let last = CB()[lcId].next;
    if (!last) throw new Error('[PUNDO] loadCode %s has an empty body');
    while (CB()[last].next) last = CB()[last].next;
    cspliceAfter(last, cchain([fixEmpty()]));
    console.log('[PUNDO] loadCode keeps at least one line');
  }

  // ---- head.txt's prune/relink only walk the Interpreter: do the Controller here
  {
    const blocks = CB();
    const keep = new Set();
    const stack = Object.keys(blocks).filter((id) => blocks[id].topLevel);
    while (stack.length) {
      const id = stack.pop();
      if (!id || keep.has(id)) continue;
      const b = blocks[id]; if (!b) continue;
      keep.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') stack.push(v[1]);
      if (b.next) stack.push(b.next);
    }
    let dropped = 0;
    for (const id of Object.keys(blocks)) if (!keep.has(id)) { delete blocks[id]; dropped++; }
    for (const id of Object.keys(blocks)) blocks[id].parent = null;
    for (const id of Object.keys(blocks)) {
      const b = blocks[id];
      if (b.next && blocks[b.next]) blocks[b.next].parent = id;
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string' && blocks[v[1]]) blocks[v[1]].parent = id;
    }
    console.log('[PUNDO] controller pruned ' + dropped + ' stale blocks');
  }
  B.setCtx('Interpreter');
});

// ---- PFONT: bigger text in the code / output / variables panels (side patch) ----
//
// PART 1 -- font size
//
// The renderer stamps one SVG costume per character (all glyphs are 6x11) and
// advances `rx` by a fixed 5.1px per character.  5.1 is not arbitrary: each panel
// is filled to ~98% at that pitch -
//
//     code text   x=-201, limit 49  -> 49 * 5.1 = 250px of 262 available
//     variables   x=  74, limit 30  -> 30 * 5.1 = 153px of 156 available
//     console     x=  74, limit 30  -> 30 * 5.1 = 153px of 156 available
//
// so the font can only grow if the column counts shrink with it.  Scale 1.15:
//
//     pitch        5.1  -> 5.87      (and the sprite size 100 -> 115, so the
//                                     stamped glyphs grow with the advance)
//     code limit   49   -> 44        (44 * 5.87 = 258px, still inside 262)
//     panel limit  30   -> 26        (26 * 5.87 = 153px, still inside 156)
//     status limit 27   -> 23        (stays clear of the Ln/Steps fields)
//
// Row steps are untouched: the 14px code rows and the 13px panel rows still hold
// a 12.65px glyph, so none of the click / page arithmetic has to change.
//
// EVERY constant that depends on the pitch has to move with it, in all three
// targets -- the renderer, the interpreter (output wrap) and the controller
// (click -> column, hscroll window).  Missing one is silent and nasty: the old
// 5.1 in `click` puts the caret up to 6 columns away from where you clicked, and
// the old 49 in `keepCursor` scrolls the view 5 columns too far.  (Both were
// missed by the first cut of this patch and are fixed below.)
//
// PART 2 -- row shadow + caret geometry
//
// A glyph costume's rotation centre is (0,0), i.e. the TOP-LEFT of the 6x11 box,
// and `text` stamps at `goto(rx, ty)` -- so a row's glyph box is [ty-11s, ty] and
// its ink sits in the upper part of that box:
//
//     cap top    y_svg  2.10   baseline   y_svg  8.30   descender  y_svg 10.13
//
// The clickable row cell is (92-14i, 106-14i] (controller: uy<108, uy>-116,
// page+floor((106-uy)/14)), i.e. the row cell centre is 99-14i, and 16 cells of
// 14px exactly fill the code panel [-118, 108].  At ty=102 the ink was
// [92.5, 99.6] -- hard against the BOTTOM of its own cell, 6px of empty shadow
// above it, and descenders crossing into the next row.  That is what "the row
// shadow sits too high" looks like.
//
// The shadow cannot move: its centre 99 is already the only value that keeps the
// 16th row's bar inside the panel.  So the text moves up 3px instead, which is
// the same thing seen from the other side -- and it also pulls the last row's
// glyph box back inside the panel (it used to hang 2.65px below it).
//
//     text anchors 102 -> 105   (ink now [95.5, 102.6], centred on the cell)
//     bar height     13 -> 14   (fills the 14px cell)
//     caret      ty+1 .. ty-10 -> ty-1 .. ty-12   (dropped 2px, same 11px length)
//
// The bar's y (99), the bar's x span (-224..57, i.e. flush with the line number on
// the left and the last code column on the right) and the row pitch (14) are all
// left alone.  Widening the bar past the text (tried: -228..58) reads as a bar
// sticking out on both sides, so don't.
//
// The caret stays 11px long and 1px wide -- only its height changes.  Once the text
// moved up, the old offsets left it at [95,106]: its top sat right on the row cell
// edge, 3.4px clear of its own capital letters.  Two pixels down puts it at
// [93,104], which is the glyph's own ink span (descender 93.35 .. cap top 102.58).
patch('PFONT bigger text', () => {
  // ---- part 1: font
  const PITCH = 5.87;        // 5.1 * 1.15
  const SIZE = 115;          // sprite scale, keeps the glyphs in step with the advance
  const CODE_COLS = 44;      // 49 * 0.87
  const PANEL_COLS = 26;     // 30 * 0.87
  const STATUS_COLS = 23;    // 27 * 0.87
  const BAR_END = 57;        // selection bar right edge (flush with the last column)
  // ---- part 2: row shadow + caret
  const TEXT_Y0 = 105;       // 102: glyph anchor, so the ink centres in the row
  const BAR_X0 = -224;       // unchanged: flush with the line-number glyph
  const BAR_H = 14;          // 13: one full 14px row
  const CARET_DY = -1;       // +1: caret top = ty - 1
  const CARET_LEN = 12;      // 10: caret bottom = ty - 12

  const kidsOf = (bl) => {
    const kids = {};
    for (const [id, b] of Object.entries(bl)) {
      const refs = [];
      for (const inp of Object.values(b.inputs || {})) for (const x of [].concat(inp)) if (typeof x === 'string') refs.push(x);
      if (b.next) refs.push(b.next);
      for (const r of refs) (kids[r] = kids[r] || []).push(id);
    }
    return kids;
  };
  const defIdIn = (bl, proccode) => {
    for (const id of Object.keys(bl)) {
      const b = bl[id];
      if (b.opcode !== 'procedures_definition' || !b.inputs || !b.inputs.custom_block) continue;
      const q = bl[b.inputs.custom_block[1]];
      if (q && q.mutation && q.mutation.proccode === proccode) return id;
    }
    throw new Error('[PFONT] no definition of ' + proccode);
  };
  const reachIn = (bl, root) => {
    const seen = new Set(); const st = [root];
    while (st.length) {
      const id = st.pop(); if (!id || seen.has(id)) continue;
      const b = bl[id]; if (!b) continue; seen.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') st.push(v[1]);
      if (b.next) st.push(b.next);
    }
    return seen;
  };
  const numIn = (bl, id, slot) => {
    const v = bl[id].inputs[slot];
    return v && Array.isArray(v[1]) && v[1][0] === 4 ? String(v[1][1]) : null;
  };
  const setNum = (bl, id, slot, val) => { bl[id].inputs[slot] = [1, [4, String(val)]]; };

  // swap every primitive literal `from` -> `to` in blocks owned by `owner`
  // (when `opcode` is given, only blocks with that opcode are touched and the
  //  owner check is skipped - the interpreter's `log` sits behind a wake chain
  //  that makes the owner walk unreliable)
  const swap = (targetName, owner, from, to, expect, opcode) => {
    const t = T(targetName); const bl = t.blocks; const kids = kidsOf(bl);
    const ownerOf = (id) => {
      let cur = id, g = 0;
      while (cur && g++ < 400) {
        const b = bl[cur]; if (!b) return null;
        if (b.opcode === 'procedures_definition') return bl[b.inputs.custom_block[1]].mutation.proccode;
        if (b.opcode.startsWith('event_')) return null;
        cur = (kids[cur] || [])[0];
      }
      return null;
    };
    let n = 0;
    for (const [id, b] of Object.entries(bl)) {
      if (opcode) { if (b.opcode !== opcode) continue; }
      else if (ownerOf(id) !== owner) continue;
      for (const inp of Object.values(b.inputs || {})) {
        if (!Array.isArray(inp) || inp.length !== 2 || !Array.isArray(inp[1])) continue;
        if (String(inp[1][1]) !== String(from)) continue;
        inp[1] = [inp[1][0], to];
        n++;
      }
    }
    const where = opcode ? opcode : owner;
    if (n !== expect) throw new Error('[PFONT] ' + targetName + '/' + where + ': ' + from + ' -> ' + to + ' expected ' + expect + ', changed ' + n);
    console.log('[PFONT] ' + targetName + ' <' + where + '> ' + from + ' -> ' + to + ' (' + n + ')');
  };

  // ---- TextRenderer/draw: move the glyph anchors up so the text centres in the
  //      row cell, then re-cut the shadow and the caret around that cell.
  //      (done FIRST, on the un-swapped literals: the bar's right edge is 48 here,
  //       the pitch/count swaps below turn it into BAR_END)
  const tr = T('TextRenderer');
  {
    const bl = tr.blocks;
    const draw = reachIn(bl, defIdIn(bl, 'draw'));
    // 5 glyph anchors: line number, code text, ">" marker, caret top, caret bottom
    const anchors = Object.keys(bl).filter((id) => draw.has(id) && bl[id].opcode === 'operator_subtract' && numIn(bl, id, 'NUM1') === '102');
    if (anchors.length !== 5) throw new Error('[PFONT] draw/102 anchors = ' + anchors.length + ', expected 5');
    for (const id of anchors) setNum(bl, id, 'NUM1', TEXT_Y0);
    console.log('[PFONT] draw row anchors 102 -> ' + TEXT_Y0 + ' (' + anchors.length + ')');

    const byOpX = (op, x) => {
      const hits = Object.keys(bl).filter((id) => draw.has(id) && bl[id].opcode === op && numIn(bl, id, 'X') === String(x));
      if (hits.length !== 1) throw new Error('[PFONT] draw/' + op + ' x=' + x + ' matched ' + hits.length + ', expected 1');
      return hits[0];
    };
    const sizeOf = (v) => {
      const hits = Object.keys(bl).filter((id) => draw.has(id) && bl[id].opcode === 'pen_setPenSizeTo' && numIn(bl, id, 'SIZE') === String(v));
      if (hits.length !== 1) throw new Error('[PFONT] draw/pensize ' + v + ' matched ' + hits.length + ', expected 1');
      return hits[0];
    };
    setNum(bl, byOpX('motion_gotoxy', -224), 'X', BAR_X0);
    setNum(bl, byOpX('motion_gotoxy', 48), 'X', BAR_END);
    setNum(bl, sizeOf(13), 'SIZE', BAR_H);
    console.log('[PFONT] row bar x ' + BAR_X0 + '..' + BAR_END + ', thickness ' + BAR_H);

    // caret: same 11px, 1px-wide stroke, two pixels lower
    const addOne = Object.keys(bl).filter((id) => draw.has(id) && bl[id].opcode === 'operator_add' && numIn(bl, id, 'NUM2') === '1');
    if (addOne.length !== 1) throw new Error('[PFONT] draw/caret top matched ' + addOne.length + ', expected 1');
    setNum(bl, addOne[0], 'NUM2', CARET_DY);
    const subTen = Object.keys(bl).filter((id) => draw.has(id) && bl[id].opcode === 'operator_subtract' && numIn(bl, id, 'NUM2') === '10');
    if (subTen.length !== 1) throw new Error('[PFONT] draw/caret bottom matched ' + subTen.length + ', expected 1');
    setNum(bl, subTen[0], 'NUM2', CARET_LEN);
    console.log('[PFONT] caret ty' + CARET_DY + ' .. ty-' + CARET_LEN + ' (width unchanged)');
  }

  // ---- TextRenderer: pitch, glyph scale, and every width that depends on them
  swap('TextRenderer', 'text %s %s %s %s %s', '5.1', PITCH, 1);
  swap('TextRenderer', 'draw', '5.1', PITCH, 2);          // caret x / click math
  swap('TextRenderer', 'draw', '49', CODE_COLS, 2);       // code text limit + caret guard
  swap('TextRenderer', 'draw', '30', PANEL_COLS, 3);      // variables + console limits, vars cutoff
  swap('TextRenderer', 'draw', '27', STATUS_COLS, 2);     // status line limit + its truncation loop
  if (tr.size !== 100) throw new Error('[PFONT] TextRenderer size is ' + tr.size + ', expected 100');
  tr.size = SIZE;
  console.log('[PFONT] TextRenderer size 100 -> ' + SIZE);

  // ---- part 3: the two wrap widths + the controller constants that follow the pitch
  swap('Interpreter', 'log %s', '30', PANEL_COLS, 1, 'operator_equals');
  swap('Controller', 'hwrap %s', '30', PANEL_COLS, 1, 'operator_equals');
  swap('Controller', 'click', '5.1', PITCH, 1);            // click -> column
  swap('Controller', 'keepCursor', '49', CODE_COLS, 2);    // hscroll window

  console.log('[PFONT] bigger text ready (1.15x, ' + CODE_COLS + ' code cols / ' + PANEL_COLS + ' panel cols)');
});

// ---- PCLIP: select code, then COPY / PASTE (Controller + TextRenderer + backdrop) ----
//
// WHY THERE IS NO Ctrl+C / Shift+click HERE: scratch-vm throws modifier keys away
// before any block can see them --
//     keyboard.js:  if (keyString.length > 1) return '';    // "Ignore modifier keys"
// so `key (join "Shift" and "") pressed?` is false forever, and Shift+arrow /
// Shift+click / Ctrl+C are simply not expressible.  Selection is therefore a MOUSE
// gesture and copy/paste are BUTTONS, like the existing IMPORT / EXPORT / UNDO.
//
// SELECTION MODEL -- anchor + focus, the same shape the caret already has:
//     (anchL, anchC)      where the drag started
//     (selected, cursor)  where the drag is now
// `selSync` normalises the two ends into selL1/selC1 .. selL2/selC2 and sets selOn;
// an empty range means "no selection", so any plain caret move just re-anchors.
// All seven of those are Stage-owned, so the TextRenderer can read them too.
//
// GESTURES
//     drag inside the code text    -> free selection, any start/end, across lines
//     double click inside the text -> select that whole line
//     single click                 -> re-anchor (collapses the selection)
//     arrow keys                   -> collapse the selection, as usual
//     COPY  -> the selection, or the whole current line when there is none
//     PASTE -> insert at the caret, REPLACING the selection if there is one
//     typing / ENTER / BACKSPACE with a selection -> replace / delete it
// The clipboard is a Stage list `ClipL` (one string per line -- no escaping needed).
//
// THE BUTTON ROW is re-cut to make room for COPY and PASTE in the keyboard row:
// the six letter buttons lose 3px each (45 -> 42) and the keypad becomes seven
// keys at the unchanged P199 font-size 6 --
//     IMPORT EXPORT DEMO NEW UNDO HELP | TAB ENTER BACKSPACE CASE SPEED COPY PASTE
//     10 .. 272  (42px + 2px gaps)       274 .. 467
// The click hit tests are moved with the buttons.
patch('PCLIP select + copy/paste', () => {
  const crypto = require('crypto');
  const CTRL = 'Controller';
  const TRN = 'TextRenderer';
  B.setCtx(CTRL);
  const CB = () => T(CTRL).blocks;
  const TB = () => T(TRN).blocks;
  const ci = (op, opts) => B.B(CTRL, op, opts);
  const cchain = (ids) => B.chain(CTRL, ids);
  const csub = (parentId, slot, ids) => {
    const first = ids.length ? cchain(ids) : null;
    CB()[parentId].inputs[slot] = [2, first];
    if (first) CB()[first].parent = parentId;
    return first;
  };
  const cvar = (n) => B.VAR(n);
  const csetV = (n, v) => ci('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [10, '']) } });
  const cjoin = (a, b) => ci('operator_join', { inputs: { STRING1: B.REP(a, [10, '']), STRING2: B.REP(b, [10, '']) } });
  const cadd = (a, b) => ci('operator_add', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const csub2 = (a, b) => ci('operator_subtract', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const cmul = (a, b) => ci('operator_multiply', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const cdiv = (a, b) => ci('operator_divide', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
  const cfloor = (x) => ci('operator_mathop', { fields: { OPERATOR: ['floor', null] }, inputs: { NUM: B.REP(x, [4, '0']) } });
  const ceq = (a, b) => ci('operator_equals', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const clt = (a, b) => ci('operator_lt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cgt = (a, b) => ci('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
  const cand = (a, b) => ci('operator_and', { inputs: { OPERAND1: B.BOOL(a), OPERAND2: B.BOOL(b) } });
  const cor = (a, b) => ci('operator_or', { inputs: { OPERAND1: B.BOOL(a), OPERAND2: B.BOOL(b) } });
  const cnot = (a) => ci('operator_not', { inputs: { OPERAND: B.BOOL(a) } });
  const clen = (s) => ci('operator_length', { inputs: { STRING: B.REP(s, [10, '']) } });
  const cletter = (i, s) => ci('operator_letter_of', { inputs: { LETTER: B.REP(i, [4, '0']), STRING: B.REP(s, [10, '']) } });
  const citem = (l, i) => ci('data_itemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const clenL = (l) => ci('data_lengthoflist', { fields: B.LISTF(l) });
  const creplace = (l, i, v) => ci('data_replaceitemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const caddTo = (l, v) => ci('data_addtolist', { fields: B.LISTF(l), inputs: { ITEM: B.REP(v, [10, '']) } });
  const cdel = (l, i) => ci('data_deleteoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']) } });
  const cclearL = (l) => ci('data_deletealloflist', { fields: B.LISTF(l) });
  const cinsert = (l, i, v) => ci('data_insertatlist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']), ITEM: B.REP(v, [10, '']) } });
  const cif = (c, ids) => { const id = ci('control_if', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', ids); return id; };
  const cifelse = (c, a, b) => { const id = ci('control_if_else', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', a); csub(id, 'SUBSTACK2', b); return id; };
  const crepeat = (n, ids) => { const id = ci('control_repeat', { inputs: { TIMES: B.REP(n, [4, '0']) } }); csub(id, 'SUBSTACK', ids); return id; };
  const crepU = (c, ids) => { const id = ci('control_repeat_until', { inputs: { CONDITION: B.BOOL(c) } }); csub(id, 'SUBSTACK', ids); return id; };
  const cstop = () => ci('control_stop', { fields: { STOP_OPTION: ['this script', null] }, mutation: { tagName: 'mutation', children: [], hasnext: 'false' } });
  const ccode = (i) => citem('Code', i);
  const cwall = (i) => clen(ccode(i));
  const codeN = () => clenL('Code');
  const cbusy = () => cand(ceq(cvar('busy'), B.num(0)), ceq(cvar('running'), B.num(0)));
  const cmouseDown = () => ci('sensing_mousedown', {});  const cmouseX = () => ci('sensing_mousex', {});
  const cmouseY = () => ci('sensing_mousey', {});
  const ctimer = () => ci('sensing_timer', {});

  const defOf = (proccode) => {
    for (const [id, b] of Object.entries(CB())) {
      if (b.opcode === 'procedures_definition' && b.inputs && b.inputs.custom_block) {
        const pr = CB()[b.inputs.custom_block[1]];
        if (pr && pr.mutation && pr.mutation.proccode === proccode) return id;
      }
    }
    throw new Error('[PCLIP] controller def not found: ' + proccode);
  };
  const ccall = (proccode, args) => {
    const defId = defOf(proccode);
    const proto = CB()[CB()[defId].inputs.custom_block[1]];
    const ids = JSON.parse(proto.mutation.argumentids);
    const inputs = {};
    for (let i = 0; i < ids.length; i++) inputs[ids[i]] = B.REP((args || [])[i], [10, '']);
    return ci('procedures_call', { inputs, mutation: { tagName: 'mutation', children: [], proccode, argumentids: proto.mutation.argumentids, warp: proto.mutation.warp || 'true' } });
  };
  const attach = (defId, ids) => { const first = ids.length ? cchain(ids) : null; CB()[defId].next = first; if (first) CB()[first].parent = defId; return first; };
  const creach = (root) => {
    const seen = new Set(); const st = [root];
    while (st.length) {
      const id = st.pop(); if (!id || seen.has(id)) continue;
      const b = CB()[id]; if (!b) continue; seen.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') st.push(v[1]);
      if (b.next) st.push(b.next);
    }
    return seen;
  };
  const cpredOf = (id) => { for (const pid of Object.keys(CB())) if (CB()[pid].next === id) return pid; return null; };
  // every literal reachable through an expression (conditions are [2, blockId])
  const exprText = (id, acc) => {
    const b = CB()[id]; if (!b) return acc;
    for (const f of Object.values(b.fields || {})) if (typeof f[0] === 'string') acc.push(f[0]);
    for (const v of Object.values(b.inputs || {})) {
      if (Array.isArray(v) && Array.isArray(v[1]) && (v[1][0] === 4 || v[1][0] === 10)) acc.push(String(v[1][1]));
      else if (Array.isArray(v) && typeof v[1] === 'string') exprText(v[1], acc);
    }
    return acc;
  };
  const condText = (b) => (b.inputs && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string')
    ? exprText(b.inputs.CONDITION[1], []) : [];
  const cspliceAfter = (afterId, firstId) => {
    const a = CB()[afterId]; const nx = a.next;
    a.next = firstId; CB()[firstId].parent = afterId;
    let t = firstId; while (CB()[t].next) t = CB()[t].next;
    CB()[t].next = nx; if (nx) CB()[nx].parent = t;
    return firstId;
  };
  // put `ids` at the head of parent/substack, in front of whatever is already there
  const cprependStack = (parentId, slot, ids) => {
    const cur = CB()[parentId].inputs[slot] ? CB()[parentId].inputs[slot][1] : null;
    const first = ids.length ? cchain(ids) : null;
    let tail = first;
    while (tail && CB()[tail].next) tail = CB()[tail].next;
    if (tail) { CB()[tail].next = cur; if (cur) CB()[cur].parent = tail; }
    else { /* nothing built: leave the substack alone */ }
    CB()[parentId].inputs[slot] = [2, first];
    if (first) CB()[first].parent = parentId;
    return first;
  };

  // ---- state: anchor/selection are Stage-owned (the TextRenderer reads them)
  B.addVar('Stage', 'anchL', 1);
  B.addVar('Stage', 'anchC', 0);
  B.addVar('Stage', 'selOn', 0);
  B.addVar('Stage', 'selL1', 1);
  B.addVar('Stage', 'selC1', 0);
  B.addVar('Stage', 'selL2', 1);
  B.addVar('Stage', 'selC2', 0);
  // ---- controller scratch
  B.addVar('Stage', 'dragSel', 0);
  B.addVar('Stage', 'dblT', -99);
  B.addVar('Stage', 'dblL', 0);
  B.addVar('Stage', 'dblC', -1);
  B.addVar('Stage', 'clipN', 0);
  B.addVar('Stage', 'csl', '');        // result of slice %s %s %s
  B.addVar('Stage', 'csa', 0);
  B.addVar('Stage', 'csb', 0);
  B.addVar('Stage', 'csi', 0);         // callers' loop counter
  B.addVar('Stage', 'csj', 0);         // slice's OWN counter -- must not be csi,
                                       // or slice eats the caller's loop index
  B.addVar('Stage', 'dt1', '');
  B.addVar('Stage', 'dt2', '');
  B.addVar('Stage', 'dc0', 0);         // selection column range, for the renderer
  B.addVar('Stage', 'dc1', 0);
  B.addList('Stage', 'ClipL', []);     // the clipboard: one string per line

  // ---------------------------------------------------------------- 1. slice
  // slice %s %s %s : result -> csl   (1-based, inclusive, clamped to the string)
  {
    const d = B.makeProcedure(CTRL, 'slice %s %s %s', ['s', 'from', 'to'], true);
    const arg = (n) => B.argReporter(CTRL, n);
    attach(d.defId, [
      csetV('csa', arg('from')),
      csetV('csb', arg('to')),
      cif(clt(cvar('csa'), B.num(1)), [csetV('csa', B.num(1))]),
      cif(cgt(cvar('csb'), clen(arg('s'))), [csetV('csb', clen(arg('s')))]),
      csetV('csl', B.txt('')),
      csetV('csj', cvar('csa')),
      crepeat(cadd(csub2(cvar('csb'), cvar('csa')), B.num(1)), [
        csetV('csl', cjoin(cvar('csl'), cletter(cvar('csj'), arg('s')))),
        csetV('csj', cadd(cvar('csj'), B.num(1)))
      ])
    ]);
  }

  // ---------------------------------------------------------------- 2. selection
  {
    const d = B.makeProcedure(CTRL, 'selSync', [], true);
    attach(d.defId, [
      cifelse(cor(clt(cvar('anchL'), cvar('selected')),
        cand(ceq(cvar('anchL'), cvar('selected')), cnot(cgt(cvar('anchC'), cvar('cursor'))))), [
        csetV('selL1', cvar('anchL')), csetV('selC1', cvar('anchC')),
        csetV('selL2', cvar('selected')), csetV('selC2', cvar('cursor'))
      ], [
        csetV('selL1', cvar('selected')), csetV('selC1', cvar('cursor')),
        csetV('selL2', cvar('anchL')), csetV('selC2', cvar('anchC'))
      ]),
      cifelse(cand(ceq(cvar('selL1'), cvar('selL2')), ceq(cvar('selC1'), cvar('selC2'))),
        [csetV('selOn', B.num(0))], [csetV('selOn', B.num(1))])
    ]);
  }
  {
    const d = B.makeProcedure(CTRL, 'selClear', [], true);
    attach(d.defId, [
      csetV('selOn', B.num(0)),
      csetV('anchL', cvar('selected')), csetV('anchC', cvar('cursor')),
      csetV('selL1', cvar('selected')), csetV('selC1', cvar('cursor')),
      csetV('selL2', cvar('selected')), csetV('selC2', cvar('cursor'))
    ]);
  }
  // remove the selected range, park the caret at its start.  The caller snapshots first.
  {
    const d = B.makeProcedure(CTRL, 'delSel', [], true);
    attach(d.defId, [
      cif(ceq(cvar('selOn'), B.num(1)), [
        cifelse(ceq(cvar('selL1'), cvar('selL2')), [
          ccall('slice %s %s %s', [ccode(cvar('selL1')), B.num(1), cvar('selC1')]),
          csetV('dt1', cvar('csl')),
          ccall('slice %s %s %s', [ccode(cvar('selL1')), cadd(cvar('selC2'), B.num(1)), B.num(999999)]),
          csetV('dt2', cvar('csl')),
          creplace('Code', cvar('selL1'), cjoin(cvar('dt1'), cvar('dt2'))),
          csetV('selected', cvar('selL1')), csetV('cursor', cvar('selC1'))
        ], [
          ccall('slice %s %s %s', [ccode(cvar('selL1')), B.num(1), cvar('selC1')]),
          csetV('dt1', cvar('csl')),
          ccall('slice %s %s %s', [ccode(cvar('selL2')), cadd(cvar('selC2'), B.num(1)), B.num(999999)]),
          csetV('dt2', cvar('csl')),
          creplace('Code', cvar('selL1'), cjoin(cvar('dt1'), cvar('dt2'))),
          crepeat(csub2(cvar('selL2'), cvar('selL1')), [cdel('Code', cadd(cvar('selL1'), B.num(1)))]),
          csetV('selected', cvar('selL1')), csetV('cursor', cvar('selC1'))
        ]),
        ccall('selClear', []),
        ccall('keepCursor', [])
      ])
    ]);
  }

  // ---------------------------------------------------------------- 3. drag
  {
    const d = B.makeProcedure(CTRL, 'dragTo', [], true);
    const rows = () => cfloor(cdiv(csub2(B.num(106), cmouseY()), B.num(14)));
    attach(d.defId, [
      cif(ceq(cvar('dragSel'), B.num(1)), [
        csetV('csi', cadd(cvar('page'), rows())),
        cif(clt(cvar('csi'), B.num(1)), [csetV('csi', B.num(1))]),
        cif(cgt(cvar('csi'), codeN()), [csetV('csi', codeN())]),
        csetV('selected', cvar('csi')),
        csetV('cursor', B.num(0)),
        cif(cgt(cmouseX(), B.num(-201)), [
          csetV('cursor', cadd(cvar('hscroll'), cfloor(cdiv(cadd(cmouseX(), B.num(201)), B.num(5.87)))))
        ]),
        cif(cgt(cvar('cursor'), cwall(cvar('selected'))), [csetV('cursor', cwall(cvar('selected')))]),
        cif(clt(cvar('cursor'), B.num(0)), [csetV('cursor', B.num(0))]),
        ccall('selSync', []),
        ccall('keepCursor', [])
      ])
    ]);
  }
  {
    const d = B.makeProcedure(CTRL, 'dropDrag', [], true);
    attach(d.defId, [
      // only a press that STARTED in the code text may touch the status line --
      // a button press must not overwrite "Copied 3 line(s)" with a selection hint
      cif(cand(ceq(cvar('dragSel'), B.num(1)), ceq(cvar('selOn'), B.num(1))), [
        csetV('status', cjoin(B.txt('Selected lines '),
          cjoin(cvar('selL1'), cjoin(B.txt('-'), cvar('selL2'))))),
        csetV('dirty', B.num(1))
      ]),
      csetV('dragSel', B.num(0))
    ]);
  }

  // ---------------------------------------------------------------- 4. copy
  {
    const d = B.makeProcedure(CTRL, 'copySel', [], true);
    attach(d.defId, [
      cif(cbusy(), [
        cclearL('ClipL'),
        cifelse(ceq(cvar('selOn'), B.num(1)), [
          csetV('csi', cvar('selL1')),
          crepeat(cadd(csub2(cvar('selL2'), cvar('selL1')), B.num(1)), [
            cifelse(ceq(cvar('selL1'), cvar('selL2')), [
              ccall('slice %s %s %s', [ccode(cvar('csi')), cadd(cvar('selC1'), B.num(1)), cvar('selC2')]),
              caddTo('ClipL', cvar('csl'))
            ], [
              cifelse(ceq(cvar('csi'), cvar('selL1')), [
                ccall('slice %s %s %s', [ccode(cvar('csi')), cadd(cvar('selC1'), B.num(1)), B.num(999999)]),
                caddTo('ClipL', cvar('csl'))
              ], [
                cifelse(ceq(cvar('csi'), cvar('selL2')), [
                  ccall('slice %s %s %s', [ccode(cvar('csi')), B.num(1), cvar('selC2')]),
                  caddTo('ClipL', cvar('csl'))
                ], [
                  caddTo('ClipL', ccode(cvar('csi')))
                ])
              ])
            ]),
            csetV('csi', cadd(cvar('csi'), B.num(1)))
          ]),
          csetV('clipN', clenL('ClipL')),
          csetV('status', cjoin(B.txt('Copied '), cjoin(cvar('clipN'), B.txt(' line(s)'))))
        ], [
          caddTo('ClipL', ccode(cvar('selected'))),
          csetV('clipN', B.num(1)),
          csetV('status', cjoin(B.txt('Copied line '), cvar('selected')))
        ]),
        csetV('dirty', B.num(1))
      ])
    ]);
  }

  // ---------------------------------------------------------------- 5. paste
  {
    const d = B.makeProcedure(CTRL, 'pasteClip', [], true);
    const line = () => ccode(cvar('selected'));
    attach(d.defId, [
      cif(cbusy(), [
        cifelse(ceq(cvar('clipN'), B.num(0)), [
          csetV('status', B.txt('Clipboard is empty')), csetV('dirty', B.num(1))
        ], [
          cif(ceq(cvar('selOn'), B.num(1)), [ccall('delSel', [])]),
          ccall('prepEdit', []),
          ccall('slice %s %s %s', [line(), B.num(1), cvar('cursor')]),
          csetV('dt1', cvar('csl')),
          ccall('slice %s %s %s', [line(), cadd(cvar('cursor'), B.num(1)), B.num(999999)]),
          csetV('dt2', cvar('csl')),
          cifelse(ceq(cvar('clipN'), B.num(1)), [
            creplace('Code', cvar('selected'), cjoin(cjoin(cvar('dt1'), citem('ClipL', B.num(1))), cvar('dt2'))),
            csetV('cursor', cadd(cvar('cursor'), clen(citem('ClipL', B.num(1)))))
          ], [
            creplace('Code', cvar('selected'), cjoin(cvar('dt1'), citem('ClipL', B.num(1)))),
            csetV('csi', B.num(2)),
            crepeat(csub2(cvar('clipN'), B.num(2)), [
              cinsert('Code', cadd(cvar('selected'), csub2(cvar('csi'), B.num(1))), citem('ClipL', cvar('csi'))),
              csetV('csi', cadd(cvar('csi'), B.num(1)))
            ]),
            cinsert('Code', cadd(cvar('selected'), csub2(cvar('clipN'), B.num(1))),
              cjoin(citem('ClipL', cvar('clipN')), cvar('dt2'))),
            csetV('selected', cadd(cvar('selected'), csub2(cvar('clipN'), B.num(1)))),
            csetV('cursor', clen(citem('ClipL', cvar('clipN'))))
          ]),
          ccall('selClear', []),
          ccall('keepCursor', []),
          csetV('dirty', B.num(1)),
          csetV('status', cjoin(B.txt('Pasted '), cjoin(cvar('clipN'), B.txt(' line(s)'))))
        ])
      ])
    ]);
  }

  // ------------------------------------------- 6. editing keys replace the selection
  const replaceSel = () => cif(ceq(cvar('selOn'), B.num(1)), [ccall('prepEdit', []), ccall('delSel', [])]);
  for (const pc of ['insert %s', 'newline']) {
    const guard = CB()[defOf(pc)].next;
    if (!guard || CB()[guard].opcode !== 'control_if') throw new Error('[PCLIP] ' + pc + ': busy guard not found');
    cprependStack(guard, 'SUBSTACK', [replaceSel()]);
    console.log('[PCLIP] ' + pc + ' replaces the selection first');
  }
  // backspace deletes ONLY the selection when there is one
  {
    const guard = CB()[defOf('backspace')].next;
    if (!guard || CB()[guard].opcode !== 'control_if') throw new Error('[PCLIP] backspace: busy guard not found');
    cprependStack(guard, 'SUBSTACK', [
      cif(ceq(cvar('selOn'), B.num(1)), [
        ccall('prepEdit', []), ccall('delSel', []),
        csetV('dirty', B.num(1)),
        csetV('status', B.txt('Deleted selection')),
        cstop()
      ])
    ]);
    console.log('[PCLIP] backspace deletes only the selection');
  }
  // a plain caret move collapses the selection
  {
    const blk = defOf('moveCursor %s');
    const first = CB()[blk].next;
    if (!first || CB()[first].opcode !== 'control_if') throw new Error('[PCLIP] moveCursor: busy guard not found');
    const body = CB()[first].inputs.SUBSTACK[1];
    if (!body) throw new Error('[PCLIP] moveCursor guard is empty');
    const pred = cpredOf(body);
    const clear = ccall('selClear', []);
    if (pred) cspliceAfter(pred, clear);
    else { CB()[first].inputs.SUBSTACK = [2, clear]; CB()[clear].parent = first; CB()[clear].next = body; CB()[body].parent = clear; }
    console.log('[PCLIP] arrow keys collapse the selection');
  }

  // ---------------------------------------------------------------- 7. click
  {
    const clk = defOf('click');
    const keep = [...creach(clk)].filter((id) => CB()[id].opcode === 'procedures_call'
      && CB()[id].mutation && CB()[id].mutation.proccode === 'keepCursor');
    if (keep.length !== 1) throw new Error('[PCLIP] keepCursor calls in click = ' + keep.length);
    const pred = cpredOf(keep[0]);
    if (!pred) throw new Error('[PCLIP] cannot find the code-area branch tail');
    const anchor = [
      csetV('anchL', cvar('selected')),
      csetV('anchC', cvar('cursor')),
      csetV('dragSel', B.num(1)),
      cif(cand(cand(clt(csub2(ctimer(), cvar('dblT')), B.num(0.5)), ceq(cvar('dblL'), cvar('selected'))),
        ceq(cvar('dblC'), cvar('cursor'))), [
        csetV('anchC', B.num(0)),
        csetV('cursor', cwall(cvar('selected'))),
        csetV('dragSel', B.num(0)),
        ccall('selSync', []),
        csetV('status', cjoin(B.txt('Selected line '), cvar('selected'))),
        csetV('dirty', B.num(1))
      ]),
      csetV('dblT', ctimer()),
      csetV('dblL', cvar('selected')),
      csetV('dblC', cvar('cursor'))
    ];
    cspliceAfter(pred, cchain(anchor));
    console.log('[PCLIP] click sets the anchor; a double click selects the line');
  }
  // ---- the bottom bar becomes TWO rows: the six letter buttons keep row 1 and the
  //      keypad splits 4 (TAB ENTER BACKSPACE CASE) + 3 (SPEED COPY PASTE).
  //      Buttons are 19px tall now (rows at svg y=300 and y=322) so the block still
  //      ends above the separator, and no row is wider than the old one.
  {
    const findRegion = (need) => {
      let hit = null;
      for (const [id, b] of Object.entries(CB())) {
        if (b.opcode !== 'control_if') continue;
        const t = condText(b);
        if (need.every((k) => t.includes(k))) hit = id;
      }
      return hit;
    };
    const setCmp = (root, map) => {
      const hits = {};
      for (const id of creach(root)) {
        const b = CB()[id];
        if (b.opcode !== 'operator_lt' && b.opcode !== 'operator_gt') continue;
        const v = b.inputs.OPERAND2;
        if (!Array.isArray(v) || !Array.isArray(v[1]) || v[1][0] !== 4) continue;
        const k = String(v[1][1]);
        if (!(k in map)) continue;
        (hits[k] = hits[k] || []).push(id);
      }
      for (const k of Object.keys(map)) {
        if (!hits[k] || hits[k].length !== 1) throw new Error('[PCLIP] hit-test edge ' + k + ' matched ' + ((hits[k] || []).length) + ', expected 1');
        CB()[hits[k][0]].inputs.OPERAND2 = [1, [4, String(map[k])]];
      }
    };
    const wrapSubstack = (regionId, cond) => {
      const old = CB()[regionId].inputs.SUBSTACK ? CB()[regionId].inputs.SUBSTACK[1] : null;
      const id = ci('control_if', { inputs: { CONDITION: B.BOOL(cond) } });
      CB()[id].inputs.SUBSTACK = [2, old];
      if (old) CB()[old].parent = id;
      CB()[regionId].inputs.SUBSTACK = [2, id];
      CB()[id].parent = regionId;
      return id;
    };

    const letters = findRegion(['-146', '-122']);
    if (!letters) throw new Error('[PCLIP] letter-button region not found');
    // the six letter buttons go 45px -> 42px (their x edges move), and they only
    // exist on row 1 now that the band is two rows tall
    setCmp(letters, { '-185': -187, '-183': -187, '-138': -143, '-136': -143, '-91': -99, '-89': -99, '-44': -55, '-42': -55, '3': -11, '5': -11, '51': 33, '52': 33 });
    setCmp(letters, { '-146': -161, '-122': -120 });
    wrapSubstack(letters, cgt(cvar('uy'), B.num(-141)));
    console.log('[PCLIP] letters re-cut to 42px, pinned to row 1');

    const pad = findRegion(['67', '231']);
    if (!pad) throw new Error('[PCLIP] keypad region not found');
    setCmp(pad, { '67': 33, '231': 228 });          // both rows share this x zone
    setCmp(pad, { '-147': -141, '-122': -120 });    // row 1 only
    const capsToggle = [
      csetV('caps', csub2(B.num(1), cvar('caps'))),
      cifelse(ceq(cvar('caps'), B.num(1)),
        [csetV('status', B.txt('Case UPPER on  (CASE lit)'))],
        [csetV('status', B.txt('Case lower on  (CASE off)'))]),
      csetV('dirty', B.num(1))
    ];
    const speedToggle = [
      csetV('speed', csub2(B.num(1), cvar('speed'))),
      cifelse(ceq(cvar('speed'), B.num(1)),
        [csetV('status', B.txt('Speed FAST  (SPEED lit)'))],
        [csetV('status', B.txt('Speed SLOW  (1 line/frame)'))]),
      csetV('dirty', B.num(1))
    ];
    // row 1: TAB ENTER BACKSPACE CASE   (svg x 274..467)
    const TH1 = [71, 119, 183];
    csub(pad, 'SUBSTACK', [
      cifelse(cgt(B.num(TH1[0]), cvar('ux')), [ccall('tab', [])], [
        cifelse(cgt(B.num(TH1[1]), cvar('ux')), [ccall('newline', [])], [
          cifelse(cgt(B.num(TH1[2]), cvar('ux')), [ccall('backspace', [])], capsToggle)
        ])
      ])
    ]);
    // row 2: SPEED COPY PASTE
    const TH2 = [98, 163];
    const row2 = cif(cand(cbusy(), cand(cand(clt(cvar('uy'), B.num(-141)), cgt(cvar('uy'), B.num(-161))),
      cand(cgt(cvar('ux'), B.num(33)), clt(cvar('ux'), B.num(228))))), [
      cifelse(cgt(B.num(TH2[0]), cvar('ux')), speedToggle, [
        cifelse(cgt(B.num(TH2[1]), cvar('ux')), [ccall('copySel', [])], [ccall('pasteClip', [])])
      ])
    ]);
    cspliceAfter(pad, row2);
    console.log('[PCLIP] keypad row 1 = TAB | ENTER | BACKSPACE | CASE');
    console.log('[PCLIP] keypad row 2 = SPEED | COPY | PASTE');
  }

  // ---------------------------------------------------------------- 8. drag loop
  {
    const forevers = Object.entries(CB()).filter(([, b]) => b.opcode === 'control_forever');
    if (forevers.length !== 1) throw new Error('[PCLIP] forever loops = ' + forevers.length);
    const top = CB()[forevers[0][0]].inputs.SUBSTACK[1];
    if (!top || CB()[top].opcode !== 'control_if') throw new Error('[PCLIP] forever head is not the mouse poll');
    let wait = CB()[top].inputs.SUBSTACK[1];
    while (wait && CB()[wait].opcode !== 'control_wait_until') wait = CB()[wait].next;
    if (!wait) throw new Error('[PCLIP] `wait until not mouseDown` not found');
    const pred = cpredOf(wait);
    if (!pred) throw new Error('[PCLIP] cannot find the block before the wait');
    const after = CB()[wait].next;
    const loop = crepU(cnot(cmouseDown()), [
      csetV('ux', cmouseX()), csetV('uy', cmouseY()), ccall('dragTo', [])
    ]);
    const drop = ccall('dropDrag', []);
    // unplug the old wait, splice the polling loop + dropDrag in its place
    CB()[pred].next = null;
    CB()[loop].parent = pred;
    CB()[pred].next = loop;
    CB()[loop].next = drop; CB()[drop].parent = loop;
    CB()[drop].next = after; if (after) CB()[after].parent = drop;
    console.log('[PCLIP] the mouse poll now tracks the drag (repeat until released)');
  }

  // ---------------------------------------------------------------- 9. renderer band
  {
    const trDef = (proccode) => {
      for (const [id, b] of Object.entries(TB())) {
        if (b.opcode !== 'procedures_definition' || !b.inputs || !b.inputs.custom_block) continue;
        const pr = TB()[b.inputs.custom_block[1]];
        if (pr && pr.mutation && pr.mutation.proccode === proccode) return id;
      }
      throw new Error('[PCLIP] textrenderer def not found: ' + proccode);
    };
    const treach = (root) => {
      const seen = new Set(); const st = [root];
      while (st.length) {
        const id = st.pop(); if (!id || seen.has(id)) continue;
        const b = TB()[id]; if (!b) continue; seen.add(id);
        for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') st.push(v[1]);
        if (b.next) st.push(b.next);
      }
      return seen;
    };
    const draw = treach(trDef('draw'));
    const lit = (b, slot) => (b.inputs[slot] && Array.isArray(b.inputs[slot][1]) && b.inputs[slot][1][0] === 4 ? String(b.inputs[slot][1][1]) : null);
    // geometry derived from what PFONT left behind, so a font change moves this too
    const rowRep = [...draw].map((id) => TB()[id]).filter((b) => b.opcode === 'control_repeat' && lit(b, 'TIMES') === '16');
    if (rowRep.length !== 1) throw new Error('[PCLIP] row loop = ' + rowRep.length);
    const rowBody = rowRep[0].inputs.SUBSTACK[1];
    const rowIf = TB()[rowBody].next;
    if (!rowIf || TB()[rowIf].opcode !== 'control_if') throw new Error('[PCLIP] row if not found');
    const shadow = TB()[rowIf].inputs.SUBSTACK[1];
    if (!shadow || TB()[shadow].opcode !== 'control_if') throw new Error('[PCLIP] row shadow if not found');
    const penSizes = [...draw].map((id) => [id, TB()[id]]).filter(([, b]) => b.opcode === 'pen_setPenSizeTo');
    const bandPen = penSizes.map(([id, b]) => [id, Number(lit(b, 'SIZE'))]).filter(([, v]) => v > 5);
    if (bandPen.length !== 1) throw new Error('[PCLIP] band pen size = ' + bandPen.length);
    const BAND_H = bandPen[0][1];
    const bandGotos = [...draw].map((id) => TB()[id]).filter((b) => b.opcode === 'motion_gotoxy' && lit(b, 'X') !== null);
    const xs = bandGotos.map((b) => Number(lit(b, 'X'))).sort((a, b) => a - b);
    const CODE_X0 = -201, CODE_X1 = Math.max(...xs);
    const ySub = TB()[bandGotos[0].inputs.Y[1]];
    if (!ySub || ySub.opcode !== 'operator_subtract') throw new Error('[PCLIP] band y is not a subtract');
    const BAND_Y = Number(lit(ySub, 'NUM1'));
    const yMul = TB()[ySub.inputs.NUM2[1]];
    if (!yMul || yMul.opcode !== 'operator_multiply') throw new Error('[PCLIP] band y pitch not found');
    const ROW_PITCH = Number(lit(yMul, 'NUM2'));
    // pitch: `rx +=` in the text proc
    const textDef = treach(trDef('text %s %s %s %s %s'));
    const rxChg = [...textDef].map((id) => TB()[id]).filter((b) => b.opcode === 'data_changevariableby' && b.fields.VARIABLE[0] === 'rx');
    if (rxChg.length !== 1) throw new Error('[PCLIP] rx advance = ' + rxChg.length);
    const PITCH = Number(lit(rxChg[0], 'VALUE'));
    if (!(PITCH > 1 && BAND_Y > 0 && ROW_PITCH > 1)) throw new Error('[PCLIP] geometry not derived');
    console.log('[PCLIP] renderer band geometry: pitch ' + PITCH + ', x ' + CODE_X0 + '..' + CODE_X1 + ', y ' + BAND_Y + '-' + ROW_PITCH + 'i, h ' + BAND_H);

    B.setCtx(TRN);
    B.addVar(TRN, 'scl', 0);
    B.addVar(TRN, 'sch', 0);
    B.addVar(TRN, 'sxa', 0);
    B.addVar(TRN, 'sxb', 0);
    const ti = (op, opts) => B.B(TRN, op, opts);
    const tv = (n) => B.VAR(n);
    const tset = (n, v) => ti('data_setvariableto', { fields: B.VARF(n), inputs: { VALUE: B.REP(v, [4, '0']) } });
    const tadd = (a, b) => ti('operator_add', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
    const tsub = (a, b) => ti('operator_subtract', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
    const tmul = (a, b) => ti('operator_multiply', { inputs: { NUM1: B.REP(a, [4, '0']), NUM2: B.REP(b, [4, '0']) } });
    const tlt = (a, b) => ti('operator_lt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
    const tgt = (a, b) => ti('operator_gt', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
    const teq = (a, b) => ti('operator_equals', { inputs: { OPERAND1: B.REP(a, [10, '']), OPERAND2: B.REP(b, [10, '']) } });
    const tand = (a, b) => ti('operator_and', { inputs: { OPERAND1: B.BOOL(a), OPERAND2: B.BOOL(b) } });
    const tnot = (a) => ti('operator_not', { inputs: { OPERAND: B.BOOL(a) } });
    const tlen = (s) => ti('operator_length', { inputs: { STRING: B.REP(s, [10, '']) } });
    const titem = (l, i) => ti('data_itemoflist', { fields: B.LISTF(l), inputs: { INDEX: B.REP(i, [4, '0']) } });
    const tif = (c, ids) => { const id = ti('control_if', { inputs: { CONDITION: B.BOOL(c) } }); const f = ids.length ? B.chain(TRN, ids) : null; TB()[id].inputs.SUBSTACK = [2, f]; if (f) TB()[f].parent = id; return id; };
    const trowY = () => tsub(B.num(BAND_Y), tmul(tv('ri'), B.num(ROW_PITCH)));
    const tgo = (x, y) => ti('motion_gotoxy', { inputs: { X: B.REP(x, [4, '0']), Y: B.REP(y, [4, '0']) } });

    const band = tif(tand(teq(tv('selOn'), B.num(1)),
      tand(tnot(tlt(tv('rline'), tv('selL1'))), tnot(tgt(tv('rline'), tv('selL2'))))), [
      tset('scl', B.num(0)),
      tset('sch', tlen(titem('Code', tv('rline')))),
      tif(teq(tv('rline'), tv('selL1')), [tset('scl', tv('selC1'))]),
      tif(teq(tv('rline'), tv('selL2')), [tset('sch', tv('selC2'))]),
      tset('sxa', tadd(B.num(CODE_X0), tmul(tsub(tv('scl'), tv('hscroll')), B.num(PITCH)))),
      tset('sxb', tadd(B.num(CODE_X0), tmul(tsub(tv('sch'), tv('hscroll')), B.num(PITCH)))),
      tif(tlt(tv('sxa'), B.num(CODE_X0)), [tset('sxa', B.num(CODE_X0))]),
      tif(tgt(tv('sxb'), B.num(CODE_X1)), [tset('sxb', B.num(CODE_X1))]),
      tif(tgt(tv('sxb'), tv('sxa')), [
        ti('pen_penUp', {}),
        tgo(tv('sxa'), trowY()),
        ti('pen_setPenColorToColor', { inputs: { COLOR: [1, [9, '#cfe0f5']] } }),
        ti('pen_setPenSizeTo', { inputs: { SIZE: B.REP(B.num(BAND_H), [4, '0']) } }),
        ti('pen_penDown', {}),
        tgo(tv('sxb'), trowY()),
        ti('pen_penUp', {})
      ])
    ]);
    // splice it in right after the row shadow, before the line number is stamped
    const nx = TB()[shadow].next;
    TB()[shadow].next = band; TB()[band].parent = shadow;
    TB()[band].next = nx; if (nx) TB()[nx].parent = band;
    console.log('[PCLIP] the selected range is drawn as a band behind the text');
  }

  // ---------------------------------------------------------------- 10. backdrop
  // Two rows, 19px tall: row 1 at svg y=300 (letters + TAB ENTER BACKSPACE CASE),
  // row 2 at y=322 (SPEED COPY PASTE, right half).  Everything is font-size 8 now.
  // The 1px separator moves 335 -> 343 so it sits under row 2 instead of through it.
  {
    const ROW1 = 300, ROW2 = 322, H = 19, BASE1 = 313, BASE2 = 335;
    const rect = (x, y, w) => '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + H + '" fill="#fcfcfc" stroke="#d6d6d6"/>';
    const label = (x, w, y, s) => '<text x="' + (x + w / 2) + '" y="' + y + '">' + s + '</text>';
    const row = (() => {
      const out = ['<g font-family="Arial,Helvetica,sans-serif" font-size="8" font-weight="700" text-anchor="middle" fill="#333">'];
      // left half, row 1: the six letter buttons, 42px each from x=10
      let x = 10;
      for (const s of ['IMPORT', 'EXPORT', 'DEMO', 'NEW', 'UNDO', 'HELP']) {
        out.push(rect(x, ROW1, 42), label(x, 42, BASE1, s));
        x += 44;
      }
      // right half, row 1: TAB ENTER BACKSPACE CASE  (274..467)
      x = 274;
      for (const s of ['TAB', 'ENTER', 'BACKSPACE', 'CASE']) {
        const w = { TAB: 36, ENTER: 46, BACKSPACE: 62, CASE: 43 }[s];
        out.push(rect(x, ROW1, w), label(x, w, BASE1, s));
        x += w + 2;
      }
      // right half, row 2: SPEED COPY PASTE  (274..467, three even keys)
      x = 274;
      for (const s of ['SPEED', 'COPY', 'PASTE']) {
        out.push(rect(x, ROW2, 63), label(x, 63, BASE2, s));
        x += 65;
      }
      return out.join('') + '</g>';
    })();
    const oldLetters = /<g font-family="Arial,Helvetica,sans-serif" font-size="8" font-weight="700" text-anchor="middle" fill="#333">[\s\S]*?<\/g>/;
    const oldKeys = /<g font-family="Arial,Helvetica,sans-serif" font-size="6" font-weight="700" text-anchor="middle" fill="#333">[\s\S]*?<\/g>/;
    const oldSep = /<line x1="0" y1="335" x2="480" y2="335" stroke="#d6d6d6"\/>/;
    let touched = 0;
    for (const c of (T('Stage').costumes || [])) {
      const nm = c.md5ext || (c.assetId + '.' + (c.dataFormat || 'svg'));
      if (!/\.svg$/.test(nm)) continue;
      const ent = entries.find((e) => e.name === nm);
      if (!ent) continue;
      let svg = ent.data.toString('utf8');
      if (svg.indexOf('>TAB</text>') < 0 || svg.indexOf('>HELP</text>') < 0) continue;
      const a = (svg.match(new RegExp(oldLetters.source, 'g')) || []).length;
      const b = (svg.match(new RegExp(oldKeys.source, 'g')) || []).length;
      if (a !== 1 || b !== 1) throw new Error('[PCLIP] backdrop groups = ' + a + '/' + b);
      if (!oldSep.test(svg)) throw new Error('[PCLIP] separator line not found');
      svg = svg.replace(oldLetters, row).replace(oldKeys, '').replace(oldSep, '<line x1="0" y1="343" x2="480" y2="343" stroke="#d6d6d6"/>');
      if (svg.indexOf('>COPY</text>') < 0 || svg.indexOf('>PASTE</text>') < 0) throw new Error('[PCLIP] backdrop not rewritten');
      const buf = Buffer.from(svg, 'utf8');
      const md5 = crypto.createHash('md5').update(buf).digest('hex');
      const newName = md5 + '.' + (c.dataFormat || 'svg');
      ent.name = newName;
      ent.data = buf;
      if (c.assetId) c.assetId = md5;
      c.md5ext = newName;
      touched++;
      console.log('[PCLIP] backdrop ' + nm + ' -> ' + newName + ' (two button rows: 19px tall, separator 335 -> 343)');
    }
    if (!touched) throw new Error('[PCLIP] backdrop not found');
  }

  // --------------------------------------- 11. EXPORT/IMPORT gets a real separator
  //
  // The old format joined the whole program with `|` and never escaped it, so a line
  // containing a `|` (i.e. `a | b`) came back as two lines -- EXPORT was lossy.  The
  // separator is now the two printable ASCII characters `\n`, and a literal
  // backslash is doubled (`\\`).  That is lossless, it is exactly the escape Python
  // itself uses, and it survives the ask box / list watcher round trip (a control
  // character would not).  Old exports still import: if the text contains no `\n`,
  // a bare `|` is treated as the separator as before.
  {
    B.setCtx(CTRL);            // section 9 left the context on the TextRenderer
    B.addVar('Stage', 'esi', 0);
    B.addVar('Stage', 'esc1', '');
    B.addVar('Stage', 'usk', 0);
    B.addVar('Stage', 'useNL', 0);
    B.addVar('Stage', 'unx', '');
    B.addVar('Stage', 'srctxt', '');
    const BS = '\\';          // one backslash character
    const NL = '\\n';         // backslash + n, the two characters that mean "newline"

    // NB: the escaping lives INSIDE exportCode, not in a helper procedure.  A helper
    // called from inside the per-line loop misbehaves here: its argument reporter
    // and/or loop bookkeeping comes back stale on the second call (the first call's
    // string sticks), so `export('abcdef')` silently produced 'abcde'.  Reading the
    // line straight out of Code[ui] inside the caller's own loop is reliable.
    attach(defOf('exportCode'), [
      cclearL('Export'),
      csetV('ut', B.txt('')),
      csetV('ui', B.num(1)),
      crepeat(codeN(), [
        cif(cgt(cvar('ui'), B.num(1)), [csetV('ut', cjoin(cvar('ut'), B.txt(NL)))]),
        csetV('esi', B.num(1)),
        crepU(ceq(cletter(cvar('esi'), ccode(cvar('ui'))), B.txt('')), [
          csetV('esc1', cletter(cvar('esi'), ccode(cvar('ui')))),
          cif(ceq(cvar('esc1'), B.txt(BS)), [csetV('ut', cjoin(cvar('ut'), B.txt(BS)))]),
          csetV('ut', cjoin(cvar('ut'), cvar('esc1'))),
          csetV('esi', cadd(cvar('esi'), B.num(1)))
        ]),
        csetV('ui', cadd(cvar('ui'), B.num(1)))
      ]),
      caddTo('Export', cvar('ut')),
      ci('data_showlist', { fields: B.LISTF('Export') }),
      csetV('exportShown', B.txt('1')),
      csetV('status', B.txt('Export: 1 line, \\n = newline')),
      csetV('dirty', B.num(1))
    ]);
    // importCode: anything you paste back
    attach(defOf('importCode'), [
      csetV('busy', B.num(1)),
      ci('sensing_askandwait', { inputs: { QUESTION: B.REP(B.txt('Paste export text  (:cancel keeps current)'), [10, '']) } }),
      cif(cnot(ceq(ci('sensing_answer', {}), B.txt(':cancel'))), [ccall('loadCode %s', [ci('sensing_answer', {})])]),
      csetV('busy', B.num(0)),
      csetV('dirty', B.num(1))
    ]);
    // loadCode: decode `\n` as a newline, `\x` as a literal x, and a bare `|` only
    // when the text has no `\n` at all (the pre-2026 export format)
    {
      const src = () => cvar('srctxt');   // copy of the argument: see the note above
      const at = (k) => cletter(k, src());
      attach(defOf('loadCode %s'), [
        ccall('backup', []),
        cclearL('Code'),
        csetV('srctxt', B.argReporter(CTRL, 'source')),
        csetV('ui', B.num(1)),
        csetV('ut', B.txt('')),
        csetV('useNL', B.num(0)),
        csetV('usk', B.num(1)),
        crepU(ceq(at(cvar('usk')), B.txt('')), [
          cif(cand(ceq(at(cvar('usk')), B.txt(BS)), ceq(at(cadd(cvar('usk'), B.num(1))), B.txt('n'))),
            [csetV('useNL', B.num(1))]),
          csetV('usk', cadd(cvar('usk'), B.num(1)))
        ]),
        crepU(ceq(at(cvar('ui')), B.txt('')), [
          csetV('uc', at(cvar('ui'))),
          cifelse(ceq(cvar('uc'), B.txt(BS)), [
            csetV('unx', at(cadd(cvar('ui'), B.num(1)))),
            cifelse(cand(ceq(cvar('unx'), B.txt('n')), ceq(cvar('useNL'), B.num(1))), [
              caddTo('Code', cvar('ut')), csetV('ut', B.txt('')),
              csetV('ui', cadd(cvar('ui'), B.num(2)))
            ], [
              csetV('ut', cjoin(cvar('ut'), cvar('unx'))),
              csetV('ui', cadd(cvar('ui'), B.num(2)))
            ])
          ], [
            cifelse(cand(ceq(cvar('uc'), B.txt('|')), ceq(cvar('useNL'), B.num(0))), [
              caddTo('Code', cvar('ut')), csetV('ut', B.txt('')),
              csetV('ui', cadd(cvar('ui'), B.num(1)))
            ], [
              csetV('ut', cjoin(cvar('ut'), cvar('uc'))),
              csetV('ui', cadd(cvar('ui'), B.num(1)))
            ])
          ])
        ]),
        caddTo('Code', cvar('ut')),
        csetV('selected', B.num(1)),
        csetV('page', B.num(1)),
        csetV('hscroll', B.num(0)),
        csetV('status', B.txt('Imported')),
        cif(ceq(codeN(), B.num(0)), [caddTo('Code', B.txt('')), csetV('dirty', B.num(1))])
      ]);
    }
    console.log('[PCLIP] EXPORT/IMPORT now separate lines with \\n and escape backslashes');
  }

  // head.txt's prune/relink only walk the Interpreter: do the Controller here,
  // then the TextRenderer (the band added blocks in both)
  {
    const blocks = CB();
    const top = Object.keys(blocks).filter((id) => blocks[id].topLevel === true);
    const keep = new Set();
    const st = top.slice();
    while (st.length) {
      const id = st.pop(); if (!id || keep.has(id)) continue;
      const b = blocks[id]; if (!b) continue;
      keep.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') st.push(v[1]);
      if (b.next) st.push(b.next);
    }
    let dropped = 0;
    for (const id of Object.keys(blocks)) if (!keep.has(id)) { delete blocks[id]; dropped++; }
    for (const id of Object.keys(blocks)) blocks[id].parent = null;
    for (const id of Object.keys(blocks)) {
      const b = blocks[id];
      if (b.next && blocks[b.next]) blocks[b.next].parent = id;
      for (const v of Object.values(b.inputs || {})) {
        if (!v) continue;
        // slot 1 = the block/shadow, slot 2 = an OBSCURED shadow (a menu block that
        // a reporter has been dropped on top of) -- it still needs a parent
        for (const k of [1, 2]) if (typeof v[k] === 'string' && blocks[v[k]]) blocks[v[k]].parent = id;
      }
    }
    console.log('[PCLIP] controller pruned ' + dropped + ' stale blocks');
  }
  {
    const blocks = TB();
    const keep = new Set();
    const st = Object.keys(blocks).filter((id) => blocks[id].topLevel);
    while (st.length) {
      const id = st.pop(); if (!id || keep.has(id)) continue;
      const b = blocks[id]; if (!b) continue;
      keep.add(id);
      for (const v of Object.values(b.inputs || {})) if (v && typeof v[1] === 'string') st.push(v[1]);
      if (b.next) st.push(b.next);
    }
    for (const id of Object.keys(blocks)) blocks[id].parent = null;
    for (const id of Object.keys(blocks)) {
      const b = blocks[id];
      if (b.next && blocks[b.next]) blocks[b.next].parent = id;
      for (const v of Object.values(b.inputs || {})) {
        if (!v) continue;
        for (const k of [1, 2]) if (typeof v[k] === 'string' && blocks[v[k]]) blocks[v[k]].parent = id;
      }
    }
    console.log('[PCLIP] textrenderer parents relinked');
  }
  B.setCtx('Interpreter');
  console.log('[PCLIP] select + copy/paste ready');
});

// ---- P68: RUN uses warp, STEP stays non-warp ----
//
// P66/P67 made the call chain non-warp so a STEP inside a function really yields
// (one frame per step instead of a 500ms warp spin).  The price was that a *long*
// run also yields at every call: fib(16) went 12 -> 799 frames (CPU unchanged, but
// the GUI only advances ~8 lines per frame).
//
// Warp is inherited downwards and only a *procedure* can turn it on, so the fix is a
// warp copy of the two procedures that enter a user call:
//
//   free run  (mode == 0): callfn/callmeth  ->  callfnW/callmethW   (warp copy)
//                          everything below (eval -> calluser -> nested calls ->
//                          the per-line execute inside the body loop) inherits warp,
//                          which is exactly the old fast behaviour.
//   step mode (mode != 0): callfn/callmeth  ->  the original non-warp body
//                          so the pause in the body loop yields properly (45ms/step).
//
// The branch lives *inside* callfn/callmeth (their original body moves into the else
// branch), so no call site has to duplicate its argument expressions.
// Measured: fib(16) 799 -> 15 frames in RUN mode; demo1 step stays ~45ms.
patch('P68 run warp step non-warp', () => {
  const cloneBody = (fromDefId, toDefId) => {
    const map = {};
    let count = 0;
    const copyBlock = (id) => {
      if (map[id]) return map[id];
      const src = BL()[id];
      const nid = B.nid('wr');
      map[id] = nid;
      const b = {
        opcode: src.opcode, next: null, parent: null, inputs: {},
        fields: JSON.parse(JSON.stringify(src.fields || {})),
        shadow: !!src.shadow, topLevel: false
      };
      if (src.mutation) b.mutation = JSON.parse(JSON.stringify(src.mutation));
      BL()[nid] = b;
      count++;
      for (const [k, v] of Object.entries(src.inputs || {})) {
        const nv = JSON.parse(JSON.stringify(v));
        if (typeof nv[1] === 'string') nv[1] = copyBlock(nv[1]);
        b.inputs[k] = nv;
      }
      if (src.next) {
        const nx = copyBlock(src.next);
        b.next = nx;
        BL()[nx].parent = nid;
      }
      return nid;
    };
    const first = copyBlock(BL()[fromDefId].next);
    BL()[toDefId].next = first;
    BL()[first].parent = toDefId;
    return count;
  };
  const wrap = (proccode, cloneCode, argNames) => {
    const defId = defIdOf(proccode);
    const origFirst = BL()[defId].next;
    if (!origFirst) throw new Error('[P68] empty body: ' + proccode);
    const np = newProc(cloneCode, argNames);            // warp copy
    const n = cloneBody(defId, np.defId);
    const call = callProc(cloneCode, argNames.map((a) => argOf(a)));
    const ie = IFELSE(EQ(VAR('mode'), num(0)), [call], [origFirst]);
    BL()[ie].parent = defId;
    BL()[defId].next = ie;
    console.log('[P68] ' + proccode + ' -> ' + cloneCode + ' (' + n + ' blocks cloned)');
  };
  wrap('callfn %s %s %s', 'callfnW %s %s %s', ['fn', 'lo', 'hi']);
  wrap('callmeth %s %s %s %s', 'callmethW %s %s %s %s', ['inst', 'meth', 'lo', 'hi']);
  console.log('[P68] RUN goes through the warp copies, STEP keeps the non-warp path');
});

// ---- DEBUG (V41_TRACE=1): record every executed line and the frame depth
if (process.env.V41_TRACE) {
  patch('PDEBUG trace', () => {
    B.addList(IT, 'Trace', []);
    newVar('tdbg', 0);
    const ex = defIdOf('execute');
    const first = BL()[ex].next;
    insertBeforeStmt(first, [
      addTo('Trace', JOIN(JOIN(JOIN(txt('EXEC pc='), VAR('pc')), JOIN(txt(' c='), VAR('cdepth'))), JOIN(txt(' head='), VAR('head'))))
    ]);
    let lastId = first; let g = 0;
    while (BL()[lastId].next && g++ < 5000) lastId = BL()[lastId].next;
    spliceAfter(lastId, chain([
      addTo('Trace', JOIN(JOIN(JOIN(txt('EXECEND pc='), VAR('pc')), JOIN(txt(' c='), VAR('cdepth'))), JOIN(txt(' err='), VAR('error'))))
    ]));
    const runDef = (() => { for (const id of allIds()) { const b = BL()[id]; if (b.opcode === 'event_whenbroadcastreceived' && b.fields.BROADCAST_OPTION && b.fields.BROADCAST_OPTION[0] === 'RUN') return id; } throw new Error('RUN hat not found'); })();
    spliceAfter(runDef, chain([clearL('Trace')]));
    console.log('[trace] enabled');
  });
}

// ---------------------------------------------------------------- main
relinkParents();
for (const p of PATCHES) { if (!patchEnabled(p.name)) { console.log('[skip] ' + p.name); continue; } p.fn(); }
const dropped = pruneUnreachable();
relinkParents();

// structural check: every non-top-level block must have a parent
let orphans = 0;
for (const id of allIds()) { const b = BL()[id]; if (!b.topLevel && !b.parent) orphans++; }

if (project.meta) project.meta.agent = STAMP;

const outEntries = entries.map((e) => e.name === 'project.json' ? { name: e.name, data: Buffer.from(JSON.stringify(project), 'utf8') } : e);
zipWrite(outEntries, OUT);
fs.writeFileSync(OUT_JSON, JSON.stringify(project));
let total = 0;
for (const t of project.targets) { const n = Object.keys(t.blocks || {}).length; total += n; console.log('  ' + t.name.padEnd(14) + ' blocks=' + String(n).padStart(6) + ' vars=' + String(Object.keys(t.variables || {}).length).padStart(4) + ' lists=' + Object.keys(t.lists || {}).length); }
console.log('[build] pruned=' + dropped + ' orphans=' + orphans + ' total=' + total + ' -> ' + OUT);
if (orphans) { console.error('STRUCTURE ERROR: ' + orphans + ' non-top blocks without parent'); process.exit(1); }
